import SwiftUI
import AppKit
import UniformTypeIdentifiers

func branchCreateAndRebaseShouldCreateBranch(
    branchAlreadyExists: Bool,
    resetExisting: Bool
) -> Bool {
    !branchAlreadyExists || resetExisting
}

/// Resolve a configured upstream such as `corp/release/2026` to the remote
/// and branch that GitUpdateSelectedBranchAction should fetch or pull. Prefer
/// the longest remote prefix so remote names containing separators remain
/// unambiguous.
func remoteBranchTargetForConfiguredUpstream(
    _ upstream: String,
    remotes: [RemoteInfo]
) -> (remote: String, branch: String)? {
    let normalized = upstream.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalized.isEmpty else { return nil }

    return remotes
        .compactMap { remote -> (remote: String, branch: String, prefixLength: Int)? in
            let prefix = "\(remote.name)/"
            guard normalized.hasPrefix(prefix) else { return nil }
            let branch = String(normalized.dropFirst(prefix.count))
            guard !branch.isEmpty else { return nil }
            return (remote: remote.name, branch: branch, prefixLength: prefix.count)
        }
        .max { $0.prefixLength < $1.prefixLength }
        .map { (remote: $0.remote, branch: $0.branch) }
}

/// GitCheckoutWithUpdateAction revalidates the selected local branch's
/// tracking branch when the action is invoked. Keep the single-root callback
/// from switching branches when its asynchronous dashboard snapshot is stale.
func checkoutAndUpdateUpstream(
    branch: String,
    syncStatuses: [SyncStatus]
) -> String? {
    guard let sync = syncStatuses.first(where: { $0.branch == branch }),
          sync.trackingExists else { return nil }
    let upstream = sync.upstream.trimmingCharacters(in: .whitespacesAndNewlines)
    guard upstream.contains("/"), !upstream.hasSuffix("/") else { return nil }
    return upstream
}

func pullDialogDefaultRebase(
    explicit: Bool?,
    savedOptions: Set<GitPullDialogOption>
) -> Bool {
    explicit ?? savedOptions.contains(.rebase)
}

/// Resolve a stash object immediately before a mutating operation. The UI
/// may have captured a stack position, but inserting or deleting another
/// stash must never redirect the operation to a different object.
private func currentStashIndex(repo: Repository, stashID: String) throws -> UInt32 {
    let stashes = try repo.stashList()
    guard let index = stashes.firstIndex(where: { $0.id == stashID }) else {
        throw NSError(
            domain: "Arbor.Stash",
            code: 1,
            userInfo: [NSLocalizedDescriptionKey: "The selected stash no longer exists."]
        )
    }
    return UInt32(index)
}

func pullStashIndex(message: String?, in stashes: [StashInfo]) -> Int? {
    guard let message else { return nil }
    let matches = stashes.indices.filter { stashes[$0].message == message }
    guard matches.count == 1 else { return nil }
    return matches[0]
}

/// IntelliJ's GitInit asks before re-initializing a directory that is already
/// inside a Git worktree. Resolve the owning worktree before starting `git
/// init`, including when the user selected a subdirectory of that worktree.
func gitInitializationExistingRepositoryRoot(path: String) -> String? {
    guard let repository = try? openRepository(path: path),
          let root = repository.workdir(),
          !root.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        return nil
    }
    return URL(fileURLWithPath: root).standardizedFileURL.path
}

/// Execute IntelliJ's Update Selected Branch semantics for one Git root:
/// update the current branch with the configured merge/rebase method, while
/// advancing a non-current local ref directly from its tracking branch.
/// Repository metadata is re-read here so a stale dashboard snapshot cannot
/// update the wrong root or accidentally route the current branch through the
/// non-current ref-update path.
func executeBranchUpdateInRoot(
    repo: Repository,
    rootPath: String,
    branch: String,
    displayName: String,
    rebase: Bool,
    tagMode: FetchTagsMode,
    broker: CredentialBroker,
    cancel: GitCancelHandle,
    savePolicy: LocalChangesSavePolicy
) throws -> RootOperationResult {
    let branches = try repo.branchList()
    guard branches.contains(where: { $0.name == branch }) else {
        throw NSError(
            domain: "Arbor.Git",
            code: 1,
            userInfo: [NSLocalizedDescriptionKey: "Branch does not exist: \(branch)"]
        )
    }

    let sync = try repo.syncStatus().first { $0.branch == branch }
    guard let sync, sync.trackingExists,
          let target = remoteBranchTargetForConfiguredUpstream(
              sync.upstream,
              remotes: try repo.remoteList()
          ) else {
        throw NSError(
            domain: "Arbor.Git",
            code: 2,
            userInfo: [NSLocalizedDescriptionKey: "Branch has no valid tracking branch: \(branch)"]
        )
    }

    if branches.first(where: { $0.isCurrent })?.name == branch {
        let result = try runRootUpdateForCurrentBranchWithOptions(
            rootPath: rootPath,
            remote: target.remote,
            localBranch: branch,
            remoteBranch: target.branch,
            rebase: rebase,
            tagMode: tagMode,
            broker: broker,
            cancel: cancel,
            savePolicy: savePolicy
        )
        return RootOperationResult(
            rootPath: rootPath,
            displayName: displayName,
            success: result.success,
            skipped: result.skipped,
            message: result.message.isEmpty ? "Updated \(branch)" : result.message
        )
    }

    try repo.updateBranchWithOptionsAndAuthAndCancel(
        branch: branch,
        tagMode: tagMode,
        broker: broker,
        cancel: cancel
    )
    return RootOperationResult(
        rootPath: rootPath,
        displayName: displayName,
        success: true,
        skipped: false,
        message: "Updated \(branch)"
    )
}

func commitWarningSetting(for kind: CommitCheckKind) -> GitCommitWarningSetting? {
    switch kind {
    case .crlfWarning: return .crlf
    case .detachedHead, .rebaseInProgress: return .detachedHead
    case .largeFile: return .largeFile
    case .badFileName: return .badFileName
    default: return nil
    }
}

func multiRootPullRebaseMode(_ operation: MultiRootOperation) -> Bool? {
    switch operation {
    case .pullMerge:
        false
    case .pullRebase:
        true
    default:
        nil
    }
}

func oldestSelectedLinearCommit(
    _ commits: [CommitInfo],
    isAncestor: (String, String) -> Bool
) -> CommitInfo? {
    let candidates = commits.filter { candidate in
        commits.allSatisfy { other in
            candidate.id == other.id || isAncestor(candidate.id, other.id)
        }
    }
    guard candidates.count == 1 else { return nil }
    return candidates[0]
}

/// Prepare the root reword without changing the generated merge-preserving
/// todo order or any of its topology markers.
func preparedRootRewordTodo(
    _ todo: RebaseTodo,
    rootCommitID: String,
    message: String
) -> RebaseTodo? {
    let rootCommitID = rootCommitID.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !rootCommitID.isEmpty else { return nil }

    var prepared = todo
    guard let targetIndex = prepared.items.firstIndex(where: { item in
        item.commitId == rootCommitID
            || item.commitId.hasPrefix(rootCommitID)
            || rootCommitID.hasPrefix(item.commitId)
    }) else {
        return nil
    }
    prepared.items[targetIndex].action = .reword
    prepared.items[targetIndex].message = message
    return prepared
}

func logChangesPatchNotificationID(
    rootPaths: [String],
    reverse: Bool
) -> String {
    let roots = rootPaths
        .map { URL(fileURLWithPath: $0).standardizedFileURL.path }
        .sorted()
        .map {
            $0
                .replacingOccurrences(of: "/", with: "_")
                .replacingOccurrences(of: ":", with: "_")
        }
    let scope = roots.isEmpty ? "unknown" : roots.joined(separator: "--")
    return "arbor.log-changes-patch.\(reverse ? "reverse" : "apply").\(scope)"
}

func directPatchNotificationID(rootPath: String) -> String {
    let scope = URL(fileURLWithPath: rootPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.direct-patch.\(scope)"
}

func operationRecoveryNotificationID(rootPath: String) -> String {
    let stableRoot = URL(fileURLWithPath: rootPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.operation-recovery.\(stableRoot)"
}

/// The first response only needs to fill the visible history viewport.
/// Continuation pages stay larger so scrolling remains efficient.
private let initialLogPageLimit: UInt32 = 80
private let continuationLogPageLimit: UInt32 = 200

/// A small persisted snapshot used only to make the first Log paint faster
/// after relaunch. Git remains authoritative: the snapshot is accepted only
/// when the root, query, and all visible ref tips still match the token read
/// from the repository immediately before the fresh Rust query.
struct PersistedLogCacheCommit: Codable, Equatable, Sendable {
    let id: String
    let repositoryPath: String?
    let shortID: String
    let summary: String
    let authorName: String
    let authorEmail: String
    let committerName: String
    let committerEmail: String
    let messageBody: String
    let hasSignature: Bool
    let time: Int64
    let parentIDs: [String]
    let refs: [String]
    let tagRefs: [String]
    let remoteRefs: [String]
    let isHead: Bool
    let lane: UInt32
    let parentLanes: [UInt32]

    init(_ commit: CommitInfo) {
        id = commit.id
        repositoryPath = commit.repositoryPath
        shortID = commit.shortId
        summary = commit.summary
        authorName = commit.authorName
        authorEmail = commit.authorEmail
        committerName = commit.committerName
        committerEmail = commit.committerEmail
        messageBody = commit.messageBody
        hasSignature = commit.hasSignature
        time = commit.time
        parentIDs = commit.parentIds
        refs = commit.refs
        tagRefs = commit.tagRefs
        remoteRefs = commit.remoteRefs
        isHead = commit.isHead
        lane = commit.lane
        parentLanes = commit.parentLanes
    }

    var commitInfo: CommitInfo {
        CommitInfo(
            id: id,
            repositoryPath: repositoryPath,
            shortId: shortID,
            summary: summary,
            authorName: authorName,
            authorEmail: authorEmail,
            committerName: committerName,
            committerEmail: committerEmail,
            messageBody: messageBody,
            hasSignature: hasSignature,
            time: time,
            parentIds: parentIDs,
            refs: refs,
            tagRefs: tagRefs,
            remoteRefs: remoteRefs,
            isHead: isHead,
            lane: lane,
            parentLanes: parentLanes
        )
    }
}

struct PersistedLogCacheEntry: Codable, Equatable, Sendable {
    static let currentSchema = 2

    let schema: Int
    let rootPath: String
    let queryFingerprint: String
    let refsToken: String
    let commits: [PersistedLogCacheCommit]

    init(
        rootPath: String,
        queryFingerprint: String,
        refsToken: String,
        commits: [CommitInfo]
    ) {
        schema = Self.currentSchema
        self.rootPath = canonicalExternalLogPath(rootPath)
        self.queryFingerprint = queryFingerprint
        self.refsToken = refsToken
        self.commits = commits.map(PersistedLogCacheCommit.init)
    }

    func restoredCommitsIfValid(
        rootPath: String,
        queryFingerprint: String,
        refsToken: String
    ) -> [CommitInfo]? {
        guard schema == Self.currentSchema,
              self.rootPath == canonicalExternalLogPath(rootPath),
              self.queryFingerprint == queryFingerprint,
              self.refsToken == refsToken else {
            return nil
        }
        return commits.map(\.commitInfo)
    }
}

/// A root-scoped continuation snapshot for the visible VCS Log graph. Unlike
/// the first-paint cache above, this records every page the user has already
/// loaded, together with the exact continuation cursor and whether Git still
/// has more rows. It is a validated display/index snapshot only: refsToken
/// must match before it is restored, and Git remains the source of truth when
/// the repository graph has changed.
struct PersistedLogGraphEntry: Codable, Equatable, Sendable {
    static let currentSchema = 1

    let schema: Int
    let rootPath: String
    let queryFingerprint: String
    let refsToken: String
    let commits: [PersistedLogCacheCommit]
    let cursor: String?
    let hasMore: Bool

    init(
        rootPath: String,
        queryFingerprint: String,
        refsToken: String,
        commits: [CommitInfo],
        cursor: String?,
        hasMore: Bool
    ) {
        schema = Self.currentSchema
        self.rootPath = canonicalExternalLogPath(rootPath)
        self.queryFingerprint = queryFingerprint
        self.refsToken = refsToken
        self.commits = commits.map(PersistedLogCacheCommit.init)
        self.cursor = cursor
        self.hasMore = hasMore
    }

    func restoredIfValid(
        rootPath: String,
        queryFingerprint: String,
        refsToken: String
    ) -> PersistedLogGraphRestore? {
        guard schema == Self.currentSchema,
              self.rootPath == canonicalExternalLogPath(rootPath),
              self.queryFingerprint == queryFingerprint,
              self.refsToken == refsToken,
              !hasMore || cursor != nil else {
            return nil
        }
        return PersistedLogGraphRestore(
            commits: commits.map(\.commitInfo),
            cursor: cursor,
            hasMore: hasMore
        )
    }
}

struct PersistedLogGraphRestore: Equatable, Sendable {
    let commits: [CommitInfo]
    let cursor: String?
    let hasMore: Bool
}

private struct PersistedLogCacheQuery: Codable, Equatable, Sendable {
    let rootPath: String
    let pathFilters: [String]
    let startRevisions: [String]
    let author: String
    let message: String
    let messageRegex: Bool
    let messageMatchCase: Bool
    let since: String
    let until: String
    let noMerges: Bool
    let follow: Bool
    let sortMode: String
    let pageLimit: UInt32
}

func persistedLogCacheQueryFingerprint(
    rootPath: String,
    pathFilters: [String],
    startRevisions: [String],
    author: String,
    message: String,
    messageRegex: Bool,
    messageMatchCase: Bool,
    since: String,
    until: String,
    noMerges: Bool,
    follow: Bool,
    sortMode: String,
    pageLimit: UInt32
) -> String {
    let query = PersistedLogCacheQuery(
        rootPath: canonicalExternalLogPath(rootPath),
        pathFilters: pathFilters,
        startRevisions: startRevisions,
        author: author,
        message: message,
        messageRegex: messageRegex,
        messageMatchCase: messageMatchCase,
        since: since,
        until: until,
        noMerges: noMerges,
        follow: follow,
        sortMode: sortMode,
        pageLimit: pageLimit
    )
    let encoder = JSONEncoder()
    encoder.outputFormatting = [.sortedKeys]
    guard let data = try? encoder.encode(query) else { return "" }
    return data.base64EncodedString()
}

/// Graph snapshots survive page-size changes. The visible page size is a UI
/// batching detail, not part of the Git Log query identity.
func persistedLogGraphQueryFingerprint(
    rootPath: String,
    pathFilters: [String],
    startRevisions: [String],
    author: String,
    message: String,
    messageRegex: Bool,
    messageMatchCase: Bool,
    since: String,
    until: String,
    noMerges: Bool,
    follow: Bool,
    sortMode: String
) -> String {
    persistedLogCacheQueryFingerprint(
        rootPath: rootPath,
        pathFilters: pathFilters,
        startRevisions: startRevisions,
        author: author,
        message: message,
        messageRegex: messageRegex,
        messageMatchCase: messageMatchCase,
        since: since,
        until: until,
        noMerges: noMerges,
        follow: follow,
        sortMode: sortMode,
        pageLimit: 0
    )
}

private struct PersistedLogRefsToken: Codable, Equatable, Sendable {
    let rootPath: String
    let headID: String
    let localBranches: [String]
    let remoteBranches: [String]
    let tags: [String]

    init(repo: Repository, rootPath: String) throws {
        self.rootPath = canonicalExternalLogPath(rootPath)
        headID = repo.headCommitId() ?? ""
        let refSnapshot = try repo.refTipSnapshot()
        localBranches = refSnapshot
            .filter { $0.hasPrefix("local\u{1f}") }
            .sorted()
        remoteBranches = refSnapshot
            .filter { $0.hasPrefix("remote\u{1f}") }
            .sorted()
        tags = refSnapshot
            .filter { $0.hasPrefix("tag\u{1f}") }
            .sorted()
    }
}

func persistedLogRefsToken(repo: Repository, rootPath: String) -> String? {
    guard let data = try? JSONEncoder().encode(
        PersistedLogRefsToken(repo: repo, rootPath: rootPath)
    ) else {
        return nil
    }
    return data.base64EncodedString()
}

private let persistedLogCacheKeyPrefix = "arbor.vcs-log-cache.v2."
private let persistedLogGraphKeyPrefix = "arbor.vcs-log-graph.v1."
private let persistedLogGraphFilePrefix = "arbor-vcs-log-graph-v1-"
private let persistedLogGraphWriteQueue = DispatchQueue(
    label: "com.arbor.vcs-log-graph-cache",
    qos: .utility
)

private func persistedLogCacheKey(rootPath: String) -> String {
    let encoded = Data(canonicalExternalLogPath(rootPath).utf8)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
    return persistedLogCacheKeyPrefix + encoded
}

private func persistedLogGraphKey(rootPath: String) -> String {
    let encoded = Data(canonicalExternalLogPath(rootPath).utf8)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
    return persistedLogGraphKeyPrefix + encoded
}

private func persistedLogGraphURL(rootPath: String) -> URL? {
    guard let cachesURL = FileManager.default.urls(
        for: .cachesDirectory,
        in: .userDomainMask
    ).first else {
        return nil
    }
    let encoded = Data(canonicalExternalLogPath(rootPath).utf8)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
    return cachesURL
        .appendingPathComponent("Arbor/VCSLogGraph", isDirectory: true)
        .appendingPathComponent(persistedLogGraphFilePrefix + encoded)
        .appendingPathExtension("json")
}

private func loadPersistedLogCache(rootPath: String) -> PersistedLogCacheEntry? {
    guard let data = UserDefaults.standard.data(
        forKey: persistedLogCacheKey(rootPath: rootPath)
    ) else {
        return nil
    }
    return try? JSONDecoder().decode(PersistedLogCacheEntry.self, from: data)
}

private func savePersistedLogCache(_ entry: PersistedLogCacheEntry) {
    guard let data = try? JSONEncoder().encode(entry) else { return }
    UserDefaults.standard.set(data, forKey: persistedLogCacheKey(rootPath: entry.rootPath))
}

private func loadPersistedLogGraph(rootPath: String) -> PersistedLogGraphEntry? {
    if let url = persistedLogGraphURL(rootPath: rootPath),
       let data = try? Data(contentsOf: url),
       let entry = try? JSONDecoder().decode(PersistedLogGraphEntry.self, from: data) {
        return entry
    }
    // Read the previous UserDefaults representation once as a migration
    // fallback. New writes are disk-backed so large histories do not inflate
    // the application's preferences domain.
    guard let data = UserDefaults.standard.data(
        forKey: persistedLogGraphKey(rootPath: rootPath)
    ) else {
        return nil
    }
    return try? JSONDecoder().decode(PersistedLogGraphEntry.self, from: data)
}

private func savePersistedLogGraph(_ entry: PersistedLogGraphEntry) {
    persistedLogGraphWriteQueue.async {
        guard let data = try? JSONEncoder().encode(entry) else { return }
        if let url = persistedLogGraphURL(rootPath: entry.rootPath) {
            do {
                try FileManager.default.createDirectory(
                    at: url.deletingLastPathComponent(),
                    withIntermediateDirectories: true
                )
                try data.write(to: url, options: [.atomic])
                return
            } catch {
                // A cache write must never make the Git Log operation fail.
                // Fall back to the legacy store if the cache directory is not
                // writable (for example in a restricted test container).
            }
        }
        UserDefaults.standard.set(data, forKey: persistedLogGraphKey(rootPath: entry.rootPath))
    }
}

/// A display-only status snapshot used to make the Commit workspace useful
/// immediately after relaunch. Git status remains authoritative: the snapshot
/// is replaced as soon as the fresh scan completes and is never used to decide
/// whether a Git operation is safe.
struct PersistedStatusCacheEntry: Codable, Equatable, Sendable {
    static let currentSchema = 1

    struct File: Codable, Equatable, Sendable {
        let path: String
        let oldPath: String?
        let staged: String
        let unstaged: String

        init(_ entry: FileEntry) {
            path = entry.path
            oldPath = entry.oldPath
            staged = persistedChangeKind(entry.staged)
            unstaged = persistedChangeKind(entry.unstaged)
        }

        var fileEntry: FileEntry? {
            guard let staged = changeKind(rawValue: staged),
                  let unstaged = changeKind(rawValue: unstaged) else {
                return nil
            }
            return FileEntry(
                path: path,
                oldPath: oldPath,
                staged: staged,
                unstaged: unstaged
            )
        }
    }

    struct ChangeList: Codable, Equatable, Sendable {
        let name: String
        let paths: [String]
        let isDefault: Bool
        let isActive: Bool

        init(_ list: ChangeListInfo) {
            name = list.name
            paths = list.paths
            isDefault = list.isDefault
            isActive = list.isActive
        }

        var changeListInfo: ChangeListInfo {
            ChangeListInfo(
                name: name,
                paths: paths,
                isDefault: isDefault,
                isActive: isActive
            )
        }
    }

    let schema: Int
    let rootPath: String
    let savedAt: Date
    let files: [File]
    let changeLists: [ChangeList]

    init(
        rootPath: String,
        files: [FileEntry],
        changeLists: [ChangeListInfo],
        savedAt: Date = Date()
    ) {
        schema = Self.currentSchema
        self.rootPath = canonicalExternalLogPath(rootPath)
        self.savedAt = savedAt
        self.files = files.map(File.init)
        self.changeLists = changeLists.map(ChangeList.init)
    }

    func restoredSnapshot(
        rootPath: String
    ) -> (files: [FileEntry], changeLists: [ChangeListInfo])? {
        guard schema == Self.currentSchema,
              self.rootPath == canonicalExternalLogPath(rootPath) else {
            return nil
        }
        return (
            files: files.compactMap(\.fileEntry),
            changeLists: changeLists.map(\.changeListInfo)
        )
    }
}

private func persistedChangeKind(_ kind: ChangeKind) -> String {
    switch kind {
    case .unchanged: return "unchanged"
    case .added: return "added"
    case .modified: return "modified"
    case .deleted: return "deleted"
    case .renamed: return "renamed"
    case .copied: return "copied"
    case .typeChanged: return "typeChanged"
    case .untracked: return "untracked"
    case .ignored: return "ignored"
    case .conflicted: return "conflicted"
    }
}

private func changeKind(rawValue: String) -> ChangeKind? {
    switch rawValue {
    case "unchanged": return .unchanged
    case "added": return .added
    case "modified": return .modified
    case "deleted": return .deleted
    case "renamed": return .renamed
    case "copied": return .copied
    case "typeChanged": return .typeChanged
    case "untracked": return .untracked
    case "ignored": return .ignored
    case "conflicted": return .conflicted
    default: return nil
    }
}

private let persistedStatusCacheKeyPrefix = "arbor.vcs-status-cache.v1."
private let persistedStatusCacheFilePrefix = "arbor-vcs-status-v1-"
private let persistedStatusCacheMaximumBytes = 4 * 1024 * 1024
private let persistedStatusCacheMaximumFiles = 20_000
private let persistedStatusCacheWriteQueue = DispatchQueue(
    label: "com.arbor.vcs-status-cache",
    qos: .utility
)

private func persistedStatusCacheFileURL(rootPath: String) -> URL? {
    guard let cachesURL = FileManager.default.urls(
        for: .cachesDirectory,
        in: .userDomainMask
    ).first else {
        return nil
    }
    let encoded = Data(canonicalExternalLogPath(rootPath).utf8)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
    return cachesURL
        .appendingPathComponent("Arbor/VCSStatus", isDirectory: true)
        .appendingPathComponent(persistedStatusCacheFilePrefix + encoded)
        .appendingPathExtension("json")
}

/// The status snapshot is display-only and can be discarded during migration.
/// Keeping it in UserDefaults makes the entire preferences domain expensive to
/// load when a large repository has many changed files.
func migrateLegacyPersistedStatusCaches(defaults: UserDefaults = .standard) {
    let legacyKeys = defaults.dictionaryRepresentation().keys.filter {
        $0.hasPrefix(persistedStatusCacheKeyPrefix)
    }
    for key in legacyKeys {
        defaults.removeObject(forKey: key)
    }
}

private func loadPersistedStatusCache(rootPath: String) -> PersistedStatusCacheEntry? {
    guard let url = persistedStatusCacheFileURL(rootPath: rootPath),
          let resourceValues = try? url.resourceValues(forKeys: [.fileSizeKey]),
          let fileSize = resourceValues.fileSize,
          fileSize <= persistedStatusCacheMaximumBytes,
          let data = try? Data(contentsOf: url) else {
        return nil
    }
    return try? JSONDecoder().decode(PersistedStatusCacheEntry.self, from: data)
}

private func savePersistedStatusCache(
    rootPath: String,
    files: [FileEntry],
    changeLists: [ChangeListInfo]
) {
    guard files.count <= persistedStatusCacheMaximumFiles else { return }
    persistedStatusCacheWriteQueue.async {
        let entry = PersistedStatusCacheEntry(
            rootPath: rootPath,
            files: files,
            changeLists: changeLists
        )
        guard let url = persistedStatusCacheFileURL(rootPath: entry.rootPath),
              let data = try? JSONEncoder().encode(entry),
              data.count <= persistedStatusCacheMaximumBytes else {
            // A repository with millions of changed files is not a useful
            // startup snapshot. Avoid serializing it into any persistent store.
            return
        }
        do {
            try FileManager.default.createDirectory(
                at: url.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            try data.write(to: url, options: [.atomic])
        } catch {
            // A cache write must never make a Git operation fail.
        }
    }
}

struct PullLocalChangesPreservation: Codable, Equatable, Sendable {
    let shelfName: String?
    let stashMessage: String?
    /// Stable identity for the temporary Pull stash. Older persisted markers
    /// may omit this and continue to use the unique message fallback.
    let stashID: String?

    init(shelfName: String?, stashMessage: String?, stashID: String? = nil) {
        self.shelfName = shelfName
        self.stashMessage = stashMessage
        self.stashID = stashID
    }
}

/// Update Project uses a stable stash message so recovery survives an app
/// restart. The Git operation state itself remains the source of truth on
/// disk; this helper only identifies Arbor's temporary local-change stash.
func isArborUpdateStashMessage(_ message: String) -> Bool {
    message == "Arbor: Update Project" || message == "Arbor: Update Project (rebase)"
}

/// Multi-root preserving processes use a unique Shelf name so parallel roots
/// never overwrite one another. The stable prefix keeps relaunch recovery
/// discoverable without depending on in-memory operation state.
func isArborUpdateShelfName(_ name: String) -> Bool {
    name.hasPrefix("Arbor: Update Project")
        || name.hasPrefix("Arbor: Checkout and Update")
}

func isArborPushRecoveryStashMessage(_ message: String) -> Bool {
    message.hasPrefix("Arbor: Push update")
}

func isArborPushRecoveryShelfName(_ name: String) -> Bool {
    name.hasPrefix("Arbor: Push update")
}

func isArborTemporaryStashMessage(_ message: String) -> Bool {
    isArborUpdateStashMessage(message) || isArborPushRecoveryStashMessage(message)
}

func isArborTemporaryShelfName(_ name: String) -> Bool {
    isArborUpdateShelfName(name) || isArborPushRecoveryShelfName(name)
}

func isArborUpdateLocalChangesName(_ name: String) -> Bool {
    isArborTemporaryStashMessage(name) || isArborTemporaryShelfName(name)
}

/// Keep the embedded pinentry endpoint alive only for the Git operation that
/// may invoke GPG. Git's process runner injects this value into the child
/// environment, including hooks and GPG itself; all other repository refreshes
/// remain unaware of the session.
private func withArborPinentrySession<T>(_ operation: () throws -> T) rethrows -> T {
    let token = try? ArborPinentryService.shared.startSession()
    if let token {
        setPinentryUserData(value: token)
    }
    defer {
        if token != nil {
            if ArborPinentryService.shared.stopSession() {
                setPinentryUserData(value: nil)
            }
        }
    }
    return try operation()
}

/// IntelliJ only opens the Push-after-commit flow when the commit phase has
/// no failures. A partial commit keeps an explicit "Push Committed Roots"
/// action in the notification, but must not start a second operation
/// implicitly.
func shouldAutomaticallyOpenMultiRootCommitPushOptions(
    pushAfterCommit: Bool,
    pushRootPaths: [String],
    failedRootPaths: [String]
) -> Bool {
    pushAfterCommit && !pushRootPaths.isEmpty && failedRootPaths.isEmpty
}

/// Decide whether the post-commit Push flow must remain visible. This is a
/// read-only preflight: automatic Push is allowed only when the caller has an
/// unambiguous push target and an attached current branch; missing transport
/// state stays in the explicit Push options flow just like IntelliJ's
/// `!canPush()` path.
func pushAfterCommitPreviewRequiresUI(
    choice: GitPushAfterCommitPreviewChoice,
    hasPushTarget: Bool,
    hasCurrentBranch: Bool,
    isProtectedBranch: Bool
) -> Bool {
    switch choice {
    case .always:
        return true
    case .protectedOnly:
        return !hasPushTarget || !hasCurrentBranch || isProtectedBranch
    case .automatic:
        return !hasPushTarget || !hasCurrentBranch
    }
}

nonisolated func pushAfterCommitRequiresPreview(
    rootPath: String,
    choice: GitPushAfterCommitPreviewChoice,
    protectedBranchPatterns: [String]
) -> Bool {
    guard choice != .always else { return true }
    guard let rootRepo = try? openRepository(path: rootPath),
          let remotes = try? rootRepo.remoteList(),
          remotes.count == 1,
          let branch = (try? rootRepo.branchList())?.first(where: { $0.isCurrent })?.name else {
        return true
    }
    return pushAfterCommitPreviewRequiresUI(
        choice: choice,
        hasPushTarget: true,
        hasCurrentBranch: true,
        isProtectedBranch: GitProtectedBranchRules.matches(
            branch,
            patterns: protectedBranchPatterns
        )
    )
}

/// Mirrors IntelliJ's CopyRevisionNumberAction: revision numbers are copied
/// from the oldest selected row to the newest, separated by spaces so the
/// result can be pasted directly into a native Git command.
func formattedRevisionIDsForClipboard(_ ids: [String]) -> String {
    ids.reversed().joined(separator: " ")
}

/// Force-pushed replay branches are deliberately kept when the replay or
/// local-change restore cannot finish. They are user-visible recovery refs,
/// not ordinary branches created by the user, so failure feedback can offer a
/// scoped cleanup action without guessing from a shell error string.
func isArborForcePushedBackupBranch(_ name: String) -> Bool {
    name.hasPrefix("arbor-force-pushed-backup-")
}

/// A rollback action is meaningful only when the merge actually moved HEAD.
func mergeRollbackHead(initial: String?, final: String?) -> String? {
    guard let initial, let final, initial != final else { return nil }
    return initial
}

struct MultiRootMergeDeleteCandidate: Equatable {
    let rootPath: String
    let displayName: String
}

/// Keep the confirmation target set root-qualified and deterministic. The
/// semantic action may be invoked after a refresh or relaunch, so callers must
/// re-resolve the roots instead of trusting the snapshot captured at merge
/// completion.
func multiRootMergeDeleteTargets(
    selectedRootPaths: Set<String>,
    candidates: [MultiRootMergeDeleteCandidate]
) -> [MultiRootMergeDeleteCandidate] {
    let normalizedSelectedPaths = Set(selectedRootPaths.map {
        URL(fileURLWithPath: $0).standardizedFileURL.path
    })
    var seen = Set<String>()
    return candidates
        .filter { candidate in
            let normalizedRoot = URL(fileURLWithPath: candidate.rootPath).standardizedFileURL.path
            return normalizedSelectedPaths.contains(normalizedRoot) && seen.insert(normalizedRoot).inserted
        }
        .sorted {
            let lhs = URL(fileURLWithPath: $0.rootPath).standardizedFileURL.path
            let rhs = URL(fileURLWithPath: $1.rootPath).standardizedFileURL.path
            if lhs != rhs { return lhs < rhs }
            return $0.displayName < $1.displayName
        }
}

private enum CheckoutReferenceTarget: Sendable {
    case localBranch(String)
    case remoteBranch(String)
    case detached(String)
}

private func resolveCheckoutReferenceTarget(
    repo: Repository,
    reference: String
) -> CheckoutReferenceTarget {
    let normalized = reference.trimmingCharacters(in: .whitespacesAndNewlines)
    let localCandidates = [
        normalized,
        normalized.hasPrefix("refs/heads/")
            ? String(normalized.dropFirst("refs/heads/".count))
            : normalized
    ]
    if let branch = (try? repo.branchList())?.first(where: { localCandidates.contains($0.name) }) {
        return .localBranch(branch.name)
    }

    let remoteCandidates = [
        normalized,
        normalized.hasPrefix("refs/remotes/")
            ? String(normalized.dropFirst("refs/remotes/".count))
            : normalized
    ]
    if let branch = (try? repo.remoteBranchList())?.first(where: { remoteCandidates.contains($0.name) }) {
        return .remoteBranch(branch.name)
    }

    return .detached(normalized)
}

private func performCheckoutReference(
    repo: Repository,
    target: CheckoutReferenceTarget
) throws {
    switch target {
    case let .localBranch(name):
        try repo.switchBranch(name: name)
    case let .remoteBranch(name):
        try repo.checkoutRemoteBranch(remoteBranch: name, localName: nil)
    case let .detached(reference):
        try repo.checkoutDetached(commitId: reference)
    }
}

/// IntelliJ 的 GitDefineRemoteDialog 在提交新增/编辑前执行 `git ls-remote`。
/// 复用 Arbor 已有的 askpass 桥，让私有 HTTPS/SSH remote 也走同一套凭证交互。
private func remoteURLCheckFailure(
    repo: Repository,
    url: String,
    broker: CredentialBroker
) throws -> String? {
    let outcome = try broker.runGitWithAskpass(
        argv: ["ls-remote", "--", url],
        workingDir: repo.workdir()
    )
    guard outcome.exitCode == 0, !outcome.cancelled, !outcome.timedOut else {
        let detail = [outcome.stderr, outcome.stdout]
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .first(where: { !$0.isEmpty })
        if let detail {
            return detail
        }
        if outcome.cancelled {
            return "Remote URL check was cancelled."
        }
        if outcome.timedOut {
            return "Remote URL check timed out."
        }
        return "git ls-remote exited with code \(outcome.exitCode)."
    }
    return nil
}

private func loadRemoteConfigRoots(scanRoot: String) throws -> [MultiRootRemoteConfigRoot] {
    let roots = try discoverGitRoots(scanRoot: scanRoot, maxDepth: nil)
    return try roots.map { root in
        let rootRepo = try openRepository(path: root.path)
        return MultiRootRemoteConfigRoot(
            rootPath: root.path,
            displayName: root.displayName,
            relativePath: root.relativePath,
            remotes: try rootRepo.remoteList()
        )
    }
}

func rebaseRangeRequestIsCurrent(
    generation: Int,
    currentGeneration: Int,
    requestedOnto: String,
    currentOnto: String,
    requestedPreserveMerges: Bool,
    currentPreserveMerges: Bool,
    requestedRoot: Bool = false,
    currentRoot: Bool = false,
    requestedBranch: String = "",
    currentBranch: String = "",
    requestedRepositoryPath: String = "",
    currentRepositoryPath: String = ""
) -> Bool {
    generation == currentGeneration
        && requestedOnto == currentOnto
        && requestedPreserveMerges == currentPreserveMerges
        && requestedRoot == currentRoot
        && requestedBranch == currentBranch
        && requestedRepositoryPath == currentRepositoryPath
}

func rebaseUndoTargetAfterCompletion(
    seed: RebaseUndoSeed?,
    currentBranch: String?,
    finalHead: String?
) -> RebaseUndoTarget? {
    let currentBranchIdentity = currentBranch ?? ""
    guard let seed,
          !seed.updateRefs,
          currentBranchIdentity == seed.branch,
          let finalHead,
          finalHead != seed.initialHead else { return nil }
    return RebaseUndoTarget(
        repositoryPath: seed.repositoryPath,
        branch: seed.branch,
        initialHead: seed.initialHead,
        expectedHead: finalHead,
        protectionCommitID: seed.protectionCommitID
    )
}

private func rebaseUndoSeedKey(repositoryPath: String) -> String {
    let normalizedPath = URL(fileURLWithPath: repositoryPath).standardizedFileURL.path
    let encoded = Data(normalizedPath.utf8)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
    return "arbor.rebase.undo-seed.v1.\(encoded)"
}

private func saveRebaseUndoSeed(_ seed: RebaseUndoSeed) {
    guard let data = try? JSONEncoder().encode(seed) else { return }
    UserDefaults.standard.set(data, forKey: rebaseUndoSeedKey(repositoryPath: seed.repositoryPath))
}

private func loadRebaseUndoSeed(repositoryPath: String) -> RebaseUndoSeed? {
    guard let data = UserDefaults.standard.data(forKey: rebaseUndoSeedKey(repositoryPath: repositoryPath)) else {
        return nil
    }
    return try? JSONDecoder().decode(RebaseUndoSeed.self, from: data)
}

private func clearRebaseUndoSeed(repositoryPath: String) {
    UserDefaults.standard.removeObject(forKey: rebaseUndoSeedKey(repositoryPath: repositoryPath))
}

private func rebaseRecoveryNotificationID(repositoryPath: String) -> String {
    let stablePath = URL(fileURLWithPath: repositoryPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.rebase-recovery.\(stablePath)"
}

private func rebaseUndoNotificationID(repositoryPath: String) -> String {
    let stablePath = URL(fileURLWithPath: repositoryPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.rebase-undo.\(stablePath)"
}

private func pendingPullPreservationKey(repositoryPath: String) -> String {
    let normalizedPath = URL(fileURLWithPath: repositoryPath).standardizedFileURL.path
    let encoded = Data(normalizedPath.utf8)
