    return try? JSONDecoder().decode(PullLocalChangesPreservation.self, from: data)
}

private func clearPendingPullPreservation(repositoryPath: String) {
    UserDefaults.standard.removeObject(
        forKey: pendingPullPreservationKey(repositoryPath: repositoryPath)
    )
}

private func logApplyRecoveryKey(repositoryPath: String) -> String {
    let normalizedPath = URL(fileURLWithPath: repositoryPath).standardizedFileURL.path
    let encoded = Data(normalizedPath.utf8)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
    return "arbor.log-apply-recovery.v1.\(encoded)"
}

private func saveLogApplyRecovery(_ recovery: PersistedLogApplyRecovery) {
    guard let data = try? JSONEncoder().encode(recovery) else { return }
    UserDefaults.standard.set(data, forKey: logApplyRecoveryKey(repositoryPath: recovery.rootPath))
}

private func loadLogApplyRecovery(repositoryPath: String) -> PersistedLogApplyRecovery? {
    guard let data = UserDefaults.standard.data(
        forKey: logApplyRecoveryKey(repositoryPath: repositoryPath)
    ) else {
        return nil
    }
    return try? JSONDecoder().decode(PersistedLogApplyRecovery.self, from: data)
}

private func pendingLogApplyRecoveries(
    sessionID: String
) -> [PersistedLogApplyRecovery] {
    UserDefaults.standard.dictionaryRepresentation().compactMap { key, value in
        guard key.hasPrefix("arbor.log-apply-recovery.v1."),
              let data = value as? Data,
              let recovery = try? JSONDecoder().decode(
                  PersistedLogApplyRecovery.self,
                  from: data
              ),
              recovery.sessionID == sessionID else {
            return nil
        }
        return recovery
    }.sorted { $0.batchIndex < $1.batchIndex }
}

/// Only the earliest still-pending root may be replayed. This preserves the
/// same ordered compound semantics as the original Log action and prevents a
/// later root from being applied while an earlier root is unresolved.
func logApplyRecoveryCanRun(
    _ recovery: PersistedLogApplyRecovery,
    pending: [PersistedLogApplyRecovery]
) -> Bool {
    pending.sorted { $0.batchIndex < $1.batchIndex }.first == recovery
}

/// Aborting one root cancels the whole ordered Log Revert/Cherry-pick
/// session. The operation is presented as one user action, so later roots
/// must not retain retry markers after the active root has been aborted.
func logApplyRecoveryCancellationTargets(
    current: PersistedLogApplyRecovery?,
    pending: [PersistedLogApplyRecovery]
) -> [PersistedLogApplyRecovery] {
    guard let current else { return [] }
    return pending
        .filter {
            $0.sessionID == current.sessionID
                && $0.operation == current.operation
        }
        .sorted { $0.batchIndex < $1.batchIndex }
}

func logApplyRecoveryActionTitle(
    _ recovery: PersistedLogApplyRecovery
) -> String {
    let operation = switch recovery.operation {
    case .cherryPick: "Cherry-pick"
    case .revert: "Revert"
    }
    guard recovery.preserveLocalChanges else {
        return "Retry \(operation)"
    }
    let policyTitle = GitLocalChangesSavePolicyChoice(rawValue: recovery.savePolicyRaw)?.title
        ?? "Local Changes"
    return "Save and Retry \(operation) (\(policyTitle))"
}

private func clearLogApplyRecovery(repositoryPath: String) {
    UserDefaults.standard.removeObject(forKey: logApplyRecoveryKey(repositoryPath: repositoryPath))
}

private func makeRebaseUndoSeed(
    repo: Repository,
    branch: String,
    onto: String? = nil
) -> RebaseUndoSeed? {
    guard let repositoryPath = repo.workdir(),
          !repositoryPath.isEmpty,
          let initialHead = try? repo.revisionCommitId(revision: branch) else { return nil }
    return RebaseUndoSeed(
        repositoryPath: repositoryPath,
        branch: branch,
        initialHead: initialHead,
        updateRefs: false,
        protectionCommitID: onto.flatMap {
            rebaseUndoProtectionCommitBeforeOperation(
                repo: repo,
                initialHead: initialHead,
                onto: $0
            )
        }
    )
}

/// Capture IntelliJ's firstChangedHash boundary before a rebase rewrites refs.
/// This helper is global because seeds are also created by nonisolated
/// operation setup paths outside the ContentView extension.
private func rebaseUndoProtectionCommitBeforeOperation(
    repo: Repository,
    initialHead: String,
    onto: String
) -> String? {
    let normalizedOnto = onto.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedOnto.isEmpty,
          let ontoID = try? repo.revisionCommitId(revision: normalizedOnto),
          ontoID != initialHead,
          let base = try? repo.mergeBaseRevisionId(
              first: initialHead,
              second: ontoID
          ),
          let commits = try? repo.logWithCommand(
              commandArgs: ["--reverse", "\(base)..\(initialHead)"],
              limit: 1
          ) else {
        return nil
    }
    return commits.first?.id
}

/// Log date fields accept calendar dates. Keep epoch seconds as a
/// backwards-compatible input, matching IntelliJ's persisted date filter.
func parseLogDate(_ value: String) -> Int64? {
    let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalized.isEmpty else { return nil }
    if let seconds = Int64(normalized) { return seconds }

    let formatter = DateFormatter()
    formatter.locale = Locale(identifier: "en_US_POSIX")
    formatter.timeZone = TimeZone.current
    for format in ["yyyy-MM-dd", "yyyy-MM-dd HH:mm", "yyyy-MM-dd HH:mm:ss"] {
        formatter.dateFormat = format
        if let date = formatter.date(from: normalized) {
            return Int64(date.timeIntervalSince1970)
        }
    }
    return nil
}

/// Mirrors IntelliJ's post-fetch suggestion. It is deliberately attached to
/// a successful manual fetch, capped at three prompts, and never replaces the
/// completed operation with a separate warning entry.
func shouldSuggestAutoFetch(
    autoFetchEnabled: Bool,
    suggestionDisabled: Bool,
    shownCount: Int
) -> Bool {
    !autoFetchEnabled && !suggestionDisabled && shownCount < 3
}

func uncommitChangedPaths(_ changes: [TreeChange]) -> [String] {
    var result: [String] = []
    var seen = Set<String>()
    for change in changes {
        for path in [change.oldPath, change.path].compactMap({ $0 }) {
            guard !path.isEmpty, seen.insert(path).inserted else { continue }
            result.append(path)
        }
    }
    return result.sorted()
}

func operationRecoveryNotificationRootKey(_ rootPath: String) -> String {
    URL(fileURLWithPath: rootPath).standardizedFileURL.path
}

/// Stable root-local identity for a paused Git operation. Git metadata
/// refreshes can report the same state many times; conflict resolution or a
/// rebase step can change the fingerprint and should produce a replacement
/// notice instead of being hidden by a notification-ID-only check.
func operationRecoveryNotificationFingerprint(_ state: OperationState) -> String {
    let kind: String
    switch state.kind {
    case .merge: kind = "merge"
    case .rebase: kind = "rebase"
    case .cherryPick: kind = "cherry-pick"
    case .revert: kind = "revert"
    }
    let origin: String
    switch state.origin {
    case .git: origin = "git"
    case .engine: origin = "engine"
    }
    let backend: String
    switch state.backend {
    case .merge?: backend = "merge"
    case .apply?: backend = "apply"
    case nil: backend = "none"
    }
    let conflicts = state.conflictedFiles.sorted().joined(separator: "\u{1f}")
    return [
        kind,
        origin,
        backend,
        state.interactive ? "interactive" : "non-interactive",
        state.onto ?? "",
        state.originalBranch ?? "",
        state.stepsDone.map(String.init) ?? "",
        state.stepsTotal.map(String.init) ?? "",
        state.message ?? "",
        conflicts
    ].joined(separator: "\u{1e}")
}

/// Mirrors GitDeleteBranchOperation's optional notification action. The
/// remote ref is only offered when the deleted local branch was the sole
/// tracker, the tracking ref still exists, and the remote branch is not
/// protected by the effective project rules.
func deletableTrackedRemoteBranch(
    branchName: String,
    upstream: String?,
    syncStatuses: [SyncStatus],
    protectedPatterns: [String]
) -> String? {
    let candidate = deletableTrackedRemoteBranches(
        branchName: branchName,
        syncStatusesByRoot: [syncStatuses],
        protectedPatterns: protectedPatterns
    )
    guard let upstream = upstream?.trimmingCharacters(in: .whitespacesAndNewlines),
          candidate.contains(upstream) else { return nil }
    return upstream
}

func deletableTrackedRemoteBranches(
    branchName: String,
    syncStatusesByRoot: [[SyncStatus]],
    protectedPatterns: [String]
) -> Set<String> {
    let normalizedBranch = branchName.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedBranch.isEmpty else { return [] }
    let candidates = Set(
        syncStatusesByRoot
            .flatMap { $0 }
            .filter {
                $0.branch == normalizedBranch
                    && $0.trackingExists
                    && $0.upstream.contains("/")
            }
            .map(\.upstream)
    )
    let otherTrackers = Set(
        syncStatusesByRoot
            .flatMap { $0 }
            .filter { $0.branch != normalizedBranch && $0.trackingExists }
            .map(\.upstream)
    )
    return Set(
        candidates.filter { upstream in
            guard !otherTrackers.contains(upstream) else { return false }
            let remoteBranchName = String(
                upstream.split(separator: "/", maxSplits: 1).dropFirst().joined(separator: "/")
            )
            return !remoteBranchName.isEmpty
                && !GitProtectedBranchRules.matches(remoteBranchName, patterns: protectedPatterns)
        }
    )
}

/// A Smart/Force retry only reruns roots blocked by local changes. Keep the
/// first pass's other root results and replace just the retried roots, matching
/// IntelliJ's aggregate reset result instead of collapsing the operation view
/// to the retry subset.
func mergeRootOperationResults(
    preserved: [RootOperationResult],
    retry: [RootOperationResult],
    rootOrder: [String]
) -> [RootOperationResult] {
    var byRoot = Dictionary(uniqueKeysWithValues: preserved.map { ($0.rootPath, $0) })
    retry.forEach { byRoot[$0.rootPath] = $0 }
    var orderedPaths = rootOrder
    orderedPaths.append(contentsOf: byRoot.keys.filter { !orderedPaths.contains($0) }.sorted())
    return orderedPaths.compactMap { byRoot[$0] }
}

/// Rebuild the small engine result value needed by Push's classification
/// helpers from the persisted presentation rows. This is only used after a
/// root-scoped retry, where the current engine call contains a subset and the
/// final notification must classify the cumulative result tree.
func rootOperationResults(from rows: [FeedbackResultRow]) -> [RootOperationResult] {
    rows.map { row in
        RootOperationResult(
            rootPath: row.rootPath,
            displayName: row.displayName,
            success: row.state == .success,
            skipped: row.state == .skipped,
            message: row.detail
        )
    }
}

/// A targeted Force Push retry may only carry force options forward when every
/// still-failed root in that retry is a stale-lease rejection. Never let a
/// force action selected for one root silently turn an unrelated NFF or
/// transport retry into a force push.
func multiRootPushRetryForceOptions(
    requestedForce: Bool,
    requestedForceWithLease: Bool,
    hasPriorResultRows: Bool,
    retryResults: [RootOperationResult]
) -> (force: Bool, forceWithLease: Bool) {
    guard requestedForce else { return (false, false) }
    guard hasPriorResultRows else {
        return (true, requestedForceWithLease)
    }
    let onlyStaleLeaseFailures = !retryResults.isEmpty
        && retryResults.allSatisfy {
            !$0.success && pushResultIsStaleLeaseRejected($0)
        }
    return onlyStaleLeaseFailures
        ? (true, requestedForceWithLease)
        : (false, false)
}

/// Multi-root Merge needs to retain more than the display row when Smart
/// retrying: initial/final HEAD and pending/conflict state drive the rollback
/// surface after the retry. Replace only retried roots while preserving the
/// complete first-pass result for every other root.
func mergeMultiRootMergeResults(
    preserved: [MultiRootMergeResult],
    retry: [MultiRootMergeResult],
    rootOrder: [String]
) -> [MultiRootMergeResult] {
    var byRoot = Dictionary(uniqueKeysWithValues: preserved.map { ($0.rootPath, $0) })
    retry.forEach { byRoot[$0.rootPath] = $0 }
    var orderedPaths = rootOrder
    orderedPaths.append(contentsOf: byRoot.keys.filter { !orderedPaths.contains($0) }.sorted())
    return orderedPaths.compactMap { byRoot[$0] }
}

nonisolated func stalePushRejectionDetails(
    _ error: Error
) -> (remote: String, branch: String, message: String)? {
    guard case let .PushRejected(kind, remote, branch, message) = error as? EngineError,
          kind == .staleInfo else { return nil }
    return (remote: remote, branch: branch, message: message)
}

/// Preserve a requested Log row across an asynchronous reload. Navigation
/// resolves a full object id, while ordinary refreshes may only have a short
/// id from the existing selection, so keep the same exact-or-prefix matching
/// semantics in one testable helper.
func matchingLogCommitID(
    requestedID: String?,
    in commits: [CommitInfo]
) -> String? {
    guard let requestedID = requestedID?.trimmingCharacters(in: .whitespacesAndNewlines),
          !requestedID.isEmpty else { return nil }
    if let exact = commits.first(where: { $0.id == requestedID }) {
        return exact.id
    }
    return commits.first(where: {
        $0.id.hasPrefix(requestedID) || requestedID.hasPrefix($0.id)
    })?.id
}

/// Merge command-filter results from multiple Git roots without allowing
/// identical object ids to collapse across repositories. A single-root
/// command keeps Git's emitted order; aggregate commands use the same stable
/// time/root/id ordering as the aggregate Log table and clear graph lanes that
/// would otherwise imply parent edges between unrelated repositories.
func mergedLogCommandEntries(
    _ entriesByRoot: [[CommitInfo]],
    limit: Int,
    aggregate: Bool
) -> [CommitInfo] {
    guard limit > 0 else { return [] }
    var entries = entriesByRoot.flatMap { $0 }
    if aggregate {
        entries = entries.map { commit in
            var flattened = commit
            flattened.lane = 0
            flattened.parentLanes = []
            return flattened
        }.sorted {
            if $0.time != $1.time { return $0.time > $1.time }
            let leftRoot = $0.repositoryPath ?? ""
            let rightRoot = $1.repositoryPath ?? ""
            if leftRoot != rightRoot { return leftRoot < rightRoot }
            return $0.id < $1.id
        }
    }
    var seen = Set<String>()
    return entries.filter { commit in
        let key = "\(commit.repositoryPath ?? "")\u{1f}\(commit.id)"
        return seen.insert(key).inserted
    }.prefix(limit).map { $0 }
}

/// Return Git's explicit max-count value when it is numeric. Options after
/// `--` are pathspecs and must not affect command-log paging.
func gitLogCommandMaximum(_ arguments: [String]) -> Int? {
    let options = arguments.prefix { $0 != "--" }
    for (index, argument) in options.enumerated() {
        if argument.hasPrefix("--max-count=") {
            return Int(argument.dropFirst("--max-count=".count))
        }
        if argument == "--max-count" || argument == "-n" {
            guard index + 1 < options.count else { return nil }
            return Int(options[index + 1])
        }
        if argument.hasPrefix("-n") {
            return Int(argument.dropFirst(2))
        }
        if argument.count > 1,
           argument.first == "-",
           Int(argument.dropFirst()) != nil {
            return Int(argument.dropFirst())
        }
    }
    return nil
}

/// IntelliJ's command filter keeps collecting until the command itself
/// imposes a maximum. Recognize the common Git spellings so command Log can
/// expose the same load-more behavior instead of treating the first page as
/// the complete result.
func gitLogCommandHasExplicitLimit(_ arguments: [String]) -> Bool {
    let options = arguments.prefix { $0 != "--" }
    return options.contains { argument in
        argument == "--max-count"
            || argument.hasPrefix("--max-count=")
            || argument == "-n"
            || (argument.hasPrefix("-n") && Int(argument.dropFirst(2)) != nil)
            || (argument.count > 1
                && argument.first == "-"
                && Int(argument.dropFirst()) != nil)
    }
}

func externalVCSActionNotificationID(repositoryPath: String) -> String {
    let stablePath = URL(fileURLWithPath: repositoryPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.external-vcs-action.\(stablePath)"
}

func runRepositoryExternalVCSActions(
    repo: Repository,
    addPaths: [String],
    stageAddPaths: [String],
    removePaths: [String],
    forceMoves: [RepositoryExternalVCSMove]
) throws -> String {
    var completed: [String] = []
    if !addPaths.isEmpty {
        // Rename destinations follow IntelliJ's move/rename path and stage
        // their complete content. Newly created files use the separate
        // empty-blob path below.
        let result = try repo.runGitCommand(
            command: "add",
            args: ["--"] + addPaths
        )
        guard result.exitCode == 0 else {
            throw NSError(
                domain: "Arbor.GitVFSListener",
                code: Int(result.exitCode),
                userInfo: [
                    NSLocalizedDescriptionKey:
                        result.stderr.isEmpty ? result.stdout : result.stderr
                ]
            )
        }
        completed.append("Added \(addPaths.count) file(s)")
    }
    if !stageAddPaths.isEmpty {
        // IntelliJ's staging-area VFS listener uses addPathsToIndex: an empty
        // blob is written to the index while the real content stays outside it.
        try repo.stageEmptyBlobPaths(paths: stageAddPaths)
        completed.append("Added \(stageAddPaths.count) new file(s) to the staging index")
    }
    if !removePaths.isEmpty {
        let result = try repo.runGitCommand(
            command: "rm",
            args: ["--cached", "--ignore-unmatch", "-r", "--"] + removePaths
        )
        guard result.exitCode == 0 else {
            throw NSError(
                domain: "Arbor.GitVFSListener",
                code: Int(result.exitCode),
                userInfo: [
                    NSLocalizedDescriptionKey:
                        result.stderr.isEmpty ? result.stdout : result.stderr
                ]
            )
        }
        completed.append("Removed \(removePaths.count) file(s) from Git")
    }
    // GitVFSListener performs ordinary add/delete work before case-only force
    // moves. Preserve that ordering for mixed VFS batches.
    if !forceMoves.isEmpty {
        for move in forceMoves {
            let result = try repo.runGitCommand(
                command: "mv",
                args: ["-f", "--", move.oldPath, move.newPath]
            )
            guard result.exitCode == 0 else {
                throw NSError(
                    domain: "Arbor.GitVFSListener",
                    code: Int(result.exitCode),
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            result.stderr.isEmpty ? result.stdout : result.stderr
                    ]
                )
            }
            completed.append("Moved \(move.oldPath) to \(move.newPath)")
        }
    }
    return completed.joined(separator: "; ")
}

/// Shelf semantic actions carry a root-qualified identity. Reject an inactive
/// root before any action can accidentally use `projectRepo`; metadata-only
/// actions may proceed through the selected secondary Shelf repository.
func shelfActionRootMatchesCurrentRoot(
    requestedRootPath: String?,
    currentRootPath: String?
) -> Bool {
    guard let requestedRootPath else { return true }
    guard let currentRootPath else { return false }
    return canonicalExternalLogPath(requestedRootPath)
        == canonicalExternalLogPath(currentRootPath)
}

/// A nil selection means the workspace's primary root. This helper keeps the
/// read-only boundary explicit and testable instead of relying on view state
/// comparisons that can briefly observe an old root during reload.
func shelfRootSelectionIsPrimary(
    selectedRootPath: String?,
    primaryRootPath: String?
) -> Bool {
    guard let primaryRootPath else { return selectedRootPath == nil }
    guard let selectedRootPath else { return true }
    return canonicalExternalLogPath(selectedRootPath)
        == canonicalExternalLogPath(primaryRootPath)
}

/// A secondary Shelf root owns its shelf files under `.git`. A metadata event
/// for that root must reload the selected Shelf snapshot; refreshing the
/// aggregate Branches snapshot alone cannot update Recently Deleted or the
/// selected root's existing change-list snapshot.
func shouldRefreshSecondaryShelfSnapshot(
    eventRootPath: String,
    activeRootPath: String?,
    primaryRootPath: String?,
    scopes: RepositoryChangeScope
) -> Bool {
    guard scopes.contains(.gitMetadata),
          let activeRootPath,
          !shelfRootSelectionIsPrimary(
              selectedRootPath: activeRootPath,
              primaryRootPath: primaryRootPath
          ) else {
        return false
    }
    return canonicalExternalLogPath(eventRootPath)
        == canonicalExternalLogPath(activeRootPath)
}

func shelfNotificationID(prefix: String, rootPath: String) -> String {
    let stableRoot = rootPath
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.\(prefix).\(stableRoot)"
}

func shelfFeedbackTitle(
    _ operation: ArborVCSActionRequest.ShelfBatchOperation,
    removeApplied: Bool = false
) -> String {
    switch operation {
    case .apply:
        return removeApplied ? "Unshelve and Remove Shelf" : "Apply Shelf"
    case .pop:
        return "Pop Shelf"
    case .drop:
        return "Drop Shelf"
    }
}

private func shelfMutationContext(
    rootPath: String?,
    activeRootPath: String?,
    primaryRootPath: String?,
    primaryRepository: Repository?,
    secondaryRepository: Repository?
) -> (repository: Repository, rootPath: String)? {
    guard let requestedRootPath = rootPath ?? primaryRootPath,
          !requestedRootPath.isEmpty else { return nil }
    let resolvedRootPath = canonicalExternalLogPath(requestedRootPath)

    // A direct call without an explicit root is a primary-root operation. An
    // explicit root must still be the root currently selected in the Shelf
    // workspace; this prevents a late notification action from crossing roots.
    if rootPath == nil {
        guard shelfRootSelectionIsPrimary(
            selectedRootPath: activeRootPath,
            primaryRootPath: primaryRootPath
        ) else { return nil }
    } else {
        guard shelfActionRootMatchesCurrentRoot(
            requestedRootPath: resolvedRootPath,
            currentRootPath: activeRootPath
        ) else { return nil }
    }

    if shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryRootPath
    ) {
        guard let primaryRepository else { return nil }
        return (primaryRepository, resolvedRootPath)
    }
    guard let secondaryRepository else { return nil }
    return (secondaryRepository, resolvedRootPath)
}

func shelfPreviewRequestMatches(
    requestedRootPath: String,
    currentRootPath: String?,
    requestedName: String,
    currentName: String?,
    requestedIsDeleted: Bool,
    currentIsDeleted: Bool
) -> Bool {
    shelfActionRootMatchesCurrentRoot(
        requestedRootPath: requestedRootPath,
        currentRootPath: currentRootPath
    )
        && requestedName == currentName
        && requestedIsDeleted == currentIsDeleted
}

func isSecondaryShelfRootScopedAction(
    _ kind: ArborVCSActionRequest.Kind
) -> Bool {
    switch kind {
    case .restoreShelf,
         .restoreShelfPaths,
         .deleteDeletedShelfPaths,
         .undoShelfDeletion,
         .undoShelfDeletions,
         .dropShelf,
         .retryShelfBatch,
         .retryShelfMemberBatch,
         .retryShelfLifecycleBatch,
         .retryShelfDeletePlan,
         // Root-scoped Push notifications may target a nested Git root even
         // when the Shelf panel is currently pointed at another repository.
         .retryPush,
         .retryPushRecovery,
         .retryStashBranch,
         // Log apply recovery is also root-scoped. Its notification can be
         // acted on while the Shelf panel remains focused on another root.
         .retryLogApply,
         .showLogApplyAffectedFiles:
        return true
    default:
        return false
    }
}

func hostedFileRevisionTarget(
    for record: LogChangeRecord
) -> (commitID: String, path: String) {
    if record.change.kind == .deleted,
       let parentIndex = record.parentIndex,
       record.commit.parentIds.indices.contains(Int(parentIndex)) {
        return (
            record.commit.parentIds[Int(parentIndex)],
            record.change.path
        )
    }
    return (record.commit.id, record.change.path)
}

private func hostedFileRevisionLink(
    repository: Repository,
    remoteURL: String,
    commitID: String,
    path: String
) -> String? {
    guard !path.trimmingCharacters(in: CharacterSet(charactersIn: "/")).isEmpty else {
        return nil
    }
    return repository.permalinkForPath(
        remoteUrl: remoteURL,
        commitId: commitID,
        path: path
    )
}

struct OperationAbortConfirmation: Equatable {
    let title: String
    let message: String
    let confirmTitle: String
}

struct StashClearConfirmation: Equatable {
    let title: String
    let message: String
    let confirmTitle: String
}

func stashClearConfirmation(repositoryName: String) -> StashClearConfirmation {
    let name = repositoryName.trimmingCharacters(in: .whitespacesAndNewlines)
    let displayName = name.isEmpty ? "the current Git root" : name
    return StashClearConfirmation(
        title: "Clear all stashes in \(displayName)?",
        message: "This permanently removes every stash in \(displayName).",
        confirmTitle: "Clear All"
    )
}

func operationAbortConfirmation(
    for kind: OperationKind,
    repositoryName: String
) -> OperationAbortConfirmation {
    let operation: String
    switch kind {
    case .merge: operation = "Merge"
    case .rebase: operation = "Rebase"
    case .cherryPick: operation = "Cherry-pick"
    case .revert: operation = "Revert"
    }
    return OperationAbortConfirmation(
        title: "Abort \(operation)?",
        message: "Abort the in-progress \(operation.lowercased()) operation in \(repositoryName)? The repository will be restored to its pre-operation state.",
        confirmTitle: "Abort"
    )
}

func pushResultIsStaleLeaseRejected(_ result: RootOperationResult) -> Bool {
    let message = result.message.lowercased()
    return message.contains("stale info") || message.contains("stale lease")
}

func pushResultIsRejected(_ result: RootOperationResult) -> Bool {
    guard !result.success else { return false }
    let message = result.message.lowercased()
    let isTransportFailure = message.contains("authentication")
        || message.contains("could not read username")
        || message.contains("permission denied")
        || message.contains("not permitted")
        || message.contains("publickey")
    guard !isTransportFailure else { return false }
    return pushResultIsStaleLeaseRejected(result)
        || pushResultNeedsUpdate(result)
        || message.contains("[rejected]")
        || message.contains("push rejected")
}

func pushResultNeedsUpdate(_ result: RootOperationResult) -> Bool {
    let message = result.message.lowercased()
    return message.contains("non-fast-forward")
        || (message.contains("[rejected]")
            && (message.contains("fetch first")
                || message.contains("remote contains work")
                || message.contains("tip of your current branch is behind")))
}

/// Resolve the repository-local exclude file from Git's actual administrative
/// directory. A linked worktree's `gitDir` is `.git/worktrees/<name>`, while
/// its `commondir` points back to the shared `.git`; Git's repository-local
/// exclude file belongs to that common directory.
func repositoryGitExcludeURL(gitDirectory: URL) -> URL {
    let administrativeDirectory = gitDirectory.standardizedFileURL
    let commonDirectory = repositoryCommonGitDirectory(gitDir: administrativeDirectory)
        ?? administrativeDirectory
    return commonDirectory.appendingPathComponent("info/exclude")
}

