// MARK: 引擎操作（后台线程）

/// Log ref actions must retain the selected commit's Git root. Resolving a
/// missing path through `repo` would make an aggregate Log mutate the window's
/// primary repository, so this action path fails closed instead.
func performLogReferenceAction(
    _ commit: CommitInfo,
    target: LogReferenceActionTarget,
    action: LogReferenceAction
) {
    guard let rootPath = logReferenceRootPath(for: commit) else {
        feedbackCenter.warning(
            "Reference action unavailable",
            detail: "The selected commit has no Git root.",
            nextStep: "Refresh Git Roots, then retry from the commit history."
        )
        return
    }

    switch action {
    case .checkout:
        checkoutBranchInRoot(
            rootPath: rootPath,
            reference: target.name,
            isRemote: target.kind == .remote
        )
    case .checkoutAndUpdate:
        executeMultiRootCheckoutAndUpdate(
            reference: target.name,
            rootPath: rootPath,
            detach: false,
            rebase: false
        )
    case .checkoutWithRebase:
        executeMultiRootCheckoutAndUpdate(
            reference: target.name,
            rootPath: rootPath,
            detach: false,
            rebase: true
        )
    case .compare:
        compareBranchInRoot(rootPath: rootPath, branch: target.name)
    case .showDiff:
        showBranchDiffWithWorkingTree(rootPath: rootPath, branch: target.name)
    case .rebase:
        rebaseCurrentInRoot(rootPath: rootPath, onto: target.name)
    case .merge:
        mergeBranchInRoot(rootPath: rootPath, branch: target.name)
    case .update:
        updateBranchInRoot(rootPath: rootPath, branch: target.name)
    case .push:
        beginMultiRootPushDialog(rootPath: rootPath, branch: target.name)
    case .pullMerge:
        pullBranchInRoot(rootPath: rootPath, branch: target.name, rebase: false)
    case .pullRebase:
        pullBranchInRoot(rootPath: rootPath, branch: target.name, rebase: true)
    case .rename:
        renameBranchInRoot(rootPath: rootPath, oldName: target.name)
    case .delete:
        switch target.kind {
        case .local:
            deleteBranchInRoot(rootPath: rootPath, name: target.name)
        case .remote:
            deleteRemoteBranchInRoot(rootPath: rootPath, branch: target.name)
        case .tag:
            deleteTagInRoot(rootPath: rootPath, name: target.name)
        }
    }
}

/// IntelliJ's ref action group falls back to rebasing the current branch onto
/// the selected commit when no non-current branch ref is attached to it. The
/// reachability check belongs at invocation time because the visible log page
/// may not contain the whole current-branch history.
func rebaseOntoCommitFromLog(_ commit: CommitInfo) {
    guard let rootPath = logReferenceRootPath(for: commit) else {
        feedbackCenter.warning(
            "Rebase unavailable",
            detail: "The selected commit has no Git root.",
            nextStep: "Refresh Git Roots, then retry from the commit history."
        )
        return
    }

    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            guard let currentBranch = try rootRepo.branchList().first(where: \.isCurrent)?.name else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 1,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "Rebase onto a commit requires the selected root to be on a branch."
                    ]
                )
            }
            let containingBranches = Set(
                try rootRepo.commitContainingBranches(commitId: commit.id)
            )
            guard !containingBranches.contains(currentBranch) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 2,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "The selected commit is already contained in the current branch."
                    ]
                )
            }
            await MainActor.run {
                self.rebaseCurrentInRoot(rootPath: rootPath, onto: commit.id)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.warning(
                    "Rebase unavailable",
                    detail: errorMessage(error),
                    nextStep: "Select a commit outside the current branch and retry."
                )
            }
        }
    }
}

func handleContentViewAppearAndLoadRoots() {
    externalLogSessionDisposed = false
    handleContentViewAppear()
    credentialAuth.ensureInstalled()
    loadMultiRoots()
}

func externalLogTabIsAlive(_ tabID: UUID) -> Bool {
    guard externalLogWindow else { return true }
    guard !externalLogSessionDisposed else { return false }
    return externalLogUIManager?.isUIAlive(tabID) == true
}

func persistExternalLogTabs() {
    guard externalLogWindow, let persistenceKey = externalLogTabsPersistenceKey else { return }

    let snapshot = currentLogTabSnapshot()
    var tabs = logTabs
    if let index = tabs.firstIndex(where: { $0.id == snapshot.id }) {
        tabs[index] = snapshot
    } else {
        tabs.insert(snapshot, at: 0)
    }
    ExternalLogTabsStore.save(
        ExternalLogTabsState(tabs: tabs, activeTabID: snapshot.id),
        key: persistenceKey
    )
}

/// Mirrors IntelliJ's external VCS Log provider disposal. The external Log
/// window owns its root-scoped query/repository state; closing it must cancel
/// pending loads and release those repositories instead of leaving a watcher
/// or stale result alive after the window is gone.
func disposeExternalLogSession() {
    guard externalLogWindow, !externalLogSessionDisposed else { return }
    persistExternalLogTabs()
    externalLogSessionDisposed = true
    if let externalLogUIManager {
        externalLogUIManager.dispose()
    } else {
        externalLogProviderSession?.dispose()
    }
    logRefreshTask?.cancel()
    logRefreshTask = nil
    logLoadTask?.cancel()
    logLoadTask = nil
    logSignatureLoadTask?.cancel()
    logSignatureLoadTask = nil
    logCommandTask?.cancel()
    logCommandTask = nil
    logDetailLoadTask?.cancel()
    logDetailLoadTask = nil
    reflogDetailLoadTask?.cancel()
    reflogDetailLoadTask = nil
    reflogLoadTask?.cancel()
    reflogLoadTask = nil
    reflogLoadMoreTask?.cancel()
    reflogLoadMoreTask = nil
    compareLoadTask?.cancel()
    compareLoadTask = nil
    cancelBranchComparisonTasks()
    logShowMyTask?.cancel()
    logShowMyTask = nil
    repositoryChangeDeliveryTask?.cancel()
    repositoryChangeDeliveryTask = nil
    repositoryChangeBatch.removeAll()
    repositoryExternalVCSActionManager.removeAll()
    repositoryDirtyScopeManager.removeAll()
    repositoryDirtyFileManager.removeAll()
    logGeneration &+= 1
    logSignatureGeneration &+= 1
    logCommandGeneration &+= 1
    reflogGeneration &+= 1
    logAggregateRepositories.removeAll()
    logActiveRepo = nil
    reflogRootRepo = nil
    activeCompareRepo = nil
    projectRepo = nil
    multiRoots = []
    multiRootBranchSnapshots = []
    multiRootConflictGroups = []
}

func handleRepositoryChange(_ event: RepositoryChangeEvent) {
    guard !(externalLogWindow && externalLogSessionDisposed) else { return }
    let eventPath = URL(fileURLWithPath: event.repositoryPath)
        .standardizedFileURL.path
    // Invalidate at event delivery, before the 100 ms packed refresh debounce,
    // so an Apply Patch dialog opened during that window cannot read stale
    // filename membership.
    RebasedPatchFilenameIndexStore.invalidate(rootPath: eventPath)
    repositoryChangeBatch.insert(event)
    guard repositoryChangeDeliveryTask == nil else { return }
    repositoryChangeDeliveryTask = Task { @MainActor in
        do {
            try await Task.sleep(for: .milliseconds(100))
        } catch {
            self.repositoryChangeDeliveryTask = nil
            return
        }
        guard !Task.isCancelled else {
            self.repositoryChangeDeliveryTask = nil
            return
        }
        let events = self.repositoryChangeBatch.drain()
        self.repositoryChangeDeliveryTask = nil
        for event in events {
            processRepositoryChange(event)
        }
    }
}

private func processRepositoryChange(_ event: RepositoryChangeEvent) {
    let eventPath = URL(fileURLWithPath: event.repositoryPath)
        .standardizedFileURL.path
    repositoryDirtyScopeManager.register(
        repositoryPaths: autoFetchRootPaths + [eventPath]
    )
    // Keep the exact VFS records before RootDirtySet-style compaction. The
    // refresh scope may become a directory or full-root scan, but actions and
    // lifecycle completion still need the original file/rename endpoints.
    repositoryDirtyFileManager.mark(
        repositoryPath: eventPath,
        dirtyPaths: event.dirtyPaths
    )
    let primaryPath = repo?.workdir().map {
        URL(fileURLWithPath: $0).standardizedFileURL.path
    }
    let eventRepo: Repository?
    if primaryPath == eventPath {
        eventRepo = repo
    } else {
        eventRepo = try? openRepository(path: eventPath)
    }
    var affectedRootPaths = [eventPath]
    if let eventRepo,
       let workdir = eventRepo.workdir() {
        let scope = repositoryDirtyScope(
            workdir: workdir,
            gitDir: eventRepo.gitDir(),
            dirtyPaths: event.dirtyPaths
        )
        affectedRootPaths = repositoryDirtyScopeManager.mark(
            repositoryPath: eventPath,
            scope: scope,
            changeScope: event.scopes,
            dirtyPaths: event.dirtyPaths
        )
    } else {
        // Keep the event in the same packed lifecycle even if the repository
        // disappeared while the watcher was delivering it. A later root
        // discovery will reconcile the full state instead of dropping the
        // invalidation because the Repository object is temporarily absent.
        affectedRootPaths = repositoryDirtyScopeManager.markEverything(
            repositoryPath: eventPath,
            changeScope: event.scopes,
            dirtyPaths: event.dirtyPaths
        )
    }

    let hasExternalVCSActionEvents = event.scopes.contains(.worktree)
        && event.dirtyPaths.contains {
            $0.kind == .created || $0.kind == .removed || $0.kind == .renamed
        }
    if hasExternalVCSActionEvents, eventRepo != nil {
        repositoryExternalVCSActionManager.enqueue(event)
    }

    for rootPath in affectedRootPaths where rootPath != eventPath {
        // GitVcsDirtyScope marks every nested root dirty when a recursive
        // parent event covers it. The exact file ledger still needs a record
        // for that synthetic full-root refresh.
        repositoryDirtyFileManager.mark(
            repositoryPath: rootPath,
            dirtyPaths: [
                RepositoryDirtyPath(
                    path: rootPath,
                    isDirectory: true,
                    kind: .modified
                )
            ]
        )
    }

    // Do not start a second refresh while the packed scope is being consumed.
    // retrieveScopes() returns an empty batch until changesProcessed() is
    // called, so events arriving during the current refresh remain pending.
    startPendingRepositoryDirtyScopes()
}

/// Consumes one IntelliJ-style packed dirty-scope batch. The scope manager is
/// deliberately the source of truth here; the watcher/event batch only
/// schedules this function and never directly acknowledges a dirty path.
private func startPendingRepositoryDirtyScopes() {
    let records = repositoryDirtyScopeManager.retrieveScopes()
    guard !records.isEmpty else { return }

    for record in records {
        let refreshEvent = record.event
        let dirtyFileTicket = repositoryDirtyFileManager.beginProcessing(
            repositoryPath: record.repositoryPath
        )
        let shouldStartExternalVCSActions = refreshEvent.scopes.contains(.worktree)
            && refreshEvent.dirtyPaths.contains {
                $0.kind == .created || $0.kind == .removed || $0.kind == .renamed
            }
        let eventRepo: Repository?
        let primaryPath = repo?.workdir().map {
            URL(fileURLWithPath: $0).standardizedFileURL.path
        }
        if primaryPath == record.repositoryPath {
            eventRepo = repo
        } else {
            eventRepo = try? openRepository(path: record.repositoryPath)
        }

        refreshRepositoryChange(refreshEvent) {
            self.repositoryDirtyScopeManager.changesProcessed(
                repositoryPath: record.repositoryPath
            )
            if let dirtyFileTicket {
                self.repositoryDirtyFileManager.changesProcessed(dirtyFileTicket)
            }
            if shouldStartExternalVCSActions, let eventRepo {
                self.startNextExternalVCSAction(repo: eventRepo)
            }
            // A new watcher event may have arrived while this batch was in
            // progress. Only now is the next packed scope eligible.
            self.startPendingRepositoryDirtyScopes()
        }
    }
}

private func refreshRepositoryChange(
    _ event: RepositoryChangeEvent,
    onCompleted: (() -> Void)? = nil
) {
    let primaryPath = repo?.workdir().map {
        URL(fileURLWithPath: $0).standardizedFileURL.path
    }
    let eventPath = URL(fileURLWithPath: event.repositoryPath)
        .standardizedFileURL.path
    if primaryPath == eventPath {
        refreshAll(
            showFeedback: false,
            changeScope: event.scopes,
            dirtyPaths: event.dirtyPaths,
            onCompleted: onCompleted
        )
        if event.scopes.contains(.gitMetadata) {
            loadRepoData(includeComparisons: false)
            loadMultiRoots()
        }
    } else {
        // A non-primary root has no dedicated Commit workspace state, but it
        // still owns Branches, Roots, conflicts, and aggregate Log rows.
        let shouldRefreshSecondaryShelf = shouldRefreshSecondaryShelfSnapshot(
            eventRootPath: eventPath,
            activeRootPath: activeShelfRootPath,
            primaryRootPath: primaryShelfRootPath,
            scopes: event.scopes
        )
        loadMultiRoots {
            if self.logViewMode == .command || self.isLogAggregate {
                self.reloadLogView()
            }
            if shouldRefreshSecondaryShelf {
                self.reloadSecondaryShelfSnapshot(rootPath: eventPath)
            }
            onCompleted?()
        }
    }
}

/// Reload the selected secondary root's complete Shelf state after an
/// external Git metadata change. The generation guard prevents an older VFS
/// event from replacing a newer root selection or a newer refresh result.
private func reloadSecondaryShelfSnapshot(rootPath: String) {
    let normalizedRootPath = canonicalExternalLogPath(rootPath)
    guard activeShelfRootPath == normalizedRootPath,
          !shelfRootSelectionIsPrimary(
              selectedRootPath: normalizedRootPath,
              primaryRootPath: primaryShelfRootPath
          ) else { return }

    shelfRootLoadGeneration += 1
    let generation = shelfRootLoadGeneration
    shelfRootLoading = true
    Task.detached(priority: .utility) {
        do {
            let rootRepo = try openRepository(path: normalizedRootPath)
            let rootShelves = try rootRepo.shelveList()
            let rootDeletedShelves = (try? rootRepo.shelveDeletedList()) ?? []
            let rootChangeLists = (try? rootRepo.changelistList()) ?? []
            await MainActor.run {
                guard self.shelfRootLoadGeneration == generation,
                      self.activeShelfRootPath == normalizedRootPath else { return }
                self.shelfRootRepository = rootRepo
                self.shelfRootSnapshots[normalizedRootPath] = ShelfRootSnapshot(
                    rootPath: normalizedRootPath,
                    shelves: rootShelves,
                    deletedShelves: rootDeletedShelves,
                    changeLists: rootChangeLists
                )
                self.shelfRootError = nil
                self.shelfRootLoading = false
            }
        } catch {
            await MainActor.run {
                guard self.shelfRootLoadGeneration == generation,
                      self.activeShelfRootPath == normalizedRootPath else { return }
                self.shelfRootError = "Refresh Shelf for "
                    + normalizedRootPath
                    + " failed: "
                    + errorMessage(error)
                self.shelfRootLoading = false
            }
        }
    }
}

private func startNextExternalVCSAction(repo: Repository) {
    guard let rawWorkdir = repo.workdir() else { return }
    let workdir = URL(fileURLWithPath: rawWorkdir).standardizedFileURL.path
    guard let ticket = repositoryExternalVCSActionManager.begin(
        repositoryPath: workdir
    ) else { return }
    let event = ticket.event
    let pathspecs: Set<String> = Set(
        event.dirtyPaths.flatMap { dirtyPath -> [String] in
            guard dirtyPath.kind == .created || dirtyPath.kind == .removed
                || dirtyPath.kind == .renamed else { return [] }
            let endpoints = [dirtyPath.path] + (dirtyPath.oldPath.map { [$0] } ?? [])
            return endpoints
                .compactMap {
                    repositoryRelativeWorktreeEventPath(
                        workdir: workdir,
                        path: $0
                    )
                }
        }
    )
    guard !pathspecs.isEmpty else {
        finishExternalVCSAction(ticket, repo: repo)
        return
    }

    Task.detached(priority: .utility) {
        do {
            let requiresRenameReconciliation = event.dirtyPaths.contains {
                $0.kind == .renamed && $0.oldPath == nil
            }
            let status = requiresRenameReconciliation
                ? try repo.status()
                : try repo.statusPaths(paths: pathspecs.sorted())
            let contentRenameMatches: [RepositoryExternalVCSMove]
            if requiresRenameReconciliation {
                let exactMatches = repositoryUniqueContentRenameMatches(
                    repo: repo,
                    event: event,
                    workdir: workdir,
                    status: status
                )
                let modifiedMatches = repositoryModifiedContentRenameMatches(
                    repo: repo,
                    event: event,
                    workdir: workdir,
                    status: status,
                    reservedMoves: exactMatches
                )
                contentRenameMatches = repositoryNonConflictingExternalVCSMoves(
                    exactMatches + modifiedMatches
                )
            } else {
                contentRenameMatches = []
            }
            let actionPaths = repositoryExternalVCSActionPaths(
                event: event,
                workdir: workdir,
                status: status,
                contentRenameMatches: contentRenameMatches
            )
            guard !actionPaths.isEmpty else {
                await MainActor.run {
                    self.finishExternalVCSAction(ticket, repo: repo)
                }
                return
            }
            await MainActor.run {
                self.confirmAndPerformExternalVCSActions(
                    actionPaths,
                    event: event,
                    repo: repo,
                    ticket: ticket
                )
            }
        } catch {
            DiagnosticsLogger.shared.record(
                level: .error,
                operation: "vfs-listener",
                repositoryPath: workdir,
                code: "status-failed"
            )
            await MainActor.run {
                self.finishExternalVCSAction(ticket, repo: repo)
            }
        }
    }
}

private func finishExternalVCSAction(
    _ ticket: RepositoryExternalVCSActionTicket,
    repo: Repository
) {
    guard repositoryExternalVCSActionManager.finish(ticket) else { return }
    startNextExternalVCSAction(repo: repo)
}

private func confirmAndPerformExternalVCSActions(
    _ paths: RepositoryExternalVCSActionPaths,
    event: RepositoryChangeEvent,
    repo: Repository,
    ticket: RepositoryExternalVCSActionTicket
) {
    var addPaths: [String] = []
    var stageAddPaths: [String] = []
    var removePaths: [String] = []
    let forceMoves = paths.forceMove
    let addAction = GitVFSListenerSettings.addAction()
    let removeAction = GitVFSListenerSettings.removeAction()
    let selectedReviewMoves: [RepositoryExternalVCSMove]
    if !paths.reviewMoves.isEmpty,
       addAction != .ignore || removeAction != .ignore {
        let selectedMoves = selectExternalVCSMoves(
            title: "Review ambiguous Git moves",
            actionTitle: "Apply selected moves",
            moves: paths.reviewMoves
        )
        selectedReviewMoves = repositoryNonConflictingExternalVCSMoves(selectedMoves)
    } else {
        selectedReviewMoves = []
    }
    let reviewAddPaths = addAction == .ignore
        ? []
        : selectedReviewMoves.map(\.newPath)
    let reviewRemovePaths = removeAction == .ignore
        ? []
        : selectedReviewMoves.map(\.oldPath)

    if !paths.add.isEmpty || !paths.stageAdd.isEmpty || !reviewAddPaths.isEmpty {
        let allAddPaths = paths.add + paths.stageAdd
        switch addAction {
        case .perform:
            addPaths = paths.add
            stageAddPaths = paths.stageAdd
        case .ask:
            let selected = Set(selectExternalVCSActionPaths(
                title: "Add files to Git?",
                actionTitle: "Add to Git",
                paths: allAddPaths
            ))
            addPaths = repositorySelectedExternalVCSPaths(
                paths: paths.add,
                selected: selected
            )
            stageAddPaths = repositorySelectedExternalVCSPaths(
                paths: paths.stageAdd,
                selected: selected
            )
        case .ignore:
            break
        }
        addPaths.append(contentsOf: reviewAddPaths)
    }
    if !paths.remove.isEmpty || !reviewRemovePaths.isEmpty {
        switch removeAction {
        case .perform:
            removePaths = paths.remove
        case .ask:
            let selected = Set(selectExternalVCSActionPaths(
                title: "Remove files from Git?",
                actionTitle: "Remove from Git",
                paths: paths.remove
            ))
            removePaths = repositorySelectedExternalVCSPaths(
                paths: paths.remove,
                selected: selected
            )
        case .ignore:
            break
        }
        removePaths.append(contentsOf: reviewRemovePaths)
    }
    guard !addPaths.isEmpty || !stageAddPaths.isEmpty || !removePaths.isEmpty || !forceMoves.isEmpty else {
        finishExternalVCSAction(ticket, repo: repo)
        return
    }

    let rootPath = URL(fileURLWithPath: event.repositoryPath)
        .standardizedFileURL
        .path
    let retryAction = RepositoryExternalVCSAction(
        addPaths: addPaths,
        stageAddPaths: stageAddPaths,
        removePaths: removePaths,
        forceMoves: forceMoves
    )
    let notificationID = externalVCSActionNotificationID(repositoryPath: rootPath)
    beginFeedbackOperation("Update Git files", notificationID: notificationID)
    Task.detached(priority: .userInitiated) { [addPaths, stageAddPaths, removePaths] in
        do {
            let completedDetail = try runRepositoryExternalVCSActions(
                repo: repo,
                addPaths: addPaths,
                stageAddPaths: stageAddPaths,
                removePaths: removePaths,
                forceMoves: forceMoves
            )
            await MainActor.run {
                self.refreshRepositoryChange(event) {
                    self.finishExternalVCSAction(ticket, repo: repo)
                }
                self.feedbackCenter.success(
                    "External Git files updated",
                    detail: completedDetail,
                    notificationID: notificationID
                )
            }
        } catch {
            await MainActor.run {
                self.refreshRepositoryChange(event) {
                    self.finishExternalVCSAction(ticket, repo: repo)
                }
                self.feedbackCenter.error(
                    "External Git file action failed",
                    detail: errorMessage(error),
                    nextStep: "Review the affected paths, then retry the external Git action.",
                    additionalActions: [
                        self.externalVCSRetryFeedbackAction(
                            rootPath: rootPath,
                            action: retryAction
                        )
                    ],
                    notificationID: notificationID
                )
            }
        }
    }
}

private func externalVCSActionRefreshEvent(
    rootPath: String,
    action: RepositoryExternalVCSAction
) -> RepositoryChangeEvent {
    let rootURL = URL(fileURLWithPath: rootPath).standardizedFileURL
    var dirtyPaths: [RepositoryDirtyPath] = []
    var seen = Set<String>()

    func absolutePath(_ relativePath: String) -> String {
        rootURL.appendingPathComponent(relativePath).standardizedFileURL.path
    }

    func appendPath(_ relativePath: String, kind: RepositoryDirtyChangeKind) {
        let path = absolutePath(relativePath)
        guard seen.insert("\(kind.rawValue):\(path)").inserted else { return }
        dirtyPaths.append(
            RepositoryDirtyPath(path: path, isDirectory: false, kind: kind)
        )
    }

    action.addPaths.forEach { appendPath($0, kind: .created) }
    action.stageAddPaths.forEach { appendPath($0, kind: .created) }
    action.removePaths.forEach { appendPath($0, kind: .removed) }
    for move in action.forceMoves {
        let newPath = absolutePath(move.newPath)
        guard seen.insert("renamed:\(newPath)").inserted else { continue }
        dirtyPaths.append(
            RepositoryDirtyPath(
                path: newPath,
                isDirectory: false,
                kind: .renamed,
                oldPath: absolutePath(move.oldPath)
            )
        )
    }
    return RepositoryChangeEvent(
        repositoryPath: rootURL.path,
        scopes: .worktree,
        dirtyPaths: dirtyPaths
    )
}

private func externalVCSRetryFeedbackAction(
        rootPath: String,
        action: RepositoryExternalVCSAction
    ) -> FeedbackAction {
        let request = ArborVCSActionRequest(
            kind: .retryExternalVCSAction,
            projectPath: projectPath,
            rootPath: rootPath,
            shelfName: "",
            externalVCSAction: action
        )
        return FeedbackAction(
            id: "retry-external-vcs:\(rootPath)",
            title: "Retry External Git Action",
            semanticAction: request
        ) {
            self.handleVCSActionRequest(request)
        }
    }

private func retryExternalVCSAction(
        rootPath: String,
        action: RepositoryExternalVCSAction
    ) {
        guard repositoryExternalVCSActionIsSafe(action), !action.isEmpty,
              let repo,
              let currentRoot = repo.workdir(),
              URL(fileURLWithPath: currentRoot).standardizedFileURL.path
                  == URL(fileURLWithPath: rootPath).standardizedFileURL.path else {
            feedbackCenter.error(
                "External Git retry unavailable",
                detail: "The saved paths are no longer a safe repository-relative action.",
                nextStep: "Refresh the repository and retry the file action from the current changes."
            )
            return
        }

        let normalizedRoot = URL(fileURLWithPath: rootPath)
            .standardizedFileURL
            .path
        let notificationID = externalVCSActionNotificationID(
            repositoryPath: normalizedRoot
        )
        beginFeedbackOperation("Update Git files", notificationID: notificationID)
        Task.detached(priority: .userInitiated) {
            do {
                let detail = try runRepositoryExternalVCSActions(
                    repo: repo,
                    addPaths: action.addPaths,
                    stageAddPaths: action.stageAddPaths,
                    removePaths: action.removePaths,
                    forceMoves: action.forceMoves
                )
                await MainActor.run {
                    self.refreshRepositoryChange(
                        externalVCSActionRefreshEvent(
                            rootPath: normalizedRoot,
                            action: action
                        )
                    )
                    self.feedbackCenter.success(
                        "External Git files updated",
                        detail: detail,
                        notificationID: notificationID
                    )
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "External Git file retry failed",
                        detail: errorMessage(error),
                        nextStep: "Review the affected paths and retry again after fixing the cause.",
                        additionalActions: [
                            self.externalVCSRetryFeedbackAction(
                                rootPath: normalizedRoot,
                                action: action
                            )
                        ],
                        notificationID: notificationID
                    )
                }
            }
        }
}

private func selectExternalVCSActionPaths(
    title: String,
    actionTitle: String,
    paths: [String]
) -> [String] {
    var uniquePaths: [String] = []
    for path in paths where !uniquePaths.contains(path) {
        uniquePaths.append(path)
    }
    let paths = uniquePaths
    guard !paths.isEmpty else { return [] }

    let alert = NSAlert()
    alert.messageText = title
    alert.informativeText = "Select the paths to process."
    alert.alertStyle = .informational
    alert.addButton(withTitle: actionTitle)
    alert.addButton(withTitle: "Skip")

    let rowHeight: CGFloat = 22
    let width: CGFloat = 440
    let contentHeight = max(rowHeight, CGFloat(paths.count) * rowHeight)
    let visibleHeight = min(contentHeight, 280)
    let checkboxes = paths.map { path -> NSButton in
        let button = NSButton(checkboxWithTitle: path, target: nil, action: nil)
        button.state = .on
        button.toolTip = path
        button.lineBreakMode = .byTruncatingMiddle
        return button
    }
    let stack = NSStackView(views: checkboxes)
    stack.orientation = .vertical
    stack.alignment = .leading
    stack.spacing = 2
    stack.frame = NSRect(
        x: 0,
        y: 0,
        width: width - 20,
        height: contentHeight
    )

    let scrollView = NSScrollView(
        frame: NSRect(x: 0, y: 0, width: width, height: visibleHeight)
    )
    scrollView.hasVerticalScroller = contentHeight > visibleHeight
    scrollView.autohidesScrollers = true
    scrollView.drawsBackground = false
    scrollView.documentView = stack
    alert.accessoryView = scrollView

    guard alert.runModal() == .alertFirstButtonReturn else { return [] }
    return zip(paths, checkboxes).compactMap { path, checkbox in
        checkbox.state == .on ? path : nil
    }
}

/// Presents ambiguous directory rename candidates as one choice per new
/// endpoint. Independent checkboxes are unsafe here because several old paths
/// can share the same unchanged suffix; a popup makes the one-to-one rule
/// visible and defaults ambiguous groups to Skip.
private func selectExternalVCSMoves(
    title: String,
    actionTitle: String,
    moves: [RepositoryExternalVCSMove]
) -> [RepositoryExternalVCSMove] {
    let groups = Dictionary(grouping: moves, by: \.newPath)
        .map { newPath, candidates in
            (newPath: newPath, candidates: candidates.sorted { $0.oldPath < $1.oldPath })
        }
        .sorted { $0.newPath < $1.newPath }
    guard !groups.isEmpty else { return [] }

    let alert = NSAlert()
    alert.messageText = title
    alert.informativeText = "Choose at most one old path for each new path. Ambiguous matches default to Skip."
    alert.alertStyle = .informational
    alert.addButton(withTitle: actionTitle)
    alert.addButton(withTitle: "Skip")

    let width: CGFloat = 560
    let rowHeight: CGFloat = 28
    let contentHeight = max(rowHeight, CGFloat(groups.count) * rowHeight)
    let visibleHeight = min(contentHeight, 320)

    enum MoveControl {
        case checkbox(RepositoryExternalVCSMove, NSButton)
        case popup([RepositoryExternalVCSMove], NSPopUpButton)
    }
    var controls: [MoveControl] = []
    var rowViews: [NSView] = []
    for group in groups {
        let row = NSStackView()
        row.orientation = .horizontal
        row.alignment = .centerY
        row.spacing = 8

        let newLabel = NSTextField(labelWithString: group.newPath)
        newLabel.lineBreakMode = .byTruncatingMiddle
        newLabel.toolTip = group.newPath
        newLabel.setContentHuggingPriority(.defaultLow, for: .horizontal)
        newLabel.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        row.addArrangedSubview(newLabel)

        let arrow = NSTextField(labelWithString: "←")
        arrow.textColor = .secondaryLabelColor
        row.addArrangedSubview(arrow)

        if group.candidates.count == 1 {
            let checkbox = NSButton(checkboxWithTitle: group.candidates[0].oldPath, target: nil, action: nil)
            checkbox.state = .on
            checkbox.toolTip = group.candidates[0].oldPath
            checkbox.lineBreakMode = .byTruncatingMiddle
            checkbox.setContentHuggingPriority(.defaultLow, for: .horizontal)
            checkbox.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
            row.addArrangedSubview(checkbox)
            controls.append(.checkbox(group.candidates[0], checkbox))
        } else {
            let popup = NSPopUpButton(frame: .zero, pullsDown: false)
            popup.addItem(withTitle: "Skip")
            popup.addItems(withTitles: group.candidates.map { $0.oldPath })
            popup.selectItem(at: 0)
            popup.setContentHuggingPriority(.defaultHigh, for: .horizontal)
            popup.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
            row.addArrangedSubview(popup)
            controls.append(.popup(group.candidates, popup))
        }
        row.frame = NSRect(x: 0, y: 0, width: width - 20, height: rowHeight)
        rowViews.append(row)
    }

    let stack = NSStackView(views: rowViews)
    stack.orientation = .vertical
    stack.alignment = .leading
    stack.spacing = 4
    stack.frame = NSRect(x: 0, y: 0, width: width - 20, height: contentHeight)

    let scrollView = NSScrollView(
        frame: NSRect(x: 0, y: 0, width: width, height: visibleHeight)
    )
    scrollView.hasVerticalScroller = contentHeight > visibleHeight
    scrollView.autohidesScrollers = true
    scrollView.drawsBackground = false
    scrollView.documentView = stack
    alert.accessoryView = scrollView

    guard alert.runModal() == .alertFirstButtonReturn else { return [] }

    var selected: [RepositoryExternalVCSMove] = []
    for control in controls {
        switch control {
        case let .checkbox(move, checkbox):
            if checkbox.state == .on { selected.append(move) }
        case let .popup(candidates, popup):
            let selectedIndex = popup.indexOfSelectedItem - 1
            guard candidates.indices.contains(selectedIndex) else { continue }
            selected.append(candidates[selectedIndex])
        }
    }
    return repositoryNonConflictingExternalVCSMoves(selected)
}

func handleArborVCSActionNotification(_ notification: Notification) {
    if let request = notification.object as? ArborVCSActionRequest {
        handleVCSActionRequest(request)
        return
    }
    guard let rawValue = notification.object as? String,
          let action = ArborVCSAction(rawValue: rawValue) else { return }
    switch action {
    case .searchEverywhere:
        showSearchEverywhere = true
    case .quickActions:
        presentVCSQuickActionsPanel()
    case .update:
        guard isArborVCSActionEnabled(.update, in: vcsActionContext) else { return }
        requestUpdateProject()
    case .reset:
        guard isArborVCSActionEnabled(.reset, in: vcsActionContext) else { return }
        beginHeadResetDialog()
    case .resetToRemoteBranch:
        resetCurrentBranchToRemote()
    case .commit:
        toolWindowMode = .commit
        toolWindowExpanded = true
    case .commitAndPush:
        toolWindowMode = .commit
        toolWindowExpanded = true
        beginCommitAndPush()
    case .push:
        beginPushDialog()
    case .fetch:
        guard isArborVCSActionEnabled(.fetch, in: vcsActionContext) else { return }
        doFetch(nil)
    case .fetchAll:
        guard isArborVCSActionEnabled(.fetchAll, in: vcsActionContext) else { return }
        doFetchAll()
    case .retryAutoFetch:
        autoFetchRunGeneration &+= 1
    case .enableAutoFetch:
        if let projectPath {
            GitIncomingCheckStrategySettings.saveProjectStrategy(.fetch, for: projectPath)
            projectIncomingCheckStrategyRaw = GitIncomingCheckStrategy.fetch.rawValue
        } else {
            incomingCheckStrategyRaw = GitIncomingCheckStrategy.fetch.rawValue
            gitAutoFetch = true
        }
    case .disableAutoFetchSuggestion:
        GitIncomingCheckStrategySettings.setSuggestionDisabled(true, for: projectPath)
        GitIncomingCheckStrategySettings.setSuggestionCount(3, for: projectPath)
    case .fetchPrune:
        guard isArborVCSActionEnabled(.fetchPrune, in: vcsActionContext) else { return }
        doFetchPrune()
    case .fetchUnshallow:
        guard isArborVCSActionEnabled(.fetchUnshallow, in: vcsActionContext) else { return }
        doFetchUnshallow()
    case .pull:
        presentPullDialog(rebase: nil)
    case .pullMerge:
        presentPullDialog(rebase: false)
    case .pullRebase:
        presentPullDialog(rebase: true)
    case .showStagingArea:
        guard isArborVCSActionEnabled(.showStagingArea, in: vcsActionContext) else { return }
        toolWindowMode = .commit
        toolWindowExpanded = true
        isShelfWorkspaceTabActive = false
    case .showShelf:
        guard isArborVCSActionEnabled(.showShelf, in: vcsActionContext) else { return }
        toolWindowMode = .commit
        toolWindowExpanded = true
        isShelfWorkspaceTabActive = true
        shelfTabRequestID &+= 1
    case .showStash:
        guard isArborVCSActionEnabled(.showStash, in: vcsActionContext) else { return }
        toolWindowMode = .commit
        toolWindowExpanded = true
        isShelfWorkspaceTabActive = true
        shelfTabRequestID &+= 1
    case .revertSelectedChanges:
        guard isArborVCSActionEnabled(.revertSelectedChanges, in: vcsActionContext),
              let path = vcsActionContext.selectedLocalChangePath else { return }
        restoreFileFromHead(
            path,
            prompt: "Revert selected changes?",
            confirmTitle: "Revert",
            feedbackTitle: "Changes reverted"
        )
    case .branches:
        loadRepoData()
        showBranchesPopover = true
    case .merge:
        guard isArborVCSActionEnabled(.merge, in: vcsActionContext) else { return }
        openMergeDialog(nil)
    case .rebase:
        guard isArborVCSActionEnabled(.rebase, in: vcsActionContext) else { return }
        openRebaseDialog(nil)
    case .stash:
        presentStashDialog()
    case .unstash:
        presentUnstashDialog()
    case .shelve:
        showShelveDialog = true
    case .applyPatch:
        applyPatchFromFile()
    case .applyPatchFromClipboard:
        applyPatchFromClipboard()
    case .newBranch:
        guard isArborVCSActionEnabled(.newBranch, in: vcsActionContext) else { return }
        presentNewBranchDialog()
    case .newTag:
        beginNewTagDialog()
    case .configureRemotes:
        guard isArborVCSActionEnabled(.configureRemotes, in: vcsActionContext) else { return }
        beginConfigureRemotes()
    case .worktrees:
        toolWindowMode = .operations
        operationsViewMode = .worktrees
        toolWindowExpanded = true
        loadWorktrees()
    case .stageTracked:
        stageAll()
    case .stageAll:
        stageEverything()
    case .copyCurrentBranchName:
        guard branches.contains(where: { $0.isCurrent }) else { return }
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(currentBranchName, forType: .string)
        feedbackCenter.success("Copied branch name", detail: currentBranchName)
    case .resolveConflicts:
        openFirstConflictFromAction()
    case .revertResolved:
        guard isArborVCSActionEnabled(.revertResolved, in: vcsActionContext),
              let path = vcsActionContext.selectedResolvedConflictPath else { return }
        revertResolvedPath(path)
    case .fileCheckin:
        guard isArborVCSActionEnabled(.fileCheckin, in: vcsActionContext),
              let file = vcsActionContext.selectedFileAction else { return }
        beginFileCheckin(file.path)
    case .fileAdd:
        guard isArborVCSActionEnabled(.fileAdd, in: vcsActionContext),
              let file = vcsActionContext.selectedFileAction else { return }
        stageSelectedFileFromFileAction(file)
    case .fileAnnotate:
        guard isArborVCSActionEnabled(.fileAnnotate, in: vcsActionContext),
              let file = vcsActionContext.selectedFileAction else { return }
        annotateProjectFile(file.path)
    case .fileCompareSameVersion:
        guard isArborVCSActionEnabled(.fileCompareSameVersion, in: vcsActionContext),
              let file = vcsActionContext.selectedFileAction else { return }
        openFileSameVersionComparison(path: file.path)
    case .fileCompareSelectedRevision:
        guard isArborVCSActionEnabled(.fileCompareSelectedRevision, in: vcsActionContext),
              let file = vcsActionContext.selectedFileAction else { return }
        openFileSelectedRevisionComparison(path: file.path, isDirectory: file.isDirectory)
    case .fileCompareWithBranch:
        guard isArborVCSActionEnabled(.fileCompareWithBranch, in: vcsActionContext),
              let file = vcsActionContext.selectedFileAction else { return }
        openFileReferenceComparison(path: file.path, isDirectory: file.isDirectory)
    case .fileHistory:
        guard isArborVCSActionEnabled(.fileHistory, in: vcsActionContext),
              let file = vcsActionContext.selectedFileAction,
              !file.isDirectory else { return }
        showFileHistory(file.rootRelativePath, rootPath: file.owningRootPath)
    case .showLog:
        toolWindowMode = .log
        toolWindowExpanded = true
        projectPanelExpanded = false
        selection = nil
        fileSelection = nil
        selectionModePath = nil
        logViewMode = .graph
        loadLog()
    case .showExternalLog:
        // ProjectCommands routes this action directly through openWindow so
        // it targets the focused project's path. Keep the notification
        // handler exhaustive for quick-action/request decoding without
        // opening one external window per subscribed ContentView.
        break
    case .showOperations:
        toolWindowMode = .operations
        operationsViewMode = .history
        toolWindowExpanded = true
    case .showGitRoots:
        toolWindowMode = .operations
        operationsViewMode = .roots
        toolWindowExpanded = true
        loadMultiRoots()
    case .showGitConsole:
        toolWindowMode = .operations
        operationsViewMode = .console
        toolWindowExpanded = true
    case .refresh:
        refreshAll()
    }
}

func handleContentViewAppear() {
    DiagnosticsLogger.shared.record(
        operation: "app",
        repositoryPath: projectPath,
        code: projectPath == nil ? "launch-no-project" : "launch-with-project"
    )
    // Rebased keeps the Log workspace paired directly with Commit/Stash. The
    // Project surface is opened from the activity rail, so it must not steal
    // vertical space from the left Git workspace on launch.
    if toolWindowMode == .log {
        projectPanelExpanded = false
    }
    beforeCommitCommands = loadBeforeCommitCommands()
    loadMergeDialogSettings(for: projectPath)
    loadRebaseDialogSettings(for: projectPath)
    projectIncomingCheckStrategyRaw = GitIncomingCheckStrategySettings.projectRawValue(for: projectPath)
    projectFetchTagsMode = GitFetchTagsSettings.mode(for: projectPath)
    projectUpdateMethod = GitUpdateMethodSettings.method(for: projectPath)
    logBranchesSelectionActionRaw = GitBranchesPopupSettings.stringValue(
        GitBranchesPopupSettings.logSelectionActionKey,
        for: projectPath
    )
    logBranchesGroupByDirectory = GitBranchesPopupSettings.value(
        GitBranchesPopupSettings.groupByDirectoryKey,
        for: projectPath
    )
    logBranchesGroupByRepository = GitBranchesPopupSettings.value(
        GitBranchesPopupSettings.groupByRepositoryKey,
        for: projectPath
    )
    loadProjectProtectedBranchSettings(for: projectPath)
    identityAuthorName = UserDefaults.standard.string(forKey: "arbor.identity.authorName") ?? ""
    identityAuthorEmail = UserDefaults.standard.string(forKey: "arbor.identity.authorEmail") ?? ""
    identityRecentAuthors = GitCommitAuthorHistorySettings.authors(for: projectPath)
    identityCommitterName = UserDefaults.standard.string(forKey: "arbor.identity.committerName") ?? ""
    identityCommitterEmail = UserDefaults.standard.string(forKey: "arbor.identity.committerEmail") ?? ""
    identitySignOff = GitSignOffCommitSettings.value(for: projectPath)
    identityCoAuthors = UserDefaults.standard.string(forKey: "arbor.identity.coAuthors") ?? ""
    // WindowGroup/AppKit restoration can materialize ContentView with its
    // initial @State before the recent-project value has been restored. Do the
    // same recovery at the lifecycle boundary as well, otherwise the shell
    // remains on Arbor's welcome page even though the recent-project list
    // contains a valid repository (the screenshot state that looks unlike
    // rebased's project workspace).
    if projectRepo == nil {
        let recoveredPath = projectPath ?? ContentView.recentProjectPath()
        if projectPath == nil, let recoveredPath {
            self.projectPath = recoveredPath
            self.path = recoveredPath
        }
        guard let recoveredPath else { return }
        DiagnosticsLogger.shared.record(
            operation: "project",
            repositoryPath: recoveredPath,
            code: "requested"
        )
        openProjectPath(recoveredPath)
    }
}

func loadProjectProtectedBranchSettings(for projectPath: String?) {
    projectProtectedBranchPatterns = GitProtectedBranchRules.projectRawValue(for: projectPath)
    projectProtectedBranchSynchronize = GitProtectedBranchRules.projectSynchronizeValue(for: projectPath)
}

/// Register the persisted project Git executable for the roots currently
/// known by this window. The Rust engine resolves the longest matching root
/// for every system-Git command, while the application-level executable stays
/// the fallback for projects without an override.
func applyProjectGitExecutableOverride(for projectPath: String, roots: [String]) {
    guard let override = GitExecutableSettings.projectOverride(for: projectPath) else {
        clearProjectGitExecutable(projectPath: projectPath)
        return
    }
    let registeredRoots = GitExecutableSettings.registeredRoots(
        projectPath: projectPath,
        repositoryRoot: nil,
        discoveredRoots: roots
    )
    do {
        _ = try setProjectGitExecutable(
            projectPath: projectPath,
            rootPaths: registeredRoots,
            path: override
        )
    } catch {
        DiagnosticsLogger.shared.record(
            operation: "settings",
            repositoryPath: projectPath,
            code: "project-git-executable-invalid"
        )
    }
}

nonisolated private func branchComparisonMap(repo: Repository) -> [String: BranchCompare] {
    guard let comparisons = try? repo.branchCompareAll() else { return [:] }
    return Dictionary(uniqueKeysWithValues: comparisons.map {
        ($0.name, BranchCompare(ahead: $0.ahead, behind: $0.behind))
    })
}

func beginFeedbackOperation(
    _ name: String,
    cancelHandle: GitCancelHandle? = nil,
    notificationID: String? = nil,
    preserveResultItems: Bool = false
) {
    feedbackCenter.begin(
        name,
        notificationID: notificationID,
        preserveResultItems: preserveResultItems,
        onCancel: cancelHandle.map { handle in
            { handle.cancel() }
        }
    )
}

/// Present the full IntelliJ-style Smart/Force/Cancel decision instead of
/// reducing an overwrite detector to a one-line retry toast.
func presentSmartOperationDecision(
    operationTitle: String,
    paths: [String],
    detail: String? = nil,
    smartButtonTitle: String,
    forceButtonTitle: String? = nil,
    onSmart: @escaping () -> Void,
    onForce: (() -> Void)? = nil
) {
    smartOperationRequest = SmartOperationRequest(
        operationTitle: operationTitle,
        smartButtonTitle: smartButtonTitle,
        forceButtonTitle: forceButtonTitle,
        paths: paths,
        detail: detail,
        localChangesSavePolicy: GitLocalChangesSavePolicySettings.choice(for: projectPath),
        onSmart: onSmart,
        onForce: onForce
    )
}

func runGitConsole(command: String, args: [String]) {
    guard let repo else { return }
    beginFeedbackOperation("Git Console")
    Task.detached(priority: .userInitiated) {
        do {
            let result = try repo.runGitCommand(command: command, args: args)
            await MainActor.run {
                self.consoleResult = result
                self.feedbackCenter.recordGitCommand(result)
                if result.exitCode == 0 {
                    self.feedbackCenter.success("Git command completed", detail: result.command)
                } else {
                    self.feedbackCenter.error(
                        "Git command failed",
                        detail: result.stderr.isEmpty ? result.stdout : result.stderr,
                        nextStep: "Review stderr in Git Console and retry after fixing the command."
                    )
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Git Console failed", detail: errorMessage(error))
            }
        }
    }
}

func refreshAll() {
    refreshAll(showFeedback: true)
}

// Operation handlers call the overload with `showFeedback: false` after they
// have already published their terminal success/warning/error message. A
// status refresh must not replace that message with a second operation.
func refreshAll(showFeedback: Bool) {
    refreshAll(showFeedback: showFeedback, changeScope: nil)
}

/// Refreshes the visible change tree for every event, but only reloads
/// repository-wide metadata when the Git administrative area changed. This
/// mirrors IntelliJ's separation between a dirty VFS scope and global VCS
/// cache invalidation: editing one worktree file must not rewalk refs, tags,
/// submodules, worktrees, or the log model.
func refreshAll(
    showFeedback: Bool,
    changeScope: RepositoryChangeScope?,
    dirtyPaths: [RepositoryDirtyPath] = [],
    onCompleted: (() -> Void)? = nil
) {
    guard let repo else {
        onCompleted?()
        return
    }
    if showFeedback {
        beginFeedbackOperation("Refresh status")
    }
    let repositoryPath = projectPath
    let refreshMetadata = changeScope?.contains(.gitMetadata) ?? true
    let requestedIncrementalStatusPaths = refreshMetadata
        ? nil
        : repositoryWorktreeStatusPaths(
            workdir: repo.workdir() ?? "",
            gitDir: repo.gitDir(),
            dirtyPaths: dirtyPaths
        )
    let refreshTicket = refreshGate.begin(
        usesIncrementalStatus: requestedIncrementalStatusPaths != nil
    )
    let incrementalStatusPaths = refreshTicket.usesIncrementalStatus
        ? requestedIncrementalStatusPaths
        : nil
    let existingEntries = entries
    let shouldLoadLog = refreshMetadata && toolWindowMode == .log && logViewMode != .reflog
    let shouldLoadReflog = refreshMetadata && toolWindowMode == .log && logViewMode == .reflog
    DiagnosticsLogger.shared.record(operation: "refresh", repositoryPath: repositoryPath, code: "started")
    Task.detached(priority: .userInitiated) {
        do {
            let st: [FileEntry]
            if let incrementalStatusPaths {
                if incrementalStatusPaths.isEmpty {
                    st = existingEntries
                } else if let refreshed = try? repo.statusPaths(paths: incrementalStatusPaths) {
                    // Replace only the pathspecs covered by this VFS batch.
                    // Deleted paths disappear from `refreshed`, which removes
                    // stale rows from the previous status snapshot.
                    let impacted = { (path: String) in
                        incrementalStatusPaths.contains { scope in
                            path == scope || path.hasPrefix("\(scope)/")
                        }
                    }
                    st = (existingEntries.filter { !impacted($0.path) } + refreshed)
                        .sorted { $0.path < $1.path }
                } else {
                    // Git pathspecs can become invalid while a directory is
                    // being atomically replaced. Preserve correctness over
                    // the optimization and rescan the repository.
                    st = try repo.status()
                }
            } else {
                st = try repo.status()
            }
            let cls: [ChangeListInfo]
            if incrementalStatusPaths != nil {
                // `st` is already the complete visible status snapshot after
                // the path-scoped merge. Projecting Changelists from it keeps
                // a worktree-only event genuinely incremental instead of
                // calling changelistList(), which performs another full
                // status walk inside the engine.
                cls = (try? repo.changelistListForPaths(
                    currentPaths: st.map(\.path)
                )) ?? []
            } else {
                cls = (try? repo.changelistList()) ?? []
            }
            let hid = repo.headCommitId()
            let mergePending = repo.mergeInProgress()
            let opState = try? repo.operationState()
            let resolvedPaths = (try? repo.conflictWorkspace().resolvedFiles) ?? []
            await MainActor.run {
                guard self.projectRepo === repo else {
                    onCompleted?()
                    return
                }
                guard self.refreshGate.isCurrent(refreshTicket) else {
                    onCompleted?()
                    return
                }
                guard self.refreshGate.finish(refreshTicket) else {
                    onCompleted?()
                    return
                }
                self.entries = st
                self.changeLists = cls
                self.isShowingCachedStatusSnapshot = false
                if incrementalStatusPaths == nil,
                   let rootPath = repo.workdir() {
                    savePersistedStatusCache(
                        rootPath: rootPath,
                        files: st,
                        changeLists: cls
                    )
                }
                self.fileContentRefreshToken &+= 1
                self.headId = hid
                self.mergeInProgress = mergePending || self.stashPopConflictInProgress || self.stashApplyConflictInProgress
                self.operationState = opState
                if let opState, let rootPath = repo.workdir() {
                    self.feedbackCenter.expire(
                        notificationID: self.logApplyRecoveryNotificationID(rootPath: rootPath)
                    )
                    self.logApplyRecoveryNotificationFingerprints.removeValue(
                        forKey: operationRecoveryNotificationRootKey(rootPath)
                    )
                    self.publishOperationRecoveryNoticeIfNeeded(
                        state: opState,
                        rootPath: rootPath
                    )
                } else if let rootPath = repo.workdir() {
                    _ = self.publishLogApplyRecoveryNoticeIfNeeded(rootPath: rootPath)
                    self.feedbackCenter.expire(
                        notificationID: operationRecoveryNotificationID(rootPath: rootPath)
                    )
                    self.operationRecoveryNotificationFingerprints.removeValue(
                        forKey: operationRecoveryNotificationRootKey(rootPath)
                    )
                }
                self.resolvedConflictPaths = resolvedPaths
                if (mergePending || self.stashPopConflictInProgress),
                   self.toolWindowMode != .log,
                   self.selection == nil {
                    self.selection = st.first(where: {
                        $0.staged == .conflicted || $0.unstaged == .conflicted
                    })?.path
                }
                if showFeedback {
                    self.feedbackCenter.success("Status refreshed")
                }
                // Rebased refreshes the visible VCS log model with the active
                // filters. Never replace it with an unfiltered history walk:
                // doing so made a refresh silently discard Text/Paths/User/
                // Date/Branch filters and could also replace the selected
                // commit with an unrelated row.
                if shouldLoadLog {
                    self.reloadLogView()
                }
                if shouldLoadReflog {
                    self.loadReflog()
                }
                onCompleted?()
            }

            // Metadata that is not needed to render the visible change tree
            // is deliberately loaded after the first MainActor update. The
            // staging model itself performs a status scan, so keeping it out
            // of the critical path avoids making every refresh wait for two
            // full worktree walks.
            Task.detached(priority: .utility) {
                let staging = try? repo.stagingModel()
                guard refreshMetadata else {
                    await MainActor.run {
                        guard self.projectRepo === repo,
                              self.refreshGate.isCurrent(refreshTicket) else { return }
                        self.stagingModel = staging
                        self.lastIndexRevision = staging?.indexRevision
                    }
                    return
                }

                let ignoredRules = (try? repo.ignoredRules()) ?? []
                let recent = (try? repo.recentCommitMessages(limit: 10)) ?? []
                let tags = (try? repo.tagList()) ?? []
                let submodules = (try? repo.submoduleList()) ?? []
                let worktrees = (try? repo.worktreeList()) ?? []
                let isShallow = repo.isShallow()
                let remoteBranches = (try? repo.remoteBranchList()) ?? []
                let recentBranches = (try? repo.recentBranches(limit: 10)) ?? []
                let syncStatuses = (try? repo.syncStatus()) ?? []
                await MainActor.run {
                    guard self.projectRepo === repo,
                          self.refreshGate.isCurrent(refreshTicket) else { return }
                    self.ignoredRules = ignoredRules
                    self.recentMessages = recent
                    self.tags = tags
                    self.submodules = submodules
                    self.worktrees = worktrees
                    self.isShallowRepository = isShallow
                    self.stagingModel = staging
                    self.lastIndexRevision = staging?.indexRevision
                    self.remoteBranches = remoteBranches
                    self.recentBranches = recentBranches
                    self.syncStatuses = syncStatuses
                }
            }
        } catch {
            DiagnosticsLogger.shared.record(level: .error, operation: "refresh", repositoryPath: repositoryPath, code: "failed")
            await MainActor.run {
                guard self.projectRepo === repo else {
                    onCompleted?()
                    return
                }
                guard self.refreshGate.isCurrent(refreshTicket) else {
                    onCompleted?()
                    return
                }
                guard self.refreshGate.finish(refreshTicket) else {
                    onCompleted?()
                    return
                }
                if showFeedback {
                    self.loadError = errorMessage(error)
                    self.feedbackCenter.error("Refresh failed", detail: errorMessage(error), nextStep: "Check the repository and retry.")
                }
                onCompleted?()
            }
        }
    }
}

func handleProjectDrop(_ providers: [NSItemProvider]) -> Bool {
    guard let provider = providers.first else { return false }
    _ = provider.loadObject(ofClass: NSURL.self) { object, _ in
        guard let url = object as? URL, url.hasDirectoryPath else { return }
        DispatchQueue.main.async {
            self.path = url.path
            self.requestOpenProject(url.path)
        }
    }
    return true
}

/// 打开当前窗口中的项目。
func openRepo() {
    requestOpenProject(path)
}

/// 文件夹选择器：NSOpenPanel 选目录后填入 path 并打开（C1）。
func showOpenPanel() {
    let panel = NSOpenPanel()
    panel.canChooseDirectories = true
    panel.canChooseFiles = false
    panel.allowsMultipleSelection = false
    panel.canCreateDirectories = false
    panel.prompt = "打开项目"
    // 默认定位到当前项目或用户主目录
    if let projectPath {
        panel.directoryURL = URL(fileURLWithPath: projectPath)
    }
    if panel.runModal() == .OK, let url = panel.url {
        requestOpenProject(url.standardizedFileURL.path)
    }
}

/// 选择一个已有目录并初始化 Git 元数据。
func showInitializePanel() {
    let panel = NSOpenPanel()
    panel.canChooseDirectories = true
    panel.canChooseFiles = false
    panel.allowsMultipleSelection = false
    panel.canCreateDirectories = false
    panel.prompt = "初始化 Git"
    if let projectPath {
        panel.directoryURL = URL(fileURLWithPath: projectPath)
    }
    guard panel.runModal() == .OK, let url = panel.url else { return }
    initializeProject(at: url.standardizedFileURL.path)
}

func chooseCloneParentDirectory() {
    let panel = NSOpenPanel()
    panel.canChooseDirectories = true
    panel.canChooseFiles = false
    panel.allowsMultipleSelection = false
    panel.canCreateDirectories = false
    panel.prompt = "选择父目录"
    panel.directoryURL = URL(fileURLWithPath: cloneParentDirectory)
    if panel.runModal() == .OK, let url = panel.url {
        cloneParentDirectory = url.standardizedFileURL.path
    }
}

func initializeProject(at requestedPath: String) {
    let selectedPath = URL(fileURLWithPath: requestedPath).standardizedFileURL.path
    if let existingRoot = gitInitializationExistingRepositoryRoot(path: selectedPath) {
        let alert = NSAlert()
        alert.alertStyle = .warning
        alert.messageText = "Directory Already Belongs to Git"
        alert.informativeText = "\(selectedPath) is inside the Git repository at \(existingRoot). Initialize Git again?"
        alert.addButton(withTitle: "Initialize Anyway")
        alert.addButton(withTitle: "Cancel")
        alert.buttons.first?.hasDestructiveAction = true
        guard alert.runModal() == .alertFirstButtonReturn else { return }
    }
    beginFeedbackOperation("Initialize Git repository")
    Task.detached(priority: .userInitiated) {
        do {
            let initializedPath = try initializeRepository(path: selectedPath)
            await MainActor.run {
                self.feedbackCenter.success("Git repository initialized", detail: initializedPath)
                self.path = initializedPath
            }
            await MainActor.run { self.requestOpenProject(initializedPath) }
        } catch {
            await MainActor.run {
                self.loadError = errorMessage(error)
                self.feedbackCenter.error("Initialize Git repository failed", detail: errorMessage(error), nextStep: "Choose a writable directory and retry.")
            }
        }
    }
}

func cloneRepositoryFromDialog() {
    let url = cloneURL.trimmingCharacters(in: .whitespacesAndNewlines)
    let parent = cloneParentDirectory.trimmingCharacters(in: .whitespacesAndNewlines)
    var directoryName = cloneDirectoryName.trimmingCharacters(in: .whitespacesAndNewlines)
    if directoryName.isEmpty {
        let lastComponent = url
            .trimmingCharacters(in: CharacterSet(charactersIn: "/"))
            .split(separator: "/")
            .last
            .map(String.init) ?? "cloned-repository"
        directoryName = lastComponent.hasSuffix(".git")
            ? String(lastComponent.dropLast(4))
            : lastComponent
    }
    guard !url.isEmpty, !parent.isEmpty, !directoryName.isEmpty else { return }
    let destination = URL(fileURLWithPath: parent).appendingPathComponent(directoryName).path
    let recursive = cloneRecursiveSubmodules
    let broker = credentialAuth.broker
    beginFeedbackOperation("Clone Git repository")
    Task.detached(priority: .userInitiated) {
        do {
            let clonedPath = try cloneRepositoryWithAuth(
                url: url,
                destination: destination,
                recursiveSubmodules: recursive,
                broker: broker
            )
            await MainActor.run {
                self.showCloneDialog = false
                self.cloneURL = ""
                self.cloneDirectoryName = ""
                self.feedbackCenter.success("Git repository cloned", detail: clonedPath)
                self.path = clonedPath
            }
            await MainActor.run { self.requestOpenProject(clonedPath) }
        } catch {
            await MainActor.run {
                self.loadError = errorMessage(error)
                self.feedbackCenter.error("Clone Git repository failed", detail: friendlyRemoteError(error), nextStep: "Check the URL, destination, and authentication, then retry.")
            }
        }
    }
}

/// 请求打开一个项目；已有项目时由用户选择替换当前窗口或新窗口。
func requestOpenProject(_ requestedPath: String) {
    let selectedPath = URL(fileURLWithPath: requestedPath).standardizedFileURL.path
    guard !selectedPath.isEmpty else { return }
    if projectRepo != nil, projectPath != selectedPath {
        pendingProjectPath = selectedPath
        showProjectSwitchAlert = true
    } else {
        openProjectPath(selectedPath)
    }
}

func replacePendingProject() {
    guard let pendingProjectPath else { return }
    let next = pendingProjectPath
    self.pendingProjectPath = nil
    resetProjectState()
    projectPath = next
    path = next
    openProjectPath(next)
}

func openPendingProjectInNewWindow() {
    guard let pendingProjectPath else { return }
    let next = pendingProjectPath
    self.pendingProjectPath = nil
    openWindow(value: next)
}

/// 在当前窗口加载单个项目，并丢弃上一项目的所有选择和缓存。
private func expireOperationRecoveryNotifications() {
    for rootPath in operationRecoveryNotificationFingerprints.keys {
        feedbackCenter.expire(
            notificationID: operationRecoveryNotificationID(rootPath: rootPath)
        )
    }
    operationRecoveryNotificationFingerprints.removeAll()
}

func openProjectPath(_ projectPath: String) {
    expireOperationRecoveryNotifications()
    repositoryChangeDeliveryTask?.cancel()
    repositoryChangeDeliveryTask = nil
    repositoryChangeBatch.removeAll()
    repositoryExternalVCSActionManager.removeAll()
    repositoryDirtyScopeManager.removeAll()
    repositoryDirtyFileManager.removeAll()
    beginFeedbackOperation("Open project")
    logRefreshTask?.cancel()
    logRefreshTask = nil
    logLoadTask?.cancel()
    logLoadTask = nil
    reflogLoadTask?.cancel()
    reflogLoadTask = nil
    reflogLoadMoreTask?.cancel()
    reflogLoadMoreTask = nil
    reflogGeneration += 1
    compareLoadTask?.cancel()
    compareLoadTask = nil
    cancelBranchComparisonTasks()
    activeCompareRepo = nil
    compareRepositoryPath = nil
    logGeneration += 1
    isLoading = true
    isLoadingLog = true
    loadError = nil
    commitFeedback = nil
    stashPopConflictInProgress = false
    stashApplyConflictInProgress = false
    shelveConflictInProgress = false
    shelveConflictIsPop = false
    shelveConflictIsDirectPatch = false
    pendingShelveConflictName = nil
    pendingShelveConflictRepository = nil
    pendingShelveConflictChangeList = nil
    pendingShelveConflictPatch = nil
    pendingShelveConflictNotificationID = nil
    pendingStashConflictNotificationID = nil
    pendingStashPopIndex = nil
    pendingStashPopID = nil
    pendingPullStashPop = false
    pendingPullStashID = nil
    pendingPullStashMessage = nil
    pendingPullShelfName = nil
    showMergeRevisionsDialog = false
    // The split workspaces keep their own selections. Clear them before the
    // new repository starts publishing data so a previous project's diff or
    // stash preview cannot remain actionable during the transition.
    selection = nil
    fileSelection = nil
    selectionModePath = nil
    commitPreviewPath = nil
    commitPreviewVisible = false
    logSelectedIDs = []
    reflogRootPath = nil
    reflogRootRepo = nil
    reflogEntries = []
    reflogSelection = nil
    reflogSelectedIDs = []
    stashPreviewStashID = nil
    stashPreviewText = nil
    showStashPreview = false
    shelfPreviewName = nil
    shelfPreviewText = nil
    showShelfPreview = false
    remoteProtectedBranchPatterns = []
    remoteProtectedBranchPatternsByRoot = [:]
    isShallowRepository = false
    let requestedPath = projectPath
    logBranchesSelectionActionRaw = GitBranchesPopupSettings.stringValue(
        GitBranchesPopupSettings.logSelectionActionKey,
        for: requestedPath
    )
    logBranchesGroupByDirectory = GitBranchesPopupSettings.value(
        GitBranchesPopupSettings.groupByDirectoryKey,
        for: requestedPath
    )
    logBranchesGroupByRepository = GitBranchesPopupSettings.value(
        GitBranchesPopupSettings.groupByRepositoryKey,
        for: requestedPath
    )
    applyProjectGitExecutableOverride(for: requestedPath, roots: [requestedPath])
    let shouldLoadReflog = logViewMode == .reflog
    Task.detached(priority: .userInitiated) {
        do {
            let r = try openRepository(path: requestedPath)
            let bs = try r.branchList()
            let hid = r.headCommitId()
            DiagnosticsLogger.shared.record(
                operation: "project",
                repositoryPath: requestedPath,
                code: "opened"
            )
            await MainActor.run {
                guard !(self.externalLogWindow && self.externalLogSessionDisposed) else { return }
                let root = r.workdir() ?? requestedPath
                self.projectPath = root
                self.path = root
                self.loadMergeDialogSettings(for: root)
                self.loadRebaseDialogSettings(for: root)
                self.logBranchesSelectionActionRaw = GitBranchesPopupSettings.stringValue(
                    GitBranchesPopupSettings.logSelectionActionKey,
                    for: root
                )
                self.logBranchesGroupByDirectory = GitBranchesPopupSettings.value(
                    GitBranchesPopupSettings.groupByDirectoryKey,
                    for: root
                )
                self.logBranchesGroupByRepository = GitBranchesPopupSettings.value(
                    GitBranchesPopupSettings.groupByRepositoryKey,
                    for: root
                )
                self.loadProjectProtectedBranchSettings(for: root)
                self.projectIncomingCheckStrategyRaw = GitIncomingCheckStrategySettings.projectRawValue(for: root)
                self.projectFetchTagsMode = GitFetchTagsSettings.mode(for: root)
                self.projectUpdateMethod = GitUpdateMethodSettings.method(for: root)
                self.projectRepo = r
                if shouldLoadReflog {
                    self.reflogRootPath = root
                    self.reflogRootRepo = r
                    self.prepareReflogRoot()
                }
                self.logActiveRootPath = nil
                self.logActiveRepo = nil
                self.logActiveBranches = []
                self.logActiveRemoteBranches = []
                self.logActiveRemotes = []
                self.logAggregateBranchFilters = []
                self.logAggregateRevisionRanges = []
                self.externalLogAggregateLoadStarted = false
                let preserveInitialExternalLogRoots = self.externalLogWindow
                    && !self.externalLogRootRequestConsumed
                    && !self.initialExternalLogRootPaths.isEmpty
                if preserveInitialExternalLogRoots {
                    self.logAggregateRootPaths = self.initialExternalLogRootPaths
                    self.externalLogRootSelectionInitialized = true
                    self.externalLogRootRequestConsumed = true
                } else {
                    self.logAggregateRootPaths = []
                    self.externalLogRootSelectionInitialized = false
                }
                self.logAggregateRepositories = [:]
                self.logAggregateLoadedCounts = [:]
                self.restorePersistedMultiRootRebaseSession(for: root)
                if self.multiRootRebaseSession == nil {
                    self.restorePersistedSingleRootRebaseState(for: root)
                    self.restorePersistedPullPreservation(for: root)
                }
                self.rememberRecentPath(root)
                self.headId = hid
                // The log and the current branch are the critical path. Do not
                // wait for repository-wide reachability scans before exposing
                // the graph: large repositories such as IntelliJ can contain
                // millions of packed objects.
                self.branches = bs
                self.refreshLogMyBranches()
                self.selection = nil; self.fileSelection = nil
                self.logSelection = nil
                self.compareSelection = nil
                self.compareSelectedPaths = []
                if let cachedStatus = loadPersistedStatusCache(rootPath: root),
                   let snapshot = cachedStatus.restoredSnapshot(rootPath: root) {
                    self.entries = snapshot.files
                    self.changeLists = snapshot.changeLists
                    self.isShowingCachedStatusSnapshot = true
                } else {
                    self.entries = []
                    self.changeLists = []
                    self.isShowingCachedStatusSnapshot = false
                }
                self.ignoredRules = []
                self.stagingModel = nil
                self.lastIndexRevision = nil
                self.mergeInProgress = false
                self.mergeInitialHead = nil
                self.operationState = nil
                expireOperationRecoveryNotifications()
                self.isLoading = false
                self.feedbackCenter.success("Project opened")
            }

            // The permanent graph is intentionally loaded after the repository
            // is visible. Route the first load through the same loader used by
            // refresh/filter changes so the persisted snapshot is available
            // after relaunch and the active tab query is not silently dropped.
            await MainActor.run {
                guard self.projectRepo === r else { return }
                self.loadLog(reset: true)
            }

            // Status is the first thing the Commit/Stash workspace needs.
            // Publish it as soon as that scan completes instead of waiting for
            // tags, remotes, worktrees, and the staging model. The old serial
            // bundle made the left workspace look empty for the entire
            // repository metadata scan.
            Task.detached(priority: .utility) {
                do {
                    let st = try r.status()
                    let cls = try r.changelistList()
                    let mergePending = r.mergeInProgress()
                    let shelveRestore = try? r.shelveRestoreInfo()
                    await MainActor.run {
                        guard self.projectRepo === r else { return }
                        self.entries = st
                        self.changeLists = cls
                        self.isShowingCachedStatusSnapshot = false
                        if let rootPath = r.workdir() {
                            savePersistedStatusCache(
                                rootPath: rootPath,
                                files: st,
                                changeLists: cls
                            )
                        }
                        self.mergeInProgress = mergePending
                        if self.mergeInProgress, self.toolWindowMode != .log {
                            self.selection = st.first(where: {
                                $0.staged == .conflicted || $0.unstaged == .conflicted
                            })?.path
                            self.showMergeRevisionsDialog = st.contains {
                                $0.staged == .conflicted || $0.unstaged == .conflicted
                            }
                        } else if let shelveRestore {
                            self.pendingShelveConflictName = shelveRestore.name
                            self.pendingShelveConflictRepository = r
                            self.pendingShelveConflictChangeList = shelveRestore.targetChangeList
                            self.shelveConflictIsPop = shelveRestore.isPop
                            self.shelveConflictIsDirectPatch = shelveRestore.isDirectPatch
                            self.pendingShelveConflictPatch = shelveRestore.patch
                            self.shelveConflictInProgress = true
                            self.mergeInitialPath = shelveRestore.paths.first
                            if self.toolWindowMode != .log {
                                self.selection = shelveRestore.paths.first
                                self.showMergeRevisionsDialog = true
                            }
                        }
                    }
                } catch {
                    await MainActor.run {
                        guard self.projectRepo === r else { return }
                        self.isShowingCachedStatusSnapshot = !self.entries.isEmpty
                        self.feedbackCenter.warning(
                            "Status refresh failed",
                            detail: errorMessage(error),
                            nextStep: "Refresh the Changes view after checking the repository."
                        )
                    }
                }

                        // Secondary metadata is intentionally independent of
                        // the visible status result. Each call is still off the
                        // main actor, but a slow remote/ref scan can no longer
                        // hold up the first usable Commit/Stash rows.
                        Task.detached(priority: .utility) {
                            let ignoredRules = (try? r.ignoredRules()) ?? []
                            let recentMessages = (try? r.recentCommitMessages(limit: 10)) ?? []
                            let staging = try? r.stagingModel()
                            let operationState = try? r.operationState()
                            let ss = (try? r.stashList()) ?? []
                            let sh = (try? r.shelveList()) ?? []
                            let dsh = (try? r.shelveDeletedList()) ?? []
                            let rs = (try? r.remoteList()) ?? []
                            let isShallow = r.isShallow()
                            let remoteBranches = (try? r.remoteBranchList()) ?? []
                            let syncStatuses = (try? r.syncStatus()) ?? []
                            let ts = (try? r.tagList()) ?? []
                            let submodules = (try? r.submoduleList()) ?? []
                            let worktrees = (try? r.worktreeList()) ?? []
                            let recentBranches = (try? r.recentBranches(limit: 10)) ?? []
                            let mergePending = r.mergeInProgress()
                            await MainActor.run {
                                guard self.projectRepo === r else { return }
                                self.ignoredRules = ignoredRules
                                self.recentMessages = recentMessages
                                self.stagingModel = staging
                                self.lastIndexRevision = staging?.indexRevision
                        self.operationState = operationState
                        self.mergeInProgress = mergePending || self.stashPopConflictInProgress || self.stashApplyConflictInProgress
                                self.stashes = ss; self.remotes = rs
                                self.isShallowRepository = isShallow
                                self.restoreRemoteProtectedBranchPatterns(for: rs, projectPath: self.projectPath)
                                self.remoteBranches = remoteBranches
                                self.recentBranches = recentBranches; self.syncStatuses = syncStatuses
                                self.shelves = sh; self.deletedShelves = dsh; self.tags = ts
                        self.submodules = submodules
                        self.worktrees = worktrees
                        if let operationState,
                           let rootPath = r.workdir() {
                            self.feedbackCenter.expire(
                                notificationID: self.logApplyRecoveryNotificationID(rootPath: rootPath)
                            )
                            self.logApplyRecoveryNotificationFingerprints.removeValue(
                                forKey: operationRecoveryNotificationRootKey(rootPath)
                            )
                            self.publishOperationRecoveryNoticeIfNeeded(
                                state: operationState,
                                rootPath: rootPath
                            )
                        } else if let rootPath = r.workdir() {
                            _ = self.publishLogApplyRecoveryNoticeIfNeeded(rootPath: rootPath)
                        }
                    }
                        }
                    }
        } catch {
            await MainActor.run {
                DiagnosticsLogger.shared.record(
                    level: .error,
                    operation: "project",
                    repositoryPath: requestedPath,
                    code: "open-failed"
                )
                self.loadError = errorMessage(error)
                self.projectRepo = nil
                self.entries = []; self.isLoading = false
                self.feedbackCenter.error("Open project failed", detail: errorMessage(error), nextStep: "Choose a valid Git repository and retry.")
            }
        }
    }
}

// MARK: 最近项目

func loadRecentPaths() -> [String] {
    UserDefaults.standard.stringArray(forKey: "lastOpenedPaths") ?? []
}

func rememberRecentPath(_ path: String) {
    var paths = loadRecentPaths().filter { $0 != path }
    paths.insert(path, at: 0)
    UserDefaults.standard.set(Array(paths.prefix(8)), forKey: "lastOpenedPaths")
}

