func stageAll() {
    guard let repo else { return }
    // GitStagePanel's toolbar action is Git.Stage.Add.Tracked, not
    // Git.Stage.Add.All. The latter belongs to the overflow action group and
    // also stages untracked files. Keep the toolbar's default behavior aligned
    // with rebased: stage tracked worktree changes only.
    guard entries.contains(where: {
        $0.unstaged != .unchanged
            && $0.unstaged != .untracked
            && $0.unstaged != .ignored
    }) else { return }
    beginFeedbackOperation("Stage changes")
    Task.detached(priority: .userInitiated) {
        do {
            // Keep Git.Stage.Add.Tracked in the engine so deleted tracked
            // files and the untracked exclusion have one authoritative path.
            try repo.stageTracked()
            let status = try repo.status()
            let staging = try? repo.stagingModel()
            await MainActor.run {
                self.entries = status
                self.stagingModel = staging
                self.lastIndexRevision = staging?.indexRevision
                self.fileContentRefreshToken &+= 1
                self.feedbackCenter.success("Changes staged")
            }
        } catch {
            await MainActor.run {
                self.loadError = errorMessage(error)
                self.feedbackCenter.error("Stage changes failed", detail: errorMessage(error), nextStep: "Check the file permissions and retry.")
            }
        }
    }
}

/// Explicit Git.Stage.Add.All action: include tracked and untracked changes.
/// The adjacent toolbar action remains tracked-only to match IntelliJ's
/// Git.Stage.Add.Tracked affordance.
func stageEverything() {
    guard let repo else { return }
    guard entries.contains(where: {
        $0.unstaged != .unchanged && $0.unstaged != .ignored
    }) else { return }
    beginFeedbackOperation("Stage all changes")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.stageAll()
            let status = try repo.status()
            let staging = try? repo.stagingModel()
            await MainActor.run {
                self.entries = status
                self.stagingModel = staging
                self.lastIndexRevision = staging?.indexRevision
                self.fileContentRefreshToken &+= 1
                self.feedbackCenter.success("All changes staged")
            }
        } catch {
            await MainActor.run {
                self.loadError = errorMessage(error)
                self.feedbackCenter.error("Stage all changes failed", detail: errorMessage(error), nextStep: "Check the file permissions and retry.")
            }
        }
    }
}

var currentLogTabID: UUID {
    activeLogTabID ?? logTabs.first?.id ?? UUID()
}

/// IntelliJ's branch filter accepts multiple heads. Keep the legacy singular
/// field as a compatibility bridge for old in-memory tabs and revision-entry
/// actions, while using the set as the source of truth for the graph query.
var activeLogStartRevisions: [String] {
    let selected = logStartRevisions
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }
        .sorted()
    if !selected.isEmpty {
        return selected
    }
    let legacy = logStartRevision.trimmingCharacters(in: .whitespacesAndNewlines)
    return legacy.isEmpty ? [] : [legacy]
}

var logBranchFilterTitle: String {
    activeLogStartRevisions.isEmpty
        ? "Branch"
        : activeLogStartRevisions.joined(separator: ", ")
}

func setLogStartRevisions(_ revisions: [String]) {
    let normalized = revisions
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }
    logStartRevisions = Set(normalized)
    logStartRevision = normalized.count == 1 ? normalized[0] : ""
}

func setLogStartRevision(_ revision: String) {
    setLogStartRevisions(revision.isEmpty ? [] : [revision])
}

func setLogStartRevisionSelected(_ revision: String, selected: Bool) {
    var revisions = logStartRevisions
    if selected {
        revisions.insert(revision)
    } else {
        revisions.remove(revision)
    }
    setLogStartRevisions(Array(revisions))
}

/// Opens IntelliJ's update-session "View Commits" target. Each distinct range
/// gets a dedicated Update Info Log tab so the user's ordinary Log stays
/// intact; every result keeps its owning repository identity.
func showLogRevisionRanges(_ persistedRanges: [PersistedLogRevisionRange]) {
    guard let projectPath else { return }
    let projectRoot = URL(fileURLWithPath: projectPath).standardizedFileURL.path
    var seen = Set<LogRootRevisionRange>()
    let ranges = persistedRanges.compactMap { persisted -> LogRootRevisionRange? in
        let rootPath = URL(fileURLWithPath: persisted.rootPath).standardizedFileURL.path
        let oldRevision = persisted.oldRevision.trimmingCharacters(in: .whitespacesAndNewlines)
        let newRevision = persisted.newRevision.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !oldRevision.isEmpty,
              !newRevision.isEmpty,
              oldRevision != newRevision,
              rootPath == projectRoot || rootPath.hasPrefix(projectRoot + "/") else {
            return nil
        }
        let range = LogRootRevisionRange(
            rootPath: rootPath,
            oldRevision: oldRevision,
            newRevision: newRevision
        )
        return seen.insert(range).inserted ? range : nil
    }
    guard !ranges.isEmpty else { return }

    var repositories: [String: Repository] = [:]
    for rootPath in Set(ranges.map(\.rootPath)) {
        if let rootRepo = try? openRepository(path: rootPath) {
            repositories[rootPath] = rootRepo
        }
    }
    guard repositories.count == Set(ranges.map(\.rootPath)).count else {
        feedbackCenter.error(
            "View Commits unavailable",
            detail: "One or more Git roots from the update session could not be opened.",
            nextStep: "Refresh Git Roots, then retry the notification action."
        )
        return
    }

    let persistedRanges = ranges.map(\.persisted).sorted {
        if $0.rootPath != $1.rootPath { return $0.rootPath < $1.rootPath }
        if $0.oldRevision != $1.oldRevision { return $0.oldRevision < $1.oldRevision }
        return $0.newRevision < $1.newRevision
    }
    saveCurrentLogTab()
    if let existing = logTabs.first(where: { $0.updateInfoRanges == persistedRanges }) {
        activeLogTabID = existing.id
        applyLogTab(existing)
        persistExternalLogTabs()
        toolWindowMode = .log
        toolWindowExpanded = true
        loadActiveLogTab(existing)
        return
    }

    let tab = makeUpdateInfoLogTab(
        ranges: persistedRanges,
        title: "Update Info · \(dateStr(Int64(Date().timeIntervalSince1970)))"
    )
    let updateInfoSelections = GitUpdateInfoPathFilterSettings.selections(for: projectPath)
    var filteredTab = tab
    filteredTab.pathSelections = updateInfoSelections
    filteredTab.pathFilter = logPathFilterEditorText(updateInfoSelections)
    appendLogTabAndLoad(filteredTab)
    toolWindowMode = .log
    toolWindowExpanded = true
}

/// IntelliJ's GitUpdateInfoAsLog is shared by Update Project, Push, and
/// force-pushed branch updates. Keep the setting/range gate in one place so
/// every successful producer opens the same dedicated Update Info tab.
private func autoOpenUpdateInfoIfEnabled(_ ranges: [PersistedLogRevisionRange]) {
    guard GitUpdateInfoAutoOpenSettings.shouldAutoOpen(ranges: ranges) else { return }
    showLogRevisionRanges(ranges)
}

/// Reopen the exact Git root and commit referenced by a commit notification,
/// then enter the same HEAD-only reword flow used by the Log action group.
/// The HEAD check is repeated after loading the commit so a stale notification
/// can never rewrite a newer commit created after the original commit.
private func openRewordCommit(rootPath: String, commitID: String) {
    let normalizedRootPath = URL(fileURLWithPath: rootPath).standardizedFileURL.path
    let normalizedCommitID = commitID.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedCommitID.isEmpty,
          let rootRepo = try? openRepository(path: normalizedRootPath) else {
        feedbackCenter.error(
            "Reword Commit unavailable",
            detail: "The Git root or commit from the notification is no longer available.",
            nextStep: "Refresh Git Roots and retry from Log."
        )
        return
    }

    logAggregateBranchFilters = []
    logAggregateRevisionRanges = []
    logAggregateRootPaths = []
    logAggregateRepositories = [:]
    logAggregateLoadedCounts = [:]
    logSelection = nil
    logSelectedIDs = []
    logViewMode = .graph
    toolWindowMode = .log
    toolWindowExpanded = true
    projectPanelExpanded = false

    let primaryRoot = repo?.workdir().map { URL(fileURLWithPath: $0).standardizedFileURL.path }
    if normalizedRootPath == primaryRoot {
        logActiveRootPath = nil
        logActiveRepo = nil
        logActiveBranches = []
        logActiveRemoteBranches = []
        logActiveRemotes = []
    } else {
        logActiveRootPath = normalizedRootPath
        logActiveRepo = rootRepo
        logActiveBranches = (try? rootRepo.branchList()) ?? []
        logActiveRemoteBranches = (try? rootRepo.remoteBranchList()) ?? []
        logActiveRemotes = (try? rootRepo.remoteList()) ?? []
    }
    loadLog()

    Task.detached(priority: .userInitiated) {
        do {
            guard rootRepo.headCommitId() == normalizedCommitID else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "The committed HEAD has changed."]
                )
            }
            let commit = try rootRepo.logFiltered(
                path: nil,
                limit: 1,
                follow: false,
                startRev: normalizedCommitID,
                author: nil,
                since: nil
            ).first { candidate in
                candidate.id == normalizedCommitID
                    || candidate.id.hasPrefix(normalizedCommitID)
                    || normalizedCommitID.hasPrefix(candidate.id)
            }
            guard let commit, rootRepo.headCommitId() == commit.id else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 2,
                    userInfo: [NSLocalizedDescriptionKey: "The committed HEAD has changed."]
                )
            }
            await MainActor.run {
                guard self.isActiveLogRepository(rootRepo) else { return }
                self.logSelection = commit.id
                self.logSelectedIDs = [commit.id]
                self.logDetailCommit = commit
                self.logRewordCommit = commit
                self.logRewordMessage = commit.messageBody.isEmpty
                    ? commit.summary
                    : "\(commit.summary)\n\n\(commit.messageBody)"
                self.logRewordUsesRootRebase = false
                if commit.parentIds.isEmpty {
                    self.pendingInitialCommitReword = commit
                    self.showInitialCommitRewordAlert = true
                } else {
                    self.showLogRewordDialog = true
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.warning(
                    "Reword Commit unavailable",
                    detail: errorMessage(error),
                    nextStep: "The action applies only while the referenced commit remains the current HEAD."
                )
            }
        }
    }
}

/// Branch dashboard navigation is root-aware. Selecting a branch in a nested
/// Git root changes only the Log repository context; the primary Commit/Status
/// repository remains unchanged.
func navigateLogToBranch(rootPath: String?, branch: String) {
    logAggregateBranchFilters = []
    logAggregateRevisionRanges = []
    logAggregateRootPaths = []
    logAggregateRepositories = [:]
    logAggregateLoadedCounts = [:]
    var navigationHeadID: String?
    if let rootPath {
        guard let rootRepo = try? openRepository(path: rootPath) else {
            feedbackCenter.error(
                "Log navigation failed",
                detail: "Unable to open Git root: \(rootPath)",
                nextStep: "Refresh Git roots and retry."
            )
            return
        }
        logActiveRootPath = rootPath
        logActiveRepo = rootRepo
        logActiveBranches = (try? rootRepo.branchList()) ?? []
        logActiveRemoteBranches = (try? rootRepo.remoteBranchList()) ?? []
        logActiveRemotes = (try? rootRepo.remoteList()) ?? []
        navigationHeadID = try? rootRepo.revisionCommitId(revision: branch)
    } else {
        logActiveRootPath = nil
        logActiveRepo = nil
        logActiveBranches = []
        logActiveRemoteBranches = []
        logActiveRemotes = []
        navigationHeadID = repo.flatMap { try? $0.revisionCommitId(revision: branch) }
    }
    setLogStartRevision(branch)
    logSelection = navigationHeadID
    logSelectedIDs = navigationHeadID.map { [$0] } ?? []
    logViewMode = .graph
    loadLog()
}

/// Search Everywhere selects a revision without changing the user's branch
/// filter. Wait for the first Log page so a selected historical commit can be
/// inserted into the visible graph by `selectLogRevision` when it is outside
/// the initial page.
func navigateLogToRevision(rootPath: String, revision: String) {
    logAggregateBranchFilters = []
    logAggregateRevisionRanges = []
    logAggregateRootPaths = []
    logAggregateRepositories = [:]
    logAggregateLoadedCounts = [:]
    guard let rootRepo = try? openRepository(path: rootPath) else {
        feedbackCenter.error(
            "Log navigation failed",
            detail: "Unable to open Git root: \(rootPath)",
            nextStep: "Refresh Git roots and retry."
        )
        return
    }
    logActiveRootPath = rootPath
    logActiveRepo = rootRepo
    logActiveBranches = (try? rootRepo.branchList()) ?? []
    logActiveRemoteBranches = (try? rootRepo.remoteBranchList()) ?? []
    logActiveRemotes = (try? rootRepo.remoteList()) ?? []
    setLogStartRevisions([])
    logSelection = nil
    logSelectedIDs = []
    logViewMode = .graph
    loadLog()
    Task { @MainActor in
        while isLoadingLog {
            guard !Task.isCancelled else { return }
            try? await Task.sleep(nanoseconds: 50_000_000)
        }
        guard !Task.isCancelled else { return }
        selectLogRevision(revision)
    }
}

/// Applies the multi-root Branches dashboard selection as one VCS Log query.
/// The root is part of every filter, so identically named branches in two
/// repositories remain independent while their histories are shown together.
func applyLogBranchFilters(_ filters: [LogRootBranchFilter]) {
    var seen = Set<LogRootBranchFilter>()
    let normalized = filters.filter { filter in
        let rootPath = filter.rootPath.trimmingCharacters(in: .whitespacesAndNewlines)
        let branch = filter.branch.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !rootPath.isEmpty, !branch.isEmpty else { return false }
        return seen.insert(LogRootBranchFilter(rootPath: rootPath, branch: branch)).inserted
    }
    guard !normalized.isEmpty else { return }
    logAggregateBranchFilters = normalized
    logAggregateRevisionRanges = []
    logAggregateRootPaths = []
    logAggregateRepositories = [:]
    logAggregateLoadedCounts = [:]
    logActiveRootPath = nil
    logActiveRepo = nil
    logActiveBranches = []
    logActiveRemoteBranches = []
    logActiveRemotes = []
    logStartRevision = ""
    logStartRevisions = []
    logSelection = nil
    logSelectedIDs = []
    logViewMode = .graph
    loadLog()
}

/// Compare a dashboard branch in its owning root. The compare loader already
/// has root-scoped repository identity checks, so the result cannot be
/// replaced by a stale comparison from another Git root.
func compareLogBranch(rootPath: String?, branch: String) {
    let comparisonRepo: Repository?
    var rootHeadBranch: String?
    if let rootPath {
        guard let rootRepo = try? openRepository(path: rootPath) else {
            feedbackCenter.error("Compare unavailable", detail: "Unable to open Git root: \(rootPath)")
            return
        }
        comparisonRepo = rootRepo
        rootHeadBranch = multiRootBranchSnapshots.first(where: { $0.rootPath == rootPath })?.headBranch
            ?? (try? rootRepo.branchList().first(where: { $0.isCurrent })?.name)
    } else {
        comparisonRepo = repo
    }
    let current = if rootPath != nil {
        rootHeadBranch ?? "HEAD"
    } else {
        currentBranchName
    }
    guard let comparisonRepo,
          let owningRoot = rootPath ?? comparisonRepo.workdir() else { return }
    openBranchComparisonTab(
        rootPath: owningRoot,
        first: current,
        second: branch
    )
}

/// IntelliJ's `Show Diff with Working Tree`: compare the selected branch
/// revision with the tracked state currently present in its owning worktree.
/// This is deliberately separate from `compareLogBranch`, which compares two
/// committed revisions and opens the history-style comparison view.
func showBranchDiffWithWorkingTree(rootPath: String?, branch: String) {
    let comparisonRepo: Repository?
    if let rootPath {
        guard let rootRepo = try? openRepository(path: rootPath) else {
            feedbackCenter.error(
                "Show Diff unavailable",
                detail: "Unable to open Git root: \(rootPath)"
            )
            return
        }
        comparisonRepo = rootRepo
    } else {
        comparisonRepo = repo
    }
    guard let comparisonRepo,
          let owningRoot = rootPath ?? comparisonRepo.workdir() else { return }
    openTreeComparisonTab(
        rootPath: owningRoot,
        first: branch,
        second: "Working Tree",
        comparesWithWorkingTree: true
    )
}

func logStartRevisionBinding(for revision: String) -> Binding<Bool> {
    Binding(
        get: { self.logStartRevisions.contains(revision) },
        set: { self.setLogStartRevisionSelected(revision, selected: $0) }
    )
}

private func currentLogTabSnapshot() -> LogTabDescriptor {
    let existingTab = logTabs.first(where: { $0.id == currentLogTabID })
    return LogTabDescriptor(
        id: currentLogTabID,
        title: logTabs.first(where: { $0.id == currentLogTabID })?.title ?? "Log",
        rootPath: (logActiveRootPath ?? existingTab?.rootPath).map(canonicalExternalLogPath),
        historyPath: existingTab?.historyPath,
        updateInfoRanges: existingTab?.updateInfoRanges,
        aggregateBranchFilters: logAggregateBranchFilters,
        aggregateRevisionRanges: logAggregateRevisionRanges.map(\.persisted),
        aggregateRootPaths: logAggregateRootPaths.sorted(),
        viewMode: logViewMode,
        startRevision: logStartRevision,
        startRevisions: activeLogStartRevisions,
        pathFilter: logPathFilter,
        pathSelections: activeLogPathFilterSelections(),
        visibleRootPathsRaw: logVisibleRootPathsRaw,
        authorFilter: logAuthorFilter,
        messageFilter: logMessageFilter,
        messageRegex: logMessageRegex,
        messageMatchCase: logMessageMatchCase,
        sinceText: logSinceText,
        untilText: logUntilText,
        commandFilter: logCommandFilter,
        follow: logFollow,
        graphSortModeRaw: logGraphSortModeRaw,
        compareRevision1: compareRev1,
        compareRevision2: compareRev2,
        compareRepositoryPath: compareRepositoryPath,
        compareWithWorkingTree: compareWithWorkingTree,
        compareFirstFilter: logViewMode == .compareBranches
            ? branchCompareFirstFilter
            : nil,
        compareSecondFilter: logViewMode == .compareBranches
            ? branchCompareSecondFilter
            : nil,
        selection: logSelection,
        selectedIDs: logSelectedIDs,
        reflogRootPath: reflogRootPath.map(canonicalExternalLogPath),
        reflogSelection: reflogSelection,
        reflogSelectedIDs: persistedReflogSelectionIDs(
            entries: reflogEntries,
            selectedIDs: reflogSelectedIDs
        )
    )
}

private func saveCurrentLogTab() {
    let snapshot = currentLogTabSnapshot()
    if let index = logTabs.firstIndex(where: { $0.id == snapshot.id }) {
        logTabs[index] = snapshot
    } else {
        logTabs.insert(snapshot, at: 0)
    }
    activeLogTabID = snapshot.id
    if externalLogWindow {
        persistExternalLogTabs()
    }
}

private func applyLogTab(_ tab: LogTabDescriptor) {
    applyLogTabRootContext(tab.rootPath)
    logAggregateBranchFilters = tab.aggregateBranchFilters ?? []
    logAggregateRevisionRanges = (tab.aggregateRevisionRanges ?? tab.updateInfoRanges ?? [])
        .map(LogRootRevisionRange.init)
    if let aggregateRootPaths = tab.aggregateRootPaths {
        logAggregateRootPaths = Set(normalizedLogRootPaths(aggregateRootPaths))
    } else if !externalLogWindow {
        logAggregateRootPaths = []
    }
    logAggregateRepositories = [:]
    logAggregateLoadedCounts = [:]
    logAggregatePageCursors = [:]
    logViewMode = tab.viewMode
    let tabRevisions = tab.startRevisions.isEmpty
        ? (tab.startRevision.isEmpty ? [] : [tab.startRevision])
        : tab.startRevisions
    setLogStartRevisions(tabRevisions)
    logPathFilter = tab.pathFilter
    logPathFilterSelections = normalizedLogPathFilterSelections(tab.pathSelections)
    logVisibleRootPathsRaw = tab.visibleRootPathsRaw
    logAuthorFilter = tab.authorFilter
    logMessageFilter = tab.messageFilter
    logMessageRegex = tab.messageRegex
    logMessageMatchCase = tab.messageMatchCase
    logSinceText = tab.sinceText
    logUntilText = tab.untilText
    logCommandFilter = tab.commandFilter
    logCommandEntries = []
    hasMoreLogCommand = true
    logCommandError = nil
    logFollow = tab.follow
    logGraphSortModeRaw = tab.graphSortModeRaw
    compareRev1 = tab.compareRevision1
    compareRev2 = tab.compareRevision2
    compareRepositoryPath = tab.compareRepositoryPath
    compareWithWorkingTree = tab.compareWithWorkingTree
    branchCompareFirstFilter = tab.compareFirstFilter ?? BranchComparisonFilter()
    branchCompareSecondFilter = tab.compareSecondFilter ?? BranchComparisonFilter()
    if let path = tab.compareRepositoryPath,
       let comparisonRepo = try? openRepository(path: path) {
        activateComparisonRepository(comparisonRepo, rootPath: path)
    } else {
        activeCompareRepo = nil
    }
    logEntries = []
    isShowingCachedLogSnapshot = false
    logSelection = tab.selection
    logSelectedIDs = tab.selectedIDs
    logPageCursor = nil
    reflogEntries = []
    let restoredReflogRoot = tab.reflogRootPath
        ?? (tab.viewMode == .reflog ? tab.rootPath : nil)
    reflogRootPath = restoredReflogRoot.map(canonicalExternalLogPath)
    reflogRootRepo = nil
    reflogSelection = tab.reflogSelection
    reflogSelectedIDs = Set(tab.reflogSelectedIDs ?? [])
    logDetailCommit = nil
    reflogDetailCommit = nil
    reflogDetailCommits = []
    reflogDetailLoadTask?.cancel()
    reflogDetailLoadTask = nil
    hasMoreLog = true
}

private func clearLogActiveRootContext() {
    logActiveRootPath = nil
    logActiveRepo = nil
    logActiveBranches = []
    logActiveRemoteBranches = []
    logActiveRemotes = []
}

private func applyLogTabRootContext(_ rootPath: String?) {
    guard let rootPath,
          !rootPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        clearLogActiveRootContext()
        return
    }
    let normalizedRootPath = canonicalExternalLogPath(rootPath)
    let primaryRootPath = repo?.workdir().map(canonicalExternalLogPath)
    if normalizedRootPath == primaryRootPath {
        clearLogActiveRootContext()
        return
    }
    logActiveRootPath = normalizedRootPath
    guard let rootRepo = try? openRepository(path: normalizedRootPath) else {
        logActiveRepo = nil
        logActiveBranches = []
        logActiveRemoteBranches = []
        logActiveRemotes = []
        return
    }
    logActiveRepo = rootRepo
    logActiveBranches = (try? rootRepo.branchList()) ?? []
    logActiveRemoteBranches = (try? rootRepo.remoteBranchList()) ?? []
    logActiveRemotes = (try? rootRepo.remoteList()) ?? []
}

private func loadActiveLogTab(_ tab: LogTabDescriptor) {
    if tab.viewMode == .command {
        runLogCommand()
    } else if tab.viewMode == .compare {
        DispatchQueue.main.async { self.loadTreeChanges() }
    } else if tab.viewMode == .compareBranches {
        DispatchQueue.main.async { self.loadBranchComparison() }
    } else if tab.viewMode == .reflog {
        prepareReflogRoot()
    } else {
        loadLog()
    }
}

private func appendLogTabAndLoad(_ tab: LogTabDescriptor) {
    if let externalLogUIManager,
       !externalLogUIManager.registerUI(tab.id) {
        return
    }
    logTabs.append(tab)
    activeLogTabID = tab.id
    applyLogTab(tab)
    persistExternalLogTabs()
    loadActiveLogTab(tab)
}

func openAnotherLogTab() {
    saveCurrentLogTab()
    var tab = currentLogTabSnapshot()
    tab.id = UUID()
    tab.title = "Log \(logTabs.count + 1)"
    appendLogTabAndLoad(tab)
}

func switchLogTab(_ id: UUID) {
    guard id != currentLogTabID,
          let tab = logTabs.first(where: { $0.id == id }) else { return }
    let previousMode = logViewMode
    saveCurrentLogTab()
    activeLogTabID = id
    applyLogTab(tab)
    persistExternalLogTabs()
    if tab.viewMode == previousMode,
       tab.viewMode == .graph || tab.viewMode == .reflog {
        loadLog()
    } else if tab.viewMode == .compare {
        DispatchQueue.main.async { self.loadTreeChanges() }
    } else if tab.viewMode == .compareBranches {
        DispatchQueue.main.async { self.loadBranchComparison() }
    } else if tab.viewMode == .command {
        runLogCommand()
    }
}

func closeLogTab(_ id: UUID) {
    guard logTabs.count > 1,
          let index = logTabs.firstIndex(where: { $0.id == id }) else { return }
    let closingActive = id == currentLogTabID
    if closingActive { saveCurrentLogTab() }
    externalLogUIManager?.disposeUI(id)
    logTabs.remove(at: index)
    if !closingActive {
        persistExternalLogTabs()
        return
    }
    let previousMode = logViewMode
    let replacementIndex = min(index, logTabs.count - 1)
    let replacement = logTabs[replacementIndex]
    activeLogTabID = replacement.id
    applyLogTab(replacement)
    persistExternalLogTabs()
    if replacement.viewMode == previousMode,
       replacement.viewMode == .graph || replacement.viewMode == .reflog {
        reloadLogView()
    } else if replacement.viewMode == .compare {
        DispatchQueue.main.async { self.loadTreeChanges() }
    } else if replacement.viewMode == .compareBranches {
        DispatchQueue.main.async { self.loadBranchComparison() }
    } else if replacement.viewMode == .command {
        runLogCommand()
    }
}

func runLogCommand(reset: Bool = true) {
    logCommandTask?.cancel()
    logCommandGeneration += 1
    let generation = logCommandGeneration
    let tabID = currentLogTabID
    let arguments = tokenizeGitCommandLine(logCommandFilter)
    let pageLimit = 500
    let previousEntryCount = reset ? 0 : logCommandEntries.count
    let commandHasExplicitLimit = gitLogCommandHasExplicitLimit(arguments)
    let explicitCommandMaximum = gitLogCommandMaximum(arguments)
    let commandLimit = max(
        pageLimit,
        previousEntryCount + pageLimit,
        reset ? (explicitCommandMaximum ?? 0) : 0
    )
    let aggregateFilterRoots = normalizedLogRootPaths(
        logAggregateBranchFilters.map(\.rootPath)
            + logAggregateRevisionRanges.map(\.rootPath)
            + Array(logAggregateRootPaths)
    )
    let discoveredRootPaths = normalizedLogRootPaths(multiRoots.map(\.path))
    let hasStoredAggregateLog = !logAggregateBranchFilters.isEmpty
        || !logAggregateRevisionRanges.isEmpty
        || !logAggregateRootPaths.isEmpty
    let commandIsAggregate = hasStoredAggregateLog || discoveredRootPaths.count > 1
    let commandRootPaths: [String]
    if commandIsAggregate {
        let candidateRoots = aggregateFilterRoots.isEmpty
            ? discoveredRootPaths
            : aggregateFilterRoots
        commandRootPaths = reconciledLogVisibleRootPaths(
            allRoots: candidateRoots,
            raw: logVisibleRootFilterRaw(for: candidateRoots)
        ).sorted()
    } else if let commandRepository = logRepository ?? logActiveRepo ?? repo,
              let rootPath = commandRepository.workdir() {
        commandRootPaths = [canonicalExternalLogPath(rootPath)]
    } else {
        commandRootPaths = []
    }
    let requestedAggregateFilters = logAggregateBranchFilters
    let requestedAggregateRanges = logAggregateRevisionRanges
    let requestedAggregateRootPaths = logAggregateRootPaths
    let requestedVisibleRootPathsRaw = logVisibleRootPathsRaw
    let requestedDiscoveredRootPaths = discoveredRootPaths
    var commandRepositories: [(String, Repository)] = []
    for rootPath in commandRootPaths {
        if let cached = logAggregateRepositories[rootPath] {
            commandRepositories.append((rootPath, cached))
            continue
        }
        if let active = logActiveRepo,
           let activePath = active.workdir(),
           canonicalExternalLogPath(activePath) == rootPath {
            commandRepositories.append((rootPath, active))
            continue
        }
        if let current = repo,
           let currentPath = current.workdir(),
           canonicalExternalLogPath(currentPath) == rootPath {
            commandRepositories.append((rootPath, current))
            continue
        }
        if let opened = try? openRepository(path: rootPath) {
            commandRepositories.append((rootPath, opened))
        }
    }
    if commandRepositories.isEmpty,
       let commandRepository = logRepository ?? logActiveRepo ?? repo {
        commandRepositories = [(
            canonicalExternalLogPath(commandRepository.workdir() ?? ""),
            commandRepository
        )].filter { !$0.0.isEmpty }
    }
    guard !commandRepositories.isEmpty else {
        isLoadingLogCommand = false
        logCommandError = "No Git root is available for the command Log."
        return
    }
    logCommandIsAggregate = commandIsAggregate
    isLoadingLogCommand = true
    if reset {
        logCommandEntries = []
        logSelectedIDs = []
        logSelection = nil
    }
    hasMoreLogCommand = !commandHasExplicitLimit
    logCommandError = nil
    let task = Task.detached(priority: .userInitiated) { [commandRepositories] in
        do {
            var entriesByRoot: [[CommitInfo]] = []
            for (_, commandRepository) in commandRepositories {
                guard !Task.isCancelled else { return }
                entriesByRoot.append(
                    try commandRepository.logWithCommand(
                        commandArgs: arguments,
                        limit: UInt32(commandLimit)
                    )
                )
            }
            let entries = mergedLogCommandEntries(
                entriesByRoot,
                limit: commandLimit,
                aggregate: commandIsAggregate
            )
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard generation == self.logCommandGeneration,
                      self.externalLogTabIsAlive(tabID),
                      self.logViewMode == .command,
                      self.logCommandIsAggregate == commandIsAggregate,
                      self.logCommandEntries.count == previousEntryCount,
                      self.logAggregateBranchFilters == requestedAggregateFilters,
                      self.logAggregateRevisionRanges == requestedAggregateRanges,
                      self.logAggregateRootPaths == requestedAggregateRootPaths,
                      self.logVisibleRootPathsRaw == requestedVisibleRootPathsRaw,
                      normalizedLogRootPaths(self.multiRoots.map(\.path))
                          == requestedDiscoveredRootPaths else { return }
                self.isLoadingLogCommand = false
                self.logCommandEntries = entries
                self.hasMoreLogCommand = !commandHasExplicitLimit && entries.count >= commandLimit
            }
        } catch {
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard generation == self.logCommandGeneration,
                      self.externalLogTabIsAlive(tabID),
                      self.logViewMode == .command,
                      self.logCommandIsAggregate == commandIsAggregate,
                      self.logCommandEntries.count == previousEntryCount,
                      self.logAggregateBranchFilters == requestedAggregateFilters,
                      self.logAggregateRevisionRanges == requestedAggregateRanges,
                      self.logAggregateRootPaths == requestedAggregateRootPaths,
                      self.logVisibleRootPathsRaw == requestedVisibleRootPathsRaw,
                      normalizedLogRootPaths(self.multiRoots.map(\.path))
                          == requestedDiscoveredRootPaths else { return }
                self.isLoadingLogCommand = false
                self.logCommandError = errorMessage(error)
                if reset {
                    self.hasMoreLogCommand = false
                }
            }
        }
    }
    logCommandTask = task
}

/// Reflog belongs to one Git root even when the surrounding Log is showing a
/// multi-root aggregate. Selecting a root here also gives commit actions the
/// correct repository context for the revision they are about to recover.
func selectReflogRoot(_ rootPath: String, preservingSelection: Bool = false) {
    let trimmedPath = rootPath.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmedPath.isEmpty else { return }
    let normalizedPath = canonicalExternalLogPath(trimmedPath)
    let primaryPath = repo?.workdir().map(canonicalExternalLogPath)
    let rootRepo: Repository?
    if normalizedPath == primaryPath {
        rootRepo = repo
    } else {
        rootRepo = try? openRepository(path: normalizedPath)
    }
    guard let rootRepo else {
        feedbackCenter.error(
            "Reflog unavailable",
            detail: "Unable to open Git root: \(normalizedPath)",
            nextStep: "Refresh Git Roots and retry."
        )
        return
    }

    reflogRootPath = normalizedPath
    reflogRootRepo = rootRepo
    reflogLoadMoreTask?.cancel()
    reflogLoadMoreTask = nil
    isLoadingMoreReflog = false
    if !preservingSelection {
        reflogEntries = []
        reflogSelection = nil
        reflogSelectedIDs = []
        reflogDetailCommit = nil
        reflogDetailCommits = []
        reflogDetailLoadTask?.cancel()
        reflogDetailLoadTask = nil
    }
    logAggregateBranchFilters = []
    logAggregateRevisionRanges = []
    logAggregateRootPaths = []
    logAggregateRepositories = [:]
    logAggregateLoadedCounts = [:]
    logStartRevision = ""
    logStartRevisions = []
    logSelection = nil
    logSelectedIDs = []

    if normalizedPath == primaryPath {
        logActiveRootPath = nil
        logActiveRepo = nil
        logActiveBranches = []
        logActiveRemoteBranches = []
        logActiveRemotes = []
    } else {
        logActiveRootPath = normalizedPath
        logActiveRepo = rootRepo
        logActiveBranches = (try? rootRepo.branchList()) ?? []
        logActiveRemoteBranches = (try? rootRepo.remoteBranchList()) ?? []
        logActiveRemotes = (try? rootRepo.remoteList()) ?? []
    }
    loadReflog()
    if externalLogWindow {
        persistExternalLogTabs()
    }
}

func prepareReflogRoot() {
    let rootPath = reflogRootPath
        ?? logActiveRootPath
        ?? repo?.workdir()
        ?? availableReflogRootPaths.first
    guard let rootPath, !rootPath.isEmpty else {
        logError = "No Git root is available for Reflog."
        return
    }
    if reflogRootPath == rootPath, reflogRootRepo != nil {
        loadReflog()
    } else {
        selectReflogRoot(rootPath, preservingSelection: true)
    }
}

func loadReflog() {
    guard logViewMode == .reflog else { return }
    guard let rootPath = reflogRootPath, !rootPath.isEmpty else {
        prepareReflogRoot()
        return
    }
    reflogLoadTask?.cancel()
    reflogLoadMoreTask?.cancel()
    reflogLoadMoreTask = nil
    reflogGeneration += 1
    let generation = reflogGeneration
    let tabID = currentLogTabID
    let requestedRepo = reflogRootRepo
    let pageSize: UInt32 = 100
    isLoadingLog = true
    isLoadingMoreReflog = false
    reflogHasMore = false
    logError = nil

    let task = Task.detached(priority: .userInitiated) {
        do {
            let rootRepo: Repository
            if let requestedRepo {
                rootRepo = requestedRepo
            } else {
                rootRepo = try openRepository(path: rootPath)
            }
            let page = try rootRepo.reflogPage(limit: pageSize + 1, offset: 0)
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard generation == self.reflogGeneration,
                      self.externalLogTabIsAlive(tabID),
                      self.logViewMode == .reflog,
                      self.reflogRootPath == rootPath else { return }
                if self.reflogRootRepo == nil {
                    self.reflogRootRepo = rootRepo
                }
                let entries = Array(page.prefix(Int(pageSize)))
                let selectionState = reconciledReflogSelection(
                    entries: entries,
                    previousSelection: self.reflogSelection,
                    previousSelectedIDs: self.reflogSelectedIDs
                )
                self.reflogEntries = entries
                self.reflogSelection = selectionState.selection
                self.reflogSelectedIDs = selectionState.selectedIDs
                self.reflogHasMore = page.count > Int(pageSize)
                self.isLoadingLog = false
                self.logError = nil
                self.loadReflogCommitDetails()
            }
        } catch {
            await MainActor.run {
                guard generation == self.reflogGeneration,
                      self.externalLogTabIsAlive(tabID),
                      self.logViewMode == .reflog,
                      self.reflogRootPath == rootPath else { return }
                self.isLoadingLog = false
                self.reflogHasMore = false
                self.logError = errorMessage(error)
            }
        }
    }
    reflogLoadTask = task
}

/// Append older HEAD reflog records without replacing the current root or
/// selection. The extra record is only a has-more probe, so a page boundary
/// never needs a second request merely to discover that the file ended.
func loadMoreReflog() {
    guard logViewMode == .reflog,
          reflogHasMore,
          !isLoadingLog,
          !isLoadingMoreReflog,
          let rootPath = reflogRootPath,
          !rootPath.isEmpty else { return }

    reflogLoadMoreTask?.cancel()
    reflogGeneration += 1
    let generation = reflogGeneration
    let tabID = currentLogTabID
    let requestedRepo = reflogRootRepo
    let offset = reflogEntries.count
    let pageSize: UInt32 = 100
    isLoadingMoreReflog = true

    let task = Task.detached(priority: .userInitiated) {
        do {
            let rootRepo: Repository
            if let requestedRepo {
                rootRepo = requestedRepo
            } else {
                rootRepo = try openRepository(path: rootPath)
            }
            let page = try rootRepo.reflogPage(
                limit: pageSize + 1,
                offset: UInt32(offset)
            )
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard generation == self.reflogGeneration,
                      self.externalLogTabIsAlive(tabID),
                      self.logViewMode == .reflog,
                      self.reflogRootPath == rootPath else { return }
                let entries = appendedReflogEntries(
                    existing: self.reflogEntries,
                    page: Array(page.prefix(Int(pageSize)))
                )
                self.reflogEntries.append(contentsOf: entries)
                self.reflogHasMore = page.count > Int(pageSize)
                self.isLoadingMoreReflog = false
                self.loadReflogCommitDetails()
            }
        } catch {
            await MainActor.run {
                guard generation == self.reflogGeneration,
                      self.externalLogTabIsAlive(tabID),
                      self.logViewMode == .reflog,
                      self.reflogRootPath == rootPath else { return }
                self.isLoadingMoreReflog = false
                self.logError = errorMessage(error)
            }
        }
    }
    reflogLoadMoreTask = task
}

func reloadLogView() {
    if logViewMode == .command {
        runLogCommand()
    } else if logViewMode == .reflog {
        loadReflog()
    } else {
        loadLog()
    }
}

/// Mirrors VisiblePackRefresher's request coalescing at the SwiftUI boundary:
/// toggling Regex, Match Case, graph options or multiple branch heads in one
/// event turn produces one refresh request with the final state snapshot.
func scheduleLogRefresh() {
    logRefreshTask?.cancel()
    logRefreshTask = Task { @MainActor in
        await Task.yield()
        guard !Task.isCancelled else { return }
        logRefreshTask = nil
        loadLog()
    }
}

/// Paths structure-filter state is stored as recent groups of normalized,
/// root-qualified selections. Legacy `[[String]]` values are still accepted
/// and become shared selections that apply to every visible Git root.
func activeLogPathFilterSelections() -> [LogPathFilterSelection] {
    let normalized = normalizedLogPathFilterSelections(logPathFilterSelections)
    if !normalized.isEmpty {
        return normalized
    }
    return makeLogPathFilterSelections(from: normalizedLogPathFilters(logPathFilter))
}

func recentLogPathFilterSelections() -> [[LogPathFilterSelection]] {
    guard let data = logRecentPathFiltersRaw.data(using: .utf8) else { return [] }
    if let decoded = try? JSONDecoder().decode([[LogPathFilterSelection]].self, from: data) {
        return decoded.compactMap { values in
            let normalized = normalizedLogPathFilterSelections(values)
            return normalized.isEmpty ? nil : normalized
        }
    }
    guard let legacy = try? JSONDecoder().decode([[String]].self, from: data) else {
        return []
    }
    return legacy.compactMap { values in
        let normalized = makeLogPathFilterSelections(from: normalizedLogPathFilters(values.joined(separator: "\n")))
        return normalized.isEmpty ? nil : normalized
    }
}

func rememberLogPathFilterSelections(_ selections: [LogPathFilterSelection]) {
    let normalized = normalizedLogPathFilterSelections(selections)
    guard !normalized.isEmpty else { return }
    let updated = ([normalized] + recentLogPathFilterSelections().filter { $0 != normalized }).prefix(10)
    guard let data = try? JSONEncoder().encode(Array(updated)) else { return }
    logRecentPathFiltersRaw = String(decoding: data, as: UTF8.self)
}

func setLogPathFilterSelections(
    _ selections: [LogPathFilterSelection],
    remember: Bool = true
) {
    let normalized = normalizedLogPathFilterSelections(selections)
    if let projectPath,
       logTabs.first(where: { $0.id == currentLogTabID })?.updateInfoRanges != nil {
        GitUpdateInfoPathFilterSettings.save(
            logPathFilterEditorText(normalized),
            roots: logStructureFilterRootPaths,
            for: projectPath
        )
    }
    logPathFilterSelections = normalized
    logPathFilter = logPathFilterEditorText(normalized)
    if remember {
        rememberLogPathFilterSelections(normalized)
    }
    scheduleLogRefresh()
}

func setLogPathFilterPaths(_ paths: [String], remember: Bool = true) {
    setLogPathFilterSelections(makeLogPathFilterSelections(from: paths), remember: remember)
}

func applyManualLogPathFilter() {
    let roots = logStructureFilterRootPaths + availableReflogRootPaths
    setLogPathFilterSelections(parseLogPathFilterEditorText(logPathFilter, roots: roots))
}

func openLogPathsEditor() {
    logPathsEditorText = logPathFilterEditorText(activeLogPathFilterSelections())
    isLogPathsEditorPresented = true
}

func applyLogPathsEditor() {
    isLogPathsEditorPresented = false
    let roots = logStructureFilterRootPaths + availableReflogRootPaths
    setLogPathFilterSelections(parseLogPathFilterEditorText(logPathsEditorText, roots: roots))
}

func clearRecentLogPathFilters() {
    logRecentPathFiltersRaw = ""
}

func logPathTreeSelections() -> Set<LogPathFilterSelection> {
    let roots = normalizedLogRootPaths(
        logStructureFilterRootPaths.isEmpty ? availableReflogRootPaths : logStructureFilterRootPaths
    )
    var result = Set<LogPathFilterSelection>()
    for selection in activeLogPathFilterSelections() {
        if let rootPath = selection.rootPath {
            if roots.contains(rootPath) {
                result.insert(selection)
            }
        } else {
            for rootPath in roots {
                result.insert(LogPathFilterSelection(rootPath: rootPath, path: selection.path))
            }
        }
    }
    return normalizedLogTreeSelections(Array(result))
}

func openLogPathsTreeChooser() {
    let rootPaths = normalizedLogRootPaths(
        logStructureFilterRootPaths.isEmpty ? availableReflogRootPaths : logStructureFilterRootPaths
    )
    let roots = rootPaths.compactMap { rootPath -> LogPathChooserRoot? in
        guard let repository = try? openRepository(path: rootPath) else { return nil }
        return LogPathChooserRoot(path: rootPath, repository: repository)
    }
    guard !roots.isEmpty else {
        feedbackCenter.warning(
            "Paths filter unavailable",
            detail: "No Git root is available for selecting a path.",
            nextStep: "Open or refresh a Git repository and retry.",
            localized: false
        )
        return
    }
    logPathsTreeChooserRoots = roots
    logPathsTreeChooserSelections = logPathTreeSelections()
    isLogPathsTreeChooserPresented = true
}

func applyLogPathsTreeChooser() {
    isLogPathsTreeChooserPresented = false
    setLogPathFilterSelections(Array(logPathsTreeChooserSelections))
}

var logStructureFilterRootPaths: [String] {
    if isLogAggregate {
        return normalizedLogRootPaths(
            logAggregateBranchFilters.map(\.rootPath)
                + logAggregateRevisionRanges.map(\.rootPath)
                + Array(logAggregateRootPaths)
        )
    }
    return normalizedLogRootPaths([logRepository?.workdir()].compactMap { $0 })
}

var visibleLogStructureFilterRootPaths: Set<String> {
    reconciledLogVisibleRootPaths(
        allRoots: logStructureFilterRootPaths,
        raw: logVisibleRootFilterRaw(for: logStructureFilterRootPaths)
    )
}

private func logVisibleRootPersistenceScope(_ roots: [String]) -> String {
    normalizedLogRootPaths(roots).joined(separator: "\u{1f}")
}

private func persistedLogVisibleRootPaths(for roots: [String]) -> Set<String>? {
    guard let data = logVisibleRootPathsPersistedRaw.data(using: .utf8),
          let values = try? JSONDecoder().decode([String: [String]].self, from: data),
          let selected = values[logVisibleRootPersistenceScope(roots)] else {
        return nil
    }
    return Set(normalizedLogRootPaths(selected)).intersection(normalizedLogRootPaths(roots))
}

private func logVisibleRootFilterRaw(for roots: [String]) -> String {
    guard logVisibleRootPathsRaw.isEmpty,
          let selected = persistedLogVisibleRootPaths(for: roots) else {
        return logVisibleRootPathsRaw
    }
    return serializedLogVisibleRootPaths(selected: selected, allRoots: roots)
}

private func persistLogVisibleRootPaths(selected: Set<String>, allRoots: [String]) {
    let normalizedRoots = normalizedLogRootPaths(allRoots)
    let scope = logVisibleRootPersistenceScope(normalizedRoots)
    guard !scope.isEmpty else { return }
    var values = (try? JSONDecoder().decode(
        [String: [String]].self,
        from: logVisibleRootPathsPersistedRaw.data(using: .utf8) ?? Data()
    )) ?? [:]
    if selected == Set(normalizedRoots) {
        values.removeValue(forKey: scope)
    } else {
        values[scope] = normalizedLogRootPaths(Array(selected.intersection(Set(normalizedRoots))))
    }
    guard let data = try? JSONEncoder().encode(values) else { return }
    logVisibleRootPathsPersistedRaw = String(decoding: data, as: UTF8.self)
}

func setLogStructureFilterRoot(_ rootPath: String, visible: Bool) {
    let allRoots = logStructureFilterRootPaths
    guard allRoots.contains(rootPath) else { return }
    var selected = visibleLogStructureFilterRootPaths
    if visible {
        selected.insert(rootPath)
    } else {
        guard selected.count > 1 else { return }
        selected.remove(rootPath)
    }
    logVisibleRootPathsRaw = serializedLogVisibleRootPaths(selected: selected, allRoots: allRoots)
    persistLogVisibleRootPaths(selected: selected, allRoots: allRoots)
    loadLog()
}

func chooseLogPathFilter() {
    let roots = logStructureFilterRootPaths.isEmpty
        ? availableReflogRootPaths
        : logStructureFilterRootPaths
    guard let firstRoot = roots.first else {
        feedbackCenter.warning(
            "Paths filter unavailable",
            detail: "No Git root is available for selecting a path.",
            nextStep: "Open or refresh a Git repository and retry.",
            localized: false
        )
        return
    }

    let panel = NSOpenPanel()
    panel.canChooseDirectories = true
    panel.canChooseFiles = true
    panel.allowsMultipleSelection = true
    panel.canCreateDirectories = false
    panel.prompt = "Select Path"
    panel.directoryURL = URL(fileURLWithPath: logRepository?.workdir() ?? firstRoot)
    guard panel.runModal() == .OK, !panel.urls.isEmpty else { return }

    let normalizedRoots = logRootPathsDeepestFirst(roots)
    var selections: [LogPathFilterSelection] = []
    for url in panel.urls {
        guard let filter = relativeLogPathFilter(for: url, roots: roots) else {
            feedbackCenter.warning(
                "Path is outside the Git roots",
                detail: url.standardizedFileURL.path,
                nextStep: "Select files or folders inside one of the project's Git roots.",
                localized: false
            )
            return
        }
        if !filter.isEmpty {
            let selectedPath = url.standardizedFileURL.path
            let rootPath = normalizedRoots.first(where: {
                selectedPath == $0 || selectedPath.hasPrefix($0 + "/")
            })
            selections.append(LogPathFilterSelection(rootPath: rootPath, path: filter))
        }
    }
    guard !selections.isEmpty else {
        setLogPathFilterPaths([])
        return
    }
    setLogPathFilterSelections(activeLogPathFilterSelections() + selections)
}

func clearLogPathFilter() {
    guard !activeLogPathFilterSelections().isEmpty else { return }
    setLogPathFilterSelections([], remember: false)
}

func loadLog(reset: Bool = true) {
    if logViewMode == .reflog {
        loadReflog()
        return
    }
    if isLogAggregate {
        loadAggregatedLog(reset: reset)
        return
    }
    guard let repo = logRepository else { return }
    // Phase 5 取消行为:新加载使旧请求结果失效(切换条件后不覆盖新结果)
    logLoadTask?.cancel()
    logGeneration += 1
    let generation = logGeneration
    let tabID = currentLogTabID
    let activePathSelections = activeLogPathFilterSelections()
    let pathFilters = logPathFilterPathsForRoot(
        activePathSelections,
        rootPath: repo.workdir() ?? ""
    ) ?? []
    let hasActivePathFilter = !activePathSelections.isEmpty
    let startRevisions = activeLogStartRevisions
    let start = startRevisions.count == 1 ? startRevisions[0] : ""
    let author = logAuthorFilter.trimmingCharacters(in: .whitespaces)
    let message = logMessageFilter.trimmingCharacters(in: .whitespaces)
    let messageRegex = logMessageRegex
    let messageMatchCase = logMessageMatchCase
    let hashQuery = isCommitHashQuery(message) ? message.lowercased() : nil
    let since = parseLogSince(logSinceText)
    let until = parseLogUntil(logUntilText)
    let noMerges = logNoMerges
    let follow = logFollow
    let querySortModeRaw = logGraphSortModeRaw
    let sortMode = LogGraphSortChoice(rawValue: logGraphSortModeRaw)?.engineValue
        ?? LogGraphSortChoice.byCommitDate.engineValue
    let effectiveStart = hashQuery ?? start
    let effectiveMessage = hashQuery == nil ? message : ""
    let dateText = logSinceText.trimmingCharacters(in: .whitespacesAndNewlines)
    let untilText = logUntilText.trimmingCharacters(in: .whitespacesAndNewlines)
    let canPage = !hasActivePathFilter && startRevisions.isEmpty && effectiveStart.isEmpty
        && author.isEmpty && effectiveMessage.isEmpty
        && since == nil && dateText.isEmpty && until == nil && untilText.isEmpty && !noMerges
    // VisiblePackRefresher can request more commits with filters applied. The
    // engine keeps the same revision/filter state and resumes from afterId;
    // short-hash lookup is intentionally a single-row query, and a path
    // selection that does not belong to this root has no continuation.
    let canContinueWithCursor = hashQuery == nil
        && !(hasActivePathFilter && pathFilters.isEmpty)
    if (!dateText.isEmpty && since == nil) || (!untilText.isEmpty && until == nil) {
        logError = "Date filters must be YYYY-MM-DD, YYYY-MM-DD HH:mm, or Unix seconds."
        isLoadingLog = false
        isLoadingMoreLog = false
        return
    }
    if let since, let until, since >= until {
        logError = "The Since date must be earlier than the Until date."
        isLoadingLog = false
        isLoadingMoreLog = false
        return
    }
    let requestedCursor = reset ? nil : logPageCursor
    if reset {
        isLoadingLog = true
        isLoadingMoreLog = false
        isShowingCachedLogSnapshot = false
        logDetailCommit = nil
        reflogDetailCommit = nil
        reflogDetailCommits = []
        reflogSelectedIDs = []
        reflogSelection = nil
        reflogDetailLoadTask?.cancel()
        reflogDetailLoadTask = nil
    } else {
        isLoadingMoreLog = true
    }
    let pageLimit = reset ? initialLogPageLimit : continuationLogPageLimit
    let rootPath = canonicalExternalLogPath(repo.workdir() ?? "")
    let queryFingerprint = persistedLogCacheQueryFingerprint(
        rootPath: rootPath,
        pathFilters: pathFilters,
        startRevisions: effectiveStart.isEmpty ? startRevisions : [effectiveStart],
        author: author,
        message: effectiveMessage,
        messageRegex: messageRegex,
        messageMatchCase: messageMatchCase,
        since: dateText,
        until: untilText,
        noMerges: noMerges,
        follow: follow,
        sortMode: querySortModeRaw,
        pageLimit: pageLimit
    )
    let graphQueryFingerprint = persistedLogGraphQueryFingerprint(
        rootPath: rootPath,
        pathFilters: pathFilters,
        startRevisions: effectiveStart.isEmpty ? startRevisions : [effectiveStart],
        author: author,
        message: effectiveMessage,
        messageRegex: messageRegex,
        messageMatchCase: messageMatchCase,
        since: dateText,
        until: untilText,
        noMerges: noMerges,
        follow: follow,
        sortMode: querySortModeRaw
    )
    let canRestoreLogSnapshot = !(hasActivePathFilter && pathFilters.isEmpty)
    let cachedEntry = reset && !rootPath.isEmpty && canRestoreLogSnapshot
        ? loadPersistedLogCache(rootPath: rootPath)
        : nil
    let cachedGraphEntry = reset && !rootPath.isEmpty && canRestoreLogSnapshot
        ? loadPersistedLogGraph(rootPath: rootPath)
        : nil
    let task = Task.detached(priority: .userInitiated) {
        do {
            let refsToken = persistedLogRefsToken(repo: repo, rootPath: rootPath)
            let restoredGraph: PersistedLogGraphRestore? = if reset,
                                                              let cachedGraphEntry,
                                                              let refsToken {
                cachedGraphEntry.restoredIfValid(
                    rootPath: rootPath,
                    queryFingerprint: graphQueryFingerprint,
                    refsToken: refsToken
                )
            } else {
                nil
            }
            if let restoredGraph {
                guard !Task.isCancelled else { return }
                await MainActor.run {
                    guard generation == self.logGeneration,
                          self.externalLogTabIsAlive(tabID),
                          self.isActiveLogRepository(repo) else { return }
                    self.logEntries = restoredGraph.commits
                    self.logPageCursor = restoredGraph.cursor
                    self.hasMoreLog = restoredGraph.hasMore
                    self.logSelection = restoredGraph.commits.first?.id
                    self.logSelectedIDs = restoredGraph.commits.first.map { [$0.id] } ?? []
                    self.isShowingCachedLogSnapshot = true
                }
            } else if reset,
                      let cachedEntry,
                      let refsToken,
                      let cachedLog = cachedEntry.restoredCommitsIfValid(
                          rootPath: rootPath,
                          queryFingerprint: queryFingerprint,
                          refsToken: refsToken
                      ) {
                guard !Task.isCancelled else { return }
                await MainActor.run {
                    guard generation == self.logGeneration,
                          self.externalLogTabIsAlive(tabID),
                          self.isActiveLogRepository(repo) else { return }
                    self.logEntries = cachedLog
                    self.logPageCursor = cachedLog.last?.id
                    self.hasMoreLog = canPage && cachedLog.count >= Int(pageLimit)
                    self.isShowingCachedLogSnapshot = true
                }
            }
            // A completed snapshot still needs a fresh first-page read on an
            // explicit reset/refresh. A partial snapshot can continue from its
            // saved cursor without replaying all previously loaded pages.
            let cursor = reset
                ? (restoredGraph?.hasMore == true ? restoredGraph?.cursor : nil)
                : requestedCursor
            let log: [CommitInfo]
            if canPage {
                log = try repo.logWithSort(
                    path: nil,
                    limit: pageLimit,
                    follow: follow,
                    afterId: cursor,
                    sortMode: sortMode
                )
            } else if hasActivePathFilter && pathFilters.isEmpty {
                log = []
            } else {
                let loaded = try repo.logFilteredWithPathsWithMessageAndDateOptionsForRevisionsWithAfterId(
                    paths: pathFilters,
                    limit: pageLimit,
                    follow: follow,
                    startRevs: effectiveStart.isEmpty ? startRevisions : [effectiveStart],
                    author: author.isEmpty ? nil : author,
                    since: since,
                    until: until,
                    message: effectiveMessage.isEmpty ? nil : effectiveMessage,
                    messageRegex: messageRegex,
                    messageMatchCase: messageMatchCase,
                    noMerges: noMerges,
                    sortMode: sortMode,
                    afterId: cursor
                )
                // A short object id is a revision lookup, not a message
                // substring search. Start the walk at the resolved commit and
                // keep only the requested row in the result table.
                log = if let hashQuery {
                    loaded.filter { $0.id.lowercased().hasPrefix(hashQuery) }
                } else {
                    loaded
                }
            }
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard !Task.isCancelled,
                      generation == self.logGeneration,
                      self.externalLogTabIsAlive(tabID),
                      self.isActiveLogRepository(repo) else { return } // 过期结果丢弃
                if reset {
                    let previousSelection = self.logSelection
                    let previousSelections = self.logSelectedIDs
                    var restoredEntries = restoredGraph?.commits ?? []
                    let restoredIDs = Set(restoredEntries.map(\.id))
                    restoredEntries.append(contentsOf: log.filter { !restoredIDs.contains($0.id) })
                    self.logEntries = restoredEntries
                    self.isShowingCachedLogSnapshot = false
                    // Keep the current row when a refresh still contains it;
                    // otherwise select the first visible revision. Refresh
                    // changes the model, not the user's context.
                    let retainedSelections = restoredEntries.filter { commit in
                        previousSelections.contains { selectedID in
                            commit.id == selectedID
                                || commit.id.hasPrefix(selectedID)
                                || selectedID.hasPrefix(commit.id)
                        }
                    }
                    if !retainedSelections.isEmpty {
                        self.logSelectedIDs = Set(retainedSelections.map(\.id))
                        self.logSelection = retainedSelections.first(where: { $0.id == previousSelection })?.id
                            ?? retainedSelections.first?.id
                    } else if let selectedID = matchingLogCommitID(
                        requestedID: previousSelection,
                        in: restoredEntries
                    ) {
                        self.logSelection = selectedID
                        self.logSelectedIDs = [selectedID]
                    } else {
                        self.logSelection = restoredEntries.first?.id
                        self.logSelectedIDs = restoredEntries.first.map { Set([$0.id]) } ?? []
                    }
                    self.logPageCursor = log.last?.id ?? restoredGraph?.cursor
                } else {
                    let oldIds = Set(self.logEntries.map(\.id))
                    self.logEntries.append(contentsOf: log.filter { !oldIds.contains($0.id) })
                    self.logPageCursor = log.last?.id ?? self.logPageCursor
                }
                self.hasMoreLog = if let restoredGraph {
                    restoredGraph.hasMore && log.count >= Int(pageLimit)
                } else {
                    canContinueWithCursor && log.count >= Int(pageLimit)
                }
                self.isLoadingMoreLog = false
                if reset { self.isLoadingLog = false }
                if reset, let refsToken {
                    savePersistedLogCache(
                        PersistedLogCacheEntry(
                            rootPath: rootPath,
                            queryFingerprint: queryFingerprint,
                            refsToken: refsToken,
                            commits: log
                        )
                    )
                    savePersistedLogGraph(
                        PersistedLogGraphEntry(
                            rootPath: rootPath,
                            queryFingerprint: graphQueryFingerprint,
                            refsToken: refsToken,
                            commits: self.logEntries,
                            cursor: self.logPageCursor,
                            hasMore: self.hasMoreLog
                        )
                    )
                } else if let refsToken {
                    savePersistedLogGraph(
                        PersistedLogGraphEntry(
                            rootPath: rootPath,
                            queryFingerprint: graphQueryFingerprint,
                            refsToken: refsToken,
                            commits: self.logEntries,
                            cursor: self.logPageCursor,
                            hasMore: self.hasMoreLog
                        )
                    )
                }
                self.logError = nil
            }
        } catch {
            await MainActor.run {
                guard !Task.isCancelled,
                      generation == self.logGeneration,
                      self.externalLogTabIsAlive(tabID),
                      self.isActiveLogRepository(repo) else { return }
                self.logError = self.isShowingCachedLogSnapshot
                    ? "Refresh failed; showing cached history. \(errorMessage(error))"
                    : errorMessage(error)
                self.isLoadingMoreLog = false
                if reset { self.isLoadingLog = false }
            }
        }
    }
    logLoadTask = task
}

private struct AggregatedLogRootResult {
    let rootPath: String
    let repository: Repository
    let commits: [CommitInfo]
    let queryFingerprint: String
    let graphQueryFingerprint: String
    let refsToken: String?
    let cursor: String?
    let hasMore: Bool
}

nonisolated private func flattenedAggregatedLogEntries(
    _ results: [AggregatedLogRootResult]
) -> [CommitInfo] {
    var entries: [CommitInfo] = []
    var seen = Set<String>()
    for result in results {
        for commit in result.commits {
            var flatCommit = commit
            flatCommit.repositoryPath = result.rootPath
            flatCommit.lane = 0
            flatCommit.parentLanes = []
            let key = "\(flatCommit.repositoryPath ?? result.rootPath)\u{1f}\(flatCommit.id)"
            if seen.insert(key).inserted {
                entries.append(flatCommit)
            }
        }
    }
    return entries.sorted {
        if $0.time != $1.time { return $0.time > $1.time }
        let leftRoot = $0.repositoryPath ?? ""
        let rightRoot = $1.repositoryPath ?? ""
        if leftRoot != rightRoot { return leftRoot < rightRoot }
        return $0.id < $1.id
    }
}

/// Loads one filtered VCS Log query per selected root and merges the rows by
/// `(repositoryPath, object id)`. Git's graph lanes are intentionally cleared:
/// lanes are meaningful inside one repository only, so drawing them across
/// roots would create false parent edges. The table remains fully selectable,
/// sortable, and diff-capable while each row keeps its owning repository.
private func loadAggregatedLog(reset: Bool) {
    logLoadTask?.cancel()
    logGeneration += 1
    let generation = logGeneration
    let filters = logAggregateBranchFilters
    let revisionRanges = logAggregateRevisionRanges
    let aggregateRootPaths = logAggregateRootPaths
    let providerSession = externalLogProviderSession
    let logManager = externalLogUIManager
    let tabID = currentLogTabID
    let allFilterByRoot: [String: [String]]
    if !revisionRanges.isEmpty {
        allFilterByRoot = Dictionary(grouping: revisionRanges, by: \LogRootRevisionRange.rootPath)
            .mapValues { ranges in
                ranges.map { "\($0.oldRevision)..\($0.newRevision)" }
            }
    } else if !filters.isEmpty {
        allFilterByRoot = Dictionary(grouping: filters, by: \LogRootBranchFilter.rootPath)
            .mapValues { $0.map(\.branch) }
    } else {
        // An external Git Log window with no branch/range filter means all
        // refs in each selected root. The Rust engine deliberately preserves
        // that default when startRevs is empty.
        allFilterByRoot = Dictionary(uniqueKeysWithValues: aggregateRootPaths.map {
            ($0, [String]())
        })
    }
    let aggregateRoots = Array(allFilterByRoot.keys)
    let visibleRootPaths = reconciledLogVisibleRootPaths(
        allRoots: aggregateRoots,
        raw: logVisibleRootFilterRaw(for: aggregateRoots)
    )
    let filterByRoot = allFilterByRoot.filter { visibleRootPaths.contains($0.key) }
    let visibleRootPathsRaw = logVisibleRootPathsRaw
    let visibleRootPathsPersistedRaw = logVisibleRootPathsPersistedRaw
    let activePathSelections = activeLogPathFilterSelections()
    let pathFiltersByRoot = Dictionary(uniqueKeysWithValues: allFilterByRoot.keys.map { rootPath in
        (rootPath, logPathFilterPathsForRoot(activePathSelections, rootPath: rootPath) ?? [])
    })
    let rootsWithoutMatchingPathFilter = Set(
        activePathSelections.isEmpty
            ? []
            : pathFiltersByRoot.compactMap { $0.value.isEmpty ? $0.key : nil }
    )
    let author = logAuthorFilter.trimmingCharacters(in: .whitespaces)
    let message = logMessageFilter.trimmingCharacters(in: .whitespaces)
    let messageRegex = logMessageRegex
    let messageMatchCase = logMessageMatchCase
    let hashQuery = isCommitHashQuery(message) ? message.lowercased() : nil
    let since = parseLogSince(logSinceText)
    let until = parseLogUntil(logUntilText)
    let noMerges = logNoMerges
    let follow = logFollow
    let querySortModeRaw = logGraphSortModeRaw
    let sortMode = LogGraphSortChoice(rawValue: logGraphSortModeRaw)?.engineValue
        ?? LogGraphSortChoice.byCommitDate.engineValue
    let dateText = logSinceText.trimmingCharacters(in: .whitespacesAndNewlines)
    let untilText = logUntilText.trimmingCharacters(in: .whitespacesAndNewlines)
    if (!dateText.isEmpty && since == nil) || (!untilText.isEmpty && until == nil) {
        logError = "Date filters must be YYYY-MM-DD, YYYY-MM-DD HH:mm, or Unix seconds."
        isLoadingLog = false
        isLoadingMoreLog = false
        return
    }
    if let since, let until, since >= until {
        logError = "The Since date must be earlier than the Until date."
        isLoadingLog = false
        isLoadingMoreLog = false
        return
    }
    if reset {
        isLoadingLog = true
        isLoadingMoreLog = false
        isShowingCachedLogSnapshot = false
        logAggregateLoadedCounts = [:]
        logAggregatePageCursors = [:]
        logDetailCommit = nil
        logAggregateRepositories = [:]
        logCherryPickedCommitIDs = []
        logCherryPickComparisonReady = false
        logCherryPickComparisonCompletedRoots = 0
        logCherryPickComparisonTotalRoots = 0
    } else {
        isLoadingMoreLog = true
    }
    let pageCursors = reset ? [:] : logAggregatePageCursors
    let pageSize = reset ? Int(initialLogPageLimit) : Int(continuationLogPageLimit)
    let task = Task.detached(priority: .userInitiated) {
        do {
            var requests: [(
                rootPath: String,
                repository: Repository,
                startRevisions: [String],
                limit: UInt32,
                afterID: String?,
                queryFingerprint: String,
                graphQueryFingerprint: String,
                refsToken: String?,
                cachedCommits: [CommitInfo]?,
                cachedGraph: PersistedLogGraphRestore?
            )] = []
            for rootPath in filterByRoot.keys.sorted() {
                guard !Task.isCancelled else { return }
                let rootRepo: Repository
                if let logManager {
                    guard let sessionRepository = logManager.repository(for: rootPath) else {
                        return
                    }
                    rootRepo = sessionRepository
                } else if let providerSession {
                    guard let sessionRepository = providerSession.repository(for: rootPath) else {
                        return
                    }
                    rootRepo = sessionRepository
                } else {
                    rootRepo = try openRepository(path: rootPath)
                }
                let startRevisions = hashQuery.map { [$0] } ?? filterByRoot[rootPath, default: []]
                let limit = UInt32(max(1, pageSize))
                let rootPathFilters = pathFiltersByRoot[rootPath] ?? []
                let queryFingerprint = persistedLogCacheQueryFingerprint(
                    rootPath: rootPath,
                    pathFilters: rootPathFilters,
                    startRevisions: startRevisions,
                    author: author,
                    message: hashQuery == nil ? message : "",
                    messageRegex: messageRegex,
                    messageMatchCase: messageMatchCase,
                    since: dateText,
                    until: untilText,
                    noMerges: noMerges,
                    follow: follow,
                    sortMode: querySortModeRaw,
                    pageLimit: limit
                )
                let graphQueryFingerprint = persistedLogGraphQueryFingerprint(
                    rootPath: rootPath,
                    pathFilters: rootPathFilters,
                    startRevisions: startRevisions,
                    author: author,
                    message: hashQuery == nil ? message : "",
                    messageRegex: messageRegex,
                    messageMatchCase: messageMatchCase,
                    since: dateText,
                    until: untilText,
                    noMerges: noMerges,
                    follow: follow,
                    sortMode: querySortModeRaw
                )
                let refsToken = persistedLogRefsToken(repo: rootRepo, rootPath: rootPath)
                let cachedGraph: PersistedLogGraphRestore?
                if reset,
                   !rootsWithoutMatchingPathFilter.contains(rootPath),
                   let cachedEntry = loadPersistedLogGraph(rootPath: rootPath),
                   let refsToken {
                    cachedGraph = cachedEntry.restoredIfValid(
                        rootPath: rootPath,
                        queryFingerprint: graphQueryFingerprint,
                        refsToken: refsToken
                    )
                } else {
                    cachedGraph = nil
                }
                let afterID = if reset {
                    cachedGraph?.hasMore == true ? cachedGraph?.cursor : nil
                } else {
                    pageCursors[rootPath]
                }
                let cachedCommits: [CommitInfo]?
                if reset,
                   cachedGraph == nil,
                   !rootsWithoutMatchingPathFilter.contains(rootPath),
                   let cachedEntry = loadPersistedLogCache(rootPath: rootPath),
                   let refsToken {
                    cachedCommits = cachedEntry.restoredCommitsIfValid(
                        rootPath: rootPath,
                        queryFingerprint: queryFingerprint,
                        refsToken: refsToken
                    )
                } else {
                    cachedCommits = nil
                }
                requests.append((
                    rootPath: rootPath,
                    repository: rootRepo,
                    startRevisions: startRevisions,
                    limit: limit,
                    afterID: afterID,
                    queryFingerprint: queryFingerprint,
                    graphQueryFingerprint: graphQueryFingerprint,
                    refsToken: refsToken,
                    cachedCommits: cachedCommits,
                    cachedGraph: cachedGraph
                ))
            }

            let cachedResults = requests.compactMap { request -> AggregatedLogRootResult? in
                if let cachedGraph = request.cachedGraph {
                    return AggregatedLogRootResult(
                        rootPath: request.rootPath,
                        repository: request.repository,
                        commits: cachedGraph.commits,
                        queryFingerprint: request.queryFingerprint,
                        graphQueryFingerprint: request.graphQueryFingerprint,
                        refsToken: request.refsToken,
                        cursor: cachedGraph.cursor,
                        hasMore: cachedGraph.hasMore
                    )
                }
                guard let cachedCommits = request.cachedCommits else { return nil }
                return AggregatedLogRootResult(
                    rootPath: request.rootPath,
                    repository: request.repository,
                    commits: cachedCommits,
                    queryFingerprint: request.queryFingerprint,
                    graphQueryFingerprint: request.graphQueryFingerprint,
                    refsToken: request.refsToken,
                    cursor: cachedCommits.last?.id,
                    hasMore: cachedCommits.count >= Int(initialLogPageLimit)
                )
            }
            let cachedEntriesSnapshot = flattenedAggregatedLogEntries(cachedResults)
            let cachedCountsSnapshot = Dictionary(
                uniqueKeysWithValues: cachedResults.map { ($0.rootPath, $0.commits.count) }
            )
            let cachedCursorsSnapshot = Dictionary(
                uniqueKeysWithValues: cachedResults.compactMap { result in
                    result.cursor.map { (result.rootPath, $0) }
                }
            )
            let cachedRepositoriesSnapshot = Dictionary(
                uniqueKeysWithValues: cachedResults.map { ($0.rootPath, $0.repository) }
            )
            let cachedHasMoreSnapshot = cachedResults.contains { $0.hasMore }
            if reset, !cachedResults.isEmpty {
                guard !Task.isCancelled else { return }
                await MainActor.run {
                    guard generation == self.logGeneration,
                          self.externalLogTabIsAlive(tabID),
                          !(self.externalLogWindow && self.externalLogSessionDisposed),
                          self.logAggregateBranchFilters == filters,
                          self.logAggregateRevisionRanges == revisionRanges,
                          self.logAggregateRootPaths == aggregateRootPaths,
                          self.logVisibleRootPathsRaw == visibleRootPathsRaw,
                          self.logVisibleRootPathsPersistedRaw == visibleRootPathsPersistedRaw else { return }
                    self.logEntries = cachedEntriesSnapshot
                    self.logAggregateRepositories = cachedRepositoriesSnapshot
                    self.logAggregateLoadedCounts = cachedCountsSnapshot
                    self.logAggregatePageCursors = cachedCursorsSnapshot
                    self.logSelection = cachedEntriesSnapshot.first.map(self.logCommitIdentity)
                    self.logSelectedIDs = cachedEntriesSnapshot.first.map { [self.logCommitIdentity($0)] } ?? []
                    self.hasMoreLog = cachedHasMoreSnapshot
                    self.isShowingCachedLogSnapshot = true
                }
            }

            var results: [AggregatedLogRootResult] = []
            for request in requests {
                guard !Task.isCancelled else { return }
                let rootPath = request.rootPath
                let rootRepo = request.repository
                let loaded: [CommitInfo]
                if rootsWithoutMatchingPathFilter.contains(rootPath) {
                    loaded = []
                } else {
                    loaded = try rootRepo.logFilteredWithPathsWithMessageAndDateOptionsForRevisionsWithAfterId(
                        paths: pathFiltersByRoot[rootPath] ?? [],
                        limit: request.limit,
                        follow: follow,
                        startRevs: request.startRevisions,
                        author: author.isEmpty ? nil : author,
                        since: since,
                        until: until,
                        message: hashQuery == nil && !message.isEmpty ? message : nil,
                        messageRegex: messageRegex,
                        messageMatchCase: messageMatchCase,
                        noMerges: noMerges,
                        sortMode: sortMode,
                        afterId: request.afterID
                    )
                }
                let commits = if let hashQuery {
                    loaded.filter { $0.id.lowercased().hasPrefix(hashQuery) }
                } else {
                    loaded
                }
                let rootScopedCommits = commits.map { commit in
                    var rootScopedCommit = commit
                    rootScopedCommit.repositoryPath = rootPath
                    return rootScopedCommit
                }
                let hasMore = if request.cachedGraph != nil {
                    request.cachedGraph!.hasMore && commits.count >= Int(request.limit)
                } else {
                    commits.count >= Int(request.limit)
                }
                let cursor = if let cachedGraph = request.cachedGraph,
                                !cachedGraph.hasMore {
                    cachedGraph.cursor
                } else {
                    rootScopedCommits.last?.id ?? request.cachedGraph?.cursor
                }
                results.append(AggregatedLogRootResult(
                    rootPath: rootPath,
                    repository: rootRepo,
                    commits: rootScopedCommits,
                    queryFingerprint: request.queryFingerprint,
                    graphQueryFingerprint: request.graphQueryFingerprint,
                    refsToken: request.refsToken,
                    cursor: cursor,
                    hasMore: hasMore
                ))
            }
            guard !Task.isCancelled else { return }
            let loadedResults = results
            await MainActor.run {
                guard !Task.isCancelled,
                      generation == self.logGeneration,
                      self.externalLogTabIsAlive(tabID),
                      !(self.externalLogWindow && self.externalLogSessionDisposed),
                      self.logAggregateBranchFilters == filters,
                      self.logAggregateRevisionRanges == revisionRanges,
                      self.logAggregateRootPaths == aggregateRootPaths,
                      self.logVisibleRootPathsRaw == visibleRootPathsRaw,
                      self.logVisibleRootPathsPersistedRaw == visibleRootPathsPersistedRaw else { return }
                var visible: [CommitInfo] = reset ? cachedEntriesSnapshot : self.logEntries
                var cursors = reset ? cachedCursorsSnapshot : self.logAggregatePageCursors
                var repositories = reset
                    ? (self.externalLogUIManager?.repositories(for: aggregateRoots)
                        ?? self.externalLogProviderSession?.repositories(for: aggregateRoots)
                        ?? cachedRepositoriesSnapshot)
                    : self.logAggregateRepositories
                for result in loadedResults {
                    repositories[result.rootPath] = result.repository
                    visible.append(contentsOf: result.commits.map { commit in
                        var flatCommit = commit
                        flatCommit.lane = 0
                        flatCommit.parentLanes = []
                        return flatCommit
                    })
                    if let cursor = result.cursor {
                        cursors[result.rootPath] = cursor
                    }
                }
                var deduplicated: [CommitInfo] = []
                var seen = Set<String>()
                for commit in visible.sorted(by: {
                    if $0.time != $1.time { return $0.time > $1.time }
                    let leftRoot = $0.repositoryPath ?? ""
                    let rightRoot = $1.repositoryPath ?? ""
                    if leftRoot != rightRoot { return leftRoot < rightRoot }
                    return $0.id < $1.id
                }) {
                    let key = "\(commit.repositoryPath ?? "")\u{1f}\(commit.id)"
                    if seen.insert(key).inserted {
                        deduplicated.append(commit)
                    }
                }
                var counts: [String: Int] = [:]
                for commit in deduplicated {
                    counts[commit.repositoryPath ?? "", default: 0] += 1
                }
                let previousSelection = self.logSelection
                let previousSelections = self.logSelectedIDs
                self.logEntries = deduplicated
                self.logAggregateRepositories = repositories
                self.logAggregateLoadedCounts = counts
                self.logAggregatePageCursors = cursors
                self.logPageCursor = nil
                self.hasMoreLog = loadedResults.contains { $0.hasMore }
                let retained = deduplicated.filter { commit in
                    let identity = self.logCommitIdentity(commit)
                    return previousSelections.contains(identity) || identity == previousSelection
                }
                if let first = retained.first {
                    self.logSelection = self.logCommitIdentity(first)
                    self.logSelectedIDs = Set(retained.map(self.logCommitIdentity))
                } else if let first = deduplicated.first {
                    self.logSelection = self.logCommitIdentity(first)
                    self.logSelectedIDs = [self.logCommitIdentity(first)]
                } else {
                    self.logSelection = nil
                    self.logSelectedIDs = []
                }
                self.isLoadingMoreLog = false
                if reset { self.isLoadingLog = false }
                self.isShowingCachedLogSnapshot = false
                if reset {
                    for result in loadedResults {
                        if let refsToken = result.refsToken {
                            savePersistedLogCache(
                                PersistedLogCacheEntry(
                                    rootPath: result.rootPath,
                                    queryFingerprint: result.queryFingerprint,
                                    refsToken: refsToken,
                                    commits: result.commits
                                )
                            )
                            let rootCommits = deduplicated.filter {
                                ($0.repositoryPath ?? "") == result.rootPath
                            }
                            savePersistedLogGraph(
                                PersistedLogGraphEntry(
                                    rootPath: result.rootPath,
                                    queryFingerprint: result.graphQueryFingerprint,
                                    refsToken: refsToken,
                                    commits: rootCommits,
                                    cursor: result.cursor,
                                    hasMore: result.hasMore
                                )
                            )
                        }
                    }
                } else {
                    for result in loadedResults {
                        if let refsToken = result.refsToken {
                            let rootCommits = deduplicated.filter {
                                ($0.repositoryPath ?? "") == result.rootPath
                            }
                            savePersistedLogGraph(
                                PersistedLogGraphEntry(
                                    rootPath: result.rootPath,
                                    queryFingerprint: result.graphQueryFingerprint,
                                    refsToken: refsToken,
                                    commits: rootCommits,
                                    cursor: result.cursor,
                                    hasMore: result.hasMore
                                )
                            )
                        }
                    }
                }
                self.logError = nil
                self.refreshCherryPickedHighlights()
            }
        } catch {
            await MainActor.run {
                guard !Task.isCancelled,
                      generation == self.logGeneration,
                      self.externalLogTabIsAlive(tabID),
                      !(self.externalLogWindow && self.externalLogSessionDisposed),
                      self.logAggregateBranchFilters == filters,
                      self.logAggregateRevisionRanges == revisionRanges,
                      self.logAggregateRootPaths == aggregateRootPaths,
                      self.logVisibleRootPathsRaw == visibleRootPathsRaw,
                      self.logVisibleRootPathsPersistedRaw == visibleRootPathsPersistedRaw else { return }
                self.logError = self.isShowingCachedLogSnapshot
                    ? "Refresh failed; showing cached history. \(errorMessage(error))"
                    : errorMessage(error)
                self.isLoadingMoreLog = false
                if reset { self.isLoadingLog = false }
            }
        }
    }
    logLoadTask = task
}

private func isActiveLogRepository(_ candidate: Repository) -> Bool {
    if let logActiveRepo {
        return logActiveRepo === candidate
    }
    return projectRepo === candidate
}

/// Aggregate VCS Log rows carry their owning Git root. A secondary root is
/// active even though it is not `logActiveRepo`; use the aggregate repository
/// map for navigation and stale-result checks in that mode.
private func isActiveLogNavigationRepository(
    _ candidate: Repository,
    rootPath: String?
) -> Bool {
    guard isLogRootQualified, let rootPath, !rootPath.isEmpty else {
        return isActiveLogRepository(candidate)
    }
    return logAggregateRepositories[rootPath] === candidate
}

/// IntelliJ's cherry-picked highlighter compares a selected source branch with
/// the current target branch using patch equivalence, not a commit-message
/// trailer. A commit is highlighted only after the branch-aware comparison
/// finishes. In an aggregate Log, run the comparison independently for every
/// root and qualify returned ids with that root so identical object ids from
/// separate repositories cannot cross-highlight.
func refreshCherryPickedHighlights() {
    logCherryPickComparisonTask?.cancel()
    logCherryPickComparisonTask = nil
    logCherryPickComparisonCancelHandle?.cancel()
    logCherryPickComparisonCancelHandle = nil
    logCherryPickComparisonGeneration += 1
    let requestedComparisonGeneration = logCherryPickComparisonGeneration
    logCherryPickComparisonInProgress = false
    logCherryPickComparisonCompletedRoots = 0
    logCherryPickComparisonTotalRoots = 0

    guard logHighlightCherryPicked,
          !logCherryPickCompareBranch.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        logCherryPickedCommitIDs = []
        logCherryPickComparisonReady = false
        return
    }
    let source = logCherryPickCompareBranch
    let aggregate = isLogAggregate
    let aggregateFilters = logAggregateBranchFilters
    let aggregateRevisionRanges = logAggregateRevisionRanges
    let aggregateRootPaths = logAggregateRootPaths
    let requestedLogGeneration = logGeneration
    let requestedRepositories: [(path: String, repo: Repository)]
    if aggregate {
        requestedRepositories = logAggregateRepositories
            .sorted { $0.key < $1.key }
            .map { (path: $0.key, repo: $0.value) }
    } else if let repo = logRepository {
        requestedRepositories = [(path: repo.workdir() ?? "", repo: repo)]
    } else {
        requestedRepositories = []
    }
    guard !requestedRepositories.isEmpty else {
        logCherryPickedCommitIDs = []
        logCherryPickComparisonReady = false
        return
    }

    let target = cherryPickTargetBranch(
        mode: logViewMode,
        sourceBranch: source,
        firstBranch: compareRev1,
        secondBranch: compareRev2,
        currentBranch: activeLogBranches.first(where: \.isCurrent)?.name
    )
    let eligibleRepositories = requestedRepositories.filter { request in
        let localBranchNames = (try? request.repo.branchList().map(\.name)) ?? []
        let remoteBranchNames = (try? request.repo.remoteBranchList().map(\.name)) ?? []
        return cherryPickSourceBranchExists(
            source,
            localBranchNames: localBranchNames,
            remoteBranchNames: remoteBranchNames
        )
    }
    guard !eligibleRepositories.isEmpty else {
        logCherryPickedCommitIDs = []
        logCherryPickComparisonReady = false
        return
    }
    logCherryPickComparisonReady = false
    logCherryPickComparisonInProgress = true
    logCherryPickComparisonTotalRoots = eligibleRepositories.count
    let cancel = GitCancelHandle()
    logCherryPickComparisonCancelHandle = cancel
    let task = Task.detached(priority: .userInitiated) {
        var highlighted: Set<String> = []
        var successfulComparisons = 0
        var failedComparisons = 0
        var lastError: Error?
        var completedComparisons = 0

        for request in eligibleRepositories {
            if Task.isCancelled {
                break
            }
            do {
                let comparisonTarget = aggregate
                    ? ((try? request.repo.branchList()) ?? []).first(where: \.isCurrent)?.name ?? "HEAD"
                    : target
                let ids = try request.repo.cherryPickedCommitsWithCancel(
                    source: source,
                    target: comparisonTarget,
                    cancel: cancel
                )
                successfulComparisons += 1
                highlighted.formUnion(ids.map {
                    logCommitDisplayIdentity(
                        repositoryPath: request.path,
                        id: $0,
                        aggregate: aggregate
                    )
                })
            } catch {
                // A branch can exist in one selected root but not another.
                // Keep successful roots visible and report only an all-roots
                // failure below.
                lastError = error
                failedComparisons += 1
            }
            completedComparisons += 1
            let completed = completedComparisons
            await MainActor.run {
                guard self.logCherryPickComparisonGeneration == requestedComparisonGeneration,
                      self.logGeneration == requestedLogGeneration,
                      self.logHighlightCherryPicked,
                      self.logCherryPickCompareBranch == source else { return }
                self.logCherryPickComparisonCompletedRoots = completed
            }
        }

        let resultIDs = highlighted
        let resultCount = successfulComparisons
        let failedCount = failedComparisons
        let resultError = lastError
        let comparisonWasCancelled = Task.isCancelled

        await MainActor.run {
            guard isCurrentCherryPickedComparison(
                highlightingEnabled: self.logHighlightCherryPicked,
                currentComparisonGeneration: self.logCherryPickComparisonGeneration,
                resultComparisonGeneration: requestedComparisonGeneration,
                currentLogGeneration: self.logGeneration,
                resultLogGeneration: requestedLogGeneration,
                currentSourceBranch: self.logCherryPickCompareBranch,
                resultSourceBranch: source
            ) else { return }
            if aggregate {
                guard self.logAggregateBranchFilters == aggregateFilters,
                      self.logAggregateRevisionRanges == aggregateRevisionRanges,
                      self.logAggregateRootPaths == aggregateRootPaths else { return }
            } else {
                guard self.isActiveLogRepository(eligibleRepositories[0].repo),
                      cherryPickTargetBranch(
                          mode: self.logViewMode,
                          sourceBranch: self.logCherryPickCompareBranch,
                          firstBranch: self.compareRev1,
                          secondBranch: self.compareRev2,
                          currentBranch: self.activeLogBranches.first(where: \.isCurrent)?.name
                      ) == target else { return }
            }
            self.logCherryPickComparisonTask = nil
            self.logCherryPickComparisonCancelHandle = nil
            self.logCherryPickComparisonInProgress = false
            guard !comparisonWasCancelled else { return }
            self.logCherryPickedCommitIDs = resultIDs
            // A successful comparison with zero picked commits is still a
            // completed comparison. The graph must remain unhighlighted,
            // rather than reviving the old trailer heuristic.
            self.logCherryPickComparisonReady = resultCount > 0
            if resultCount == 0, let resultError {
                self.feedbackCenter.error(
                    "Cherry-picked comparison failed",
                    detail: errorMessage(resultError),
                    nextStep: "Choose a valid local or remote branch, then retry."
                )
            } else if failedCount > 0 {
                self.feedbackCenter.warning(
                    "Cherry-picked comparison partially completed",
                    detail: "Compared \(resultCount) root(s); \(failedCount) root(s) could not be compared.",
                    nextStep: "Verify that the selected source branch exists in every affected Git root."
                )
            }
        }
    }
    logCherryPickComparisonTask = task
}

/// Mirrors IntelliJ's `stopTaskAndUnhighlight`: cancelling must also remove
/// fallback/trailer highlighting instead of leaving stale decoration visible.
func cancelCherryPickedHighlighting() {
    logCherryPickComparisonTask?.cancel()
    logCherryPickComparisonTask = nil
    logCherryPickComparisonCancelHandle?.cancel()
    logCherryPickComparisonCancelHandle = nil
    logCherryPickComparisonGeneration += 1
    logCherryPickComparisonInProgress = false
    logCherryPickedCommitIDs = []
    logCherryPickComparisonReady = false
    logHighlightCherryPicked = false
}

/// Resolve a selected revision that is outside the current paged graph. This
/// is required for reflog rows and for external "open commit" notifications:
/// the inspector must remain useful even when the graph has only loaded its
/// first page.
func loadCommitDetailsIfNeeded(_ id: String, forReflog: Bool = false) {
    let normalized = id.trimmingCharacters(in: .whitespacesAndNewlines)
    guard let repo = logRepository, !normalized.isEmpty else { return }
    let revision = normalized.split(separator: "\u{1f}", maxSplits: 1).last.map(String.init) ?? normalized
    if !forReflog,
       let visible = (logViewMode == .command ? logCommandEntries : logEntries).first(where: {
           let identity = logCommitIdentity($0)
           return identity == normalized || identity.hasPrefix(normalized) || normalized.hasPrefix(identity)
       }) {
        logDetailLoadTask?.cancel()
        logDetailCommit = visible
        return
    }
    if forReflog, reflogDetailCommit?.id == normalized { return }
    logDetailLoadTask?.cancel()
    if forReflog {
        reflogDetailCommit = nil
    } else {
        logDetailCommit = nil
    }
    let expectedReflogSelection = forReflog ? reflogSelection : nil
    let expectedLogSelection = forReflog ? nil : logSelection
    let tabID = currentLogTabID
    let task = Task.detached(priority: .userInitiated) {
        do {
            let candidates = try repo.logFiltered(
                path: nil,
                limit: 1,
                follow: false,
                startRev: revision,
                author: nil,
                since: nil
            )
            guard !Task.isCancelled,
                  let commit = candidates.first(where: {
                      $0.id == normalized || $0.id.hasPrefix(normalized) || normalized.hasPrefix($0.id)
            }) else { return }
            await MainActor.run {
                guard self.externalLogTabIsAlive(tabID),
                      self.isActiveLogRepository(repo) else { return }
                if forReflog {
                    guard self.reflogSelection == expectedReflogSelection,
                          self.selectedReflogEntry?.newId == commit.id else { return }
                    self.reflogDetailCommit = commit
                } else if let selected = expectedLogSelection,
                          selected == normalized
                            || selected.hasPrefix(normalized)
                            || normalized.hasPrefix(selected) {
                    self.logDetailCommit = commit
                }
            }
        } catch {
            // The graph/inspector will keep its existing content. A missing
            // reflog object is not a reason to replace a usable log with an
            // error screen.
        }
    }
    logDetailLoadTask = task
}

/// Reflog uses the same multi-commit Changes browser as the main Log. A
/// reflog row points at an object rather than carrying a full CommitInfo, so
/// resolve the selected object IDs together and preserve the visible Reflog
/// order while loading them off the main actor.
func loadReflogCommitDetails() {
    reflogDetailLoadTask?.cancel()
    reflogDetailLoadTask = nil
    reflogDetailCommit = nil
    reflogDetailCommits = []
    guard let repo = reflogRepository, !reflogSelectedIDs.isEmpty else { return }

    let expectedSelection = reflogSelectedIDs
    let expectedEntryIDs = selectedReflogEntries.map(reflogEntryIdentifier)
    let commitIDs = orderedUniqueReflogCommitIDs(selectedReflogEntries)
    let tabID = currentLogTabID
    guard !commitIDs.isEmpty else { return }

    let task = Task.detached(priority: .userInitiated) {
        var commits: [CommitInfo] = []
        for id in commitIDs {
            guard !Task.isCancelled else { return }
            guard let candidates = try? repo.logFiltered(
                path: nil,
                limit: 1,
                follow: false,
                startRev: id,
                author: nil,
                since: nil
            ), let commit = candidates.first(where: {
                $0.id == id || $0.id.hasPrefix(id) || id.hasPrefix($0.id)
            }) else { continue }
            commits.append(commit)
        }
        guard !Task.isCancelled else { return }
        let loadedCommits = commits
        await MainActor.run {
            guard self.externalLogTabIsAlive(tabID),
                  self.isActiveLogRepository(repo),
                  self.reflogSelectedIDs == expectedSelection,
                  self.selectedReflogEntries.map(reflogEntryIdentifier) == expectedEntryIDs else { return }
            self.reflogDetailCommits = loadedCommits
        }
    }
    reflogDetailLoadTask = task
}

func loadMoreLog() {
    if logViewMode == .command {
        guard hasMoreLogCommand else { return }
        runLogCommand(reset: false)
        return
    }
    guard !isLoadingMoreLog, hasMoreLog else { return }
    guard logPageCursor != nil else { return }
    loadLog(reset: false)
}

/// Vcs.Log.GoToParent / GoToChild: keep navigation inside the graph table so
/// the details inspector follows the new lead selection immediately. IntelliJ
/// exposes all adjacent graph rows when there is more than one choice; resolve
/// those rows from the repository rather than treating the loaded page as the
/// complete graph.
func selectParentLogCommit() {
    guard let commit = selectedCommit,
          !commit.parentIds.isEmpty,
          let repository = logRepository(for: commit) else { return }

    let parentIDs = commit.parentIds
    let expectedSelection = logCommitIdentity(commit)
    let expectedGeneration = logGeneration
    if parentIDs.count == 1 {
        selectLogRevision(
            logCommitIdentity(repositoryPath: commit.repositoryPath, id: parentIDs[0])
        )
        return
    }

    Task.detached(priority: .userInitiated) {
        let parents = try? parentIDs.map { try repository.commitInfo(commitId: $0) }
        guard !Task.isCancelled else { return }
        await MainActor.run {
            guard self.logGeneration == expectedGeneration,
                  self.logSelection == expectedSelection,
                  self.isActiveLogNavigationRepository(repository, rootPath: commit.repositoryPath) else {
                return
            }
            guard let parents, !parents.isEmpty else {
                self.feedbackCenter.warning(
                    "Parent navigation unavailable",
                    detail: "The selected commit's parent records could not be loaded.",
                    nextStep: "Refresh Log and try again."
                )
                return
            }
            self.pendingLogNavigationCommits = parents
            self.logNavigationChoosesParent = true
            self.pendingLogNavigationSelection = expectedSelection
            self.pendingLogNavigationGeneration = expectedGeneration
            self.isLogNavigationChoicePresented = true
        }
    }
}

func selectChildLogCommit() {
    guard let commit = selectedCommit,
          let repository = logRepository(for: commit) else { return }

    let expectedSelection = logCommitIdentity(commit)
    let expectedGeneration = logGeneration
    Task.detached(priority: .userInitiated) {
        let children = try? repository.commitChildren(commitId: commit.id)
        guard !Task.isCancelled else { return }
        await MainActor.run {
            guard self.logGeneration == expectedGeneration,
                  self.logSelection == expectedSelection,
                  self.isActiveLogNavigationRepository(repository, rootPath: commit.repositoryPath) else {
                return
            }
            guard let children else {
                self.feedbackCenter.warning(
                    "Child navigation unavailable",
                    detail: "The selected commit's child records could not be loaded.",
                    nextStep: "Refresh Log and try again."
                )
                return
            }
            guard !children.isEmpty else {
                self.feedbackCenter.warning(
                    "No child commits",
                    detail: "The selected commit has no reachable direct child in this Git root.",
                    nextStep: "Select another commit in Log."
                )
                return
            }
            if children.count == 1 {
                self.selectLogRevision(self.logCommitIdentity(children[0]))
            } else {
                self.pendingLogNavigationCommits = children
                self.logNavigationChoosesParent = false
                self.pendingLogNavigationSelection = expectedSelection
                self.pendingLogNavigationGeneration = expectedGeneration
                self.isLogNavigationChoicePresented = true
            }
        }
    }
}

func choosePendingLogNavigationCommit(_ commit: CommitInfo) {
    guard isLogNavigationChoicePresented,
          pendingLogNavigationSelection == logSelection,
          pendingLogNavigationGeneration == logGeneration else {
        isLogNavigationChoicePresented = false
        pendingLogNavigationCommits = []
        pendingLogNavigationSelection = nil
        pendingLogNavigationGeneration = nil
        return
    }
    let identity = logCommitIdentity(commit)
    isLogNavigationChoicePresented = false
    pendingLogNavigationCommits = []
    pendingLogNavigationSelection = nil
    pendingLogNavigationGeneration = nil
    selectLogRevision(identity)
}

func selectLogRevision(_ id: String) {
    let visibleEntries = logViewMode == .command ? logCommandEntries : logEntries
    if let visible = visibleEntries.first(where: {
        let identity = logCommitIdentity($0)
        return identity == id || identity.hasPrefix(id) || id.hasPrefix(identity)
    }) {
        let identity = logCommitIdentity(visible)
        logSelection = identity
        logSelectedIDs = [identity]
        return
    }

    let parts = id.split(separator: "\u{1f}", maxSplits: 1)
    let repositoryPath = parts.count == 2 ? String(parts[0]) : nil
    let revision = parts.last.map(String.init) ?? id
    let revisionRepo = repositoryPath.flatMap { logAggregateRepositories[$0] }
        ?? repositoryPath.flatMap { try? openRepository(path: $0) }
        ?? logRepository
    guard let repo = revisionRepo else { return }
    let expectedGeneration = logGeneration
    Task.detached(priority: .userInitiated) {
        guard let commit = try? repo.logFiltered(
            path: nil,
            limit: 1,
            follow: false,
            startRev: revision,
            author: nil,
            since: nil
        ).first else { return }
        await MainActor.run {
            guard self.isActiveLogNavigationRepository(repo, rootPath: repositoryPath),
                  self.logGeneration == expectedGeneration else { return }
            if self.logViewMode == .command {
                if !self.logCommandEntries.contains(where: { $0.id == commit.id }) {
                    self.logCommandEntries.insert(commit, at: 0)
                }
            } else if !self.logEntries.contains(where: { $0.id == commit.id }) {
                self.logEntries.insert(commit, at: 0)
            }
            let identity = self.logCommitIdentity(commit)
            self.logSelection = identity
            self.logSelectedIDs = [identity]
        }
    }
}

func copySelectedLogIDs() {
    let ids = logEntries
        .filter { logSelectedIDs.contains(logCommitIdentity($0)) }
        .map(\.id)
    guard !ids.isEmpty else { return }
    NSPasteboard.general.clearContents()
    NSPasteboard.general.setString(formattedRevisionIDsForClipboard(ids), forType: .string)
    feedbackCenter.success("Copied revisions", detail: "\(ids.count) commit ID(s)")
}

func copyRepositoryRelativePath(_ path: String) {
    guard let normalized = normalizedRepositoryRelativePath(path) else { return }
    NSPasteboard.general.clearContents()
    NSPasteboard.general.setString(normalized, forType: .string)
    feedbackCenter.success("Path copied", detail: normalized)
}

/// Open the Compare with Branch or Tag action against the deepest Git root
/// containing the selected project-tree file or directory. Root discovery may
/// still be in flight when the user opens the context menu, so refresh the
/// candidate list on demand if the cached multi-root list is empty.
func openFileReferenceComparison(path: String, isDirectory: Bool) {
    fileTreeDiffRequest = nil
    guard let primaryRepo = repo,
          let primaryRootPath = primaryRepo.workdir(),
          normalizedRepositoryRelativePath(path) != nil else {
        feedbackCenter.error(
            "Unable to compare project path",
            detail: "The selected project-tree path is not a safe repository-relative path.",
            nextStep: "Refresh the project tree, then try again."
        )
        return
    }

    let cachedRoots = multiRoots
    Task.detached(priority: .userInitiated) {
        let roots = cachedRoots.isEmpty
            ? ((try? discoverGitRoots(scanRoot: primaryRootPath, maxDepth: nil)) ?? [])
            : cachedRoots
        guard let target = fileReferenceComparisonTarget(
            path: path,
            primaryRootPath: primaryRootPath,
            roots: roots
        ) else {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Unable to compare project path",
                    detail: "The selected file is outside the discovered Git roots.",
                    nextStep: "Refresh the project roots, then try again."
                )
            }
            return
        }

        do {
            let targetRepo: Repository
            if canonicalExternalLogPath(primaryRootPath) == target.rootPath {
                targetRepo = primaryRepo
            } else {
                targetRepo = try openRepository(path: target.rootPath)
            }
            await MainActor.run {
                self.fileReferenceComparisonRequest = FileReferenceComparisonRequest(
                    repo: targetRepo,
                    path: target.relativePath,
                    isDirectory: isDirectory,
                    mode: .references
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Unable to open Git root",
                    detail: "\(target.rootPath)\n\(errorMessage(error))",
                    nextStep: "Check that the nested repository is still available, then retry."
                )
            }
        }
    }
}

