/// IntelliJ's `Compare.SameVersion`: compare the selected worktree file with
/// the current revision in its owning Git root. This is intentionally a
/// separate path from `Compare with Branch or Tag…`, which opens a ref picker.
func openFileSameVersionComparison(path: String) {
    guard let primaryRepo = repo,
          let primaryRootPath = primaryRepo.workdir(),
          normalizedRepositoryRelativePath(path) != nil else {
        feedbackCenter.error(
            "Unable to compare project path",
            detail: "The selected project-tree path is not a safe repository-relative path.",
            nextStep: "Refresh the project tree, then try again."
        )
        return
    }

    let cachedRoots = multiRoots
    Task.detached(priority: .userInitiated) {
        let roots = cachedRoots.isEmpty
            ? ((try? discoverGitRoots(scanRoot: primaryRootPath, maxDepth: nil)) ?? [])
            : cachedRoots
        guard let target = fileReferenceComparisonTarget(
            path: path,
            primaryRootPath: primaryRootPath,
            roots: roots
        ) else {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Unable to compare project path",
                    detail: "The selected file is outside the discovered Git roots.",
                    nextStep: "Refresh the project roots, then try again."
                )
            }
            return
        }

        do {
            let targetRepo: Repository
            if canonicalExternalLogPath(primaryRootPath) == target.rootPath {
                targetRepo = primaryRepo
            } else {
                targetRepo = try openRepository(path: target.rootPath)
            }
            guard targetRepo.headCommitId() != nil else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "The repository has no HEAD revision."]
                )
            }
            let entry = FileEntry(
                path: target.relativePath,
                oldPath: nil,
                staged: .unchanged,
                unstaged: .modified
            )
            await MainActor.run {
                self.toolWindowMode = .commit
                self.selection = nil
                self.fileSelection = nil
                self.selectionModePath = nil
                self.commitPreviewPath = nil
                self.commitPreviewVisible = false
                self.fileTreeDiffRequest = FileTreeDiffRequest(
                    repo: targetRepo,
                    entry: entry,
                    initialMode: .worktreeToHead
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Unable to compare with HEAD",
                    detail: "\(target.rootPath)\n\(errorMessage(error))",
                    nextStep: "Check that the repository has a committed HEAD and retry."
                )
            }
        }
    }
}

/// IntelliJ's `Show.Current.Revision` displays the metadata for the latest
/// committed revision that owns the selected file. Resolve the owning Git
/// root before querying history so nested repositories cannot use the parent
/// repository's revision.
func showCurrentRevision(path: String) {
    guard let primaryRepo = repo,
          let primaryRootPath = primaryRepo.workdir(),
          normalizedRepositoryRelativePath(path) != nil else {
        feedbackCenter.error(
            "Current revision unavailable",
            detail: "The selected project-tree path is not a safe repository-relative path.",
            nextStep: "Refresh the project tree, then try again."
        )
        return
    }

    let cachedRoots = multiRoots
    Task.detached(priority: .userInitiated) {
        let roots = cachedRoots.isEmpty
            ? ((try? discoverGitRoots(scanRoot: primaryRootPath, maxDepth: nil)) ?? [])
            : cachedRoots
        guard let target = fileReferenceComparisonTarget(
            path: path,
            primaryRootPath: primaryRootPath,
            roots: roots
        ) else {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Current revision unavailable",
                    detail: "The selected file is outside the discovered Git roots.",
                    nextStep: "Refresh the project roots, then retry."
                )
            }
            return
        }

        do {
            let targetRepo: Repository
            if canonicalExternalLogPath(primaryRootPath) == target.rootPath {
                targetRepo = primaryRepo
            } else {
                targetRepo = try openRepository(path: target.rootPath)
            }
            guard let commit = try targetRepo.logWithCommand(
                commandArgs: [
                    "--all",
                    "--follow",
                    "-n1",
                    "--",
                    target.relativePath
                ],
                limit: 1
            ).first else {
                await MainActor.run {
                    self.feedbackCenter.warning(
                        "Current revision unavailable",
                        detail: "No committed revision was found for \(target.relativePath).",
                        nextStep: "Only tracked files with committed history can show a current revision."
                    )
                }
                return
            }
            await MainActor.run {
                guard let currentRootPath = self.repo?.workdir(),
                      canonicalExternalLogPath(currentRootPath)
                          == canonicalExternalLogPath(primaryRootPath) else {
                    return
                }
                self.currentRevisionRequest = CurrentRevisionRequest(
                    repo: targetRepo,
                    path: target.relativePath,
                    commit: commit
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Unable to load current revision",
                    detail: "\(target.rootPath)\n\(errorMessage(error))",
                    nextStep: "Check the repository state, then retry."
                )
            }
        }
    }
}

/// Export selected revision/tree comparison changes as a portable patch.
/// Revision and path arguments stay separate so unusual branch names and
/// filenames cannot become shell syntax. This is the compare-view equivalent
/// of IntelliJ's Changes Browser Create Patch action.
func createPatchFromCompare() {
    let selectedChanges = orderedCompareSelection(
        changes: treeChanges,
        selectedPaths: compareSelectedPaths
    )
    guard let comparisonRepo = activeCompareRepo ?? repo,
          !selectedChanges.isEmpty,
          !compareRev1.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
          compareWithWorkingTree || !compareRev2.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        return
    }

    var paths: [String] = []
    var seenPaths = Set<String>()
    for change in selectedChanges {
        for path in [change.oldPath, change.path].compactMap({ $0 }) {
            guard !path.isEmpty, seenPaths.insert(path).inserted else { continue }
            paths.append(path)
        }
    }
    guard !paths.isEmpty else { return }

    let expectedRev1 = compareRev1
    let expectedRev2 = compareRev2
    let expectedWorkingTree = compareWithWorkingTree
    guard let comparisonRootPath = comparisonRepo.workdir(), !comparisonRootPath.isEmpty else { return }
    presentPatchExportDialog(
        title: "Create Compare Patch",
        defaultFileName: "compare.patch",
        repositoryRootPath: comparisonRootPath,
        paths: paths,
        allowsBaseDirectory: true
    ) { options in
        let destination = options.copyToClipboard
            ? nil
            : self.patchExportDestination(
                defaultFileName: "compare.patch",
                repositoryRootPath: comparisonRootPath
            )
        guard options.copyToClipboard || destination != nil else { return }
        PatchExportSettings.save(options, for: comparisonRootPath)

        let baseArguments = comparePatchGitArguments(
            rev1: expectedRev1,
            rev2: expectedRev2,
            comparesWithWorkingTree: expectedWorkingTree,
            paths: paths
        )
        guard let arguments = patchExportGitArguments(
            baseArguments: baseArguments,
            repositoryRootPath: comparisonRootPath,
            paths: paths,
            options: options
        ) else { return }

        self.beginFeedbackOperation(options.copyToClipboard ? "Copy compare patch" : "Create compare patch")
        Task.detached(priority: .userInitiated) {
            do {
                let result = try comparisonRepo.runGitCommand(command: "diff", args: arguments)
                guard result.exitCode == 0 else {
                    let detail = result.stderr.isEmpty ? result.stdout : result.stderr
                    throw NSError(
                        domain: "Arbor.Git",
                        code: Int(result.exitCode),
                        userInfo: [NSLocalizedDescriptionKey: detail]
                    )
                }
                guard !result.stdoutBytes.isEmpty else {
                    throw NSError(
                        domain: "Arbor.Git",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "The selected comparison has no patch output."]
                    )
                }
                if let destination {
                    try patchExportData(result.stdoutBytes, encoding: options.encoding)
                        .write(to: destination, options: .atomic)
                }
                await MainActor.run {
                    if options.copyToClipboard {
                        NSPasteboard.general.clearContents()
                        NSPasteboard.general.setString(result.stdout, forType: .string)
                    }
                    self.feedbackCenter.success(
                        options.copyToClipboard ? "Compare patch copied" : "Compare patch created",
                        detail: options.copyToClipboard
                            ? "\(selectedChanges.count) selected change(s)"
                            : "\(selectedChanges.count) selected change(s) → \(destination?.lastPathComponent ?? "")"
                    )
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error(
                        options.copyToClipboard ? "Copy compare patch failed" : "Create compare patch failed",
                        detail: errorMessage(error),
                        nextStep: "Check the compared revisions and destination, then retry."
                    )
                }
            }
        }
    }
}

/// Export the selected commit's parent-to-commit diff as a portable patch.
/// Keep the revision arguments separate from the Git command so commit ids
/// and repository content can never become shell syntax. Merge commits use
/// the first parent, matching the default parent shown by the Changes browser.
func createPatchFromLog(_ commit: CommitInfo) {
    guard let repo = logRepository(for: commit) else { return }

    guard let repositoryRootPath = repo.workdir(), !repositoryRootPath.isEmpty else { return }
    presentPatchExportDialog(
        title: "Create Patch",
        defaultFileName: "\(commit.shortId).patch",
        repositoryRootPath: repositoryRootPath,
        paths: [],
        allowsBaseDirectory: false
    ) { options in
        let destination = options.copyToClipboard
            ? nil
            : self.patchExportDestination(
                defaultFileName: "\(commit.shortId).patch",
                repositoryRootPath: repositoryRootPath
            )
        guard options.copyToClipboard || destination != nil else { return }
        PatchExportSettings.save(options, for: repositoryRootPath)

        let command: String
        let baseArguments: [String]
        if let parent = commit.parentIds.first {
            command = "diff"
            baseArguments = ["--binary", "--no-ext-diff", parent, commit.id]
        } else {
            command = "show"
            baseArguments = ["--format=", "--binary", "--no-ext-diff", "--root", commit.id]
        }
        guard let arguments = patchExportGitArguments(
            baseArguments: baseArguments,
            repositoryRootPath: repositoryRootPath,
            paths: [],
            options: options
        ) else { return }

        self.beginFeedbackOperation(options.copyToClipboard ? "Copy patch" : "Create patch")
        Task.detached(priority: .userInitiated) {
            do {
                let result = try repo.runGitCommand(command: command, args: arguments)
                guard result.exitCode == 0 else {
                    let detail = result.stderr.isEmpty ? result.stdout : result.stderr
                    throw NSError(
                        domain: "Arbor.Git",
                        code: Int(result.exitCode),
                        userInfo: [NSLocalizedDescriptionKey: detail]
                    )
                }
                guard !result.stdoutBytes.isEmpty else {
                    throw NSError(
                        domain: "Arbor.Git",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "The selected revision has no patch output."]
                    )
                }
                let message = commit.summary + (commit.messageBody.isEmpty ? "" : "\n\n\(commit.messageBody)")
                let patch = patchTextWithCommitMessage(result.stdout, commitMessage: message)
                guard !patch.isEmpty else {
                    throw NSError(
                        domain: "Arbor.Git",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "The selected revision has no patch output."]
                    )
                }
                if let destination {
                    try patchExportData(
                        result.stdoutBytes,
                        commitMessage: message,
                        encoding: options.encoding
                    )
                        .write(to: destination, options: .atomic)
                }
                await MainActor.run {
                    if options.copyToClipboard {
                        NSPasteboard.general.clearContents()
                        NSPasteboard.general.setString(patch, forType: .string)
                    }
                    self.feedbackCenter.success(
                        options.copyToClipboard ? "Patch copied" : "Patch created",
                        detail: options.copyToClipboard
                            ? commit.shortId
                            : destination?.lastPathComponent ?? ""
                    )
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error(
                        options.copyToClipboard ? "Copy patch failed" : "Create patch failed",
                        detail: errorMessage(error),
                        nextStep: "Check the selected revision and destination, then retry."
                    )
                }
            }
        }
    }
}

/// Export or copy the selected Changes Browser rows as one patch. Each group
/// is diffed against its own commit parent, then the textual patches are
/// joined only after every Git command succeeds. The action is intentionally
/// fail-closed for duplicate paths because a plain patch cannot express the
/// ordering of two revisions of the same file.
func createPatchFromLogSelection(_ records: [LogChangeRecord]) {
    createPatchFromLogSelection(records, copyToClipboard: false)
}

func copyPatchFromLogSelection(_ records: [LogChangeRecord]) {
    createPatchFromLogSelection(records, copyToClipboard: true)
}

private func createPatchFromLogSelection(
    _ records: [LogChangeRecord],
    copyToClipboard: Bool
) {
    guard canCreateLogPatchSelection(records) else { return }

    let groups = logChangePatchGroups(records)
    let requests = groups.compactMap { group -> (Repository, CommitInfo, UInt32?, [String])? in
        guard let first = group.first,
              let repo = logRepository(for: first.commit) else {
            return nil
        }

        var paths: [String] = []
        var seenPaths = Set<String>()
        for record in group {
            for path in [record.change.oldPath, record.change.path].compactMap({ $0 }) {
                guard !path.isEmpty, seenPaths.insert(path).inserted else { continue }
                paths.append(path)
            }
        }
        guard !paths.isEmpty else { return nil }
        return (repo, first.commit, first.parentIndex, paths)
    }
    guard requests.count == groups.count, !requests.isEmpty else { return }

    let firstCommit = records[0].commit
    let defaultFileName = records.count == 1
        ? "\(firstCommit.shortId).patch"
        : "selected.patch"
    let repositoryRootPaths = Set(requests.compactMap { $0.0.workdir() })
    guard !repositoryRootPaths.isEmpty else { return }
    let sharedRootPath = repositoryRootPaths.count == 1 ? repositoryRootPaths.first : nil
    let exportRootPath = sharedRootPath ?? repositoryRootPaths.sorted().first!
    let allPaths = requests.flatMap { $0.3 }

    let performExport: (PatchExportOptions) -> Void = { options in
        let destination = options.copyToClipboard
            ? nil
            : self.patchExportDestination(
                defaultFileName: defaultFileName,
                repositoryRootPath: exportRootPath
            )
        guard options.copyToClipboard || destination != nil else { return }
        PatchExportSettings.save(options, for: exportRootPath)

        self.beginFeedbackOperation(options.copyToClipboard ? "Copy patch" : "Create patch")
        Task.detached(priority: .userInitiated) {
            do {
                var patchParts: [Data] = []
                var patchTextParts: [String] = []
                for (repo, commit, parentIndex, paths) in requests {
                    guard let plannedCommand = logPatchGitCommand(
                        commit: commit,
                        parentIndex: parentIndex,
                        paths: paths
                    ), let repositoryRootPath = repo.workdir(),
                    let arguments = patchExportGitArguments(
                        baseArguments: plannedCommand.args,
                        repositoryRootPath: repositoryRootPath,
                        paths: paths,
                        options: options
                    ) else {
                        throw NSError(
                            domain: "Arbor.Git",
                            code: 1,
                            userInfo: [NSLocalizedDescriptionKey: "Selected revision, base directory, or path is no longer available."]
                        )
                    }

                    let result = try repo.runGitCommand(
                        command: plannedCommand.command,
                        args: arguments
                    )
                    guard result.exitCode == 0 else {
                        let detail = result.stderr.isEmpty ? result.stdout : result.stderr
                        throw NSError(
                            domain: "Arbor.Git",
                            code: Int(result.exitCode),
                            userInfo: [NSLocalizedDescriptionKey: detail]
                        )
                    }
                    patchParts.append(result.stdoutBytes)
                    patchTextParts.append(result.stdout)
                }

                let patchData = joinedGitPatchData(patchParts)
                let patchText = joinedGitPatchParts(patchTextParts)
                guard !patchData.isEmpty else {
                    throw NSError(
                        domain: "Arbor.Git",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "The selected changes have no patch output."]
                    )
                }
                if let destination {
                    try patchExportData(patchData, encoding: options.encoding)
                        .write(to: destination, options: .atomic)
                }
                await MainActor.run {
                    if options.copyToClipboard {
                        NSPasteboard.general.clearContents()
                        NSPasteboard.general.setString(patchText, forType: .string)
                    }
                    self.feedbackCenter.success(
                        options.copyToClipboard ? "Patch copied" : "Patch created",
                        detail: options.copyToClipboard
                            ? "\(records.count) selected change(s)"
                            : "\(records.count) selected change(s) → \(destination?.lastPathComponent ?? "")"
                    )
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error(
                        options.copyToClipboard ? "Copy patch failed" : "Create patch failed",
                        detail: errorMessage(error),
                        nextStep: "Check the selected revisions and destination, then retry."
                    )
                }
            }
        }
    }

    if copyToClipboard {
        performExport(PatchExportOptions(
            baseDirectory: nil,
            reverse: false,
            copyToClipboard: true,
            encoding: PatchExportSettings.encoding(for: exportRootPath)
        ))
    } else {
        presentPatchExportDialog(
            title: "Create Selected Patch",
            defaultFileName: defaultFileName,
            repositoryRootPath: exportRootPath,
            paths: allPaths,
            allowsBaseDirectory: sharedRootPath != nil,
            onExport: performExport
        )
    }
}

private func isCommitHashQuery(_ value: String) -> Bool {
    let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
    guard (4...40).contains(normalized.count) else { return false }
    return normalized.unicodeScalars.allSatisfy { scalar in
        switch scalar.value {
        case 48...57, 65...70, 97...102: return true
        default: return false
        }
    }
}

func parseLogSince(_ value: String) -> Int64? {
    parseLogDate(value)
}

func parseLogUntil(_ value: String) -> Int64? {
    parseLogDate(value)
}

func beginCommitAndPush() {
    if multiRoots.count > 1 {
        openMultiRootCommitDialog()
        return
    }
    guard hasStaged,
          !commitMessage.trimmingCharacters(in: .whitespaces).isEmpty else { return }
    // Match GitCommitAndPushExecutor: the commit workflow owns the first
    // stage. Push options are shown only after Git has created the commit.
    // This prevents a rejected/failed commit from ever entering transport.
    pendingCommitAndPush = true
    doCommit()
}

/// Complete the single-root Commit and Push executor after the commit phase.
/// The default keeps IntelliJ's Push preview, while the project preference can
/// opt into automatic transport for a root that has a usable remote/branch.
private func beginSingleRootPushAfterCommit(rootPath: String) {
    let choice = GitPushAfterCommitSettings.choice(for: projectPath)
    let protectedBranchPatterns = effectiveProtectedBranchPatterns
    Task.detached(priority: .userInitiated) {
        let requiresPreview = pushAfterCommitRequiresPreview(
            rootPath: rootPath,
            choice: choice,
            protectedBranchPatterns: protectedBranchPatterns
        )
        await MainActor.run {
            guard self.repo?.workdir().map({
                URL(fileURLWithPath: $0).standardizedFileURL.path
            }) == URL(fileURLWithPath: rootPath).standardizedFileURL.path else {
                self.feedbackCenter.warning(
                    "Push after commit unavailable",
                    detail: "The original Git root is no longer active.",
                    nextStep: "Open the original project and use Push from that Git root."
                )
                return
            }
            if requiresPreview {
                self.pushDialogRemote = nil
                self.pushDialogBranch = nil
                self.pushDialogSourceRevision = nil
                self.pushDialogRefspec = nil
                self.pushDialogMode = .push
                self.showPushDialog = true
            } else {
                self.doPush(
                    nil,
                    branch: nil,
                    force: false,
                    forceWithLease: false,
                    setUpstream: false,
                    refspec: nil,
                    tagMode: nil,
                    skipHooks: false,
                    afterCommit: true
                )
            }
        }
    }
}

/// IntelliJ's auto-squash actions create a normal commit whose message is
/// understood by Git's autosquash rebase. They do not rewrite history
/// immediately; the generated message is presented in the Commit tool window
/// so the user can review, stage, and commit the current local changes. The
/// optional Commit and Rebase executor remains available for that same commit.
func beginAutoSquashCommitFromLog(_ commit: CommitInfo, kind: AutoSquashCommitKind) {
    if isLogAggregate {
        feedbackCenter.warning(
            "Auto-squash unavailable in aggregate Log",
            detail: "The selected commit belongs to a root whose Commit workspace is not active.",
            nextStep: "Navigate to one Git root before creating an autosquash commit."
        )
        return
    }
    if let activeRoot = logActiveRootPath,
       activeRoot != projectPath {
        feedbackCenter.warning(
            "Auto-squash is available in the primary Log root",
            detail: "The nested root Log is read and mutation capable, but its Commit workspace is not yet root-scoped.",
            nextStep: "Switch Log back to the primary repository before creating an autosquash commit."
        )
        return
    }
    guard hasLocalChanges else {
        feedbackCenter.warning(
            "No local changes",
            detail: "\(kind.title) commits need changes to commit.",
            nextStep: "Make or stage changes, then retry."
        )
        return
    }
    let isRootTarget = commit.parentIds.isEmpty
    let isMergeTarget = commit.parentIds.count > 1
    if isMergeTarget {
        feedbackCenter.warning(
            "Merge commit autosquash unavailable",
            detail: "Git autosquash cannot safely target a merge topology row.",
            nextStep: "Use Interactive Rebase with merge preservation to edit the merge history."
        )
        return
    }
    let onto = commit.parentIds.first ?? ""
    let subject = commit.summary
        .split(whereSeparator: { $0.isNewline })
        .first
        .map(String.init) ?? commit.summary
    commitMessage = "\(kind.prefix)! \(subject)"
    pendingAutoSquashRebase = PendingAutoSquashRebase(
        targetID: commit.id,
        onto: onto,
        kind: kind,
        root: isRootTarget
    )
    amendMode = false
    toolWindowMode = .commit
    toolWindowExpanded = true
    projectPanelExpanded = false
    commitFeedback = nil
}

/// 顶部工具栏/Branches 弹出的普通 Push 入口；提交工具窗的
/// “Commit and Push…” 则仍由 beginCommitAndPush 进入同一对话框的另一模式。
func beginPushDialog(branch: String? = nil) {
    // GitPushBranchAction remains reachable for a local branch without a
    // configured remote; let the dialog explain that state and offer remote
    // configuration instead of silently discarding the click.
    guard self.repo != nil else { return }
    pushDialogRemote = nil
    pushDialogRefspec = nil
    pushDialogBranch = branch
    pushDialogSourceRevision = nil
    pushDialogMode = .push
    showPushDialog = true
}

/// LOG-003：将 Log 中选中的提交作为 source 推送到目标分支。
/// IntelliJ 会打开 Push 对话框；有包含该提交的本地分支时预填它，
/// 否则使用 detached source，并让用户编辑远程目标分支。
func pushUpToCommitFromLog(_ commit: CommitInfo) {
    guard let repo = logRepository(for: commit) else {
        feedbackCenter.error("Push unavailable", detail: "No remote is configured.", nextStep: "Add a remote before pushing.")
        return
    }
    let commitRemotes = (try? repo.remoteList()) ?? activeLogRemotes
    guard !commitRemotes.isEmpty else {
        feedbackCenter.error("Push unavailable", detail: "No remote is configured.", nextStep: "Add a remote before pushing.")
        return
    }
    let commitID = commit.id
    let localBranches = activeLogBranches
    Task.detached(priority: .userInitiated) {
        // Match GitPushUpToCommitAction: prefer the current branch only when
        // it actually contains the selected commit; otherwise use the first
        // local branch that contains it. Query the repository's live permanent
        // graph once instead of walking every local branch independently. The
        // old implementation always pushed to the checked-out branch, which
        // could move an unrelated branch when the Log view was showing another
        // branch's history.
        let containingBranches = Set(
            (try? repo.commitContainingBranches(commitId: commitID)) ?? []
        )
        let current = localBranches.first(where: { $0.isCurrent })
        let candidate = [current].compactMap { $0 }
            .first { containingBranches.contains($0.name) }
            ?? localBranches.first {
                !$0.isCurrent
                    && containingBranches.contains($0.name)
            }
        await MainActor.run {
            self.pushDialogMode = .pushUpToCommit
            self.pushDialogRemote = nil
            self.pushDialogBranch = candidate?.name
            self.pushDialogSourceRevision = commitID
            self.pushDialogRefspec = nil
            self.showPushDialog = true
        }
    }
}

/// IntelliJ's Add Commits to Remote Branch action fetches only the selected
/// remote branch, replays the selected commits without touching the checked
/// out worktree, and then hands the detached result to the normal Push dialog.
private func addCommitsToRemoteBranchNotificationID(repositoryPath: String) -> String {
    let stablePath = URL(fileURLWithPath: repositoryPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.add-commits-to-remote-branch.\(stablePath)"
}

func addCommitsToRemoteBranchFromLog(_ commits: [CommitInfo]) {
    guard let firstCommit = commits.first,
          let commitRepo = logRepository(for: firstCommit) else {
        feedbackCenter.error(
            "Add commits unavailable",
            detail: "No repository is open.",
            nextStep: "Open a Git repository, then retry."
        )
        return
    }
    var seen = Set<String>()
    let selected = commits.filter { seen.insert($0.id).inserted }
    guard !selected.isEmpty else { return }
    guard isAddCommitsToRemoteBranchAvailable(for: selected) else {
        feedbackCenter.warning(
            "Add commits unavailable",
            detail: "Select linear commits from one Git root.",
            nextStep: "Do not include merge commits or commits from another repository."
        )
        return
    }
    let notificationID = addCommitsToRemoteBranchNotificationID(
        repositoryPath: commitRepo.workdir() ?? ""
    )
    // In an aggregate multi-root Log, the active dashboard root is not
    // necessarily the root that owns the selected commits. Resolve the
    // remote-tracking branches from the commit's repository, just as the
    // subsequent fetch/replay step resolves its Repository instance.
    let remoteBranches = (try? commitRepo.remoteBranchList()) ?? []
    guard !remoteBranches.isEmpty else {
        feedbackCenter.error(
            "Add commits unavailable",
            detail: "No fetched remote branches are available.",
            nextStep: "Fetch a remote branch, then retry.",
            notificationID: notificationID
        )
        return
    }
    addCommitsToRemoteBranchContext = AddCommitsToRemoteBranchContext(
        commits: selected,
        remoteBranches: remoteBranches
    )
}

func prepareAddCommitsToRemoteBranch(
    _ remoteBranch: RemoteBranchInfo,
    commits: [CommitInfo]
) {
    guard isAddCommitsToRemoteBranchAvailable(for: commits) else {
        feedbackCenter.warning(
            "Add commits unavailable",
            detail: "Select linear commits from one Git root.",
            nextStep: "Do not include merge commits or commits from another repository."
        )
        return
    }
    guard let firstCommit = commits.first,
          let repo = logRepository(for: firstCommit) else {
        feedbackCenter.warning(
            "Add commits unavailable",
            detail: "Selected commits must belong to one Git root.",
            nextStep: "Select commits from one repository and retry."
        )
        return
    }
    let branch = ContentView.branchNameForProtection(remoteBranch)
    let ordered = commits.count > 1 ? Array(commits.reversed()) : commits
    let commitIDs = ordered.map(\.id)
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    let cancel = GitCancelHandle()
    let notificationID = addCommitsToRemoteBranchNotificationID(
        repositoryPath: repo.workdir() ?? ""
    )
    beginFeedbackOperation(
        "Add commits to remote branch",
        cancelHandle: cancel,
        notificationID: notificationID
    )
    Task.detached(priority: .userInitiated) {
        do {
            _ = try repo.fetchRemoteBranchWithOptionsAndAuthAndCancel(
                remote: remoteBranch.remote,
                branch: branch,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel
            )
            guard !Task.isCancelled, !cancel.isCancelled() else {
                throw EngineError.Cancelled
            }
            let tip = try repo.prepareAddCommitsToRemoteBranch(
                remote: remoteBranch.remote,
                branch: branch,
                commitIds: commitIDs
            )
            guard !Task.isCancelled, !cancel.isCancelled() else {
                throw EngineError.Cancelled
            }
            await MainActor.run {
                guard !cancel.isCancelled() else {
                    self.feedbackCenter.warning(
                        "Add commits to remote branch canceled",
                        detail: "The remote branch was fetched, but no detached replay was published.",
                        notificationID: notificationID,
                        notificationGroup: .important
                    )
                    return
                }
                if let tip {
                    self.feedbackCenter.success(
                        "Commits prepared for remote branch",
                        detail: "Prepared detached tip \(tip) for \(remoteBranch.name).",
                        notificationID: notificationID,
                        notificationGroup: .standard
                    )
                    self.pushDialogMode = .addCommitsToRemoteBranch
                    self.pushDialogRemote = remoteBranch.remote
                    self.pushDialogBranch = branch
                    self.pushDialogSourceRevision = tip
                    self.pushDialogRefspec = nil
                    self.showPushDialog = true
                } else {
                    self.feedbackCenter.success(
                        "No commits to add",
                        detail: "All selected changes are already present on \(remoteBranch.name).",
                        notificationID: notificationID,
                        notificationGroup: .standard
                    )
                }
            }
        } catch {
            await MainActor.run {
                let detail = friendlyRemoteError(error)
                if let engineError = error as? EngineError, case .Cancelled = engineError {
                    self.feedbackCenter.warning(
                        "Add commits to remote branch canceled",
                        detail: "The remote branch was fetched, but no detached replay was published.",
                        notificationID: notificationID,
                        notificationGroup: .important
                    )
                } else {
                    self.feedbackCenter.error(
                        "Add commits to remote branch failed",
                        detail: detail,
                        nextStep: "Resolve the conflict or authentication problem, then retry.",
                        notificationID: notificationID,
                        notificationGroup: .important
                    )
                }
                if self.isAuthenticationFailure(error) {
                    self.showHostingAuthPrompt = true
                }
            }
        }
    }
}

