/// Map IntelliJ's `Vcs.EditSource` to the macOS default application for the
/// current worktree file. Arbor is not an IDE, so this deliberately delegates
/// editing to the user's system file association rather than embedding one.
func editSourceFromLog(_ path: String) {
    guard let repo = logRepository, let workdir = repo.workdir() else {
        feedbackCenter.error(
            "Edit source unavailable",
            detail: "No repository is open.",
            nextStep: "Open a Git repository, then retry."
        )
        return
    }

    let root = URL(fileURLWithPath: workdir).standardizedFileURL
    let components = path.split(separator: "/", omittingEmptySubsequences: true)
    guard !components.isEmpty, !components.contains("..") else {
        feedbackCenter.error(
            "Edit source unavailable",
            detail: "The selected path is not a repository-relative file.",
            nextStep: "Refresh the Changes browser and retry."
        )
        return
    }
    let fileURL = root
        .appendingPathComponent(components.joined(separator: "/"))
        .standardizedFileURL
    guard fileURL.path == root.path || fileURL.path.hasPrefix(root.path + "/") else {
        feedbackCenter.error(
            "Edit source unavailable",
            detail: "The selected path is outside the repository.",
            nextStep: "Refresh the Changes browser and retry."
        )
        return
    }

    guard FileManager.default.fileExists(atPath: fileURL.path) else {
        NSWorkspace.shared.activateFileViewerSelecting([fileURL.deletingLastPathComponent()])
        feedbackCenter.warning(
            "Source file unavailable",
            detail: "\(path) is not present in the current worktree.",
            nextStep: "Use Show File at Revision to inspect the historical copy."
        )
        return
    }

    guard NSWorkspace.shared.open(fileURL) else {
        feedbackCenter.error(
            "Open source failed",
            detail: "macOS could not open \(path) with its default application.",
            nextStep: "Choose an application for this file type in Finder."
        )
        return
    }
}

/// Restore selected historical file versions into both the index and worktree.
/// This is the Changes Browser's `Vcs.GetVersion` action. IntelliJ accepts the
/// complete selected-change set, so a single confirmation covers multi-file,
/// multi-commit, and multi-root selections.
func restoreSelectedFilesFromRevisions(_ records: [LogChangeRecord]) {
    guard !records.isEmpty else { return }
    let requests = records.compactMap { record -> (Repository, String, String, String)? in
        guard let repo = logRepository(for: record.commit) else { return nil }
        return (
            repo,
            record.change.path,
            record.commit.id,
            "\(record.commit.repositoryPath ?? "Git root") · \(record.commit.shortId) · \(record.change.path)"
        )
    }
    guard !requests.isEmpty else { return }

    let alert = NSAlert()
    alert.messageText = records.count == 1 ? "Get file version?" : "Get file versions?"
    let rootCount = max(
        1,
        Set(records.compactMap(\.commit.repositoryPath).filter { !$0.isEmpty }).count
    )
    alert.informativeText = "Replace the index and working tree copies of \(requests.count) file(s) from \(rootCount) Git root(s)?"
    alert.alertStyle = .warning
    alert.addButton(withTitle: records.count == 1 ? "Get Version" : "Get Versions")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    beginFeedbackOperation(records.count == 1 ? "Get file version" : "Get file versions")
    Task.detached(priority: .userInitiated) {
        var restoredCount = 0
        var failures: [String] = []
        for (repo, path, revision, label) in requests {
            do {
                try repo.restoreFile(path: path, revision: revision)
                restoredCount += 1
            } catch {
                failures.append("\(label): \(errorMessage(error))")
            }
        }

        let restored = restoredCount
        let failed = failures
        await MainActor.run {
            self.refreshAll(showFeedback: false)
            if failed.isEmpty {
                self.feedbackCenter.success(
                    restored == 1 ? "File restored" : "Files restored",
                    detail: "\(restored) file(s)"
                )
            } else if restored > 0 {
                self.feedbackCenter.warning(
                    "Some files could not be restored",
                    detail: "Restored \(restored); failed \(failed.count). \(failed.joined(separator: " | "))",
                    nextStep: "Check the selected revisions and retry the failed files."
                )
            } else {
                self.feedbackCenter.error(
                    "Get file versions failed",
                    detail: failed.joined(separator: " | "),
                    nextStep: "Check the selected revisions and retry."
                )
            }
        }
    }
}

/// Apply or reverse selected Changes Browser records as worktree patches.
/// Unlike Get Version this keeps the index untouched and leaves unrelated
/// files alone. IntelliJ applies every selected commit/parent patch in one
/// action; keep root-qualified batches ordered and stop at the first failure
/// so a conflict never allows later patches to run against an unresolved tree.
func applySelectedChangesFromLog(
    _ records: [LogChangeRecord],
    reverse: Bool
) {
    let groups = logChangePatchGroups(records)
    guard !groups.isEmpty else { return }
    let requests = groups.compactMap { group -> (Repository, CommitInfo, UInt32?, [String])? in
        guard let first = group.first,
              let repo = logRepository(for: first.commit) else {
            return nil
        }
        return (
            repo,
            first.commit,
            first.parentIndex,
            group.map(\.change.path)
        )
    }
    guard requests.count == groups.count else { return }
    let requestRootPaths = Set(requests.compactMap { request in
        request.0.workdir().map { URL(fileURLWithPath: $0).standardizedFileURL.path }
    })
    let refreshMultiRootChanges = requestRootPaths.count > 1

    let action = reverse ? "Revert Selected Changes" : "Apply Selected Changes"
    let question = reverse ? "Revert selected changes?" : "Apply selected changes?"
    let fileCount = records.count
    let commitCount = Set(records.map { record in
        "\(record.commit.repositoryPath ?? "")\u{1f}\(record.commit.id)"
    }).count
    let worktreeScope = requestRootPaths.count > 1
        ? " across \(requestRootPaths.count) Git roots"
        : " in the current worktree"
    let notificationID = logChangesPatchNotificationID(
        rootPaths: Array(requestRootPaths),
        reverse: reverse
    )
    let detail = reverse
        ? "Reverse \(fileCount) file change(s) from \(commitCount) commit(s)\(worktreeScope)."
        : "Apply \(fileCount) file change(s) from \(commitCount) commit(s)\(worktreeScope)."
    let alert = NSAlert()
    alert.messageText = question
    alert.informativeText = detail + " The index and unrelated files will not be changed."
    alert.alertStyle = .warning
    alert.addButton(withTitle: reverse ? "Revert Changes" : "Apply Changes")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    beginFeedbackOperation(action, notificationID: notificationID)
    Task.detached(priority: .userInitiated) {
        var appliedFiles = 0
        for (repo, commit, parentIndex, paths) in requests {
            do {
                try repo.applySelectedCommitChanges(
                    commitId: commit.id,
                    parentIndex: parentIndex,
                    paths: paths,
                    reverse: reverse
                )
                appliedFiles += paths.count
            } catch {
                let completed = appliedFiles
                if case let .ShelveApplyConflict(conflictName, conflictPaths) = error as? EngineError {
                    let restoreInfo = (try? repo.shelveRestoreInfo()) ?? nil
                    let patchText = restoreInfo?.patch
                    await MainActor.run {
                        self.presentShelveConflict(
                            name: conflictName,
                            paths: conflictPaths,
                            isPop: false,
                            isDirectPatch: true,
                            patchText: patchText,
                            repository: repo,
                            notificationID: notificationID
                        )
                        if refreshMultiRootChanges {
                            self.loadMultiRootChanges()
                        }
                    }
                } else {
                    await MainActor.run {
                        self.refreshAll(showFeedback: false)
                        if refreshMultiRootChanges {
                            self.loadMultiRootChanges()
                        }
                        if completed > 0 {
                            self.feedbackCenter.warning(
                                "Some selected changes applied",
                                detail: "Applied \(completed) file(s); the remaining patch failed: \(errorMessage(error))",
                                nextStep: "Review the worktree and retry the failed selection.",
                                notificationID: notificationID
                            )
                        } else {
                            self.feedbackCenter.error(
                                "\(action) failed",
                                detail: errorMessage(error),
                                nextStep: "Review local changes and patch applicability, then retry.",
                                notificationID: notificationID
                            )
                        }
                    }
                }
                return
            }
        }
        let totalAppliedFiles = appliedFiles
        await MainActor.run {
            self.feedbackCenter.success(
                action,
                detail: "\(totalAppliedFiles) file(s) from \(commitCount) commit(s)\(requestRootPaths.count > 1 ? " across \(requestRootPaths.count) Git roots" : "")",
                notificationID: notificationID
            )
            self.refreshAll(showFeedback: false)
            if refreshMultiRootChanges {
                self.loadMultiRootChanges()
            }
        }
    }
}

/// LOG-005：复制与 Log 提交对应的远程仓库链接。
func copyRevisionLinkFromLog(_ commit: CommitInfo, remote: RemoteInfo) {
    guard let repo = logRepository(for: commit) else {
        feedbackCenter.error(
            "Copy repository link unavailable",
            detail: "The commit's Git root is no longer available.",
            nextStep: "Refresh the project and retry."
        )
        return
    }
    Task.detached(priority: .userInitiated) {
        let link = repo.permalink(remoteUrl: remote.url, commitId: commit.id)
        await MainActor.run {
            guard let link else {
                self.feedbackCenter.error(
                    "Copy repository link unavailable",
                    detail: "The remote does not expose a repository permalink.",
                    nextStep: "Use Copy Commit ID instead."
                )
                return
            }
            NSPasteboard.general.clearContents()
            NSPasteboard.general.setString(link, forType: .string)
            self.feedbackCenter.success("Repository link copied", detail: link)
        }
    }
}

