func commitAndPush(
    remote: String?,
    branch: String?,
    force: Bool,
    forceWithLease: Bool? = nil,
    setUpstream: Bool = false,
    skipChecks: Bool = false
) {
    guard let repo else { return }
    let targetBranch = branch ?? currentBranchName
    let useForceWithLease = GitPushSettings.useForceWithLease(force: force, requested: forceWithLease)
    if force,
       GitProtectedBranchRules.matches(
           targetBranch,
           patterns: effectiveProtectedBranchPatterns
       ) {
        feedbackCenter.error(
            "Force push blocked",
            detail: "\(targetBranch) is protected by Git settings.",
            nextStep: "Edit Protected Branches in Settings or use a non-force push."
        )
        return
    }
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Commit and push", cancelHandle: cancel)
    let msg = commitMessage
    let hooks = GitCommitHooksSettings.effectiveSkipHooks(requested: self.skipHooks)
    let checks = beforeCommitCommands
    let authorNameOverride = identityAuthorName.trimmingCharacters(in: .whitespacesAndNewlines)
    let authorEmailOverride = identityAuthorEmail.trimmingCharacters(in: .whitespacesAndNewlines)
    let committerNameOverride = identityCommitterName.trimmingCharacters(in: .whitespacesAndNewlines)
    let committerEmailOverride = identityCommitterEmail.trimmingCharacters(in: .whitespacesAndNewlines)
    let signOff = identitySignOff
    let coAuthors = parseCoAuthors(identityCoAuthors)
    let broker = credentialAuth.broker
    rememberCommitAuthor(
        name: authorNameOverride,
        email: authorEmailOverride,
        projectPath: projectPath
    )
    Task.detached(priority: .userInitiated) {
        do {
            if !skipChecks {
                try runBeforeCommitChecks(repo: repo, commands: checks)
            }
            let identity = try? repo.gitIdentity()
            let hasOverrides = !authorNameOverride.isEmpty || !authorEmailOverride.isEmpty
                || !committerNameOverride.isEmpty || !committerEmailOverride.isEmpty || signOff || !coAuthors.isEmpty
            let outcome: CommitPushOutcome
            if identity?.signCommits == true || hasOverrides {
                outcome = try withArborPinentrySession {
                    try repo.commitAndPushWithIdentityWithAuthAndCancel(
                        message: msg,
                        remote: remote,
                        branch: branch,
                        force: force,
                        forceWithLease: useForceWithLease,
                        skipHooks: hooks,
                        setUpstream: setUpstream,
                        authorName: authorNameOverride.isEmpty ? nil : authorNameOverride,
                        authorEmail: authorEmailOverride.isEmpty ? nil : authorEmailOverride,
                        committerName: committerNameOverride.isEmpty ? nil : committerNameOverride,
                        committerEmail: committerEmailOverride.isEmpty ? nil : committerEmailOverride,
                        signKey: identity?.signingKey,
                        signOff: signOff,
                        coAuthors: coAuthors,
                        broker: broker,
                        cancel: cancel
                    )
                }
            } else {
                outcome = try repo.commitAndPushWithOptionsWithAuthAndCancel(
                    message: msg,
                    remote: remote,
                    branch: branch,
                    force: force,
                    forceWithLease: useForceWithLease,
                    skipHooks: hooks,
                    setUpstream: setUpstream,
                    broker: broker,
                    cancel: cancel
                )
            }
            let st = try repo.status()
            let cls = (try? repo.changelistList()) ?? []
            let hid = repo.headCommitId()
            let recent = (try? repo.recentCommitMessages(limit: 10)) ?? []
            let staging = try? repo.stagingModel()
            let branchList = (try? repo.branchList()) ?? []
            let syncStatuses = (try? repo.syncStatus()) ?? []
            await MainActor.run {
                self.entries = st
                self.changeLists = cls
                self.headId = hid
                self.stagingModel = staging
                self.lastIndexRevision = staging?.indexRevision
                self.branches = branchList
                self.syncStatuses = syncStatuses
                self.recentMessages = recent
                if self.toolWindowMode == .log {
                    self.loadLog()
                }
                self.commitMessage = ""
                self.pushFeedback = outcome.pushed
                    ? "已提交并推送 \(String(outcome.commitId.prefix(7)))"
                    : "已提交 \(String(outcome.commitId.prefix(7)))（未推送：没有可用远程或分支）"
                self.commitFeedback = self.pushFeedback
            }
        } catch {
            await MainActor.run {
                if let checkError = error as? BeforeCommitCheckError {
                    self.feedbackCenter.warning(
                        "Commit checks failed",
                        detail: "\(checkError.command)\n\n\(checkError.output)",
                        nextStep: "Review the check output, then retry or choose the force action."
                    )
                    let alert = NSAlert()
                    alert.messageText = "提交前检查失败"
                    alert.informativeText = "\(checkError.command)\n\n\(checkError.output)"
                    alert.addButton(withTitle: "强制提交并推送")
                    alert.addButton(withTitle: "取消")
                    if alert.runModal() == .alertFirstButtonReturn {
                        self.commitAndPush(
                            remote: remote,
                            branch: branch,
                            force: force,
                            forceWithLease: useForceWithLease,
                            setUpstream: setUpstream,
                            skipChecks: true
                        )
                    }
                    return
                }
                self.pushFeedback = friendlyRemoteError(error)
                self.commitFeedback = self.pushFeedback
                let detail = errorMessage(error)
                if gitCommitSigningFailureNeedsGPGConfiguration(detail) {
                    self.feedbackCenter.error(
                        "Commit signing failed",
                        detail: detail,
                        nextStep: "Install GnuPG if needed, or configure a working pinentry program, then retry the commit.",
                        additionalActions: [self.gpgAgentSettingsFeedbackAction()],
                        notificationID: self.repo?.workdir().map(self.pushNotificationID)
                    )
                }
                if self.isAuthenticationFailure(error) {
                    self.showHostingAuthPrompt = true
                }
                self.offerPushRecovery(
                    error,
                    remote: remote,
                    branch: branch,
                    force: force,
                    forceWithLease: useForceWithLease,
                    setUpstream: setUpstream,
                    afterCommit: true
                )
            }
        }
    }
}

func showInFinder(_ repo: Repository) {
    guard let workdir = repo.workdir() else { return }
    NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: workdir)])
}

func loadTreeChanges() {
    compareLoadTask?.cancel()
    compareLoadTask = nil
    let comparisonRepo = activeCompareRepo ?? repo
    guard let comparisonRepo else {
        treeChanges = []
        compareSelection = nil
        compareSelectedPaths = []
        compareError = nil
        return
    }
    let old = compareRev1.trimmingCharacters(in: .whitespaces)
    let new = compareRev2.trimmingCharacters(in: .whitespaces)
    let usesWorkingTree = compareWithWorkingTree
    let tabID = currentLogTabID
    guard !old.isEmpty, usesWorkingTree || !new.isEmpty else {
        treeChanges = []
        compareSelection = nil
        compareSelectedPaths = []
        compareError = "请输入两个 revision"
        return
    }
    let task = Task.detached(priority: .userInitiated) {
        do {
            let changes = if usesWorkingTree {
                try comparisonRepo.treeChangesWithWorktree(revision: old)
            } else {
                try comparisonRepo.treeChanges(rev1: old, rev2: new)
            }
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard !Task.isCancelled,
                      self.externalLogTabIsAlive(tabID),
                      self.compareRev1.trimmingCharacters(in: .whitespaces) == old,
                      (usesWorkingTree || self.compareRev2.trimmingCharacters(in: .whitespaces) == new),
                      self.compareWithWorkingTree == usesWorkingTree,
                      self.activeCompareRepo === comparisonRepo ||
                        (self.activeCompareRepo == nil && self.projectRepo === comparisonRepo) else { return }
                self.treeChanges = changes
                // The reference changes browser selects the first affected
                // file when a comparison is opened, so the right preview is
                // immediately useful instead of showing a blank inspector.
                self.compareSelection = changes.first?.path
                self.compareSelectedPaths = changes.first.map { [$0.path] } ?? []
                self.compareError = nil
            }
        } catch {
            await MainActor.run {
                guard !Task.isCancelled,
                      self.externalLogTabIsAlive(tabID),
                      self.compareRev1.trimmingCharacters(in: .whitespaces) == old,
                      (usesWorkingTree || self.compareRev2.trimmingCharacters(in: .whitespaces) == new),
                      self.compareWithWorkingTree == usesWorkingTree,
                      self.activeCompareRepo === comparisonRepo ||
                        (self.activeCompareRepo == nil && self.projectRepo === comparisonRepo) else { return }
                self.treeChanges = []
                self.compareSelection = nil
                self.compareSelectedPaths = []
                self.compareError = errorMessage(error)
            }
        }
    }
    compareLoadTask = task
}

func beginNewTagDialog() {
    tagRepositoryOverride = nil
    tagForce = false
    showNewTagDialog = true
}

/// Open the shared Tag dialog for a Log commit, retaining the commit's own
/// repository so a multi-root Log cannot create the tag in the primary root.
func beginCreateTagFromLog(_ commit: CommitInfo) {
    guard let targetRepo = logRepository(for: commit) else {
        feedbackCenter.warning(
            "Create Tag unavailable",
            detail: "The selected commit's Git root could not be opened.",
            nextStep: "Refresh Git Roots, then retry from the commit history."
        )
        return
    }
    tagRepositoryOverride = targetRepo
    tagAt = commit.id
    tagForce = false
    showNewTagDialog = true
}

func createTag() {
    guard let targetRepo = tagRepositoryOverride ?? repo else { return }
    let name = tagName.trimmingCharacters(in: .whitespaces)
    guard !name.isEmpty else { return }
    let at = tagAt.trimmingCharacters(in: .whitespaces)
    let annotated = tagAnnotated
    let force = tagForce
    let message = tagMessage
    let signKey = tagSignKey.trimmingCharacters(in: .whitespacesAndNewlines)
    let targetRootPath = targetRepo.workdir()
    beginFeedbackOperation("Create tag")
    Task.detached(priority: .userInitiated) {
        do {
            if annotated {
                if signKey.isEmpty {
                    try targetRepo.tagCreateWithOptionsAndForce(
                        name: name,
                        at: at.isEmpty ? nil : at,
                        message: message,
                        signKey: nil,
                        force: force
                    )
                } else {
                    try withArborPinentrySession {
                        try targetRepo.tagCreateWithOptionsAndForce(
                            name: name,
                            at: at.isEmpty ? nil : at,
                            message: message,
                            signKey: signKey,
                            force: force
                        )
                    }
                }
            } else {
                try targetRepo.tagCreateWithForce(
                    name: name,
                    at: at.isEmpty ? nil : at,
                    force: force
                )
            }
            let tags = try targetRepo.tagList()
            await MainActor.run {
                if targetRootPath == self.repo?.workdir() {
                    self.tags = tags
                }
                self.tagName = ""
                self.tagAt = ""
                self.tagMessage = ""
                self.tagSignKey = ""
                self.tagAnnotated = false
                self.tagForce = false
                self.tagRepositoryOverride = nil
                self.tagFeedback = "已创建 \(name)"
                self.feedbackCenter.success(
                    "Tag created",
                    detail: targetRootPath.map { "\(name) @ \($0)" } ?? name
                )
                if self.toolWindowMode == .log { self.loadLog() }
            }
        } catch {
            await MainActor.run {
                let detail = friendlyRemoteError(error)
                self.tagFeedback = detail
                let signingAction = !signKey.isEmpty
                    || gitCommitSigningFailureNeedsGPGConfiguration(detail)
                    ? [self.gpgAgentSettingsFeedbackAction()]
                    : []
                self.feedbackCenter.error(
                    "Create tag failed",
                    detail: detail,
                    nextStep: !signKey.isEmpty
                        ? "Install GnuPG if needed, configure pinentry, then retry the signed tag."
                        : "Check the tag name and selected Git root, then retry.",
                    additionalActions: signingAction
                )
            }
        }
    }
}

func deleteTag(_ name: String) {
    guard let repo else { return }
    beginFeedbackOperation("Delete tag")
    Task.detached(priority: .userInitiated) {
        do {
            guard let tag = try repo.tagList().first(where: { $0.name == name }) else {
                throw NSError(
                    domain: "Arbor.TagDelete",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "Tag not found: \(name)"]
                )
            }
            try repo.tagDelete(name: name)
            let tags = try repo.tagList()
            await MainActor.run {
                self.tags = tags
                self.tagFeedback = "已删除 \(name)"
                self.tagDeleteRecovery = TagDeleteRecoveryContext(repo: repo, tag: tag, rootPath: nil)
                if self.toolWindowMode == .log { self.loadLog() }
            }
        } catch {
            await MainActor.run { self.tagFeedback = errorMessage(error) }
        }
    }
}

func pushTag(_ tag: String, remote selectedRemote: String? = nil) {
    guard let repo,
          let remote = resolveSelectedRemoteName(
              selectedRemote: selectedRemote,
              availableRemoteNames: remotes.map(\.name)
          ) else {
        feedbackCenter.warning(
            "Choose a remote before pushing the tag",
            detail: "Multiple remotes are configured for this Git root."
        )
        return
    }
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Push tag", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            try repo.tagPushWithAuthAndCancel(
                remote: remote,
                tag: tag,
                broker: broker,
                cancel: cancel
            )
            await MainActor.run { self.tagFeedback = "已推送 \(tag)" }
        } catch {
            await MainActor.run {
                self.tagFeedback = friendlyRemoteError(error)
                if self.isAuthenticationFailure(error) { self.showHostingAuthPrompt = true }
            }
        }
    }
}

func presentNewBranchDialog(
    baseRevision: String? = nil,
    suggestedName: String? = nil,
    title: String? = nil,
    afterCreateRebase: Bool = false,
    repositoryOverride: Repository? = nil
) {
    newBranchName = suggestedName ?? ""
    newBranchBase = baseRevision ?? ""
    newBranchDialogTitle = title ?? String(localized: "New Branch")
    newBranchCheckout = true
    newBranchResetExisting = false
    newBranchAfterCreateRebase = afterCreateRebase
    newBranchRepositoryOverride = repositoryOverride
    if let targetRepo = repositoryOverride ?? repo {
        newBranchDialogBranches = (try? targetRepo.branchList()) ?? branches
    } else {
        newBranchDialogBranches = branches
    }
    showNewBranchDialog = true
}

func dismissNewBranchDialog() {
    showNewBranchDialog = false
    newBranchDialogTitle = String(localized: "New Branch")
    newBranchName = ""
    newBranchBase = ""
    newBranchCheckout = true
    newBranchResetExisting = false
    newBranchAfterCreateRebase = false
    newBranchRepositoryOverride = nil
    newBranchDialogBranches = []
}

/// Shared Branch Dashboard semantics for a single Git root. IntelliJ's
/// Checkout as New Branch keeps the selected ref as the start point; the
/// remote Checkout with Rebase variant creates the local branch first and
/// then rebases it onto the current branch.
func presentNewBranchFromReference(
    _ reference: String,
    isRemote: Bool,
    afterCreateRebase: Bool = false,
    rootPath: String? = nil
) {
    let trimmedReference = reference.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmedReference.isEmpty else { return }
    let suggestedName: String
    if isRemote,
       let separator = trimmedReference.firstIndex(of: "/") {
        let suffixStart = trimmedReference.index(after: separator)
        suggestedName = suffixStart < trimmedReference.endIndex
            ? String(trimmedReference[suffixStart...])
            : trimmedReference
    } else {
        suggestedName = trimmedReference
    }
    let repositoryOverride: Repository?
    if let rootPath {
        guard let selectedRepository = try? openRepository(path: rootPath) else {
            feedbackCenter.warning(
                "Checkout with Rebase unavailable",
                detail: "The selected Git root could not be opened.",
                nextStep: "Refresh Git Roots, then retry from the branch or tag."
            )
            return
        }
        repositoryOverride = selectedRepository
    } else {
        repositoryOverride = nil
    }
    presentNewBranchDialog(
        baseRevision: trimmedReference,
        suggestedName: afterCreateRebase ? suggestedName : suggestedName + "-copy",
        title: afterCreateRebase ? "Checkout with Rebase" : "Checkout as New Branch",
        afterCreateRebase: afterCreateRebase,
        repositoryOverride: repositoryOverride
    )
}

/// IntelliJ's Create New Working Tree action is repository-scoped. The
/// multi-root Branches Popup therefore carries the selected root into the
/// same dialog instead of pretending that one worktree operation spans roots.
func presentNewWorktreeFromReference(
    _ reference: String,
    isTag: Bool,
    rootPath: String? = nil
) {
    let selectedRootPath = rootPath ?? repo?.workdir()
    guard let selectedRootPath, !selectedRootPath.isEmpty else { return }
    if rootPath != nil, (try? openRepository(path: selectedRootPath)) == nil {
        feedbackCenter.warning(
            "New Working Tree unavailable",
            detail: "The selected Git root could not be opened.",
            nextStep: "Refresh Git Roots, then retry from the branch or tag."
        )
        return
    }
    let trimmedReference = reference.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmedReference.isEmpty else { return }
    newWorktreeRootPath = selectedRootPath
    newWorktreeReference = trimmedReference
    newWorktreeIsTag = isTag
    newWorktreePath = ""
    newWorktreeBranch = ""
    showNewWorktreeDialog = true
}

func dismissNewWorktreeDialog() {
    showNewWorktreeDialog = false
    newWorktreeRootPath = nil
    newWorktreeReference = ""
    newWorktreeIsTag = false
    newWorktreePath = ""
    newWorktreeBranch = ""
}

func createBranchFromCommit(_ commit: CommitInfo) {
    guard let targetRepo = logRepository(for: commit) else {
        feedbackCenter.warning(
            "Create Branch unavailable",
            detail: "The selected commit's Git root could not be opened.",
            nextStep: "Refresh Git Roots, then retry from the commit history."
        )
        return
    }
    presentNewBranchDialog(
        baseRevision: commit.id,
        suggestedName: "branch-\(commit.shortId)",
        title: String(localized: "New Branch from %@")
            .replacingOccurrences(of: "%@", with: commit.shortId),
        repositoryOverride: targetRepo
    )
}

// MARK: Log context actions

nonisolated private func configuredCherryPickEmptyPolicy() -> CherryPickEmptyPolicy {
    configuredCherryPickEmptyPolicyChoice().engineValue
}

nonisolated private func configuredCherryPickEmptyPolicyChoice() -> GitCherryPickEmptyPolicyChoice {
    let rawValue = UserDefaults.standard.string(forKey: GitCherryPickSettings.emptyPolicyKey)
        ?? GitCherryPickSettings.defaultEmptyPolicy.rawValue
    return GitCherryPickEmptyPolicyChoice(rawValue: rawValue)
        ?? GitCherryPickSettings.defaultEmptyPolicy
}

nonisolated private static func branchNameForProtection(_ remoteBranch: RemoteBranchInfo) -> String {
    let prefix = "\(remoteBranch.remote)/"
    if remoteBranch.name.hasPrefix(prefix) {
        return String(remoteBranch.name.dropFirst(prefix.count))
    }
    return remoteBranch.name.split(separator: "/", maxSplits: 1).dropFirst().joined(separator: "/")
}

/// Returns the first protected remote branch that contains a commit. This is
/// the same reachability rule IntelliJ uses before Log history editing: a
/// published commit on a protected branch must not be rewritten locally.
nonisolated static func protectedRemoteBranchNameContainingCommit(
    commitID: String,
    remoteBranches: [RemoteBranchInfo],
    protectedPatterns: [String],
    isReachable: (String, String) -> Bool
) -> String? {
    remoteBranches.first { remoteBranch in
        GitProtectedBranchRules.matches(
            ContentView.branchNameForProtection(remoteBranch),
            patterns: protectedPatterns
        ) && isReachable(commitID, remoteBranch.name)
    }?.name
}

/// Derive the oldest commit in the original rewritten range. IntelliJ uses
/// the first changed commit rather than blindly checking the old tip. The
/// merge-base fallback keeps older persisted Undo actions safe when Git cannot
/// resolve a common ancestor or the original range is no longer available.
nonisolated private func rebaseUndoProtectionCommit(
    repo: Repository,
    initialHead: String,
    expectedHead: String,
    recordedCommitID: String?
) -> String {
    if let recordedCommitID,
       !recordedCommitID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
        return (try? repo.isCommitReachableFrom(
            commitId: recordedCommitID,
            descendantId: initialHead
        )) == true
            ? recordedCommitID
            : initialHead
    }
    guard initialHead != expectedHead,
          let base = try? repo.mergeBaseRevisionId(
              first: initialHead,
              second: expectedHead
          ),
          let commits = try? repo.logWithCommand(
              commandArgs: ["--reverse", "\(base)..\(initialHead)"],
              limit: 1
          ),
          let firstChangedCommit = commits.first?.id else {
        return initialHead
    }
    return firstChangedCommit
}

nonisolated private func protectedRemoteBranchContainingCommit(
    repo: Repository,
    commitID: String,
    remoteBranches: [RemoteBranchInfo],
    protectedPatterns: [String]
) -> String? {
    let containingBranches = Set(
        (try? repo.commitContainingBranches(commitId: commitID)) ?? []
    )
    return remoteBranches.first { remoteBranch in
        GitProtectedBranchRules.matches(
            ContentView.branchNameForProtection(remoteBranch),
            patterns: protectedPatterns
        ) && containingBranches.contains(remoteBranch.name)
    }?.name
}

/// Return the complete message shown by IntelliJ's Squash dialog.
private nonisolated func completeCommitMessage(_ commit: CommitInfo) -> String {
    commit.messageBody.isEmpty
        ? commit.summary
        : "\(commit.summary)\n\n\(commit.messageBody)"
}

/// Match GitSquashedCommitsMessage.prettySquash closely enough for the
/// standalone Log Squash dialog: preserve full messages, remove duplicate
/// entries, and trim fixup!/squash! subjects when their target is selected.
private nonisolated func prettySquashMessage(_ commits: [CommitInfo]) -> String {
    let messages = commits.map(completeCommitMessage)
    let subjects = Set(messages.map { message in
        String(message.split(whereSeparator: \.isNewline).first ?? "")
    }.filter { subject in
        !subject.hasPrefix("fixup! ") && !subject.hasPrefix("squash! ")
    })
    var seen = Set<String>()
    let rendered = messages.compactMap { message -> String? in
        let subject = String(message.split(whereSeparator: \.isNewline).first ?? "")
        var value = message
        if subject.hasPrefix("fixup! ") || subject.hasPrefix("squash! ") {
            let target = subject.hasPrefix("fixup! ")
                ? String(subject.dropFirst("fixup! ".count))
                : String(subject.dropFirst("squash! ".count))
            if subjects.contains(target) {
                value = message.split(separator: "\n", maxSplits: 1, omittingEmptySubsequences: false)
                    .dropFirst()
                    .joined(separator: "\n")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
            }
        }
        guard !value.isEmpty, seen.insert(value).inserted else { return nil }
        return value
    }
    return rendered.joined(separator: "\n\n\n")
}

nonisolated private func shouldAppendCherryPickSuffix(
    projectPath: String?,
    commits: [CommitInfo],
    repo: Repository,
    remoteBranches: [RemoteBranchInfo],
    protectedPatterns: [String]
) -> Bool {
    guard GitCherryPickSettings.effectiveAppendPublishedSuffix(for: projectPath),
          !commits.isEmpty else {
        return false
    }
    let protectedBranches = remoteBranches.filter {
        GitProtectedBranchRules.matches(
            ContentView.branchNameForProtection($0),
            patterns: protectedPatterns
        )
    }
    guard !protectedBranches.isEmpty else { return false }
    return commits.allSatisfy { commit in
        protectedBranches.contains { remoteBranch in
            (try? repo.isCommitReachableFrom(
                commitId: commit.id,
                descendantId: remoteBranch.shortId
            )) == true
        }
    }
}

func cherryPickFromLog(_ commit: CommitInfo) {
    cherryPickCommitsFromLog([commit])
}

func cherryPickCommitsFromLog(_ commits: [CommitInfo]) {
    runLogApplyOperation(
        .cherryPick,
        commits: commits,
        confirm: false,
        preserveLocalChanges: false
    )
}

private enum LogApplyOperation: Equatable {
    case cherryPick
    case revert

    var title: String {
        switch self {
        case .cherryPick: "Cherry-pick"
        case .revert: "Revert"
        }
    }

    var smartTitle: String {
        switch self {
        case .cherryPick: "Smart Cherry-pick"
        case .revert: "Smart Revert"
        }
    }

    var pausedMessage: String {
        switch self {
        case .cherryPick: "Cherry-pick paused: resolve conflicts, then Continue or Abort"
        case .revert: "Revert paused: resolve conflicts, then Continue or Abort"
        }
    }
}

private nonisolated func executeLogApply(
    operation: LogApplyOperation,
    repo: Repository,
    commitIDs: [String],
    emptyPolicy: CherryPickEmptyPolicy,
    appendPublishedSuffix: Bool,
    preserveLocalChanges: Bool,
    savePolicy: LocalChangesSavePolicy
) throws -> String {
    switch operation {
    case .cherryPick:
        if preserveLocalChanges {
            return try repo.cherryPickManyWithOptionsAndPolicy(
                commitIds: commitIDs,
                emptyPolicy: emptyPolicy,
                appendSuffix: appendPublishedSuffix,
                savePolicy: savePolicy
            )
        }
        return try repo.cherryPickManyWithOptions(
            commitIds: commitIDs,
            emptyPolicy: emptyPolicy,
            appendSuffix: appendPublishedSuffix
        )
    case .revert:
        if preserveLocalChanges {
            return try repo.revertManyWithPolicy(
                commitIds: commitIDs,
                mainline: nil,
                savePolicy: savePolicy
            )
        }
        return try repo.revertMany(commitIds: commitIDs, mainline: nil)
    }
}

private func runLogApplyOperation(
    _ operation: LogApplyOperation,
    commits: [CommitInfo],
    confirm: Bool,
    preserveLocalChanges: Bool
) {
    guard !commits.isEmpty else { return }
    let batches = logCommitRootBatches(commits)
    guard !batches.isEmpty,
          batches.flatMap(\.commits).count == commits.count else {
        feedbackCenter.warning(
            "\(operation.title) unavailable",
            detail: "Every selected commit must belong to an available Git root.",
            nextStep: "Refresh Git Roots, then retry from the Log."
        )
        return
    }

    if operation == .revert,
       !commits.allSatisfy({ $0.parentIds.count == 1 }) {
        feedbackCenter.warning(
            "Revert unavailable",
            detail: "Root and merge commits cannot be reverted from this selection."
        )
        return
    }

    if confirm {
        let alert = NSAlert()
        if commits.count == 1, let commit = commits.first {
            alert.messageText = operation == .revert ? "Revert this commit?" : "Cherry-pick this commit?"
            alert.informativeText = operation == .revert
                ? "A new inverse commit will be created for \(commit.shortId) \(commit.summary)."
                : "A new commit will be created from \(commit.shortId) \(commit.summary)."
        } else {
            alert.messageText = operation == .revert ? "Revert selected commits?" : "Cherry-pick selected commits?"
            alert.informativeText = operation == .revert
                ? "A new inverse commit will be created for each selected commit across its Git root."
                : "A new commit will be created for each selected commit in its Git root."
        }
        alert.addButton(withTitle: operation == .revert ? "Revert" : "Cherry-pick")
        alert.addButton(withTitle: "Cancel")
        guard alert.runModal() == .alertFirstButtonReturn else { return }
    }

    beginFeedbackOperation(operation.title)
    let emptyPolicyChoice = configuredCherryPickEmptyPolicyChoice()
    let emptyPolicy = emptyPolicyChoice.engineValue
    let protectedPatterns = effectiveProtectedBranchPatterns
    let savePolicyChoice = GitLocalChangesSavePolicySettings.choice(for: projectPath)
    let operationProjectPath = projectPath
    let logApplySessionID = UUID().uuidString
    let logApplyBatchCount = batches.count
    Task.detached(priority: .userInitiated) {
        // Save every root before the first engine mutation. A process exit
        // between two roots must not erase the remaining Log selection.
        var preparedRecoveries: [String: PersistedLogApplyRecovery] = [:]
        for (batchIndex, batch) in batches.enumerated() {
            let orderedCommits = operation == .cherryPick && batch.commits.count > 1
                ? Array(batch.commits.reversed())
                : batch.commits
            guard let batchRepo = try? openRepository(path: batch.rootPath),
                  let initialHead = batchRepo.headCommitId(),
                  let rootPath = batchRepo.workdir() else { continue }
            let remoteBranches = (try? batchRepo.remoteBranchList()) ?? []
            let appendSuffix = operation == .cherryPick && shouldAppendCherryPickSuffix(
                projectPath: operationProjectPath,
                commits: orderedCommits,
                repo: batchRepo,
                remoteBranches: remoteBranches,
                protectedPatterns: protectedPatterns
            )
            let recovery = PersistedLogApplyRecovery(
                operation: operation == .cherryPick ? .cherryPick : .revert,
                rootPath: rootPath,
                commitIDs: orderedCommits.map(\.id),
                sessionID: logApplySessionID,
                batchIndex: batchIndex,
                batchCount: logApplyBatchCount,
                initialHead: initialHead,
                preserveLocalChanges: preserveLocalChanges,
                emptyPolicyRaw: emptyPolicyChoice.rawValue,
                appendPublishedSuffix: appendSuffix,
                savePolicyRaw: savePolicyChoice.rawValue
            )
            saveLogApplyRecovery(recovery)
            preparedRecoveries[rootPath] = recovery
        }

        var completedCommits: [CommitInfo] = []
        var resultIDs: [(String, String)] = []
        for (batchIndex, batch) in batches.enumerated() {
            do {
                let repo = try openRepository(path: batch.rootPath)
                // The Log is newest-first; Cherry-pick replays each root's
                // selected sequence oldest-first. Revert keeps IntelliJ's
                // existing UI order and Git's sequencer semantics.
                let orderedCommits = operation == .cherryPick && batch.commits.count > 1
                    ? Array(batch.commits.reversed())
                    : batch.commits
                let ids = orderedCommits.map(\.id)
                let resultID: String
                switch operation {
                case .cherryPick:
                    let recovery = preparedRecoveries[batch.rootPath]
                    let appendSuffix = recovery?.appendPublishedSuffix ?? {
                        let remoteBranches = (try? repo.remoteBranchList()) ?? []
                        return shouldAppendCherryPickSuffix(
                            projectPath: operationProjectPath,
                            commits: orderedCommits,
                            repo: repo,
                            remoteBranches: remoteBranches,
                            protectedPatterns: protectedPatterns
                        )
                    }()
                    if let initialHead = repo.headCommitId(),
                       let rootPath = repo.workdir(),
                       recovery == nil {
                        saveLogApplyRecovery(
                            PersistedLogApplyRecovery(
                                operation: operation == .cherryPick ? .cherryPick : .revert,
                                rootPath: rootPath,
                                commitIDs: ids,
                                sessionID: logApplySessionID,
                                batchIndex: batchIndex,
                                batchCount: logApplyBatchCount,
                                initialHead: initialHead,
                                preserveLocalChanges: preserveLocalChanges,
                                emptyPolicyRaw: emptyPolicyChoice.rawValue,
                                appendPublishedSuffix: appendSuffix,
                                savePolicyRaw: savePolicyChoice.rawValue
                            )
                        )
                    }
                    resultID = try executeLogApply(
                        operation: operation,
                        repo: repo,
                        commitIDs: ids,
                        emptyPolicy: emptyPolicy,
                        appendPublishedSuffix: appendSuffix,
                        preserveLocalChanges: preserveLocalChanges,
                        savePolicy: savePolicyChoice.engineValue
                    )
                case .revert:
                    let recovery = preparedRecoveries[batch.rootPath]
                    if let initialHead = repo.headCommitId(),
                       let rootPath = repo.workdir(),
                       recovery == nil {
                        saveLogApplyRecovery(
                            PersistedLogApplyRecovery(
                                operation: .revert,
                                rootPath: rootPath,
                                commitIDs: ids,
                                sessionID: logApplySessionID,
                                batchIndex: batchIndex,
                                batchCount: logApplyBatchCount,
                                initialHead: initialHead,
                                preserveLocalChanges: preserveLocalChanges,
                                emptyPolicyRaw: emptyPolicyChoice.rawValue,
                                appendPublishedSuffix: false,
                                savePolicyRaw: savePolicyChoice.rawValue
                            )
                        )
                    }
                    resultID = try executeLogApply(
                        operation: operation,
                        repo: repo,
                        commitIDs: ids,
                        emptyPolicy: emptyPolicy,
                        appendPublishedSuffix: false,
                        preserveLocalChanges: preserveLocalChanges,
                        savePolicy: savePolicyChoice.engineValue
                    )
                }
                if let rootPath = repo.workdir() {
                    clearLogApplyRecovery(repositoryPath: rootPath)
                }
                completedCommits.append(contentsOf: orderedCommits)
                resultIDs.append((batch.rootPath, resultID))
            } catch {
                let repo = try? openRepository(path: batch.rootPath)
                let pendingCommits = batches[batchIndex...].flatMap(\.commits)
                let status = repo.flatMap { try? $0.status() } ?? []
                let state = repo.flatMap { try? $0.operationState() }
                let firstConflict = status.first {
                    $0.staged == .conflicted || $0.unstaged == .conflicted
                }?.path
                let completedCommitsSnapshot = completedCommits
                await MainActor.run {
                    self.handleLogApplyFailure(
                        operation: operation,
                        error: error,
                        repo: repo,
                        status: status,
                        state: state,
                        firstConflict: firstConflict,
                        pendingCommits: pendingCommits,
                        completedCommits: completedCommitsSnapshot
                    )
                }
                return
            }
        }
        let resultIDsSnapshot = resultIDs
        await MainActor.run {
            let details = resultIDsSnapshot.map { rootPath, id in
                "\(rootPath): \(String(id.prefix(7)))"
            }.joined(separator: "\n")
            self.commitFeedback = operation.title
            self.feedbackCenter.success(operation.title, detail: details)
            self.logSelection = nil
            self.logSelectedIDs = []
            self.refreshAll(showFeedback: false)
        }
    }
}

func revertFromLog(_ commit: CommitInfo) {
    revertCommitsFromLog([commit])
}

func revertCommitsFromLog(_ commits: [CommitInfo]) {
    runLogApplyOperation(
        .revert,
        commits: commits,
        confirm: true,
        preserveLocalChanges: false
    )
}

private func handleLogApplyFailure(
    operation: LogApplyOperation,
    error: Error,
    repo: Repository?,
    status: [FileEntry],
    state: OperationState?,
    firstConflict: String?,
    pendingCommits: [CommitInfo],
    completedCommits: [CommitInfo]
) {
    if case let .LocalChangesWouldBeOverwritten(paths) = error as? EngineError {
        let expectedRecoveryOperation: PersistedLogApplyRecovery.Operation = operation == .revert
            ? .revert
            : .cherryPick
        if let recovery = repo?.workdir().flatMap({ loadLogApplyRecovery(repositoryPath: $0) }),
           recovery.operation == expectedRecoveryOperation {
            let savedRecovery = recovery.updating(
                preserveLocalChanges: true,
                affectedPaths: paths
            )
            saveLogApplyRecovery(savedRecovery)
            _ = publishLogApplyRecoveryNoticeIfNeeded(rootPath: savedRecovery.rootPath)
            return
        }

        feedbackCenter.warning(
            "\(operation.title) needs a decision",
            detail: paths.joined(separator: ", "),
            nextStep: "Choose \(operation.smartTitle) to preserve local changes, or cancel and keep the current worktree."
        )
        presentSmartOperationDecision(
            operationTitle: operation.title,
            paths: paths,
            detail: errorMessage(error),
            smartButtonTitle: operation.smartTitle,
            onSmart: {
                self.runLogApplyOperation(
                    operation,
                    commits: pendingCommits,
                    confirm: false,
                    preserveLocalChanges: true
                )
            }
        )
        return
    }

    if state != nil || firstConflict != nil {
        entries = status
        operationState = state
        mergeInProgress = true
        mergeInitialPath = firstConflict
        showMergeRevisionsDialog = true
        let completedDetail = completedCommits.isEmpty
            ? ""
            : " (\(completedCommits.count) commit(s) completed before this root)"
        commitFeedback = operation.pausedMessage + completedDetail
    } else {
        let expectedRecoveryOperation: PersistedLogApplyRecovery.Operation = operation == .revert
            ? .revert
            : .cherryPick
        let recovery = repo?.workdir().flatMap {
            loadLogApplyRecovery(repositoryPath: $0)
        }.flatMap { $0.operation == expectedRecoveryOperation ? $0 : nil }
        let recoveryRootPath = recovery?.rootPath
        feedbackCenter.error(
            "\(operation.title) failed",
            detail: errorMessage(error),
            nextStep: repo == nil
                ? "Refresh Git Roots, then retry."
                : "Review the selected root's status, then retry.",
            additionalActions: recovery.map {
                logApplyRecoveryActions($0)
            } ?? [],
            notificationID: recoveryRootPath.map {
                logApplyRecoveryNotificationID(rootPath: $0)
            }
        )
    }
}

/// Drop/Extract operate on a single commit's file selection from the Log
/// Changes browser. The engine preserves local changes around the object-level
/// rewrite, while the UI keeps the destructive action behind the same explicit
/// confirmation used by the reference workflow.
func dropSelectedChangesFromLog(_ commit: CommitInfo, paths: [String]) {
    guard let repo = logRepository(for: commit) else { return }
    let alert = NSAlert()
    alert.messageText = "Drop selected changes?"
    alert.informativeText = "The selected files will be removed from \(commit.shortId) and the rewritten history will replace the current branch tip."
    alert.addButton(withTitle: "Drop Changes")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    beginFeedbackOperation("Drop Selected Changes")
    Task.detached(priority: .userInitiated) {
        do {
            guard let rootPath = repo.workdir(),
                  let initialHead = repo.headCommitId() else {
                throw EngineError.GitOperation(
                    message: "Drop Selected Changes requires a worktree with a current HEAD."
                )
            }
            let expectedBranch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name ?? ""
            let outcome = try repo.dropSelectedChanges(commitId: commit.id, paths: paths)
            let undoTarget = LogSelectedChangesUndoTarget(
                repositoryPath: rootPath,
                branch: expectedBranch,
                initialHead: initialHead,
                expectedHead: outcome.headId
            )
            let notificationID = logSelectedChangesUndoNotificationID(
                repositoryPath: rootPath,
                expectedHead: outcome.headId
            )
            await MainActor.run {
                self.commitFeedback = "已从 \(commit.shortId) 丢弃 \(paths.count) 个文件变更"
                self.feedbackCenter.success(
                    "Drop Selected Changes",
                    detail: commit.shortId,
                    additionalActions: [logSelectedChangesUndoFeedbackAction(for: undoTarget)],
                    notificationID: notificationID
                )
                self.logSelection = nil
                let isCurrentRoot = self.repo?.workdir().map {
                    logSelectedChangesRootPathsMatch(rootPath, $0)
                } == true
                if isCurrentRoot {
                    self.refreshAll(showFeedback: false)
                    self.loadLog()
                } else {
                    self.loadMultiRoots {
                        let activeRootMatches = self.logActiveRootPath.map {
                            logSelectedChangesRootPathsMatch(rootPath, $0)
                        } == true
                        if self.isLogAggregate || self.logViewMode == .command || activeRootMatches {
                            self.reloadLogView()
                        }
                    }
                }
            }
        } catch {
            let failedRootPath = repo.workdir() ?? ""
            await MainActor.run {
                self.feedbackCenter.error(
                    "Drop Selected Changes failed",
                    detail: errorMessage(error),
                    nextStep: "本操作会保存并恢复本地修改；若恢复冲突，请先处理冲突或使用保留的临时 stash。目标须在当前分支 first-parent 历史中；merge 目标及其后继 merge 会保留 parent 拓扑并按 first-parent 变更重放，无法安全重放时会拒绝改写。rename 会按旧路径和新路径成对处理，submodule gitlink 会按子模块边界同步。"
                )
                self.presentLogSelectedChangesRestoreConflict(rootPath: failedRootPath)
            }
        }
    }
}

func extractSelectedChangesFromLog(_ commit: CommitInfo, paths: [String]) {
    guard let repo = logRepository(for: commit) else { return }
    let alert = NSAlert()
    alert.messageText = "Extract selected changes"
    alert.informativeText = "The selected files will become a new commit after \(commit.shortId)."
    let messageField = NSTextField(string: commit.summary)
    messageField.placeholderString = "New commit message"
    messageField.frame = NSRect(x: 0, y: 0, width: 360, height: 24)
    alert.accessoryView = messageField
    alert.addButton(withTitle: "Extract Changes")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    let message = messageField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !message.isEmpty else {
        feedbackCenter.warning(
            "Extract Selected Changes cancelled",
            detail: "A non-empty commit message is required.",
            nextStep: "Run the action again and enter a commit message."
        )
        return
    }

    beginFeedbackOperation("Extract Selected Changes")
    Task.detached(priority: .userInitiated) {
        do {
            guard let rootPath = repo.workdir(),
                  let initialHead = repo.headCommitId() else {
                throw EngineError.GitOperation(
                    message: "Extract Selected Changes requires a worktree with a current HEAD."
                )
            }
            let expectedBranch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name ?? ""
            let outcome = try repo.extractSelectedChanges(
                commitId: commit.id,
                paths: paths,
                newMessage: message
            )
            let undoTarget = LogSelectedChangesUndoTarget(
                repositoryPath: rootPath,
                branch: expectedBranch,
                initialHead: initialHead,
                expectedHead: outcome.headId
            )
            let notificationID = logSelectedChangesUndoNotificationID(
                repositoryPath: rootPath,
                expectedHead: outcome.headId
            )
            await MainActor.run {
                self.commitFeedback = "已将 \(paths.count) 个文件变更抽取为新提交"
                self.feedbackCenter.success(
                    "Extract Selected Changes",
                    detail: message,
                    additionalActions: [logSelectedChangesUndoFeedbackAction(for: undoTarget)],
                    notificationID: notificationID
                )
                self.logSelection = nil
                let isCurrentRoot = self.repo?.workdir().map {
                    logSelectedChangesRootPathsMatch(rootPath, $0)
                } == true
                if isCurrentRoot {
                    self.refreshAll(showFeedback: false)
                    self.loadLog()
                } else {
                    self.loadMultiRoots {
                        let activeRootMatches = self.logActiveRootPath.map {
                            logSelectedChangesRootPathsMatch(rootPath, $0)
                        } == true
                        if self.isLogAggregate || self.logViewMode == .command || activeRootMatches {
                            self.reloadLogView()
                        }
                    }
                }
            }
        } catch {
            let failedRootPath = repo.workdir() ?? ""
            await MainActor.run {
                self.feedbackCenter.error(
                    "Extract Selected Changes failed",
                    detail: errorMessage(error),
                    nextStep: "本操作会保存并恢复本地修改；若恢复冲突，请先处理冲突或使用保留的临时 stash。目标须在当前分支 first-parent 历史中；merge 目标及其后继 merge 会保留 parent 拓扑并按 first-parent 变更重放，无法安全重放时会拒绝改写。rename 会按旧路径和新路径成对处理，submodule gitlink 会按子模块边界同步。"
                )
                self.presentLogSelectedChangesRestoreConflict(rootPath: failedRootPath)
            }
        }
    }
}

/// A Drop/Extract rewrite can finish its history edit and still fail while
/// replaying the user's saved local scene. The engine leaves a stable
/// history-rewrite marker and the exact stash; open the same root-scoped
/// resolver used by the other preserving operations instead of leaving only
/// a generic error and a stash hint.
private func presentLogSelectedChangesRestoreConflict(rootPath: String) {
    guard !rootPath.isEmpty else { return }
    Task.detached(priority: .utility) {
        guard let rootRepo = try? openRepository(path: rootPath),
              let info = (try? rootRepo.applyLocalChangesRestoreInfo()) ?? nil,
              info.operation == "history-rewrite" else { return }
        let paths = ((try? rootRepo.status()) ?? [])
            .filter { $0.staged == .conflicted || $0.unstaged == .conflicted }
            .map(\.path)
        await MainActor.run {
            self.openMultiRootConflictResolver(
                preferredRootPath: rootPath,
                preferredPath: paths.first
            )
        }
    }
}

func checkoutFromLog(_ commit: CommitInfo) {
    guard let repo = logRepository(for: commit) else { return }
    let alert = NSAlert()
    alert.messageText = "Checkout revision?"
    alert.informativeText = "This will detach HEAD at \(commit.shortId). Uncommitted changes must be clean."
    alert.addButton(withTitle: "Checkout")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    beginFeedbackOperation("Checkout revision")
    let id = commit.id
    Task.detached(priority: .userInitiated) {
        do {
            try repo.checkoutDetached(commitId: id)
            await MainActor.run {
                self.commitFeedback = "已 checkout \(String(id.prefix(7)))"
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            let detail = errorMessage(error)
            await MainActor.run {
                self.commitFeedback = detail
                self.presentCheckoutRecovery(
                    repo: repo,
                    name: id,
                    detail: detail,
                    onSmart: { self.smartCheckoutDetached(repo: repo, revision: id) },
                    onForce: { self.forceCheckoutDetached(repo: repo, revision: id) }
                )
            }
        }
    }
}

func resetFromLog(_ commit: CommitInfo) {
    resetFromLog([commit])
}

/// IntelliJ's VCS log reset action accepts at most one selected revision per
/// Git root. Keep the selection root-qualified before presenting the mode
/// dialog, so aggregate Log cannot accidentally reset every root to the first
/// selected repository's object.
func resetFromLog(_ commits: [CommitInfo]) {
    let commits = commits.filter { logRepository(for: $0) != nil }
    guard isResetSelectionAvailable(for: commits) else {
        feedbackCenter.warning(
            "Reset unavailable",
            detail: "Select at most one revision per Git root.",
            nextStep: "Choose one commit in each repository and retry."
        )
        return
    }
    guard let first = commits.first else { return }
    resetTargetCommits = commits
    resetTargetCommit = first
    resetMode = GitResetModeSettings.mode(for: projectPath).engineValue
    showResetDialog = true
}

func resetCommit(_ commit: CommitInfo, mode: ResetMode) {
    guard let repo = logRepository(for: commit) else { return }
    GitResetModeSettings.save(GitResetModeChoice(mode), for: projectPath)
    runResetCommit(repo: repo, id: commit.id, mode: mode, preserveLocalChanges: false)
}

private func runResetCommit(
    repo: Repository,
    id: String,
    mode: ResetMode,
    preserveLocalChanges: Bool
) {
    beginFeedbackOperation("Reset branch")
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    Task.detached(priority: .userInitiated) {
        do {
            let recovery = try repo.resetWithRecovery(
                commitId: id,
                mode: mode,
                savePolicy: projectSavePolicy,
                smart: preserveLocalChanges,
                force: false
            )
            await MainActor.run {
                self.commitFeedback = "已 \(resetModeName(mode)) reset 到 \(String(id.prefix(7)))"
                let recoveryTarget = recovery.rollbackId.map {
                    PersistedResetRecoveryTarget(
                        rootPath: repo.workdir() ?? "",
                        displayName: URL(fileURLWithPath: repo.workdir() ?? "").lastPathComponent,
                        initialHead: recovery.initialHead,
                        expectedHead: recovery.finalHead,
                        expectedHeadBranch: recovery.finalBranch,
                        mode: mode,
                        rollbackID: $0
                    )
                }
                self.feedbackCenter.success(
                    "Reset completed",
                    detail: "\(resetModeName(mode)) · \(String(id.prefix(7)))",
                    additionalActions: recoveryTarget.map {
                        self.resetRecoveryActions(targets: [$0])
                    } ?? [],
                    notificationID: self.resetRecoveryNotificationID(),
                    notificationGroup: .standard
                )
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            await MainActor.run {
                self.commitFeedback = errorMessage(error)
                if case let .LocalChangesWouldBeOverwritten(paths) = error as? EngineError {
                    self.feedbackCenter.warning(
                        "Reset needs a decision",
                        detail: paths.joined(separator: ", "),
                        nextStep: "Choose Smart Reset to preserve local changes, or cancel and keep the current worktree."
                    )
                    self.presentSmartOperationDecision(
                        operationTitle: "Reset",
                        paths: paths,
                        detail: errorMessage(error),
                        smartButtonTitle: "Smart Reset",
                        forceButtonTitle: mode == .hard ? "Reset hard anyway" : nil,
                        onSmart: {
                            self.runResetCommit(
                                repo: repo,
                                id: id,
                                mode: mode,
                                preserveLocalChanges: true
                            )
                        },
                        onForce: mode == .hard ? {
                            self.forceResetCommit(repo: repo, id: id)
                        } : nil
                    )
                } else if case let .StashApplyConflict(paths, stashID) = error as? EngineError {
                    self.showStashRestoreConflict(
                        paths,
                        operationName: "Reset",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repo.workdir()
                        ).map { [$0] } ?? [],
                        stashID: stashID
                    )
                } else if case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                    self.presentShelveConflict(
                        name: name,
                        paths: paths,
                        isPop: true,
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repo.workdir()
                        ).map { [$0] } ?? []
                    )
                } else {
                    self.feedbackCenter.error(
                        "Reset failed",
                        detail: errorMessage(error),
                        nextStep: "Check the target revision and current Git state, then retry.",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repo.workdir()
                        ).map { [$0] } ?? []
                    )
                }
            }
        }
    }
}

private func forceResetCommit(repo: Repository, id: String) {
    beginFeedbackOperation("Force reset branch")
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    Task.detached(priority: .userInitiated) {
        do {
            let recovery = try repo.resetWithRecovery(
                commitId: id,
                mode: .hard,
                savePolicy: projectSavePolicy,
                smart: false,
                force: true
            )
            await MainActor.run {
                self.commitFeedback = "已 hard reset 到 \(String(id.prefix(7)))"
                let recoveryTarget = recovery.rollbackId.map {
                    PersistedResetRecoveryTarget(
                        rootPath: repo.workdir() ?? "",
                        displayName: URL(fileURLWithPath: repo.workdir() ?? "").lastPathComponent,
                        initialHead: recovery.initialHead,
                        expectedHead: recovery.finalHead,
                        expectedHeadBranch: recovery.finalBranch,
                        mode: .hard,
                        rollbackID: $0
                    )
                }
                self.feedbackCenter.success(
                    "Hard reset completed",
                    detail: String(id.prefix(7)),
                    additionalActions: recoveryTarget.map {
                        self.resetRecoveryActions(targets: [$0])
                    } ?? [],
                    notificationID: self.resetRecoveryNotificationID(),
                    notificationGroup: .standard
                )
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Hard reset failed",
                    detail: errorMessage(error),
                    nextStep: "No local changes were restored; inspect the current Git state before retrying."
                )
            }
        }
    }
}

/// Reset the same revision across all discovered Git roots. The first pass is
/// deliberately direct so the engine can return every affected path; only the
/// explicit Smart/Force choice retries the roots that were actually blocked.
func resetCommitsAcrossRoots(_ commit: CommitInfo, mode: ResetMode) {
    guard let projectPath, multiRoots.count > 1 else { return }
    GitResetModeSettings.save(GitResetModeChoice(mode), for: projectPath)
    let selectedRootPaths = multiRoots.map(\.path)
    runMultiRootResetOperation(
        projectPath: projectPath,
        selectedRootPaths: selectedRootPaths,
        commitID: commit.id,
        mode: mode,
        smart: false,
        force: false
    )
}

/// Reset the Log selection with one target revision per owning Git root.
func resetCommitsAcrossRoots(_ commits: [CommitInfo], mode: ResetMode) {
    guard let projectPath, isResetSelectionAvailable(for: commits) else { return }
    GitResetModeSettings.save(GitResetModeChoice(mode), for: projectPath)
    let targets = commits.compactMap { commit -> MultiRootResetTarget? in
        guard let repository = logRepository(for: commit),
              let rootPath = repository.workdir() else { return nil }
        return MultiRootResetTarget(rootPath: rootPath, commitId: commit.id)
    }
    guard targets.count == commits.count else {
        feedbackCenter.error(
            "Reset unavailable",
            detail: "One or more selected revisions no longer belongs to an available Git root.",
            nextStep: "Refresh the Log and select the revisions again."
        )
        return
    }
    runMultiRootResetOperation(
        projectPath: projectPath,
        selectedRootPaths: targets.map(\.rootPath),
        targetSpecs: targets,
        mode: mode,
        smart: false,
        force: false
    )
}

private func runMultiRootResetOperation(
    projectPath: String,
    selectedRootPaths: [String],
    commitID: String? = nil,
    targetSpecs: [MultiRootResetTarget]? = nil,
    mode: ResetMode,
    smart: Bool,
    force: Bool,
    rootOrder: [String]? = nil,
    preservedResults: [RootOperationResult] = []
) {
    let operationRootPaths = selectedRootPaths
    let resultRootOrder = rootOrder ?? (
        operationRootPaths + preservedResults
            .map(\.rootPath)
            .filter { !operationRootPaths.contains($0) }
    )
    multiRootRunning = true
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Multi-root reset")
    Task.detached(priority: .userInitiated) {
        do {
            let results: [MultiRootResetResult]
            if let targetSpecs {
                results = try runMultiRootResetWithTargets(
                    scanRoot: projectPath,
                    targets: targetSpecs,
                    mode: mode,
                    savePolicy: projectSavePolicy,
                    smart: smart,
                    force: force
                )
            } else if let commitID {
                results = try runMultiRootResetWithPolicy(
                    scanRoot: projectPath,
                    selectedRootPaths: operationRootPaths,
                    commitId: commitID,
                    mode: mode,
                    savePolicy: projectSavePolicy,
                    smart: smart,
                    force: force
                )
            } else {
                throw NSError(
                    domain: "Arbor.Reset",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "Reset target is missing"]
                )
            }
            let operationResults = results.map { result in
                RootOperationResult(
                    rootPath: result.rootPath,
                    displayName: result.displayName,
                    success: result.success,
                    skipped: result.skipped,
                    message: result.message
                )
            }
            let combinedOperationResults = mergeRootOperationResults(
                preserved: preservedResults,
                retry: operationResults,
                rootOrder: resultRootOrder
            )
            let overwriteFailures = results.filter {
                !$0.success && !$0.skipped && !$0.localChangesOverwritePaths.isEmpty
            }
            let failures = combinedOperationResults.filter { !$0.success || $0.skipped }
            let resetRecoveryTargets: [PersistedResetRecoveryTarget] = results.compactMap { result in
                guard result.success,
                      !result.skipped,
                      let initialHead = result.initialHead,
                      let expectedHead = result.finalHead,
                      let rollbackID = result.rollbackId else { return nil }
                return PersistedResetRecoveryTarget(
                    rootPath: result.rootPath,
                    displayName: result.displayName,
                    initialHead: initialHead,
                    expectedHead: expectedHead,
                    expectedHeadBranch: result.finalBranch,
                    mode: mode,
                    rollbackID: rollbackID
                )
            }
            await MainActor.run {
                self.multiRootRunning = false
                self.multiRootResults = combinedOperationResults
                self.loadMultiRoots()
                if !overwriteFailures.isEmpty && !smart && !force {
                    let detail = overwriteFailures.map {
                        "\($0.displayName): \($0.localChangesOverwritePaths.joined(separator: ", "))"
                    }.joined(separator: "\n")
                    self.feedbackCenter.warning(
                        "Multi-root Reset needs a decision",
                        detail: detail,
                        nextStep: "Choose Smart Reset to preserve local changes in blocked roots, or cancel."
                    )
                    self.presentSmartOperationDecision(
                        operationTitle: "Multi-root Reset",
                        paths: overwriteFailures.flatMap { result in
                            result.localChangesOverwritePaths.map { "\(result.displayName): \($0)" }
                        },
                        detail: detail,
                        smartButtonTitle: "Smart Reset",
                        forceButtonTitle: mode == .hard ? "Force Reset" : nil,
                        onSmart: {
                            self.runMultiRootResetOperation(
                                projectPath: projectPath,
                                selectedRootPaths: overwriteFailures.map(\.rootPath),
                                commitID: commitID,
                                targetSpecs: targetSpecs?.filter { target in
                                    overwriteFailures.contains(where: { $0.rootPath == target.rootPath })
                                },
                                mode: mode,
                                smart: true,
                                force: false,
                                rootOrder: resultRootOrder,
                                preservedResults: combinedOperationResults.filter { result in
                                    !overwriteFailures.contains(where: { $0.rootPath == result.rootPath })
                                }
                            )
                        },
                        onForce: mode == .hard ? {
                            self.runMultiRootResetOperation(
                                projectPath: projectPath,
                                selectedRootPaths: overwriteFailures.map(\.rootPath),
                                commitID: commitID,
                                targetSpecs: targetSpecs?.filter { target in
                                    overwriteFailures.contains(where: { $0.rootPath == target.rootPath })
                                },
                                mode: mode,
                                smart: false,
                                force: true,
                                rootOrder: resultRootOrder,
                                preservedResults: combinedOperationResults.filter { result in
                                    !overwriteFailures.contains(where: { $0.rootPath == result.rootPath })
                                }
                            )
                        } : nil
                    )
                } else if failures.isEmpty {
                    let targetDetail = targetSpecs == nil
                        ? "target \(String((commitID ?? "").prefix(7)))"
                        : "one target per repository"
                    self.feedbackCenter.success(
                        "Multi-root Reset completed",
                        detail: "\(results.count) repositories · \(self.resetModeName(mode)) · \(targetDetail)",
                        additionalActions: self.resetRecoveryActions(
                            targets: resetRecoveryTargets
                        ),
                        notificationID: self.multiRootResetNotificationID(),
                        notificationGroup: .standard
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Multi-root Reset partially completed",
                        detail: failures.map {
                            "\($0.displayName): \($0.message.isEmpty ? ($0.skipped ? "skipped" : "failed") : $0.message)"
                        }.joined(separator: "\n"),
                        nextStep: "Review the affected Git roots and resolve any saved local-change restore marker.",
                        actionTitle: "Resolve Conflicts",
                        action: {
                            self.openMultiRootConflictResolver(preferredRootPath: failures.first?.rootPath)
                        },
                        additionalActions: self.resetRecoveryActions(
                            targets: resetRecoveryTargets
                        ),
                        notificationID: self.multiRootResetNotificationID(),
                        notificationGroup: .standard
                    )
                }
            }
        } catch {
            await MainActor.run {
                self.multiRootRunning = false
                self.feedbackCenter.error(
                    "Multi-root Reset failed",
                    detail: errorMessage(error),
                    nextStep: "Check the selected Git roots and target revision, then retry."
                )
            }
        }
    }
}

private func multiRootResetRollbackRequest(
    targets: [PersistedMultiRootResetRollbackTarget]
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .rollbackMultiRootReset,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        multiRootResetRollbackTargets: targets
    )
}

private func multiRootResetRollbackAction(
    targets: [PersistedMultiRootResetRollbackTarget]
) -> FeedbackAction? {
    guard !targets.isEmpty else { return nil }
    let request = multiRootResetRollbackRequest(targets: targets)
    return FeedbackAction(title: "Rollback Soft Reset", semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

private func multiRootResetNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.multi-root-reset.\(stableProject)"
}

private func resetRecoveryNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.reset-recovery.\(stableProject)"
}

private func resetRecoveryRollbackRequest(
    targets: [PersistedResetRecoveryTarget]
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .rollbackResetRecovery,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        resetRecoveryTargets: targets
    )
}

private func resetRecoveryRollbackAction(
    targets: [PersistedResetRecoveryTarget]
) -> FeedbackAction? {
    guard !targets.isEmpty else { return nil }
    let request = resetRecoveryRollbackRequest(targets: targets)
    return FeedbackAction(
        title: targets.count == 1 ? "Undo Reset" : "Rollback Successful Resets",
        semanticAction: request
    ) {
        self.handleVCSActionRequest(request)
    }
}

private func resetRecoveryKeepRequest(
    targets: [PersistedResetRecoveryTarget]
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .keepResetRecovery,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        resetRecoveryTargets: targets
    )
}

private func resetRecoveryKeepAction(
    targets: [PersistedResetRecoveryTarget]
) -> FeedbackAction? {
    guard !targets.isEmpty else { return nil }
    let request = resetRecoveryKeepRequest(targets: targets)
    return FeedbackAction(
        title: targets.count == 1 ? "Keep Reset Result" : "Keep Successful Resets",
        semanticAction: request
    ) {
        self.handleVCSActionRequest(request)
    }
}

private func resetRecoveryActions(
    targets: [PersistedResetRecoveryTarget]
) -> [FeedbackAction] {
    [
        resetRecoveryRollbackAction(targets: targets),
        resetRecoveryKeepAction(targets: targets)
    ].compactMap { $0 }
}

/// Full-scene reset undo. Rust validates every target's post-reset index and
/// worktree snapshot before changing anything; failed roots remain as a
/// persisted retry action while successful roots are removed from the action.
private func rollbackResetRecovery(
    _ targets: [PersistedResetRecoveryTarget]
) {
    guard !targets.isEmpty else { return }
    beginFeedbackOperation("Rollback reset")
    Task.detached(priority: .userInitiated) {
        do {
            let results = try rollbackMultiRootResetRecovery(
                targets: targets.map { $0.makeLiveTarget() }
            )
            await MainActor.run {
                self.multiRootResults = results
                self.loadMultiRoots()
                self.refreshAll(showFeedback: false)
                let failures = results.filter { !$0.success }
                guard !failures.isEmpty else {
                    self.feedbackCenter.success(
                        "Reset rollback completed",
                        detail: "Restored \(results.count) root\(results.count == 1 ? "" : "s") including local changes.",
                        notificationID: self.resetRecoveryNotificationID(),
                        notificationGroup: .standard
                    )
                    return
                }
                let failedPaths = Set(failures.map(\.rootPath))
                let remainingTargets = targets.filter { failedPaths.contains($0.rootPath) }
                let retryRequest = self.resetRecoveryRollbackRequest(targets: remainingTargets)
                self.feedbackCenter.warning(
                    "Reset rollback partially failed",
                    detail: failures.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n"),
                    nextStep: "The failed roots were left untouched. Retry after confirming their HEAD and local scene.",
                    additionalActions: remainingTargets.isEmpty
                        ? []
                        : [FeedbackAction(
                            title: "Retry Remaining Reset Rollback",
                            semanticAction: retryRequest
                        ) {
                            self.handleVCSActionRequest(retryRequest)
                        },
                        self.resetRecoveryKeepAction(targets: remainingTargets)].compactMap { $0 },
                    notificationID: self.resetRecoveryNotificationID(),
                    notificationGroup: .standard
                )
            }
        } catch {
            await MainActor.run {
                let retryRequest = self.resetRecoveryRollbackRequest(targets: targets)
                self.feedbackCenter.warning(
                    "Reset rollback failed",
                    detail: errorMessage(error),
                    nextStep: "No root was assumed restored. Confirm the repository state and retry.",
                    additionalActions: [
                        FeedbackAction(
                            title: "Retry Reset Rollback",
                            semanticAction: retryRequest
                        ) {
                            self.handleVCSActionRequest(retryRequest)
                        },
                        self.resetRecoveryKeepAction(targets: targets)
                    ].compactMap { $0 },
                    notificationID: self.resetRecoveryNotificationID(),
                    notificationGroup: .standard
                )
            }
        }
    }
}

/// Keep the reset result after verifying that every selected root still has
/// the exact post-reset scene. Failed roots remain as retryable semantic
/// targets; successful roots release their repository-owned snapshots.
private func keepResetRecovery(
    _ targets: [PersistedResetRecoveryTarget]
) {
    guard !targets.isEmpty else { return }
    beginFeedbackOperation("Keep reset result")
    Task.detached(priority: .userInitiated) {
        do {
            let results = try keepMultiRootResetRecovery(
                targets: targets.map { $0.makeLiveTarget() }
            )
            await MainActor.run {
                self.multiRootResults = results
                self.loadMultiRoots()
                self.refreshAll(showFeedback: false)
                let failures = results.filter { !$0.success }
                guard !failures.isEmpty else {
                    self.feedbackCenter.success(
                        "Reset result kept",
                        detail: "Released recovery snapshots for \(results.count) root\(results.count == 1 ? "" : "s").",
                        notificationID: self.resetRecoveryNotificationID(),
                        notificationGroup: .standard
                    )
                    return
                }
                let failedPaths = Set(failures.map(\.rootPath))
                let remainingTargets = targets.filter { failedPaths.contains($0.rootPath) }
                let retryRequest = self.resetRecoveryKeepRequest(targets: remainingTargets)
                self.feedbackCenter.warning(
                    "Reset result partially kept",
                    detail: failures.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n"),
                    nextStep: "The failed roots remain protected. Retry Keep after confirming their HEAD and local scene.",
                    additionalActions: remainingTargets.isEmpty
                        ? []
                        : [FeedbackAction(
                            title: "Retry Remaining Keep",
                            semanticAction: retryRequest
                        ) {
                            self.handleVCSActionRequest(retryRequest)
                        },
                        self.resetRecoveryRollbackAction(targets: remainingTargets)].compactMap { $0 },
                    notificationID: self.resetRecoveryNotificationID(),
                    notificationGroup: .standard
                )
            }
        } catch {
            await MainActor.run {
                let retryRequest = self.resetRecoveryKeepRequest(targets: targets)
                self.feedbackCenter.warning(
                    "Keep Reset result failed",
                    detail: errorMessage(error),
                    nextStep: "Confirm the repository state, then retry Keep or Undo.",
                    additionalActions: [
                        FeedbackAction(
                            title: "Retry Keep Reset Result",
                            semanticAction: retryRequest
                        ) {
                            self.handleVCSActionRequest(retryRequest)
                        },
                        self.resetRecoveryRollbackAction(targets: targets)
                    ].compactMap { $0 },
                    notificationID: self.resetRecoveryNotificationID(),
                    notificationGroup: .standard
                )
            }
        }
    }
}

/// Roll back only soft-reset roots whose expected HEAD and branch still match.
/// The engine operation is ref-only, so user edits made after the reset remain
/// untouched. Failed roots stay as retryable semantic targets.
private func rollbackMultiRootReset(
    _ targets: [PersistedMultiRootResetRollbackTarget]
) {
    guard !targets.isEmpty else { return }
    beginFeedbackOperation("Rollback multi-root soft reset")
    Task.detached(priority: .userInitiated) {
        do {
            let results = try Arbor.rollbackMultiRootReset(
                targets: targets.map { $0.makeLiveTarget() }
            )
            await MainActor.run {
                self.multiRootResults = results
                self.loadMultiRoots()
                let failures = results.filter { !$0.success }
                guard !failures.isEmpty else {
                    self.feedbackCenter.success(
                        "Soft reset rollback completed",
                        detail: "Restored \(results.count) root\(results.count == 1 ? "" : "s").",
                        notificationID: self.multiRootResetNotificationID(),
                        notificationGroup: .standard
                    )
                    return
                }
                let failedPaths = Set(failures.map(\.rootPath))
                let remainingTargets = targets.filter { failedPaths.contains($0.rootPath) }
                let retryRequest = self.multiRootResetRollbackRequest(targets: remainingTargets)
                self.feedbackCenter.warning(
                    "Soft reset rollback partially failed",
                    detail: failures.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n"),
                    nextStep: "Review the changed roots and retry only the remaining rollback targets.",
                    additionalActions: remainingTargets.isEmpty
                        ? []
                        : [FeedbackAction(
                            title: "Retry Remaining Rollback",
                            semanticAction: retryRequest
                        ) {
                            self.handleVCSActionRequest(retryRequest)
                        }],
                    notificationID: self.multiRootResetNotificationID(),
                    notificationGroup: .standard
                )
            }
        } catch {
            await MainActor.run {
                let retryRequest = self.multiRootResetRollbackRequest(targets: targets)
                self.feedbackCenter.warning(
                    "Soft reset rollback failed",
                    detail: errorMessage(error),
                    nextStep: "Confirm the roots still have the expected HEAD, then retry the rollback action.",
                    additionalActions: [
                        FeedbackAction(
                            title: "Retry Soft Reset Rollback",
                            semanticAction: retryRequest
                        ) {
                            self.handleVCSActionRequest(retryRequest)
                        }
                    ],
                    notificationID: self.multiRootResetNotificationID(),
                    notificationGroup: .standard
                )
            }
        }
    }
}

func resetModeName(_ mode: ResetMode) -> String {
    switch mode {
    case .soft: return "soft"
    case .mixed: return "mixed"
    case .hard: return "hard"
    case .keep: return "keep"
    }
}

func restoreSelectedFile() {
    // The Commit workspace keeps its selected row in `commitPreviewPath` so the
    // main Log selection can remain independent.  Fall back to the older
    // selection channels for Project/Conflict workspaces.
    guard let path = commitPreviewPath ?? selection ?? fileSelection else { return }
    restoreFileFromHead(path)
}

/// Restore is a tree action in GitStagePanel, not a global toolbar action.
/// Keep the selected-file wrapper for keyboard/legacy callers, but let the
/// tree context menu pass its path directly so a context-menu click cannot
/// race the asynchronous row-selection state update.
func restoreFileFromHead(
    _ path: String,
    prompt: String = "Restore file from HEAD?",
    confirmTitle: String = "Restore",
    feedbackTitle: String = "File restored"
) {
    guard let repo else { return }
    let alert = NSAlert()
    alert.messageText = prompt
    alert.informativeText = "This restores \(path) in both the index and working tree."
    alert.alertStyle = .warning
    alert.addButton(withTitle: confirmTitle)
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    beginFeedbackOperation("Restore file")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.restoreFile(path: path, revision: nil)
            await MainActor.run {
                self.feedbackCenter.success(feedbackTitle, detail: path)
                self.selection = nil
                self.commitPreviewPath = nil
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Restore file failed", detail: errorMessage(error), nextStep: "Check the selected path and retry.")
            }
        }
    }
}

/// Project-tree Revert is the same tracked-file operation as ChangesView's
/// Revert, but resolves nested Git roots before touching the index/worktree.
func restoreProjectTreePath(_ path: String) {
    guard let normalizedPath = normalizedRepositoryRelativePath(path),
          let primaryRepo = repo,
          let primaryRootPath = primaryRepo.workdir(),
          !primaryRootPath.isEmpty else { return }
    let alert = NSAlert()
    alert.messageText = "Revert file?"
    alert.informativeText = "This restores \(normalizedPath) in both the index and working tree."
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Revert")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    let cachedRoots = multiRoots
    beginFeedbackOperation("Revert file")
    Task.detached(priority: .userInitiated) {
        do {
            let roots = cachedRoots.isEmpty
                ? ((try? discoverGitRoots(scanRoot: primaryRootPath, maxDepth: nil)) ?? [])
                : cachedRoots
            guard let target = fileReferenceComparisonTarget(
                path: normalizedPath,
                primaryRootPath: primaryRootPath,
                roots: roots
            ) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "The selected path is outside the discovered Git roots."]
                )
            }
            let targetRepo = canonicalExternalLogPath(primaryRootPath) == target.rootPath
                ? primaryRepo
                : try openRepository(path: target.rootPath)
            let currentStatus = try targetRepo.statusPaths(paths: [target.relativePath])
            guard projectFileTreeCanRevert(
                path: target.relativePath,
                isDirectory: false,
                entries: currentStatus
            ) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 2,
                    userInfo: [NSLocalizedDescriptionKey: "The file is no longer a tracked, non-conflicted change."]
                )
            }
            try targetRepo.restoreFile(path: target.relativePath, revision: nil)
            await MainActor.run {
                self.refreshAll(showFeedback: false)
                self.loadMultiRootChanges()
                self.feedbackCenter.success("File reverted", detail: normalizedPath)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Revert failed",
                    detail: errorMessage(error),
                    nextStep: "Check that the file is a tracked, non-conflicted change, then retry."
                )
            }
        }
    }
}

func compareFromLog(_ commit: CommitInfo) {
    guard let selectedRepo = logRepository(for: commit) else {
        feedbackCenter.warning(
            "Compare unavailable",
            detail: "The selected commit's Git root could not be opened.",
            nextStep: "Refresh Git roots and retry from the commit history."
        )
        return
    }
    let selectedRootPath = commit.repositoryPath ?? selectedRepo.workdir()
    guard let selectedRootPath else {
        feedbackCenter.warning(
            "Compare unavailable",
            detail: "The selected commit's Git root could not be resolved.",
            nextStep: "Refresh Git roots and retry from the commit history."
        )
        return
    }
    // GitLogDiffHandler.showDiffWithLocal compares the selected revision with
    // the current worktree. Keep that direction explicit and use the same
    // independent Changes Browser tab as the branch comparison actions.
    openTreeComparisonTab(
        rootPath: selectedRootPath,
        first: commit.id,
        second: "Working Tree",
        comparesWithWorkingTree: true
    )
}

/// Open the Uncommit chooser against the repository that owns the selected
/// Log commit. This matters in aggregate/multi-root Log: the visible HEAD may
/// belong to a nested repository rather than the primary Commit workspace.
func uncommitFromLog(_ selectedCommit: CommitInfo) {
    guard isUncommitActionAvailable(for: selectedCommit) else {
        feedbackCenter.warning(
            "Undo commit unavailable",
            detail: "Only the current HEAD commit with a parent can be undone.",
            nextStep: "Select the latest commit in the owning Git root."
        )
        return
    }
    guard let selectedRepo = logRepository(for: selectedCommit) else {
        feedbackCenter.error(
            "Undo commit unavailable",
            detail: "The Git root for the selected commit is no longer available.",
            nextStep: "Refresh Git roots and retry."
        )
        return
    }
    let protectedPatterns = effectiveProtectedBranchPatterns
    Task.detached(priority: .userInitiated) {
        do {
            guard let repositoryPath = selectedRepo.workdir() else {
                throw EngineError.GitOperation(message: "Undo commit requires a worktree repository.")
            }
            guard selectedRepo.headCommitId() == selectedCommit.id else {
                throw EngineError.GitOperation(
                    message: "The selected commit is no longer HEAD in its Git root."
                )
            }
            guard let head = try selectedRepo.log(path: nil, limit: 1, follow: false, afterId: nil).first,
                  let parentID = head.parentIds.first else {
                throw EngineError.GitOperation(message: "Undo commit requires a HEAD commit with a parent.")
            }
            let remoteBranches = try selectedRepo.remoteBranchList()
            if let protectedBranch = protectedRemoteBranchContainingCommit(
                repo: selectedRepo,
                commitID: head.id,
                remoteBranches: remoteBranches,
                protectedPatterns: protectedPatterns
            ) {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Undo commit blocked",
                        detail: "The selected commit is published to protected branch \(protectedBranch).",
                        nextStep: "Fetch or select an unpublished commit before rewriting history."
                    )
                }
                return
            }
            let changes = try selectedRepo.treeChanges(rev1: parentID, rev2: head.id)
            let changedPaths = uncommitChangedPaths(changes)
            let rootChangeLists = try selectedRepo.changelistList()
            let headBranch = (try? selectedRepo.branchList())?.first(where: { $0.isCurrent })?.name
            await MainActor.run {
                self.uncommitRequest = RebasedUncommitRequest(
                    commit: head,
                    repositoryPath: repositoryPath,
                    changedPaths: changedPaths,
                    changeLists: rootChangeLists,
                    headBranch: headBranch
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Undo commit unavailable",
                    detail: errorMessage(error),
                    nextStep: "Select a non-root HEAD commit."
                )
            }
        }
    }
}

func performUncommit(_ request: RebasedUncommitRequest, targetName: String) {
    let restoredCommitMessage = request.commit.messageBody.isEmpty
        ? request.commit.summary
        : "\(request.commit.summary)\n\n\(request.commit.messageBody)"
    beginFeedbackOperation("Undo commit")
    Task.detached(priority: .userInitiated) {
        var didUncommit = false
        do {
            let targetRepo = try openRepository(path: request.repositoryPath)
            guard targetRepo.headCommitId() == request.commit.id else {
                throw EngineError.GitOperation(
                    message: "The selected commit is no longer HEAD in its Git root."
                )
            }
            let normalizedTargetName = targetName.trimmingCharacters(in: .whitespacesAndNewlines)
            if !normalizedTargetName.isEmpty {
                // Create/lookup the target before the destructive soft reset.
                try targetRepo.changelistEnsure(name: normalizedTargetName)
            }
            try targetRepo.uncommitExpectedHead(expectedHead: request.commit.id)
            didUncommit = true
            let statusPaths = Set(try targetRepo.status().map(\.path))
            let assignablePaths = request.changedPaths.filter(statusPaths.contains)
            if !normalizedTargetName.isEmpty, !assignablePaths.isEmpty {
                try targetRepo.changelistMovePaths(paths: assignablePaths, targetName: normalizedTargetName)
            }
            let lists = try targetRepo.changelistList()
            await MainActor.run {
                // IntelliJ restores the undone commit's full message into the
                // Changes workflow so the user can recommit without copying it.
                self.commitMessage = restoredCommitMessage
                self.commitFeedback = "已撤销最近一次提交，变更仍保留在暂存区"
                if self.repo?.workdir() == request.repositoryPath {
                    self.changeLists = lists
                    self.refreshAll(showFeedback: false)
                } else {
                    self.loadMultiRoots {
                        if self.logViewMode == .command || self.isLogAggregate {
                            self.reloadLogView()
                        }
                    }
                }
                let undoAction = self.uncommitUndoFeedbackAction(for: request)
                self.feedbackCenter.success(
                    "Latest commit undone",
                    detail: normalizedTargetName.isEmpty
                        ? "Changes remain staged"
                        : "Changes moved to \(normalizedTargetName)",
                    additionalActions: undoAction.map { [$0] } ?? [],
                    notificationID: self.uncommitUndoNotificationID(
                        rootPath: request.repositoryPath
                    )
                )
            }
        } catch {
            let uncommitDidComplete = didUncommit
            await MainActor.run {
                self.feedbackCenter.error(
                    "Undo commit failed",
                    detail: errorMessage(error),
                    nextStep: uncommitDidComplete
                        ? "Uncommit 已完成，但后续 Changelist 同步失败；先恢复或重新检查当前状态。"
                        : "确认当前提交存在父提交且工作区状态允许 soft reset。",
                    additionalActions: uncommitDidComplete
                        ? (self.uncommitUndoFeedbackAction(for: request).map { [$0] } ?? [])
                        : [],
                    notificationID: uncommitDidComplete
                        ? self.uncommitUndoNotificationID(rootPath: request.repositoryPath)
                        : nil
                )
            }
        }
    }
}

private func uncommitUndoNotificationID(rootPath: String) -> String {
    let normalized = URL(fileURLWithPath: rootPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.uncommit-undo.\(normalized)"
}

private func uncommitUndoRequest(
    for request: RebasedUncommitRequest
) -> ArborVCSActionRequest? {
    guard let expectedHead = request.commit.parentIds.first else { return nil }
    return ArborVCSActionRequest(
        kind: .undoUncommit,
        projectPath: projectPath,
        rootPath: request.repositoryPath,
        shelfName: "",
        uncommitCommitID: request.commit.id,
        uncommitExpectedHead: expectedHead,
        uncommitExpectedBranch: request.headBranch ?? ""
    )
}

private func uncommitUndoFeedbackAction(
    for request: RebasedUncommitRequest
) -> FeedbackAction? {
    guard let semanticRequest = uncommitUndoRequest(for: request) else { return nil }
    return FeedbackAction(
        id: "undo-uncommit:\(semanticRequest.rootPath ?? ""):\(semanticRequest.uncommitCommitID ?? "")",
        title: "Undo Uncommit",
        semanticAction: semanticRequest
    ) {
        handleVCSActionRequest(semanticRequest)
    }
}

/// Restore the exact commit that was just soft-uncommitted. The engine only
/// moves the ref and checks both the expected parent and branch identity, so
/// local edits made after the Uncommit are never rewritten.
private func undoUncommit(
    rootPath: String,
    originalCommitID: String,
    expectedHead: String,
    expectedBranch: String
) {
    beginFeedbackOperation("Undo Uncommit")
    Task.detached(priority: .userInitiated) {
        do {
            let targetRepo = try openRepository(path: rootPath)
            try targetRepo.undoUncommitExpectedHead(
                originalCommitId: originalCommitID,
                expectedHead: expectedHead,
                expectedBranch: expectedBranch
            )
            await MainActor.run {
                self.feedbackCenter.expire(
                    notificationID: self.uncommitUndoNotificationID(rootPath: rootPath)
                )
                let isCurrentRoot = self.repo?.workdir().map {
                    URL(fileURLWithPath: $0).standardizedFileURL.path
                        == URL(fileURLWithPath: rootPath).standardizedFileURL.path
                } == true
                if isCurrentRoot {
                    self.refreshAll(showFeedback: false)
                } else {
                    self.loadMultiRoots {
                        if self.logViewMode == .command || self.isLogAggregate {
                            self.reloadLogView()
                        }
                    }
                }
                self.feedbackCenter.success(
                    "Uncommit undone",
                    detail: "HEAD restored to \(String(originalCommitID.prefix(8)))."
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Undo Uncommit failed",
                    detail: errorMessage(error),
                    nextStep: "The repository changed after Uncommit; review the current branch and retry only if the original HEAD is still intended."
                )
            }
        }
    }
}

/// Undo a successful reword by restoring only the original HEAD ref. The
/// expected HEAD and branch make the operation compare-and-swap safe, while
/// the protected-remote check mirrors IntelliJ's refusal to rewrite published
/// history. No index or worktree materialization is performed.
private func undoRewordCommit(
    rootPath: String,
    context: PersistedRewordUndo
) {
    let notificationID = rewordUndoNotificationID(
        rootPath: rootPath,
        expectedHeadID: context.expectedHeadID
    )
    let protectedPatterns = effectiveProtectedBranchPatterns
    beginFeedbackOperation("Undo Reword Commit", notificationID: notificationID)
    Task.detached(priority: .userInitiated) {
        do {
            let targetRepo = try openRepository(path: rootPath)
            guard try targetRepo.operationState() == nil else {
                throw EngineError.GitOperation(
                    message: "Undo Reword Commit is unavailable while another Git operation is active."
                )
            }
            guard targetRepo.headCommitId() == context.expectedHeadID else {
                throw EngineError.GitOperation(
                    message: "Undo Reword Commit refused: HEAD changed after reword."
                )
            }
            let currentBranch = try targetRepo.branchList()
                .first(where: { $0.isCurrent })?.name ?? ""
            guard currentBranch == context.expectedBranch else {
                throw EngineError.GitOperation(
                    message: "Undo Reword Commit refused: the current branch changed after reword."
                )
            }
            let remoteBranches = try targetRepo.remoteBranchList()
            if let protectedBranch = protectedRemoteBranchContainingCommit(
                repo: targetRepo,
                commitID: context.initialHeadID,
                remoteBranches: remoteBranches,
                protectedPatterns: protectedPatterns
            ) {
                throw EngineError.GitOperation(
                    message: "Undo Reword Commit blocked: \(protectedBranch) contains the published commit."
                )
            }
            try targetRepo.restoreHeadRefIfExpected(
                initialCommitId: context.initialHeadID,
                expectedCommitId: context.expectedHeadID,
                expectedHeadBranch: context.expectedBranch
            )
            await MainActor.run {
                self.feedbackCenter.expire(notificationID: notificationID)
                let isCurrentRoot = self.repo?.workdir().map {
                    URL(fileURLWithPath: $0).standardizedFileURL.path
                        == URL(fileURLWithPath: rootPath).standardizedFileURL.path
                } == true
                if isCurrentRoot {
                    self.refreshAll(showFeedback: false)
                } else {
                    self.loadMultiRoots {
                        if self.logViewMode == .command || self.isLogAggregate {
                            self.reloadLogView()
                        }
                    }
                }
                self.feedbackCenter.success(
                    "Reword undone",
                    detail: "HEAD restored to \(String(context.initialHeadID.prefix(8)))."
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Undo Reword Commit failed",
                    detail: errorMessage(error),
                    nextStep: "The repository may have changed after reword; review the current HEAD and branch before retrying.",
                    notificationID: notificationID
                )
            }
        }
    }
}

func stagePath(_ p: String) {
    guard let repo else { return }
    beginFeedbackOperation("Stage file")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.stage(path: p)
            let st = try repo.statusPaths(paths: [p]); let hid = repo.headCommitId()
            let staging = try? repo.stagingModel()
            await MainActor.run {
                self.applyIncrementalStatus(st, paths: [p]); self.headId = hid
                self.stagingModel = staging
                self.lastIndexRevision = staging?.indexRevision
                self.feedbackCenter.success("Changes staged")
            }
        } catch { await MainActor.run { self.loadError = errorMessage(error) } }
    }
}

/// Project-tree Git.Add must resolve the owning root at invocation time. The
/// tree is rendered from the primary worktree, but nested repositories may
/// appear in it and must never be staged through the parent repository.
func stageProjectTreePath(_ path: String) {
    guard let normalizedPath = normalizedRepositoryRelativePath(path),
          let primaryRepo = repo,
          let primaryRootPath = primaryRepo.workdir(),
          !primaryRootPath.isEmpty else { return }
    let cachedRoots = multiRoots
    beginFeedbackOperation("Add file")
    Task.detached(priority: .userInitiated) {
        do {
            let roots = cachedRoots.isEmpty
                ? ((try? discoverGitRoots(scanRoot: primaryRootPath, maxDepth: nil)) ?? [])
                : cachedRoots
            guard let target = fileReferenceComparisonTarget(
                path: normalizedPath,
                primaryRootPath: primaryRootPath,
                roots: roots
            ) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "The selected path is outside the discovered Git roots."]
                )
            }
            let targetRepo = canonicalExternalLogPath(primaryRootPath) == target.rootPath
                ? primaryRepo
                : try openRepository(path: target.rootPath)
            let currentStatus = try targetRepo.statusPaths(paths: [target.relativePath])
            guard projectFileTreeCanAdd(
                path: target.relativePath,
                isDirectory: false,
                entries: currentStatus
            ) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 2,
                    userInfo: [NSLocalizedDescriptionKey: "The file is no longer an untracked, non-conflicted path."]
                )
            }
            try targetRepo.stage(path: target.relativePath)
            await MainActor.run {
                self.refreshAll(showFeedback: false)
                self.loadMultiRootChanges()
                self.feedbackCenter.success("Added to Git", detail: normalizedPath)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Add failed",
                    detail: errorMessage(error),
                    nextStep: "Refresh the project tree and retry."
                )
            }
        }
    }
}

/// Git.FileActions > Checkin Files is scoped to the selected worktree file.
/// Keep the selection in the Commit workspace instead of silently opening the
/// first changed row in the repository.
func beginFileCheckin(_ path: String) {
    guard let normalizedPath = normalizedRepositoryRelativePath(path) else { return }
    toolWindowMode = .commit
    toolWindowExpanded = true
    projectPanelExpanded = false
    isShelfWorkspaceTabActive = false
    commitPreviewPath = normalizedPath
    commitPreviewMode = .unstaged
    commitPreviewComparisonMode = nil
    commitPreviewThreeVersions = false
    commitPreviewVisible = true
    selection = nil
    fileSelection = nil
    selectionModePath = nil
}

/// Git.Add from the main menu and the project-tree context menu share the same
/// invocation-time root and status validation. This keeps a stale menu state
/// from staging a newly modified tracked file.
func stageSelectedFileFromFileAction(_ file: ArborSelectedGitFileContext) {
    guard !file.isDirectory else { return }
    stageProjectTreePath(file.path)
}

func stageWithoutContent(_ p: String) {
    guard let repo else { return }
    beginFeedbackOperation("Stage without content")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.stageWithoutContent(path: p)
            let st = try repo.statusPaths(paths: [p])
            let staging = try? repo.stagingModel()
            await MainActor.run {
                self.applyIncrementalStatus(st, paths: [p])
                self.stagingModel = staging
                self.lastIndexRevision = staging?.indexRevision
                self.feedbackCenter.success("Intent-to-add staged", detail: p)
            }
        } catch {
            await MainActor.run {
                self.loadError = errorMessage(error)
                self.feedbackCenter.error(
                    "Intent-to-add failed",
                    detail: errorMessage(error),
                    nextStep: "选择一个未跟踪文件后重试。"
                )
            }
        }
    }
}

/// Batch Git.Stage.Add.No.Content action for the untracked section. The
/// engine sends one `git add -N -- <paths>` command so the index update has
/// the same all-or-nothing command boundary as IntelliJ's batch action.
func stageWithoutContentAll() {
    guard let repo else { return }
    let paths = untrackedEntries.map(\.path)
    guard !paths.isEmpty else { return }
    beginFeedbackOperation("Stage untracked without content")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.stageWithoutContentPaths(paths: paths)
            let status = try repo.status()
            let staging = try? repo.stagingModel()
            await MainActor.run {
                self.entries = status
                self.stagingModel = staging
                self.lastIndexRevision = staging?.indexRevision
                self.fileContentRefreshToken &+= 1
                self.feedbackCenter.success("Intent-to-add staged", detail: "\(paths.count) untracked files")
            }
        } catch {
            await MainActor.run {
                self.loadError = errorMessage(error)
                self.feedbackCenter.error(
                    "Intent-to-add failed",
                    detail: errorMessage(error),
                    nextStep: "选择未跟踪文件后重试。"
                )
            }
        }
    }
}

/// Changes-view entry point for IntelliJ Git.RevertResolved. The resolved
/// ledger supplies the exact file set; the confirmation remains at the file
/// level so the user can review the path before Git reopens its conflict.
func revertResolvedPath(_ path: String) {
    guard let repo else { return }
    let alert = NSAlert()
    alert.messageText = "Revert resolved file?"
    alert.informativeText = "\(path) will return to the unresolved conflict list."
    alert.addButton(withTitle: "Revert")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    beginFeedbackOperation("Revert Resolved")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.revertResolvedConflict(path: path)
            await MainActor.run {
                self.feedbackCenter.success("Revert Resolved", detail: path)
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Revert Resolved failed",
                    detail: errorMessage(error),
                    nextStep: "打开冲突工作台并检查该文件后重试。"
                )
            }
        }
    }
}

func loadGitSSHSettings() {
    guard let repo else { return }
    let lastSuccessfulAuthentications = credentialAuth.sshAuthenticationRecords()
    Task.detached(priority: .userInitiated) {
        do {
            let settings = try repo.sshConnectionSettings()
            let credentialHelperConfig = (try? repo.credentialHelperConfig()) ?? []
            let credentialHelpers = (try? repo.credentialHelpers()) ?? []
            let sshAgentDiagnostics = try? repo.sshAgentDiagnostics()
            await MainActor.run {
                guard self.projectRepo === repo else { return }
                self.gitSSHCommand = settings.command
                self.gitSSHKnownHostsFile = settings.knownHostsFile
                self.gitSSHIdentityFile = settings.identityFile
                self.gitSSHHostKeyPolicy = settings.hostKeyPolicy
                self.gitSSHAuthMethod = settings.authMethod
                self.gitCredentialHelperConfig = credentialHelperConfig.joined(separator: "\n")
                self.gitCredentialHelpers = credentialHelpers
                self.gitSSHAgentDiagnostics = sshAgentDiagnostics
                self.lastSuccessfulSSHAuthentications = lastSuccessfulAuthentications
                self.showGitSSHSettings = true
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Load SSH settings failed",
                    detail: errorMessage(error),
                    nextStep: "确认当前项目是一个可写的 Git 工作区。"
                )
            }
        }
    }
}

func loadGitSSHAgentDiagnostics() {
    guard let repo else { return }
    Task.detached(priority: .userInitiated) {
        let diagnostics = try? repo.sshAgentDiagnostics()
        await MainActor.run {
            guard self.projectRepo === repo else { return }
            self.gitSSHAgentDiagnostics = diagnostics
        }
    }
}

func loadGitCredentialHelpers() {
    guard let repo else { return }
    Task.detached(priority: .userInitiated) {
        let credentialHelpers = (try? repo.credentialHelpers()) ?? []
        await MainActor.run {
            guard self.projectRepo === repo else { return }
            self.gitCredentialHelpers = credentialHelpers
        }
    }
}

func saveGitSSHSettings() {
    guard let repo else { return }
    let command = gitSSHCommand.trimmingCharacters(in: .whitespacesAndNewlines)
    let knownHostsFile = gitSSHKnownHostsFile.trimmingCharacters(in: .whitespacesAndNewlines)
    let identityFile = gitSSHIdentityFile.trimmingCharacters(in: .whitespacesAndNewlines)
    let hostKeyPolicy = gitSSHHostKeyPolicy
    let authMethod = gitSSHAuthMethod
    let helperValues = gitCredentialHelperConfig
        .split(whereSeparator: \.isNewline)
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }
    beginFeedbackOperation("Save SSH and credential settings")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.setSshConnectionSettings(
                command: command,
                knownHostsFile: knownHostsFile,
                identityFile: identityFile,
                hostKeyPolicy: hostKeyPolicy,
                authMethod: authMethod
            )
            try repo.setCredentialHelperConfig(helpers: helperValues)
            let credentialHelpers = (try? repo.credentialHelpers()) ?? []
            let sshAgentDiagnostics = try? repo.sshAgentDiagnostics()
            await MainActor.run {
                self.gitCredentialHelpers = credentialHelpers
                self.gitSSHAgentDiagnostics = sshAgentDiagnostics
                self.feedbackCenter.success(
                    "SSH and credential settings saved",
                    detail: command.isEmpty
                        ? "Using the configured SSH defaults"
                        : command
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Save SSH and credential settings failed",
                    detail: errorMessage(error),
                    nextStep: "检查 SSH 与 credential.helper 每行一项后重试。"
                )
            }
        }
    }
}

func unstagePath(_ p: String) {
    guard let repo else { return }
    beginFeedbackOperation("Unstage file")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.unstage(path: p)
            let st = try repo.statusPaths(paths: [p]); let hid = repo.headCommitId()
            let staging = try? repo.stagingModel()
            await MainActor.run {
                self.applyIncrementalStatus(st, paths: [p]); self.headId = hid
                self.stagingModel = staging
                self.lastIndexRevision = staging?.indexRevision
                self.feedbackCenter.success("Changes unstaged")
            }
        } catch { await MainActor.run { self.loadError = errorMessage(error) } }
    }
}

/// Revert only the unstaged side of a file. This deliberately restores from
/// the index instead of HEAD so a partially staged file keeps its staged
/// content intact.
func revertUnstagedPath(_ p: String) {
    guard let repo else { return }
    let alert = NSAlert()
    alert.messageText = "Revert unstaged changes?"
    alert.informativeText = "This restores \(p) to the staged version and keeps the index unchanged."
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Revert")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    beginFeedbackOperation("Revert unstaged changes")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.restoreUnstagedPath(path: p)
            let status = try repo.statusPaths(paths: [p])
            let staging = try? repo.stagingModel()
            await MainActor.run {
                self.applyIncrementalStatus(status, paths: [p])
                self.stagingModel = staging
                self.lastIndexRevision = staging?.indexRevision
                self.feedbackCenter.success("Unstaged changes reverted", detail: p)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Revert unstaged changes failed",
                    detail: errorMessage(error),
                    nextStep: "检查文件是否仍有未暂存内容后重试。"
                )
            }
        }
    }
}

/// 用路径范围状态替换文件树中的对应条目，避免每次单文件操作都重建整棵状态树。
private func applyIncrementalStatus(_ updates: [FileEntry], paths: [String]) {
    let pathSet = Set(paths)
    entries.removeAll { pathSet.contains($0.path) }
    entries.append(contentsOf: updates)
    entries.sort { $0.path.localizedStandardCompare($1.path) == .orderedAscending }
    isShowingCachedStatusSnapshot = false
    fileContentRefreshToken &+= 1
}

struct BeforeCommitCheckError: Error {
    let command: String
    let output: String
}

nonisolated private func runBeforeCommitChecks(repo: Repository, commands: [BeforeCommitCommand]) throws {
    for item in commands {
        let outcome = try repo.runCheckCommand(command: item.command, args: item.args)
        guard outcome.success else {
            throw BeforeCommitCheckError(command: item.display, output: outcome.output)
        }
    }
}

private struct CommitWarningPresentation: Sendable, Hashable {
    let setting: GitCommitWarningSetting
    let rootLabel: String
    let message: String
}

private struct CommitWarningDecision: Sendable {
    let shouldContinue: Bool
    let setCoreAutocrlf: Bool
}

private nonisolated func commitWarningOrder(_ setting: GitCommitWarningSetting) -> Int {
    switch setting {
    case .crlf: return 0
    case .largeFile: return 1
    case .detachedHead: return 2
    case .badFileName: return 3
    }
}

private nonisolated func commitWarningPresentations(
    _ checks: [CommitCheckResult],
    rootLabel: String,
    projectPath: String?
) -> [CommitWarningPresentation] {
    checks.compactMap { check in
        guard !check.blocking,
              let setting = commitWarningSetting(for: check.kind),
              GitCommitWarningSettings.warningEnabled(setting, for: projectPath) else {
            return nil
        }
        return CommitWarningPresentation(
            setting: setting,
            rootLabel: rootLabel,
            message: check.message
        )
    }.sorted { lhs, rhs in
        commitWarningOrder(lhs.setting) < commitWarningOrder(rhs.setting)
    }
}

@MainActor
private func presentCommitWarningDecision(
    _ warnings: [CommitWarningPresentation],
    projectPath: String?
) -> CommitWarningDecision {
    guard !warnings.isEmpty else {
        return CommitWarningDecision(shouldContinue: true, setCoreAutocrlf: false)
    }

    // IntelliJ runs CommitCheck handlers in order and presents the first
    // unresolved CommitProblem as a modal decision. Keeping one warning per
    // dialog matters when a commit spans multiple roots: the user can accept
    // a large-file warning while still cancelling a later detached-HEAD or
    // filename warning, and each "don't warn again" choice remains scoped to
    // its own warning category.
    var setCoreAutocrlf = false
    var seenSettings = Set<GitCommitWarningSetting>()
    for warning in warnings {
        guard !seenSettings.contains(warning.setting) else { continue }

        let alert = NSAlert()
        alert.messageText = "Commit warning: \(warning.setting.title)"
        let prefix = warning.rootLabel.isEmpty ? "" : "\(warning.rootLabel): "
        alert.informativeText = "\(prefix)\(warning.message)"
        alert.alertStyle = .warning
        alert.showsSuppressionButton = true
        alert.suppressionButton?.title = "Don't warn about this again in this project"
        if warning.setting == .crlf {
            alert.addButton(withTitle: "Set core.autocrlf and Commit")
        }
        alert.addButton(withTitle: "Commit Anyway")
        alert.addButton(withTitle: "Cancel")

        let response = alert.runModal()
        let isCrlfFix = warning.setting == .crlf
            && response == .alertFirstButtonReturn
        let commitResponse: NSApplication.ModalResponse = warning.setting == .crlf
            ? .alertSecondButtonReturn
            : .alertFirstButtonReturn
        guard isCrlfFix || response == commitResponse else {
            return CommitWarningDecision(shouldContinue: false, setCoreAutocrlf: false)
        }
        seenSettings.insert(warning.setting)

        if alert.suppressionButton?.state == .on {
            if !(isCrlfFix && warning.setting == .crlf) {
                GitCommitWarningSettings.saveWarning(false, warning.setting, for: projectPath)
            }
        }
        if isCrlfFix {
            setCoreAutocrlf = true
        }
    }
    return CommitWarningDecision(
        shouldContinue: true,
        setCoreAutocrlf: setCoreAutocrlf
    )
}

private nonisolated func collectMultiRootCommitWarnings(
    rootPaths: [String],
    selectedChanges: [MultiRootChangeSelection]?,
    projectPath: String?
) throws -> [CommitWarningPresentation] {
    let selectedPathsByRoot = selectedChanges.map {
        Dictionary(grouping: normalizedMultiRootCommitSelections($0), by: \.rootPath)
            .mapValues { selections in Array(Set(selections.map(\.path)).sorted()) }
    }
    let largeFileLimitBytes = GitCommitWarningSettings.largeFileLimitBytes(for: projectPath)
    var warnings: [CommitWarningPresentation] = []
    for rootPath in rootPaths {
        let repository = try openRepository(path: rootPath)
        let checks: [CommitCheckResult]
        if let paths = selectedPathsByRoot?[rootPath], !paths.isEmpty {
            checks = try repository.commitChecksWithLargeFileLimitForPaths(
                maxFileSizeBytes: largeFileLimitBytes,
                paths: paths
            )
        } else {
            checks = try repository.commitChecksWithLargeFileLimit(
                maxFileSizeBytes: largeFileLimitBytes
            )
        }
        let rootLabel = URL(fileURLWithPath: rootPath).lastPathComponent
        warnings.append(contentsOf: commitWarningPresentations(
            checks,
            rootLabel: rootLabel,
            projectPath: projectPath
        ))
    }
    return warnings
}

func doCommit(forceChecks: Bool = false, rebaseAfterCommit: Bool = false) {
    guard let repo, !commitMessage.trimmingCharacters(in: .whitespaces).isEmpty else { return }
    let isRebaseEditAmend = amendMode && rebaseEditPauseAllowsAmend(operationState)
    guard operationState == nil || isRebaseEditAmend else { return }
    beginFeedbackOperation(amendMode ? "Amend commit" : "Commit")
    let msg = commitMessage
    let isAmend = amendMode
    let hooks = GitCommitHooksSettings.effectiveSkipHooks(requested: self.skipHooks)
    let checks = beforeCommitCommands
    let authorName = identityAuthorName.trimmingCharacters(in: .whitespacesAndNewlines)
    let authorEmail = identityAuthorEmail.trimmingCharacters(in: .whitespacesAndNewlines)
    let committerName = identityCommitterName.trimmingCharacters(in: .whitespacesAndNewlines)
    let committerEmail = identityCommitterEmail.trimmingCharacters(in: .whitespacesAndNewlines)
    let signOff = identitySignOff
    let coAuthors = parseCoAuthors(identityCoAuthors)
    let pendingRebase = rebaseAfterCommit ? pendingAutoSquashRebase : nil
    let operationProjectPath = projectPath
    let operationRootPath = repo.workdir() ?? ""
    let operationRootLabel = operationRootPath.isEmpty
        ? ""
        : URL(fileURLWithPath: operationRootPath).lastPathComponent
    rememberCommitAuthor(
        name: authorName,
        email: authorEmail,
        projectPath: operationProjectPath
    )
    Task.detached(priority: .userInitiated) {
        do {
            // COMMIT-001 内置检查:身份缺失/未解决冲突(阻塞),大文件/CRLF/detached(警告)
            let builtin = try repo.commitChecksWithLargeFileLimit(
                maxFileSizeBytes: GitCommitWarningSettings.largeFileLimitBytes(
                    for: operationProjectPath
                )
            )
            let blocking = builtin.filter { $0.blocking }
            if !blocking.isEmpty {
                await MainActor.run {
                    self.pendingCommitAndPush = false
                    let kinds = blocking.map { $0.kind }.map { kind -> String in
                        switch kind {
                        case .identityMissing: return "Git 身份未配置 (user.name / user.email)"
                        case .unresolvedConflicts: return "存在未解决冲突"
                        default: return "提交被内置检查阻止"
                        }
                    }
                    self.feedbackCenter.error(
                        "Commit blocked",
                        detail: kinds.joined(separator: "\n"),
                        nextStep: "配置身份或解决冲突后重试。"
                    )
                    if blocking.contains(where: { $0.kind == .identityMissing }) {
                        self.pendingIdentityCommitRetry = true
                        self.showIdentitySettings = true
                    }
                }
                return
            }
            let warningPresentations = commitWarningPresentations(
                builtin,
                rootLabel: operationRootLabel,
                projectPath: operationProjectPath
            )
            if !warningPresentations.isEmpty {
                let decision = await MainActor.run {
                    presentCommitWarningDecision(
                        warningPresentations,
                        projectPath: operationProjectPath
                    )
                }
                guard decision.shouldContinue else {
                    await MainActor.run {
                        self.pendingCommitAndPush = false
                        self.commitFeedback = "Commit cancelled"
                        self.feedbackCenter.warning(
                            "Commit cancelled",
                            detail: "Review the pre-commit warnings before committing.",
                            notificationID: operationRootLabel.isEmpty
                                ? nil
                                : self.commitNotificationID(rootPath: operationRootPath)
                        )
                    }
                    return
                }
                if decision.setCoreAutocrlf {
                    try? repo.setGlobalCoreAutocrlf()
                }
            }
            if !forceChecks {
                try runBeforeCommitChecks(repo: repo, commands: checks)
            }
            let identity = (try? repo.gitIdentity())
            let hasOverrides = !authorName.isEmpty || !authorEmail.isEmpty || !committerName.isEmpty || !committerEmail.isEmpty || signOff || !coAuthors.isEmpty
            let id = if identity?.signCommits == true || hasOverrides {
                try withArborPinentrySession {
                    try repo.commitWithOptions(
                        message: msg,
                        skipHooks: hooks,
                        authorName: authorName.isEmpty ? nil : authorName,
                        authorEmail: authorEmail.isEmpty ? nil : authorEmail,
                        committerName: committerName.isEmpty ? nil : committerName,
                        committerEmail: committerEmail.isEmpty ? nil : committerEmail,
                        signKey: identity?.signingKey,
                        signOff: signOff,
                        coAuthors: coAuthors,
                        amend: isAmend
                    )
                }
            } else if isAmend {
                try repo.amend(message: msg, skipHooks: hooks)
            } else {
                try repo.commit(message: msg, skipHooks: hooks)
            }
            let st = try repo.status(); let hid = repo.headCommitId()
            let repositoryPath = repo.workdir()
            let recent = (try? repo.recentCommitMessages(limit: 10)) ?? []
            let staging = try? repo.stagingModel()
            let branchList = (try? repo.branchList()) ?? []
            let syncStatuses = (try? repo.syncStatus()) ?? []
            await MainActor.run {
                self.entries = st; self.headId = hid
                self.stagingModel = staging
                self.lastIndexRevision = staging?.indexRevision
                self.branches = branchList
                self.syncStatuses = syncStatuses
                self.logDetailCommit = nil
                if self.toolWindowMode == .log {
                    // The Log workspace stays live beside Commit in Rebased;
                    // committing from the left pane must immediately move
                    // the graph and inspector to the new HEAD.
                    self.loadLog()
                }
                self.recentMessages = recent
                self.commitMessage = ""
                if isRebaseEditAmend {
                    self.refreshAll(showFeedback: false)
                    let recoveryActions = repositoryPath.flatMap { rootPath in
                        self.operationState.map {
                            self.operationRecoveryFeedbackActions(
                                state: $0,
                                rootPath: rootPath
                            )
                        }
                    } ?? []
                    self.commitFeedback = "已 Amend rebase edit \(String(id.prefix(7)))"
                    self.feedbackCenter.success(
                        "Rebase commit amended",
                        detail: "\(String(id.prefix(7)))；请从恢复栏 Continue Rebase。",
                        additionalActions: recoveryActions,
                        notificationID: repositoryPath.map {
                            operationRecoveryNotificationID(rootPath: $0)
                        },
                        notificationGroup: .standard,
                        localized: false
                    )
                    return
                }
                let shouldOpenPushDialog = self.pendingCommitAndPush
                self.pendingCommitAndPush = false
                self.pendingAutoSquashRebase = nil
                self.commitFeedback = isAmend
                    ? "已 Amend \(String(id.prefix(7)))"
                    : "已提交 \(String(id.prefix(7)))"
                let rewordAction = repositoryPath.map {
                    self.commitRewordFeedbackAction(rootPath: $0, commitID: id)
                }
                self.feedbackCenter.success(
                    isAmend ? "Amend completed" : "Commit completed",
                    detail: String(id.prefix(7)),
                    additionalActions: rewordAction.map { [$0] } ?? [],
                    notificationID: repositoryPath.map(self.commitNotificationID)
                )
                if shouldOpenPushDialog, let repositoryPath {
                    self.beginSingleRootPushAfterCommit(rootPath: repositoryPath)
                }
                if let pendingRebase {
                    let hasResidualChanges = st.contains {
                        $0.staged != .unchanged
                            || $0.unstaged != .unchanged
                    }
                    if hasResidualChanges {
                        self.commitFeedback = "已提交；为保护未提交改动，未自动变基"
                        self.feedbackCenter.warning(
                            "Commit completed; rebase skipped",
                            detail: "Uncommitted changes remain after the partial commit.",
                            nextStep: "Review or stash the remaining changes, then run the rebase again."
                        )
                    } else {
                        self.startAutoSquashRebase(
                            onto: pendingRebase.onto,
                            targetID: pendingRebase.targetID,
                            root: pendingRebase.root
                        )
                    }
                }
            }
        } catch {
            await MainActor.run {
                if let checkError = error as? BeforeCommitCheckError {
                    self.feedbackCenter.warning(
                        "Commit checks failed",
                        detail: "\(checkError.command)\n\n\(checkError.output)",
                        nextStep: "Review the check output, then retry or choose the force action."
                    )
                    let alert = NSAlert()
                    alert.messageText = "提交前检查失败"
                    alert.informativeText = "\(checkError.command)\n\n\(checkError.output)"
                    alert.addButton(withTitle: "强制提交")
                    alert.addButton(withTitle: "取消")
                    if alert.runModal() == .alertFirstButtonReturn {
                        self.doCommit(forceChecks: true, rebaseAfterCommit: rebaseAfterCommit)
                    } else {
                        self.pendingCommitAndPush = false
                    }
                    return
                }
                self.pendingCommitAndPush = false
                self.commitFeedback = errorMessage(error)
                self.loadError = self.commitFeedback
                let detail = errorMessage(error)
                if gitCommitSigningFailureNeedsGPGConfiguration(detail) {
                    self.feedbackCenter.error(
                        "Commit signing failed",
                        detail: detail,
                        nextStep: "Install GnuPG if needed, or configure a working pinentry program, then retry the commit.",
                        additionalActions: [self.gpgAgentSettingsFeedbackAction()],
                        notificationID: self.repo?.workdir().map(self.commitNotificationID)
                    )
                }
            }
        }
    }
}

/// IntelliJ's Git.Stage.ToggleCommitAll path: when nothing is staged, commit
/// all tracked worktree changes without adding untracked files implicitly.
/// The explicit Stage All action remains available for users who also want to
/// include untracked files.
func commitAllTrackedChanges() {
    guard let repo,
          !commitMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
          entries.contains(where: {
              $0.staged != .conflicted
                  && $0.unstaged != .conflicted
                  && $0.unstaged != .unchanged
                  && $0.unstaged != .untracked
                  && $0.unstaged != .ignored
          }) else { return }
    beginFeedbackOperation("Commit all tracked changes")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.stageTracked()
            await MainActor.run {
                self.refreshAll(showFeedback: false)
                self.doCommit()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Commit All failed",
                    detail: errorMessage(error),
                    nextStep: "Check the tracked changes and retry."
                )
            }
        }
    }
}

/// Run IntelliJ's Commit and Rebase executor after a generated fixup!/squash!
/// commit. Let native interactive rebase apply Git's exact autosquash title
/// matching and ordering rules, then use the same conflict recovery path as
/// interactive rebase.
func startAutoSquashRebase(
    onto: String,
    targetID: String,
    root: Bool
) {
    guard let repo else { return }
    let repositoryPath = repo.workdir() ?? ""
    rebaseUndoSeed = nil
    rebaseUndoTarget = nil
    clearRebaseUndoSeed(repositoryPath: repositoryPath)
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Rebase", cancelHandle: cancel)
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    Task.detached(priority: .userInitiated) {
        do {
            // IntelliJ's Commit and Rebase executor starts a native
            // interactive rebase after the fixup!/squash! commit is created.
            // Load the plain range only to validate the target; Git itself is
            // authoritative for autosquash ordering and control semantics.
            let todo: RebaseTodo = if root {
                try repo.rebaseRootTodo(autoSquash: false, preserveMerges: false)
            } else {
                try repo.rebaseTodoWithOptions(
                    onto: onto,
                    autoSquash: false,
                    preserveMerges: false
                )
            }
            guard todo.items.contains(where: { $0.commitId == targetID }) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 1,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "The selected target commit is not in the current rebase range."
                    ]
                )
            }
            let branch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name
            let initialHead = branch.flatMap { try? repo.revisionCommitId(revision: $0) }
            let seed = initialHead.flatMap { initialHead in
                branch.map {
                    RebaseUndoSeed(
                        repositoryPath: repositoryPath,
                        branch: $0,
                        initialHead: initialHead,
                        updateRefs: false,
                        protectionCommitID: root
                            ? nil
                            : rebaseUndoProtectionCommitBeforeOperation(
                                repo: repo,
                                initialHead: initialHead,
                                onto: onto
                            )
                    )
                }
            }
            if let seed {
                saveRebaseUndoSeed(seed)
            }
            let nativeActions = todo.items.map { _ in RebaseAction.pick }
            let outcome = try repo.rebaseWithAdvancedOptionsAndPolicyAndCancel(
                onto: onto,
                actions: nativeActions,
                preserveMerges: false,
                autoSquash: true,
                keepEmpty: false,
                updateRefs: false,
                root: root,
                savePolicy: projectSavePolicy,
                cancel: cancel
            )
            let st = try repo.status()
            let finalHead = seed.flatMap { try? repo.revisionCommitId(revision: $0.branch) }
            let currentBranch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name
            let undoTarget = rebaseUndoTargetAfterCompletion(
                seed: seed,
                currentBranch: currentBranch,
                finalHead: finalHead
            )
            await MainActor.run {
                self.entries = st
                self.rebaseRange = []
                self.rebaseActions = []
                self.rebaseTodoItems = []
                self.rebaseTodoRoot = false
                self.showRebaseTodoEditor = false
                self.rebasePaused = outcome.paused
                self.rebasePauseReason = outcome.pauseReason
                self.rebaseConflicts = outcome.conflicts
                if outcome.paused, outcome.pauseReason == .conflict {
                    let names = outcome.conflicts.prefix(3).joined(separator: "、")
                    let suffix = names.isEmpty ? "" : "：\(names)"
                    self.rebaseFeedback = "Autosquash 冲突 \(outcome.conflicts.count) 个文件\(suffix)，请解决后「继续」"
                    self.showMergeRevisionsDialog = true
                } else if outcome.paused {
                    self.rebaseFeedback = "Autosquash 已暂停在 edit 提交，可修改文件后「继续」"
                } else {
                    self.rebaseFeedback = "Autosquash 变基完成"
                }
                self.rebaseUndoSeed = outcome.paused ? seed : nil
                self.rebaseUndoTarget = outcome.paused ? nil : undoTarget
                if outcome.paused {
                    if let seed {
                        saveRebaseUndoSeed(seed)
                    }
                } else {
                    clearRebaseUndoSeed(repositoryPath: repositoryPath)
                }
                if let undoTarget {
                    self.feedbackCenter.success(
                        "Rebase completed",
                        detail: String(outcome.headId.prefix(7)),
                        additionalActions: [self.rebaseUndoFeedbackAction(for: undoTarget)],
                        notificationID: rebaseUndoNotificationID(repositoryPath: repositoryPath),
                        notificationGroup: .standard
                    )
                }
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            if case .Cancelled = error as? EngineError {
                await MainActor.run {
                    self.rebaseFeedback = "Autosquash 变基已取消；保存的本地现场未被丢弃"
                    self.feedbackCenter.warning(
                        "Autosquash rebase cancelled",
                        detail: self.rebaseFeedback ?? "保存的本地现场未被丢弃",
                        nextStep: "Check Saved Changes or Stash, restore any pending local scene, then retry.",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repositoryPath
                        ).map { [$0] } ?? []
                    )
                }
                return
            }
            await MainActor.run {
                if (try? repo.operationState())?.kind != .rebase {
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = nil
                    clearRebaseUndoSeed(repositoryPath: repositoryPath)
                }
                let detail = errorMessage(error)
                self.rebaseFeedback = "Autosquash 变基失败：\(detail)"
                self.feedbackCenter.error(
                    "Autosquash rebase failed",
                    detail: detail,
                    nextStep: "Review the rebase target and operation state, then retry or abort.",
                    additionalActions: self.pendingSavedChangesFeedbackAction(
                        repo: repo,
                        rootPath: repositoryPath
                    ).map { [$0] } ?? []
                )
            }
        }
    }
}

/// 逐行暂存入口：选中文件并让 diff 视图进入选择模式。
func partialMode(_ p: String) {
    commitPreviewPath = p
    selectionModePath = p
    selection = nil
    fileSelection = nil
    commitPreviewVisible = true
}

/// 加载提交信息模板（commit.template）填入提交信息框。
func loadTemplate() {
    guard let repo else { return }
    Task.detached(priority: .userInitiated) {
        let tpl = (try? repo.commitTemplate()) ?? nil
        await MainActor.run {
            if let tpl, !tpl.isEmpty {
                self.commitMessage = tpl
            } else {
                self.commitFeedback = "未配置提交模板"
            }
        }
    }
}

/// 加载最近提交信息（供「最近信息」下拉）。
func loadRecentMessages() {
    guard let repo else { return }
    Task.detached(priority: .userInitiated) {
        let msgs = (try? repo.recentCommitMessages(limit: 10)) ?? []
        await MainActor.run { self.recentMessages = msgs }
    }
}

func currentMergeEngineOptions() -> MergeOptions {
    let strategy = MergeStrategyChoice(rawValue: mergeStrategyRaw) ?? .automatic
    let message = mergeCommitMessage.trimmingCharacters(in: .whitespacesAndNewlines)
    return MergeOptions(
        mode: mergeEngineMode(for: strategy),
        commitMessage: mergeUseCustomCommitMessage && !message.isEmpty ? message : nil,
        noCommit: mergeNoCommit,
        noVerify: mergeNoVerify,
        allowUnrelatedHistories: mergeAllowUnrelatedHistories
    )
}

func doMerge() {
    guard operationState?.kind == nil,
          isArborVCSActionEnabled(.merge, in: vcsActionContext) else { return }
    saveMergeDialogSettings()
    runMerge(preserveLocalChanges: false)
}

private func runMerge(preserveLocalChanges: Bool) {
    guard let repo, !mergeBranch.isEmpty else { return }
    beginFeedbackOperation("Merge")
    pendingMergeDeleteBranch = nil
    let branch = mergeBranch
    let initialHead = repo.headCommitId()
    mergeInitialHead = initialHead
    let strategy = MergeStrategyChoice(rawValue: mergeStrategyRaw) ?? .automatic
    let commitMessage = mergeCommitMessage.trimmingCharacters(in: .whitespacesAndNewlines)
    let noCommit = mergeNoCommit
    let noVerify = mergeNoVerify
    let allowUnrelatedHistories = mergeAllowUnrelatedHistories
    let canDeleteMergedBranch = branches.contains {
        $0.name == branch && !$0.isCurrent
    } && !GitProtectedBranchRules.matches(
        branch,
        patterns: effectiveProtectedBranchPatterns
    )
    let deleteOnMerge = GitDeleteOnMergeOption.effectiveOption(
        mergeDeleteOnMergeOption,
        canDeleteBranch: canDeleteMergedBranch
    )
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    Task.detached(priority: .userInitiated) {
        do {
            let mergedBranchNames = Set((try? repo.branchListMergedAll().map(\.name)) ?? [])
            if mergeBranchIsAlreadyMerged(branch, mergedBranches: mergedBranchNames) {
                await MainActor.run {
                    self.mergeInitialHead = nil
                    self.mergeFeedback = "分支已合并，无需再次合并：\(branch)"
                    self.feedbackCenter.warning(
                        "Merge is not needed",
                        detail: "\(branch) is already merged into the current branch.",
                        nextStep: "Choose a branch with unmerged commits."
                    )
                }
                return
            }
            let mode: MergeMode
            switch strategy {
            case .automatic: mode = .fastForward
            case .fastForwardOnly: mode = .fastForwardOnly
            case .noFastForward: mode = .noFastForward
            case .squash: mode = .squash
            }
            let options = MergeOptions(
                mode: mode,
                commitMessage: commitMessage.isEmpty ? nil : commitMessage,
                noCommit: noCommit,
                noVerify: noVerify,
                allowUnrelatedHistories: allowUnrelatedHistories
            )
            let mo = if preserveLocalChanges {
                try repo.mergeWithSettingsAndPolicy(
                    branch: branch,
                    options: options,
                    savePolicy: projectSavePolicy
                )
            } else {
                try repo.mergeWithSettings(branch: branch, options: options)
            }
            let finalHead = repo.headCommitId()
            let st = try repo.status()
            await MainActor.run {
                self.entries = st
                self.toolWindowMode = .commit
                self.toolWindowExpanded = true
                self.mergeInProgress = mo.requiresFinish
                self.pendingMergeDeleteBranch = mo.requiresFinish ? branch : nil
                self.selection = mo.conflicts.first
                self.showMergeRevisionsDialog = !mo.conflicts.isEmpty
                if !mo.conflicts.isEmpty {
                    self.mergeFeedback = "冲突 \(mo.conflicts.count) 个文件：\(mo.conflicts.joined(separator: ", "))"
                } else if mo.completed {
                    self.mergeFeedback = "合并成功（已完成）"
                    let viewCommitsAction = repo.workdir().flatMap { rootPath in
                        self.completedMergeViewCommitsAction(
                            rootPath: rootPath,
                            initialHead: initialHead,
                            finalHead: finalHead,
                            completed: mo.completed
                        )
                    }
                    let viewCommitsActions = viewCommitsAction.map { [$0] } ?? []
                    if deleteOnMerge == .delete {
                        self.feedbackCenter.success(
                            "Merge completed",
                            detail: branch,
                            additionalActions: viewCommitsActions,
                            notificationGroup: .standard
                        )
                        self.branchDelete(branch)
                    } else if deleteOnMerge == .propose {
                        self.feedbackCenter.success(
                            "Merge completed",
                            detail: branch,
                            actionTitle: "Delete branch",
                            action: postMergeDeleteAction(repo: repo, branch: branch),
                            additionalActions: viewCommitsActions,
                            notificationGroup: .standard
                        )
                    } else {
                        self.feedbackCenter.success(
                            "Merge completed",
                            detail: branch,
                            additionalActions: viewCommitsActions,
                            notificationGroup: .standard
                        )
                    }
                    self.mergeInitialHead = nil
                    self.refreshAll(showFeedback: false)
                } else if mo.squashed {
                    self.mergeFeedback = "Squash 合并已应用，点击「完成合并」创建单父提交"
                } else {
                    self.mergeFeedback = "合并已应用，点击「完成合并」创建双父提交"
                }
            }
        } catch {
            if case let .LocalChangesWouldBeOverwritten(paths) = error as? EngineError {
                await MainActor.run {
                    self.feedbackCenter.warning(
                        "Merge needs a decision",
                        detail: paths.joined(separator: ", "),
                        nextStep: "Choose Smart Merge to preserve local changes, or cancel and keep the current worktree."
                    )
                    self.presentSmartOperationDecision(
                        operationTitle: "Merge",
                        paths: paths,
                        detail: errorMessage(error),
                        smartButtonTitle: "Smart Merge",
                        onSmart: {
                            self.runMerge(preserveLocalChanges: true)
                        }
                    )
                    self.mergeFeedback = errorMessage(error)
                }
            } else {
                await MainActor.run {
                    self.mergeInitialHead = nil
                    self.mergeFeedback = friendlyRemoteError(error)
                    if self.isAuthenticationFailure(error) { self.showHostingAuthPrompt = true }
                }
            }
        }
    }
}

func finishMerge() {
    if stashPopConflictInProgress || stashApplyConflictInProgress {
        finishStashConflict()
        return
    }
    guard let repo, mergeInProgress else { return }
    let sourceBranch = pendingMergeDeleteBranch ?? repo.mergeSourceReference()
    let initialHead = mergeInitialHead
        ?? (try? repo.revisionCommitId(revision: "ORIG_HEAD"))
    let canProposeDelete = sourceBranch.map {
        canProposeDeleteMergedBranch(
            repo: repo,
            branch: $0,
            protectedPatterns: effectiveProtectedBranchPatterns
        )
    } ?? false
    beginFeedbackOperation("Complete merge")
    Task.detached(priority: .userInitiated) {
        do {
            let commitID = try repo.finishMerge(message: nil)
            let finalHead = repo.headCommitId()
            await MainActor.run {
                self.mergeInProgress = false
                self.pendingMergeDeleteBranch = nil
                self.mergeFeedback = "已完成合并 \(String(commitID.prefix(7)))"
                self.showMergeRevisionsDialog = false
                let deleteOnMerge = GitDeleteOnMergeOption.effectiveOption(
                    self.mergeDeleteOnMergeOption,
                    canDeleteBranch: canProposeDelete
                )
                let viewCommitsActions = repo.workdir().flatMap { rootPath in
                    self.completedMergeViewCommitsAction(
                        rootPath: rootPath,
                        initialHead: initialHead,
                        finalHead: finalHead,
                        completed: true
                    )
                }.map { [$0] } ?? []
                self.mergeInitialHead = nil
                if deleteOnMerge == .delete, let sourceBranch {
                    self.feedbackCenter.success(
                        "Merge completed",
                        detail: sourceBranch,
                        additionalActions: viewCommitsActions,
                        notificationGroup: .standard
                    )
                    self.branchDelete(sourceBranch)
                } else if deleteOnMerge == .propose, let sourceBranch {
                    self.feedbackCenter.success(
                        "Merge completed",
                        detail: sourceBranch,
                        actionTitle: "Delete branch",
                        action: postMergeDeleteAction(repo: repo, branch: sourceBranch),
                        additionalActions: viewCommitsActions,
                        notificationGroup: .standard
                    )
                } else {
                    self.feedbackCenter.success(
                        "Merge completed",
                        detail: String(commitID.prefix(7)),
                        additionalActions: viewCommitsActions,
                        notificationGroup: .standard
                    )
                }
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                self.mergeFeedback = errorMessage(error)
                if case let .StashApplyConflict(paths, stashID) = error as? EngineError {
                    self.showStashRestoreConflict(
                        paths,
                        operationName: "Merge",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repo.workdir()
                        ).map { [$0] } ?? [],
                        stashID: stashID
                    )
                } else if case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                    self.presentShelveConflict(
                        name: name,
                        paths: paths,
                        isPop: true,
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repo.workdir()
                        ).map { [$0] } ?? []
                    )
                } else {
                    self.feedbackCenter.error(
                        "Complete merge failed",
                        detail: errorMessage(error),
                        nextStep: "Resolve remaining conflicts, or abort the merge.",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repo.workdir()
                        ).map { [$0] } ?? []
                    )
                }
            }
        }
    }
}

/// Roll back a completed merge only when the branch has not moved since the
/// success notification. This prevents an old toast action from undoing a
/// later commit or branch switch.
func rollbackMerge(_ request: MergeRollbackRequest) {
    guard projectRepo === request.repo else {
        feedbackCenter.error(
            "Merge rollback unavailable",
            detail: "The repository is no longer the active project.",
            nextStep: "Open the original project window and retry the rollback."
        )
        return
    }
    beginFeedbackOperation("Rollback Merge")
    Task.detached(priority: .userInitiated) {
        do {
            guard request.repo.headCommitId() == request.expectedHead else {
                throw NSError(
                    domain: "Arbor.MergeRollback",
                    code: 1,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "The merge result changed after the notification was created."
                    ]
                )
            }
            guard try request.repo.operationState() == nil else {
                throw NSError(
                    domain: "Arbor.MergeRollback",
                    code: 2,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "Another Git operation is active in this repository."
                    ]
                )
            }
            try request.repo.reset(commitId: request.initialHead, mode: .keep)
            await MainActor.run {
                self.loadRepoData(includeComparisons: false)
                self.loadMultiRoots()
                self.refreshAll(showFeedback: false)
                self.feedbackCenter.success(
                    "Merge rollback completed",
                    detail: request.branch
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Merge rollback failed",
                    detail: errorMessage(error),
                    nextStep: "No changes were discarded; resolve overlapping local edits or use Reset explicitly."
                )
            }
        }
    }
}

/// IDX-001「Add to Git / Ignore」入口：追加规则到工作区或选定的 .gitignore。
/// Multiple selected unversioned files share one ignore-file choice and are
/// validated by Rust before any rule is written.
struct IgnoreFileCreationRequest: Equatable {
    let paths: [String]
    let workdir: String
}

func ignorePaths(_ paths: [String], ignoreFilePath: String? = nil) {
    guard let repo else { return }
    let paths = Array(Set(paths)).sorted()
    guard !paths.isEmpty else { return }
    if let workdir = repo.workdir(),
       gitIgnoreNeedsRootCreationConfirmation(
           ignoreFilePath: ignoreFilePath,
           workdir: workdir
       ) {
        pendingIgnoreFileCreation = IgnoreFileCreationRequest(
            paths: paths,
            workdir: URL(fileURLWithPath: workdir).standardizedFileURL.path
        )
        return
    }
    performIgnorePaths(paths, ignoreFilePath: ignoreFilePath)
}

func confirmPendingIgnoreFileCreation() {
    guard let request = pendingIgnoreFileCreation else { return }
    pendingIgnoreFileCreation = nil
    guard let repo,
          let workdir = repo.workdir(),
          URL(fileURLWithPath: workdir).standardizedFileURL.path == request.workdir
    else {
        feedbackCenter.error(
            "Ignore failed",
            detail: "The repository changed while confirming .gitignore creation.",
            nextStep: "Select the files again and retry."
        )
        return
    }
    performIgnorePaths(request.paths, ignoreFilePath: nil)
}

private func performIgnorePaths(_ paths: [String], ignoreFilePath: String?) {
    guard let repo else { return }
    let targetPaths: [String]
    if let ignoreFilePath, let workdir = repo.workdir() {
        targetPaths = gitIgnoreTargetPaths(
            for: paths,
            ignoreFile: ignoreFilePath,
            workdir: workdir
        )
    } else {
        targetPaths = paths
    }
    guard !targetPaths.isEmpty else { return }
    beginFeedbackOperation("Ignore file")
    Task.detached(priority: .userInitiated) {
        do {
            let rules: [String]
            if let ignoreFilePath, let workdir = repo.workdir() {
                let relativeRules = targetPaths.map { path in
                    gitIgnoreRule(
                        for: path,
                        ignoreFile: ignoreFilePath,
                        workdir: workdir
                    )
                }
                rules = try repo.addToGitignoreAtPaths(
                    rules: relativeRules,
                    ignoreFile: ignoreFilePath,
                    targetPaths: targetPaths
                )
            } else {
                rules = try repo.addToGitignoreRules(rules: targetPaths)
            }
            await MainActor.run {
                let destination = ignoreFilePath ?? ".gitignore"
                self.feedbackCenter.success(
                    "Ignored",
                    detail: "\(rules.joined(separator: ", ")) -> \(destination)"
                )
                self.operationFeedback = nil
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Ignore failed", detail: errorMessage(error), nextStep: "规则必须是非空单行。")
            }
        }
    }
}

/// IDX-001「Exclude」入口：追加路径到 .git/info/exclude（不入库）。
func excludePathFromRepo(_ path: String) {
    guard let repo else { return }
    beginFeedbackOperation("Exclude path")
    Task.detached(priority: .userInitiated) {
        do {
            let rule = try repo.excludePath(path: path)
            await MainActor.run {
                self.feedbackCenter.success("Excluded", detail: "\(rule) -> .git/info/exclude")
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Exclude failed", detail: errorMessage(error), nextStep: "路径必须是非空单行。")
            }
        }
    }
}

/// REBASE-001：从 Log 选中提交发起交互式 rebase。
/// 生成显式 todo（rebase_todo）并打开编辑器；autosquash 在生成时预览。
func interactiveRebaseFromLog(_ commit: CommitInfo) {
    guard let repo = logRepository(for: commit) else { return }
    let root = commit.parentIds.isEmpty
    guard root || interactiveRebaseBaseRevision(for: commit) != nil else {
        feedbackCenter.error(
            "Interactive Rebase unavailable",
            detail: "The selected commit has no usable rebase upstream.",
            nextStep: "Select a commit on the current branch and retry."
        )
        return
    }
    guard !root || (try? repo.isCommitReachableFrom(commitId: commit.id, descendantId: "HEAD")) == true else {
        feedbackCenter.error(
            "Interactive Rebase unavailable",
            detail: "The selected root is not an ancestor of the current branch.",
            nextStep: "Select the current branch root and retry."
        )
        return
    }
    let onto = interactiveRebaseBaseRevision(for: commit) ?? ""
    let preserveMerges = commit.parentIds.count > 1
    beginFeedbackOperation("Interactive Rebase")
    Task.detached(priority: .userInitiated) {
        do {
            let todo: RebaseTodo = if root {
                try repo.rebaseRootTodo(autoSquash: false, preserveMerges: preserveMerges)
            } else {
                try repo.rebaseTodoWithOptions(
                    onto: onto,
                    autoSquash: false,
                    preserveMerges: preserveMerges
                )
            }
            await MainActor.run {
                self.rebaseTodoOnto = onto
                self.rebaseTodoItems = todo.items
                self.rebaseTodoPreserveMerges = preserveMerges
                self.rebaseTodoRoot = root
                self.showRebaseTodoEditor = true
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Interactive Rebase failed", detail: errorMessage(error), nextStep: "无法从该提交生成 todo。")
            }
        }
    }
}

/// REBASE-002：从 Log 的提交上下文菜单预配置单提交改写动作。
/// 仍然交给 todo 编辑器确认，避免上下文菜单直接执行不可逆的历史重写。
func rewriteCommitFromLog(
    _ commit: CommitInfo,
    action: RebaseTodoAction,
    initialCommitConfirmed: Bool = false
) {
    guard let repo = logRepository(for: commit) else { return }
    guard (try? repo.isCommitReachableFrom(commitId: commit.id, descendantId: "HEAD")) == true else {
        feedbackCenter.error(
            "Rewrite commit unavailable",
            detail: "The selected commit is not on the current branch's linear history.",
            nextStep: "Select a commit from the current branch and retry."
        )
        return
    }
    if let protectedBranch = protectedRemoteBranchContainingCommit(
        repo: repo,
        commitID: commit.id,
        remoteBranches: activeLogRemoteBranches,
        protectedPatterns: effectiveProtectedBranchPatterns
    ) {
        feedbackCenter.error(
            "History rewrite blocked",
            detail: "The selected commit is published to protected branch \(protectedBranch).",
            nextStep: "Fetch or select an unpublished commit before rewriting history."
        )
        return
    }

    // IntelliJ uses `git commit --amend --only` for the latest commit. Keep
    // this fast path separate from the todo editor: a Log reword must never
    // absorb unrelated staged changes from the Commit workspace.
    if action == .reword, commit.isHead {
        logRewordUsesRootRebase = false
        logRewordCommit = commit
        logRewordMessage = commit.messageBody.isEmpty
            ? commit.summary
            : "\(commit.summary)\n\n\(commit.messageBody)"
        if commit.parentIds.isEmpty {
            pendingInitialCommitReword = commit
            showInitialCommitRewordAlert = true
        } else {
            showLogRewordDialog = true
        }
        return
    }
    if action == .reword, commit.parentIds.isEmpty {
        // IntelliJ uses `git rebase --root` when the selected root is not
        // HEAD. Keep the same full-message editor, but route confirmation to
        // the engine's clean linear root-history rewrite path.
        logRewordUsesRootRebase = true
        logRewordCommit = commit
        logRewordMessage = commit.messageBody.isEmpty
            ? commit.summary
            : "\(commit.summary)\n\n\(commit.messageBody)"
        showLogRewordDialog = true
        return
    }
    if action == .drop, commit.parentIds.isEmpty {
        if !initialCommitConfirmed {
            pendingInitialCommitRewrite = PendingInitialCommitRewrite(
                commits: [commit],
                action: action
            )
            showInitialCommitRewriteAlert = true
            return
        }
        dropSelectedCommitsFromLog([commit], repository: repo)
        return
    }
    guard let firstParent = commit.parentIds.first else {
        feedbackCenter.error(
            "Rewrite commit unavailable",
            detail: "The initial commit can only be reworded when it is HEAD.",
            nextStep: "Check out the branch containing the initial commit, then retry."
        )
        return
    }
    if commit.parentIds.count > 1 {
        feedbackCenter.error(
            "Rewrite commit unavailable",
            detail: "Merge commits are not supported by the linear todo editor.",
            nextStep: "Use a regular interactive rebase with merge preservation."
        )
        return
    }
    if action == .drop {
        dropSelectedCommitsFromLog([commit], repository: repo)
        return
    }

    beginFeedbackOperation("Prepare Commit Rewrite")
    Task.detached(priority: .userInitiated) {
        do {
            let onto: String
            switch action {
            case .squash, .fixup:
                let previous = try repo.logFiltered(
                    path: nil,
                    limit: 1,
                    follow: false,
                    startRev: firstParent,
                    author: nil,
                    since: nil
                ).first
                guard let previous,
                      let previousParent = previous.parentIds.first else {
                    throw NSError(
                        domain: "Arbor.Git",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "The selected commit has no previous commit to combine with."]
                    )
                }
                onto = previousParent
            default:
                onto = firstParent
            }

            var todo = try repo.rebaseTodo(onto: onto, autoSquash: false)
            guard let targetIndex = todo.items.firstIndex(where: { item in
                item.commitId == commit.id
                    || item.commitId.hasPrefix(commit.id)
                    || commit.id.hasPrefix(item.commitId)
            }) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 2,
                    userInfo: [NSLocalizedDescriptionKey: "The selected commit is not on the current branch's linear history."]
                )
            }
            todo.items[targetIndex].action = action
            let preparedItems = todo.items

            await MainActor.run {
                self.rebaseTodoOnto = onto
                self.rebaseTodoItems = preparedItems
                self.rebaseTodoPreserveMerges = false
                self.rebaseTodoRoot = false
                self.showRebaseTodoEditor = true
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Prepare commit rewrite failed",
                    detail: errorMessage(error),
                    nextStep: "The action applies only to a linear commit on the current branch."
                )
            }
        }
    }
}

/// Reword the current HEAD without changing its tree or consuming staged files.
func submitLogHeadReword() {
    guard let repo = logRepository, let commit = logRewordCommit else { return }
    let message = logRewordMessage.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !message.isEmpty else {
        feedbackCenter.warning(
            "Commit message required",
            detail: "A reworded commit must keep a non-empty message.",
            nextStep: "Enter a commit title and retry."
        )
        return
    }
    if logRewordUsesRootRebase {
        showLogRewordDialog = false
        let cancel = GitCancelHandle()
        beginFeedbackOperation("Reword Root History", cancelHandle: cancel)
        let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
        Task.detached(priority: .userInitiated) {
            do {
                guard let rootPath = repo.workdir(),
                      let initialHeadID = repo.headCommitId() else {
                    throw EngineError.GitOperation(
                        message: "Reword undo requires a worktree repository with a HEAD."
                    )
                }
                let expectedBranch = try repo.branchList()
                    .first(where: { $0.isCurrent })?.name ?? ""
                // A merge descendant must be rewritten through the native
                // merge-preserving todo. The linear object-level path remains
                // the smaller/faster path when the root history has no merges.
                let outcome: RebaseOutcome
                let mergePreservingTodo = try repo.rebaseRootTodo(
                    autoSquash: false,
                    preserveMerges: true
                )
                if mergePreservingTodo.items.contains(where: { $0.isMergeCommit }) {
                    guard let todo = preparedRootRewordTodo(
                        mergePreservingTodo,
                        rootCommitID: commit.id,
                        message: message
                    ) else {
                        throw NSError(
                            domain: "Arbor.Git",
                            code: 1,
                            userInfo: [
                                NSLocalizedDescriptionKey:
                                    "The selected root commit is not in the current root rebase range."
                            ]
                        )
                    }
                    outcome = try repo.rebaseRootWithTodoAndPolicyAndCancel(
                        todo: todo,
                        preserveMerges: true,
                        savePolicy: projectSavePolicy,
                        cancel: cancel
                    )
                } else {
                    outcome = try repo.rewordRootCommit(commitId: commit.id, message: message)
                }
                let undoContext = PersistedRewordUndo(
                    initialHeadID: initialHeadID,
                    expectedHeadID: outcome.headId,
                    expectedBranch: expectedBranch
                )
                await MainActor.run {
                    self.logRewordCommit = nil
                    self.logRewordUsesRootRebase = false
                    self.feedbackCenter.expire(
                        notificationID: self.commitNotificationID(rootPath: rootPath)
                    )
                    self.feedbackCenter.success(
                        "Root commit reworded",
                        detail: String(outcome.headId.prefix(7)),
                        additionalActions: [
                            self.rewordUndoFeedbackAction(
                                rootPath: rootPath,
                                context: undoContext
                            )
                        ],
                        notificationID: self.rewordUndoNotificationID(
                            rootPath: rootPath,
                            expectedHeadID: outcome.headId
                        )
                    )
                    self.refreshAll(showFeedback: false)
                    self.loadLog()
                }
            } catch {
                if case .Cancelled = error as? EngineError {
                    await MainActor.run {
                        self.showLogRewordDialog = true
                        self.operationFeedback = "Root reword cancelled; saved local changes were restored"
                        self.feedbackCenter.warning(
                            "Root reword cancelled",
                            detail: self.operationFeedback ?? "Saved local changes were restored",
                            nextStep: "Review Saved Changes or Stash, then retry the root reword."
                        )
                    }
                    return
                }
                await MainActor.run {
                    // Keep the draft available so repository-state or todo
                    // mapping errors can be reviewed and retried.
                    self.showLogRewordDialog = true
                    self.feedbackCenter.error(
                        "Root commit reword failed",
                        detail: errorMessage(error),
                        nextStep: "Resolve the repository state, then retry the root reword.",
                        localized: true
                    )
                }
            }
        }
        return
    }
    guard commit.isHead else {
        showLogRewordDialog = false
        logRewordCommit = nil
        logRewordUsesRootRebase = false
        return
    }
    showLogRewordDialog = false
    beginFeedbackOperation("Reword HEAD")
    Task.detached(priority: .userInitiated) {
        do {
            guard let rootPath = repo.workdir(),
                  let initialHeadID = repo.headCommitId() else {
                throw EngineError.GitOperation(
                    message: "Reword undo requires a worktree repository with a HEAD."
                )
            }
            let expectedBranch = try repo.branchList()
                .first(where: { $0.isCurrent })?.name ?? ""
            let id = try repo.rewordHead(message: message, skipHooks: true)
            let undoContext = PersistedRewordUndo(
                initialHeadID: initialHeadID,
                expectedHeadID: id,
                expectedBranch: expectedBranch
            )
            await MainActor.run {
                self.logRewordCommit = nil
                self.logRewordUsesRootRebase = false
                self.feedbackCenter.expire(
                    notificationID: self.commitNotificationID(rootPath: rootPath)
                )
                self.feedbackCenter.success(
                    "Commit reworded",
                    detail: String(id.prefix(7)),
                    additionalActions: [
                        self.rewordUndoFeedbackAction(
                            rootPath: rootPath,
                            context: undoContext
                        )
                    ],
                    notificationID: self.rewordUndoNotificationID(
                        rootPath: rootPath,
                        expectedHeadID: id
                    )
                )
                self.refreshAll(showFeedback: false)
                self.loadLog()
            }
        } catch {
            await MainActor.run {
                // Keep the draft available so a hook/index/permission error can
                // be reviewed and retried without rebuilding the message.
                self.showLogRewordDialog = true
                self.feedbackCenter.error(
                    "Reword HEAD failed",
                    detail: errorMessage(error),
                    nextStep: "The commit message was not changed; review the error and retry."
                )
            }
        }
    }
}

/// Continue the IntelliJ-style initial-commit warning into the normal full
/// message editor. The engine still uses `--amend --only`, which also works
/// for a root HEAD commit without importing staged changes.
func confirmInitialCommitReword() {
    guard let commit = pendingInitialCommitReword else { return }
    pendingInitialCommitReword = nil
    logRewordUsesRootRebase = false
    logRewordCommit = commit
    logRewordMessage = commit.messageBody.isEmpty
        ? commit.summary
        : "\(commit.summary)\n\n\(commit.messageBody)"
    showLogRewordDialog = true
}

private func rebaseUndoRequest(for target: RebaseUndoTarget) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .undoRebase,
        projectPath: projectPath,
        rootPath: target.repositoryPath,
        shelfName: "",
        rebaseUndoInitialHead: target.initialHead,
        rebaseUndoExpectedHead: target.expectedHead,
        rebaseUndoBranch: target.branch,
        rebaseUndoProtectionCommit: target.protectionCommitID
    )
}

private func rebaseUndoFeedbackAction(for target: RebaseUndoTarget) -> FeedbackAction {
    let request = rebaseUndoRequest(for: target)
    return FeedbackAction(
        id: "undo-rebase:\(target.repositoryPath):\(target.expectedHead)",
        title: "Undo Rebase",
        semanticAction: request
    ) {
        handleVCSActionRequest(request)
    }
}

nonisolated private func logSelectedChangesUndoNotificationID(
    repositoryPath: String,
    expectedHead: String
) -> String {
    let stablePath = URL(fileURLWithPath: repositoryPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.log-selected-changes-undo.\(stablePath).\(expectedHead)"
}

nonisolated private func logSelectedChangesRootPathsMatch(_ lhs: String, _ rhs: String) -> Bool {
    URL(fileURLWithPath: lhs).standardizedFileURL.path
        == URL(fileURLWithPath: rhs).standardizedFileURL.path
}

private func logSelectedChangesUndoRequest(
    for target: LogSelectedChangesUndoTarget
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .undoLogSelectedChanges,
        projectPath: projectPath,
        rootPath: target.repositoryPath,
        shelfName: "",
        logSelectedChangesUndoInitialHead: target.initialHead,
        logSelectedChangesUndoExpectedHead: target.expectedHead,
        logSelectedChangesUndoBranch: target.branch
    )
}

private func logSelectedChangesUndoFeedbackAction(
    for target: LogSelectedChangesUndoTarget
) -> FeedbackAction {
    let request = logSelectedChangesUndoRequest(for: target)
    return FeedbackAction(
        id: "undo-log-selected-changes:\(target.repositoryPath):\(target.expectedHead)",
        title: "Undo Selected Changes",
        semanticAction: request
    ) {
        handleVCSActionRequest(request)
    }
}

/// Undo a completed Drop/Extract history rewrite only while its exact branch
/// tip is still checked out. The engine uses reset --keep, so local changes
/// made after the rewrite survive when they do not overlap the restored tree.
private func undoLogSelectedChanges(_ target: LogSelectedChangesUndoTarget) {
    let notificationID = logSelectedChangesUndoNotificationID(
        repositoryPath: target.repositoryPath,
        expectedHead: target.expectedHead
    )
    let protectedPatterns = effectiveProtectedBranchPatterns
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Undo Selected Changes", notificationID: notificationID)
    Task.detached(priority: .userInitiated) {
        do {
            let targetRepo = try openRepository(path: target.repositoryPath)
            guard try targetRepo.operationState() == nil else {
                throw EngineError.GitOperation(
                    message: "Undo Selected Changes is unavailable while another Git operation is active."
                )
            }
            guard targetRepo.headCommitId() == target.expectedHead else {
                throw EngineError.GitOperation(
                    message: "Undo Selected Changes refused: HEAD changed after the rewrite."
                )
            }
            let currentBranch = try targetRepo.branchList()
                .first(where: { $0.isCurrent })?.name ?? ""
            guard currentBranch == target.branch else {
                throw EngineError.GitOperation(
                    message: "Undo Selected Changes refused: the current branch changed after the rewrite."
                )
            }
            let remoteBranches = try targetRepo.remoteBranchList()
            if let protectedBranch = protectedRemoteBranchContainingCommit(
                repo: targetRepo,
                commitID: target.initialHead,
                remoteBranches: remoteBranches,
                protectedPatterns: protectedPatterns
            ) {
                throw EngineError.GitOperation(
                    message: "Undo Selected Changes blocked: \(protectedBranch) contains published pre-rewrite history."
                )
            }
            try targetRepo.undoLogSelectedChangesExpectedHead(
                initialCommitId: target.initialHead,
                expectedHead: target.expectedHead,
                expectedBranch: target.branch,
                savePolicy: projectSavePolicy
            )
            await MainActor.run {
                self.feedbackCenter.expire(notificationID: notificationID)
                self.feedbackCenter.success(
                    "Selected Changes rewrite undone",
                    detail: "HEAD restored to \(String(target.initialHead.prefix(8)))."
                )
                let isCurrentRoot = self.repo?.workdir().map {
                    logSelectedChangesRootPathsMatch(target.repositoryPath, $0)
                } == true
                if isCurrentRoot {
                    self.refreshAll(showFeedback: false)
                    self.loadLog()
                } else {
                    self.loadMultiRoots {
                        let activeRootMatches = self.logActiveRootPath.map {
                            logSelectedChangesRootPathsMatch(target.repositoryPath, $0)
                        } == true
                        if self.isLogAggregate || self.logViewMode == .command || activeRootMatches {
                            self.reloadLogView()
                        }
                    }
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Undo Selected Changes failed",
                    detail: errorMessage(error),
                    nextStep: "The repository may have changed after Drop/Extract; inspect the current Log before retrying.",
                    notificationID: notificationID
                )
            }
        }
    }
}

/// Execute IntelliJ's direct multi-commit Drop path. The engine still builds
/// and validates the explicit todo, but the user gets the native action
/// confirmation instead of an intermediate todo editor.
func dropSelectedCommitsFromLog(_ commits: [CommitInfo], repository repo: Repository) {
    // IntelliJ permits Log Drop while HEAD is detached. Keep an empty branch
    // identity so the same expected-HEAD Undo/CAS path can validate detached
    // state without inventing a ref to update.
    let branch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name ?? ""

    if GitDropCommitSettings.showConfirmation() {
        let alert = NSAlert()
        alert.messageText = commits.count == 1 ? "Drop this commit?" : "Drop selected commits?"
        let summaries = commits.prefix(3).map { $0.summary }.joined(separator: ", ")
        let suffix = commits.count > 3 ? " …" : ""
        let noun = commits.count == 1 ? "commit" : "commits"
        let destination = branch.isEmpty ? "detached HEAD" : branch
        alert.informativeText = String(commits.count) + " " + noun + " will be removed from " + destination + " and the history will be rewritten. " + summaries + suffix
        alert.addButton(withTitle: commits.count == 1 ? "Drop Commit" : "Drop Commits")
        alert.addButton(withTitle: "Cancel")
        guard alert.runModal() == .alertFirstButtonReturn else { return }
    }

    let repositoryPath = repo.workdir() ?? ""
    let commitIDs = commits.map { $0.id }
    let commitSummaries = commits.map { $0.summary }
    let protectedPatterns = effectiveProtectedBranchPatterns
    let remoteBranchesForRewrite = activeLogRemoteBranches
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    rebaseUndoSeed = nil
    rebaseUndoTarget = nil
    clearRebaseUndoSeed(repositoryPath: repositoryPath)
    let cancel = GitCancelHandle()
    let useInMemory = shouldUseInMemoryCommitEditing(
        settingEnabled: GitInMemoryCommitEditingSettings.isEnabled(),
        items: [],
        preserveMerges: false
    )
    beginFeedbackOperation("Drop Commits", cancelHandle: cancel)

    Task.detached(priority: .userInitiated) {
        do {
            guard commitIDs.allSatisfy({
                (try? repo.isCommitReachableFrom(
                    commitId: $0,
                    descendantId: "HEAD"
                )) == true
            }) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 6,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "The selected commit is not on the current branch's linear history."
                    ]
                )
            }
            if let protectedBranch = commitIDs.compactMap({ commitID in
                protectedRemoteBranchContainingCommit(
                    repo: repo,
                    commitID: commitID,
                    remoteBranches: remoteBranchesForRewrite,
                    protectedPatterns: protectedPatterns
                )
            }).first {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 7,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "The selected commit is published to protected branch \(protectedBranch)."
                    ]
                )
            }

            guard let initialHead = repo.headCommitId() else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 8,
                    userInfo: [NSLocalizedDescriptionKey: "Drop Commits requires a checked-out commit."]
                )
            }
            let seed = RebaseUndoSeed(
                repositoryPath: repositoryPath,
                branch: branch,
                initialHead: initialHead,
                updateRefs: false
            )
            saveRebaseUndoSeed(seed)
            let runNativeDrop: () throws -> RebaseOutcome = {
                try repo.dropSelectedCommitsNativeWithPolicyAndCancel(
                    commitIds: commitIDs,
                    savePolicy: projectSavePolicy,
                    cancel: cancel
                )
            }
            let outcome: RebaseOutcome
            if useInMemory {
                let inMemoryOutcome = try repo.dropSelectedCommitsWithPolicyAndCancel(
                    commitIds: commitIDs,
                    savePolicy: projectSavePolicy,
                    cancel: cancel
                )
                if inMemoryOutcome.paused, inMemoryOutcome.pauseReason == .conflict {
                    // IntelliJ drops the partial object-level rewrite before
                    // retrying native Git, so the native path sees the same
                    // original HEAD and local scene as the first attempt.
                    try repo.rebaseAbort()
                    outcome = try runNativeDrop()
                } else {
                    outcome = inMemoryOutcome
                }
            } else {
                outcome = try runNativeDrop()
            }
            let status = try repo.status()
            let finalHead = repo.headCommitId()
            let currentBranch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name
            let undoTarget = rebaseUndoTargetAfterCompletion(
                seed: seed,
                currentBranch: currentBranch,
                finalHead: finalHead
            )

            await MainActor.run {
                self.entries = status
                self.rebaseRange = []
                self.rebaseActions = []
                self.rebaseTodoItems = []
                self.rebaseTodoRoot = false
                self.showRebaseTodoEditor = false
                self.rebasePaused = outcome.paused
                self.rebasePauseReason = outcome.pauseReason
                self.rebaseConflicts = outcome.conflicts
                if outcome.paused, outcome.pauseReason == .conflict {
                    let names = outcome.conflicts.prefix(3).joined(separator: "、")
                    let suffix = names.isEmpty ? "" : "：\(names)"
                    self.rebaseFeedback = "Drop Commits 冲突 \(outcome.conflicts.count) 个文件\(suffix)，请解决后「继续」"
                    self.showMergeRevisionsDialog = true
                } else if outcome.paused {
                    self.rebaseFeedback = "Drop Commits 已暂停，可修改文件后「继续」"
                } else {
                    self.rebaseFeedback = "已删除 \(commitIDs.count) 个提交"
                }
                self.rebaseUndoSeed = outcome.paused ? seed : nil
                self.rebaseUndoTarget = outcome.paused ? nil : undoTarget
                if outcome.paused {
                    saveRebaseUndoSeed(seed)
                } else {
                    clearRebaseUndoSeed(repositoryPath: repositoryPath)
                }
                if let undoTarget {
                    self.feedbackCenter.success(
                        "Drop Commits completed",
                        detail: commitSummaries.prefix(3).joined(separator: ", "),
                        additionalActions: [self.rebaseUndoFeedbackAction(for: undoTarget)],
                        notificationID: rebaseUndoNotificationID(repositoryPath: repositoryPath),
                        notificationGroup: .standard
                    )
                } else if !outcome.paused {
                    self.feedbackCenter.success(
                        "Drop Commits completed",
                        detail: commitSummaries.prefix(3).joined(separator: ", "),
                        notificationID: rebaseUndoNotificationID(repositoryPath: repositoryPath),
                        notificationGroup: .standard
                    )
                }
                self.logSelection = nil
                self.refreshAll(showFeedback: false)
                self.loadLog()
            }
        } catch {
            if case .Cancelled = error as? EngineError {
                await MainActor.run {
                    self.rebaseFeedback = "Drop Commits 已取消；保存的本地现场未被丢弃"
                    self.feedbackCenter.warning(
                        "Drop Commits cancelled",
                        detail: self.rebaseFeedback ?? "保存的本地现场未被丢弃",
                        nextStep: "Check Saved Changes or Stash, then retry when the repository is ready.",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repositoryPath
                        ).map { [$0] } ?? []
                    )
                }
                return
            }
            await MainActor.run {
                if (try? repo.operationState())?.kind != .rebase {
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = nil
                    clearRebaseUndoSeed(repositoryPath: repositoryPath)
                }
                self.feedbackCenter.error(
                    "Drop Commits failed",
                    detail: errorMessage(error),
                    nextStep: "The operation only accepts linear commits on the checked-out history; resolve any preserved local-change conflict or Abort the paused rebase."
                )
            }
        }
    }
}

/// REBASE-003：从 Log 多选提交预配置批量 reword/squash/drop。
/// 多选动作只接受当前分支上的线性提交；root 可用于 Reword/Squash/Drop，
/// 其中 Drop 仍保持 merge-preserving 边界。Squash 使用独立完整消息
/// 对话框，Reword 仍交给 todo 编辑器确认，Drop 使用 IntelliJ 的直接确认执行路径。
func rewriteSelectedCommitsFromLog(
    _ commits: [CommitInfo],
    action: RebaseTodoAction,
    initialCommitConfirmed: Bool = false
) {
    guard let repo = logRepository(for: commits) else {
        feedbackCenter.warning("Batch rewrite unavailable", detail: "Selected commits must belong to one Git root.", nextStep: "Select commits from one repository and retry.")
        return
    }
    var seenCommitIDs = Set<String>()
    let selected = commits.filter { commit in
        seenCommitIDs.insert(commit.id).inserted
    }
    guard selected.count >= 2 else {
        feedbackCenter.warning(
            "Select at least two commits",
            detail: "Batch rewrite needs multiple selected commits.",
            nextStep: "Use Cmd-click or Shift-click in the Log graph."
        )
        return
    }
    guard action == .reword || action == .squash || action == .drop else {
        feedbackCenter.error(
            "Batch rewrite unavailable",
            detail: "Only reword, squash, and drop support multi-selection from Log.",
            nextStep: "Use the interactive rebase editor for other actions."
        )
        return
    }
    if action == .drop {
        guard selected.allSatisfy({ $0.parentIds.count <= 1 }) else {
            feedbackCenter.error(
                "Batch drop unavailable",
                detail: "Merge commits cannot be dropped by the linear multi-selection action.",
                nextStep: "Use Interactive Rebase with the appropriate history-preserving mode."
            )
            return
        }
        dropSelectedCommitsFromLog(selected, repository: repo)
        return
    }

    guard selected.allSatisfy({ $0.parentIds.count <= 1 }) else {
        feedbackCenter.error(
            "Batch rewrite unavailable",
            detail: "Merge commits cannot be rewritten by the linear multi-selection action.",
            nextStep: "Use Interactive Rebase with merge preservation instead."
        )
        return
    }

    if selected.contains(where: { $0.parentIds.isEmpty }), !initialCommitConfirmed {
        pendingInitialCommitRewrite = PendingInitialCommitRewrite(
            commits: selected,
            action: action
        )
        showInitialCommitRewriteAlert = true
        return
    }

    beginFeedbackOperation("Prepare Batch Commit Rewrite")
    let protectedPatterns = effectiveProtectedBranchPatterns
    let remoteBranchesForRewrite = activeLogRemoteBranches
    Task.detached(priority: .userInitiated) {
        do {
            guard selected.allSatisfy({
                (try? repo.isCommitReachableFrom(
                    commitId: $0.id,
                    descendantId: "HEAD"
                )) == true
            }) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 6,
                    userInfo: [NSLocalizedDescriptionKey: "The selected commit is not on the current branch's linear history."]
                )
            }
            guard let oldest = oldestSelectedLinearCommit(
                selected,
                isAncestor: { ancestor, descendant in
                    (try? repo.isCommitReachableFrom(
                        commitId: ancestor,
                        descendantId: descendant
                    )) == true
                }
            ) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 9,
                    userInfo: [NSLocalizedDescriptionKey: "The selected commits do not form one linear history range."]
                )
            }
            let rootRebase = oldest.parentIds.isEmpty
            let onto = oldest.parentIds.first ?? ""
            if let protectedBranch = selected.compactMap({ commit in
                protectedRemoteBranchContainingCommit(
                    repo: repo,
                    commitID: commit.id,
                    remoteBranches: remoteBranchesForRewrite,
                    protectedPatterns: protectedPatterns
                )
            }).first {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 7,
                    userInfo: [NSLocalizedDescriptionKey: "The selected commit is published to protected branch \(protectedBranch)."]
                )
            }
            var todo: RebaseTodo = if rootRebase {
                try repo.rebaseRootTodo(autoSquash: false, preserveMerges: false)
            } else {
                try repo.rebaseTodo(onto: onto, autoSquash: false)
            }
            let indexes = selected.map { commit in
                todo.items.firstIndex { item in
                    item.commitId == commit.id
                        || item.commitId.hasPrefix(commit.id)
                        || commit.id.hasPrefix(item.commitId)
                }
            }
            guard indexes.allSatisfy({ $0 != nil }) else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 3,
                    userInfo: [NSLocalizedDescriptionKey: "One or more selected commits are not on the current branch's linear history."]
                )
            }
            let sortedIndexes = indexes.compactMap { $0 }.sorted()
            guard sortedIndexes.count == selected.count else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 4,
                    userInfo: [NSLocalizedDescriptionKey: "The selected commits could not be mapped to one rebase range."]
                )
            }
            let squashCommits: [CommitInfo]
            let preparedSquashIndexes: [Int]
            if action == .squash {
                // IntelliJ's in-memory `unite` moves selected entries next to
                // the first selected entry, preserving their history order,
                // then turns that group into one squash. Do the same before
                // presenting the standalone message editor so non-contiguous
                // selection does not silently lose its intended semantics.
                let selectedTodoIDs = Set(sortedIndexes.map { todo.items[$0].commitId })
                let selectedItems = sortedIndexes.map { todo.items[$0] }
                let insertionIndex = sortedIndexes[0]
                let remainingItems = todo.items.filter { !selectedTodoIDs.contains($0.commitId) }
                var reorderedItems = remainingItems
                reorderedItems.insert(contentsOf: selectedItems, at: insertionIndex)
                todo.items = reorderedItems
                preparedSquashIndexes = Array(insertionIndex..<(insertionIndex + selectedItems.count))
                squashCommits = selectedItems.compactMap { item in
                    let todoID = item.commitId
                    return selected.first { commit in
                        commit.id == todoID
                            || todoID.hasPrefix(commit.id)
                            || commit.id.hasPrefix(todoID)
                    }
                }
                guard squashCommits.count == selectedItems.count else {
                    throw NSError(
                        domain: "Arbor.Git",
                        code: 8,
                        userInfo: [NSLocalizedDescriptionKey: "The selected commits could not be loaded for the Squash message."]
                    )
                }
            } else if action == .reword {
                preparedSquashIndexes = sortedIndexes
                squashCommits = []
                for index in sortedIndexes {
                    todo.items[index].action = .reword
                    // The todo editor exposes each message field so every
                    // selected commit can be changed independently before
                    // the destructive operation starts.
                    todo.items[index].message = todo.items[index].summary
                }
            } else {
                preparedSquashIndexes = sortedIndexes
                squashCommits = []
                for index in sortedIndexes {
                    todo.items[index].action = .drop
                }
            }
            let preparedItems = todo.items
            let squashSummaries = squashCommits.map(\.summary)
            let squashMessage = prettySquashMessage(squashCommits)
            await MainActor.run {
                self.rebaseTodoOnto = onto
                self.rebaseTodoItems = preparedItems
                self.rebaseTodoPreserveMerges = false
                self.rebaseTodoRoot = rootRebase
                if action == .squash {
                    self.logSquashIndexes = preparedSquashIndexes
                    self.logSquashSummaries = squashSummaries
                    self.logSquashMessage = squashMessage
                    self.feedbackCenter.success(
                        "Squash message ready",
                        detail: "Edit the combined message before rewriting \(squashSummaries.count) commits."
                    )
                    self.showLogSquashDialog = true
                } else {
                    self.showRebaseTodoEditor = true
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Prepare batch rewrite failed",
                    detail: errorMessage(error),
                    nextStep: action == .squash
                        ? "Select linear commits on the current branch, then retry."
                        : "Select linear commits from the current branch, then retry."
                )
            }
        }
    }
}

/// Continue the IntelliJ-style warning shown before a multi-selection that
/// includes the initial commit enters the root todo editor.
func confirmInitialCommitRewrite() {
    guard let pending = pendingInitialCommitRewrite else { return }
    pendingInitialCommitRewrite = nil
    if pending.commits.count == 1,
       let commit = pending.commits.first,
       pending.action == .drop {
        rewriteCommitFromLog(commit, action: pending.action, initialCommitConfirmed: true)
    } else {
        rewriteSelectedCommitsFromLog(
            pending.commits,
            action: pending.action,
            initialCommitConfirmed: true
        )
    }
}

/// Convert the confirmed Squash message into one reword root followed by
/// fixups. The resulting tree is identical to pick+squash, while the root
/// keeps exactly the message edited in the IntelliJ-style dialog.
func submitLogSquash() {
    let message = logSquashMessage.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !message.isEmpty else {
        feedbackCenter.warning(
            "Commit message required",
            detail: "A squashed commit must keep a non-empty message.",
            nextStep: "Enter a combined commit message and retry."
        )
        return
    }
    let indexes = logSquashIndexes.sorted()
    guard let first = indexes.first,
          indexes.count >= 2,
          indexes.allSatisfy({ $0 >= 0 && $0 < rebaseTodoItems.count }) else {
        feedbackCenter.error(
            "Squash unavailable",
            detail: "The selected commits are no longer available in the prepared history range.",
            nextStep: "Refresh the Log and select the commits again."
        )
        showLogSquashDialog = false
        return
    }
    rebaseTodoItems[first].action = .reword
    rebaseTodoItems[first].message = message
    for index in indexes.dropFirst() {
        rebaseTodoItems[index].action = .fixup
        rebaseTodoItems[index].message = nil
    }
    showLogSquashDialog = false
    logSquashIndexes = []
    logSquashSummaries = []
    startTodoRebase()
}

/// Capture Git's complete native todo for the current structured rebase
/// draft. This is the IntelliJ fallback for label/reset/merge, exec, break,
/// update-ref, and any future command that is not a structured row action.
func prepareRawRebaseTodoEditor() {
    guard !isLogAggregate, let repo = logRepository else { return }
    let onto = rebaseTodoOnto
    let preserve = rebaseTodoPreserveMerges
    let root = rebaseTodoRoot
    showRebaseTodoEditor = false
    let cancel = GitCancelHandle()
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Prepare Native Rebase Todo", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let raw = try repo.rebaseRawTodoWithOptionsAndPolicyAndCancel(
                onto: onto,
                preserveMerges: preserve,
                autoSquash: false,
                keepEmpty: false,
                updateRefs: false,
                root: root,
                savePolicy: projectSavePolicy,
                cancel: cancel
            )
            await MainActor.run {
                self.rebaseRawTodoText = raw
                self.showRawRebaseTodoEditor = true
                self.feedbackCenter.success(
                    "Native rebase todo ready",
                    detail: "Git control rows remain editable as text."
                )
            }
        } catch {
            await MainActor.run {
                if case .Cancelled = error as? EngineError {
                    self.operationFeedback = "Native rebase todo preparation cancelled; local changes were restored"
                    self.feedbackCenter.warning(
                        "Native rebase todo preparation cancelled",
                        detail: self.operationFeedback ?? "Local changes were restored",
                        nextStep: "Edit the native todo again when the repository is ready."
                    )
                    return
                }
                self.feedbackCenter.error(
                    "Prepare native rebase todo failed",
                    detail: errorMessage(error),
                    nextStep: "The repository must be free of another Git operation; retry after refreshing."
                )
            }
        }
    }
}

/// 按编辑后的 todo 启动 rebase（顺序与 action 为最终权威）。
func startTodoRebase() {
    guard !isLogAggregate else {
        feedbackCenter.warning(
            "Interactive Rebase unavailable in aggregate Log",
            detail: "Rebase edits must be scoped to one Git root.",
            nextStep: "Navigate to one repository before applying the edited todo list."
        )
        return
    }
    guard let repo = logRepository else { return }
    let onto = rebaseTodoOnto
    let todo = RebaseTodo(onto: onto, items: rebaseTodoItems)
    let preserve = rebaseTodoPreserveMerges
    let root = rebaseTodoRoot
    let repositoryPath = repo.workdir() ?? ""
    let useInMemory = shouldUseInMemoryCommitEditing(
        settingEnabled: GitInMemoryCommitEditingSettings.isEnabled(),
        items: rebaseTodoItems,
        preserveMerges: preserve
    )
    let nativeActions = rebaseTodoItems.map { item -> RebaseAction in
        switch item.action {
        case .pick:
            return .pick
        case .drop:
            return .drop
        case .reword:
            return .reword(message: item.message ?? item.summary)
        case .squash:
            if let message = item.message?.trimmingCharacters(in: .whitespacesAndNewlines),
               !message.isEmpty {
                return .squashWithMessage(message: message)
            }
            return .squash
        case .fixup:
            return .fixup
        case .edit:
            return .edit
        }
    }
    rebaseUndoSeed = nil
    rebaseUndoTarget = nil
    clearRebaseUndoSeed(repositoryPath: repositoryPath)
    let cancel = GitCancelHandle()
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Start Interactive Rebase", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let branch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name
            let initialHead = branch.flatMap { try? repo.revisionCommitId(revision: $0) }
            let seed = initialHead.flatMap { initialHead in
                branch.map {
                    RebaseUndoSeed(
                        repositoryPath: repositoryPath,
                        branch: $0,
                        initialHead: initialHead,
                        updateRefs: false,
                        protectionCommitID: root
                            ? nil
                            : rebaseUndoProtectionCommitBeforeOperation(
                                repo: repo,
                                initialHead: initialHead,
                                onto: onto
                            )
                    )
                }
            }
            if let seed {
                saveRebaseUndoSeed(seed)
            }
            let runNativeRebase: () throws -> RebaseOutcome = {
                if let branch {
                    return try repo.rebaseBranchWithAdvancedOptionsAndPolicyAndCancel(
                        onto: onto,
                        branch: branch,
                        actions: nativeActions,
                        preserveMerges: preserve,
                        autoSquash: false,
                        keepEmpty: false,
                        updateRefs: false,
                        root: root,
                        savePolicy: projectSavePolicy,
                        cancel: cancel
                    )
                }
                return try repo.rebaseWithAdvancedOptionsAndPolicyAndCancel(
                    onto: onto,
                    actions: nativeActions,
                    preserveMerges: preserve,
                    autoSquash: false,
                    keepEmpty: false,
                    updateRefs: false,
                    root: root,
                    savePolicy: projectSavePolicy,
                    cancel: cancel
                )
            }
            let outcome: RebaseOutcome
            if useInMemory {
                let inMemoryOutcome: RebaseOutcome = if root {
                    try repo.rebaseRootWithTodoAndPolicyAndCancel(
                        todo: todo,
                        preserveMerges: preserve,
                        savePolicy: projectSavePolicy,
                        cancel: cancel
                    )
                } else {
                    try repo.rebaseWithTodoAndPolicyAndCancel(
                        onto: onto,
                        todo: todo,
                        preserveMerges: preserve,
                        savePolicy: projectSavePolicy,
                        cancel: cancel
                    )
                }
                if inMemoryOutcome.paused, inMemoryOutcome.pauseReason == .conflict {
                    // The reference implementation discards partial object-level
                    // progress and retries the complete native todo. Abort first:
                    // it restores the original HEAD and the saved local scene,
                    // after which the native runner preserves that scene again.
                    try repo.rebaseAbort()
                    outcome = try runNativeRebase()
                } else {
                    outcome = inMemoryOutcome
                }
            } else {
                outcome = try runNativeRebase()
            }
            let finalHead = seed.flatMap { try? repo.revisionCommitId(revision: $0.branch) }
            let currentBranch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name
            let undoTarget = rebaseUndoTargetAfterCompletion(
                seed: seed,
                currentBranch: currentBranch,
                finalHead: finalHead
            )
            await MainActor.run {
                self.showRebaseTodoEditor = false
                self.rebaseTodoRoot = false
                if outcome.paused {
                    self.rebaseUndoSeed = seed
                    self.rebaseUndoTarget = nil
                    if let seed {
                        saveRebaseUndoSeed(seed)
                    }
                    self.operationFeedback = outcome.pauseReason == .conflict
                        ? "Rebase 冲突暂停：\(outcome.conflicts.count) 个文件"
                        : "Rebase 在 edit 暂停"
                    self.showMergeRevisionsDialog = true
                } else {
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = undoTarget
                    clearRebaseUndoSeed(repositoryPath: repositoryPath)
                    if let undoTarget {
                        self.feedbackCenter.success(
                            "Rebase completed",
                            detail: String(outcome.headId.prefix(7)),
                            additionalActions: [self.rebaseUndoFeedbackAction(for: undoTarget)],
                            notificationID: rebaseUndoNotificationID(repositoryPath: repositoryPath),
                            notificationGroup: .standard
                        )
                    } else {
                        self.feedbackCenter.success("Rebase completed", detail: String(outcome.headId.prefix(7)))
                    }
                }
                self.refreshAll(showFeedback: false)
            }
        } catch {
            if case .Cancelled = error as? EngineError {
                await MainActor.run {
                    self.operationFeedback = "Rebase 已取消；保存的本地现场未被丢弃"
                    self.feedbackCenter.warning(
                        "Rebase cancelled",
                        detail: self.operationFeedback ?? "保存的本地现场未被丢弃",
                        nextStep: "Check Saved Changes or Stash, restore any pending local scene, then retry.",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repositoryPath
                        ).map { [$0] } ?? []
                    )
                }
                return
            }
            await MainActor.run {
                if (try? repo.operationState())?.kind != .rebase {
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = nil
                    clearRebaseUndoSeed(repositoryPath: repositoryPath)
                }
                self.feedbackCenter.error(
                    "Rebase failed",
                    detail: errorMessage(error),
                    nextStep: "修正 todo 后重试，或 Abort。",
                    additionalActions: self.pendingSavedChangesFeedbackAction(
                        repo: repo,
                        rootPath: repositoryPath
                    ).map { [$0] } ?? []
                )
            }
        }
    }
}

/// Execute the text edited in Git's native todo format. The engine writes it
/// back through GIT_SEQUENCE_EDITOR and lets Git own every command's native
/// topology and pause semantics.
func startRawTodoRebase() {
    guard !isLogAggregate else {
        feedbackCenter.warning(
            "Interactive Rebase unavailable in aggregate Log",
            detail: "Native todo edits must be scoped to one Git root.",
            nextStep: "Navigate to one repository before applying the edited todo list."
        )
        return
    }
    guard let repo = logRepository else { return }
    let onto = rebaseTodoOnto
    let rawTodo = rebaseRawTodoText
    let preserve = rebaseTodoPreserveMerges
    let root = rebaseTodoRoot
    let repositoryPath = repo.workdir() ?? ""
    rebaseUndoSeed = nil
    rebaseUndoTarget = nil
    clearRebaseUndoSeed(repositoryPath: repositoryPath)
    let cancel = GitCancelHandle()
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Start Native Interactive Rebase", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        let messageMonitor = Task.detached(priority: .userInitiated) {
            var sawActiveRebase = false
            while !Task.isCancelled {
                let active = (try? repo.operationState())?.kind == .rebase
                sawActiveRebase = sawActiveRebase || active
                if let pending = try? repo.rebasePendingMessage() {
                    await MainActor.run {
                        guard !self.showRawRebaseMessageEditor else { return }
                        self.rawRebaseMessageRepository = repo
                        self.rawRebaseMessageText = pending
                        self.showRawRebaseMessageEditor = true
                    }
                }
                if sawActiveRebase && !active {
                    await MainActor.run {
                        guard (self.rawRebaseMessageRepository?.workdir() ?? "") == repositoryPath else { return }
                        self.showRawRebaseMessageEditor = false
                        self.rawRebaseMessageRepository = nil
                        self.rawRebaseMessageText = ""
                    }
                    break
                }
                try? await Task.sleep(nanoseconds: 100_000_000)
            }
        }
        do {
            let branch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name
            let initialHead = branch.flatMap { try? repo.revisionCommitId(revision: $0) }
            let seed = initialHead.flatMap { initialHead in
                branch.map {
                    RebaseUndoSeed(
                        repositoryPath: repositoryPath,
                        branch: $0,
                        initialHead: initialHead,
                        updateRefs: false,
                        protectionCommitID: rebaseUndoProtectionCommitBeforeOperation(
                            repo: repo,
                            initialHead: initialHead,
                            onto: onto
                        )
                    )
                }
            }
            if let seed {
                saveRebaseUndoSeed(seed)
            }
            let outcome = try repo.rebaseWithRawTodoAndPolicyAndCancel(
                onto: onto,
                rawTodo: rawTodo,
                preserveMerges: preserve,
                autoSquash: false,
                keepEmpty: false,
                updateRefs: false,
                root: root,
                savePolicy: projectSavePolicy,
                cancel: cancel
            )
            if !outcome.paused {
                messageMonitor.cancel()
            }
            let finalHead = seed.flatMap { try? repo.revisionCommitId(revision: $0.branch) }
            let currentBranch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name
            let undoTarget = rebaseUndoTargetAfterCompletion(
                seed: seed,
                currentBranch: currentBranch,
                finalHead: finalHead
            )
            await MainActor.run {
                self.showRawRebaseTodoEditor = false
                self.rebaseRawTodoText = ""
                self.rebaseTodoRoot = false
                if outcome.paused {
                    self.rebaseUndoSeed = seed
                    self.rebaseUndoTarget = nil
                    if let seed {
                        saveRebaseUndoSeed(seed)
                    }
                    self.operationFeedback = outcome.pauseReason == .conflict
                        ? "Native rebase conflict paused: \(outcome.conflicts.count) files"
                        : "Native rebase paused; resolve the operation before continuing"
                    self.showMergeRevisionsDialog = true
                } else {
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = undoTarget
                    clearRebaseUndoSeed(repositoryPath: repositoryPath)
                    if let undoTarget {
                        self.feedbackCenter.success(
                            "Rebase completed",
                            detail: String(outcome.headId.prefix(7)),
                            additionalActions: [self.rebaseUndoFeedbackAction(for: undoTarget)],
                            notificationID: rebaseUndoNotificationID(repositoryPath: repositoryPath),
                            notificationGroup: .standard
                        )
                    } else {
                        self.feedbackCenter.success(
                            "Rebase completed",
                            detail: String(outcome.headId.prefix(7))
                        )
                    }
                }
                self.refreshAll(showFeedback: false)
            }
        } catch {
            messageMonitor.cancel()
            await MainActor.run {
                if case .Cancelled = error as? EngineError {
                    self.operationFeedback = "Native rebase cancelled; saved local changes were not discarded"
                    self.feedbackCenter.warning(
                        "Native rebase cancelled",
                        detail: self.operationFeedback ?? "Saved local changes were not discarded",
                        nextStep: "Continue or abort the native rebase, then restore Saved Changes or Stash if it remains pending.",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repositoryPath
                        ).map { [$0] } ?? []
                    )
                    return
                }
                if (try? repo.operationState())?.kind != .rebase {
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = nil
                    clearRebaseUndoSeed(repositoryPath: repositoryPath)
                }
                self.feedbackCenter.error(
                    "Native rebase failed",
                    detail: errorMessage(error),
                    nextStep: "Review the Git todo syntax and operation state, then retry or abort.",
                    additionalActions: self.pendingSavedChangesFeedbackAction(
                        repo: repo,
                        rootPath: repositoryPath
                    ).map { [$0] } ?? []
                )
            }
        }
    }
}

/// Complete the commit-message request made by Git's native GIT_EDITOR.
func submitRawRebaseMessage() {
    guard let repo = rawRebaseMessageRepository else { return }
    let message = rawRebaseMessageText
    guard !message.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        feedbackCenter.warning(
            "Commit message required",
            detail: "A reworded or squashed commit must keep a non-empty message.",
            nextStep: "Enter a commit title and save the message."
        )
        return
    }
    do {
        try repo.rebaseSetPendingMessage(message: message)
        showRawRebaseMessageEditor = false
        rawRebaseMessageRepository = nil
        rawRebaseMessageText = ""
    } catch {
        feedbackCenter.error(
            "Save rebase message failed",
            detail: errorMessage(error),
            nextStep: "Retry while the native rebase message editor is waiting."
        )
    }
}

/// Cancel the native message editor by returning the same non-zero result
/// Git would receive from an IntelliJ unstructured-editor cancellation.
func cancelRawRebaseMessage() {
    guard let repo = rawRebaseMessageRepository else { return }
    do {
        try repo.rebaseCancelPendingMessage()
        showRawRebaseMessageEditor = false
        rawRebaseMessageRepository = nil
        rawRebaseMessageText = ""
    } catch {
        feedbackCenter.error(
            "Cancel rebase message failed",
            detail: errorMessage(error),
            nextStep: "The rebase may already have completed; refresh the operation state."
        )
    }
}

/// BRANCH-001：Recent 分组检出（recent_branches 数据源）。
func checkoutRecentBranch(_ name: String) {
    // Keep Recent and Local Branches on the same checkout state machine so a
    // dirty-worktree checkout cannot bypass Smart/Force/Cancel recovery.
    switchBranch(name)
}

/// BRANCH-001：Tag 检出（detached HEAD）。
func checkoutTag(_ name: String) {
    guard let repo else { return }
    beginFeedbackOperation("Checkout tag")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.checkoutDetached(commitId: name)
            await MainActor.run { self.feedbackCenter.success("Checked out tag", detail: name) }
            await MainActor.run { self.refreshAll(showFeedback: false) }
        } catch {
            let detail = errorMessage(error)
            await MainActor.run {
                self.presentCheckoutRecovery(
                    repo: repo,
                    name: name,
                    detail: detail,
                    onSmart: { self.smartCheckoutDetached(repo: repo, revision: name) },
                    onForce: { self.forceCheckoutDetached(repo: repo, revision: name) }
                )
            }
        }
    }
}

/// BRANCH-001：Checkout 并同步远程（update = merge,rebase = --rebase）。
func checkoutAndUpdate(_ name: String, rebase: Bool) {
    guard let repo else { return }
    if rebase {
        checkoutAndRebaseOntoCurrent(repo: repo, name: name)
        return
    }
    guard let upstream = checkoutAndUpdateUpstream(
        branch: name,
        syncStatuses: syncStatuses
    ) else {
        feedbackCenter.warning(
            "Checkout and Update unavailable",
            detail: "The branch no longer has a valid tracking branch.",
            nextStep: "Refresh Git State, then retry Checkout and Update."
        )
        return
    }
    beginFeedbackOperation("Checkout and update")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.switchBranch(name: name)
            await MainActor.run {
                self.finishCheckoutAndUpdate(
                    repo: repo,
                    name: name,
                    upstream: upstream,
                    rebase: rebase
                )
            }
        } catch {
            let detail = errorMessage(error)
            await MainActor.run {
                self.presentCheckoutRecovery(
                    repo: repo,
                    name: name,
                    detail: detail,
                    onSmart: {
                        self.smartCheckoutBranch(repo: repo, name: name) {
                            self.finishCheckoutAndUpdate(
                                repo: repo,
                                name: name,
                                upstream: upstream,
                                rebase: rebase
                            )
                        }
                    },
                    onForce: {
                        self.forceCheckoutBranch(repo: repo, name: name) {
                            self.finishCheckoutAndUpdate(
                                repo: repo,
                                name: name,
                                upstream: upstream,
                                rebase: rebase
                            )
                        }
                    }
                )
            }
        }
    }
}

private func finishCheckoutAndUpdate(
    repo: Repository,
    name: String,
    upstream: String?,
    rebase: Bool
) {
    guard let upstream, upstream.contains("/") else {
        feedbackCenter.success("Checked out and updated", detail: name)
        refreshAll(showFeedback: false)
        loadRepoData()
        return
    }

    beginFeedbackOperation("Checkout and Update")
    pullAfterCheckout(
        repo: repo,
        upstream: upstream,
        onComplete: { self.feedbackCenter.success("Checked out and updated", detail: name) }
    )
}

/// Smart Checkout restores the user's local changes after switching branches.
/// Inspect the repository again before Update; otherwise a clean checkout
/// followed by a successful Smart restore would make pull reject the restored
/// worktree instead of entering the normal stash/pull/pop flow.
private func pullAfterCheckout(
    repo: Repository,
    upstream: String,
    onComplete: @escaping () -> Void
) {
    Task.detached(priority: .userInitiated) {
        let dirty = (try? repo.status())?.contains { entry in
            entry.staged != .unchanged
                || (entry.unstaged != .unchanged && entry.unstaged != .ignored)
        } == true
        await MainActor.run {
            if dirty {
                self.stashAndPull(
                    remote: nil,
                    remoteBranch: upstream,
                    rebase: false,
                    onComplete: onComplete
                )
            } else {
                self.runPull(
                    remote: nil,
                    remoteBranch: upstream,
                    rebase: false,
                    restoreStash: false,
                    onComplete: onComplete
                )
            }
        }
    }
}

/// IntelliJ 的 Checkout with Rebase：将选中的本地分支 rebase 到当前分支，
/// 而不是切换后 pull 它自己的 upstream。引擎使用 --autostash，冲突时留下
/// system rebase 状态，由统一 Continue/Skip/Abort 工作台接管。
private func checkoutAndRebaseOntoCurrent(repo: Repository, name: String) {
    rebaseUndoTarget = nil
    rebaseUndoSeed = nil
    let currentBranch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name
    let seed = makeRebaseUndoSeed(repo: repo, branch: name, onto: currentBranch)
    if let seed {
        saveRebaseUndoSeed(seed)
        rebaseUndoSeed = seed
    }
    let cancel = GitCancelHandle()
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Checkout with Rebase", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            try repo.rebaseBranchOnCurrentWithPolicyAndCancel(
                branch: name,
                savePolicy: projectSavePolicy,
                cancel: cancel
            )
            await MainActor.run {
                self.rebaseUndoSeed = nil
                if let seed {
                    clearRebaseUndoSeed(repositoryPath: seed.repositoryPath)
                }
                self.feedbackCenter.success("Checked out and rebased", detail: name)
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            if case .Cancelled = error as? EngineError {
                await MainActor.run {
                    self.feedbackCenter.warning(
                        "Checkout with Rebase cancelled",
                        detail: "The saved local scene for \(name) was not discarded.",
                        nextStep: "Check Saved Changes or Stash, restore any pending local scene, then retry.",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: seed?.repositoryPath ?? repo.workdir()
                        ).map { [$0] } ?? []
                    )
                }
                return
            }
            let status = (try? repo.status()) ?? []
            let state = try? repo.operationState()
            let firstConflict = status.first {
                $0.staged == .conflicted || $0.unstaged == .conflicted
            }?.path
            await MainActor.run {
                if state?.kind == .rebase {
                    if let seed {
                        self.rebaseUndoSeed = seed
                        saveRebaseUndoSeed(seed)
                    }
                    self.entries = status
                    self.operationState = state
                    self.mergeInProgress = true
                    self.mergeInitialPath = firstConflict
                    self.showMergeRevisionsDialog = true
                    self.feedbackCenter.warning(
                        "Checkout with Rebase paused",
                        detail: errorMessage(error),
                        nextStep: "Resolve conflicts, then Continue or Abort the rebase.",
                        additionalActions: [
                            seed.map {
                                persistedRebaseRecoveryAction(rootPath: $0.repositoryPath, branch: $0.branch)
                            },
                            self.pendingSavedChangesFeedbackAction(
                                repo: repo,
                                rootPath: seed?.repositoryPath ?? repo.workdir()
                            )
                        ].compactMap { $0 },
                        notificationID: seed.map { rebaseRecoveryNotificationID(repositoryPath: $0.repositoryPath) }
                    )
                } else {
                    self.rebaseUndoSeed = nil
                    if let seed {
                        clearRebaseUndoSeed(repositoryPath: seed.repositoryPath)
                    }
                    self.feedbackCenter.error(
                        "Checkout with Rebase failed",
                        detail: errorMessage(error),
                        nextStep: "检查目标分支与当前仓库状态后重试。",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: seed?.repositoryPath ?? repo.workdir()
                        ).map { [$0] } ?? []
                    )
                }
                self.refreshAll(showFeedback: false)
            }
        }
    }
}

/// Phase 5：在文件编辑器中打开 .gitignore（不存在则创建）。
func editGitignore() {
    guard let repo, let workdir = repo.workdir() else { return }
    let path = URL(fileURLWithPath: workdir).appendingPathComponent(".gitignore").path
    if !FileManager.default.fileExists(atPath: path) {
        FileManager.default.createFile(atPath: path, contents: nil)
    }
    NSWorkspace.shared.open(URL(fileURLWithPath: path))
}

/// Open the repository-local exclude file without exposing Git internals in
/// the view layer. This is the companion to the existing Exclude action.
func editGitExclude() {
    guard let repo else { return }
    let path = repositoryGitExcludeURL(
        gitDirectory: URL(fileURLWithPath: repo.gitDir())
    )
    try? FileManager.default.createDirectory(at: path.deletingLastPathComponent(), withIntermediateDirectories: true)
    if !FileManager.default.fileExists(atPath: path.path) {
        FileManager.default.createFile(atPath: path.path, contents: nil)
    }
    NSWorkspace.shared.open(path)
}

/// Branch file comparison is an editor-style Changes Browser surface in
/// IntelliJ, not a mode switch that replaces the user's current history.
func openTreeComparisonTab(
    rootPath: String,
    first: String,
    second: String,
    comparesWithWorkingTree: Bool
) {
    let tab = makeTreeComparisonLogTab(
        first: first,
        second: second,
        rootPath: rootPath,
        comparesWithWorkingTree: comparesWithWorkingTree
    )
    toolWindowMode = .log
    toolWindowExpanded = true
    projectPanelExpanded = false
    showBranchesPopover = false
    saveCurrentLogTab()
    if let existing = logTabs.first(where: {
        $0.viewMode == .compare
            && $0.rootPath == tab.rootPath
            && $0.compareRepositoryPath == tab.compareRepositoryPath
            && $0.compareRevision1 == tab.compareRevision1
            && $0.compareRevision2 == tab.compareRevision2
            && $0.compareWithWorkingTree == tab.compareWithWorkingTree
    }) {
        if existing.id == currentLogTabID {
            applyLogTab(existing)
            loadActiveLogTab(existing)
        } else {
            switchLogTab(existing.id)
        }
        return
    }
    appendLogTabAndLoad(tab)
}

/// Compare Branches is an editor-style Log surface in IntelliJ, not a mode
/// switch that replaces the user's current history. Keep one tab per exact
/// root/range pair and let the normal Log tab lifecycle own persistence,
/// switching and close behavior.
func openBranchComparisonTab(rootPath: String, first: String, second: String) {
    let tab = makeBranchComparisonLogTab(
        first: first,
        second: second,
        rootPath: rootPath
    )
    toolWindowMode = .log
    toolWindowExpanded = true
    projectPanelExpanded = false
    showBranchesPopover = false
    saveCurrentLogTab()
    if let existing = logTabs.first(where: {
        $0.viewMode == .compareBranches
            && $0.rootPath == tab.rootPath
            && $0.compareRepositoryPath == tab.compareRepositoryPath
            && $0.compareRevision1 == tab.compareRevision1
            && $0.compareRevision2 == tab.compareRevision2
    }) {
        if existing.id == currentLogTabID {
            applyLogTab(existing)
            loadActiveLogTab(existing)
        } else {
            switchLogTab(existing.id)
        }
        return
    }
    appendLogTabAndLoad(tab)
}

private func openFileHistoryTab(path: String, startRevision: String, rootPath: String?) {
    let tab = makeFileHistoryLogTab(
        path: path,
        startRevision: startRevision,
        rootPath: rootPath
    )
    saveCurrentLogTab()
    if let existing = logTabs.first(where: {
        $0.historyPath == tab.historyPath
            && $0.rootPath == tab.rootPath
            && $0.startRevision == tab.startRevision
            && $0.startRevisions == tab.startRevisions
            && $0.pathFilter == tab.pathFilter
            && $0.pathSelections == tab.pathSelections
            && $0.follow
    }) {
        if existing.id == currentLogTabID {
            applyLogTab(existing)
            loadLog()
        } else {
            switchLogTab(existing.id)
        }
        return
    }
    appendLogTabAndLoad(tab)
}

/// HISTORY-001：File History 入口——打开独立 Log tab 并按路径过滤（follow renames）。
func showFileHistory(_ path: String, rootPath: String? = nil) {
    let normalizedPath = path.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedPath.isEmpty else { return }
    let historyRootPath = resolvedFileHistoryRootPath(
        preferredRootPath: rootPath,
        selectedCommitRootPath: selectedCommit?.repositoryPath,
        activeLogRootPath: logActiveRootPath,
        repositoryRootPath: repo?.workdir()
    )
    logAggregateBranchFilters = []
    logAggregateRevisionRanges = []
    logAggregateRootPaths = []
    logAggregateRepositories = [:]
    logAggregateLoadedCounts = [:]
    toolWindowMode = .log
    toolWindowExpanded = true
    // File History is a Log editor hand-off. The left workspace must return
    // to Commit/Stash immediately instead of leaving the Project tool window
    // expanded over the staging surface.
    projectPanelExpanded = false
    selection = nil
    fileSelection = nil
    selectionModePath = nil
    commitPreviewPath = nil
    commitPreviewVisible = false
    openFileHistoryTab(path: normalizedPath, startRevision: "HEAD", rootPath: historyRootPath)
}

/// Vcs.ShowHistoryForRevision: open the file history rooted at the selected
/// revision instead of silently starting from the current branch tip.
func showFileHistoryForRevision(_ commit: CommitInfo, _ path: String) {
    let normalizedPath = path.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedPath.isEmpty else { return }
    let historyRootPath = commit.repositoryPath
        ?? logActiveRootPath
        ?? repo?.workdir()
    logAggregateBranchFilters = []
    logAggregateRevisionRanges = []
    logAggregateRootPaths = []
    logAggregateRepositories = [:]
    logAggregateLoadedCounts = [:]
    toolWindowMode = .log
    toolWindowExpanded = true
    projectPanelExpanded = false
    selection = nil
    fileSelection = nil
    selectionModePath = nil
    commitPreviewPath = nil
    commitPreviewVisible = false
    openFileHistoryTab(
        path: normalizedPath,
        startRevision: commit.id,
        rootPath: historyRootPath
    )
}

/// REPO-001:发现项目下的所有 Git root(聚合视图数据源)。
func loadMultiRoots(onCompleted: (() -> Void)? = nil) {
    guard let projectPath else {
        onCompleted?()
        return
    }
    let requestedExternalRootPaths = externalLogWindow
        ? initialExternalLogRootPaths.map(canonicalExternalLogPath)
        : []
    Task.detached(priority: .userInitiated) {
        do {
            var roots = try discoverGitRoots(scanRoot: projectPath, maxDepth: nil)
            if !requestedExternalRootPaths.isEmpty {
                var knownRootPaths = Set(roots.map { canonicalExternalLogPath($0.path) })
                for requestedRootPath in requestedExternalRootPaths
                    where !knownRootPaths.contains(requestedRootPath) {
                    guard let requestedRoot = try? discoverGitRoots(
                        scanRoot: requestedRootPath,
                        maxDepth: 0
                    ).first(where: {
                        canonicalExternalLogPath($0.path) == requestedRootPath
                    }) else {
                        continue
                    }
                    roots.append(requestedRoot)
                    knownRootPaths.insert(requestedRootPath)
                }
            }
            let operationStates = roots.compactMap { root -> (String, OperationState)? in
                guard root.operation != nil,
                      let rootRepo = try? openRepository(path: root.path),
                      let state = try? rootRepo.operationState() else {
                    return nil
                }
                return (root.path, state)
            }
            if let override = GitExecutableSettings.projectOverride(for: projectPath) {
                let registeredRoots = GitExecutableSettings.registeredRoots(
                    projectPath: projectPath,
                    repositoryRoot: nil,
                    discoveredRoots: roots.map(\.path)
                )
                _ = try? setProjectGitExecutable(
                    projectPath: projectPath,
                    rootPaths: registeredRoots,
                    path: override
                )
            } else {
                clearProjectGitExecutable(projectPath: projectPath)
            }
            var snapshots = try listMultiRootBranches(scanRoot: projectPath)
            if !requestedExternalRootPaths.isEmpty {
                let knownSnapshotPaths = Set(snapshots.map {
                    canonicalExternalLogPath($0.rootPath)
                })
                for requestedRootPath in requestedExternalRootPaths
                    where !knownSnapshotPaths.contains(requestedRootPath) {
                    if let requestedSnapshot = try? listMultiRootBranches(
                        scanRoot: requestedRootPath
                    ).first(where: {
                        canonicalExternalLogPath($0.rootPath) == requestedRootPath
                    }) {
                        snapshots.append(requestedSnapshot)
                    }
                }
            }
            let conflictGroups = roots.compactMap { root -> MultiRootConflictGroup? in
                guard let rootRepo = try? openRepository(path: root.path),
                      let entries = try? rootRepo.status() else { return nil }
                let paths = entries
                    .filter { $0.staged == .conflicted || $0.unstaged == .conflicted }
                    .map(\.path)
                    .sorted()
                guard !paths.isEmpty else { return nil }
                return MultiRootConflictGroup(
                    rootPath: root.path,
                    displayName: root.displayName,
                    relativePath: root.relativePath,
                    operation: root.operation,
                    paths: paths
                )
            }
            let updateStashRoots = Set(
                snapshots.compactMap { snapshot in
                    snapshot.stashes.contains(where: { isArborUpdateLocalChangesName($0.message) })
                        || snapshot.shelves.contains(where: { isArborTemporaryShelfName($0.name) })
                        ? snapshot.rootPath
                        : nil
                }
            )
            let rootsSnapshot = roots
            let snapshotsSnapshot = snapshots
            await MainActor.run {
                guard !(self.externalLogWindow && self.externalLogSessionDisposed) else { return }
                let externalLogNeedsInitialLoad = self.externalLogWindow
                    && !self.externalLogAggregateLoadStarted
                    && !rootsSnapshot.isEmpty
                let externalLogSelection = reconciledExternalLogRootSelection(
                    availableRoots: rootsSnapshot.map(\.path),
                    selectedRoots: self.logAggregateRootPaths,
                    initialized: self.externalLogRootSelectionInitialized
                )
                let externalLogSelectionChanged = self.externalLogWindow
                    && externalLogSelection != self.logAggregateRootPaths
                self.multiRoots = rootsSnapshot
                self.multiRootBranchSnapshots = snapshotsSnapshot
                self.remoteProtectedBranchPatternsByRoot = Dictionary(
                    uniqueKeysWithValues: snapshotsSnapshot.compactMap { snapshot -> (String, [String])? in
                        guard !self.hostingRepositories(for: snapshot.remotes).isEmpty else {
                            return nil
                        }
                        let key = canonicalExternalLogPath(snapshot.rootPath)
                        return (key, GitProtectedBranchRules.loadRemotePatterns(for: key))
                    }
                )
                if let primaryPath = self.projectPath {
                    let primaryKey = canonicalExternalLogPath(primaryPath)
                    self.remoteProtectedBranchPatterns =
                        self.remoteProtectedBranchPatternsByRoot[primaryKey] ?? []
                }
                self.multiRootConflictGroups = conflictGroups
                if let selectedShelfRoot = self.shelfRootPath,
                   !rootsSnapshot.contains(where: {
                       canonicalExternalLogPath($0.path)
                           == canonicalExternalLogPath(selectedShelfRoot)
                   }) {
                    self.shelfRootLoadGeneration += 1
                    self.shelfRootPath = nil
                    self.shelfRootLoading = false
                    self.shelfRootRepository = nil
                    self.shelfRootError = nil
                    self.shelfRootSnapshots.removeValue(
                        forKey: canonicalExternalLogPath(selectedShelfRoot)
                    )
                    self.shelfPreviewName = nil
                    self.shelfPreviewRootPath = nil
                    self.shelfPreviewText = nil
                    self.shelfPreviewIsDeleted = false
                    self.showShelfPreview = false
                }
                if self.externalLogWindow {
                    self.logAggregateRootPaths = externalLogSelection
                    self.externalLogRootSelectionInitialized = !externalLogSelection.isEmpty
                }
                let previousOperationRoots = Set(
                    self.operationRecoveryNotificationFingerprints.keys
                )
                let activeOperationRoots = Set(operationStates.map {
                    operationRecoveryNotificationRootKey($0.0)
                })
                for rootKey in previousOperationRoots.subtracting(activeOperationRoots) {
                    self.feedbackCenter.expire(
                        notificationID: operationRecoveryNotificationID(rootPath: rootKey)
                    )
                }
                self.operationRecoveryNotificationFingerprints =
                    self.operationRecoveryNotificationFingerprints.filter {
                        activeOperationRoots.contains($0.key)
                    }
                for (rootPath, state) in operationStates {
                    self.publishOperationRecoveryNoticeIfNeeded(
                        state: state,
                        rootPath: rootPath
                    )
                }
                if self.logBranchesShowOnlyMy {
                    self.refreshLogMyBranches()
                }
                if let activeRootPath = self.logActiveRootPath {
                    if snapshotsSnapshot.count <= 1
                        || !snapshotsSnapshot.contains(where: { $0.rootPath == activeRootPath }) {
                        self.logActiveRootPath = nil
                        self.logActiveRepo = nil
                        self.logActiveBranches = []
                        self.logActiveRemoteBranches = []
                        self.logActiveRemotes = []
                    } else if let activeSnapshot = snapshotsSnapshot.first(
                        where: { $0.rootPath == activeRootPath }
                    ) {
                        // Keep the Log context tied to the refreshed root while
                        // retaining the live Repository for operations such as
                        // remote URL lookup and credential-aware actions.
                        self.logActiveBranches = activeSnapshot.branches
                        self.logActiveRemoteBranches = activeSnapshot.remoteBranches
                        if let activeRepo = self.logActiveRepo {
                            self.logActiveRemotes = (try? activeRepo.remoteList()) ?? self.logActiveRemotes
                        }
                    }
                }
                if self.logAggregateBranchFilters.contains(where: { filter in
                    !snapshotsSnapshot.contains(where: { $0.rootPath == filter.rootPath })
                }) {
                    self.logAggregateBranchFilters = []
                    self.logAggregateRevisionRanges = []
                    self.logAggregateRepositories = [:]
                    self.logAggregateLoadedCounts = [:]
                    self.logEntries = []
                    self.logSelection = nil
                    self.logSelectedIDs = []
                }
                self.applyProjectGitExecutableOverride(
                    for: projectPath,
                    roots: rootsSnapshot.map(\.path)
                )
                // Rebuild this state from Git's stash stack on every refresh.
                // That makes a temporary Update stash discoverable after the
                // app is reopened instead of relying on in-memory bookkeeping.
                self.multiRootUpdateStashedRoots = updateStashRoots
                self.scanPendingApplyRestores()
                if externalLogSelectionChanged {
                    if self.logAggregateRootPaths.isEmpty {
                        self.logEntries = []
                        self.logSelection = nil
                        self.logSelectedIDs = []
                    } else {
                        self.externalLogAggregateLoadStarted = true
                        if self.logViewMode == .command {
                            self.runLogCommand()
                        } else {
                            self.loadLog()
                        }
                    }
                } else if externalLogNeedsInitialLoad {
                    self.externalLogAggregateLoadStarted = true
                    if self.logViewMode == .command {
                        self.runLogCommand()
                    } else {
                        self.loadLog()
                    }
                }
                onCompleted?()
            }
        } catch {
            await MainActor.run {
                self.multiRoots = []
                self.multiRootBranchSnapshots = []
                self.multiRootConflictGroups = []
                self.multiRootUpdateStashedRoots = []
                self.shelfRootLoadGeneration += 1
                self.shelfRootPath = nil
                self.shelfRootSnapshots = [:]
                self.shelfRootRepository = nil
                self.shelfRootLoading = false
                self.shelfRootError = nil
                self.logActiveRootPath = nil
                self.logActiveRepo = nil
                self.logActiveBranches = []
                self.logActiveRemoteBranches = []
                self.logActiveRemotes = []
                self.logAggregateBranchFilters = []
                self.logAggregateRevisionRanges = []
                self.logAggregateRootPaths = []
                self.externalLogRootSelectionInitialized = false
                self.externalLogAggregateLoadStarted = false
                self.logAggregateRepositories = [:]
                self.logAggregateLoadedCounts = [:]
                onCompleted?()
            }
        }
    }
}

private func publishShelfSnapshot(
    rootPath: String,
    shelves: [ShelveInfo],
    deletedShelves: [ShelveInfo],
    changeLists: [ChangeListInfo]? = nil
) {
    let normalizedRootPath = canonicalExternalLogPath(rootPath)
    if shelfRootSelectionIsPrimary(
        selectedRootPath: normalizedRootPath,
        primaryRootPath: primaryShelfRootPath
    ) {
        self.shelves = shelves
        self.deletedShelves = deletedShelves
        if let changeLists {
            self.changeLists = changeLists
        }
    } else if activeShelfRootPath == normalizedRootPath {
        let previousChangeLists = shelfRootSnapshots[normalizedRootPath]?.changeLists ?? []
        shelfRootSnapshots[normalizedRootPath] = ShelfRootSnapshot(
            rootPath: normalizedRootPath,
            shelves: shelves,
            deletedShelves: deletedShelves,
            changeLists: changeLists ?? previousChangeLists
        )
    }
}

/// Select the repository whose Shelves are shown in the Commit workspace.
/// Secondary roots keep their own snapshot and repository so metadata-only
/// Shelf mutations cannot accidentally target the primary repository.
func setShelfRoot(_ rootPath: String) {
    let normalizedPath = canonicalExternalLogPath(rootPath)
    let primaryPath = primaryShelfRootPath
    guard availableShelfRoots.contains(where: {
        canonicalExternalLogPath($0.path) == normalizedPath
    }) else {
        return
    }

    shelfRootLoadGeneration += 1
    let generation = shelfRootLoadGeneration
    shelfRootError = nil
    shelfPreviewName = nil
    shelfPreviewRootPath = nil
    shelfPreviewText = nil
    shelfPreviewIsDeleted = false
    showShelfPreview = false

    if normalizedPath == primaryPath {
        shelfRootPath = nil
        shelfRootRepository = nil
        shelfRootLoading = false
        return
    }

    shelfRootPath = normalizedPath
    shelfRootRepository = nil
    shelfRootLoading = true
    if shelfRootSnapshots[normalizedPath] == nil,
       let snapshot = multiRootBranchSnapshots.first(where: {
           canonicalExternalLogPath($0.rootPath) == normalizedPath
       }) {
        shelfRootSnapshots[normalizedPath] = ShelfRootSnapshot(
            rootPath: normalizedPath,
            shelves: snapshot.shelves,
            deletedShelves: [],
            changeLists: []
        )
    }

    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: normalizedPath)
            let rootShelves = try rootRepo.shelveList()
            let rootDeletedShelves = (try? rootRepo.shelveDeletedList()) ?? []
            let rootChangeLists = (try? rootRepo.changelistList()) ?? []
            await MainActor.run {
                guard self.shelfRootLoadGeneration == generation,
                      self.activeShelfRootPath == normalizedPath else { return }
                self.shelfRootRepository = rootRepo
                self.shelfRootSnapshots[normalizedPath] = ShelfRootSnapshot(
                    rootPath: normalizedPath,
                    shelves: rootShelves,
                    deletedShelves: rootDeletedShelves,
                    changeLists: rootChangeLists
                )
                self.shelfRootLoading = false
            }
        } catch {
            await MainActor.run {
                guard self.shelfRootLoadGeneration == generation,
                      self.activeShelfRootPath == normalizedPath else { return }
                self.shelfRootRepository = nil
                self.shelfRootLoading = false
                self.shelfRootError = "Load Shelf for "
                    + normalizedPath
                    + " failed: "
                    + errorMessage(error)
            }
        }
    }
}

/// Change the root scope of an external Git Log window. Root selection is a
/// query scope, so changing it deliberately clears branch/range filters from
/// another Log action instead of silently combining incompatible scopes.
func setExternalLogRootSelection(_ rootPath: String, selected: Bool) {
    guard externalLogWindow else { return }
    let normalizedPath = canonicalExternalLogPath(rootPath)
    var next = logAggregateRootPaths
    if selected {
        next.insert(normalizedPath)
    } else {
        guard next.count > 1 else { return }
        next.remove(normalizedPath)
    }
    applyExternalLogRootSelection(next)
}

func selectAllExternalLogRoots() {
    applyExternalLogRootSelection(Set(multiRoots.map(\.path)))
}

func selectPrimaryExternalLogRoot() {
    guard let primaryPath = repo?.workdir() ?? projectPath else { return }
    let normalizedPrimaryPath = canonicalExternalLogPath(primaryPath)
    guard multiRoots.contains(where: {
        canonicalExternalLogPath($0.path) == normalizedPrimaryPath
    }) else { return }
    applyExternalLogRootSelection([normalizedPrimaryPath])
}

private func applyExternalLogRootSelection(_ requestedPaths: Set<String>) {
    guard externalLogWindow else { return }
    let availablePaths = normalizedLogRootPaths(multiRoots.map(\.path))
    let next = reconciledExternalLogRootSelection(
        availableRoots: availablePaths,
        selectedRoots: requestedPaths,
        initialized: true
    )
    guard !next.isEmpty, next != logAggregateRootPaths else { return }
    logAggregateBranchFilters = []
    logAggregateRevisionRanges = []
    logAggregateRootPaths = next
    logAggregateRepositories = [:]
    logAggregateLoadedCounts = [:]
    logSelection = nil
    logSelectedIDs = []
    logError = nil
    logViewMode = .graph
    loadLog()
}

/// Open the project-level Changes Browser without widening the write boundary
/// of the existing single-root commit workspace.
func openMultiRootCommitDialog(_ selectedChanges: [MultiRootChangeSelection]? = nil) {
    multiRootCommitSelectedPaths = selectedChanges
    multiRootCommitMessage = ""
    multiRootCommitRecentMessages = []
    multiRootCommitAmendMode = false
    multiRootCommitSkipHooks = skipHooks
    multiRootCommitAuthorName = identityAuthorName
    multiRootCommitAuthorEmail = identityAuthorEmail
    multiRootCommitCommitterName = identityCommitterName
    multiRootCommitCommitterEmail = identityCommitterEmail
    multiRootCommitSignOff = identitySignOff
    multiRootCommitCoAuthors = identityCoAuthors
    showMultiRootCommitDialog = true
    loadMultiRootChanges()
    loadMultiRootCommitMetadata(rootPaths: multiRoots.map(\.path))
}

/// Keep the project-level commit draft isolated from the persistent identity
/// settings sheet, while reflecting values saved there when it closes.
func syncMultiRootCommitIdentityDraftFromSettings() {
    multiRootCommitAuthorName = identityAuthorName
    multiRootCommitAuthorEmail = identityAuthorEmail
    multiRootCommitCommitterName = identityCommitterName
    multiRootCommitCommitterEmail = identityCommitterEmail
    multiRootCommitSignOff = identitySignOff
    multiRootCommitCoAuthors = identityCoAuthors
}

private func currentMultiRootCommitOptions() -> MultiRootCommitOptions {
    MultiRootCommitOptions(
        skipHooks: multiRootCommitSkipHooks,
        authorName: multiRootCommitAuthorName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? nil
            : multiRootCommitAuthorName.trimmingCharacters(in: .whitespacesAndNewlines),
        authorEmail: multiRootCommitAuthorEmail.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? nil
            : multiRootCommitAuthorEmail.trimmingCharacters(in: .whitespacesAndNewlines),
        committerName: multiRootCommitCommitterName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? nil
            : multiRootCommitCommitterName.trimmingCharacters(in: .whitespacesAndNewlines),
        committerEmail: multiRootCommitCommitterEmail.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? nil
            : multiRootCommitCommitterEmail.trimmingCharacters(in: .whitespacesAndNewlines),
        signOff: multiRootCommitSignOff,
        coAuthors: parseCoAuthors(multiRootCommitCoAuthors),
        amend: multiRootCommitAmendMode,
        runBeforeCommitChecks: true,
        beforeCommitCommands: beforeCommitCommands.map {
            MultiRootCommitCheck(command: $0.command, args: $0.args)
        }
    )
}

/// Commit a validated message only in the repositories explicitly selected by
/// the project-level Commit dialog. The engine returns a root-qualified
/// partial result, including clean and unselected roots as skipped entries.
func commitMultiRootSelectedRoots(_ rootPaths: [String], _ message: String) {
    let commitMessage = message.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !rootPaths.isEmpty, !commitMessage.isEmpty else { return }

    let options = currentMultiRootCommitOptions()

    performMultiRootCommit(
        rootPaths: rootPaths,
        message: commitMessage,
        options: options,
        allowForceRetry: true,
        pushAfterCommit: false
    )
}

/// Project-level Commit and Push follows IntelliJ's two-stage executor: the
/// selected roots are committed first, then only roots that actually created
/// a commit are offered to the shared Push options flow.
func commitAndPushMultiRootSelectedRoots(_ rootPaths: [String], _ message: String) {
    let commitMessage = message.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !rootPaths.isEmpty, !commitMessage.isEmpty else { return }

    let options = currentMultiRootCommitOptions()

    performMultiRootCommit(
        rootPaths: rootPaths,
        message: commitMessage,
        options: options,
        allowForceRetry: true,
        pushAfterCommit: true
    )
}

/// Commit only the root-qualified files selected in the project-level Changes
/// Browser. The selected rows are normalized before crossing the FFI boundary
/// so identical relative paths in different Git roots remain independent.
func commitMultiRootSelectedChanges(
    _ selectedChanges: [MultiRootChangeSelection],
    _ message: String
) {
    let commitMessage = message.trimmingCharacters(in: .whitespacesAndNewlines)
    let normalizedChanges = normalizedMultiRootCommitSelections(selectedChanges)
    guard !normalizedChanges.isEmpty, !commitMessage.isEmpty else { return }

    performMultiRootCommit(
        rootPaths: Array(Set(normalizedChanges.map(\.rootPath))).sorted(),
        message: commitMessage,
        options: currentMultiRootCommitOptions(),
        allowForceRetry: true,
        pushAfterCommit: false,
        selectedChanges: normalizedChanges
    )
}

/// Selected-file Commit and Push commits the root-qualified file set first,
/// then exposes Push options only for roots that actually produced a commit.
func commitAndPushMultiRootSelectedChanges(
    _ selectedChanges: [MultiRootChangeSelection],
    _ message: String
) {
    let commitMessage = message.trimmingCharacters(in: .whitespacesAndNewlines)
    let normalizedChanges = normalizedMultiRootCommitSelections(selectedChanges)
    guard !normalizedChanges.isEmpty, !commitMessage.isEmpty else { return }

    performMultiRootCommit(
        rootPaths: Array(Set(normalizedChanges.map(\.rootPath))).sorted(),
        message: commitMessage,
        options: currentMultiRootCommitOptions(),
        allowForceRetry: true,
        pushAfterCommit: true,
        selectedChanges: normalizedChanges
    )
}

/// Execute a project-level commit and, when a custom before-commit command
/// fails, offer IntelliJ's explicit Commit Anyway decision for only those
/// roots. Built-in identity/conflict checks remain enforced by Rust.
func performMultiRootCommit(
    rootPaths: [String],
    message: String,
    options requestedOptions: MultiRootCommitOptions,
    allowForceRetry: Bool,
    pushAfterCommit: Bool = false,
    priorPushRootPaths: [String] = [],
    selectedChanges: [MultiRootChangeSelection]? = nil
) {
    guard !rootPaths.isEmpty, !message.isEmpty, let projectPath else { return }
    var options = requestedOptions
    options.skipHooks = GitCommitHooksSettings.effectiveSkipHooks(
        requested: requestedOptions.skipHooks
    )
    showMultiRootCommitDialog = false
    multiRootRunning = true
    beginFeedbackOperation(
        "Multi-root commit",
        notificationID: multiRootRetryNotificationID(.commit)
    )
    rememberCommitAuthor(
        name: options.authorName ?? "",
        email: options.authorEmail ?? "",
        projectPath: projectPath
    )

    Task.detached(priority: .userInitiated) { [options] in
        do {
            let warningPresentations = try collectMultiRootCommitWarnings(
                rootPaths: rootPaths,
                selectedChanges: selectedChanges,
                projectPath: projectPath
            )
            var setCoreAutocrlf = false
            if !warningPresentations.isEmpty {
                let decision = await MainActor.run {
                    presentCommitWarningDecision(
                        warningPresentations,
                        projectPath: projectPath
                    )
                }
                guard decision.shouldContinue else {
                    await MainActor.run {
                        self.multiRootRunning = false
                        self.feedbackCenter.warning(
                            "Multi-root Commit cancelled",
                            detail: "Review the pre-commit warnings before committing.",
                            notificationID: self.multiRootRetryNotificationID(.commit)
                        )
                    }
                    return
                }
                setCoreAutocrlf = decision.setCoreAutocrlf
            }
            if setCoreAutocrlf, let rootPath = rootPaths.first,
               let warningRepository = try? openRepository(path: rootPath) {
                // Match IntelliJ's non-blocking CRLF fix: a config failure
                // leaves the warning enabled for the next commit, but must
                // not turn an otherwise valid commit into a failed commit.
                try? warningRepository.setGlobalCoreAutocrlf()
            }
            let results = try withArborPinentrySession {
                if let selectedChanges {
                    return try runMultiRootCommitSelectedPathsWithOptions(
                        scanRoot: projectPath,
                        selections: makeLiveMultiRootCommitSelections(selectedChanges),
                        commitMessage: message,
                        options: options
                    )
                }
                return try runMultiRootCommitWithOptions(
                    scanRoot: projectPath,
                    rootPaths: rootPaths,
                    commitMessage: message,
                    options: options
                )
            }
            let committedHeadIDs = Self.headCommitIDs(
                for: results
                    .filter { $0.success && !$0.skipped }
                    .map(\.rootPath)
            )
            await MainActor.run {
                let checkFailures = results.filter {
                    !$0.success && $0.message.contains("before-commit check")
                }
                let failedRootPaths = results.filter { !$0.success }.map(\.rootPath)
                let committedRootPaths = results
                    .filter { $0.success && !$0.skipped }
                    .map(\.rootPath)
                let pushRootPaths = Array(Set(priorPushRootPaths + committedRootPaths)).sorted()
                let retryAction = failedRootPaths.isEmpty
                    ? nil
                    : self.multiRootCommitRetryFeedbackAction(
                        rootPaths: failedRootPaths,
                        message: message,
                        options: options,
                        pushAfterCommit: pushAfterCommit,
                        pushRootPaths: pushAfterCommit ? pushRootPaths : [],
                        selectedChanges: selectedChanges?.filter {
                            failedRootPaths.contains($0.rootPath)
                        }
                    )
                let pushAction = pushAfterCommit && !pushRootPaths.isEmpty
                    ? self.multiRootCommitPushFeedbackAction(rootPaths: pushRootPaths)
                    : nil
                let signingActions = results.contains(where: {
                    !$0.success && gitCommitSigningFailureNeedsGPGConfiguration($0.message)
                }) ? [self.gpgAgentSettingsFeedbackAction()] : []
                let identityActions = results.contains(where: {
                    !$0.success && $0.message.localizedCaseInsensitiveContains("git identity missing")
                }) ? [self.identitySettingsFeedbackAction()] : []
                let rewordActions = committedRootPaths.compactMap { rootPath -> FeedbackAction? in
                    guard let commitID = committedHeadIDs[rootPath], !commitID.isEmpty else {
                        return nil
                    }
                    return self.commitRewordFeedbackAction(
                        rootPath: rootPath,
                        commitID: commitID
                    )
                }
                self.multiRootResults = results
                self.multiRootRunning = false
                if allowForceRetry && options.runBeforeCommitChecks && !checkFailures.isEmpty {
                    let alert = NSAlert()
                    alert.messageText = "Commit checks failed"
                    alert.informativeText = checkFailures.map {
                        "\($0.displayName): \($0.message)"
                    }.joined(separator: "\n")
                    alert.addButton(withTitle: "Commit Anyway")
                    alert.addButton(withTitle: "Cancel")
                    if alert.runModal() == .alertFirstButtonReturn {
                        var forcedOptions = options
                        forcedOptions.runBeforeCommitChecks = false
                        self.performMultiRootCommit(
                            rootPaths: checkFailures.map(\.rootPath),
                            message: message,
                            options: forcedOptions,
                            allowForceRetry: false,
                            pushAfterCommit: pushAfterCommit,
                            priorPushRootPaths: pushRootPaths,
                            selectedChanges: selectedChanges?.filter {
                                checkFailures.map(\.rootPath).contains($0.rootPath)
                            }
                        )
                    } else {
                        var additionalActions = rewordActions
                        if let retryAction {
                            additionalActions.append(retryAction)
                        }
                        if let pushAction {
                            additionalActions.append(pushAction)
                        }
                        self.feedbackCenter.warning(
                            "Commit checks failed",
                            detail: alert.informativeText,
                            nextStep: "Fix the checks or choose Commit Anyway for the failed roots.",
                            additionalActions: additionalActions,
                            notificationID: self.multiRootRetryNotificationID(.commit)
                        )
                        self.feedbackCenter.attachResultRows(
                            feedbackResultRows(from: results),
                            notificationID: self.multiRootRetryNotificationID(.commit)
                        )
                        if shouldAutomaticallyOpenMultiRootCommitPushOptions(
                            pushAfterCommit: pushAfterCommit,
                            pushRootPaths: pushRootPaths,
                            failedRootPaths: failedRootPaths
                        ) {
                            self.beginMultiRootCommitPush(rootPaths: pushRootPaths)
                        }
                        self.refreshAll(showFeedback: false)
                        self.loadMultiRoots(onCompleted: self.loadMultiRootChanges)
                    }
                    return
                }

                let committed = results.filter { $0.success && !$0.skipped }.count
                let failed = results.filter { !$0.success }.count
                let skipped = results.filter { $0.skipped }.count
                let detail = "\(committed) committed · \(failed) failed · \(skipped) skipped"
                var additionalActions = rewordActions
                additionalActions.append(contentsOf: signingActions)
                additionalActions.append(contentsOf: identityActions)
                if let retryAction {
                    additionalActions.append(retryAction)
                }
                if let pushAction {
                    additionalActions.append(pushAction)
                }
                if failed == 0 {
                    self.feedbackCenter.success(
                        "Multi-root commit complete",
                        detail: detail,
                        additionalActions: additionalActions,
                        notificationID: self.multiRootRetryNotificationID(.commit)
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Multi-root commit partially completed",
                        detail: detail,
                        nextStep: "Review the failed roots and retry the selected commit.",
                        additionalActions: additionalActions,
                        notificationID: self.multiRootRetryNotificationID(.commit)
                    )
                }
                self.feedbackCenter.attachResultRows(
                    feedbackResultRows(from: results),
                    notificationID: self.multiRootRetryNotificationID(.commit)
                )
                if shouldAutomaticallyOpenMultiRootCommitPushOptions(
                    pushAfterCommit: pushAfterCommit,
                    pushRootPaths: pushRootPaths,
                    failedRootPaths: failedRootPaths
                ) {
                    self.beginMultiRootCommitPush(rootPaths: pushRootPaths)
                }
                self.refreshAll(showFeedback: false)
                self.loadMultiRoots(onCompleted: self.loadMultiRootChanges)
            }
        } catch {
            await MainActor.run {
                self.multiRootRunning = false
                let retryAction = self.multiRootCommitRetryFeedbackAction(
                    rootPaths: rootPaths,
                    message: message,
                    options: options,
                    pushAfterCommit: pushAfterCommit,
                    pushRootPaths: pushAfterCommit ? priorPushRootPaths : [],
                    selectedChanges: selectedChanges
                )
                var additionalActions = [retryAction]
                let detail = errorMessage(error)
                if gitCommitSigningFailureNeedsGPGConfiguration(detail) {
                    additionalActions.append(self.gpgAgentSettingsFeedbackAction())
                }
                if pushAfterCommit && !priorPushRootPaths.isEmpty {
                    additionalActions.append(
                        self.multiRootCommitPushFeedbackAction(rootPaths: priorPushRootPaths)
                    )
                }
                if let engineError = error as? EngineError, case .Cancelled = engineError {
                    self.feedbackCenter.warning(
                        "Multi-root commit canceled",
                        detail: "The selected roots were kept for an explicit retry.",
                        additionalActions: additionalActions,
                        notificationID: self.multiRootRetryNotificationID(.commit),
                        notificationGroup: .important
                    )
                } else {
                    self.feedbackCenter.error(
                        "Multi-root commit failed",
                        detail: detail,
                        nextStep: "Check the commit message and selected roots, then retry.",
                        additionalActions: additionalActions,
                        notificationID: self.multiRootRetryNotificationID(.commit)
                    )
                }
            }
        }
    }
}

/// Load recent messages from all discovered roots so the aggregate dialog
/// never silently presents the primary repository's history as every root's.
func loadMultiRootCommitMetadata(rootPaths: [String]) {
    let paths = Array(Set(rootPaths)).sorted()
    Task.detached(priority: .utility) {
        var messages: [String] = []
        for path in paths {
            guard let rootRepo = try? openRepository(path: path) else { continue }
            messages.append(contentsOf: (try? rootRepo.recentCommitMessages(limit: 10)) ?? [])
        }
        var seen = Set<String>()
        let unique = messages.filter { seen.insert($0).inserted }
        await MainActor.run {
            self.multiRootCommitRecentMessages = unique
        }
    }
}

/// Apply the first configured template from the selected roots in stable
/// order. A single project-level message cannot represent multiple different
/// repository templates, so the choice is deterministic and visible.
func loadMultiRootCommitTemplate(_ rootPaths: [String]) {
    let paths = Array(Set(rootPaths)).sorted()
    Task.detached(priority: .userInitiated) {
        var template: String?
        for path in paths {
            guard let rootRepo = try? openRepository(path: path),
                  let candidate = try? rootRepo.commitTemplate(),
                  !candidate.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                continue
            }
            template = candidate
            break
        }
        let selectedTemplate = template
        await MainActor.run {
            if let selectedTemplate {
                self.multiRootCommitMessage = selectedTemplate
            } else {
                self.feedbackCenter.warning(
                    "No commit template configured",
                    detail: "None of the selected Git roots exposes a non-empty commit.template."
                )
            }
        }
    }
}

/// Open the project-level Changes Browser. Its write actions are still routed
/// to an explicit Git root rather than the window's primary repository.
func openMultiRootChanges() {
    showMultiRootChanges = true
    loadMultiRootChanges()
}

/// Stage one path in the Git root that owns the aggregate Changes row.
/// This deliberately opens the supplied root instead of using `repo`, which
/// is only the primary repository of the current window.
func stageMultiRootPath(rootPath: String, path: String) {
    let retryAction = multiRootChangesRetryFeedbackAction(
        operation: .stage,
        rootPath: rootPath,
        path: path
    )
    let notificationID = multiRootChangesMutationNotificationID(
        operation: .stage,
        rootPath: rootPath,
        path: path
    )
    guard let rootRepo = try? openRepository(path: rootPath) else {
        feedbackCenter.error(
            "Stage failed",
            detail: "\(rootPath): \(path)\nUnable to open the owning Git root.",
            nextStep: "Check the root, then retry staging.",
            additionalActions: [retryAction],
            notificationID: notificationID
        )
        return
    }
    beginFeedbackOperation("Stage file · \(rootPath)")
    Task.detached(priority: .userInitiated) {
        do {
            try rootRepo.stage(path: path)
            await MainActor.run {
                self.feedbackCenter.success(
                    "Changes staged",
                    detail: "\(rootPath): \(path)",
                    notificationID: notificationID
                )
                self.loadMultiRootChanges()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Stage failed",
                    detail: "\(rootPath): \(path)\n\(errorMessage(error))",
                    nextStep: "Check the file, then retry staging.",
                    additionalActions: [retryAction],
                    notificationID: notificationID
                )
            }
        }
    }
}

