/// Read status independently for every discovered Git root. The root path is
/// retained alongside the Repository so a diff can never fall back to the
/// primary repository merely because two roots contain the same relative path.
func loadMultiRootChanges() {
    multiRootChangesGeneration &+= 1
    let generation = multiRootChangesGeneration
    guard !multiRoots.isEmpty else {
        multiRootChangeGroups = []
        multiRootChangesError = nil
        multiRootChangesLoading = false
        return
    }

    let roots = multiRoots.map {
        (path: $0.path, displayName: $0.displayName, relativePath: $0.relativePath)
    }
    multiRootChangesLoading = true
    multiRootChangesError = nil

    Task.detached(priority: .userInitiated) {
        var groups: [MultiRootChangeGroup] = []
        var failures: [String] = []

        for root in roots {
            do {
                let rootRepo = try openRepository(path: root.path)
                let entries = try rootRepo.status()
                groups.append(
                    MultiRootChangeGroup(
                        rootPath: root.path,
                        displayName: root.displayName,
                        relativePath: root.relativePath,
                        repository: rootRepo,
                        entries: entries
                    )
                )
            } catch {
                failures.append("\(root.displayName): \(error.localizedDescription)")
            }
        }

        groups.sort { $0.relativePath.localizedStandardCompare($1.relativePath) == .orderedAscending }
        let loadedGroups = groups
        let failureMessage = failures.isEmpty ? nil : failures.joined(separator: "\n")
        await MainActor.run {
            guard generation == self.multiRootChangesGeneration else { return }
            self.multiRootChangeGroups = loadedGroups
            self.multiRootChangesLoading = false
            self.multiRootChangesError = failureMessage
        }
    }
}

/// IntelliJ's "Show My Branches" is based on branch ownership, not merely on
/// the author of the branch tip. The engine computes each reference's commits
/// that are not reachable from another branch and matches those commits to
/// Git's configured identity. Keep the expensive reachability work off the UI
/// actor and discard results after a project/root refresh.
func setLogBranchesShowOnlyMy(_ enabled: Bool) {
    logBranchesShowOnlyMy = enabled
    logShowMyTask?.cancel()
    logShowMyTask = nil

    guard enabled else {
        logMyBranchIDs = []
        isLoadingMyBranches = false
        return
    }

    var rootPaths: [String]
    if multiRootBranchSnapshots.count > 1 {
        rootPaths = multiRootBranchSnapshots.map(\.rootPath)
    } else if let projectPath {
        rootPaths = [projectPath]
    } else {
        rootPaths = []
    }
    rootPaths = Array(Set(rootPaths)).sorted()
    guard !rootPaths.isEmpty else {
        logMyBranchIDs = []
        isLoadingMyBranches = false
        return
    }

    let projectToken = projectPath
    isLoadingMyBranches = true
    logShowMyTask = Task.detached(priority: .utility) { [rootPaths] in
        var branchIDs = Set<String>()
        for rootPath in rootPaths {
            guard !Task.isCancelled,
                  let rootRepo = try? openRepository(path: rootPath),
                  let names = try? rootRepo.myBranchNames() else { continue }
            branchIDs.formUnion(names.local.map {
                BranchDashboardReference.referenceID(
                    rootPath: rootPath,
                    name: $0,
                    kind: .local
                )
            })
            branchIDs.formUnion(names.remote.map {
                BranchDashboardReference.referenceID(
                    rootPath: rootPath,
                    name: $0,
                    kind: .remote
                )
            })
        }
        guard !Task.isCancelled else { return }
        let resolvedBranchIDs = branchIDs
        await MainActor.run {
            guard self.projectPath == projectToken,
                  self.logBranchesShowOnlyMy else { return }
            self.logMyBranchIDs = resolvedBranchIDs
            self.isLoadingMyBranches = false
            self.logShowMyTask = nil
        }
    }
}

func refreshLogMyBranches() {
    guard logBranchesShowOnlyMy else { return }
    setLogBranchesShowOnlyMy(true)
}

/// Restore the single-root rebase seed that was written when Arbor paused a
/// rebase entry point. Git keeps the operation itself in `.git/rebase-*`, but
/// that state does not contain Arbor's expected-HEAD undo boundary or the
/// original `--update-refs` policy. Do not synthesize a seed for an operation
/// created outside Arbor: without those facts, offering Undo would be unsafe.
private func restorePersistedSingleRootRebaseState(for repositoryPath: String) {
    guard multiRootRebaseSession == nil,
          let seed = loadRebaseUndoSeed(repositoryPath: repositoryPath) else { return }
    Task.detached(priority: .utility) {
        do {
            let rootRepo = try openRepository(path: repositoryPath)
            guard let state = try rootRepo.operationState(), state.kind == .rebase else {
                clearRebaseUndoSeed(repositoryPath: repositoryPath)
                return
            }
            let status = try rootRepo.status()
            let pauseReason: RebasePauseReason = state.conflictedFiles.isEmpty ? .edit : .conflict
            await MainActor.run {
                guard self.multiRootRebaseSession == nil else { return }
                let isCurrentRoot = self.repo?.workdir().map({
                    URL(fileURLWithPath: $0).standardizedFileURL.path
                }) == URL(fileURLWithPath: repositoryPath).standardizedFileURL.path
                if isCurrentRoot {
                    self.rebaseUndoSeed = seed
                    self.rebaseRootPath = repositoryPath
                    self.rebaseBranch = seed.branch
                    self.rebasePaused = true
                    self.rebasePauseReason = pauseReason
                    self.rebaseConflicts = state.conflictedFiles
                    self.operationState = state
                    self.entries = status
                    if pauseReason == .conflict {
                        self.showMergeRevisionsDialog = true
                    }
                }
                let request = ArborVCSActionRequest(
                    kind: .resumeRebase,
                    projectPath: repositoryPath,
                    rootPath: repositoryPath,
                    shelfName: "",
                    rebaseBranch: seed.branch
                )
                let detail = state.conflictedFiles.isEmpty
                    ? "\(seed.branch): rebase paused at edit"
                    : "\(seed.branch): \(state.conflictedFiles.count) unresolved file(s)"
                self.feedbackCenter.warning(
                    "Rebase recovery available",
                    detail: detail,
                    nextStep: "Continue or abort the paused rebase from the recovery workbench.",
                    additionalActions: [
                        FeedbackAction(
                            title: "Open Rebase Recovery",
                            semanticAction: request
                        ) {
                            self.openPersistedRebaseRecovery(
                                rootPath: repositoryPath,
                                branch: seed.branch
                            )
                        }
                    ],
                    notificationID: rebaseRecoveryNotificationID(repositoryPath: repositoryPath)
                )
            }
        } catch {
            // A later project refresh will retry. Never keep a stale seed when
            // the repository cannot be opened or its operation state vanished.
            clearRebaseUndoSeed(repositoryPath: repositoryPath)
        }
    }
}

/// Rehydrate the local-change preservation paired with Pull. Unlike Git's
/// rebase/merge state, the temporary Shelf/Stash is an Arbor concern, so its
/// association must be persisted separately from the operation itself.
private func restorePersistedPullPreservation(for repositoryPath: String) {
    guard let preservation = loadPendingPullPreservation(repositoryPath: repositoryPath) else {
        return
    }
    Task.detached(priority: .utility) {
        do {
            let rootRepo = try openRepository(path: repositoryPath)
            let preservationStillExists: Bool
            if let shelfName = preservation.shelfName {
                preservationStillExists = try rootRepo.shelveList().contains { $0.name == shelfName }
            } else if let stashID = preservation.stashID {
                preservationStillExists = try rootRepo.stashList().contains { $0.id == stashID }
            } else if let stashMessage = preservation.stashMessage {
                preservationStillExists = try rootRepo.stashList().contains { $0.message == stashMessage }
            } else {
                preservationStillExists = false
            }
            guard preservationStillExists else {
                clearPendingPullPreservation(repositoryPath: repositoryPath)
                return
            }
            let state = try? rootRepo.operationState()
            await MainActor.run {
                guard self.projectRepo?.workdir().map({
                    URL(fileURLWithPath: $0).standardizedFileURL.path
                }) == URL(fileURLWithPath: repositoryPath).standardizedFileURL.path else {
                    return
                }
                self.pendingPullShelfName = preservation.shelfName
                self.pendingPullStashPop = preservation.stashID != nil || preservation.stashMessage != nil
                self.pendingPullStashID = preservation.stashID
                self.pendingPullStashMessage = preservation.stashMessage
                guard state == nil else { return }
                self.feedbackCenter.warning(
                    "Pull local changes pending",
                    detail: preservation.shelfName ?? preservation.stashMessage,
                    nextStep: "Restore the local changes saved before Pull.",
                    actionTitle: "Restore Pull Changes",
                    action: { self.popPendingPullStash() },
                    notificationID: pendingPullPreservationNotificationID(repositoryPath: repositoryPath)
                )
            }
        } catch {
            // A later refresh can retry. Do not delete the marker merely
            // because the repository was temporarily unavailable.
        }
    }
}

/// Route a persisted rebase action back to the root-scoped recovery workbench.
/// The actual Continue/Abort command re-reads Git's operation state, so a
/// notification response cannot replay an obsolete command line.
func openPersistedRebaseRecovery(rootPath: String, branch: String? = nil) {
    let normalizedRoot = URL(fileURLWithPath: rootPath).standardizedFileURL.path
    guard let seed = loadRebaseUndoSeed(repositoryPath: normalizedRoot) else { return }
    rebaseUndoSeed = seed
    rebaseRootPath = normalizedRoot
    rebaseBranch = branch ?? seed.branch
    rebasePaused = true
    if let persistedRepo = try? openRepository(path: normalizedRoot) {
        let persistedState = try? persistedRepo.operationState()
        operationState = persistedState
        rebasePauseReason = persistedState?.conflictedFiles.isEmpty == false ? .conflict : .edit
        rebaseConflicts = persistedState?.conflictedFiles ?? []
    }
    openMultiRootConflictResolver(preferredRootPath: normalizedRoot)
    if repo?.workdir() == normalizedRoot {
        loadRepoData()
    }
}

private func persistedRebaseRecoveryAction(rootPath: String, branch: String) -> FeedbackAction {
    let request = ArborVCSActionRequest(
        kind: .resumeRebase,
        projectPath: projectPath ?? rootPath,
        rootPath: rootPath,
        shelfName: "",
        rebaseBranch: branch
    )
    return FeedbackAction(
        title: "Open Rebase Recovery",
        semanticAction: request
    ) {
        self.openPersistedRebaseRecovery(rootPath: rootPath, branch: branch)
    }
}

private func finishPendingPullRebaseRestore(
    seed: RebaseUndoSeed?,
    target: RebaseUndoTarget?
) {
    guard let seed else { return }
    rebasePaused = false
    rebasePauseReason = nil
    rebaseConflicts = []
    rebaseUndoSeed = nil
    rebaseUndoTarget = target
    clearRebaseUndoSeed(repositoryPath: seed.repositoryPath)
}

/// Rehydrate preserving-process restore markers after launch. The marker is
/// written before Merge/Reset/Cherry-pick/Revert/Rebase changes the worktree,
/// so a process crash must leave an actionable path back to the same saved
/// stash or Shelf instead of silently looking like an ordinary dirty repository.
private func scanPendingApplyRestores() {
    guard let projectPath else { return }
    Task.detached(priority: .utility) {
        do {
            let roots = try discoverGitRoots(scanRoot: projectPath, maxDepth: nil)
            var pending: [(
                rootPath: String,
                displayName: String,
                operation: String,
                kind: String,
                identifier: String,
                paths: [String]
            )] = []
            for root in roots {
                guard let rootRepo = try? openRepository(path: root.path),
                      let info = ((try? rootRepo.applyLocalChangesRestoreInfo()) ?? nil)
                        ?? ((try? rootRepo.rebaseLocalChangesRestoreInfo()) ?? nil) else { continue }
                let paths = ((try? rootRepo.status()) ?? [])
                    .filter { $0.staged == .conflicted || $0.unstaged == .conflicted }
                    .map(\.path)
                    .sorted()
                let savedArtifactExists: Bool? = {
                    switch info.kind {
                    case "stash":
                        guard let stashes = try? rootRepo.stashList() else { return nil }
                        return stashes.contains { $0.id == info.identifier }
                    case "shelf":
                        guard let shelves = try? rootRepo.shelveList() else { return nil }
                        return shelves.contains { $0.name == info.identifier }
                    default:
                        return nil
                    }
                }()
                if info.operation == "submodule-update",
                   paths.isEmpty,
                   savedArtifactExists == false {
                    // If restore already consumed the artifact and the app
                    // died just before clearing the marker, finalize the
                    // marker silently instead of surfacing a false recovery.
                    _ = try? rootRepo.finalizeApplyLocalChangesRestore()
                    continue
                }
                pending.append((root.path, root.displayName, info.operation, info.kind, info.identifier, paths))
            }
            let pendingItems = pending
            await MainActor.run {
                guard self.projectPath == projectPath else { return }
                for item in pendingItems {
                    guard let savedChangesKind = ArborVCSActionRequest.SavedChangesKind(rawValue: item.kind) else {
                        continue
                    }
                    let request = ArborVCSActionRequest(
                        kind: .restoreApplyLocalChanges,
                        projectPath: projectPath,
                        rootPath: item.rootPath,
                        shelfName: "",
                        savedChangesKind: savedChangesKind,
                        savedChangesID: item.identifier
                    )
                    let affected = item.paths.isEmpty
                        ? item.identifier
                        : item.paths.joined(separator: ", ")
                    let viewAction = self.savedChangesFeedbackAction(
                        kind: savedChangesKind,
                        identifier: item.identifier,
                        rootPath: item.rootPath
                    )
                    let resolveAction: FeedbackAction? = item.operation == "rebase"
                        ? nil
                        : FeedbackAction(
                            title: "Resolve local changes",
                            semanticAction: request
                        ) {
                            self.openApplyLocalChangesRestore(request)
                        }
                    self.feedbackCenter.warning(
                        "Saved local changes need restoration",
                        detail: "\(item.displayName): \(item.operation) · \(affected)",
                        nextStep: "Resolve the saved local changes in the Git Roots conflict workbench.",
                        additionalActions: [viewAction, resolveAction].compactMap { $0 },
                        notificationID: "arbor.apply-restore.\(item.rootPath.replacingOccurrences(of: "/", with: "_"))"
                    )
                }
            }
        } catch {
            // A later root refresh will retry this scan. Do not replace a
            // usable project shell with a startup-only marker error.
        }
    }
}

func presentMultiRootNewBranchDialog() {
    guard !multiRootBranchSnapshots.isEmpty else {
        loadMultiRoots()
        feedbackCenter.warning("New branch unavailable", detail: "No Git roots were discovered.")
        return
    }
    multiRootNewBranchName = ""
    multiRootNewBranchBase = ""
    multiRootNewBranchCheckout = true
    multiRootNewBranchResetExisting = false
    multiRootExistingBranchNames = Dictionary(
        uniqueKeysWithValues: multiRootBranchSnapshots.map { snapshot in
            (snapshot.rootPath, Set(snapshot.branches.map(\.name)))
        }
    )
    multiRootSelectedRootPaths = Set(multiRootBranchSnapshots.map(\.rootPath))
    showMultiRootNewBranchDialog = true
}

/// IntelliJ's Checkout as New Branch action keeps the selected reference as
/// the base revision and restricts the dialog to the owning Git root.  Do not
/// reuse the project-wide New Branch defaults here: a same-named ref in a
/// nested root must never become the base of the new branch.
func presentMultiRootNewBranchFromReference(
    rootPath: String,
    reference: String,
    isRemote: Bool
) {
    guard multiRootBranchSnapshots.contains(where: { $0.rootPath == rootPath }) else {
        feedbackCenter.warning(
            "Checkout as New Branch unavailable",
            detail: "The selected Git root is no longer available: \(rootPath)"
        )
        loadMultiRoots()
        return
    }

    let trimmedReference = reference.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmedReference.isEmpty else {
        feedbackCenter.warning(
            "Checkout as New Branch unavailable",
            detail: "The selected reference is empty."
        )
        return
    }

    let suggestedName: String
    if isRemote,
       let separator = trimmedReference.firstIndex(of: "/") {
        let suffixStart = trimmedReference.index(after: separator)
        suggestedName = suffixStart < trimmedReference.endIndex
            ? String(trimmedReference[suffixStart...])
            : trimmedReference
    } else {
        suggestedName = trimmedReference
    }

    multiRootNewBranchName = suggestedName + "-copy"
    multiRootNewBranchBase = trimmedReference
    multiRootNewBranchCheckout = true
    multiRootNewBranchResetExisting = false
    multiRootExistingBranchNames = Dictionary(
        uniqueKeysWithValues: multiRootBranchSnapshots.map { snapshot in
            (snapshot.rootPath, Set(snapshot.branches.map(\.name)))
        }
    )
    multiRootSelectedRootPaths = [rootPath]
    showMultiRootNewBranchDialog = true
}

func dismissMultiRootNewBranchDialog() {
    showMultiRootNewBranchDialog = false
    multiRootNewBranchName = ""
    multiRootNewBranchBase = ""
    multiRootNewBranchCheckout = true
    multiRootNewBranchResetExisting = false
    multiRootExistingBranchNames = [:]
    multiRootSelectedRootPaths = []
}

func presentMultiRootRenameBranchDialog(name: String) {
    let eligible = multiRootBranchSnapshots.filter { snapshot in
        snapshot.branches.contains(where: { $0.name == name })
    }
    guard !eligible.isEmpty else {
        feedbackCenter.warning("Rename branch unavailable", detail: "No Git root contains " + name + ".")
        return
    }
    multiRootRenameOldName = name
    multiRootRenameNewName = name
    multiRootRenameUnsetUpstream = false
    multiRootRenameSelectedRootPaths = Set(eligible.map(\.rootPath))
    showMultiRootRenameBranchDialog = true
}

func dismissMultiRootRenameBranchDialog() {
    showMultiRootRenameBranchDialog = false
    multiRootRenameOldName = ""
    multiRootRenameNewName = ""
    multiRootRenameUnsetUpstream = false
    multiRootRenameSelectedRootPaths = []
}

func presentMultiRootMergeDialog(name: String) {
    let branchName = name.trimmingCharacters(in: .whitespacesAndNewlines)
    let eligible = multiRootBranchSnapshots.filter { snapshot in
        snapshot.branches.contains { $0.name == branchName }
    }
    guard !branchName.isEmpty, !eligible.isEmpty else {
        feedbackCenter.warning(
            "Merge branch unavailable",
            detail: "No Git root contains " + branchName + "."
        )
        return
    }
    multiRootMergeBranchName = branchName
    multiRootMergeSelectedRootPaths = Set(eligible.map(\.rootPath))
    multiRootMergeMergedBranchesByRoot = [:]
    multiRootMergeDialogGeneration &+= 1
    let generation = multiRootMergeDialogGeneration
    showMultiRootMergeDialog = true
    let rootPaths = eligible.map(\.rootPath)
    Task.detached(priority: .userInitiated) {
        var mergedBranchesByRoot: [String: Set<String>] = [:]
        for rootPath in rootPaths {
            guard let rootRepo = try? openRepository(path: rootPath),
                  let mergedBranches = try? rootRepo.branchListMergedAll() else {
                continue
            }
            mergedBranchesByRoot[rootPath] = Set(mergedBranches.map(\.name))
        }
        let loadedMergedBranchesByRoot = mergedBranchesByRoot
        await MainActor.run {
            guard generation == self.multiRootMergeDialogGeneration else { return }
            let alreadyMergedRootPaths = Set(
                loadedMergedBranchesByRoot.compactMap { rootPath, mergedBranches in
                    mergeBranchIsAlreadyMerged(branchName, mergedBranches: mergedBranches)
                        ? rootPath
                        : nil
                }
            )
            self.multiRootMergeMergedBranchesByRoot = loadedMergedBranchesByRoot
            self.multiRootMergeSelectedRootPaths.subtract(alreadyMergedRootPaths)
        }
    }
}

func presentMultiRootMergeFromPopup(name: String) {
    presentMultiRootMergeDialog(name: name)
    showBranchesPopover = false
}

func dismissMultiRootMergeDialog() {
    multiRootMergeDialogGeneration &+= 1
    showMultiRootMergeDialog = false
    multiRootMergeBranchName = ""
    multiRootMergeSelectedRootPaths = []
    multiRootMergeMergedBranchesByRoot = [:]
}

func startMultiRootMergeFromDialog() {
    let actionableRootPaths = multiRootMergeSelectedRootPaths.filter { rootPath in
        guard let mergedBranches = multiRootMergeMergedBranchesByRoot[rootPath] else {
            return true
        }
        return !mergeBranchIsAlreadyMerged(
            multiRootMergeBranchName,
            mergedBranches: mergedBranches
        )
    }
    multiRootMergeSelectedRootPaths = actionableRootPaths
    guard !actionableRootPaths.isEmpty else {
        feedbackCenter.warning(
            "Merge is not needed",
            detail: "The selected branch is already merged in every selected repository."
        )
        return
    }
    saveMergeDialogSettings()
    mergeMultiRootBranch(
        name: multiRootMergeBranchName,
        selectedRootPaths: actionableRootPaths,
        options: currentMergeEngineOptions()
    )
}

func dismissMultiRootMergeRollback() {
    multiRootMergeRollbackContext = nil
    if let notificationID = multiRootMergeRollbackNotificationID() {
        feedbackCenter.expire(notificationID: notificationID)
    }
}

func keepMultiRootMergePartial(_ context: MultiRootMergeRollbackContext) {
    multiRootMergeRollbackContext = nil
    let pendingRootPath = context.targets.first(where: { $0.operationPending })?.rootPath
        ?? context.pendingRootPath
    feedbackCenter.warning(
        "Partial merge kept",
        detail: context.branchName,
        nextStep: pendingRootPath == nil
            ? "Review the successful repositories in Git Roots."
            : "Resolve the pending merge in the affected Git root.",
        notificationID: multiRootMergeRollbackNotificationID(),
        notificationGroup: .standard
    )
    if let pendingRootPath {
        openMultiRootConflictResolver(preferredRootPath: pendingRootPath)
    }
}

/// Merge one local branch in the selected Git roots using IntelliJ's
/// repository-operation sequencing: conflicts are retained and the next root
/// is attempted, while a fatal failure marks all later roots as skipped.
func mergeMultiRootBranch(
    name: String,
    selectedRootPaths: Set<String>,
    options: MergeOptions? = nil
) {
    runMultiRootMergeOperation(
        name: name,
        selectedRootPaths: selectedRootPaths,
        options: options ?? currentMergeEngineOptions(),
        preserveLocalChanges: false
    )
}

private func runMultiRootMergeOperation(
    name: String,
    selectedRootPaths: Set<String>,
    options: MergeOptions,
    preserveLocalChanges: Bool,
    rootOrder: [String]? = nil,
    preservedResults: [MultiRootMergeResult] = []
) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    let branchName = name.trimmingCharacters(in: .whitespacesAndNewlines)
    let roots = multiRootBranchSnapshots.filter { snapshot in
        selectedRootPaths.contains(snapshot.rootPath)
            && snapshot.branches.contains { $0.name == branchName }
    }
    guard !branchName.isEmpty, !roots.isEmpty, let projectPath else { return }

    let canDeleteMergedBranch = roots.allSatisfy { snapshot in
        !snapshot.branches.contains { $0.name == branchName && $0.isCurrent }
    } && !GitProtectedBranchRules.matches(
        branchName,
        patterns: effectiveProtectedBranchPatterns
    )
    let deleteOnMerge = GitDeleteOnMergeOption.effectiveOption(
        mergeDeleteOnMergeOption,
        canDeleteBranch: canDeleteMergedBranch
    )
    let mergeRootPaths = roots.map(\.rootPath)
    let resultRootOrder = rootOrder ?? (
        mergeRootPaths + preservedResults
            .map(\.rootPath)
            .filter { !mergeRootPaths.contains($0) }
    )
    let allMergeRootPaths = rootOrder ?? mergeRootPaths
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    multiRootRunning = true
    beginFeedbackOperation(
        "Multi-root merge",
        notificationID: multiRootMergeNotificationID()
    )
    Task.detached(priority: .userInitiated) {
        do {
            let results: [MultiRootMergeResult]
            if preserveLocalChanges {
                results = try runMultiRootMergeWithPolicy(
                    scanRoot: projectPath,
                    selectedRootPaths: roots.map(\.rootPath),
                    branch: branchName,
                    options: options,
                    savePolicy: projectSavePolicy
                )
            } else {
                results = try runMultiRootMerge(
                    scanRoot: projectPath,
                    selectedRootPaths: roots.map(\.rootPath),
                    branch: branchName,
                    options: options
                )
            }
            let combinedResults = mergeMultiRootMergeResults(
                preserved: preservedResults,
                retry: results,
                rootOrder: resultRootOrder
            )
            let operationResults = combinedResults.map { result in
                RootOperationResult(
                    rootPath: result.rootPath,
                    displayName: result.displayName,
                    success: result.success,
                    skipped: result.skipped,
                    message: result.message
                )
            }
            let rollbackTargets = combinedResults.compactMap { result -> MultiRootMergeRollbackTarget? in
                guard result.success, !result.skipped,
                      let initialHead = result.initialHead,
                      let expectedHead = result.finalHead,
                      result.requiresFinish || !result.conflicts.isEmpty || initialHead != expectedHead else {
                    return nil
                }
                return MultiRootMergeRollbackTarget(
                    rootPath: result.rootPath,
                    displayName: result.displayName,
                    initialHead: initialHead,
                    expectedHead: expectedHead,
                    operationPending: result.requiresFinish || !result.conflicts.isEmpty
                )
            }
            let conflicts = combinedResults.filter { $0.success && !$0.skipped && !$0.conflicts.isEmpty }
            let failures = combinedResults.filter { !$0.success || $0.skipped }
            let overwriteFailures = combinedResults.filter {
                !$0.success && !$0.skipped && !$0.localChangesOverwritePaths.isEmpty
            }
            let pendingOperations = combinedResults.contains {
                !$0.skipped && $0.requiresFinish
            }
            let pendingFailureRootPath = combinedResults.first {
                !$0.success && !$0.skipped && $0.requiresFinish
            }?.rootPath
            await MainActor.run {
                self.multiRootRunning = false
                self.showMultiRootMergeDialog = false
                self.multiRootMergeBranchName = ""
                self.multiRootMergeSelectedRootPaths = []
                self.multiRootResults = operationResults
                self.loadMultiRoots()
                if preserveLocalChanges {
                    self.presentMultiRootMergeRestoreConflicts(combinedResults)
                }

                let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
                    ranges: Self.completedMergeRevisionRanges(combinedResults)
                )

                if !overwriteFailures.isEmpty && !pendingOperations && !preserveLocalChanges {
                    let details = overwriteFailures.map {
                        "\($0.displayName): \($0.localChangesOverwritePaths.joined(separator: ", "))"
                    }.joined(separator: "\n")
                    self.feedbackCenter.warning(
                        "Multi-root Merge needs a decision",
                        detail: details,
                        nextStep: "Choose Smart Merge to preserve local changes in each affected root, or cancel.",
                        additionalActions: viewCommitsAction.map { [$0] } ?? [],
                        notificationID: self.multiRootMergeNotificationID()
                    )
                    self.presentSmartOperationDecision(
                        operationTitle: "Multi-root Merge",
                        paths: overwriteFailures.flatMap { result in
                            result.localChangesOverwritePaths.map { "\(result.displayName): \($0)" }
                        },
                        detail: details,
                        smartButtonTitle: "Smart Merge",
                        onSmart: {
                            self.runMultiRootMergeOperation(
                                name: branchName,
                                selectedRootPaths: Set(overwriteFailures.map(\.rootPath)),
                                options: options,
                                preserveLocalChanges: true,
                                rootOrder: resultRootOrder,
                                preservedResults: combinedResults.filter { result in
                                    !overwriteFailures.contains(where: { $0.rootPath == result.rootPath })
                                }
                            )
                        }
                    )
                } else if !failures.isEmpty {
                    self.toolWindowMode = .operations
                    self.toolWindowExpanded = true
                    let failureDetails = failures.map {
                        "\($0.displayName): \($0.message.isEmpty ? ($0.skipped ? "skipped" : "failed") : $0.message)"
                    }
                    var additionalActions = self.multiRootMergeRollbackAction(
                        branchName: branchName,
                        targets: rollbackTargets
                    ).map { [$0] } ?? []
                    if let viewCommitsAction {
                        additionalActions.append(viewCommitsAction)
                    }
                    self.feedbackCenter.warning(
                        "Multi-root merge partially completed",
                        detail: failureDetails.joined(separator: "\n"),
                        nextStep: rollbackTargets.isEmpty
                            ? "Review the affected Git roots and resolve or abort any pending merge."
                            : "Choose whether to rollback successful roots or keep the partial state.",
                        additionalActions: additionalActions,
                        notificationID: self.multiRootMergeNotificationID(),
                        notificationGroup: rollbackTargets.isEmpty ? .toolWindow : .standard
                    )
                    if !rollbackTargets.isEmpty {
                        self.multiRootMergeRollbackContext = MultiRootMergeRollbackContext(
                            branchName: branchName,
                            targets: rollbackTargets,
                            failures: failureDetails,
                            pendingRootPath: pendingFailureRootPath
                        )
                    }
                    if rollbackTargets.isEmpty, let pendingFailureRootPath {
                        self.openMultiRootConflictResolver(preferredRootPath: pendingFailureRootPath)
                    }
                } else if !conflicts.isEmpty {
                    let conflict = conflicts.first
                    self.feedbackCenter.warning(
                        "Multi-root merge paused",
                        detail: conflicts.map {
                            "\($0.displayName): \($0.conflicts.count) conflict(s)"
                        }.joined(separator: "\n"),
                        nextStep: "Resolve conflicts in each affected root, then use Continue or Abort in Git Roots.",
                        additionalActions: viewCommitsAction.map { [$0] } ?? [],
                        notificationID: self.multiRootMergeNotificationID(),
                        notificationGroup: viewCommitsAction == nil ? .toolWindow : .standard
                    )
                    self.openMultiRootConflictResolver(
                        preferredRootPath: conflict?.rootPath,
                        preferredPath: conflict?.conflicts.first
                    )
                } else {
                    let mergeResultRows = feedbackResultRows(from: operationResults)
                    if deleteOnMerge == .delete {
                        self.feedbackCenter.success(
                            "Multi-root merge completed",
                            detail: "\(combinedResults.filter { $0.success && !$0.skipped }.count) repositories · \(branchName)",
                            additionalActions: viewCommitsAction.map { [$0] } ?? [],
                            notificationID: self.multiRootMergeNotificationID(),
                            notificationGroup: .standard
                        )
                        self.feedbackCenter.attachResultRows(
                            mergeResultRows,
                            notificationID: self.multiRootMergeNotificationID()
                        )
                        self.deleteMultiRootBranch(
                            name: branchName,
                            selectedRootPaths: Set(allMergeRootPaths),
                            allowForceDelete: false
                        )
                    } else if deleteOnMerge == .propose {
                        if let deleteAction = self.multiRootMergeDeleteAction(
                            branch: branchName,
                            rootPaths: allMergeRootPaths
                        ) {
                            self.feedbackCenter.success(
                                "Multi-root merge completed",
                                detail: "\(combinedResults.filter { $0.success && !$0.skipped }.count) repositories · \(branchName)",
                                additionalActions: [deleteAction] + (viewCommitsAction.map { [$0] } ?? []),
                                notificationID: self.multiRootMergeDeleteNotificationID(),
                                notificationGroup: .standard
                            )
                            self.feedbackCenter.attachResultRows(
                                mergeResultRows,
                                notificationID: self.multiRootMergeDeleteNotificationID()
                            )
                        }
                    } else {
                        self.feedbackCenter.success(
                            "Multi-root merge completed",
                            detail: "\(combinedResults.filter { $0.success && !$0.skipped }.count) repositories · \(branchName)",
                            additionalActions: viewCommitsAction.map { [$0] } ?? [],
                            notificationID: self.multiRootMergeNotificationID(),
                            notificationGroup: .standard
                        )
                        self.feedbackCenter.attachResultRows(
                            mergeResultRows,
                            notificationID: self.multiRootMergeNotificationID()
                        )
                    }
                }
            }
        } catch {
            await MainActor.run {
                self.multiRootRunning = false
                self.feedbackCenter.error(
                    "Multi-root merge failed",
                    detail: errorMessage(error),
                    nextStep: "Check the selected Git roots and retry the merge."
                )
            }
        }
    }
}

/// Route a typed preserving-operation restore failure to the root-scoped
/// workbench. The apply marker identifies the exact saved artifact; the
/// conflict paths come from the failed restore when available. Pull uses the
/// same marker after a selected secondary root completes Merge/Rebase.
private func presentMultiRootMergeRestoreConflict(
    rootPath: String,
    paths: [String],
    stashID: String? = nil
) {
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            guard let info = try rootRepo.applyLocalChangesRestoreInfo() else {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Saved local changes unavailable",
                        detail: "\(rootPath): the preservation marker is missing.",
                        nextStep: "Inspect that Git root's saved changes before continuing."
                    )
                }
                return
            }
            if info.kind == "shelf" {
                await MainActor.run {
                    self.openMultiRootConflictResolver(
                        preferredRootPath: rootPath,
                        preferredPath: paths.first
                    )
                }
            } else {
                let resolvedStashID = stashID ?? info.identifier
                guard let index = try rootRepo.stashList().firstIndex(where: {
                    $0.id == resolvedStashID
                }) else {
                    await MainActor.run {
                        self.feedbackCenter.error(
                            "Saved local changes unavailable",
                            detail: "\(rootPath): the temporary \(info.kind) for \(info.operation) could not be located.",
                            nextStep: "Inspect that Git root's saved changes before continuing."
                        )
                    }
                    return
                }
                await MainActor.run {
                    self.presentMultiRootStashConflict(
                        rootPath: rootPath,
                        index: index,
                        stashID: resolvedStashID,
                        isPop: true,
                        paths: paths
                    )
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Saved local changes unavailable",
                    detail: "\(rootPath): \(errorMessage(error))",
                    nextStep: "Open that Git root and resolve its saved local changes manually."
                )
            }
        }
    }
}

/// Rehydrate Smart Merge's per-root preservation marker after a merge result
/// reports a restore failure. The marker is authoritative; stash messages and
/// numeric positions are only used to connect the root to the existing
/// conflict workbench.
private func presentMultiRootMergeRestoreConflicts(_ results: [MultiRootMergeResult]) {
    for result in results where !result.success {
        let rootPath = result.rootPath
        Task.detached(priority: .userInitiated) {
            do {
                let rootRepo = try openRepository(path: rootPath)
                guard let info = try rootRepo.applyLocalChangesRestoreInfo(),
                      info.operation == "merge" else { return }
                let paths = try rootRepo.status()
                    .filter { $0.staged == .conflicted || $0.unstaged == .conflicted }
                    .map(\.path)
                if info.kind == "shelf" {
                    await MainActor.run {
                        self.openMultiRootConflictResolver(
                            preferredRootPath: rootPath,
                            preferredPath: paths.first
                        )
                    }
                } else if let index = try rootRepo.stashList().firstIndex(where: {
                    $0.id == info.identifier
                }) {
                    await MainActor.run {
                        self.presentMultiRootStashConflict(
                            rootPath: rootPath,
                            index: index,
                            stashID: info.identifier,
                            isPop: true,
                            paths: paths
                        )
                    }
                } else {
                    await MainActor.run {
                        self.feedbackCenter.error(
                            "Merge local changes unavailable",
                            detail: "\(rootPath): the temporary \(info.kind) could not be located.",
                            nextStep: "Inspect that Git root's saved changes before changing its conflicted files."
                        )
                    }
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Merge local changes unavailable",
                        detail: "\(rootPath): \(errorMessage(error))",
                        nextStep: "Open that Git root and resolve its saved local changes manually."
                    )
                }
            }
        }
    }
}

private func multiRootMergeRollbackRequest(
    branchName: String,
    targets: [MultiRootMergeRollbackTarget],
    resultRows: [FeedbackResultRow] = []
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .rollbackMultiRootMerge,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        multiRootMergeBranchName: branchName,
        multiRootMergeRollbackTargets: targets.map(PersistedMultiRootMergeRollbackTarget.init),
        multiRootMergeRollbackResultRows: resultRows.isEmpty ? nil : resultRows
    )
}

private func multiRootMergeRollbackAction(
    branchName: String,
    targets: [MultiRootMergeRollbackTarget]
) -> FeedbackAction? {
    guard !targets.isEmpty else { return nil }
    let request = multiRootMergeRollbackRequest(branchName: branchName, targets: targets)
    return FeedbackAction(title: "Rollback Successful Roots", semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

private func multiRootMergeRollbackNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.multi-root-merge.rollback.\(stableProject)"
}

/// Stable display identity for the initial multi-root Merge result. Rollback
/// and delete-on-merge use separate IDs so their later lifecycle updates do
/// not erase the original root-qualified result tree.
private func multiRootMergeNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.multi-root-merge.\(stableProject)"
}

/// Smart rollback can leave a reset preserving marker when the user's saved
/// changes conflict during restore. Reuse the project resolver immediately so
/// the failure is actionable before the next retry.
private func presentMultiRootMergeRollbackRestoreConflict(
    _ targets: [MultiRootMergeRollbackTarget]
) {
    Task.detached(priority: .utility) {
        for target in targets {
            guard let rootRepo = try? openRepository(path: target.rootPath),
                  let info = (try? rootRepo.applyLocalChangesRestoreInfo()) ?? nil,
                  info.operation == "reset" else {
                continue
            }
            let paths = ((try? rootRepo.status()) ?? [])
                .filter { $0.staged == .conflicted || $0.unstaged == .conflicted }
                .map(\.path)
            await MainActor.run {
                self.openMultiRootConflictResolver(
                    preferredRootPath: target.rootPath,
                    preferredPath: paths.first
                )
            }
            return
        }
    }
}

/// Roll back only roots whose HEAD is still the exact merge result recorded by
/// the engine. Pending merges use Abort so conflict worktrees are not silently
/// overwritten; completed merges use the configured preserving lifecycle and a
/// hard reset, matching IntelliJ's smart rollback for dirty repositories.
func rollbackMultiRootMerge(
    _ targets: [MultiRootMergeRollbackTarget],
    branchName: String? = nil,
    priorResultRows: [FeedbackResultRow] = []
) {
    guard !targets.isEmpty else { return }
    let rollbackContext = multiRootMergeRollbackContext
    let rollbackBranchName = branchName
        ?? rollbackContext?.branchName
        ?? multiRootMergeBranchName
    let previousFailures = rollbackContext?.failures ?? []
    let savePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    multiRootMergeRollbackContext = nil
    let stableNotificationID = multiRootMergeRollbackNotificationID()
    beginFeedbackOperation(
        "Rollback multi-root merge",
        notificationID: stableNotificationID
    )
    Task.detached(priority: .userInitiated) {
        var failures: [String] = []
        var remaining: [MultiRootMergeRollbackTarget] = []
        var results: [RootOperationResult] = []
        for target in targets {
            do {
                let rootRepo = try openRepository(path: target.rootPath)
                guard rootRepo.headCommitId() == target.expectedHead else {
                    throw NSError(
                        domain: "Arbor.MultiRootMergeRollback",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "HEAD changed after the merge; rollback was skipped."]
                    )
                }
                if target.operationPending {
                    try rootRepo.mergeAbort()
                } else {
                    try rootRepo.resetWithPolicy(
                        commitId: target.initialHead,
                        mode: .hard,
                        savePolicy: savePolicy
                    )
                }
                guard rootRepo.headCommitId() == target.initialHead else {
                    throw NSError(
                        domain: "Arbor.MultiRootMergeRollback",
                        code: 2,
                        userInfo: [NSLocalizedDescriptionKey: "Rollback did not restore the original HEAD."]
                    )
                }
                results.append(
                    RootOperationResult(
                        rootPath: target.rootPath,
                        displayName: target.displayName,
                        success: true,
                        skipped: false,
                        message: target.operationPending
                            ? "Aborted merge and restored the original HEAD"
                            : "Restored the original HEAD"
                    )
                )
            } catch {
                let message = errorMessage(error)
                failures.append("\(target.displayName): \(message)")
                remaining.append(target)
                results.append(
                    RootOperationResult(
                        rootPath: target.rootPath,
                        displayName: target.displayName,
                        success: false,
                        skipped: false,
                        message: message
                    )
                )
            }
        }
        let rollbackSucceeded = failures.isEmpty
        let remainingTargets = remaining
        let rollbackFailureDetails = failures
        let rollbackFailures = previousFailures + rollbackFailureDetails
        let rollbackResultRows = mergeFeedbackResultRows(
            preserved: priorResultRows,
            retry: feedbackResultRows(from: results)
        )
        await MainActor.run {
            self.loadMultiRoots()
            if rollbackSucceeded {
                self.feedbackCenter.success(
                    "Multi-root merge rollback completed",
                    detail: "\(targets.count) repositories restored",
                    notificationID: stableNotificationID,
                    notificationGroup: .standard
                )
                self.feedbackCenter.attachResultRows(
                    rollbackResultRows,
                    notificationID: stableNotificationID
                )
            } else {
                self.multiRootMergeRollbackContext = MultiRootMergeRollbackContext(
                    branchName: rollbackBranchName,
                    targets: remainingTargets,
                    failures: rollbackFailures,
                    pendingRootPath: nil
                )
                let retryRequest = self.multiRootMergeRollbackRequest(
                    branchName: rollbackBranchName,
                    targets: remainingTargets,
                    resultRows: rollbackResultRows
                )
                self.feedbackCenter.warning(
                    "Multi-root merge rollback partially failed",
                    detail: rollbackFailureDetails.joined(separator: "\n"),
                    nextStep: "Review the remaining roots and retry only after confirming their current HEAD.",
                    additionalActions: [
                        FeedbackAction(
                            title: "Retry Remaining Rollback",
                            semanticAction: retryRequest
                        ) {
                            self.handleVCSActionRequest(retryRequest)
                        }
                    ],
                    notificationID: stableNotificationID,
                    notificationGroup: .standard
                )
                self.feedbackCenter.attachResultRows(
                    rollbackResultRows,
                    notificationID: stableNotificationID
                )
                self.presentMultiRootMergeRollbackRestoreConflict(remainingTargets)
            }
        }
    }
}

func validateMultiRootRenameName(_ value: String) -> String? {
    let candidate = value.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !candidate.isEmpty else { return nil }
    guard candidate != multiRootRenameOldName else {
        return String(localized: "The new name must be different.")
    }
    let selected = multiRootBranchSnapshots.filter { snapshot in
        multiRootRenameSelectedRootPaths.contains(snapshot.rootPath)
            && snapshot.branches.contains(where: { $0.name == multiRootRenameOldName })
    }
    for snapshot in selected {
        if let conflict = branchRenameConflictMessage(
            oldName: multiRootRenameOldName,
            newName: candidate,
            localBranchNames: snapshot.branches.map(\.name),
            remoteBranchNames: snapshot.remoteBranches.map(\.name)
        ) {
            return "\(conflict) (\(snapshot.relativePath))"
        }
        guard let rootRepo = try? openRepository(path: snapshot.rootPath) else { continue }
        do {
            try rootRepo.validateBranchName(name: candidate)
        } catch {
            return errorMessage(error)
        }
    }
    return nil
}

/// Rename the same local branch in selected Git roots. A failure in one root
/// does not hide successful roots; the user gets an explicit rollback choice,
/// matching IntelliJ's repository-scoped branch operation model.
func renameMultiRootBranch(
    oldName: String,
    newName: String,
    unsetUpstream: Bool,
    selectedRootPaths: Set<String>
) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    let oldName = oldName.trimmingCharacters(in: .whitespacesAndNewlines)
    let newName = newName.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !oldName.isEmpty, !newName.isEmpty, oldName != newName else { return }
    let roots = multiRootBranchSnapshots.filter { snapshot in
        selectedRootPaths.contains(snapshot.rootPath)
            && snapshot.branches.contains(where: { $0.name == oldName })
    }
    guard !roots.isEmpty else { return }
    multiRootRunning = true
    beginFeedbackOperation("Multi-root branch rename")
    Task.detached(priority: .userInitiated) {
        var results: [RootOperationResult] = []
        var successfulTargets: [PersistedMultiRootBranchRenameRollbackTarget] = []
        var failures: [String] = []
        for snapshot in roots {
            let originalUpstream = snapshot.syncStatuses.first {
                $0.branch == oldName && $0.trackingExists
            }?.upstream
            do {
                let rootRepo = try openRepository(path: snapshot.rootPath)
                try rootRepo.branchRename(old: oldName, new: newName)
                if unsetUpstream {
                    do {
                        try rootRepo.branchUnsetUpstream(branch: newName)
                    } catch {
                        do {
                            try rootRepo.branchRename(old: newName, new: oldName)
                        } catch let rollbackError {
                            throw NSError(
                                domain: "Arbor.MultiRootBranchRename",
                                code: 2,
                                userInfo: [
                                    NSLocalizedDescriptionKey:
                                        "Upstream removal failed: \(errorMessage(error)); automatic rename rollback failed: \(errorMessage(rollbackError))"
                                ]
                            )
                        }
                        throw NSError(
                            domain: "Arbor.MultiRootBranchRename",
                            code: 1,
                            userInfo: [
                                NSLocalizedDescriptionKey:
                                    "Upstream removal failed; the branch rename was rolled back: \(errorMessage(error))"
                            ]
                        )
                    }
                }
                if let expectedNewTip = try? rootRepo.revisionCommitId(revision: newName),
                   !expectedNewTip.isEmpty,
                   let branchSnapshot = try? rootRepo.branchList() {
                    let expectedCurrentBranch = branchSnapshot.first { $0.isCurrent }?.name ?? ""
                    let expectedUpstream = unsetUpstream ? nil : originalUpstream
                    successfulTargets.append(
                        PersistedMultiRootBranchRenameRollbackTarget(
                            rootPath: snapshot.rootPath,
                            displayName: snapshot.displayName,
                            oldName: oldName,
                            newName: newName,
                            expectedNewTip: expectedNewTip,
                            expectedCurrentBranch: expectedCurrentBranch,
                            expectedUpstream: expectedUpstream,
                            upstream: originalUpstream
                        )
                    )
                }
                results.append(
                    RootOperationResult(
                        rootPath: snapshot.rootPath,
                        displayName: snapshot.displayName,
                        success: true,
                        skipped: false,
                        message: "Renamed \(oldName) to \(newName)"
                    )
                )
            } catch {
                let detail = "\(snapshot.displayName): \(errorMessage(error))"
                failures.append(detail)
                results.append(
                    RootOperationResult(
                        rootPath: snapshot.rootPath,
                        displayName: snapshot.displayName,
                        success: false,
                        skipped: false,
                        message: errorMessage(error)
                    )
                )
            }
        }
        let resultsToApply = results
        let successfulTargetsToOffer = successfulTargets
        let failuresToReport = failures
        await MainActor.run {
            self.multiRootRunning = false
            self.showMultiRootRenameBranchDialog = false
            self.multiRootResults = resultsToApply
            self.loadMultiRoots()
            if failuresToReport.isEmpty {
                self.feedbackCenter.success(
                    "Multi-root branch rename completed",
                    detail: "\(successfulTargetsToOffer.count) repositories · \(oldName) → \(newName)"
                )
            } else {
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                self.presentMultiRootBranchRenameRollback(
                    oldName: oldName,
                    newName: newName,
                    targets: successfulTargetsToOffer,
                    failureDetail: failuresToReport.joined(separator: "\n")
                )
            }
        }
    }
}

private func presentMultiRootBranchRenameRollback(
    oldName: String,
    newName: String,
    targets: [PersistedMultiRootBranchRenameRollbackTarget],
    failureDetail: String
) {
    guard !targets.isEmpty else {
        feedbackCenter.warning(
            "Multi-root branch rename failed",
            detail: failureDetail,
            nextStep: "Check the selected Git roots and retry.",
            notificationID: multiRootBranchRenameRollbackNotificationID(),
            notificationGroup: .standard
        )
        return
    }
    let rollbackRequest = multiRootBranchRenameRollbackRequest(
        oldName: oldName,
        newName: newName,
        targets: targets
    )
    let keepRequest = ArborVCSActionRequest(
        kind: .keepMultiRootBranchRenamePartial,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        multiRootBranchRenameOldName: oldName,
        multiRootBranchRenameNewName: newName
    )
    feedbackCenter.warning(
        "Multi-root branch rename partially completed",
        detail: failureDetail,
        nextStep: "Rollback the successful roots or keep the partial branch state.",
        additionalActions: [
            FeedbackAction(
                title: "Rollback Successful Roots",
                semanticAction: rollbackRequest
            ) {
                self.handleVCSActionRequest(rollbackRequest)
            },
            FeedbackAction(
                title: "Keep Partial Renames",
                semanticAction: keepRequest
            ) {
                self.handleVCSActionRequest(keepRequest)
            }
        ],
        notificationID: multiRootBranchRenameRollbackNotificationID(),
        notificationGroup: .standard
    )
}

private func multiRootBranchRenameRollbackRequest(
    oldName: String,
    newName: String,
    targets: [PersistedMultiRootBranchRenameRollbackTarget]
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .rollbackMultiRootBranchRename,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        multiRootBranchRenameOldName: oldName,
        multiRootBranchRenameNewName: newName,
        multiRootBranchRenameRollbackTargets: targets
    )
}

private func multiRootBranchRenameRollbackNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.multi-root-branch-rename.rollback.\(stableProject)"
}

private func rollbackMultiRootBranchRename(
    _ targets: [PersistedMultiRootBranchRenameRollbackTarget]
) {
    guard !targets.isEmpty else { return }
    beginFeedbackOperation("Rollback multi-root branch rename")
    Task.detached(priority: .userInitiated) {
        var results: [(target: PersistedMultiRootBranchRenameRollbackTarget, success: Bool, message: String)] = []
        for target in targets {
            do {
                let rootRepo = try openRepository(path: target.rootPath)
                let branches = try rootRepo.branchList()
                let oldBranch = branches.first { $0.name == target.oldName }
                let newBranch = branches.first { $0.name == target.newName }
                let currentBranch = branches.first { $0.isCurrent }?.name ?? ""

                if newBranch != nil {
                    guard oldBranch == nil else {
                        throw NSError(
                            domain: "Arbor.MultiRootBranchRenameRollback",
                            code: 1,
                            userInfo: [NSLocalizedDescriptionKey: "both old and new branch names exist"]
                        )
                    }
                    let actualTip = try rootRepo.revisionCommitId(revision: target.newName)
                    let actualUpstream = (try rootRepo.syncStatus()).first {
                        $0.branch == target.newName && $0.trackingExists
                    }?.upstream
                    guard actualTip == target.expectedNewTip,
                          currentBranch == target.expectedCurrentBranch,
                          actualUpstream == target.expectedUpstream else {
                        throw NSError(
                            domain: "Arbor.MultiRootBranchRenameRollback",
                            code: 2,
                            userInfo: [NSLocalizedDescriptionKey: "branch state changed after the rename"]
                        )
                    }
                    try rootRepo.branchRename(old: target.newName, new: target.oldName)
                } else {
                    guard oldBranch != nil else {
                        throw NSError(
                            domain: "Arbor.MultiRootBranchRenameRollback",
                            code: 3,
                            userInfo: [NSLocalizedDescriptionKey: "neither renamed branch exists"]
                        )
                    }
                    let actualTip = try rootRepo.revisionCommitId(revision: target.oldName)
                    let expectedRollbackBranch = target.expectedCurrentBranch == target.newName
                        ? target.oldName
                        : target.expectedCurrentBranch
                    let actualUpstream = (try rootRepo.syncStatus()).first {
                        $0.branch == target.oldName && $0.trackingExists
                    }?.upstream
                    let upstreamIsSafe = target.upstream == nil
                        ? actualUpstream == nil
                        : actualUpstream == nil || actualUpstream == target.upstream
                    guard actualTip == target.expectedNewTip,
                          currentBranch == expectedRollbackBranch,
                          upstreamIsSafe else {
                        throw NSError(
                            domain: "Arbor.MultiRootBranchRenameRollback",
                            code: 4,
                            userInfo: [NSLocalizedDescriptionKey: "branch state changed after rollback began"]
                        )
                    }
                }
                if let upstream = target.upstream, !upstream.isEmpty {
                    try rootRepo.branchSetUpstream(branch: target.oldName, upstream: upstream)
                }
                results.append((target, true, ""))
            } catch {
                results.append((target, false, errorMessage(error)))
            }
        }
        let resultsSnapshot = results
        await MainActor.run {
            self.loadMultiRoots()
            let failures = resultsSnapshot.filter { !$0.success }
            guard !failures.isEmpty else {
                self.feedbackCenter.success(
                    "Branch rename rollback completed",
                    detail: "\(resultsSnapshot.count) repositories · \(targets.first?.oldName ?? "")",
                    notificationID: self.multiRootBranchRenameRollbackNotificationID(),
                    notificationGroup: .standard
                )
                return
            }
            let remainingTargets = failures.map { $0.target }
            let retryRequest = self.multiRootBranchRenameRollbackRequest(
                oldName: targets.first?.oldName ?? "",
                newName: targets.first?.newName ?? "",
                targets: remainingTargets
            )
            self.feedbackCenter.warning(
                "Branch rename rollback partially failed",
                detail: failures.map { "\($0.target.displayName): \($0.message)" }.joined(separator: "\n"),
                nextStep: "Review changed roots and retry only the remaining rollback targets.",
                additionalActions: [
                    FeedbackAction(
                        title: "Retry Remaining Rollback",
                        semanticAction: retryRequest
                    ) {
                        self.handleVCSActionRequest(retryRequest)
                    }
                ],
                notificationID: self.multiRootBranchRenameRollbackNotificationID(),
                notificationGroup: .standard
            )
        }
    }
}

func presentMultiRootDeleteBranchDialog(name: String) {
    let eligible = multiRootBranchSnapshots.filter { snapshot in
        snapshot.branches.contains { $0.name == name && !$0.isCurrent }
    }
    guard !eligible.isEmpty else {
        feedbackCenter.warning(
            "Delete branch unavailable",
            detail: "No non-current Git root contains " + name + "."
        )
        return
    }
    multiRootDeleteBranchName = name
    multiRootDeleteSelectedRootPaths = Set(eligible.map(\.rootPath))
    showMultiRootDeleteBranchDialog = true
}

func dismissMultiRootDeleteBranchDialog() {
    showMultiRootDeleteBranchDialog = false
    multiRootDeleteBranchName = ""
    multiRootDeleteSelectedRootPaths = []
}

/// Delete a shared local branch using IntelliJ's multi-repository semantics:
/// safe deletion is attempted first, and an unmerged branch is force-deleted
/// while retaining the exact tip for a restore action.
func deleteMultiRootBranch(
    name: String,
    selectedRootPaths: Set<String>,
    allowForceDelete: Bool = true
) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    let branchName = name.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !branchName.isEmpty else { return }
    for notificationID in [
        multiRootMergeNotificationID(),
        multiRootMergeDeleteNotificationID()
    ].compactMap({ $0 }) {
        feedbackCenter.expire(notificationID: notificationID)
    }
    let roots = multiRootBranchSnapshots.filter { snapshot in
        selectedRootPaths.contains(snapshot.rootPath)
            && snapshot.branches.contains { $0.name == branchName && !$0.isCurrent }
    }
    guard !roots.isEmpty else { return }
    multiRootRunning = true
    beginFeedbackOperation("Multi-root branch deletion")
    let protectedPatterns = effectiveProtectedBranchPatterns
    Task.detached(priority: .userInitiated) {
        var results: [RootOperationResult] = []
        var recoveryContexts: [BranchDeleteRecoveryContext] = []
        var syncStatusesByRoot: [[SyncStatus]] = []
        var failures: [String] = []
        var forceDeletedRoots: [String] = []
        for snapshot in roots {
            do {
                let rootRepo = try openRepository(path: snapshot.rootPath)
                let preview = try rootRepo.branchDeletePreview(name: branchName)
                let syncStatusesBeforeDelete = (try? rootRepo.syncStatus()) ?? []
                syncStatusesByRoot.append(syncStatusesBeforeDelete)
                var forceDeleted = false
                do {
                    try rootRepo.branchDelete(name: branchName, force: false)
                } catch {
                    guard allowForceDelete, isUnmergedBranchDeletionError(error) else { throw error }
                    try rootRepo.branchDelete(name: branchName, force: true)
                    forceDeleted = true
                }
                recoveryContexts.append(
                    BranchDeleteRecoveryContext(
                        repo: rootRepo,
                        preview: preview,
                        rootPath: snapshot.rootPath
                    )
                )
                if forceDeleted {
                    forceDeletedRoots.append(snapshot.displayName)
                }
                results.append(
                    RootOperationResult(
                        rootPath: snapshot.rootPath,
                        displayName: snapshot.displayName,
                        success: true,
                        skipped: false,
                        message: forceDeleted ? "Deleted \(branchName) (force)" : "Deleted \(branchName)"
                    )
                )
            } catch {
                let detail = "\(snapshot.displayName): \(errorMessage(error))"
                failures.append(detail)
                results.append(
                    RootOperationResult(
                        rootPath: snapshot.rootPath,
                        displayName: snapshot.displayName,
                        success: false,
                        skipped: false,
                        message: errorMessage(error)
                    )
                )
            }
        }
        let resultsToApply = results
        let deletableRemoteBranches = deletableTrackedRemoteBranches(
            branchName: branchName,
            syncStatusesByRoot: syncStatusesByRoot,
            protectedPatterns: protectedPatterns
        )
        let contextsToOffer = recoveryContexts.map { context in
            guard let upstream = context.preview.upstream,
                  deletableRemoteBranches.contains(upstream) else { return context }
            return BranchDeleteRecoveryContext(
                repo: context.repo,
                preview: context.preview,
                rootPath: context.rootPath,
                trackedRemoteBranch: upstream
            )
        }
        let failuresToReport = failures
        let forceDeletedRootsToReport = forceDeletedRoots
        await MainActor.run {
            self.multiRootRunning = false
            self.showMultiRootDeleteBranchDialog = false
            self.multiRootResults = resultsToApply
            self.loadMultiRoots()
            if failuresToReport.isEmpty {
                self.multiRootBranchDeleteRecovery = MultiRootBranchDeleteRecoveryContext(
                    branchName: branchName,
                    contexts: contextsToOffer
                )
                let detail = forceDeletedRootsToReport.isEmpty
                    ? "\(contextsToOffer.count) repositories"
                    : "\(contextsToOffer.count) repositories · force deleted: \(forceDeletedRootsToReport.joined(separator: ", "))"
                self.feedbackCenter.success(
                    "Multi-root branch deletion completed",
                    detail: detail,
                    additionalActions: self.branchDeleteRecoveryActions(
                        contexts: contextsToOffer
                    ),
                    notificationID: self.branchDeleteNotificationID(),
                    notificationGroup: .standard
                )
            } else {
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                self.feedbackCenter.warning(
                    "Multi-root branch deletion partially completed",
                    detail: failuresToReport.joined(separator: "\n"),
                    nextStep: "Review the affected roots and keep or rollback the successful deletions.",
                    additionalActions: self.branchDeleteRecoveryActions(
                        contexts: contextsToOffer
                    ),
                    notificationID: self.branchDeleteNotificationID(),
                    notificationGroup: contextsToOffer.isEmpty ? .toolWindow : .standard
                )
                self.presentMultiRootBranchDeleteRollback(
                    branchName: branchName,
                    contexts: contextsToOffer,
                    failures: failuresToReport
                )
            }
        }
    }
}

private func presentMultiRootBranchDeleteRollback(
    branchName: String,
    contexts: [BranchDeleteRecoveryContext],
    failures: [String]
) {
    guard !contexts.isEmpty else { return }
    let alert = NSAlert()
    alert.messageText = "Multi-root branch deletion partially completed"
    let successful = contexts.map { $0.rootPath ?? String(localized: "Repository") }
    alert.informativeText = "Deleted \(branchName) in:\n\(successful.joined(separator: "\n"))\n\nFailures:\n\(failures.joined(separator: "\n"))"
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Rollback Successful Roots")
    alert.addButton(withTitle: "Keep Partial Deletions")
    guard alert.runModal() == .alertFirstButtonReturn else {
        multiRootBranchDeleteRecovery = MultiRootBranchDeleteRecoveryContext(
            branchName: branchName,
            contexts: contexts
        )
        feedbackCenter.warning(
            "Partial branch deletions kept",
            detail: "\(branchName) in \(contexts.count) repositories"
        )
        return
    }
    restoreDeletedBranches(contexts)
}

private func restoreDeletedBranchesFromSemanticTargets(
    _ targets: [PersistedBranchDeleteRecoveryTarget]
) {
    guard let normalizedTargets = normalizedBranchDeleteRecoveryTargets(targets) else { return }
    if let notificationID = branchDeleteNotificationID() {
        feedbackCenter.expire(notificationID: notificationID)
    }
    branchDeleteRecovery = nil
    multiRootBranchDeleteRecovery = nil
    beginFeedbackOperation("Restore deleted branches")
    Task.detached(priority: .userInitiated) {
        var failures: [String] = []
        var remaining: [PersistedBranchDeleteRecoveryTarget] = []
        var upstreamWarnings: [String] = []
        for target in normalizedTargets {
            do {
                let rootRepo = try openRepository(path: target.rootPath)
                try rootRepo.branchCreate(
                    name: target.branchName,
                    at: target.tipID
                )
                if let upstream = target.upstream, !upstream.isEmpty {
                    do {
                        try rootRepo.branchSetUpstream(
                            branch: target.branchName,
                            upstream: upstream
                        )
                    } catch {
                        upstreamWarnings.append(
                            "\(target.rootPath): \(errorMessage(error))"
                        )
                    }
                }
            } catch {
                failures.append(
                    "\(target.rootPath): \(errorMessage(error))"
                )
                remaining.append(target)
            }
        }
        let failuresToReport = failures
        let remainingTargets = remaining
        let upstreamWarningsToReport = upstreamWarnings
        await MainActor.run {
            self.loadMultiRoots()
            if let currentRootPath = self.repo?.workdir().map({
                URL(fileURLWithPath: $0).standardizedFileURL.path
            }), normalizedTargets.contains(where: { $0.rootPath == currentRootPath }) {
                self.loadRepoData()
            }
            if failuresToReport.isEmpty && upstreamWarningsToReport.isEmpty {
                self.feedbackCenter.success(
                    "Deleted branch restore completed",
                    detail: normalizedTargets.map { "\($0.branchName) · \($0.rootPath)" }.joined(separator: ", ")
                )
            } else {
                let details = failuresToReport + upstreamWarningsToReport
                self.feedbackCenter.warning(
                    "Deleted branch restore partially failed",
                    detail: details.joined(separator: "\n"),
                    nextStep: "Retry the remaining branch restore action.",
                    additionalActions: self.branchDeleteRestoreAction(
                        targets: remainingTargets,
                        title: "Retry Restore"
                    ).map { [$0] } ?? [],
                    notificationID: remainingTargets.isEmpty
                        ? nil
                        : self.branchDeleteNotificationID(),
                    notificationGroup: remainingTargets.isEmpty ? .toolWindow : .standard
                )
            }
        }
    }
}

private func viewDeletedBranchCommitsFromSemanticTargets(
    _ targets: [PersistedBranchDeleteRecoveryTarget]
) {
    guard let normalizedTargets = normalizedBranchDeleteRecoveryTargets(targets) else { return }
    var contexts: [BranchDeleteRecoveryContext] = []
    for target in normalizedTargets {
        guard let rootRepo = try? openRepository(path: target.rootPath) else {
            feedbackCenter.error(
                "View deleted commits unavailable",
                detail: "The Git root could not be opened: \(target.rootPath)",
                nextStep: "Refresh Git Roots, then retry the notification action."
            )
            return
        }
        let preview = BranchDeletePreview(
            branchName: target.branchName,
            tipId: target.tipID,
            upstream: target.upstream,
            baseBranches: target.baseBranches,
            unmergedCommits: target.unmergedCommits.map {
                BranchDeleteCommit(
                    id: $0.id,
                    shortId: $0.shortID,
                    summary: $0.summary,
                    time: $0.time
                )
            }
        )
        contexts.append(
            BranchDeleteRecoveryContext(
                repo: rootRepo,
                preview: preview,
                rootPath: target.rootPath
            )
        )
    }
    guard !contexts.isEmpty else { return }
    branchDeleteRecovery = nil
    multiRootBranchDeleteRecovery = nil
    if contexts.count == 1 {
        branchDeleteRecovery = contexts[0]
    } else {
        let branchNames = Array(Set(contexts.map { $0.preview.branchName })).sorted()
        multiRootBranchDeleteRecovery = MultiRootBranchDeleteRecoveryContext(
            branchName: branchNames.joined(separator: ", "),
            contexts: contexts
        )
    }
}

func restoreDeletedBranches(_ contexts: [BranchDeleteRecoveryContext]) {
    guard !contexts.isEmpty else { return }
    if let notificationID = branchDeleteNotificationID() {
        feedbackCenter.expire(notificationID: notificationID)
    }
    multiRootBranchDeleteRecovery = nil
    beginFeedbackOperation("Restore multi-root branches")
    Task.detached(priority: .userInitiated) {
        var failures: [String] = []
        var remaining: [BranchDeleteRecoveryContext] = []
        var upstreamWarnings: [String] = []
        for context in contexts {
            do {
                try context.repo.branchCreate(
                    name: context.preview.branchName,
                    at: context.preview.tipId
                )
                if let upstream = context.preview.upstream, !upstream.isEmpty {
                    do {
                        try context.repo.branchSetUpstream(
                            branch: context.preview.branchName,
                            upstream: upstream
                        )
                    } catch {
                        upstreamWarnings.append(
                            "\(context.rootPath ?? String(localized: "Repository")): \(errorMessage(error))"
                        )
                    }
                }
            } catch {
                failures.append(
                    "\(context.rootPath ?? String(localized: "Repository")): \(errorMessage(error))"
                )
                remaining.append(context)
            }
        }
        let failuresToReport = failures
        let remainingContexts = remaining
        let upstreamWarningsToReport = upstreamWarnings
        await MainActor.run {
            self.loadMultiRoots()
            if failuresToReport.isEmpty && upstreamWarningsToReport.isEmpty {
                self.feedbackCenter.success(
                    "Multi-root branch restore completed",
                    detail: contexts.first?.preview.branchName ?? ""
                )
            } else {
                self.multiRootBranchDeleteRecovery = remainingContexts.isEmpty
                    ? nil
                    : MultiRootBranchDeleteRecoveryContext(
                        branchName: contexts.first?.preview.branchName ?? "",
                        contexts: remainingContexts
                    )
                let details = failuresToReport + upstreamWarningsToReport
                self.feedbackCenter.warning(
                    "Multi-root branch restore partially failed",
                    detail: details.joined(separator: "\n"),
                    nextStep: "Review the affected roots and retry the remaining restore action.",
                    additionalActions: self.branchDeleteRestoreAction(
                        contexts: remainingContexts,
                        title: "Retry Restore"
                    ).map { [$0] } ?? [],
                    notificationID: remainingContexts.isEmpty
                        ? nil
                        : self.branchDeleteNotificationID(),
                    notificationGroup: remainingContexts.isEmpty ? .toolWindow : .standard
                )
            }
        }
    }
}

private func trackedRemoteProtectionName(_ remoteBranch: String) -> String {
    String(remoteBranch.split(separator: "/", maxSplits: 1).dropFirst().joined(separator: "/"))
}

func deleteTrackedRemoteBranch(_ context: BranchDeleteRecoveryContext) {
    guard let remoteBranch = context.trackedRemoteBranch else { return }
    deleteTrackedRemoteBranch(remoteBranch, contexts: [context])
}

func deleteTrackedRemoteBranch(
    _ remoteBranch: String,
    contexts: [BranchDeleteRecoveryContext]
) {
    let normalizedRemoteBranch = remoteBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedRemoteBranch.isEmpty,
          !contexts.isEmpty,
          contexts.contains(where: { $0.trackedRemoteBranch == normalizedRemoteBranch }) else {
        return
    }
    guard !GitProtectedBranchRules.matches(
        trackedRemoteProtectionName(normalizedRemoteBranch),
        patterns: effectiveProtectedBranchPatterns
    ) else {
        feedbackCenter.warning(
            "Tracked remote branch is protected",
            detail: normalizedRemoteBranch,
            nextStep: "Edit Protected Branches in Settings before deleting it."
        )
        return
    }

    let roots = contexts.filter { $0.trackedRemoteBranch == normalizedRemoteBranch }
    let location = roots.compactMap(\.rootPath).joined(separator: "\n")
    let alert = NSAlert()
    alert.messageText = "Delete tracked remote branch?"
    alert.informativeText = "This will delete \(normalizedRemoteBranch) from the remote repository.\(location.isEmpty ? "" : "\n\n\(location)")"
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Delete tracked remote branch", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        var succeeded: [BranchDeleteRecoveryContext] = []
        var failures: [String] = []
        var cancelled = false
        for context in roots {
            guard !cancel.isCancelled() else {
                cancelled = true
                break
            }
            do {
                try context.repo.deleteRemoteBranchWithAuthAndCancel(
                    remoteBranch: normalizedRemoteBranch,
                    broker: broker,
                    cancel: cancel
                )
                succeeded.append(context)
            } catch {
                if cancel.isCancelled() {
                    cancelled = true
                    break
                }
                failures.append(
                    "\(context.rootPath ?? String(localized: "Repository")): \(friendlyRemoteError(error))"
                )
            }
        }
        let succeededIDs = Set(succeeded.map(\.id))
        let failuresToReport = failures
        let cancelledToReport = cancelled
        await MainActor.run {
            if let context = self.branchDeleteRecovery,
               context.trackedRemoteBranch == normalizedRemoteBranch,
               succeededIDs.contains(context.id) {
                self.branchDeleteRecovery = BranchDeleteRecoveryContext(
                    repo: context.repo,
                    preview: context.preview,
                    rootPath: context.rootPath,
                    trackedRemoteBranch: nil
                )
            }
            if let context = self.multiRootBranchDeleteRecovery {
                let updatedContexts = context.contexts.map { item in
                    guard item.trackedRemoteBranch == normalizedRemoteBranch,
                          succeededIDs.contains(item.id) else { return item }
                    return BranchDeleteRecoveryContext(
                        repo: item.repo,
                        preview: item.preview,
                        rootPath: item.rootPath,
                        trackedRemoteBranch: nil
                    )
                }
                self.multiRootBranchDeleteRecovery = MultiRootBranchDeleteRecoveryContext(
                    branchName: context.branchName,
                    contexts: updatedContexts
                )
            }
            if roots.contains(where: { $0.rootPath != nil }) {
                self.loadMultiRoots()
            }
            if roots.contains(where: { $0.rootPath == nil }) {
                self.loadRepoData()
            }
            if failuresToReport.isEmpty && !cancelledToReport {
                self.feedbackCenter.success(
                    "Tracked remote branch deleted",
                    detail: normalizedRemoteBranch
                )
            } else {
                var details = failuresToReport
                if cancelledToReport {
                    details.insert("Operation cancelled.", at: 0)
                }
                self.feedbackCenter.warning(
                    "Tracked remote branch deletion partially failed",
                    detail: details.joined(separator: "\n"),
                    nextStep: "Retry the remaining remote deletion from the recovery sheet."
                )
            }
        }
    }
}

/// BRANCH-001：对选中的 Git roots 创建同名分支。Rust 返回旧 HEAD 与逐 root
/// 状态，Swift 只负责呈现 IntelliJ 风格的部分成功和显式 rollback 决策。
func createMultiRootBranch(
    name: String,
    baseRevision: String,
    checkout: Bool,
    reset: Bool,
    selectedRootPaths: Set<String>
) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    guard let projectPath else { return }
    let branchName = GitBranchNameCleanup.cleanUp(name)
        .trimmingCharacters(in: .whitespacesAndNewlines)
    guard !branchName.isEmpty else { return }
    let startPoint = baseRevision.trimmingCharacters(in: .whitespacesAndNewlines)
    let selected = selectedRootPaths.isEmpty ? nil : Array(selectedRootPaths)
    multiRootRunning = true
    beginFeedbackOperation("Multi-root branch creation")
    Task.detached(priority: .userInitiated) {
        do {
            let results = try Arbor.runMultiRootBranchCreateWithOptions(
                scanRoot: projectPath,
                selectedRootPaths: selected,
                name: branchName,
                startPoint: startPoint.isEmpty ? nil : startPoint,
                checkout: checkout,
                reset: reset
            )
            await MainActor.run {
                self.multiRootResults = results.map {
                    RootOperationResult(
                        rootPath: $0.rootPath,
                        displayName: $0.displayName,
                        success: $0.success,
                        skipped: $0.skipped,
                        message: $0.message
                    )
                }
                self.multiRootRunning = false
                self.loadMultiRoots()
                let created = results.filter { $0.success && !$0.skipped && $0.branchCreated }.count
                let overwritten = results.filter {
                    $0.success && !$0.skipped && $0.previousBranchTip != nil
                }.count
                let failures = results.filter { !$0.success }
                if failures.isEmpty {
                    self.feedbackCenter.success(
                        "Multi-root branch creation completed",
                        detail: "\(created) created · \(overwritten) overwritten · \(branchName)"
                    )
                } else {
                    self.operationsViewMode = .roots
                    self.toolWindowMode = .operations
                    self.toolWindowExpanded = true
                    self.presentMultiRootBranchRollback(name: branchName, results: results)
                }
            }
        } catch {
            await MainActor.run {
                self.multiRootRunning = false
                self.feedbackCenter.error(
                    "Multi-root branch creation failed",
                    detail: errorMessage(error),
                    nextStep: "Check the selected Git roots and retry."
                )
            }
        }
    }
}

private func presentMultiRootBranchRollback(
    name: String,
    results: [MultiRootBranchResult]
) {
    let targets = results
        .filter {
            $0.success && !$0.skipped
                && ($0.branchCreated || $0.previousBranchTip != nil)
        }
        .map {
            MultiRootBranchCreateTarget(
                rootPath: $0.rootPath,
                checkedOut: $0.checkedOut,
                previousBranch: $0.previousBranch,
                previousHead: $0.previousHead,
                expectedHead: $0.checkedOut ? $0.expectedBranchTip : nil,
                expectedBranch: $0.checkedOut ? name : nil,
                previousBranchTip: $0.previousBranchTip,
                expectedBranchTip: $0.expectedBranchTip
            )
        }
    let failureDetail = results
        .filter { !$0.success || $0.skipped }
        .map { "\($0.displayName): \($0.message)" }
        .joined(separator: "\n")
    guard !targets.isEmpty else {
        feedbackCenter.warning(
            "Multi-root branch creation failed",
            detail: failureDetail,
            nextStep: "Check the selected Git roots and retry.",
            notificationID: multiRootBranchCreateRollbackNotificationID(),
            notificationGroup: .standard
        )
        return
    }

    let rollbackRequest = multiRootBranchCreateRollbackRequest(
        branchName: name,
        targets: targets
    )
    let keepRequest = ArborVCSActionRequest(
        kind: .keepMultiRootBranchCreatePartial,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        multiRootBranchName: name
    )
    feedbackCenter.warning(
        "Multi-root branch creation partially completed",
        detail: failureDetail,
        nextStep: "Rollback the successful roots or keep the partial branch state.",
        additionalActions: [
            FeedbackAction(
                title: "Rollback Successful Roots",
                semanticAction: rollbackRequest
            ) {
                self.handleVCSActionRequest(rollbackRequest)
            },
            FeedbackAction(
                title: "Keep Partial Branches",
                semanticAction: keepRequest
            ) {
                self.handleVCSActionRequest(keepRequest)
            }
        ],
        notificationID: multiRootBranchCreateRollbackNotificationID(),
        notificationGroup: .standard
    )
}

private func multiRootBranchCreateRollbackRequest(
    branchName: String,
    targets: [MultiRootBranchCreateTarget]
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .rollbackMultiRootBranchCreate,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        multiRootBranchName: branchName,
        multiRootBranchCreateRollbackTargets: targets.map(PersistedMultiRootBranchCreateTarget.init)
    )
}

private func multiRootBranchCreateRollbackNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.multi-root-branch-create.rollback.\(stableProject)"
}

private func rollbackMultiRootBranchCreate(
    _ targets: [MultiRootBranchCreateTarget],
    branchName: String
) {
    guard !targets.isEmpty else { return }
    beginFeedbackOperation("Rollback multi-root branch")
    Task.detached(priority: .userInitiated) {
        do {
            let rollback = try Arbor.rollbackMultiRootBranchCreateWithState(
                name: branchName,
                targets: targets
            )
            await MainActor.run {
                self.finishMultiRootBranchCreateRollback(
                    branchName: branchName,
                    targets: targets,
                    results: rollback
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.warning(
                    "Branch rollback failed",
                    detail: errorMessage(error),
                    nextStep: "Retry after confirming the selected roots still contain the expected branch state.",
                    additionalActions: [
                        FeedbackAction(
                            title: "Retry Branch Rollback",
                            semanticAction: self.multiRootBranchCreateRollbackRequest(
                                branchName: branchName,
                                targets: targets
                            )
                        ) {
                            self.rollbackMultiRootBranchCreate(targets, branchName: branchName)
                        }
                    ],
                    notificationID: self.multiRootBranchCreateRollbackNotificationID(),
                    notificationGroup: .standard
                )
            }
        }
    }
}

private func finishMultiRootBranchCreateRollback(
    branchName: String,
    targets: [MultiRootBranchCreateTarget],
    results: [RootOperationResult]
) {
    multiRootResults = results
    loadMultiRoots()
    let failedRootPaths = Set(results.filter { !$0.success }.map(\.rootPath))
    let remainingTargets = targets.filter { failedRootPaths.contains($0.rootPath) }
    guard !remainingTargets.isEmpty else {
        feedbackCenter.success(
            "Branch rollback completed",
            detail: branchName,
            notificationID: multiRootBranchCreateRollbackNotificationID(),
            notificationGroup: .standard
        )
        return
    }

    let retryRequest = multiRootBranchCreateRollbackRequest(
        branchName: branchName,
        targets: remainingTargets
    )
    let failures = results
        .filter { !$0.success }
        .map { "\($0.displayName): \($0.message)" }
        .joined(separator: "\n")
    feedbackCenter.warning(
        "Branch rollback partially failed",
        detail: failures,
        nextStep: "Review the remaining roots and retry only when their expected branch state is still present.",
        additionalActions: [
            FeedbackAction(
                title: "Retry Remaining Rollback",
                semanticAction: retryRequest
            ) {
                self.rollbackMultiRootBranchCreate(
                    remainingTargets,
                    branchName: branchName
                )
            }
        ],
        notificationID: multiRootBranchCreateRollbackNotificationID(),
        notificationGroup: .standard
    )
}

/// Project-level Push uses the same root result workbench as the other
/// aggregate operations, but needs the credential broker, cancellation and
/// submodule dependency guard supplied by the dedicated engine API.
func executeMultiRootPush(
    selectedRootPaths: [String]? = nil,
    fromCommit: Bool = false
) {
    multiRootPushOptionsRootPaths = selectedRootPaths
    multiRootPushOptionsFromCommit = fromCommit
    showMultiRootPushOptions = true
}

func beginMultiRootCommitPushOptions(rootPaths: [String]) {
    guard !rootPaths.isEmpty else { return }
    executeMultiRootPush(selectedRootPaths: rootPaths, fromCommit: true)
}

/// Run the post-commit Push executor according to the effective project
/// preference. The explicit action remains available in Operation Log, while
/// automatic mode preflights every committed root before starting transport.
func beginMultiRootCommitPush(rootPaths: [String]) {
    let normalizedPaths = Array(Set(rootPaths)).sorted()
    guard !normalizedPaths.isEmpty else { return }
    let choice = GitPushAfterCommitSettings.choice(for: projectPath)
    let protectedBranchPatternsByRoot = Dictionary(
        uniqueKeysWithValues: normalizedPaths.map { rootPath in
            (
                canonicalExternalLogPath(rootPath),
                effectiveProtectedBranchPatterns(forRootPath: rootPath)
            )
        }
    )
    Task.detached(priority: .userInitiated) {
        let requiresPreview = choice == .always || normalizedPaths.contains { rootPath in
            pushAfterCommitRequiresPreview(
                rootPath: rootPath,
                choice: choice,
                protectedBranchPatterns: protectedBranchPatternsByRoot[
                    canonicalExternalLogPath(rootPath)
                ] ?? []
            )
        }
        await MainActor.run {
            if requiresPreview {
                self.executeMultiRootPush(
                    selectedRootPaths: normalizedPaths,
                    fromCommit: true
                )
            } else {
                self.runMultiRootPush(
                    selectedRootPaths: normalizedPaths,
                    tagMode: nil,
                    skipHooks: false,
                    force: false,
                    forceWithLease: false,
                    fromCommit: true
                )
            }
        }
    }
}

func runMultiRootPush(
    selectedRootPaths: [String]?,
    tagMode: PushDialogTagMode?,
    skipHooks: Bool,
    force: Bool = false,
    forceWithLease: Bool = false,
    fromCommit: Bool = false,
    priorViewCommitRanges: [PersistedLogRevisionRange] = [],
    priorResultRows: [FeedbackResultRow] = []
) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    multiRootPushRetryContext = nil
    guard let projectPath else { return }
    let observedRootPaths: [String]
    if let selectedRootPaths {
        observedRootPaths = selectedRootPaths
    } else {
        // The Push All dialog is populated from this snapshot already. Do
        // not synchronously rescan a large project on the main actor just to
        // enrich the eventual notification; an empty snapshot only loses the
        // optional View Commits action, never the push itself.
        observedRootPaths = multiRoots.map(\.path)
    }
    let pendingPushRevisionRanges = Self.multiRootPushRevisionRanges(
        for: observedRootPaths
    )
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    let protectedPatternsByRoot = observedRootPaths.map { rootPath in
        RootProtectedBranchPatterns(
            rootPath: canonicalExternalLogPath(rootPath),
            patterns: effectiveProtectedBranchPatterns(forRootPath: rootPath)
        )
    }
    let notificationID = multiRootRetryNotificationID(.push)
    multiRootRunning = true
    // A partial Commit and Push notification may still contain Retry Failed
    // Commits for roots that were not committed. Starting the Push stage must
    // not expire that recovery entry; the Push notification has a different
    // stable ID and can coexist with it in Operation Log.
    if !fromCommit,
       let notificationID = multiRootRetryNotificationID(.commit) {
        feedbackCenter.expire(notificationID: notificationID)
    }
    beginFeedbackOperation(
        "Push All",
        cancelHandle: cancel,
        notificationID: notificationID
    )
    Task.detached(priority: .userInitiated) { () async -> Void in
        let result: Result<[RootOperationResult], Error> = Result { () throws -> [RootOperationResult] in
            try runMultiRootPushWithForceOptions(
                scanRoot: projectPath,
                selectedRootPaths: selectedRootPaths,
                tagMode: tagMode.map { mode in
                    switch mode {
                    case .all: PushTagMode.all
                    case .currentBranch: PushTagMode.follow
                    }
                },
                skipHooks: skipHooks,
                force: force,
                forceWithLease: forceWithLease,
                protectedBranchPatterns: protectedPatternsByRoot,
                broker: broker,
                cancel: cancel
            )
        }
        await MainActor.run {
            switch result {
            case let .success(results):
                self.finishMultiRootPush(
                    results,
                    tagMode: tagMode,
                    skipHooks: skipHooks,
                    force: force,
                    forceWithLease: forceWithLease,
                    pendingPushRevisionRanges: pendingPushRevisionRanges,
                    priorViewCommitRanges: priorViewCommitRanges,
                    priorResultRows: priorResultRows,
                    notificationID: notificationID
                )
            case let .failure(error):
                self.multiRootRunning = false
                let retryAction: FeedbackAction? = observedRootPaths.isEmpty
                    ? nil
                    : {
                        let retryRequest = self.makeMultiRootRetryRequest(
                            operation: .push,
                            rootPaths: observedRootPaths,
                            tagMode: tagMode,
                            skipHooks: skipHooks,
                            force: force,
                            forceWithLease: forceWithLease,
                            logRevisionRanges: priorViewCommitRanges
                        )
                        return FeedbackAction(
                            title: "Retry Push",
                            semanticAction: retryRequest
                        ) {
                            self.handleVCSActionRequest(retryRequest)
                        }
                    }()
                let actions = retryAction.map { [$0] } ?? []
                if let engineError = error as? EngineError, case .Cancelled = engineError {
                    self.feedbackCenter.warning(
                        "Multi-root Push canceled",
                        detail: "No additional Push roots were published.",
                        additionalActions: actions,
                        notificationID: notificationID,
                        notificationGroup: .important
                    )
                } else {
                    self.feedbackCenter.error(
                        "Multi-root Push failed",
                        detail: errorMessage(error),
                        nextStep: "检查各 Git root 的 remote 和认证配置后重试。",
                        additionalActions: actions,
                        notificationID: notificationID
                    )
                }
                if self.isAuthenticationFailure(error) {
                    self.showHostingAuthPrompt = true
                }
            }
        }
    }
}

private func finishMultiRootPush(
    _ results: [RootOperationResult],
    tagMode: PushDialogTagMode?,
    skipHooks: Bool,
    force: Bool,
    forceWithLease: Bool,
    pendingPushRevisionRanges: [PersistedLogRevisionRange],
    priorViewCommitRanges: [PersistedLogRevisionRange],
    priorResultRows: [FeedbackResultRow],
    notificationID: String?
) {
    if !priorResultRows.isEmpty {
        let preservedEngineResults = self.multiRootResults.isEmpty
            ? rootOperationResults(from: priorResultRows)
            : self.multiRootResults
        self.multiRootResults = mergeRootOperationResults(
            preserved: preservedEngineResults,
            retry: results,
            rootOrder: priorResultRows.map(\.rootPath)
        )
    } else {
        self.multiRootResults = results
    }
    self.multiRootRunning = false
    self.showHostingAuthPromptIfNeeded(for: results)
    let resultRows = mergeFeedbackResultRows(
        preserved: priorResultRows,
        retry: feedbackResultRows(from: results)
    )
    let effectiveResults = priorResultRows.isEmpty
        ? results
        : rootOperationResults(from: resultRows)
    let retryPaths = effectiveResults.filter { result in
        if !result.success { return true }
        guard result.skipped else { return false }
        return result.message.localizedCaseInsensitiveContains("submodule push failed")
            || result.message.localizedCaseInsensitiveContains("cancelled")
    }.map(\.rootPath)
    let retryForceOptions = multiRootPushRetryForceOptions(
        requestedForce: force,
        requestedForceWithLease: forceWithLease,
        hasPriorResultRows: !priorResultRows.isEmpty,
        retryResults: effectiveResults.filter { retryPaths.contains($0.rootPath) }
    )
    let retryForce = retryForceOptions.force
    let retryForceWithLease = retryForceOptions.forceWithLease
    let viewCommitRanges = Self.joinedRevisionRanges(
        existing: priorViewCommitRanges,
        latest: Self.successfulPushRevisionRanges(
            pendingRanges: pendingPushRevisionRanges,
            results: results
        )
    )
    self.multiRootPushRetryContext = retryPaths.isEmpty
        ? nil
        : MultiRootPushRetryContext(
            rootPaths: retryPaths,
            tagMode: tagMode,
            skipHooks: skipHooks,
            force: retryForce,
            forceWithLease: retryForceWithLease,
            viewCommitRanges: viewCommitRanges,
            resultRows: resultRows
        )
    let nonFastForwardPaths = effectiveResults.filter { result in
        !retryForce && !result.success && pushResultNeedsUpdate(result)
    }.map(\.rootPath)
    let staleLeasePaths = effectiveResults.filter { result in
        !result.success && pushResultIsStaleLeaseRejected(result)
    }.map(\.rootPath)
    let hasRejectedResults = effectiveResults.contains { result in
        !result.success && pushResultIsRejected(result)
    }
    let hasErrorResults = effectiveResults.contains { result in
        !result.success && !pushResultIsRejected(result)
    }
    let ok = effectiveResults.filter { $0.success && !$0.skipped }.count
    let failed = effectiveResults.filter { !$0.success }.count
    let skipped = effectiveResults.filter { $0.skipped }.count
    let detail = effectiveResults.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n")
    let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
        ranges: viewCommitRanges
    )
    let shouldAutoUpdate = staleLeasePaths.isEmpty
        && !nonFastForwardPaths.isEmpty
        && !hasErrorResults
        && GitPushAutoUpdateSettings.value(for: self.projectPath)
    if shouldAutoUpdate {
        self.recoverMultiRootPushRoots(
            nonFastForwardPaths,
            rebase: GitUpdateMethodSettings.method(for: self.projectPath) == .rebase,
            updateRootPaths: self.multiRoots.map(\.path),
            tagMode: tagMode,
            skipHooks: skipHooks,
            priorViewCommitRanges: viewCommitRanges,
            priorResultRows: resultRows
        )
    } else if failed == 0 && retryPaths.isEmpty {
        self.feedbackCenter.success(
            "Multi-root complete",
            detail: "\(ok) ok · \(failed) failed · \(skipped) skipped",
            additionalActions: viewCommitsAction.map { [$0] } ?? [],
            notificationID: notificationID,
            notificationGroup: .standard
        )
    } else {
        self.operationsViewMode = .roots
        self.toolWindowMode = .operations
        self.toolWindowExpanded = true
        var additionalActions = [FeedbackAction]()
        if let viewCommitsAction {
            additionalActions.append(viewCommitsAction)
        }
        if !shouldAutoUpdate && !staleLeasePaths.isEmpty {
            let forceRequest = makeMultiRootRetryRequest(
                operation: .push,
                rootPaths: staleLeasePaths,
                tagMode: tagMode,
                skipHooks: skipHooks,
                force: true,
                forceWithLease: false,
                logRevisionRanges: viewCommitRanges,
                priorResultRows: resultRows
            )
            additionalActions.append(
                FeedbackAction(
                    title: "Force Push Anyway",
                    semanticAction: forceRequest
                ) {
                    self.handleVCSActionRequest(forceRequest)
                }
            )
        }
        if !shouldAutoUpdate && !nonFastForwardPaths.isEmpty {
            let updateRootPaths = self.multiRoots.map(\.path)
            let mergeRequest = makeMultiRootRetryRequest(
                operation: .pushRecovery,
                rootPaths: nonFastForwardPaths,
                updateRootPaths: updateRootPaths,
                rebase: false,
                tagMode: tagMode,
                skipHooks: skipHooks,
                logRevisionRanges: viewCommitRanges
            )
            additionalActions.append(
                FeedbackAction(
                    title: "Update with Merge",
                    semanticAction: mergeRequest
                ) {
                    self.handleVCSActionRequest(mergeRequest)
                }
            )
            let rebaseRequest = makeMultiRootRetryRequest(
                operation: .pushRecovery,
                rootPaths: nonFastForwardPaths,
                updateRootPaths: updateRootPaths,
                rebase: true,
                tagMode: tagMode,
                skipHooks: skipHooks,
                logRevisionRanges: viewCommitRanges
            )
            additionalActions.append(
                FeedbackAction(
                    title: "Update with Rebase",
                    semanticAction: rebaseRequest
                ) {
                    self.handleVCSActionRequest(rebaseRequest)
                }
            )
        }
        if !retryPaths.isEmpty {
            let retryRequest = makeMultiRootRetryRequest(
                operation: .push,
                rootPaths: retryPaths,
                tagMode: tagMode,
                skipHooks: skipHooks,
                force: retryForce,
                forceWithLease: retryForceWithLease,
                logRevisionRanges: viewCommitRanges,
                priorResultRows: resultRows
            )
            additionalActions.append(
                FeedbackAction(
                    title: "Retry Failed Push Roots",
                    semanticAction: retryRequest
                ) {
                    self.handleVCSActionRequest(retryRequest)
                }
            )
        }
        if let notificationID {
            additionalActions.append(
                self.showOperationDetailsAction(notificationID: notificationID)
            )
        }
        additionalActions.append(
            FeedbackAction(title: "Git Roots") {
                self.operationsViewMode = .roots
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
            }
        )
        let title: String
        if hasErrorResults {
            title = ok > 0 ? "Multi-root Push partially failed" : "Multi-root Push failed"
            self.feedbackCenter.error(
                title,
                detail: detail,
                nextStep: "Open the details, correct the affected Git roots, then retry.",
                additionalActions: additionalActions,
                notificationID: notificationID,
                notificationGroup: .important
            )
        } else if hasRejectedResults {
            title = ok > 0 ? "Multi-root Push partially rejected" : "Multi-root Push rejected"
            self.feedbackCenter.warning(
                title,
                detail: detail,
                nextStep: "Open the details, update or force-push only after verifying the remote history.",
                additionalActions: additionalActions,
                notificationID: notificationID,
                notificationGroup: .important
            )
        } else {
            self.feedbackCenter.warning(
                "Multi-root Push partially completed",
                detail: detail,
                nextStep: "Retry failed roots after correcting their Git configuration.",
                additionalActions: additionalActions,
                notificationID: notificationID,
                notificationGroup: .important
            )
        }
    }
    self.autoOpenUpdateInfoIfEnabled(viewCommitRanges)
    // Keep Push's grouped Operation Log entry root-qualified just like the
    // generic Fetch/Pull runner. The rows are presentation-only; retry safety
    // continues to use the dedicated root paths and semantic request context.
    self.feedbackCenter.attachResultRows(
        resultRows,
        notificationID: notificationID
    )
    if shouldAutoUpdate, let notificationID {
        self.feedbackCenter.expire(notificationID: notificationID)
    }
    self.refreshAll(showFeedback: false)
}

private func recoverMultiRootPushRoots(
    _ rootPaths: [String],
    rebase: Bool,
    updateRootPaths: [String]? = nil,
    tagMode: PushDialogTagMode? = nil,
    skipHooks: Bool = false,
    priorViewCommitRanges: [PersistedLogRevisionRange] = [],
    priorResultRows: [FeedbackResultRow] = []
) {
    guard !rootPaths.isEmpty, !multiRootRunning, let projectPath else { return }
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    multiRootRunning = true
    let notificationID = multiRootRetryNotificationID(.pushRecovery)
    beginFeedbackOperation(
        rebase ? "Update Push Roots (rebase)" : "Update Push Roots",
        cancelHandle: cancel,
        notificationID: notificationID
    )
    let fetchTagMode = fetchTagsMode
    let observedRootPaths = Array(Set((updateRootPaths ?? []) + rootPaths)).sorted()
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    Task.detached(priority: .userInitiated) {
        let previousHeads = Self.headCommitIDs(for: observedRootPaths)
        let result: Result<[RootOperationResult], Error> = Result { () throws -> [RootOperationResult] in
            try runMultiRootPushRecoveryWithOptionsAndFetchTags(
                scanRoot: projectPath,
                selectedRootPaths: rootPaths,
                updateRootPaths: updateRootPaths,
                rebase: rebase,
                fetchTagsMode: fetchTagMode,
                tagMode: tagMode.map { mode in
                    switch mode {
                    case .all: PushTagMode.all
                    case .currentBranch: PushTagMode.follow
                    }
                },
                skipHooks: skipHooks,
                broker: broker,
                cancel: cancel,
                savePolicy: projectSavePolicy
            )
        }
        let currentHeads = Self.headCommitIDs(for: observedRootPaths)
        await MainActor.run {
            self.finishMultiRootPushRecovery(
                result,
                rebase: rebase,
                pushRootPaths: rootPaths,
                updateRootPaths: updateRootPaths,
                tagMode: tagMode,
                skipHooks: skipHooks,
                previousHeads: previousHeads,
                currentHeads: currentHeads,
                priorViewCommitRanges: priorViewCommitRanges,
                priorResultRows: priorResultRows
            )
        }
    }
}

private func finishMultiRootPushRecovery(
    _ result: Result<[RootOperationResult], Error>,
    rebase: Bool,
    pushRootPaths: [String],
    updateRootPaths: [String]?,
    tagMode: PushDialogTagMode?,
    skipHooks: Bool,
    previousHeads: [String: String],
    currentHeads: [String: String],
    priorViewCommitRanges: [PersistedLogRevisionRange],
    priorResultRows: [FeedbackResultRow]
) {
    switch result {
    case let .success(results):
        if !priorResultRows.isEmpty {
            let preservedEngineResults = self.multiRootResults.isEmpty
                ? rootOperationResults(from: priorResultRows)
                : self.multiRootResults
            self.multiRootResults = mergeRootOperationResults(
                preserved: preservedEngineResults,
                retry: results,
                rootOrder: priorResultRows.map(\.rootPath)
            )
        } else {
            self.multiRootResults = results
        }
        self.multiRootRunning = false
        self.showHostingAuthPromptIfNeeded(for: results)
        let resultRows = mergeFeedbackResultRows(
            preserved: priorResultRows,
            retry: feedbackResultRows(from: results)
        )
        let effectiveResults = priorResultRows.isEmpty
            ? results
            : rootOperationResults(from: resultRows)
        let retryPaths = effectiveResults
            .filter { pushRootPaths.contains($0.rootPath) && (!$0.success || $0.skipped) }
            .map(\.rootPath)
        let viewCommitRanges = Self.joinedRevisionRanges(
            existing: priorViewCommitRanges,
            latest: Self.updateSessionRevisionRanges(
                previousHeads: previousHeads,
                currentHeads: currentHeads,
                results: results
            )
        )
        self.multiRootPushRetryContext = retryPaths.isEmpty
            ? nil
            : MultiRootPushRetryContext(
                rootPaths: retryPaths,
                recoveryRebase: rebase,
                recoveryUpdateRootPaths: updateRootPaths,
                tagMode: tagMode,
                skipHooks: skipHooks,
                viewCommitRanges: viewCommitRanges,
                resultRows: resultRows
            )
        let failures = effectiveResults.filter { !$0.success }
        let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
            ranges: viewCommitRanges
        )
        if failures.isEmpty && retryPaths.isEmpty {
            self.feedbackCenter.success(
                rebase ? "Update Push Roots completed (rebase)" : "Update Push Roots completed",
                detail: "\(effectiveResults.filter { $0.success && !$0.skipped }.count) updated and pushed",
                additionalActions: viewCommitsAction.map { [$0] } ?? [],
                notificationID: multiRootRetryNotificationID(.pushRecovery),
                notificationGroup: .standard
            )
        } else {
            self.operationsViewMode = .roots
            self.toolWindowMode = .operations
            self.toolWindowExpanded = true
            var recoveryActions = [FeedbackAction]()
            if failures.contains(where: {
                $0.message.localizedCaseInsensitiveContains("conflict")
                    || $0.message.localizedCaseInsensitiveContains("local changes remain")
            }) {
                recoveryActions.append(
                    FeedbackAction(title: "Resolve Conflicts") {
                        self.openMultiRootConflictResolver()
                    }
                )
            }
            recoveryActions.append(
                FeedbackAction(title: "Git Roots") {
                    self.operationsViewMode = .roots
                    self.toolWindowMode = .operations
                    self.toolWindowExpanded = true
                }
            )
            let retryRequest = retryPaths.isEmpty
                ? nil
                : makeMultiRootRetryRequest(
                    operation: .pushRecovery,
                    rootPaths: retryPaths,
                    updateRootPaths: updateRootPaths,
                    rebase: rebase,
                    tagMode: tagMode,
                    skipHooks: skipHooks,
                    logRevisionRanges: viewCommitRanges,
                    priorResultRows: resultRows
                )
            if let retryRequest {
                recoveryActions.insert(
                FeedbackAction(
                        title: "Retry Failed Push Roots",
                        semanticAction: retryRequest
                    ) {
                        self.handleVCSActionRequest(retryRequest)
                    },
                    at: 0
                )
            }
            if let viewCommitsAction {
                recoveryActions.insert(viewCommitsAction, at: 0)
            }
            self.feedbackCenter.warning(
                rebase ? "Update Push Roots partially completed (rebase)" : "Update Push Roots partially completed",
                detail: effectiveResults.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n"),
                nextStep: "Resolve the affected roots, then retry the remaining Push roots.",
                additionalActions: recoveryActions,
                notificationID: multiRootRetryNotificationID(.pushRecovery)
            )
        }
        self.autoOpenUpdateInfoIfEnabled(viewCommitRanges)
        self.feedbackCenter.attachResultRows(
            resultRows,
            notificationID: multiRootRetryNotificationID(.pushRecovery)
        )
        self.refreshAll(showFeedback: false)
    case let .failure(error):
        self.multiRootRunning = false
        let retryRequest = makeMultiRootRetryRequest(
            operation: .pushRecovery,
            rootPaths: pushRootPaths,
            updateRootPaths: updateRootPaths,
            rebase: rebase,
            tagMode: tagMode,
            skipHooks: skipHooks,
            logRevisionRanges: priorViewCommitRanges,
            priorResultRows: priorResultRows
        )
        let retryAction = FeedbackAction(
            title: "Retry Push Recovery",
            semanticAction: retryRequest
        ) {
            self.handleVCSActionRequest(retryRequest)
        }
        if let engineError = error as? EngineError, case .Cancelled = engineError {
            self.feedbackCenter.warning(
                rebase ? "Update Push Roots canceled (rebase)" : "Update Push Roots canceled",
                detail: "The affected roots were kept for an explicit retry.",
                additionalActions: [retryAction],
                notificationID: multiRootRetryNotificationID(.pushRecovery),
                notificationGroup: .important
            )
        } else {
            self.feedbackCenter.error(
                rebase ? "Update Push Roots failed (rebase)" : "Update Push Roots failed",
                detail: errorMessage(error),
                nextStep: "Resolve the affected roots, then retry the Push recovery.",
                additionalActions: [retryAction],
                notificationID: multiRootRetryNotificationID(.pushRecovery)
            )
            if self.isAuthenticationFailure(error) {
                self.showHostingAuthPrompt = true
            }
        }
    }
}

func retryMultiRootPushFailedRoots(
    rootPaths: [String]? = nil,
    recoveryRebase: Bool? = nil,
    recoveryUpdateRootPaths: [String]? = nil,
    tagMode: PushDialogTagMode? = nil,
    skipHooks: Bool? = nil,
    force: Bool? = nil,
    forceWithLease: Bool? = nil,
    priorViewCommitRanges: [PersistedLogRevisionRange]? = nil,
    priorResultRows: [FeedbackResultRow]? = nil
) {
    guard !multiRootRunning else { return }
    let context = multiRootPushRetryContext
    let retryPaths = rootPaths ?? context?.rootPaths ?? []
    guard !retryPaths.isEmpty else { return }
    let resolvedRebase = recoveryRebase ?? context?.recoveryRebase
    let resolvedUpdateRootPaths = recoveryUpdateRootPaths ?? context?.recoveryUpdateRootPaths
    let resolvedTagMode = tagMode ?? context?.tagMode
    let resolvedSkipHooks = skipHooks ?? context?.skipHooks ?? false
    let resolvedForce = force ?? context?.force ?? false
    let resolvedForceWithLease = forceWithLease ?? context?.forceWithLease ?? false
    let resolvedViewCommitRanges = priorViewCommitRanges ?? context?.viewCommitRanges ?? []
    let resolvedResultRows = priorResultRows ?? context?.resultRows ?? []
    if let recoveryRebase = resolvedRebase {
        recoverMultiRootPushRoots(
            retryPaths,
            rebase: recoveryRebase,
            updateRootPaths: resolvedUpdateRootPaths,
            tagMode: resolvedTagMode,
            skipHooks: resolvedSkipHooks,
            priorViewCommitRanges: resolvedViewCommitRanges,
            priorResultRows: resolvedResultRows
        )
    } else {
        runMultiRootPush(
            selectedRootPaths: retryPaths,
            tagMode: resolvedTagMode,
            skipHooks: resolvedSkipHooks,
            force: resolvedForce,
            forceWithLease: resolvedForce && resolvedForceWithLease,
            priorViewCommitRanges: resolvedViewCommitRanges,
            priorResultRows: resolvedResultRows
        )
    }
}

/// REPO-001:对全部 root 执行聚合操作,展示逐 root 结果(部分成功/失败/跳过)。
/// When `rootPaths` is supplied, the operation is a root-scoped retry and must
/// not repeat roots that already completed successfully in the original run.
func executeMultiRootOperation(
    _ operation: MultiRootOperation,
    message: String? = nil,
    rootPaths: [String]? = nil,
    priorRevisionRanges: [PersistedLogRevisionRange] = []
) {
    if let rebase = multiRootPullRebaseMode(operation) {
        multiRootPushRetryContext = nil
        if let rootPaths {
            retryMultiRootUpdateFailedRoots(
                rootPaths: rootPaths,
                rebase: rebase,
                priorRevisionRanges: priorRevisionRanges
            )
        } else {
            executeMultiRootUpdate(rebase: rebase)
        }
        return
    }
    switch operation {
    case .push:
        executeMultiRootPush()
        return
    default:
        multiRootPushRetryContext = nil
    }
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    guard let projectPath else { return }
    multiRootRunning = true
    beginFeedbackOperation(
        multiRootOperationTitle(operation),
        notificationID: multiRootRetryOperation(for: operation)
            .flatMap { multiRootRetryNotificationID($0) }
    )
    Task.detached(priority: .userInitiated) {
        do {
            let results: [RootOperationResult]
            if let rootPaths {
                results = try runMultiRootOperationOnRoots(
                    scanRoot: projectPath,
                    selectedRootPaths: rootPaths,
                    operation: operation,
                    commitMessage: message
                )
            } else {
                results = try runMultiRootOperation(
                    scanRoot: projectPath,
                    operation: operation,
                    commitMessage: message
                )
            }
            await MainActor.run {
                self.finishGenericMultiRootOperation(
                    results,
                    operation: operation,
                    priorRevisionRanges: [],
                    revisionRanges: []
                )
            }
        } catch {
            await MainActor.run {
                self.multiRootRunning = false
                let retryPaths = rootPaths ?? self.multiRoots.map(\.path)
                let retryAction: FeedbackAction? = self.multiRootRetryOperation(for: operation).flatMap { retryOperation in
                    guard !retryPaths.isEmpty else { return nil }
                    let request = self.makeMultiRootRetryRequest(
                        operation: retryOperation,
                        rootPaths: retryPaths,
                        logRevisionRanges: []
                    )
                    let title: String = switch retryOperation {
                    case .fetch: "Retry Fetch Roots"
                    case .pullMerge: "Retry Pull Roots (Merge)"
                    case .pullRebase: "Retry Pull Roots (Rebase)"
                    default: "Retry Failed Roots"
                    }
                    return FeedbackAction(title: title, semanticAction: request) {
                        self.handleVCSActionRequest(request)
                    }
                }
                self.feedbackCenter.error(
                    "Multi-root operation failed",
                    detail: errorMessage(error),
                    nextStep: "检查仓库配置后重试。",
                    additionalActions: retryAction.map { [$0] } ?? [],
                    notificationID: self.multiRootRetryOperation(for: operation)
                        .flatMap { self.multiRootRetryNotificationID($0) }
                )
                // Fetch/Pull can fail before the engine has a chance to emit
                // per-root results. Preserve the same hosting-token recovery
                // path used by single-root and partial aggregate failures.
                if self.isAuthenticationFailure(error) {
                    self.showHostingAuthPrompt = true
                }
            }
        }
    }
}

private func showHostingAuthPromptIfNeeded(for results: [RootOperationResult]) {
    guard results.contains(where: { !$0.success && arborAuthenticationFailureMessage($0.message) }) else {
        return
    }
    showHostingAuthPrompt = true
}

private func multiRootOperationTitle(_ operation: MultiRootOperation) -> String {
    switch operation {
    case .fetch: "Fetch All"
    case .pullMerge: "Pull All (Merge)"
    case .pullRebase: "Pull All (Rebase)"
    case .push: "Push All"
    case .commit: "Commit All"
    }
}

private func multiRootRetryOperation(
    for operation: MultiRootOperation
) -> ArborVCSActionRequest.MultiRootRetryOperation? {
    switch operation {
    case .fetch: .fetch
    case .pullMerge: .pullMerge
    case .pullRebase: .pullRebase
    case .push, .commit: nil
    }
}

private func multiRootRetryableRootPaths(
    from results: [RootOperationResult]
) -> [String] {
    results.compactMap { result in
        if !result.success {
            return result.rootPath
        }
        guard result.skipped,
              result.message.localizedCaseInsensitiveContains("cancel") else {
            return nil
        }
        return result.rootPath
    }
}

private func finishGenericMultiRootOperation(
    _ results: [RootOperationResult],
    operation: MultiRootOperation,
    priorRevisionRanges: [PersistedLogRevisionRange] = [],
    revisionRanges: [PersistedLogRevisionRange] = []
) {
    multiRootResults = results
    multiRootRunning = false
    showHostingAuthPromptIfNeeded(for: results)

    let completed = results.filter { $0.success && !$0.skipped }.count
    let failed = results.filter { !$0.success }.count
    let skipped = results.filter { $0.skipped }.count
    let retryPaths = multiRootRetryableRootPaths(from: results)
    let retryOperation = multiRootRetryOperation(for: operation)
    let combinedRevisionRanges = operation == .pullMerge || operation == .pullRebase
        ? ContentView.joinedRevisionRanges(existing: priorRevisionRanges, latest: revisionRanges)
        : []
    var actions: [FeedbackAction] = []

    if let viewCommitsAction = multiRootUpdateViewCommitsAction(ranges: combinedRevisionRanges) {
        actions.append(viewCommitsAction)
    }

    if let retryOperation, !retryPaths.isEmpty {
        let request = makeMultiRootRetryRequest(
            operation: retryOperation,
            rootPaths: retryPaths,
            logRevisionRanges: combinedRevisionRanges
        )
        let title: String = switch retryOperation {
        case .fetch: "Retry Failed Fetch Roots"
        case .pullMerge: "Retry Failed Pull Roots (Merge)"
        case .pullRebase: "Retry Failed Pull Roots (Rebase)"
        default: "Retry Failed Roots"
        }
        actions.append(
            FeedbackAction(
                id: "retry-multi-root-\(retryOperation.rawValue):\(retryPaths.sorted().joined(separator: "|"))",
                title: title,
                semanticAction: request
            ) {
                handleVCSActionRequest(request)
            }
        )
    }

    let detail = results.map { result in
        let state = result.success
            ? (result.skipped ? "skipped" : "ok")
            : "failed"
        let message = result.message.trimmingCharacters(in: .whitespacesAndNewlines)
        return message.isEmpty
            ? "\(result.displayName): \(state)"
            : "\(result.displayName): \(state) — \(message)"
    }.joined(separator: "\n")
    let notificationID = multiRootRetryOperation(for: operation)
        .flatMap { multiRootRetryNotificationID($0) }

    if failed == 0 && skipped == 0 {
        feedbackCenter.success(
            multiRootOperationTitle(operation) + " completed",
            detail: "\(completed) ok",
            additionalActions: actions,
            notificationID: notificationID,
            notificationGroup: .standard
        )
    } else {
        feedbackCenter.warning(
            multiRootOperationTitle(operation) + " partially completed",
            detail: "\(completed) ok · \(failed) failed · \(skipped) skipped\n\(detail)",
            nextStep: actions.isEmpty
                ? "Review the affected Git roots and resolve their configuration or operation state."
                : "Resolve the affected roots, then retry only the remaining roots.",
            additionalActions: actions,
            notificationID: notificationID,
            notificationGroup: failed == 0 ? .toolWindow : .important
        )
    }
    feedbackCenter.attachResultRows(
        feedbackResultRows(from: results),
        notificationID: notificationID
    )
    refreshAll(showFeedback: false)
}

nonisolated static func updatedCommitCount(from updateMessage: String) -> Int? {
    let words = updateMessage.split(whereSeparator: { $0 == " " || $0 == "\n" })
    guard let index = words.firstIndex(where: { $0.caseInsensitiveCompare("updated") == .orderedSame }),
          index < words.index(before: words.endIndex) else {
        return nil
    }
    return Int(words[words.index(after: index)])
}

/// IntelliJ treats an Update Project run with no tracked, checked-out root as
/// NOT_READY. Detached or untracked roots may be skipped only when another
/// root can actually perform the update.
nonisolated static func updateProjectHasEligibleRoot(
    _ results: [RootOperationResult]
) -> Bool {
    results.contains { result in
        result.success && !result.skipped
    }
}

/// The engine performs IntelliJ's project-level readiness check before any
/// root is fetched or updated. Keep the presentation classifier tolerant of
/// the older single-root error wording as well, so a race that is detected at
/// the root boundary still follows the same unavailable/recovery flow.
nonisolated static func updateProjectIsNotReady(
    _ results: [RootOperationResult]
) -> Bool {
    results.contains { result in
        let message = result.message.lowercased()
        return message.contains("update not ready")
            || message.contains("another git operation is already in progress")
            || message.contains("unresolved conflicts remain")
    }
}

nonisolated static func skippedUpdateRootDetails(_ results: [RootOperationResult]) -> [String] {
    var rootsByReason: [String: [String]] = [:]
    for result in results where result.skipped {
        let reason = result.message.trimmingCharacters(in: .whitespacesAndNewlines)
        rootsByReason[reason.isEmpty ? "not available" : reason, default: []].append(result.displayName)
    }
    return rootsByReason.keys.sorted().compactMap { reason in
        guard let roots = rootsByReason[reason], !roots.isEmpty else { return nil }
        return "\(roots.joined(separator: ", ")) (\(reason))"
    }
}

struct UpdateRootRecoveryTarget: Equatable, Sendable {
    enum Kind: String, Equatable, Sendable {
        case chooseUpstream
        case openBranches
    }

    let kind: Kind
    let rootPath: String
    let displayName: String
    let branch: String?
}

struct UpdateRootRecoveryRoot: Equatable, Sendable {
    let path: String
    let displayName: String
    let isSubmodule: Bool
    let headBranch: String?
}

/// Project Update skips detached or untracked roots instead of turning one
/// root's configuration problem into a compound-operation failure. Keep the
/// recovery target root-qualified so the follow-up action cannot accidentally
/// edit the current window's repository when the skipped root is nested.
nonisolated static func updateRootRecoveryTargets(
    results: [RootOperationResult],
    roots: [UpdateRootRecoveryRoot]
) -> [UpdateRootRecoveryTarget] {
    let rootsByPath = Dictionary(
        uniqueKeysWithValues: roots.map {
            (URL(fileURLWithPath: $0.path).standardizedFileURL.path, $0)
        }
    )
    var targets: [UpdateRootRecoveryTarget] = []
    for result in results where result.skipped {
        let path = URL(fileURLWithPath: result.rootPath).standardizedFileURL.path
        guard let root = rootsByPath[path], !root.isSubmodule else { continue }
        let message = result.message.lowercased()
        if message.contains("no configured upstream")
            || message.contains("tracking branch")
        {
            guard let branch = root.headBranch, !branch.isEmpty else { continue }
            targets.append(
                UpdateRootRecoveryTarget(
                    kind: .chooseUpstream,
                    rootPath: path,
                    displayName: root.displayName,
                    branch: branch
                )
            )
        } else if message.contains("detached head") {
            targets.append(
                UpdateRootRecoveryTarget(
                    kind: .openBranches,
                    rootPath: path,
                    displayName: root.displayName,
                    branch: nil
                )
            )
        }
    }
    return targets.sorted {
        if $0.kind != $1.kind { return $0.kind.rawValue < $1.kind.rawValue }
        return $0.rootPath < $1.rootPath
    }
}

nonisolated static func multiRootUpdateFailureDetails(
    _ results: [RootOperationResult],
    submoduleRootPaths: Set<String>
) -> [String] {
    func normalizedPath(_ path: String) -> String {
        URL(fileURLWithPath: path).standardizedFileURL.path
    }

    func isDescendant(_ path: String, of ancestor: String) -> Bool {
        path.hasPrefix(ancestor + "/")
    }

    let normalizedSubmodulePaths = Set(submoduleRootPaths.map(normalizedPath))
    let resultPaths = Dictionary(uniqueKeysWithValues: results.map {
        (normalizedPath($0.rootPath), $0)
    })
    let failedPaths = Set(results.filter { !$0.success }.map { normalizedPath($0.rootPath) })

    func nearestFailedAncestor(for path: String) -> String? {
        failedPaths
            .filter { $0 != path && isDescendant(path, of: $0) }
            .max { $0.count < $1.count }
    }

    var grouped: [String: [RootOperationResult]] = [:]
    for result in results where !result.success {
        let path = normalizedPath(result.rootPath)
        let groupPath = nearestFailedAncestor(for: path) ?? path
        grouped[groupPath, default: []].append(result)
    }
    for result in results where result.skipped {
        let path = normalizedPath(result.rootPath)
        guard normalizedSubmodulePaths.contains(path),
              let groupPath = nearestFailedAncestor(for: path) else { continue }
        grouped[groupPath, default: []].append(result)
    }

    var groupedResultPaths = Set<String>()
    var details: [String] = []
    for groupPath in grouped.keys.sorted() {
        guard let groupRoot = resultPaths[groupPath],
              let members = grouped[groupPath] else { continue }
        groupedResultPaths.formUnion(members.map { normalizedPath($0.rootPath) })
        details.append("\(groupRoot.displayName): \(groupRoot.message)")
        for member in members
            .filter({ normalizedPath($0.rootPath) != groupPath })
            .sorted(by: { $0.rootPath < $1.rootPath }) {
            details.append("  \(member.displayName): \(member.message)")
        }
    }

    var skippedByReason: [String: [String]] = [:]
    for result in results where result.skipped {
        let path = normalizedPath(result.rootPath)
        guard !groupedResultPaths.contains(path) else { continue }
        let reason = result.message.trimmingCharacters(in: .whitespacesAndNewlines)
        skippedByReason[reason.isEmpty ? "not available" : reason, default: []].append(result.displayName)
    }
    for reason in skippedByReason.keys.sorted() {
        guard let roots = skippedByReason[reason], !roots.isEmpty else { continue }
        details.append("\(roots.joined(separator: ", ")) (\(reason))")
    }
    return details
}

nonisolated static func multiRootUpdateSuccessDetail(
    _ results: [RootOperationResult],
    updatedFilesCount: Int? = nil
) -> String {
    let updatedResults = results.filter { $0.success && !$0.skipped }
    let parsedCommitCounts = updatedResults.compactMap { updatedCommitCount(from: $0.message) }
    let updatedCommits = parsedCommitCounts.reduce(0, +)
    var details: [String] = []
    if updatedResults.isEmpty {
        details.append("Nothing to update")
    } else if parsedCommitCounts.count == updatedResults.count && updatedCommits == 0 {
        details.append("Nothing to update")
    } else if parsedCommitCounts.isEmpty {
        details.append("\(updatedResults.count) updated")
    } else {
        details.append("\(updatedResults.count) updated · \(updatedCommits) commits")
    }
    if let updatedFilesCount,
       !updatedResults.isEmpty,
       !(parsedCommitCounts.count == updatedResults.count && updatedCommits == 0) {
        if parsedCommitCounts.count == updatedResults.count {
            details[0] = "\(updatedFilesCount) files updated in \(updatedCommits) commits"
        } else {
            details[0] = "\(updatedFilesCount) files updated"
        }
    }
    let skipped = skippedUpdateRootDetails(results)
    if !skipped.isEmpty {
        details.append("Skipped: \(skipped.joined(separator: "; "))")
    }
    return details.joined(separator: " · ")
}

/// IntelliJ's UpdateSession reports the number of files touched by the
/// received range. Keep the calculation outside RootOperationResult so the
/// generic multi-root operation record remains source-compatible; if any
/// root cannot resolve its saved range, omit the count instead of showing a
/// misleading partial number.
nonisolated static func updateSessionUpdatedFilesCount(
    _ ranges: [PersistedLogRevisionRange]
) -> Int? {
    guard !ranges.isEmpty else { return 0 }
    var total = 0
    for range in ranges {
        guard let rootRepo = try? openRepository(path: range.rootPath),
              let changes = try? rootRepo.treeChanges(
                  rev1: range.oldRevision,
                  rev2: range.newRevision
              ) else {
            return nil
        }
        total += changes.count
    }
    return total
}

/// Update Project's View Commits action needs the exact before/after tip for
/// each root that actually advanced. Keep this derived in Swift so the
/// existing RootOperationResult UniFFI record remains source-compatible for
/// every other multi-root operation.
nonisolated static func updateSessionRevisionRanges(
    previousHeads: [String: String],
    currentHeads: [String: String],
    results: [RootOperationResult]
) -> [PersistedLogRevisionRange] {
    func normalizedPath(_ path: String) -> String {
        URL(fileURLWithPath: path).standardizedFileURL.path
    }

    var previousByRoot: [String: String] = [:]
    for (path, head) in previousHeads {
        previousByRoot[normalizedPath(path)] = head
    }
    var currentByRoot: [String: String] = [:]
    for (path, head) in currentHeads {
        currentByRoot[normalizedPath(path)] = head
    }

    return results
        .filter { $0.success && !$0.skipped }
        .compactMap { result in
            let rootPath = normalizedPath(result.rootPath)
            guard let oldRevision = previousByRoot[rootPath],
                  let newRevision = currentByRoot[rootPath],
                  !oldRevision.isEmpty,
                  !newRevision.isEmpty,
                  oldRevision != newRevision else {
                return nil
            }
            return PersistedLogRevisionRange(
                rootPath: rootPath,
                oldRevision: oldRevision,
                newRevision: newRevision
            )
        }
        .sorted { $0.rootPath < $1.rootPath }
}

/// GitMergeAction exposes the same received-commits follow-up as Update when
/// a merge actually creates or advances a commit. Keep the range derived from
/// the engine's per-root before/after heads so fast-forward, no-ff and mixed
/// multi-root results do not expose an unrelated or unchanged Log range.
nonisolated static func completedMergeRevisionRanges(
    _ results: [MultiRootMergeResult]
) -> [PersistedLogRevisionRange] {
    func normalizedPath(_ path: String) -> String {
        URL(fileURLWithPath: path).standardizedFileURL.path
    }

    return results
        .filter { result in
            result.success
                && !result.skipped
                && result.completed
                && result.initialHead != nil
                && result.finalHead != nil
        }
        .compactMap { result in
            guard let initialHead = result.initialHead,
                  let finalHead = result.finalHead,
                  !initialHead.isEmpty,
                  !finalHead.isEmpty,
                  initialHead != finalHead else {
                return nil
            }
            return PersistedLogRevisionRange(
                rootPath: normalizedPath(result.rootPath),
                oldRevision: initialHead,
                newRevision: finalHead
            )
        }
        .sorted { $0.rootPath < $1.rootPath }
}

private func completedMergeViewCommitsAction(
    rootPath: String,
    initialHead: String?,
    finalHead: String?,
    completed: Bool
) -> FeedbackAction? {
    guard completed,
          let initialHead,
          let finalHead,
          !initialHead.isEmpty,
          !finalHead.isEmpty,
          initialHead != finalHead else {
        return nil
    }
    return multiRootUpdateViewCommitsAction(
        ranges: [PersistedLogRevisionRange(
            rootPath: URL(fileURLWithPath: rootPath).standardizedFileURL.path,
            oldRevision: initialHead,
            newRevision: finalHead
        )]
    )
}

/// IntelliJ joins ranges when a rejected Push recovery performs more than one
/// Update before the next Push attempt. Keep the first pre-update boundary and
/// advance only the latest post-update tip for each normalized Git root.
nonisolated static func joinedRevisionRanges(
    existing: [PersistedLogRevisionRange],
    latest: [PersistedLogRevisionRange]
) -> [PersistedLogRevisionRange] {
    func normalizedPath(_ path: String) -> String {
        URL(fileURLWithPath: path).standardizedFileURL.path
    }

    var rangesByRoot: [String: PersistedLogRevisionRange] = [:]
    for range in existing {
        let rootPath = normalizedPath(range.rootPath)
        rangesByRoot[rootPath] = PersistedLogRevisionRange(
            rootPath: rootPath,
            oldRevision: range.oldRevision,
            newRevision: range.newRevision
        )
    }
    for range in latest {
        let rootPath = normalizedPath(range.rootPath)
        if let previous = rangesByRoot[rootPath] {
            rangesByRoot[rootPath] = PersistedLogRevisionRange(
                rootPath: rootPath,
                oldRevision: previous.oldRevision,
                newRevision: range.newRevision
            )
        } else {
            rangesByRoot[rootPath] = PersistedLogRevisionRange(
                rootPath: rootPath,
                oldRevision: range.oldRevision,
                newRevision: range.newRevision
            )
        }
    }
    return rangesByRoot.values.sorted { $0.rootPath < $1.rootPath }
}

/// Push leaves the local HEAD unchanged, so its View Commits range uses the
/// merge-base of the local tip and the tracked upstream tip, matching
/// IntelliJ's `GitUpdatedRanges` calculation. Roots without a resolvable
/// upstream or common ancestor are intentionally omitted: a first publish or
/// a tag-only push has no trustworthy old commit boundary.
nonisolated static func multiRootPushRevisionRanges(
    for rootPaths: [String],
    remote: String? = nil
) -> [PersistedLogRevisionRange] {
    let normalizedRootPaths = Set(rootPaths.map {
        URL(fileURLWithPath: $0).standardizedFileURL.path
    })
    return normalizedRootPaths.compactMap { rootPath in
        guard let rootRepo = try? openRepository(path: rootPath),
              let branch = (try? rootRepo.branchList())?.first(where: { $0.isCurrent })?.name,
              let head = rootRepo.headCommitId(),
              !head.isEmpty,
              let sync = (try? rootRepo.syncStatus())?.first(where: {
                  $0.branch == branch && $0.trackingExists
              }),
              remote.map({ sync.upstream.hasPrefix("\($0)/") }) ?? true,
              let upstreamHead = try? rootRepo.revisionCommitId(revision: sync.upstream),
              !upstreamHead.isEmpty,
              let rangeStart = try? rootRepo.mergeBaseRevisionId(
                  first: head,
                  second: upstreamHead
              ),
              !rangeStart.isEmpty,
              rangeStart != head else {
            return nil
        }
        return PersistedLogRevisionRange(
            rootPath: rootPath,
            oldRevision: rangeStart,
            newRevision: head
        )
    }
    .sorted { $0.rootPath < $1.rootPath }
}

/// Keep only ranges belonging to roots whose Push result actually completed.
/// This prevents a successful sibling from exposing a failed root's pending
/// commits in a compound notification.
nonisolated static func successfulPushRevisionRanges(
    pendingRanges: [PersistedLogRevisionRange],
    results: [RootOperationResult]
) -> [PersistedLogRevisionRange] {
    func normalizedPath(_ path: String) -> String {
        URL(fileURLWithPath: path).standardizedFileURL.path
    }

    let successfulRoots = Set(
        results
            .filter { $0.success && !$0.skipped }
            .map { normalizedPath($0.rootPath) }
    )
    return pendingRanges
        .filter { successfulRoots.contains(normalizedPath($0.rootPath)) }
        .sorted { $0.rootPath < $1.rootPath }
}

nonisolated static func headCommitIDs(for rootPaths: [String]) -> [String: String] {
    var heads: [String: String] = [:]
    for rootPath in rootPaths {
        guard let rootRepo = try? openRepository(path: rootPath),
              let head = rootRepo.headCommitId(),
              !head.isEmpty else { continue }
        heads[rootPath] = head
    }
    return heads
}

/// Capture the symbolic HEAD identity alongside commit IDs so an Update
/// rollback cannot mutate a different branch that happens to share the same
/// commit tip. An empty value represents detached HEAD.
nonisolated static func headBranchNames(for rootPaths: [String]) -> [String: String] {
    var branches: [String: String] = [:]
    for rootPath in rootPaths {
        guard let rootRepo = try? openRepository(path: rootPath) else { continue }
        let branch = (try? rootRepo.branchList())?.first(where: { $0.isCurrent })?.name ?? ""
        branches[rootPath] = branch
    }
    return branches
}

/// Build the expected-HEAD set for an Update Project rollback. Only roots
/// that completed and actually advanced are included; failed roots may still
/// have an active merge/rebase state and must remain in their recovery flow.
nonisolated static func updateSessionRollbackTargets(
    previousHeads: [String: String],
    currentHeads: [String: String],
    results: [RootOperationResult],
    submoduleRootPaths: [String],
    previousHeadBranches: [String: String] = [:]
) -> [PersistedMultiRootUpdateRollbackTarget] {
    func normalizedPath(_ path: String) -> String {
        URL(fileURLWithPath: path).standardizedFileURL.path
    }

    let previousByRoot = Dictionary(
        uniqueKeysWithValues: previousHeads.map { (normalizedPath($0.key), $0.value) }
    )
    let currentByRoot = Dictionary(
        uniqueKeysWithValues: currentHeads.map { (normalizedPath($0.key), $0.value) }
    )
    let previousBranchByRoot = Dictionary(
        uniqueKeysWithValues: previousHeadBranches.map { (normalizedPath($0.key), $0.value) }
    )
    let normalizedSubmodulePaths = submoduleRootPaths.map(normalizedPath)
    return results
        .filter { $0.success && !$0.skipped }
        .compactMap { result in
            let rootPath = normalizedPath(result.rootPath)
            guard let initialHead = previousByRoot[rootPath],
                  let expectedHead = currentByRoot[rootPath],
                  !initialHead.isEmpty,
                  !expectedHead.isEmpty,
                  initialHead != expectedHead else {
                return nil
            }
            let ignoredPaths = normalizedSubmodulePaths
                .filter {
                    $0 != rootPath && $0.hasPrefix(rootPath + "/")
                }
                .map {
                    String($0.dropFirst(rootPath.count + 1))
                }
                .sorted()
            return PersistedMultiRootUpdateRollbackTarget(
                rootPath: rootPath,
                displayName: result.displayName,
                initialHead: initialHead,
                expectedHead: expectedHead,
                expectedHeadBranch: previousBranchByRoot[rootPath],
                ignoredPaths: ignoredPaths
            )
        }
        .sorted { lhs, rhs in
            if lhs.rootPath.count != rhs.rootPath.count {
                return lhs.rootPath.count > rhs.rootPath.count
            }
            return lhs.rootPath < rhs.rootPath
        }
}

/// Capture the detached submodule worktrees that moved during a standalone
/// `git submodule update`. Unlike Update Project, this operation does not move
/// the superproject HEAD, so only initialized submodule roots with a changed
/// HEAD are rollback candidates. The same expected-HEAD guard used by the
/// project updater keeps a later checkout or local change from being clobbered.
nonisolated static func submoduleUpdateRollbackTargets(
    before: [GitRootInfo],
    after: [GitRootInfo]
) -> [PersistedMultiRootUpdateRollbackTarget] {
    let beforeByPath = Dictionary(
        uniqueKeysWithValues: before.map {
            (URL(fileURLWithPath: $0.path).standardizedFileURL.path, $0)
        }
    )
    let results = after.map {
        RootOperationResult(
            rootPath: $0.path,
            displayName: $0.displayName,
            success: true,
            skipped: false,
            message: "submodule updated"
        )
    }
    let previousHeads = beforeByPath.reduce(into: [String: String]()) { heads, item in
        if let head = item.value.headId, !head.isEmpty {
            heads[item.key] = head
        }
    }
    let currentHeads = after.reduce(into: [String: String]()) { heads, root in
        if let head = root.headId, !head.isEmpty {
            heads[root.path] = head
        }
    }
    let previousBranches = beforeByPath.reduce(into: [String: String]()) { branches, item in
        branches[item.key] = item.value.headBranch ?? ""
    }
    let submodulePaths = after.filter(\.isSubmodule).map(\.path)
    return updateSessionRollbackTargets(
        previousHeads: previousHeads,
        currentHeads: currentHeads,
        results: results,
        submoduleRootPaths: submodulePaths,
        previousHeadBranches: previousBranches
    )
    .filter { target in
        after.contains { root in
            root.isSubmodule
                && URL(fileURLWithPath: root.path).standardizedFileURL.path == target.rootPath
        }
    }
}

private func multiRootUpdateViewCommitsAction(
    ranges: [PersistedLogRevisionRange]
) -> FeedbackAction? {
    guard !ranges.isEmpty else { return nil }
    let request = ArborVCSActionRequest(
        kind: .showLogRanges,
        projectPath: projectPath,
        rootPath: ranges.count == 1 ? ranges[0].rootPath : nil,
        shelfName: "",
        logRevisionRanges: ranges
    )
    return FeedbackAction(title: "View Commits", semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

private func multiRootUpdateRollbackRequest(
    targets: [PersistedMultiRootUpdateRollbackTarget],
    kind: ArborVCSActionRequest.Kind = .rollbackMultiRootUpdate
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: kind,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        multiRootUpdateRollbackTargets: targets
    )
}

private func multiRootUpdateRollbackAction(
    targets: [PersistedMultiRootUpdateRollbackTarget],
    title: String = "Rollback Updated Roots"
) -> FeedbackAction? {
    guard !targets.isEmpty else { return nil }
    let request = multiRootUpdateRollbackRequest(targets: targets)
    return FeedbackAction(title: title, semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

private func submoduleUpdateRollbackAction(
    targets: [PersistedMultiRootUpdateRollbackTarget]
) -> FeedbackAction? {
    guard !targets.isEmpty else { return nil }
    let request = ArborVCSActionRequest(
        kind: .rollbackSubmoduleUpdate,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        multiRootUpdateRollbackTargets: targets
    )
    return FeedbackAction(title: "Undo Submodule Update", semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

/// Capture only the state that makes a deinitialized submodule reversible.
/// A dirty or otherwise ambiguous module deliberately gets no Undo action.
nonisolated static func submoduleDeinitUndoContext(
    path: String,
    before: [SubmoduleInfo],
    gitmodulesPresent: Bool,
    gitmodulesContents: String?
) -> PersistedSubmoduleUndo? {
    let normalizedPath = path.trimmingCharacters(in: .whitespacesAndNewlines)
        .replacingOccurrences(of: "./", with: "", options: [.anchored])
    guard !normalizedPath.isEmpty,
          let module = before.first(where: { $0.path == normalizedPath }),
          module.state == .clean,
          !module.dirty,
          !module.headId.isEmpty else {
        return nil
    }
    return PersistedSubmoduleUndo(
        operation: .deinitialize,
        path: normalizedPath,
        expectedHeadID: module.headId,
        expectedGitmodulesPresent: gitmodulesPresent,
        expectedGitmodulesContents: gitmodulesContents
    )
}

/// Capture the clean pre-add boundary. An already occupied path is excluded
/// because its exact filesystem shape is not represented in the durable
/// undo payload and must never be guessed on restore.
nonisolated static func submoduleAddUndoSeed(
    path: String,
    before: [SubmoduleInfo],
    parentHeadID: String?,
    gitmodulesPresent: Bool,
    gitmodulesContents: String?,
    pathExists: Bool
) -> SubmoduleAddUndoSeed? {
    let normalizedPath = path.trimmingCharacters(in: .whitespacesAndNewlines)
        .replacingOccurrences(of: "./", with: "", options: [.anchored])
    guard !normalizedPath.isEmpty,
          !pathExists,
          !before.contains(where: { $0.path == normalizedPath }),
          let parentHeadID,
          !parentHeadID.isEmpty else {
        return nil
    }
    return SubmoduleAddUndoSeed(
        path: normalizedPath,
        parentHeadID: parentHeadID,
        gitmodulesPresent: gitmodulesPresent,
        gitmodulesContents: gitmodulesContents
    )
}

nonisolated static func submoduleAddUndoContext(
    _ seed: SubmoduleAddUndoSeed,
    module: SubmoduleInfo,
    gitmodulesPresent: Bool,
    gitmodulesContents: String?
) -> PersistedSubmoduleUndo? {
    guard module.path == seed.path,
          module.state == .clean,
          !module.dirty,
          !module.headId.isEmpty,
          gitmodulesPresent,
          gitmodulesContents != nil else {
        return nil
    }
    return PersistedSubmoduleUndo(
        operation: .add,
        path: seed.path,
        expectedHeadID: module.headId,
        expectedGitmodulesPresent: gitmodulesPresent,
        expectedGitmodulesContents: gitmodulesContents,
        expectedParentHeadID: seed.parentHeadID,
        restoreGitmodulesPresent: seed.gitmodulesPresent,
        restoreGitmodulesContents: seed.gitmodulesContents
    )
}

/// Capture the clean pre-remove boundary. Existing edits in either the
/// worktree or index are intentionally excluded: restoring a removed
/// submodule must not silently replace a user's staged `.gitmodules` or
/// gitlink change.
nonisolated static func submoduleRemoveUndoSeed(
    repo: Repository,
    path: String,
    before: [SubmoduleInfo],
    parentHeadID: String?,
    gitmodulesPresent: Bool,
    gitmodulesContents: String?
) -> SubmoduleRemoveUndoSeed? {
    let normalizedPath = path.trimmingCharacters(in: .whitespacesAndNewlines)
        .replacingOccurrences(of: "./", with: "", options: [.anchored])
    guard !normalizedPath.isEmpty,
          let module = before.first(where: { $0.path == normalizedPath }),
          module.state == .clean,
          !module.dirty,
          !module.headId.isEmpty,
          let parentHeadID,
          !parentHeadID.isEmpty,
          gitmodulesPresent,
          gitmodulesContents != nil else {
        return nil
    }
    guard (try? repo.submoduleWorktreeHasUntrackedOrIgnoredFiles(path: normalizedPath)) == false else {
        return nil
    }
    let workingTreeClean = (try? repo.runGitCommand(
        command: "diff",
        args: ["--quiet", "--", ".gitmodules"]
    ).exitCode) == 0
    let indexClean = (try? repo.runGitCommand(
        command: "diff",
        args: ["--cached", "--quiet", "--", ".gitmodules"]
    ).exitCode) == 0
    guard workingTreeClean, indexClean else { return nil }
    return SubmoduleRemoveUndoSeed(
        path: normalizedPath,
        parentHeadID: parentHeadID,
        gitlinkID: module.headId,
        gitmodulesPresent: gitmodulesPresent,
        gitmodulesContents: gitmodulesContents
    )
}

nonisolated static func submoduleRemoveUndoContextAfterRemove(
    _ seed: SubmoduleRemoveUndoSeed,
    gitmodulesPresent: Bool,
    gitmodulesContents: String?
) -> PersistedSubmoduleUndo? {
    guard gitmodulesPresent, gitmodulesContents != nil else { return nil }
    return PersistedSubmoduleUndo(
        operation: .remove,
        path: seed.path,
        expectedHeadID: seed.gitlinkID,
        expectedGitmodulesPresent: gitmodulesPresent,
        expectedGitmodulesContents: gitmodulesContents,
        expectedParentHeadID: seed.parentHeadID,
        restoreGitmodulesPresent: seed.gitmodulesPresent,
        restoreGitmodulesContents: seed.gitmodulesContents
    )
}

/// Validate that the deinit command produced the exact expected intermediate
/// state before exposing Undo. This prevents a later index or .gitmodules edit
/// from being mistaken for the original operation's result.
nonisolated static func submoduleDeinitUndoTargetAfterDeinit(
    _ context: PersistedSubmoduleUndo,
    modules: [SubmoduleInfo],
    gitmodulesPresent: Bool,
    gitmodulesContents: String?
) -> PersistedSubmoduleUndo? {
    guard context.operation == .deinitialize,
          let module = modules.first(where: { $0.path == context.path }),
          module.state == .uninitialized,
          !module.dirty,
          module.headId == context.expectedHeadID,
          gitmodulesPresent == context.expectedGitmodulesPresent,
          gitmodulesContents == context.expectedGitmodulesContents else {
        return nil
    }
    return context
}

/// Validate the post-Undo state. The gitlink must still be the same commit,
/// but the nested worktree must now be initialized and clean.
nonisolated static func submoduleDeinitUndoTargetAfterRestore(
    _ context: PersistedSubmoduleUndo,
    modules: [SubmoduleInfo],
    gitmodulesPresent: Bool,
    gitmodulesContents: String?
) -> Bool {
    guard context.operation == .deinitialize,
          let module = modules.first(where: { $0.path == context.path }) else {
        return false
    }
    return module.state == .clean
        && !module.dirty
        && module.headId == context.expectedHeadID
        && gitmodulesPresent == context.expectedGitmodulesPresent
        && gitmodulesContents == context.expectedGitmodulesContents
}

private func submoduleUpdateRollbackNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "git.submodule.update.rollback.\(stableProject)"
}

private func multiRootUpdateNotificationID(partial: Bool) -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return partial
        ? "git.project.partially.updated.\(stableProject)"
        : "git.project.updated.\(stableProject)"
}

private func multiRootUpdateErrorNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "git.project.update.error.\(stableProject)"
}

private func multiRootUpdateRollbackNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "git.project.update.rollback.\(stableProject)"
}

private func updateRootRecoveryActions(
    _ targets: [UpdateRootRecoveryTarget]
) -> [FeedbackAction] {
    var actions: [FeedbackAction] = []
        for target in targets where target.kind == .chooseUpstream {
            guard let branch = target.branch else { continue }
            actions.append(
                FeedbackAction(title: "Choose Upstream · \(target.displayName)") {
                    self.presentUpstreamDialogInRoot(
                        rootPath: target.rootPath,
                        displayName: target.displayName,
                        branch: branch
                    )
                }
            )
        }
    if targets.contains(where: { $0.kind == .openBranches }) {
        actions.append(
            FeedbackAction(title: "Open Branches") {
                self.loadMultiRoots()
                self.showBranchesPopover = true
            }
        )
    }
    return actions
}

private func chooseUpstreamFeedbackAction(for error: Error) -> FeedbackAction? {
    let branch: String
    switch error as? EngineError {
    case let .NoUpstream(name):
        branch = name
    case let .TrackingMissing(name, _):
        branch = name
    default:
        return nil
    }
    guard !branch.isEmpty else { return nil }
    return FeedbackAction(title: "Choose Upstream Branch") {
        self.upstreamLocalBranch = branch
        self.loadRepoData(includeComparisons: false)
        self.showUpstreamDialog = true
    }
}

/// IntelliJ's Update Project dialog exposes RESET as a one-shot action rather
/// than as a persisted update method. Keep the same boundary here: only a
/// single checked-out branch with a configured upstream can use it.
func beginHeadResetDialog() {
    guard isArborVCSActionEnabled(.reset, in: vcsActionContext) else { return }
    let roots = resetHeadRootOptions
    guard !roots.isEmpty else { return }
    let defaultRootPath = repo?.workdir() ?? roots[0].path
    headResetRootPath = roots.first(where: {
        canonicalExternalLogPath($0.path) == canonicalExternalLogPath(defaultRootPath)
    })?.path ?? roots[0].path
    headResetTarget = "HEAD"
    let savedMode = GitResetModeSettings.mode(for: projectPath).engineValue
    headResetMode = savedMode == .keep ? .mixed : savedMode
    showHeadResetDialog = true
}

func validateResetHeadTarget(
    _ target: String,
    rootPath: String
) -> RebasedResetTargetValidation {
    let revision = target.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !revision.isEmpty else {
        return RebasedResetTargetValidation(isValid: false, message: "Enter a revision.")
    }
    guard let repository = try? openRepository(path: rootPath) else {
        return RebasedResetTargetValidation(
            isValid: false,
            message: "The selected Git root is no longer available."
        )
    }
    do {
        let commitID = try repository.revisionCommitId(revision: revision)
        return RebasedResetTargetValidation(
            isValid: true,
            message: "Resolves to \(String(commitID.prefix(12)))."
        )
    } catch {
        return RebasedResetTargetValidation(isValid: false, message: errorMessage(error))
    }
}

/// IntelliJ's Git.Reset accepts an arbitrary revision expression, unlike the
/// separate reset-to-upstream command. Resolve the expression off the main
/// actor, then reuse the existing recovery-aware reset pipeline.
func resetHead(rootPath: String, target: String, mode: ResetMode) {
    let revision = target.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !revision.isEmpty, let repository = try? openRepository(path: rootPath) else {
        feedbackCenter.error(
            "Reset Head failed",
            detail: "The selected Git root or revision is unavailable.",
            nextStep: "Refresh the project and enter a valid revision, then retry."
        )
        return
    }
    Task.detached(priority: .userInitiated) {
        do {
            let commitID = try repository.revisionCommitId(revision: revision)
            await MainActor.run {
                self.runResetCommit(
                    repo: repository,
                    id: commitID,
                    mode: mode,
                    preserveLocalChanges: false
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Reset Head failed",
                    detail: errorMessage(error),
                    nextStep: "Check the revision expression and current Git state, then retry."
                )
            }
        }
    }
}

func resetCurrentBranchToRemote() {
    guard let repository = repo else { return }
    guard multiRoots.count == 1,
          branches.contains(where: { $0.isCurrent }),
          currentSyncStatus?.trackingExists == true,
          !(currentSyncStatus?.upstream.isEmpty ?? true) else {
        feedbackCenter.warning(
            "Reset to Remote Branch unavailable",
            detail: "This action requires one Git root, a checked-out branch, and a tracked remote branch.",
            nextStep: "Fetch the remote or configure an upstream, then retry."
        )
        return
    }
    guard let currentBranch = branches.first(where: { $0.isCurrent })?.name,
          let sync = currentSyncStatus,
          let separator = sync.upstream.firstIndex(of: "/") else {
        feedbackCenter.warning(
            "Reset to Remote Branch unavailable",
            detail: "The current branch has no usable tracked remote branch.",
            nextStep: "Configure an upstream branch, then retry."
        )
        return
    }

    let upstream = sync.upstream
    let remote = String(upstream[..<separator])
    guard !remote.isEmpty, !upstream[upstream.index(after: separator)...].isEmpty else {
        feedbackCenter.warning(
            "Reset to Remote Branch unavailable",
            detail: "The configured upstream is invalid: \(upstream)",
            nextStep: "Choose a valid upstream branch, then retry."
        )
        return
    }

    let saveChoice = GitLocalChangesSavePolicySettings.choice(for: projectPath)
    let alert = NSAlert()
    alert.messageText = "Reset to Remote Branch?"
    alert.informativeText = [
        "Reset \(currentBranch) to \(upstream) after fetching the remote tip.",
        "Local commits on \(currentBranch) will no longer be reachable from that branch.",
        "Uncommitted changes will be preserved with \(saveChoice.title) when needed, and the completed reset can be undone."
    ].joined(separator: "\n\n")
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Reset to Remote Branch")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    let savePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    let cancel = GitCancelHandle()
    beginFeedbackOperation(
        "Reset to Remote Branch",
        cancelHandle: cancel,
        notificationID: resetRecoveryNotificationID()
    )
    Task.detached(priority: .userInitiated) {
        do {
            _ = try repository.fetchRemoteBranchWithOptionsAndAuthAndCancel(
                remote: remote,
                branch: upstream,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel
            )
            guard !Task.isCancelled, !cancel.isCancelled() else {
                throw EngineError.Cancelled
            }
            let remoteID = try repository.revisionCommitId(revision: upstream)
            let recovery = try repository.resetWithRecovery(
                commitId: remoteID,
                mode: .hard,
                savePolicy: savePolicy,
                smart: true,
                force: false
            )
            await MainActor.run {
                let recoveryTarget = recovery.rollbackId.map {
                    PersistedResetRecoveryTarget(
                        rootPath: repository.workdir() ?? "",
                        displayName: URL(fileURLWithPath: repository.workdir() ?? "").lastPathComponent,
                        initialHead: recovery.initialHead,
                        expectedHead: recovery.finalHead,
                        expectedHeadBranch: recovery.finalBranch,
                        mode: .hard,
                        rollbackID: $0
                    )
                }
                self.feedbackCenter.success(
                    "Reset to Remote Branch completed",
                    detail: "\(currentBranch) → \(upstream) · \(String(remoteID.prefix(7)))",
                    additionalActions: recoveryTarget.map {
                        self.resetRecoveryActions(targets: [$0])
                    } ?? [],
                    notificationID: self.resetRecoveryNotificationID(),
                    notificationGroup: .standard
                )
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            await MainActor.run {
                if case let .StashApplyConflict(paths, stashID) = error as? EngineError {
                    self.showStashRestoreConflict(
                        paths,
                        operationName: "Reset to Remote Branch",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repository,
                            rootPath: repository.workdir()
                        ).map { [$0] } ?? [],
                        stashID: stashID
                    )
                } else if case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                    self.presentShelveConflict(
                        name: name,
                        paths: paths,
                        isPop: true,
                        repository: repository,
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repository,
                            rootPath: repository.workdir()
                        ).map { [$0] } ?? []
                    )
                } else if case .Cancelled = error as? EngineError {
                    self.feedbackCenter.warning(
                        "Reset to Remote Branch cancelled",
                        detail: "The remote branch was fetched, but the local branch was not reset.",
                        notificationID: self.resetRecoveryNotificationID(),
                        notificationGroup: .important
                    )
                } else {
                    self.feedbackCenter.error(
                        "Reset to Remote Branch failed",
                        detail: friendlyRemoteError(error),
                        nextStep: "Check the upstream branch and working tree, then retry.",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repository,
                            rootPath: repository.workdir()
                        ).map { [$0] } ?? [],
                        notificationID: self.resetRecoveryNotificationID(),
                        notificationGroup: .important
                    )
                }
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
                if self.isAuthenticationFailure(error) {
                    self.showHostingAuthPrompt = true
                }
            }
        }
    }
}

private enum UpdateRebaseOverMergeDecision: Sendable, Equatable {
    case mergeInstead
    case rebaseAnyway
    case cancel
}

/// IntelliJ's Update Project guard: only roots whose local range contains a
/// non-empty merge commit are called out, and the user can substitute merge
/// for those roots without changing the selected rebase method elsewhere.
private func presentUpdateRebaseOverMergeDialog(
    problematicRoots: [GitRootInfo]
) -> UpdateRebaseOverMergeDecision {
    let alert = NSAlert()
    alert.messageText = "Rebase would replay merge commits"
    let roots = problematicRoots
        .map { "• \($0.displayName) (\($0.relativePath))" }
        .joined(separator: "\n")
    alert.informativeText = "The following Git roots contain merge commits with file changes in the range that would be rebased:\n\n\(roots)\n\nMerging those roots preserves their merge history."
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Merge Instead")
    alert.addButton(withTitle: "Rebase Anyway")
    alert.addButton(withTitle: "Cancel")
    switch alert.runModal() {
    case .alertFirstButtonReturn:
        return .mergeInstead
    case .alertSecondButtonReturn:
        return .rebaseAnyway
    default:
        return .cancel
    }
}

/// Vcs.UpdateProject first presents the platform options dialog unless the
/// project opted out. The selected method is applied only after confirmation;
/// Reset remains a dialog-side action and never persists a new update method.
func requestUpdateProject() {
    guard !isArborBackgroundVCSOperationInProgress(
        feedbackIsRunning: feedbackCenter.isRunning,
        multiRootIsRunning: multiRootRunning || updateProjectDiscoveryRunning
    ) else { return }
    guard repo != nil else { return }
    guard let projectPath, !projectPath.isEmpty else {
        executeMultiRootUpdate(rebase: projectUpdateMethod == .rebase)
        return
    }
    if GitUpdateOptionsDialogSettings.shouldShow(for: projectPath) {
        showUpdateProjectOptions = true
    } else {
        executeMultiRootUpdate(rebase: projectUpdateMethod == .rebase)
    }
}

/// Vcs.UpdateProject / ⌘T：多 root 项目必须一次更新所有 configured upstream，
/// 而不是只更新当前窗口绑定的 root。
func executeMultiRootUpdate(rebase: Bool) {
    guard !isArborBackgroundVCSOperationInProgress(
        feedbackIsRunning: feedbackCenter.isRunning,
        multiRootIsRunning: multiRootRunning || updateProjectDiscoveryRunning
    ) else { return }
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    multiRootUpdateRebaseRootPaths = nil
    guard let projectPath else { return }
    updateProjectDiscoveryRunning = true
    multiRootUpdateRebase = rebase
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    let cancel = GitCancelHandle()
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    Task.detached(priority: .userInitiated) {
        do {
            let roots = try discoverGitRoots(scanRoot: projectPath, maxDepth: nil)
            guard roots.count > 1 else {
                if rebase, let root = roots.first {
                    let preflight = try prepareMultiRootUpdate(
                        scanRoot: projectPath,
                        selectedRootPaths: [root.path],
                        tagMode: tagMode,
                        broker: broker,
                        cancel: cancel
                    )
                    if preflight.problematicRootPaths.contains(root.path) {
                        let decision = await MainActor.run {
                            presentUpdateRebaseOverMergeDialog(problematicRoots: [root])
                        }
                        guard decision != .cancel else {
                            await MainActor.run {
                                self.updateProjectDiscoveryRunning = false
                                self.feedbackCenter.warning(
                                    "Update Project cancelled",
                                    detail: "No working tree changes were applied."
                                )
                            }
                            return
                        }
                        await MainActor.run {
                            self.updateProjectDiscoveryRunning = false
                            self.doPull(
                                nil,
                                rebase: decision == .rebaseAnyway,
                                autoOpenUpdateInfo: true
                            )
                        }
                        return
                    }
                }
                await MainActor.run {
                    self.updateProjectDiscoveryRunning = false
                    self.doPull(nil, rebase: rebase, autoOpenUpdateInfo: true)
                }
                return
            }
            let submoduleRootPaths = Set(roots.filter(\.isSubmodule).map(\.path))
            let rootPaths = roots.map(\.path)
            await MainActor.run {
                self.updateProjectDiscoveryRunning = false
                self.multiRootRunning = true
                self.multiRootUpdateRetryAvailable = true
                self.beginFeedbackOperation(
                    rebase ? "Update Project (rebase)" : "Update Project",
                    cancelHandle: cancel
                )
            }
            let preflight: UpdateProjectPreflight? = rebase
                ? try prepareMultiRootUpdate(
                    scanRoot: projectPath,
                    selectedRootPaths: nil,
                    tagMode: tagMode,
                    broker: broker,
                    cancel: cancel
                )
                : nil
            let decision: UpdateRebaseOverMergeDecision
            if rebase, let preflight, !preflight.problematicRootPaths.isEmpty {
                let problematicRoots = roots.filter {
                    preflight.problematicRootPaths.contains($0.path)
                }
                decision = await MainActor.run {
                    presentUpdateRebaseOverMergeDialog(problematicRoots: problematicRoots)
                }
            } else {
                decision = .rebaseAnyway
            }
            guard decision != .cancel else {
                await MainActor.run {
                    self.multiRootRunning = false
                    self.multiRootUpdateRetryAvailable = false
                    self.feedbackCenter.warning(
                        "Update Project cancelled",
                        detail: "No working tree changes were applied."
                    )
                }
                return
            }
            let rebaseRootPaths: [String]? = decision == .mergeInstead
                ? rootPaths.filter { !(preflight?.problematicRootPaths.contains($0) ?? false) }
                : nil
            await MainActor.run {
                self.multiRootUpdateRebaseRootPaths = rebaseRootPaths.map(Set.init)
            }
            let previousHeads = Self.headCommitIDs(for: rootPaths)
            let previousHeadBranches = Self.headBranchNames(for: rootPaths)
            let results = try runMultiRootUpdateSelectedWithMethodsAndOptions(
                scanRoot: projectPath,
                selectedRootPaths: nil,
                rebase: rebase,
                rebaseRootPaths: rebaseRootPaths,
                prefetchedRootPaths: preflight?.fetchedRootPaths,
                broker: broker,
                cancel: cancel,
                tagMode: tagMode,
                savePolicy: projectSavePolicy
            )
            let currentHeads = Self.headCommitIDs(for: rootPaths)
            let revisionRanges = Self.updateSessionRevisionRanges(
                previousHeads: previousHeads,
                currentHeads: currentHeads,
                results: results
            )
            let updatedFilesCount = Self.updateSessionUpdatedFilesCount(revisionRanges)
            let rollbackTargets = Self.updateSessionRollbackTargets(
                previousHeads: previousHeads,
                currentHeads: currentHeads,
                results: results,
                submoduleRootPaths: Array(submoduleRootPaths),
                previousHeadBranches: previousHeadBranches
            )
            let recoveryTargets = Self.updateRootRecoveryTargets(
                results: results,
                roots: roots.map {
                    UpdateRootRecoveryRoot(
                        path: $0.path,
                        displayName: $0.displayName,
                        isSubmodule: $0.isSubmodule,
                        headBranch: $0.headBranch
                    )
                }
            )
            await MainActor.run {
                self.multiRootResults = results
                self.updateProjectDiscoveryRunning = false
                self.multiRootRunning = false
                for result in results {
                    if result.success || result.skipped {
                        self.multiRootUpdateStashedRoots.remove(result.rootPath)
                    } else if result.message.localizedCaseInsensitiveContains("local changes remain in stash")
                                || result.message.localizedCaseInsensitiveContains("local changes remain in shelf")
                                || result.message.localizedCaseInsensitiveContains("local restore conflicted") {
                        self.multiRootUpdateStashedRoots.insert(result.rootPath)
                    }
                }
                self.loadMultiRoots()
                let failed = results.filter { !$0.success }.count
                let cancelled = results.contains {
                    $0.message.localizedCaseInsensitiveContains("cancelled")
                }
                let hasEligibleRoot = Self.updateProjectHasEligibleRoot(results)
                let updateNotReady = Self.updateProjectIsNotReady(results)
                if !cancelled && updateNotReady {
                    if let notificationID = self.multiRootUpdateNotificationID(partial: false) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    if let notificationID = self.multiRootUpdateNotificationID(partial: true) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    self.operationsViewMode = .roots
                    self.toolWindowMode = .operations
                    self.toolWindowExpanded = true
                    let details = Self.multiRootUpdateFailureDetails(
                        results,
                        submoduleRootPaths: submoduleRootPaths
                    )
                    var recoveryActions = self.updateRootRecoveryActions(recoveryTargets)
                    recoveryActions.insert(
                        FeedbackAction(title: "Open Conflict Workbench") {
                            self.openMultiRootConflictResolver()
                        },
                        at: 0
                    )
                    self.feedbackCenter.error(
                        "Update Project unavailable",
                        detail: details.isEmpty
                            ? "Update Project cannot start because a Git root is not ready."
                            : "Update Project cannot start.\n" + details.joined(separator: "\n"),
                        nextStep: "Resolve the ongoing Git operation or unresolved conflicts, then retry Update Project.",
                        additionalActions: recoveryActions,
                        notificationID: self.multiRootUpdateErrorNotificationID(),
                        notificationGroup: .important
                    )
                    self.feedbackCenter.attachResultRows(
                        feedbackResultRows(from: results),
                        notificationID: self.multiRootUpdateErrorNotificationID()
                    )
                } else if failed == 0 && !cancelled && !hasEligibleRoot {
                    if let notificationID = self.multiRootUpdateNotificationID(partial: false) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    if let notificationID = self.multiRootUpdateNotificationID(partial: true) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    self.operationsViewMode = .roots
                    self.toolWindowMode = .operations
                    self.toolWindowExpanded = true
                    let skippedDetails = Self.skippedUpdateRootDetails(results)
                    let detail = skippedDetails.isEmpty
                        ? "No Git root has a checked-out branch with a configured upstream."
                        : "No Git root can be updated.\n" + skippedDetails.joined(separator: "\n")
                    let recoveryActions = self.updateRootRecoveryActions(recoveryTargets)
                    self.feedbackCenter.error(
                        "Update Project unavailable",
                        detail: detail,
                        nextStep: recoveryActions.isEmpty
                            ? "Check out a branch and configure its upstream, then retry Update Project."
                            : "Configure an upstream or check out a branch, then retry Update Project.",
                        additionalActions: recoveryActions,
                        notificationID: self.multiRootUpdateErrorNotificationID(),
                        notificationGroup: .important
                    )
                    self.feedbackCenter.attachResultRows(
                        feedbackResultRows(from: results),
                        notificationID: self.multiRootUpdateErrorNotificationID()
                    )
                } else if failed == 0 && !cancelled {
                    if let notificationID = self.multiRootUpdateErrorNotificationID() {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    if let notificationID = self.multiRootUpdateNotificationID(partial: true) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
                        ranges: revisionRanges
                    )
                    let recoveryActions = self.updateRootRecoveryActions(recoveryTargets)
                    self.feedbackCenter.success(
                        rebase ? "Update Project completed (rebase)" : "Update Project completed",
                        detail: Self.multiRootUpdateSuccessDetail(
                            results,
                            updatedFilesCount: revisionRanges.isEmpty ? nil : updatedFilesCount
                        ),
                        additionalActions: (viewCommitsAction.map { [$0] } ?? []) + recoveryActions,
                        notificationID: self.multiRootUpdateNotificationID(partial: false),
                        notificationGroup: .standard
                    )
                    self.autoOpenUpdateInfoIfEnabled(revisionRanges)
                } else {
                    if let notificationID = self.multiRootUpdateErrorNotificationID() {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    if let notificationID = self.multiRootUpdateNotificationID(partial: false) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    self.operationsViewMode = .roots
                    self.toolWindowMode = .operations
                    self.toolWindowExpanded = true
                    var details = Self.multiRootUpdateFailureDetails(
                        results,
                        submoduleRootPaths: submoduleRootPaths
                    )
                    if !revisionRanges.isEmpty {
                        details.insert(
                            Self.multiRootUpdateSuccessDetail(
                                results,
                                updatedFilesCount: updatedFilesCount
                            ),
                            at: 0
                        )
                    }
                    let retryPaths = results.filter { !$0.success }.map(\.rootPath)
                    var additionalActions = [FeedbackAction]()
                    if !retryPaths.isEmpty {
                        let retryRequest = makeMultiRootRetryRequest(
                            operation: .update,
                            rootPaths: retryPaths,
                            rebase: rebase,
                            rebaseRootPaths: self.multiRootUpdateRebaseRootPaths.map(Array.init)
                        )
                        additionalActions.append(
                            FeedbackAction(
                                title: "Retry Failed Update Roots",
                                semanticAction: retryRequest
                            ) {
                                self.handleVCSActionRequest(retryRequest)
                            }
                        )
                    }
                    if let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
                        ranges: revisionRanges
                    ) {
                        additionalActions.insert(viewCommitsAction, at: 0)
                    }
                    additionalActions.append(contentsOf: self.updateRootRecoveryActions(recoveryTargets))
                    if let rollbackAction = self.multiRootUpdateRollbackAction(
                        targets: rollbackTargets
                    ) {
                        additionalActions.append(rollbackAction)
                    }
                    self.feedbackCenter.warning(
                        rebase ? "Update Project partially completed (rebase)" : "Update Project partially completed",
                        detail: details.joined(separator: "\n"),
                        nextStep: "Resolve conflicted roots, then continue or abort their Git operation.",
                        actionTitle: "Resolve Conflicts",
                        action: {
                            NotificationCenter.default.post(
                                name: .arborOpenMultiRootConflictResolver,
                                object: nil
                            )
                        },
                        additionalActions: additionalActions,
                        notificationID: self.multiRootUpdateNotificationID(partial: true),
                        notificationGroup: .standard
                    )
                    self.autoOpenUpdateInfoIfEnabled(revisionRanges)
                    self.presentMultiRootUpdateRestoreConflicts(results)
                    self.recoverMultiRootUpdateStashesAfterFailure(results)
                }
            }
        } catch {
            await MainActor.run {
                self.updateProjectDiscoveryRunning = false
                self.multiRootRunning = false
                if let notificationID = self.multiRootUpdateNotificationID(partial: false) {
                    self.feedbackCenter.expire(notificationID: notificationID)
                }
                if let notificationID = self.multiRootUpdateNotificationID(partial: true) {
                    self.feedbackCenter.expire(notificationID: notificationID)
                }
                self.feedbackCenter.error(
                    "Update Project failed",
                    detail: errorMessage(error),
                    nextStep: "检查各 Git root 的 upstream 和认证配置后重试。",
                    notificationID: self.multiRootUpdateErrorNotificationID()
                )
                if self.isAuthenticationFailure(error) {
                    self.showHostingAuthPrompt = true
                }
            }
        }
    }
}

/// Retry only roots that failed in the last Update Project run. Successful
/// roots stay untouched; the engine adds the submodule dependency closure
/// (parent chain plus nested submodule descendants) when needed.
func retryMultiRootUpdateFailedRoots(
    rootPaths: [String]? = nil,
    rebase: Bool? = nil,
    rebaseRootPaths: [String]? = nil,
    priorRevisionRanges: [PersistedLogRevisionRange] = []
) {
    guard let projectPath else { return }
    let selectedRootPaths = rootPaths ?? multiRootResults
        .filter { !$0.success }
        .map(\.rootPath)
    guard !selectedRootPaths.isEmpty else {
        feedbackCenter.warning("Retry unavailable", detail: "There are no failed Git roots to retry.")
        return
    }
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    let cancel = GitCancelHandle()
    let rebase = rebase ?? multiRootUpdateRebase
    let rebaseRootPaths = rebaseRootPaths
        ?? multiRootUpdateRebaseRootPaths.map(Array.init)
    multiRootRunning = true
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation(
        rebase ? "Retry Update Project (rebase)" : "Retry Update Project",
        cancelHandle: cancel,
        notificationID: multiRootUpdateNotificationID(partial: false)
    )
    Task.detached(priority: .userInitiated) {
        do {
            let observedRoots = (try? discoverGitRoots(
                scanRoot: projectPath,
                maxDepth: nil
            )) ?? []
            let observedRootPaths = observedRoots.isEmpty ? selectedRootPaths : observedRoots.map(\.path)
            let submoduleRootPaths = Set(observedRoots.filter(\.isSubmodule).map(\.path))
            let previousHeads = Self.headCommitIDs(for: observedRootPaths)
            let previousHeadBranches = Self.headBranchNames(for: observedRootPaths)
            let retryResults = try runMultiRootUpdateSelectedWithMethodsAndOptions(
                scanRoot: projectPath,
                selectedRootPaths: selectedRootPaths,
                rebase: rebase,
                rebaseRootPaths: rebaseRootPaths,
                prefetchedRootPaths: nil,
                broker: broker,
                cancel: cancel,
                tagMode: tagMode,
                savePolicy: projectSavePolicy
            )
            let currentHeads = Self.headCommitIDs(for: observedRootPaths)
            let revisionRanges = Self.updateSessionRevisionRanges(
                previousHeads: previousHeads,
                currentHeads: currentHeads,
                results: retryResults
            )
            let combinedRevisionRanges = Self.joinedRevisionRanges(
                existing: priorRevisionRanges,
                latest: revisionRanges
            )
            let updatedFilesCount = Self.updateSessionUpdatedFilesCount(combinedRevisionRanges)
            let rollbackTargets = Self.updateSessionRollbackTargets(
                previousHeads: previousHeads,
                currentHeads: currentHeads,
                results: retryResults,
                submoduleRootPaths: Array(submoduleRootPaths),
                previousHeadBranches: previousHeadBranches
            )
            let recoveryTargets = Self.updateRootRecoveryTargets(
                results: retryResults,
                roots: observedRoots.map {
                    UpdateRootRecoveryRoot(
                        path: $0.path,
                        displayName: $0.displayName,
                        isSubmodule: $0.isSubmodule,
                        headBranch: $0.headBranch
                    )
                }
            )
            await MainActor.run {
                var mergedResults = self.multiRootResults
                for retryResult in retryResults {
                    if let index = mergedResults.firstIndex(where: { $0.rootPath == retryResult.rootPath }) {
                        mergedResults[index] = retryResult
                    } else {
                        mergedResults.append(retryResult)
                    }
                }
                self.multiRootResults = mergedResults
                self.multiRootRunning = false
                for result in retryResults {
                    if result.success || result.skipped {
                        self.multiRootUpdateStashedRoots.remove(result.rootPath)
                    } else if result.message.localizedCaseInsensitiveContains("local changes remain in stash")
                                || result.message.localizedCaseInsensitiveContains("local changes remain in shelf")
                                || result.message.localizedCaseInsensitiveContains("local restore conflicted") {
                        self.multiRootUpdateStashedRoots.insert(result.rootPath)
                    }
                }
                self.loadMultiRoots()
                let failures = retryResults.filter { !$0.success }
                let cancelled = retryResults.contains {
                    $0.message.localizedCaseInsensitiveContains("cancelled")
                }
                if failures.isEmpty && !cancelled {
                    if let notificationID = self.multiRootUpdateErrorNotificationID() {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    if let notificationID = self.multiRootUpdateNotificationID(partial: true) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
                        ranges: combinedRevisionRanges
                    )
                    let recoveryActions = self.updateRootRecoveryActions(recoveryTargets)
                    self.feedbackCenter.success(
                        rebase ? "Retry Update Project completed (rebase)" : "Retry Update Project completed",
                        detail: Self.multiRootUpdateSuccessDetail(
                            retryResults,
                            updatedFilesCount: combinedRevisionRanges.isEmpty ? nil : updatedFilesCount
                        ),
                        additionalActions: (viewCommitsAction.map { [$0] } ?? []) + recoveryActions,
                        notificationID: self.multiRootUpdateNotificationID(partial: false),
                        notificationGroup: .standard
                    )
                    self.autoOpenUpdateInfoIfEnabled(combinedRevisionRanges)
                } else {
                    if let notificationID = self.multiRootUpdateErrorNotificationID() {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    if let notificationID = self.multiRootUpdateNotificationID(partial: false) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    self.operationsViewMode = .roots
                    self.toolWindowMode = .operations
                    self.toolWindowExpanded = true
                    var details = Self.multiRootUpdateFailureDetails(
                        retryResults,
                        submoduleRootPaths: submoduleRootPaths
                    )
                    if !combinedRevisionRanges.isEmpty {
                        details.insert(
                            Self.multiRootUpdateSuccessDetail(
                                retryResults,
                                updatedFilesCount: updatedFilesCount
                            ),
                            at: 0
                        )
                    }
                    var additionalActions = [FeedbackAction]()
                    if !failures.isEmpty {
                        let retryPaths = failures.map(\.rootPath)
                        let retryRequest = makeMultiRootRetryRequest(
                            operation: .update,
                            rootPaths: retryPaths,
                            rebase: rebase,
                            rebaseRootPaths: self.multiRootUpdateRebaseRootPaths.map(Array.init)
                        )
                        additionalActions.append(
                            FeedbackAction(
                                title: "Retry Failed Update Roots",
                                semanticAction: retryRequest
                            ) {
                                self.handleVCSActionRequest(retryRequest)
                            }
                        )
                    }
                    if let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
                        ranges: combinedRevisionRanges
                    ) {
                        additionalActions.insert(viewCommitsAction, at: 0)
                    }
                    additionalActions.append(contentsOf: self.updateRootRecoveryActions(recoveryTargets))
                    if let rollbackAction = self.multiRootUpdateRollbackAction(
                        targets: rollbackTargets
                    ) {
                        additionalActions.append(rollbackAction)
                    }
                    self.feedbackCenter.warning(
                        rebase ? "Retry Update Project partially completed (rebase)" : "Retry Update Project partially completed",
                        detail: details.joined(separator: "\n"),
                        nextStep: "Resolve the affected roots, then retry only the remaining failures.",
                        actionTitle: "Resolve Conflicts",
                        action: {
                            NotificationCenter.default.post(
                                name: .arborOpenMultiRootConflictResolver,
                                object: nil
                            )
                        },
                        additionalActions: additionalActions,
                        notificationID: self.multiRootUpdateNotificationID(partial: true),
                        notificationGroup: .standard
                    )
                    self.autoOpenUpdateInfoIfEnabled(combinedRevisionRanges)
                    self.presentMultiRootUpdateRestoreConflicts(retryResults)
                    self.recoverMultiRootUpdateStashesAfterFailure(retryResults)
                }
            }
        } catch {
            await MainActor.run {
                self.multiRootRunning = false
                if let notificationID = self.multiRootUpdateNotificationID(partial: false) {
                    self.feedbackCenter.expire(notificationID: notificationID)
                }
                if let notificationID = self.multiRootUpdateNotificationID(partial: true) {
                    self.feedbackCenter.expire(notificationID: notificationID)
                }
                self.feedbackCenter.error(
                    "Retry Update Project failed",
                    detail: errorMessage(error),
                    nextStep: "Check the selected Git roots and retry after resolving their current state.",
                    notificationID: self.multiRootUpdateErrorNotificationID()
                )
                if self.isAuthenticationFailure(error) {
                    self.showHostingAuthPrompt = true
                }
            }
        }
    }
}

/// Roll back every root that advanced during one compound Update Project run.
/// Targets are expected-HEAD guarded and ordered deepest-first so a detached
/// submodule is restored before its parent gitlink. A later user change or a
/// local edit that would be overwritten leaves only that target retryable.
func rollbackMultiRootUpdate(
    _ targets: [PersistedMultiRootUpdateRollbackTarget],
    completionTitle: String = "Update Project rollback completed",
    operationTitle: String = "Rollback Update Project",
    notificationID: String? = nil,
    rollbackKind: ArborVCSActionRequest.Kind = .rollbackMultiRootUpdate
) {
    guard !targets.isEmpty else { return }
    let stableNotificationID = notificationID ?? multiRootUpdateRollbackNotificationID()
    beginFeedbackOperation(
        operationTitle,
        notificationID: stableNotificationID
    )
    Task.detached(priority: .userInitiated) {
        var failures: [String] = []
        var remaining: [PersistedMultiRootUpdateRollbackTarget] = []
        for target in targets {
            do {
                let rootRepo = try openRepository(path: target.rootPath)
                guard try rootRepo.operationState() == nil else {
                    throw NSError(
                        domain: "Arbor.MultiRootUpdateRollback",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "A Git operation is still in progress."]
                    )
                }
                try rootRepo.restoreHeadIfExpectedWithIgnoredPathsAndBranch(
                    initialCommitId: target.initialHead,
                    expectedCommitId: target.expectedHead,
                    expectedHeadBranch: target.expectedHeadBranch,
                    ignoredPaths: target.ignoredPaths
                )
            } catch {
                failures.append("\(target.displayName): \(errorMessage(error))")
                remaining.append(target)
            }
        }
        let rollbackFailures = failures
        let rollbackRemaining = remaining
        await MainActor.run {
            self.loadMultiRoots()
            if rollbackFailures.isEmpty {
                self.feedbackCenter.success(
                    completionTitle,
                    detail: "Restored \(targets.count) updated root\(targets.count == 1 ? "" : "s").",
                    notificationID: stableNotificationID
                )
            } else {
                let retryRequest = self.multiRootUpdateRollbackRequest(
                    targets: rollbackRemaining,
                    kind: rollbackKind
                )
                self.feedbackCenter.warning(
                    "\(operationTitle) partially failed",
                    detail: rollbackFailures.joined(separator: "\n"),
                    nextStep: "Review the affected roots and retry the remaining rollback targets.",
                    additionalActions: [
                        FeedbackAction(
                            title: "Retry Remaining Rollback",
                            semanticAction: retryRequest
                        ) {
                            self.handleVCSActionRequest(retryRequest)
                        }
                    ],
                    notificationID: stableNotificationID,
                    notificationGroup: .standard
                )
            }
        }
    }
}

/// A completed merge can be rolled back without discarding unrelated local
/// edits. The request carries the exact pre-merge HEAD and repository handle;
/// the action is posted through NotificationCenter because ContentView is a
/// SwiftUI value type and must not be captured by a long-lived feedback action.
struct MergeRollbackRequest {
    let repo: Repository
    let initialHead: String
    let expectedHead: String
    let branch: String
}

struct MergeDeleteBranchRequest {
    let repo: Repository
    let branch: String
    let rootPath: String?
}

func handleMergeDeleteNotification(_ notification: Notification) {
    guard let request = notification.object as? MergeDeleteBranchRequest else { return }
    if let rootPath = request.rootPath {
        deleteBranchInRoot(rootPath: rootPath, name: request.branch)
    } else if projectRepo === request.repo {
        branchDelete(request.branch)
    } else {
        feedbackCenter.error(
            "Delete merged branch unavailable",
            detail: "The original repository is no longer active."
        )
    }
}

nonisolated func canProposeDeleteMergedBranch(
    repo: Repository,
    branch: String,
    protectedPatterns: [String]
) -> Bool {
    guard !branch.isEmpty,
          !GitProtectedBranchRules.matches(branch, patterns: protectedPatterns),
          let localBranches = try? repo.branchList(),
          let source = localBranches.first(where: { $0.name == branch }) else {
        return false
    }
    return !source.isCurrent
}

private func confirmAndDeleteMultiRootMergedBranch(
    name: String,
    selectedRootPaths: Set<String>
) {
    let branchName = name.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !branchName.isEmpty else { return }
    guard !GitProtectedBranchRules.matches(
        branchName,
        patterns: effectiveProtectedBranchPatterns
    ) else {
        feedbackCenter.warning(
            "Delete merged branch unavailable",
            detail: "The branch is protected: \(branchName)",
            nextStep: "Remove the branch from the protected-branch rules before deleting it."
        )
        return
    }

    let candidates = multiRootBranchSnapshots.compactMap { snapshot -> MultiRootMergeDeleteCandidate? in
        guard snapshot.branches.contains(where: {
            $0.name == branchName && !$0.isCurrent
        }) else { return nil }
        return MultiRootMergeDeleteCandidate(
            rootPath: snapshot.rootPath,
            displayName: snapshot.displayName
        )
    }
    let targets = multiRootMergeDeleteTargets(
        selectedRootPaths: selectedRootPaths,
        candidates: candidates
    )
    guard !targets.isEmpty else {
        feedbackCenter.warning(
            "Delete merged branch unavailable",
            detail: "No selected Git root still contains a non-current local branch named \(branchName).",
            nextStep: "Refresh Git state and retry the action."
        )
        return
    }

    let rootList = targets.map { target in
        let displayName = target.displayName.isEmpty ? target.rootPath : target.displayName
        return "• \(displayName) — \(target.rootPath)"
    }.joined(separator: "\n")
    let alert = NSAlert()
    alert.messageText = "Delete merged branch \(branchName) from \(targets.count) Git root\(targets.count == 1 ? "" : "s")?"
    alert.informativeText = "This removes the local branch reference in:\n\(rootList)"
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    deleteMultiRootBranch(
        name: branchName,
        selectedRootPaths: Set(targets.map(\.rootPath)),
        allowForceDelete: false
    )
}

private func postMergeRollbackAction(
    repo: Repository,
    initialHead: String,
    expectedHead: String,
    branch: String
) -> (() -> Void) {
    {
        NotificationCenter.default.post(
            name: .arborRollbackMerge,
            object: MergeRollbackRequest(
                repo: repo,
                initialHead: initialHead,
                expectedHead: expectedHead,
                branch: branch
            )
        )
    }
}

private func postMergeDeleteAction(
    repo: Repository,
    branch: String,
    rootPath: String? = nil
) -> (() -> Void) {
    {
        NotificationCenter.default.post(
            name: .arborDeleteMergedBranch,
            object: MergeDeleteBranchRequest(
                repo: repo,
                branch: branch,
                rootPath: rootPath
            )
        )
    }
}

private func multiRootMergeDeleteRequest(
    branch: String,
    rootPaths: [String]
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .deleteMultiRootMergeBranch,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        multiRootMergeDeleteBranchName: branch,
        multiRootMergeDeleteRootPaths: rootPaths
    )
}

private func multiRootMergeDeleteAction(
    branch: String,
    rootPaths: [String]
) -> FeedbackAction? {
    let normalizedRootPaths = Array(Set(rootPaths)).sorted()
    guard !branch.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
          !normalizedRootPaths.isEmpty else { return nil }
    let request = multiRootMergeDeleteRequest(
        branch: branch,
        rootPaths: normalizedRootPaths
    )
    return FeedbackAction(title: "Delete branch", semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

private func multiRootMergeDeleteNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.multi-root-merge.delete-branch.\(stableProject)"
}

private func branchDeleteRecoveryTargets(
    from contexts: [BranchDeleteRecoveryContext]
) -> [PersistedBranchDeleteRecoveryTarget]? {
    let targets = contexts.compactMap { context -> PersistedBranchDeleteRecoveryTarget? in
        guard let rootPath = context.rootPath ?? context.repo.workdir() else { return nil }
        return PersistedBranchDeleteRecoveryTarget(
            rootPath: URL(fileURLWithPath: rootPath).standardizedFileURL.path,
            branchName: context.preview.branchName,
            tipID: context.preview.tipId,
            upstream: context.preview.upstream,
            baseBranches: context.preview.baseBranches,
            unmergedCommits: context.preview.unmergedCommits.map {
                PersistedBranchDeleteCommit(
                    id: $0.id,
                    shortID: $0.shortId,
                    summary: $0.summary,
                    time: $0.time
                )
            }
        )
    }
    guard targets.count == contexts.count, !targets.isEmpty else { return nil }
    return targets.sorted {
        if $0.rootPath != $1.rootPath { return $0.rootPath < $1.rootPath }
        if $0.branchName != $1.branchName { return $0.branchName < $1.branchName }
        return $0.tipID < $1.tipID
    }
}

private func normalizedBranchDeleteRecoveryTargets(
    _ targets: [PersistedBranchDeleteRecoveryTarget]
) -> [PersistedBranchDeleteRecoveryTarget]? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let projectRoot = URL(fileURLWithPath: projectPath).standardizedFileURL.path
    let normalizedTargets = targets.map { target in
        PersistedBranchDeleteRecoveryTarget(
            rootPath: URL(fileURLWithPath: target.rootPath).standardizedFileURL.path,
            branchName: target.branchName,
            tipID: target.tipID,
            upstream: target.upstream,
            baseBranches: target.baseBranches,
            unmergedCommits: target.unmergedCommits
        )
    }.sorted {
        if $0.rootPath != $1.rootPath { return $0.rootPath < $1.rootPath }
        if $0.branchName != $1.branchName { return $0.branchName < $1.branchName }
        return $0.tipID < $1.tipID
    }
    guard !normalizedTargets.isEmpty,
          normalizedTargets.allSatisfy({ target in
              !target.branchName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                  && !target.tipID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                  && (target.rootPath == projectRoot || target.rootPath.hasPrefix(projectRoot + "/"))
          }) else {
        return nil
    }
    return normalizedTargets
}

private func branchDeleteRestoreRequest(
    targets: [PersistedBranchDeleteRecoveryTarget]
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .restoreDeletedBranches,
        projectPath: projectPath,
        rootPath: targets.count == 1 ? targets[0].rootPath : nil,
        shelfName: "",
        branchDeleteRecoveryTargets: targets
    )
}

private func branchDeleteViewCommitsAction(
    contexts: [BranchDeleteRecoveryContext]
) -> FeedbackAction? {
    guard contexts.contains(where: { !$0.preview.unmergedCommits.isEmpty }),
          let targets = branchDeleteRecoveryTargets(from: contexts) else {
        return nil
    }
    let request = ArborVCSActionRequest(
        kind: .viewDeletedBranchCommits,
        projectPath: projectPath,
        rootPath: targets.count == 1 ? targets[0].rootPath : nil,
        shelfName: "",
        branchDeleteRecoveryTargets: targets
    )
    return FeedbackAction(title: "View Commits", semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

private func branchDeleteRecoveryActions(
    contexts: [BranchDeleteRecoveryContext]
) -> [FeedbackAction] {
    [
        branchDeleteRestoreAction(contexts: contexts),
        branchDeleteViewCommitsAction(contexts: contexts)
    ].compactMap { $0 }
}

private func branchDeleteRestoreAction(
    contexts: [BranchDeleteRecoveryContext],
    title: String = "Restore"
) -> FeedbackAction? {
    guard let targets = branchDeleteRecoveryTargets(from: contexts) else { return nil }
    return branchDeleteRestoreAction(
        targets: targets,
        title: title
    )
}

private func branchDeleteRestoreAction(
    targets: [PersistedBranchDeleteRecoveryTarget],
    title: String = "Restore"
) -> FeedbackAction? {
    guard !targets.isEmpty else { return nil }
    let request = branchDeleteRestoreRequest(targets: targets)
    return FeedbackAction(title: title, semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

private func branchDeleteNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.branch-deleted.\(stableProject)"
}

func executeMultiRootCheckout(reference: String, detach: Bool) {
    performMultiRootCheckout(reference: reference, detach: detach, mode: .normal, offerRecovery: true)
}

private func performMultiRootCheckout(
    reference: String,
    detach: Bool,
    mode: MultiRootCheckoutMode,
    offerRecovery: Bool
) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    guard let projectPath, !reference.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        feedbackCenter.warning("Checkout cancelled", detail: "A branch, tag, or revision is required.")
        return
    }
    multiRootRunning = true
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation(mode == .normal ? "Multi-root checkout" : "Multi-root \(mode == .smart ? "Smart" : "Force") Checkout")
    Task.detached(priority: .userInitiated) {
        do {
            let initialRoots = try Arbor.discoverGitRoots(scanRoot: projectPath, maxDepth: nil)
            let initialSnapshots = try Arbor.listMultiRootBranches(scanRoot: projectPath)
            let savedChangeIDsBefore = mode == .smart
                ? Self.savedChangeIDsByRoot(rootPaths: initialRoots.map(\.path))
                : (stashes: [:], shelves: [:])
            let results = try Arbor.runMultiRootCheckoutWithPolicy(
                scanRoot: projectPath,
                reference: reference,
                detach: detach,
                mode: mode,
                savePolicy: projectSavePolicy
            )
            let newSavedChangeIDs = mode == .smart
                ? Self.newSavedChangeIDsByRoot(
                    rootPaths: results.map(\.rootPath),
                    before: savedChangeIDsBefore,
                    stashMessagePrefix: "Arbor: Smart Checkout to \(reference)",
                    shelfNamePrefix: "Arbor: Smart Checkout to \(reference)"
                )
                : (stashes: [:], shelves: [:])
            await MainActor.run {
                self.multiRootResults = results
                self.multiRootRunning = false
                let failures = results.filter { !$0.success }
                let initialRootsByPath = Dictionary(uniqueKeysWithValues: initialRoots.map { ($0.path, $0) })
                let initialSnapshotsByPath = Dictionary(uniqueKeysWithValues: initialSnapshots.map { ($0.rootPath, $0) })
                let finalRootsByPath: [String: GitRootInfo] = (try? Arbor.discoverGitRoots(
                    scanRoot: projectPath,
                    maxDepth: nil
                ))
                .map { Dictionary(uniqueKeysWithValues: $0.map { ($0.path, $0) }) } ?? [:]
                let successfulTargets: [MultiRootBranchTarget] = mode == .normal
                    ? results
                        .filter { $0.success && !$0.skipped }
                        .compactMap { result in
                            guard let root = initialRootsByPath[result.rootPath],
                                  let finalRoot = finalRootsByPath[result.rootPath],
                                  let expectedHead = finalRoot.headId else { return nil }
                            return MultiRootBranchTarget(
                                rootPath: root.path,
                                checkedOut: true,
                                previousBranch: root.headBranch,
                                previousHead: root.headId,
                                expectedHead: expectedHead,
                                expectedBranch: finalRoot.headBranch,
                                createdBranch: createdCheckoutBranch(
                                    reference: reference,
                                    detach: detach,
                                    snapshot: initialSnapshotsByPath[result.rootPath]
                                )
                            )
                        }
                    : []
                if failures.isEmpty {
                    self.feedbackCenter.success(
                        mode == .normal ? "Multi-root checkout complete" : "Multi-root checkout restored",
                        detail: "\(results.count) roots · \(reference)"
                    )
                    self.loadMultiRoots()
                } else if mode == .normal && offerRecovery,
                          failures.contains(where: isCheckoutOverwriteFailure) {
                    self.presentMultiRootCheckoutRecovery(
                        reference: reference,
                        detach: detach,
                        failures: failures,
                        successfulTargets: successfulTargets
                    )
                } else if mode == .normal && offerRecovery && !successfulTargets.isEmpty {
                    self.presentMultiRootCheckoutPartialResult(
                        reference: reference,
                        failures: failures,
                        successfulTargets: successfulTargets
                    )
                } else {
                    let savedChangesActions = results.compactMap { result -> FeedbackAction? in
                        if let stashID = newSavedChangeIDs.stashes[result.rootPath] {
                            return self.savedChangesFeedbackAction(
                                kind: .stash,
                                identifier: stashID,
                                rootPath: result.rootPath
                            )
                        }
                        if let shelfName = newSavedChangeIDs.shelves[result.rootPath] {
                            return self.savedChangesFeedbackAction(
                                kind: .shelf,
                                identifier: shelfName,
                                rootPath: result.rootPath
                            )
                        }
                        return nil
                    }
                    self.feedbackCenter.error(
                        mode == .normal ? "Multi-root checkout failed" : "Multi-root checkout paused",
                        detail: failures.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n"),
                        nextStep: "Resolve the affected roots, then retry checkout.",
                        additionalActions: savedChangesActions
                    )
                    self.loadMultiRoots()
                    self.presentMultiRootShelfRestoreConflicts(results)
                }
            }
        } catch {
            await MainActor.run {
                self.multiRootRunning = false
                self.feedbackCenter.error(
                    "Multi-root checkout failed",
                    detail: errorMessage(error),
                    nextStep: "Resolve the affected roots, then retry checkout."
                )
            }
        }
    }
}

private func presentMultiRootCheckoutRecovery(
    reference: String,
    detach: Bool,
    failures: [RootOperationResult],
    successfulTargets: [MultiRootBranchTarget] = []
) {
    let alert = NSAlert()
    alert.messageText = "Local changes would be overwritten in multiple Git roots"
    alert.informativeText = failures
        .map { "\($0.displayName): \($0.message)" }
        .joined(separator: "\n")
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Smart Checkout All")
    alert.addButton(withTitle: "Force Checkout All")
    alert.addButton(withTitle: "Cancel")
    switch alert.runModal() {
    case .alertFirstButtonReturn:
        performMultiRootCheckout(
            reference: reference,
            detach: detach,
            mode: .smart,
            offerRecovery: false
        )
    case .alertSecondButtonReturn:
        performMultiRootCheckout(
            reference: reference,
            detach: detach,
            mode: .force,
            offerRecovery: false
        )
    default:
        if successfulTargets.isEmpty {
            feedbackCenter.warning("Checkout cancelled", detail: "Local changes were kept in every root.")
        } else {
            presentMultiRootCheckoutPartialResult(
                reference: reference,
                failures: failures,
                successfulTargets: successfulTargets
            )
        }
    }
}

private func presentMultiRootCheckoutPartialResult(
    reference: String,
    failures: [RootOperationResult],
    successfulTargets: [MultiRootBranchTarget]
) {
    operationsViewMode = .roots
    toolWindowMode = .operations
    toolWindowExpanded = true
    let rollbackRequest = ArborVCSActionRequest(
        kind: .rollbackMultiRootCheckout,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        checkoutReference: reference,
        checkoutTargets: successfulTargets.map(PersistedMultiRootCheckoutTarget.init)
    )
    feedbackCenter.warning(
        "Multi-root checkout partially completed",
        detail: failures.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n"),
        nextStep: "Keep the successful roots checked out or rollback them to their previous HEAD.",
        additionalActions: [
            FeedbackAction(
                title: "Rollback Successful Roots",
                semanticAction: rollbackRequest
            ) {
                self.handleVCSActionRequest(rollbackRequest)
            }
        ],
        notificationID: multiRootCheckoutRollbackNotificationID()
    )
    loadMultiRoots()
}

private func multiRootCheckoutRollbackNotificationID() -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableProject = URL(fileURLWithPath: projectPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.multi-root-checkout.rollback.\(stableProject)"
}

private func makeMultiRootRetryRequest(
    operation: ArborVCSActionRequest.MultiRootRetryOperation,
    rootPaths: [String],
    changePath: String? = nil,
    changePaths: [PersistedMultiRootChangePath]? = nil,
    updateRootPaths: [String]? = nil,
    rebase: Bool? = nil,
    rebaseRootPaths: [String]? = nil,
    tagMode: PushDialogTagMode? = nil,
    skipHooks: Bool? = nil,
    force: Bool? = nil,
    forceWithLease: Bool? = nil,
    commitRetry: PersistedMultiRootCommitRetry? = nil,
    logRevisionRanges: [PersistedLogRevisionRange]? = nil,
    priorResultRows: [FeedbackResultRow]? = nil
) -> ArborVCSActionRequest {
    let persistedTagMode = tagMode.map { mode -> ArborVCSActionRequest.MultiRootPushTagMode in
        switch mode {
        case .all: .all
        case .currentBranch: .currentBranch
        }
    }
    return ArborVCSActionRequest(
        kind: .retryMultiRootOperation,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        multiRootRetryOperation: operation,
        multiRootRetryRootPaths: rootPaths,
        multiRootRetryPath: changePath,
        multiRootRetryChangePaths: changePaths,
        multiRootRetryUpdateRootPaths: updateRootPaths,
        multiRootRetryRebase: rebase,
        multiRootRetryRebaseRootPaths: rebaseRootPaths,
        multiRootRetryLogRevisionRanges: logRevisionRanges,
        multiRootRetryResultRows: priorResultRows,
        multiRootPushTagMode: persistedTagMode,
        multiRootPushSkipHooks: skipHooks,
        multiRootPushForce: force,
        multiRootPushForceWithLease: forceWithLease,
        multiRootCommitRetry: commitRetry
    )
}

private func multiRootChangesRetryFeedbackAction(
    operation: ArborVCSActionRequest.MultiRootRetryOperation,
    rootPath: String,
    path: String?
) -> FeedbackAction {
    let request = makeMultiRootRetryRequest(
        operation: operation,
        rootPaths: [rootPath],
        changePath: path
    )
    let title: String = switch operation {
    case .stage: "Retry Stage"
    case .unstage: "Retry Unstage"
    case .stageAll: "Retry Stage All"
    case .unstageAll: "Retry Unstage All"
    default: "Retry Changes"
    }
    let identity = [operation.rawValue, rootPath, path ?? "all"]
        .joined(separator: "|")
    return FeedbackAction(
        id: "retry-multi-root-changes:\(identity)",
        title: title,
        semanticAction: request
    ) {
        handleVCSActionRequest(request)
    }
}

private func normalizedMultiRootChangePaths(
    _ paths: [PersistedMultiRootChangePath]
) -> [PersistedMultiRootChangePath] {
    var seen = Set<String>()
    return paths
        .filter { !$0.rootPath.isEmpty && !$0.path.isEmpty }
        .filter { seen.insert("\($0.rootPath)\u{1f}\($0.path)").inserted }
        .sorted {
            if $0.rootPath == $1.rootPath { return $0.path < $1.path }
            return $0.rootPath < $1.rootPath
        }
}

private func multiRootChangesBatchRetryFeedbackAction(
    operation: ArborVCSActionRequest.MultiRootRetryOperation,
    changePaths: [PersistedMultiRootChangePath]
) -> FeedbackAction {
    let normalizedPaths = normalizedMultiRootChangePaths(changePaths)
    let rootPaths = Array(Set(normalizedPaths.map(\.rootPath))).sorted()
    let request = makeMultiRootRetryRequest(
        operation: operation,
        rootPaths: rootPaths,
        changePaths: normalizedPaths
    )
    let title: String = switch operation {
    case .stage: "Retry Selected Stage"
    case .unstage: "Retry Selected Unstage"
    default: "Retry Selected Changes"
    }
    let identity = normalizedPaths
        .map { "\($0.rootPath)\u{1f}\($0.path)" }
        .joined(separator: "|")
    return FeedbackAction(
        id: "retry-multi-root-changes-batch:\(operation.rawValue):\(identity)",
        title: title,
        semanticAction: request
    ) {
        handleVCSActionRequest(request)
    }
}

private func multiRootChangesMutationNotificationID(
    operation: ArborVCSActionRequest.MultiRootRetryOperation,
    rootPath: String,
    path: String?
) -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableComponent: (String) -> String = { value in
        value
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: ":", with: "_")
            .replacingOccurrences(of: "|", with: "_")
    }
    return [
        "arbor.multi-root-changes",
        operation.rawValue,
        stableComponent(URL(fileURLWithPath: projectPath).standardizedFileURL.path),
        stableComponent(rootPath),
        stableComponent(path ?? "all")
    ].joined(separator: ".")
}

private func multiRootChangesBatchMutationNotificationID(
    operation: ArborVCSActionRequest.MultiRootRetryOperation,
    changePaths: [PersistedMultiRootChangePath]
) -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let stableComponent: (String) -> String = { value in
        value
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: ":", with: "_")
            .replacingOccurrences(of: "|", with: "_")
            .replacingOccurrences(of: "\u{1f}", with: "_")
    }
    let identity = normalizedMultiRootChangePaths(changePaths)
        .map { "\(stableComponent($0.rootPath))_\(stableComponent($0.path))" }
        .joined(separator: "_")
    return [
        "arbor.multi-root-changes.batch",
        operation.rawValue,
        stableComponent(URL(fileURLWithPath: projectPath).standardizedFileURL.path),
        identity
    ].joined(separator: ".")
}

private func multiRootCommitRetryFeedbackAction(
    rootPaths: [String],
    message: String,
    options: MultiRootCommitOptions,
    pushAfterCommit: Bool = false,
    pushRootPaths: [String] = [],
    selectedChanges: [MultiRootChangeSelection]? = nil
) -> FeedbackAction {
    let normalizedSelectedChanges = selectedChanges.map(normalizedMultiRootCommitSelections)
    let request = makeMultiRootRetryRequest(
        operation: .commit,
        rootPaths: rootPaths,
        commitRetry: PersistedMultiRootCommitRetry(
            message: message,
            options: options,
            pushAfterCommit: pushAfterCommit,
            pushRootPaths: pushRootPaths,
            selectedPaths: normalizedSelectedChanges?.map(PersistedMultiRootChangePath.init)
        )
    )
    return FeedbackAction(
        id: "retry-multi-root-commit:\(rootPaths.sorted().joined(separator: "|")):\(normalizedSelectedChanges?.map(\.id).joined(separator: "|") ?? "roots")",
        title: "Retry Failed Commits",
        semanticAction: request
    ) {
        handleVCSActionRequest(request)
    }
}

private nonisolated func normalizedMultiRootCommitSelections(
    _ selections: [MultiRootChangeSelection]
) -> [MultiRootChangeSelection] {
    var seen = Set<String>()
    return selections
        .filter {
            !$0.rootPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                && !$0.path.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        }
        .filter { seen.insert($0.id).inserted }
        .sorted {
            if $0.rootPath == $1.rootPath { return $0.path < $1.path }
            return $0.rootPath < $1.rootPath
        }
}

private nonisolated func makeLiveMultiRootCommitSelections(
    _ selections: [MultiRootChangeSelection]
) -> [MultiRootCommitSelection] {
    let normalized = normalizedMultiRootCommitSelections(selections)
    let grouped = Dictionary(grouping: normalized, by: \.rootPath)
    return grouped.keys.sorted().map { rootPath in
        let paths = grouped[rootPath, default: []]
            .map(\.path)
        return MultiRootCommitSelection(
            rootPath: rootPath,
            paths: Array(Set(paths)).sorted()
        )
    }
}

private func multiRootCommitPushFeedbackAction(rootPaths: [String]) -> FeedbackAction {
    let normalizedPaths = Array(Set(rootPaths)).sorted()
    let request = makeMultiRootRetryRequest(
        operation: .pushAfterCommit,
        rootPaths: normalizedPaths
    )
    return FeedbackAction(
        id: "push-multi-root-committed:\(normalizedPaths.joined(separator: "|"))",
        title: "Push Committed Roots",
        semanticAction: request
    ) {
        self.beginMultiRootCommitPushOptions(rootPaths: normalizedPaths)
    }
}

