func rollbackMultiRootCheckout(
    _ targets: [MultiRootBranchTarget],
    reference: String
) {
    guard !targets.isEmpty else { return }
    let notificationID = multiRootCheckoutRollbackNotificationID()
    let fullRetryRequest = ArborVCSActionRequest(
        kind: .rollbackMultiRootCheckout,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        checkoutReference: reference,
        checkoutTargets: targets.map(PersistedMultiRootCheckoutTarget.init)
    )
    beginFeedbackOperation(
        "Rollback multi-root checkout",
        notificationID: notificationID
    )
    Task.detached(priority: .userInitiated) {
        do {
            let results = try Arbor.restoreMultiRootCheckout(targets: targets)
            await MainActor.run {
                self.multiRootResults = results
                self.loadMultiRoots()
                let failures = results.filter { !$0.success }
                if failures.isEmpty {
                    self.feedbackCenter.success(
                        "Checkout rollback completed",
                        detail: reference,
                        notificationID: notificationID,
                        notificationGroup: .standard
                    )
                } else {
                    let failedRootPaths = Set(failures.map(\.rootPath))
                    let remainingTargets = targets.filter { failedRootPaths.contains($0.rootPath) }
                    let retryRequest = ArborVCSActionRequest(
                        kind: .rollbackMultiRootCheckout,
                        projectPath: projectPath,
                        rootPath: nil,
                        shelfName: "",
                        checkoutReference: reference,
                        checkoutTargets: remainingTargets.map(PersistedMultiRootCheckoutTarget.init)
                    )
                    self.feedbackCenter.warning(
                        "Checkout rollback partially failed",
                        detail: failures.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n"),
                        nextStep: "Review the affected roots and retry the remaining rollback targets.",
                        additionalActions: remainingTargets.isEmpty
                            ? []
                            : [FeedbackAction(
                                title: "Retry Checkout Rollback",
                                semanticAction: retryRequest
                            ) {
                                self.handleVCSActionRequest(retryRequest)
                            }],
                        notificationID: notificationID,
                        notificationGroup: .important
                    )
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Checkout rollback failed",
                    detail: errorMessage(error),
                    nextStep: "Review the affected roots and retry the rollback action.",
                    additionalActions: [FeedbackAction(
                        title: "Retry Checkout Rollback",
                        semanticAction: fullRetryRequest
                    ) {
                        self.handleVCSActionRequest(fullRetryRequest)
                    }],
                    notificationID: notificationID,
                    notificationGroup: .important
                )
            }
        }
    }
}

/// BRANCH-001：在选中的 Git root 集合上执行 Checkout and Update / Checkout
/// with Rebase。Branches Popup 传入单 root，项目级入口可以传入全部 roots。
func executeMultiRootCheckoutAndUpdate(
    reference: String,
    rootPath: String? = nil,
    detach: Bool,
    rebase: Bool
) {
    performMultiRootCheckoutAndUpdate(
        reference: reference,
        selectedRootPaths: rootPath.map { [$0] },
        detach: detach,
        rebase: rebase,
        mode: .normal,
        offerRecovery: true
    )
}

/// IntelliJ 的多 root Branches Popup 语义：非当前本地分支 rebase 到当前分支，
/// 而不是 checkout 后 pull 该分支自己的 upstream。远程分支需先检出为本地分支。
func executeMultiRootCheckoutWithRebase(rootPath: String, branch: String) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    guard !branch.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        feedbackCenter.warning("Checkout with Rebase cancelled", detail: "A local branch is required.")
        return
    }
    let cancel = GitCancelHandle()
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Checkout with Rebase", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        let rootRepo: Repository
        do {
            rootRepo = try openRepository(path: rootPath)
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Checkout with Rebase failed",
                    detail: "\(branch): \(errorMessage(error))",
                    nextStep: "Resolve the selected root's status, then retry Checkout with Rebase."
                )
            }
            return
        }
        let currentBranch = (try? rootRepo.branchList())?.first(where: { $0.isCurrent })?.name
        let seed = makeRebaseUndoSeed(repo: rootRepo, branch: branch, onto: currentBranch)
        if let seed {
            saveRebaseUndoSeed(seed)
        }
        do {
            try rootRepo.rebaseBranchOnCurrentWithPolicyAndCancel(
                branch: branch,
                savePolicy: projectSavePolicy,
                cancel: cancel
            )
            await MainActor.run {
                if let seed {
                    clearRebaseUndoSeed(repositoryPath: seed.repositoryPath)
                    if self.repo?.workdir() == seed.repositoryPath {
                        self.rebaseUndoSeed = nil
                    }
                }
                self.feedbackCenter.success("Checked out and rebased", detail: branch)
                self.loadMultiRoots()
                self.refreshAll(showFeedback: false)
            }
        } catch {
            if case .Cancelled = error as? EngineError {
                await MainActor.run {
                    self.feedbackCenter.warning(
                        "Checkout with Rebase cancelled",
                        detail: "The saved local scene for \(branch) was not discarded.",
                        nextStep: "Check Saved Changes or Stash, restore any pending local scene, then retry.",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: rootRepo,
                            rootPath: rootPath
                        ).map { [$0] } ?? []
                    )
                }
                return
            }
            let state = try? rootRepo.operationState()
            await MainActor.run {
                self.operationsViewMode = .roots
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                if state?.kind == .rebase {
                    if let seed {
                        saveRebaseUndoSeed(seed)
                    }
                    self.feedbackCenter.warning(
                        "Checkout with Rebase paused",
                        detail: "\(branch): \(errorMessage(error))",
                        nextStep: "Resolve the selected root's rebase, then continue or abort it.",
                        additionalActions: [
                            seed.map {
                                persistedRebaseRecoveryAction(rootPath: $0.repositoryPath, branch: $0.branch)
                            },
                            self.pendingSavedChangesFeedbackAction(
                                repo: rootRepo,
                                rootPath: rootPath
                            )
                        ].compactMap { $0 },
                        notificationID: seed.map { rebaseRecoveryNotificationID(repositoryPath: $0.repositoryPath) }
                    )
                } else {
                    if let seed {
                        clearRebaseUndoSeed(repositoryPath: seed.repositoryPath)
                    }
                    self.feedbackCenter.error(
                        "Checkout with Rebase failed",
                        detail: "\(branch): \(errorMessage(error))",
                        nextStep: "Resolve the selected root's status, then retry Checkout with Rebase.",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: rootRepo,
                            rootPath: rootPath
                        ).map { [$0] } ?? []
                    )
                }
                self.loadMultiRoots()
            }
        }
    }
}

private func performMultiRootCheckoutAndUpdate(
    reference: String,
    selectedRootPaths: [String]?,
    detach: Bool,
    rebase: Bool,
    mode: MultiRootCheckoutMode,
    offerRecovery: Bool,
    mergeResults: Bool = false
) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    guard let projectPath, !reference.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        feedbackCenter.warning("Checkout cancelled", detail: "A branch, tag, or revision is required.")
        return
    }
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    multiRootRunning = true
    let modeLabel = mode == .smart ? "Smart" : "Force"
    beginFeedbackOperation(
        mode == .normal
            ? (rebase ? "Checkout with Rebase" : "Checkout and Update")
            : "Multi-root \(modeLabel) Checkout and Update",
        cancelHandle: cancel,
        notificationID: multiRootRetryNotificationID(.checkoutUpdate)
    )
    let fetchTagMode = fetchTagsMode
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    Task.detached(priority: .userInitiated) {
        do {
            let initialRoots = try Arbor.discoverGitRoots(scanRoot: projectPath, maxDepth: nil)
            let initialSnapshots = try Arbor.listMultiRootBranches(scanRoot: projectPath)
            let savedChangeIDsBefore: (stashes: [String: Set<String>], shelves: [String: Set<String>])
            if mode == .smart {
                savedChangeIDsBefore = Self.savedChangeIDsByRoot(rootPaths: initialRoots.map(\.path))
            } else {
                savedChangeIDsBefore = (stashes: [:], shelves: [:])
            }
            let results = try Arbor.runMultiRootCheckoutAndUpdateWithPolicyAndOptions(
                scanRoot: projectPath,
                selectedRootPaths: selectedRootPaths,
                reference: reference,
                detach: detach,
                rebase: rebase,
                mode: mode,
                tagMode: fetchTagMode,
                broker: broker,
                cancel: cancel,
                savePolicy: projectSavePolicy
            )
            let finalRoots = (try? Arbor.discoverGitRoots(scanRoot: projectPath, maxDepth: nil)) ?? []
            let newSavedChangeIDs = mode == .smart
                ? Self.newSavedChangeIDsByRoot(
                    rootPaths: results.map(\.rootPath),
                    before: savedChangeIDsBefore,
                    stashMessagePrefix: "Arbor: Checkout and Update to \(reference)",
                    shelfNamePrefix: "Arbor: Checkout and Update to \(reference)"
                )
                : (stashes: [:], shelves: [:])
            await MainActor.run {
                if mergeResults {
                    let retryByRoot = Dictionary(uniqueKeysWithValues: results.map { ($0.rootPath, $0) })
                    self.multiRootResults = self.multiRootResults.map { retryByRoot[$0.rootPath] ?? $0 }
                } else {
                    self.multiRootResults = results
                }
                self.multiRootRunning = false
                let failures = results.filter { !$0.success }
                let successfulRollbackTargets: [MultiRootBranchTarget] = (!mergeResults && mode != .force)
                    ? results
                        .filter { $0.success && !$0.skipped }
                        .compactMap { result in
                            guard let initialRoot = initialRoots.first(where: { $0.path == result.rootPath }),
                                  let finalRoot = finalRoots.first(where: { $0.path == result.rootPath }),
                                  let expectedHead = finalRoot.headId else { return nil }
                            let initialSnapshot = initialSnapshots.first(where: { $0.rootPath == result.rootPath })
                            return MultiRootBranchTarget(
                                rootPath: result.rootPath,
                                checkedOut: true,
                                previousBranch: initialRoot.headBranch,
                                previousHead: initialRoot.headId,
                                expectedHead: expectedHead,
                                expectedBranch: finalRoot.headBranch,
                                createdBranch: createdCheckoutBranch(
                                    reference: reference,
                                    detach: detach,
                                    snapshot: initialSnapshot
                                )
                            )
                        }
                    : []
                if failures.isEmpty {
                    self.multiRootCheckoutUpdateRetryAvailable = false
                    self.multiRootCheckoutUpdateRetryContext = nil
                } else {
                    self.multiRootCheckoutUpdateRetryAvailable = true
                    self.multiRootCheckoutUpdateRetryContext = MultiRootCheckoutUpdateRetryContext(
                        reference: reference,
                        selectedRootPaths: failures.map(\.rootPath),
                        detach: detach,
                        rebase: rebase,
                        mode: mode
                    )
                }
                let dirtyFailure = failures.contains(where: isCheckoutOverwriteFailure)
                if failures.isEmpty {
                    let skipped = results.filter(\.skipped).count
                    self.feedbackCenter.success(
                        rebase ? "Checkout with Rebase completed" : "Checkout and Update completed",
                        detail: "\(results.count - skipped) updated · \(skipped) skipped · \(reference)"
                    )
                    self.loadMultiRoots()
                } else if mode == .normal && offerRecovery && dirtyFailure {
                    self.presentMultiRootCheckoutAndUpdateRecovery(
                        reference: reference,
                        selectedRootPaths: selectedRootPaths,
                        detach: detach,
                        rebase: rebase,
                        failures: failures
                    )
                } else {
                    self.operationsViewMode = .roots
                    self.toolWindowMode = .operations
                    self.toolWindowExpanded = true
                    let retryRequest = self.makeMultiRootCheckoutUpdateRetryRequest(
                        reference: reference,
                        rootPaths: failures.map(\.rootPath),
                        detach: detach,
                        rebase: rebase,
                        mode: mode
                    )
                    let rollbackRequest = successfulRollbackTargets.isEmpty
                        ? nil
                        : ArborVCSActionRequest(
                            kind: .rollbackMultiRootCheckout,
                            projectPath: projectPath,
                            rootPath: nil,
                            shelfName: "",
                            checkoutReference: reference,
                            checkoutTargets: successfulRollbackTargets.map(PersistedMultiRootCheckoutTarget.init)
                        )
                    var recoveryActions: [FeedbackAction] = [
                        FeedbackAction(
                            title: "Retry Failed Checkout Roots",
                            semanticAction: retryRequest
                        ) {
                            self.handleVCSActionRequest(retryRequest)
                        }
                    ]
                    if let rollbackRequest {
                        recoveryActions.append(
                            FeedbackAction(
                                title: "Rollback Successful Roots",
                                semanticAction: rollbackRequest
                            ) {
                                self.handleVCSActionRequest(rollbackRequest)
                            }
                        )
                    }
                    self.feedbackCenter.warning(
                        rebase ? "Checkout with Rebase partially completed" : "Checkout and Update partially completed",
                        detail: failures.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n"),
                        nextStep: successfulRollbackTargets.isEmpty
                            ? "Resolve conflicted roots, then continue or abort their Git operation."
                            : "Retry the failed roots or rollback the roots that already changed.",
                        additionalActions: recoveryActions + results.compactMap { result -> FeedbackAction? in
                            if let stashID = newSavedChangeIDs.stashes[result.rootPath] {
                                return self.savedChangesFeedbackAction(
                                    kind: .stash,
                                    identifier: stashID,
                                    rootPath: result.rootPath
                                )
                            }
                            if let shelfName = newSavedChangeIDs.shelves[result.rootPath] {
                                return self.savedChangesFeedbackAction(
                                    kind: .shelf,
                                    identifier: shelfName,
                                    rootPath: result.rootPath
                                )
                            }
                            return nil
                        },
                        notificationID: self.multiRootRetryNotificationID(.checkoutUpdate)
                    )
                    self.loadMultiRoots()
                    self.presentMultiRootShelfRestoreConflicts(results)
                }
            }
        } catch {
            await MainActor.run {
                self.multiRootRunning = false
                self.feedbackCenter.error(
                    rebase ? "Checkout with Rebase failed" : "Checkout and Update failed",
                    detail: errorMessage(error),
                    nextStep: "Resolve the affected roots, then retry the operation."
                )
            }
        }
    }
}

/// Retry only roots that failed in the last Checkout and Update / Checkout
/// with Rebase run. Successful roots remain untouched, while the engine still
/// includes any required parent Git roots for a selected nested repository.
func retryMultiRootCheckoutAndUpdateFailedRoots(
    reference: String? = nil,
    selectedRootPaths: [String]? = nil,
    detach: Bool? = nil,
    rebase: Bool? = nil,
    checkoutMode: ArborVCSActionRequest.CheckoutUpdateMode? = nil
) {
    guard !multiRootRunning else { return }
    let context = multiRootCheckoutUpdateRetryContext
    guard let reference = reference ?? context?.reference,
          let requestedRootPaths = selectedRootPaths ?? context?.selectedRootPaths,
          let detach = detach ?? context?.detach,
          let rebase = rebase ?? context?.rebase,
          let mode = checkoutMode.map(engineCheckoutMode)
              ?? context.map(\.mode) else {
        feedbackCenter.warning(
            "Retry unavailable",
            detail: "There is no failed Checkout and Update root to retry."
        )
        return
    }
    let retryableRootPaths: Set<String>
    if selectedRootPaths == nil {
        retryableRootPaths = Set(multiRootResults.compactMap { result -> String? in
            guard !result.success,
                  requestedRootPaths.contains(result.rootPath),
                  !multiRootUpdateStashedRoots.contains(result.rootPath),
                  multiRoots.first(where: { $0.path == result.rootPath })?.operation == nil else {
                return nil
            }
            return result.rootPath
        })
    } else {
        retryableRootPaths = Set(requestedRootPaths.filter { rootPath in
            !multiRootUpdateStashedRoots.contains(rootPath)
                && multiRoots.first(where: { $0.path == rootPath })?.operation == nil
        })
    }
    let selectedRootPaths = requestedRootPaths.filter(retryableRootPaths.contains)
    guard !selectedRootPaths.isEmpty else {
        feedbackCenter.warning(
            "Retry unavailable",
            detail: "There are no failed Checkout and Update roots to retry."
        )
        return
    }
    performMultiRootCheckoutAndUpdate(
        reference: reference,
        selectedRootPaths: selectedRootPaths,
        detach: detach,
        rebase: rebase,
        mode: mode,
        offerRecovery: false,
        mergeResults: true
    )
}

private func engineCheckoutMode(
    _ mode: ArborVCSActionRequest.CheckoutUpdateMode
) -> MultiRootCheckoutMode {
    switch mode {
    case .normal:
        return .normal
    case .smart:
        return .smart
    case .force:
        return .force
    }
}

private func isCheckoutOverwriteFailure(_ result: RootOperationResult) -> Bool {
    result.message.localizedCaseInsensitiveContains("overwrit")
}

private func createdCheckoutBranch(
    reference: String,
    detach: Bool,
    snapshot: GitRootBranchSnapshot?
) -> String? {
    guard !detach,
          let snapshot,
          snapshot.branches.allSatisfy({ $0.name != reference }),
          snapshot.remoteBranches.contains(where: { $0.name == reference }),
          let separator = reference.firstIndex(of: "/") else {
        return nil
    }
    return String(reference[reference.index(after: separator)...])
}

private func presentMultiRootCheckoutAndUpdateRecovery(
    reference: String,
    selectedRootPaths: [String]?,
    detach: Bool,
    rebase: Bool,
    failures: [RootOperationResult]
) {
    let alert = NSAlert()
    alert.messageText = "Local changes would be overwritten during checkout"
    alert.informativeText = failures.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n")
    alert.alertStyle = .warning
    alert.addButton(withTitle: rebase ? "Smart Checkout with Rebase" : "Smart Checkout and Update")
    alert.addButton(withTitle: rebase ? "Force Checkout with Rebase" : "Force Checkout and Update")
    alert.addButton(withTitle: "Cancel")
    switch alert.runModal() {
    case .alertFirstButtonReturn:
        performMultiRootCheckoutAndUpdate(
            reference: reference,
            selectedRootPaths: selectedRootPaths,
            detach: detach,
            rebase: rebase,
            mode: .smart,
            offerRecovery: false
        )
    case .alertSecondButtonReturn:
        performMultiRootCheckoutAndUpdate(
            reference: reference,
            selectedRootPaths: selectedRootPaths,
            detach: detach,
            rebase: rebase,
            mode: .force,
            offerRecovery: false
        )
    default:
        feedbackCenter.warning("Checkout cancelled", detail: "Local changes were kept.")
    }
}

private func operationRecoveryKindTitle(_ kind: OperationKind) -> String {
    switch kind {
    case .merge: return "Merge"
    case .rebase: return "Rebase"
    case .cherryPick: return "Cherry-pick"
    case .revert: return "Revert"
    }
}

private func operationRecoveryActionTitle(
    _ action: ArborVCSActionRequest.OperationRecoveryAction
) -> String {
    switch action {
    case .continueOperation: return "Continue"
    case .skip: return "Skip"
    case .abort: return "Abort"
    case .openRecovery: return "Open Recovery"
    }
}

private func logApplyRecoveryNotificationID(rootPath: String) -> String {
    let stableRoot = URL(fileURLWithPath: rootPath).standardizedFileURL.path
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
    return "arbor.log-apply-recovery.\(stableRoot)"
}

private func logApplyRecoveryTitle(
    _ operation: PersistedLogApplyRecovery.Operation
) -> String {
    switch operation {
    case .cherryPick: "Cherry-pick"
    case .revert: "Revert"
    }
}

private func logApplyRecoveryAction(
    _ recovery: PersistedLogApplyRecovery
) -> FeedbackAction {
    let request = ArborVCSActionRequest(
        kind: .retryLogApply,
        projectPath: projectPath,
        rootPath: recovery.rootPath,
        shelfName: "",
        logApplyRecovery: recovery
    )
    return FeedbackAction(
        title: logApplyRecoveryActionTitle(recovery),
        semanticAction: request
    ) {
        self.handleVCSActionRequest(request)
    }
}

private func logApplyAffectedFilesAction(
    _ recovery: PersistedLogApplyRecovery
) -> FeedbackAction? {
    guard !recovery.affectedPaths.isEmpty else { return nil }
    let request = ArborVCSActionRequest(
        kind: .showLogApplyAffectedFiles,
        projectPath: projectPath,
        rootPath: recovery.rootPath,
        shelfName: "",
        logApplyRecovery: recovery
    )
    return FeedbackAction(title: "Show Files", semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

private func logApplyRecoveryActions(
    _ recovery: PersistedLogApplyRecovery
) -> [FeedbackAction] {
    [logApplyAffectedFilesAction(recovery), logApplyRecoveryAction(recovery)]
        .compactMap { $0 }
}

private func logApplyRecoveryFingerprint(
    _ recovery: PersistedLogApplyRecovery
) -> String {
    [
        recovery.operation.rawValue,
        recovery.rootPath,
        recovery.sessionID,
        String(recovery.batchIndex),
        String(recovery.batchCount),
        recovery.initialHead,
        recovery.commitIDs.joined(separator: "\u{1f}"),
        recovery.preserveLocalChanges ? "preserve" : "direct",
        recovery.emptyPolicyRaw,
        recovery.appendPublishedSuffix ? "suffix" : "no-suffix",
        recovery.savePolicyRaw,
        recovery.affectedPaths.joined(separator: "\u{1f}")
    ].joined(separator: "\u{1e}")
}

private func nextLogApplyRecovery(
    after completed: PersistedLogApplyRecovery
) -> PersistedLogApplyRecovery? {
    pendingLogApplyRecoveries(sessionID: completed.sessionID).first {
        $0.operation == completed.operation
            && $0.batchCount == completed.batchCount
            && $0.batchIndex == completed.batchIndex + 1
    }
}

private func retryNextLogApplyRoot(
    after completed: PersistedLogApplyRecovery
) {
    guard let nextRecovery = nextLogApplyRecovery(after: completed) else { return }
    retryLogApplyRecovery(nextRecovery, automatic: true)
}

private func publishLogApplyRecoveryNoticeIfNeeded(rootPath: String) -> Bool {
    let normalizedRoot = URL(fileURLWithPath: rootPath).standardizedFileURL.path
    guard let recovery = loadLogApplyRecovery(repositoryPath: normalizedRoot),
          recovery.rootPath == normalizedRoot,
          !recovery.commitIDs.isEmpty,
          !recovery.initialHead.isEmpty else {
        feedbackCenter.expire(notificationID: logApplyRecoveryNotificationID(rootPath: normalizedRoot))
        logApplyRecoveryNotificationFingerprints.removeValue(
            forKey: operationRecoveryNotificationRootKey(normalizedRoot)
        )
        return false
    }
    let key = operationRecoveryNotificationRootKey(normalizedRoot)
    let fingerprint = logApplyRecoveryFingerprint(recovery)
    guard logApplyRecoveryNotificationFingerprints[key] != fingerprint else { return true }
    let title = logApplyRecoveryTitle(recovery.operation)
    if recovery.preserveLocalChanges, !recovery.affectedPaths.isEmpty {
        feedbackCenter.error(
            "\(title) failed",
            detail: "Local changes would be overwritten: \(recovery.affectedPaths.joined(separator: ", ")).",
            nextStep: "Show the affected files or choose \(logApplyRecoveryActionTitle(recovery)).",
            additionalActions: logApplyRecoveryActions(recovery),
            notificationID: logApplyRecoveryNotificationID(rootPath: normalizedRoot),
            notificationGroup: .important,
            localized: false
        )
    } else {
        feedbackCenter.warning(
            "\(title) recovery available",
            detail: "A previous Log \(title) action was interrupted before its final result was recorded.",
            nextStep: "Retry is allowed only while the repository HEAD remains \(String(recovery.initialHead.prefix(7))).",
            additionalActions: logApplyRecoveryActions(recovery),
            notificationID: logApplyRecoveryNotificationID(rootPath: normalizedRoot),
            notificationGroup: .important,
            localized: false
        )
    }
    logApplyRecoveryNotificationFingerprints[key] = fingerprint
    return true
}

private func retryLogApplyRecovery(
    _ requestedRecovery: PersistedLogApplyRecovery,
    automatic: Bool = false
) {
    guard let recovery = loadLogApplyRecovery(repositoryPath: requestedRecovery.rootPath),
          recovery == requestedRecovery else {
        feedbackCenter.warning(
            "Retry unavailable",
            detail: "The saved Log operation is no longer pending.",
            nextStep: "Refresh the Log and select the commits again."
        )
        return
    }
    let normalizedRoot = URL(fileURLWithPath: recovery.rootPath).standardizedFileURL.path
    guard recovery.rootPath == normalizedRoot,
          !recovery.commitIDs.isEmpty,
          !recovery.initialHead.isEmpty else {
        feedbackCenter.warning(
            "Retry unavailable",
            detail: "The saved Log operation context is incomplete."
        )
        return
    }
    let pendingRecoveries = pendingLogApplyRecoveries(sessionID: recovery.sessionID)
    if let firstPending = pendingRecoveries.first,
       !logApplyRecoveryCanRun(recovery, pending: pendingRecoveries) {
        feedbackCenter.warning(
            "Retry unavailable",
            detail: "An earlier Git root in this Log operation is still pending.",
            nextStep: "Complete or retry root \(firstPending.batchIndex + 1) before continuing this root."
        )
        return
    }
    guard let targetRepo = try? openRepository(path: normalizedRoot) else {
        feedbackCenter.warning(
            "Retry unavailable",
            detail: "The saved Git root could not be opened.",
            nextStep: "Refresh Git Roots, then retry from the recovery notification."
        )
        return
    }
    do {
        guard try targetRepo.operationState() == nil else {
            feedbackCenter.warning(
                "Retry unavailable",
                detail: "This repository still has an active Git operation.",
                nextStep: "Continue or Abort the active operation first."
            )
            return
        }
    } catch {
        feedbackCenter.warning(
            "Retry unavailable",
            detail: "The current Git operation state could not be read.",
            nextStep: "Refresh Git Roots, then retry when the repository is readable."
        )
        return
    }
    guard targetRepo.headCommitId() == recovery.initialHead else {
        clearLogApplyRecovery(repositoryPath: normalizedRoot)
        feedbackCenter.expire(notificationID: logApplyRecoveryNotificationID(rootPath: normalizedRoot))
        logApplyRecoveryNotificationFingerprints.removeValue(
            forKey: operationRecoveryNotificationRootKey(normalizedRoot)
        )
        feedbackCenter.warning(
            "Retry refused",
            detail: "The repository HEAD changed after the interrupted Log operation.",
            nextStep: "Re-select the commits from the current Log instead of replaying the old action."
        )
        return
    }

    let operation: LogApplyOperation = recovery.operation == .cherryPick
        ? .cherryPick
        : .revert
    let emptyPolicy = GitCherryPickEmptyPolicyChoice(rawValue: recovery.emptyPolicyRaw)
        ?? GitCherryPickSettings.defaultEmptyPolicy
    let savePolicy = GitLocalChangesSavePolicyChoice(rawValue: recovery.savePolicyRaw)
        ?? GitLocalChangesSavePolicySettings.defaultPolicy
    beginFeedbackOperation(logApplyRecoveryTitle(recovery.operation))
    Task.detached(priority: .userInitiated) {
        do {
            let resultID = try executeLogApply(
                operation: operation,
                repo: targetRepo,
                commitIDs: recovery.commitIDs,
                emptyPolicy: emptyPolicy.engineValue,
                appendPublishedSuffix: recovery.appendPublishedSuffix,
                preserveLocalChanges: recovery.preserveLocalChanges,
                savePolicy: savePolicy.engineValue
            )
            clearLogApplyRecovery(repositoryPath: normalizedRoot)
            await MainActor.run {
                self.logApplyRecoveryNotificationFingerprints.removeValue(
                    forKey: operationRecoveryNotificationRootKey(normalizedRoot)
                )
                self.feedbackCenter.expire(
                    notificationID: self.logApplyRecoveryNotificationID(rootPath: normalizedRoot)
                )
                let nextRecovery = self.nextLogApplyRecovery(after: recovery)
                self.feedbackCenter.success(
                    automatic || nextRecovery != nil
                        ? "\(logApplyRecoveryTitle(recovery.operation)) root completed"
                        : "\(logApplyRecoveryTitle(recovery.operation)) retried",
                    detail: nextRecovery == nil
                        ? "\(normalizedRoot): \(String(resultID.prefix(7)))"
                        : "\(normalizedRoot): \(String(resultID.prefix(7))). Continuing the next Git root."
                )
                self.refreshAll(showFeedback: false)
                if let nextRecovery {
                    self.retryLogApplyRecovery(nextRecovery, automatic: true)
                }
            }
        } catch {
            let latestState = try? targetRepo.operationState()
            await MainActor.run {
                self.refreshAll(showFeedback: false)
                if let latestState, let rootPath = targetRepo.workdir() {
                    self.operationState = latestState
                    self.publishOperationRecoveryNoticeIfNeeded(
                        state: latestState,
                        rootPath: rootPath
                    )
                } else {
                    self.feedbackCenter.error(
                        "\(logApplyRecoveryTitle(recovery.operation)) retry failed",
                        detail: errorMessage(error),
                        nextStep: "Review the current root, then retry the saved Log action.",
                        additionalActions: [self.logApplyRecoveryAction(recovery)],
                        notificationID: self.logApplyRecoveryNotificationID(rootPath: normalizedRoot)
                    )
                }
            }
        }
    }
}

private func operationRecoveryRequest(
    action: ArborVCSActionRequest.OperationRecoveryAction,
    projectPath: String?,
    rootPath: String
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .operationRecovery,
        projectPath: projectPath,
        rootPath: rootPath,
        shelfName: "",
        operationRecoveryAction: action
    )
}

private func operationRecoveryFeedbackAction(
    _ action: ArborVCSActionRequest.OperationRecoveryAction,
    projectPath: String?,
    rootPath: String
) -> FeedbackAction {
    let request = operationRecoveryRequest(
        action: action,
        projectPath: projectPath,
        rootPath: rootPath
    )
    return FeedbackAction(
        title: operationRecoveryActionTitle(action),
        semanticAction: request
    ) {
        self.handleVCSActionRequest(request)
    }
}

private func operationRecoveryFeedbackActions(
    state: OperationState,
    rootPath: String
) -> [FeedbackAction] {
    var actions = [
        operationRecoveryFeedbackAction(
            .continueOperation,
            projectPath: projectPath,
            rootPath: rootPath
        )
    ]
    if state.kind == .rebase {
        actions.append(
            operationRecoveryFeedbackAction(
                .skip,
                projectPath: projectPath,
                rootPath: rootPath
            )
        )
    }
    actions.append(
        operationRecoveryFeedbackAction(
            .abort,
            projectPath: projectPath,
            rootPath: rootPath
        )
    )
    actions.append(
        operationRecoveryFeedbackAction(
            .openRecovery,
            projectPath: projectPath,
            rootPath: rootPath
        )
    )
    return actions
}

private func publishOperationRecoveryNotice(
    state: OperationState,
    rootPath: String
) -> Bool {
    let normalizedRoot = URL(fileURLWithPath: rootPath).standardizedFileURL.path
    let hasDedicatedRebaseRecovery = state.kind == .rebase
        && (
            loadRebaseUndoSeed(repositoryPath: normalizedRoot) != nil
                || multiRootRebaseSession?.roots.contains(where: {
                    URL(fileURLWithPath: $0.rootPath).standardizedFileURL.path == normalizedRoot
                }) == true
        )
    guard !hasDedicatedRebaseRecovery else { return false }
    let kindTitle = operationRecoveryKindTitle(state.kind)
    let detail: String
    if state.conflictedFiles.isEmpty {
        detail = "A \(kindTitle) operation is paused in this repository."
    } else {
        detail = "\(state.conflictedFiles.count) conflicted file(s) must be resolved before continuing."
    }
    feedbackCenter.warning(
        "\(kindTitle) recovery available",
        detail: detail,
        nextStep: "Continue, Skip, or Abort the operation from the recovery actions.",
        additionalActions: operationRecoveryFeedbackActions(
            state: state,
            rootPath: rootPath
        ),
        notificationID: operationRecoveryNotificationID(rootPath: rootPath),
        notificationGroup: .important,
        localized: false
    )
    return true
}

private func publishOperationRecoveryNoticeIfNeeded(
    state: OperationState,
    rootPath: String
) {
    let key = operationRecoveryNotificationRootKey(rootPath)
    let fingerprint = operationRecoveryNotificationFingerprint(state)
    guard operationRecoveryNotificationFingerprints[key] != fingerprint else { return }
    if publishOperationRecoveryNotice(state: state, rootPath: rootPath) {
        operationRecoveryNotificationFingerprints[key] = fingerprint
    }
}

private func openOperationRecovery(rootPath: String, preferredPath: String? = nil) {
    toolWindowMode = .commit
    toolWindowExpanded = true
    let currentRootMatches = repo?.workdir().map {
        URL(fileURLWithPath: $0).standardizedFileURL.path
            == URL(fileURLWithPath: rootPath).standardizedFileURL.path
    } == true
    guard currentRootMatches else {
        openMultiRootConflictResolver(
            preferredRootPath: rootPath,
            preferredPath: preferredPath
        )
        return
    }
    if let preferredPath {
        mergeInitialPath = preferredPath
        selection = preferredPath
    } else if let conflictPath = operationState?.conflictedFiles.first {
        mergeInitialPath = conflictPath
        selection = conflictPath
    }
    if let state = operationState, !state.conflictedFiles.isEmpty {
        openMultiRootConflictResolver(
            preferredRootPath: rootPath,
            preferredPath: preferredPath ?? state.conflictedFiles.first
        )
    }
}

/// OPS-001 恢复动作：根据 operation_state() 的类别分派
/// continue/skip/abort（引擎层已按 origin 分派到引擎实现或系统 git）。
func doOperationContinue() {
    if stashPopConflictInProgress || stashApplyConflictInProgress {
        finishStashConflict()
        return
    }
    guard let repo, let state = operationState else { return }
    let rebaseRootPath = repo.workdir()
    let rebaseSessionID = state.kind == .rebase
        ? multiRootRebaseSession?.roots.contains(where: { $0.rootPath == rebaseRootPath }) == true
            ? multiRootRebaseSession?.id
            : nil
        : nil
    let sourceBranch = state.kind == .merge && state.origin == .engine
        ? (pendingMergeDeleteBranch ?? repo.mergeSourceReference())
        : nil
    let protectedPatterns = effectiveProtectedBranchPatterns
    let pendingPullStash = pendingPullStashPop
    let pendingPullStashIDValue = pendingPullStashID
    let pendingPullStashMessageValue = pendingPullStashMessage
    let pendingPullShelfNameValue = pendingPullShelfName
    let singleRootRebaseSeed = state.kind == .rebase && rebaseSessionID == nil
        ? rebaseUndoSeed
        : nil
    let completedLogApplyRecovery = rebaseRootPath.flatMap { rootPath -> PersistedLogApplyRecovery? in
        guard let recovery = loadLogApplyRecovery(repositoryPath: rootPath) else { return nil }
        switch state.kind {
        case .cherryPick:
            return recovery.operation == .cherryPick ? recovery : nil
        case .revert:
            return recovery.operation == .revert ? recovery : nil
        case .merge, .rebase:
            return nil
        }
    }
    let operationNotificationID = rebaseRootPath.map {
        operationRecoveryNotificationID(rootPath: $0)
    }
    beginFeedbackOperation(
        "Continue operation",
        notificationID: operationNotificationID
    )
    Task.detached(priority: .userInitiated) {
        do {
            switch state.kind {
            case .merge:
                _ = try state.origin == .engine
                    ? repo.finishMerge(message: nil)
                    : repo.mergeContinue(message: nil)
            case .rebase:
                _ = try repo.rebaseContinue()
            case .cherryPick:
                try repo.cherryPickContinueWithOptions(
                    emptyPolicy: configuredCherryPickEmptyPolicy()
                )
            case .revert:
                try repo.revertContinue()
            }
            let continuationState = try repo.operationState()
            let operationStillActive = continuationState != nil
            if !operationStillActive, let rootPath = rebaseRootPath {
                clearLogApplyRecovery(repositoryPath: rootPath)
            }
            let completedRebaseUndoTarget: RebaseUndoTarget?
            if !operationStillActive, let singleRootRebaseSeed {
                let finalHead = try? repo.revisionCommitId(revision: singleRootRebaseSeed.branch)
                let currentBranch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name
                completedRebaseUndoTarget = rebaseUndoTargetAfterCompletion(
                    seed: singleRootRebaseSeed,
                    currentBranch: currentBranch,
                    finalHead: finalHead
                )
            } else {
                completedRebaseUndoTarget = nil
            }
            var pullStashRestoreConflictPaths: [String]?
            var pullStashRestoreIndex: Int?
            var pullStashRestoreConflictID: String?
            var pullShelfRestoreConflictName: String?
            var pullShelfRestoreConflictPaths: [String]?
            var pullRestoreError: String?
            var pullRestoreStashID: String?
            var pullRestoreShelfName: String?
            var pullChangesRestored = false
            if !operationStillActive {
                if let pendingPullShelfNameValue {
                    pullRestoreShelfName = pendingPullShelfNameValue
                    do {
                        try repo.shelvePopPreservation(name: pendingPullShelfNameValue)
                        pullChangesRestored = true
                    } catch let error as EngineError {
                        if case let .ShelveApplyConflict(name, paths) = error {
                            pullShelfRestoreConflictName = name
                            pullShelfRestoreConflictPaths = paths
                        } else {
                            pullRestoreError = errorMessage(error)
                        }
                    } catch {
                        pullRestoreError = errorMessage(error)
                    }
                } else if pendingPullStash {
                    do {
                        let reference = try Self.pullStashReference(
                            repo: repo,
                            stashID: pendingPullStashIDValue,
                            message: pendingPullStashMessageValue
                        )
                        pullRestoreStashID = reference.stash.id
                        pullStashRestoreIndex = Int(reference.index)
                        try repo.stashPopWithIndex(
                            index: try currentStashIndex(repo: repo, stashID: reference.stash.id),
                            restoreIndex: true
                        )
                        pullChangesRestored = true
                    } catch let error as EngineError {
                        if case let .StashApplyConflict(paths, conflictID) = error {
                            pullStashRestoreConflictPaths = paths
                            pullStashRestoreConflictID = conflictID ?? pullRestoreStashID
                        } else {
                            pullRestoreError = errorMessage(error)
                        }
                    } catch {
                        pullRestoreError = errorMessage(error)
                    }
                }
            }
            let pullRestoreBlocked = pullStashRestoreConflictPaths != nil
                || pullShelfRestoreConflictPaths != nil
                || pullRestoreError != nil
            let canProposeDelete = (
                !operationStillActive && (sourceBranch.map {
                    canProposeDeleteMergedBranch(
                        repo: repo,
                        branch: $0,
                        protectedPatterns: protectedPatterns
                    )
                } ?? false)
            ) && !pullRestoreBlocked
            let pullStashRestoreConflictPathsValue = pullStashRestoreConflictPaths
            let pullStashRestoreIndexValue = pullStashRestoreIndex
            let pullStashRestoreConflictIDValue = pullStashRestoreConflictID
            let pullShelfRestoreConflictNameValue = pullShelfRestoreConflictName
            let pullShelfRestoreConflictPathsValue = pullShelfRestoreConflictPaths
            let pullRestoreErrorValue = pullRestoreError
            let pullRestoreStashIDValue = pullRestoreStashID
            let pullRestoreShelfNameValue = pullRestoreShelfName
            let pullChangesRestoredValue = pullChangesRestored
            await MainActor.run {
                self.operationFeedback = "已继续"
                if let pullStashRestoreConflictPathsValue {
                    self.showStashRestoreConflict(
                        pullStashRestoreConflictPathsValue,
                        operationName: "Pull",
                        notificationID: operationNotificationID,
                        stashID: pullStashRestoreConflictIDValue ?? pullRestoreStashIDValue
                    )
                    self.pendingStashPopIndex = pullStashRestoreIndexValue
                    self.pendingPullStashPop = false
                    self.pendingPullStashID = nil
                    self.pendingPullStashMessage = nil
                } else if let pullShelfRestoreConflictNameValue,
                          let pullShelfRestoreConflictPathsValue
                {
                    self.pendingPullShelfName = nil
                    self.presentShelveConflict(
                        name: pullShelfRestoreConflictNameValue,
                        paths: pullShelfRestoreConflictPathsValue,
                        isPop: true,
                        notificationID: operationNotificationID
                    )
                } else if pullChangesRestoredValue {
                    self.pendingPullStashPop = false
                    self.pendingPullStashID = nil
                    self.pendingPullStashMessage = nil
                    self.pendingPullShelfName = nil
                    if let rebaseRootPath {
                        clearPendingPullPreservation(repositoryPath: rebaseRootPath)
                    }
                }
                if let pullRestoreErrorValue {
                    let savedChangesAction: FeedbackAction? = {
                        if let pullRestoreShelfNameValue {
                            return self.savedChangesFeedbackAction(
                                kind: .shelf,
                                identifier: pullRestoreShelfNameValue
                            )
                        }
                        if let pullRestoreStashIDValue {
                            return self.savedChangesFeedbackAction(
                                kind: .stash,
                                identifier: pullRestoreStashIDValue
                            )
                        }
                        return nil
                    }()
                    self.feedbackCenter.error(
                        "Pull local changes restore failed",
                        detail: pullRestoreErrorValue,
                        nextStep: "View the saved changes, resolve the local issue, then retry the restore.",
                        additionalActions: savedChangesAction.map { [$0] } ?? [],
                        notificationID: operationNotificationID
                    )
                } else if pullRestoreBlocked {
                    self.feedbackCenter.warning(
                        "Pull local changes restore paused",
                        detail: "Resolve the restored local changes, then complete the restore.",
                        notificationID: operationNotificationID
                    )
                }
                if state.kind == .merge {
                    self.pendingMergeDeleteBranch = nil
                }
                if state.kind == .rebase, rebaseSessionID == nil {
                    if operationStillActive {
                        self.rebasePaused = true
                        self.rebasePauseReason = continuationState?.conflictedFiles.isEmpty == false
                            ? .conflict
                            : .edit
                        self.rebaseConflicts = continuationState?.conflictedFiles ?? []
                        self.rebaseUndoSeed = singleRootRebaseSeed
                        self.rebaseUndoTarget = nil
                        if let singleRootRebaseSeed {
                            saveRebaseUndoSeed(singleRootRebaseSeed)
                        }
                    } else if !pullRestoreBlocked {
                        self.rebasePaused = false
                        self.rebasePauseReason = nil
                        self.rebaseConflicts = []
                        self.rebaseUndoSeed = nil
                        self.rebaseUndoTarget = completedRebaseUndoTarget
                        if let singleRootRebaseSeed {
                            clearRebaseUndoSeed(repositoryPath: singleRootRebaseSeed.repositoryPath)
                        }
                    } else {
                        // The Git rebase has completed; only the saved local
                        // scene remains unresolved. Keep its seed for a
                        // later expected-HEAD Undo, but do not leave the
                        // operation bar pretending that Git is still paused.
                        self.rebasePaused = false
                        self.rebasePauseReason = nil
                        self.rebaseConflicts = []
                        self.rebaseUndoSeed = singleRootRebaseSeed
                        self.rebaseUndoTarget = nil
                        if let singleRootRebaseSeed {
                            saveRebaseUndoSeed(singleRootRebaseSeed)
                        }
                    }
                }
                self.refreshAll(showFeedback: false)
                if state.kind == .rebase,
                   let rebaseRootPath,
                   let rebaseSessionID,
                   !pullRestoreBlocked {
                    self.handleMultiRootRebaseRecovery(
                        rootPath: rebaseRootPath,
                        action: .continueOperation,
                        operationStillActive: operationStillActive,
                        sessionID: rebaseSessionID
                    )
                    return
                }
                if canProposeDelete, let sourceBranch {
                    self.feedbackCenter.success(
                        "Merge completed",
                        detail: sourceBranch,
                        actionTitle: "Delete branch",
                        action: postMergeDeleteAction(repo: repo, branch: sourceBranch),
                        notificationID: operationNotificationID
                    )
                } else if state.kind == .rebase,
                          rebaseSessionID == nil,
                          operationStillActive,
                          !pullRestoreBlocked
                {
                    self.feedbackCenter.warning(
                        "Rebase paused",
                        detail: continuationState?.conflictedFiles.isEmpty == false
                            ? "Resolve the remaining conflicts before continuing."
                            : "The rebase is paused at an edit step.",
                        nextStep: "Continue or abort the rebase from the recovery bar.",
                        notificationID: operationNotificationID
                    )
                } else if state.kind == .rebase,
                          rebaseSessionID == nil,
                          let completedRebaseUndoTarget,
                          !pullRestoreBlocked
                {
                    self.feedbackCenter.success(
                        "Rebase completed",
                        detail: String(completedRebaseUndoTarget.expectedHead.prefix(7)),
                        additionalActions: [self.rebaseUndoFeedbackAction(for: completedRebaseUndoTarget)],
                        notificationID: rebaseUndoNotificationID(
                            repositoryPath: completedRebaseUndoTarget.repositoryPath
                        ),
                        notificationGroup: .standard
                    )
                } else if !pullRestoreBlocked {
                    let detail = pullChangesRestoredValue
                        ? "The Git operation is no longer paused; local changes were restored."
                        : "The Git operation is no longer paused."
                    self.feedbackCenter.success(
                        "Operation continued",
                        detail: detail,
                        notificationID: operationNotificationID
                    )
                    if !operationStillActive,
                       let completedLogApplyRecovery {
                        self.retryNextLogApplyRoot(after: completedLogApplyRecovery)
                    }
                }
            }
        } catch {
            let latestState = try? repo.operationState()
            let latestRootPath = repo.workdir()
            await MainActor.run {
                self.operationFeedback = friendlyRemoteError(error)
                // A failed recovery command can leave Git at a different
                // paused step (or with a different conflict set). Read the
                // state synchronously before publishing actions; refresh the
                // visible UI as well, so neither surface keeps a stale
                // pre-command snapshot.
                self.refreshAll(showFeedback: false)
                if case let .StashApplyConflict(paths, stashID) = error as? EngineError {
                    self.showStashRestoreConflict(
                        paths,
                        operationName: state.kind == .cherryPick ? "Cherry-pick" : "Revert",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repo.workdir()
                        ).map { [$0] } ?? [],
                        notificationID: operationNotificationID,
                        stashID: stashID
                    )
                } else if case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                    self.presentShelveConflict(
                        name: name,
                        paths: paths,
                        isPop: true,
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repo.workdir()
                        ).map { [$0] } ?? [],
                        notificationID: operationNotificationID
                    )
                } else {
                    let recoveryRootPath = latestRootPath ?? rebaseRootPath
                    let recoveryActions: [FeedbackAction]
                    if let latestState, let recoveryRootPath {
                        recoveryActions = self.operationRecoveryFeedbackActions(
                            state: latestState,
                            rootPath: recoveryRootPath
                        )
                    } else {
                        recoveryActions = []
                    }
                    self.feedbackCenter.error(
                        "Continue failed",
                        detail: errorMessage(error),
                        nextStep: "解决剩余冲突后重试，或选择 Abort。",
                        additionalActions: recoveryActions + (self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: latestRootPath ?? rebaseRootPath
                        ).map { [$0] } ?? []),
                        notificationID: recoveryRootPath.map {
                            operationRecoveryNotificationID(rootPath: $0)
                        }
                    )
                }
            }
        }
    }
}

func doOperationSkip() {
    guard let repo, let state = operationState, state.kind == .rebase else { return }
    let rebaseRootPath = repo.workdir()
    let rebaseSessionID = rebaseRootPath.flatMap { rootPath in
        multiRootRebaseSession?.roots.contains(where: { $0.rootPath == rootPath }) == true
            ? multiRootRebaseSession?.id
            : nil
    }
    let singleRootRebaseSeed = rebaseSessionID == nil ? rebaseUndoSeed : nil
    let operationNotificationID = rebaseRootPath.map {
        operationRecoveryNotificationID(rootPath: $0)
    }
    beginFeedbackOperation(
        "Skip rebase step",
        notificationID: operationNotificationID
    )
    Task.detached(priority: .userInitiated) {
        do {
            let outcome = try repo.rebaseSkip()
            let continuationState = try repo.operationState()
            let operationStillActive = continuationState != nil
            let completedRebaseUndoTarget: RebaseUndoTarget?
            if !operationStillActive, let singleRootRebaseSeed {
                let finalHead = try? repo.revisionCommitId(revision: singleRootRebaseSeed.branch)
                let currentBranch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name
                completedRebaseUndoTarget = rebaseUndoTargetAfterCompletion(
                    seed: singleRootRebaseSeed,
                    currentBranch: currentBranch,
                    finalHead: finalHead
                )
            } else {
                completedRebaseUndoTarget = nil
            }
            await MainActor.run {
                self.operationFeedback = outcome.paused ? "已跳过当前步，rebase 继续暂停" : "已跳过，rebase 完成"
                if operationStillActive {
                    self.rebaseUndoSeed = singleRootRebaseSeed
                    self.rebaseUndoTarget = nil
                    if let singleRootRebaseSeed {
                        saveRebaseUndoSeed(singleRootRebaseSeed)
                    }
                } else {
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = completedRebaseUndoTarget
                    if let singleRootRebaseSeed {
                        clearRebaseUndoSeed(repositoryPath: singleRootRebaseSeed.repositoryPath)
                    }
                }
                self.refreshAll(showFeedback: false)
                if let rebaseRootPath,
                   let rebaseSessionID {
                    self.handleMultiRootRebaseRecovery(
                        rootPath: rebaseRootPath,
                        action: .skip,
                        operationStillActive: operationStillActive,
                        sessionID: rebaseSessionID
                    )
                    return
                }
                    if let completedRebaseUndoTarget, !operationStillActive {
                        self.feedbackCenter.success(
                            "Rebase completed",
                            detail: self.operationFeedback,
                            additionalActions: [self.rebaseUndoFeedbackAction(for: completedRebaseUndoTarget)],
                            notificationID: rebaseUndoNotificationID(
                                repositoryPath: completedRebaseUndoTarget.repositoryPath
                            ),
                            notificationGroup: .standard
                        )
                } else {
                    self.feedbackCenter.success(
                        outcome.paused ? "Rebase step skipped" : "Rebase completed",
                        detail: self.operationFeedback,
                        notificationID: operationNotificationID
                    )
                }
            }
        } catch {
            let latestState = try? repo.operationState()
            let latestRootPath = repo.workdir()
            await MainActor.run {
                self.operationFeedback = friendlyRemoteError(error)
                // Re-read the native rebase state before exposing another
                // Skip/Continue/Abort action after a failed command.
                self.refreshAll(showFeedback: false)
                let recoveryRootPath = latestRootPath ?? rebaseRootPath
                let recoveryActions: [FeedbackAction]
                if let latestState, let recoveryRootPath {
                    recoveryActions = self.operationRecoveryFeedbackActions(
                        state: latestState,
                        rootPath: recoveryRootPath
                    )
                } else {
                    recoveryActions = []
                }
                self.feedbackCenter.error(
                    "Skip failed",
                    detail: errorMessage(error),
                    nextStep: "可改为 Continue 或 Abort。",
                    additionalActions: recoveryActions + (self.pendingSavedChangesFeedbackAction(
                        repo: repo,
                        rootPath: latestRootPath ?? rebaseRootPath
                    ).map { [$0] } ?? []),
                    notificationID: recoveryRootPath.map {
                        operationRecoveryNotificationID(rootPath: $0)
                    }
                )
            }
        }
    }
}

func doOperationAbort() {
    guard let repo, let state = operationState else { return }
    let repositoryName = repo.workdir()
        .map { URL(fileURLWithPath: $0).lastPathComponent }
        .flatMap { $0.isEmpty ? nil : $0 }
        ?? "repository"
    let confirmation = operationAbortConfirmation(
        for: state.kind,
        repositoryName: repositoryName
    )
    let alert = NSAlert()
    alert.messageText = confirmation.title
    alert.informativeText = confirmation.message
    alert.alertStyle = .warning
    alert.addButton(withTitle: confirmation.confirmTitle)
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    let rebaseRootPath = repo.workdir()
    let rebaseSessionID = state.kind == .rebase
        ? rebaseRootPath.flatMap { rootPath in
            multiRootRebaseSession?.roots.contains(where: { $0.rootPath == rootPath }) == true
                ? multiRootRebaseSession?.id
                : nil
        }
        : nil
    let singleRootRebaseSeed = state.kind == .rebase && rebaseSessionID == nil
        ? rebaseUndoSeed
        : nil
    let operationNotificationID = rebaseRootPath.map {
        operationRecoveryNotificationID(rootPath: $0)
    }
    let activeLogApplyRecovery = rebaseRootPath.flatMap { rootPath -> PersistedLogApplyRecovery? in
        guard let recovery = loadLogApplyRecovery(repositoryPath: rootPath) else {
            return nil
        }
        switch state.kind {
        case .cherryPick:
            return recovery.operation == .cherryPick ? recovery : nil
        case .revert:
            return recovery.operation == .revert ? recovery : nil
        case .merge, .rebase:
            return nil
        }
    }
    let logApplyRecoveriesToCancel = activeLogApplyRecovery.map {
        logApplyRecoveryCancellationTargets(
            current: $0,
            pending: pendingLogApplyRecoveries(sessionID: $0.sessionID)
        )
    } ?? []
    beginFeedbackOperation(
        "Abort operation",
        notificationID: operationNotificationID
    )
    Task.detached(priority: .userInitiated) {
        do {
            switch state.kind {
            case .merge:
                try repo.mergeAbort()
            case .rebase:
                try repo.rebaseAbort()
            case .cherryPick:
                try repo.cherryPickAbort()
            case .revert:
                try repo.revertAbort()
            }
            let operationStillActive = try repo.operationState() != nil
            await MainActor.run {
                self.operationFeedback = "已中止"
                if !operationStillActive {
                    for recovery in logApplyRecoveriesToCancel {
                        clearLogApplyRecovery(repositoryPath: recovery.rootPath)
                        self.logApplyRecoveryNotificationFingerprints.removeValue(
                            forKey: operationRecoveryNotificationRootKey(recovery.rootPath)
                        )
                        self.feedbackCenter.expire(
                            notificationID: self.logApplyRecoveryNotificationID(
                                rootPath: recovery.rootPath
                            )
                        )
                    }
                }
                if state.kind == .merge {
                    self.pendingMergeDeleteBranch = nil
                    self.mergeInitialHead = nil
                }
                if state.kind == .rebase, rebaseSessionID == nil {
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = nil
                    if let singleRootRebaseSeed {
                        clearRebaseUndoSeed(repositoryPath: singleRootRebaseSeed.repositoryPath)
                    } else if let rebaseRootPath {
                        clearRebaseUndoSeed(repositoryPath: rebaseRootPath)
                    }
                }
                if state.kind == .rebase,
                   let rebaseRootPath,
                   let rebaseSessionID {
                    self.handleMultiRootRebaseRecovery(
                        rootPath: rebaseRootPath,
                        action: .abort,
                        operationStillActive: operationStillActive,
                        sessionID: rebaseSessionID
                    )
                    self.refreshAll(showFeedback: false)
                    return
                }
                self.refreshAll(showFeedback: false)
                self.feedbackCenter.success(
                    "Operation aborted",
                    detail: "The repository was restored to its pre-operation state.",
                    notificationID: operationNotificationID
                )
            }
        } catch {
            let latestState = try? repo.operationState()
            let latestRootPath = repo.workdir()
            await MainActor.run {
                self.operationFeedback = friendlyRemoteError(error)
                // Abort failures must retain the current Git operation and
                // its latest conflicts, not the snapshot captured at click
                // time. This keeps Retry/Continue/Abort root-qualified.
                self.refreshAll(showFeedback: false)
                if case let .StashApplyConflict(paths, stashID) = error as? EngineError {
                    self.showStashRestoreConflict(
                        paths,
                        operationName: state.kind == .cherryPick ? "Cherry-pick" : "Revert",
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repo.workdir()
                        ).map { [$0] } ?? [],
                        notificationID: operationNotificationID,
                        stashID: stashID
                    )
                } else if case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                    self.presentShelveConflict(
                        name: name,
                        paths: paths,
                        isPop: true,
                        additionalActions: self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: repo.workdir()
                        ).map { [$0] } ?? [],
                        notificationID: operationNotificationID
                    )
                } else {
                    let recoveryRootPath = latestRootPath ?? rebaseRootPath
                    let recoveryActions: [FeedbackAction]
                    if let latestState, let recoveryRootPath {
                        recoveryActions = self.operationRecoveryFeedbackActions(
                            state: latestState,
                            rootPath: recoveryRootPath
                        )
                    } else {
                        recoveryActions = []
                    }
                    self.feedbackCenter.error(
                        "Abort failed",
                        detail: errorMessage(error),
                        nextStep: "状态已保留，可重试或选择其他动作。",
                        additionalActions: recoveryActions + (self.pendingSavedChangesFeedbackAction(
                            repo: repo,
                            rootPath: latestRootPath ?? rebaseRootPath
                        ).map { [$0] } ?? []),
                        notificationID: recoveryRootPath.map {
                            operationRecoveryNotificationID(rootPath: $0)
                        }
                    )
                }
            }
        }
    }
}

/// Keeps operation failures and the recovery bar on the same project-level
/// conflict entry point. The resolver rescans every Git root, so the action
/// remains valid after another root changed while the notification was open.
var operationConflictResolverAction: (() -> Void)? {
    guard let state = operationState,
          !state.conflictedFiles.isEmpty else { return nil }
    let preferredRootPath = projectPath
    let preferredPath = state.conflictedFiles.first
    return {
        var userInfo: [AnyHashable: Any] = [:]
        if let preferredRootPath {
            userInfo["rootPath"] = preferredRootPath
        }
        if let preferredPath {
            userInfo["path"] = preferredPath
        }
        NotificationCenter.default.post(
            name: .arborOpenMultiRootConflictResolver,
            object: nil,
            userInfo: userInfo
        )
    }
}

func openActiveOperationConflictResolver() {
    operationConflictResolverAction?()
}

/// 打开项目级统一冲突 resolver。所有 root 的状态先在后台重新读取，
/// 然后由同一个队列视图管理当前 root；不能复用当前窗口的 `repo`。
func openMultiRootConflictResolver(
    preferredRootPath: String? = nil,
    preferredPath: String? = nil
) {
    guard let projectPath else { return }
    let currentRootPath = preferredRootPath ?? multiRootResolverActiveRootPath
    let pendingStashPaths = multiRootStashConflicts
    let pendingStashIndexes = multiRootStashConflictIndexes
    let pendingStashIDs = multiRootStashConflictIDs
    let pendingStashPopModes = multiRootStashConflictPopModes
    multiRootResolverLoadGeneration += 1
    let generation = multiRootResolverLoadGeneration
    multiRootResolverWorking = true
    multiRootResolverError = nil
    multiRootResolverActiveRepo = nil
    multiRootResolverActiveEntries = []
    multiRootResolverActiveKind = nil

    Task.detached(priority: .userInitiated) {
        do {
            let discovered = try discoverGitRoots(scanRoot: projectPath, maxDepth: nil)
            let pendingRoots = stableMultiRootConflictResolverRoots(
                discovered.compactMap { root -> MultiRootConflictResolverRoot? in
                guard let rootRepo = try? openRepository(path: root.path) else { return nil }
                let state = try? rootRepo.operationState()
                let statusPaths = ((try? rootRepo.status()) ?? [])
                    .filter { $0.staged == .conflicted || $0.unstaged == .conflicted }
                    .map(\.path)
                    .sorted()

                if let state {
                    let paths = Array(Set(statusPaths + state.conflictedFiles)).sorted()
                    return MultiRootConflictResolverRoot(
                        rootPath: root.path,
                        displayName: root.displayName,
                        relativePath: root.relativePath,
                        paths: paths,
                        kind: .operation(state.kind)
                    )
                }

                if let stashPaths = pendingStashPaths[root.path] {
                    return MultiRootConflictResolverRoot(
                        rootPath: root.path,
                        displayName: root.displayName,
                        relativePath: root.relativePath,
                        paths: statusPaths.isEmpty ? stashPaths.sorted() : statusPaths,
                        kind: .stash(
                            stashID: pendingStashIDs[root.path],
                            index: pendingStashIndexes[root.path] ?? 0,
                            isPop: pendingStashPopModes[root.path] ?? false
                        )
                    )
                }

                let shelveRestore = (try? rootRepo.shelveRestoreInfo()) ?? nil
                if let shelveRestore {
                    return MultiRootConflictResolverRoot(
                        rootPath: root.path,
                        displayName: root.displayName,
                        relativePath: root.relativePath,
                        paths: statusPaths.isEmpty ? shelveRestore.paths : statusPaths,
                        kind: .shelve(name: shelveRestore.name, isPop: shelveRestore.isPop)
                    )
                }

                let applyInfo = (try? rootRepo.applyLocalChangesRestoreInfo()) ?? nil
                if let applyInfo, applyInfo.kind == "stash",
                   let stashIndex = try? rootRepo.stashList().firstIndex(where: {
                       $0.id == applyInfo.identifier
                   }) {
                    return MultiRootConflictResolverRoot(
                        rootPath: root.path,
                        displayName: root.displayName,
                        relativePath: root.relativePath,
                        paths: statusPaths,
                        kind: .stash(
                            stashID: applyInfo.identifier,
                            index: stashIndex,
                            isPop: true
                        )
                    )
                }
                if let applyInfo, applyInfo.kind == "shelf" {
                    return MultiRootConflictResolverRoot(
                        rootPath: root.path,
                        displayName: root.displayName,
                        relativePath: root.relativePath,
                        paths: statusPaths,
                        kind: .shelve(name: applyInfo.identifier, isPop: true)
                    )
                }

                guard !statusPaths.isEmpty else { return nil }
                return MultiRootConflictResolverRoot(
                    rootPath: root.path,
                    displayName: root.displayName,
                    relativePath: root.relativePath,
                    paths: statusPaths,
                    kind: .workingTree
                )
                }
            )
            let selected = pendingRoots.first(where: { $0.rootPath == currentRootPath })
                ?? pendingRoots.first

            await MainActor.run {
                guard self.multiRootResolverLoadGeneration == generation else { return }
                self.multiRootResolverRoots = pendingRoots
                self.multiRootResolverActiveRootPath = selected?.rootPath
                self.multiRootResolverActiveInitialPath = selected?.paths.first
                self.multiRootResolverWorking = false
                self.multiRootResolverError = nil
                self.showMultiRootConflictResolver = selected != nil
                if let selected {
                    self.selectMultiRootResolverRoot(selected.rootPath)
                    if let preferredPath, selected.paths.contains(preferredPath) {
                        self.multiRootResolverActiveInitialPath = preferredPath
                    }
                }
            }
        } catch {
            await MainActor.run {
                guard self.multiRootResolverLoadGeneration == generation else { return }
                self.multiRootResolverWorking = false
                self.multiRootResolverError = errorMessage(error)
                self.feedbackCenter.error(
                    "Conflict workbench unavailable",
                    detail: errorMessage(error),
                    nextStep: "Refresh Git Roots, then reopen the project conflict resolver."
                )
            }
        }
    }
}

/// 选择统一 resolver 中的 root，并只加载该 root 的 Repository/status。
func selectMultiRootResolverRoot(_ rootPath: String) {
    guard let root = multiRootResolverRoots.first(where: { $0.rootPath == rootPath }) else { return }
    multiRootResolverActiveRootPath = rootPath
    multiRootResolverActiveInitialPath = root.paths.first
    multiRootResolverActiveKind = root.kind
    multiRootResolverActiveRepo = nil
    multiRootResolverActiveEntries = []
    multiRootResolverWorking = true
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let entries = try rootRepo.status()
            await MainActor.run {
                guard self.multiRootResolverActiveRootPath == rootPath else { return }
                self.multiRootResolverActiveRepo = rootRepo
                self.multiRootResolverActiveEntries = entries
                self.multiRootResolverWorking = false
                self.multiRootResolverError = nil
            }
        } catch {
            await MainActor.run {
                guard self.multiRootResolverActiveRootPath == rootPath else { return }
                self.multiRootResolverWorking = false
                self.multiRootResolverError = "\(root.displayName): \(errorMessage(error))"
            }
        }
    }
}

func refreshMultiRootResolverActiveRoot() {
    guard let rootRepo = multiRootResolverActiveRepo,
          let rootPath = multiRootResolverActiveRootPath else { return }
    Task.detached(priority: .userInitiated) {
        let entries = (try? rootRepo.status()) ?? []
        await MainActor.run {
            guard self.multiRootResolverActiveRootPath == rootPath,
                  self.multiRootResolverActiveRepo === rootRepo else { return }
            self.multiRootResolverActiveEntries = entries
        }
    }
}

func completeMultiRootResolverRoot() {
    guard let root = multiRootResolverRoots.first(where: {
        $0.rootPath == self.multiRootResolverActiveRootPath
    }) else { return }
    switch root.kind {
    case .operation:
        runMultiRootResolverRecovery(rootPath: root.rootPath, action: .continueOperation)
    case .stash:
        completeMultiRootResolverStash(root)
    case .shelve(let name, _):
        completeMultiRootResolverShelf(root, name: name)
    case .workingTree:
        openMultiRootConflictResolver(preferredRootPath: root.rootPath)
    }
}

func skipMultiRootResolverRoot() {
    guard let root = multiRootResolverRoots.first(where: {
        $0.rootPath == self.multiRootResolverActiveRootPath
    }), root.canSkip else { return }
    runMultiRootResolverRecovery(rootPath: root.rootPath, action: .skip)
}

func abortMultiRootResolverRoot() {
    guard let root = multiRootResolverRoots.first(where: {
        $0.rootPath == self.multiRootResolverActiveRootPath
    }) else { return }
    switch root.kind {
    case .operation:
        runMultiRootResolverRecovery(rootPath: root.rootPath, action: .abort)
    case .shelve(let name, _):
        abortMultiRootResolverShelf(root, name: name)
    case .stash, .workingTree:
        break
    }
}

func closeMultiRootResolver() {
    multiRootResolverLoadGeneration += 1
    showMultiRootConflictResolver = false
    multiRootResolverWorking = false
    multiRootResolverActiveRepo = nil
    multiRootResolverActiveEntries = []
    multiRootResolverActiveKind = nil
}

/// 统一 resolver 中的 Continue/Skip/Abort。完成一个 root 后立即重读整个
/// root 队列，因此 rebase 的下一暂停步骤和其它 root 都会留在同一窗口。
private func runMultiRootResolverRecovery(
    rootPath: String,
    action: MultiRootRecoveryAction,
    stageTrackedBeforeContinue: Bool = false
) {
    guard !multiRootResolverWorking else { return }
    let restoresUpdateLocalChanges = multiRootUpdateStashedRoots.contains(rootPath)
    let batchRebaseSessionID = multiRootRebaseSession?.roots.contains(where: { $0.rootPath == rootPath }) == true
        ? multiRootRebaseSession?.id
        : nil
    let protectedPatterns = effectiveProtectedBranchPatterns
    multiRootResolverWorking = true
    multiRootResolverError = nil
    beginFeedbackOperation("Multi-root recovery")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            guard let state = try rootRepo.operationState() else {
                throw NSError(
                    domain: "Arbor.MultiRootRecovery",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "该 Git root 没有可恢复的进行中操作。"]
                )
            }
            let previousHead = rootRepo.headCommitId()
            let sourceBranch = state.kind == .merge && state.origin == .engine
                ? rootRepo.mergeSourceReference()
                : nil
            let messageMonitor = Task.detached(priority: .userInitiated) {
                while !Task.isCancelled {
                    if let pending = try? rootRepo.rebasePendingMessage() {
                        await MainActor.run {
                            guard !self.showRawRebaseMessageEditor else { return }
                            self.rawRebaseMessageRepository = rootRepo
                            self.rawRebaseMessageText = pending
                            self.showRawRebaseMessageEditor = true
                        }
                    }
                    try? await Task.sleep(nanoseconds: 100_000_000)
                }
            }
            defer { messageMonitor.cancel() }
            switch action {
            case .continueOperation:
                switch state.kind {
                case .merge:
                    _ = try state.origin == .engine
                        ? rootRepo.finishMerge(message: nil)
                        : rootRepo.mergeContinue(message: nil)
                case .rebase:
                    if stageTrackedBeforeContinue {
                        try rootRepo.stageTracked()
                    }
                    _ = try rootRepo.rebaseContinue()
                case .cherryPick:
                    try rootRepo.cherryPickContinueWithOptions(
                        emptyPolicy: configuredCherryPickEmptyPolicy()
                    )
                case .revert:
                    try rootRepo.revertContinue()
                }
            case .skip:
                guard state.kind == .rebase else {
                    throw NSError(
                        domain: "Arbor.MultiRootRecovery",
                        code: 2,
                        userInfo: [NSLocalizedDescriptionKey: "只有 rebase 支持 Skip。"]
                    )
                }
                _ = try rootRepo.rebaseSkip()
            case .abort:
                switch state.kind {
                case .merge: try rootRepo.mergeAbort()
                case .rebase: try rootRepo.rebaseAbort()
                case .cherryPick: try rootRepo.cherryPickAbort()
                case .revert: try rootRepo.revertAbort()
                }
            }

            let operationStillActive = try rootRepo.operationState() != nil
            let currentHead = rootRepo.headCommitId()
            var stashConflictPaths: [String]?
            var stashConflictIndex: Int?
            var stashConflictID: String?
            var stashRestoreFailure: String?
            var shelfRestoreConflict = false
            if restoresUpdateLocalChanges && !operationStillActive {
                let shelves = try rootRepo.shelveList()
                if let shelf = shelves.first(where: { isArborTemporaryShelfName($0.name) }) {
                    do {
                        try rootRepo.shelvePopPreservation(name: shelf.name)
                    } catch let error as EngineError {
                        if case .ShelveApplyConflict = error {
                            shelfRestoreConflict = true
                        } else {
                            stashRestoreFailure = errorMessage(error)
                        }
                    } catch {
                        stashRestoreFailure = errorMessage(error)
                    }
                } else {
                    let stashes = try rootRepo.stashList()
                    if let indexedStash = stashes.enumerated().first(where: {
                        isArborTemporaryStashMessage($0.element.message)
                    }) {
                    do {
                        try rootRepo.stashPopWithIndex(
                            index: try currentStashIndex(
                                repo: rootRepo,
                                stashID: indexedStash.element.id
                            ),
                            restoreIndex: true
                        )
                    } catch let error as EngineError {
                        if case let .StashApplyConflict(paths, conflictStashID) = error {
                            stashConflictPaths = paths
                            stashConflictIndex = indexedStash.offset
                            stashConflictID = conflictStashID ?? indexedStash.element.id
                        } else {
                            stashRestoreFailure = errorMessage(error)
                        }
                    } catch {
                        stashRestoreFailure = errorMessage(error)
                    }
                } else {
                    stashRestoreFailure = "The temporary Update Project stash could not be located."
                }
                }
            }

            let canProposeDelete = action == .continueOperation
                && !operationStillActive
                && stashConflictPaths == nil
                && !shelfRestoreConflict
                && stashRestoreFailure == nil
                && sourceBranch.map {
                    canProposeDeleteMergedBranch(
                        repo: rootRepo,
                        branch: $0,
                        protectedPatterns: protectedPatterns
                    )
                } ?? false

            let resolvedStashConflictPaths = stashConflictPaths
            let resolvedStashConflictIndex = stashConflictIndex
            let resolvedStashConflictID = stashConflictID
            let resolvedStashRestoreFailure = stashRestoreFailure
            let resolvedShelfRestoreConflict = shelfRestoreConflict
            await MainActor.run {
                self.multiRootResolverWorking = false
                if (self.rawRebaseMessageRepository?.workdir() ?? "") == rootPath {
                    self.showRawRebaseMessageEditor = false
                    self.rawRebaseMessageRepository = nil
                    self.rawRebaseMessageText = ""
                }
                if let resolvedStashConflictPaths {
                    self.multiRootStashConflicts[rootPath] = resolvedStashConflictPaths
                    self.multiRootStashConflictIndexes[rootPath] = resolvedStashConflictIndex ?? 0
                    self.multiRootStashConflictIDs[rootPath] = resolvedStashConflictID
                    self.multiRootStashConflictPopModes[rootPath] = true
                } else if resolvedStashRestoreFailure == nil
                            && !resolvedShelfRestoreConflict
                            && restoresUpdateLocalChanges {
                    self.multiRootUpdateStashedRoots.remove(rootPath)
                }
                if resolvedShelfRestoreConflict {
                    self.multiRootResolverError = nil
                    self.openMultiRootConflictResolver(preferredRootPath: rootPath)
                } else if let resolvedStashRestoreFailure {
                    self.multiRootResolverError = "\(rootPath): \(resolvedStashRestoreFailure)"
                } else if state.kind == .rebase, let batchRebaseSessionID {
                    self.closeMultiRootResolver()
                    self.handleMultiRootRebaseRecovery(
                        rootPath: rootPath,
                        action: action,
                        operationStillActive: operationStillActive,
                        sessionID: batchRebaseSessionID
                    )
                    if operationStillActive {
                        self.openMultiRootConflictResolver(preferredRootPath: rootPath)
                    }
                } else {
                    self.multiRootResolverError = nil
                    let mergeViewCommitsAction = state.kind == .merge
                        && action == .continueOperation
                        ? self.completedMergeViewCommitsAction(
                            rootPath: rootPath,
                            initialHead: previousHead,
                            finalHead: currentHead,
                            completed: !operationStillActive
                        )
                        : nil
                    if canProposeDelete, let sourceBranch {
                        self.feedbackCenter.success(
                            "Merge completed",
                            detail: "\(sourceBranch) · \(rootPath)",
                            actionTitle: "Delete branch",
                            action: postMergeDeleteAction(
                                repo: rootRepo,
                                branch: sourceBranch,
                                rootPath: rootPath
                            ),
                            additionalActions: mergeViewCommitsAction.map { [$0] } ?? [],
                            notificationGroup: .standard
                        )
                    } else if let mergeViewCommitsAction {
                        self.feedbackCenter.success(
                            "Merge completed",
                            detail: rootPath,
                            additionalActions: [mergeViewCommitsAction],
                            notificationGroup: .standard
                        )
                    } else {
                        self.feedbackCenter.success(
                            "Git root recovery completed",
                            detail: "\(rootPath): \(multiRootRecoveryTitle(action))"
                        )
                    }
                }
                self.openMultiRootConflictResolver(preferredRootPath: rootPath)
            }
        } catch {
            let canStageAndRetry: Bool = {
                guard action == .continueOperation else { return false }
                guard batchRebaseSessionID != nil else { return false }
                guard let rootRepo = try? openRepository(path: rootPath) else { return false }
                return (try? rootRepo.status().contains {
                    $0.unstaged != .unchanged
                        && $0.unstaged != .untracked
                        && $0.unstaged != .ignored
                        && $0.unstaged != .conflicted
                }) ?? false
            }()
            await MainActor.run {
                self.multiRootResolverWorking = false
                if case let .StashApplyConflict(paths, stashID) = error as? EngineError {
                    self.presentMultiRootMergeRestoreConflict(
                        rootPath: rootPath,
                        paths: paths,
                        stashID: stashID
                    )
                    return
                }
                if case .ShelveApplyConflict = error as? EngineError {
                    self.presentMultiRootMergeRestoreConflict(rootPath: rootPath, paths: [])
                    return
                }
                self.multiRootResolverError = "\(rootPath): \(errorMessage(error))"
                let stageAndRetryAction = canStageAndRetry
                    ? batchRebaseSessionID.map {
                        self.multiRootRebaseRecoveryFeedbackAction(
                            .stageAndRetry,
                            rootPath: rootPath,
                            sessionID: $0
                        )
                    }
                    : nil
                self.feedbackCenter.error(
                    "Multi-root recovery failed",
                    detail: self.multiRootResolverError,
                    nextStep: "Resolve the remaining conflicts in that root, then retry Continue, Skip, or Abort.",
                    additionalActions: stageAndRetryAction.map { [$0] } ?? [],
                    notificationID: self.multiRootRebaseNotificationID()
                )
                self.refreshMultiRootResolverActiveRoot()
            }
        }
    }
}

private func stageAndRetryMultiRootRebaseContinue(rootPath: String, sessionID: UUID) {
    guard multiRootRebaseSession?.id == sessionID else { return }
    runMultiRootResolverRecovery(
        rootPath: rootPath,
        action: .continueOperation,
        stageTrackedBeforeContinue: true
    )
}

private func completeMultiRootResolverStash(_ root: MultiRootConflictResolverRoot) {
    guard case let .stash(stashID, _, isPop) = root.kind,
          let rootRepo = multiRootResolverActiveRepo else { return }
    multiRootResolverWorking = true
    multiRootResolverError = nil
    Task.detached(priority: .userInitiated) {
        do {
            let conflicts = try rootRepo.status().filter {
                $0.staged == .conflicted || $0.unstaged == .conflicted
            }
            guard conflicts.isEmpty else {
                throw NSError(
                    domain: "Arbor.MultiRootStashRestore",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "仍有冲突文件未解决：\(conflicts.map(\.path).joined(separator: ", "))"]
                )
            }
            if isPop {
                let finalizedPreserved = try rootRepo.finalizeApplyLocalChangesRestore()
                if !finalizedPreserved {
                    guard let stashID else {
                        throw NSError(
                            domain: "Arbor.MultiRootStashRestore",
                            code: 2,
                            userInfo: [NSLocalizedDescriptionKey: "The stash identity is unavailable; the stash was kept."]
                        )
                    }
                    try rootRepo.stashDrop(index: try currentStashIndex(repo: rootRepo, stashID: stashID))
                }
            }
            await MainActor.run {
                self.multiRootStashConflicts[root.rootPath] = nil
                self.multiRootStashConflictIndexes[root.rootPath] = nil
                self.multiRootStashConflictIDs[root.rootPath] = nil
                self.multiRootStashConflictPopModes[root.rootPath] = nil
                if isPop {
                    if let stashID {
                        self.clearStashDiffIfMatching(rootPath: root.rootPath, stashID: stashID)
                    }
                    self.multiRootUpdateStashedRoots.remove(root.rootPath)
                }
                self.multiRootResolverWorking = false
                self.feedbackCenter.success(
                    isPop ? "Stash pop completed" : "Stash apply completed",
                    detail: root.rootPath
                )
                self.openMultiRootConflictResolver(preferredRootPath: root.rootPath)
            }
        } catch {
            await MainActor.run {
                self.multiRootResolverWorking = false
                self.multiRootResolverError = "\(root.rootPath): \(errorMessage(error))"
                self.refreshMultiRootResolverActiveRoot()
            }
        }
    }
}

private func completeMultiRootResolverShelf(
    _ root: MultiRootConflictResolverRoot,
    name: String
) {
    guard case let .shelve(_, isPop) = root.kind,
          let rootRepo = multiRootResolverActiveRepo else { return }
    let batchRebaseSessionID = isPop
        && multiRootRebaseSession?.roots.contains(where: { $0.rootPath == root.rootPath }) == true
        ? multiRootRebaseSession?.id
        : nil
    multiRootResolverWorking = true
    multiRootResolverError = nil
    Task.detached(priority: .userInitiated) {
        do {
            let conflicts = try rootRepo.status().filter {
                $0.staged == .conflicted || $0.unstaged == .conflicted
            }
            guard conflicts.isEmpty else {
                throw NSError(
                    domain: "Arbor.MultiRootShelfRestore",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "仍有冲突文件未解决：\(conflicts.map(\.path).joined(separator: ", "))"]
                )
            }
            // A crash can happen after the preserving apply marker is written
            // but before the Shelf restore snapshot is created. In that
            // narrow window there is no shelveRestoreInfo yet; replay the
            // exact marked Shelf so a clean apply finalizes the marker and a
            // conflicting apply creates the normal restore snapshot.
            let pendingShelveRestore = (try? rootRepo.shelveRestoreInfo()) ?? nil
            let applyInfo = (try? rootRepo.applyLocalChangesRestoreInfo()) ?? nil
            if pendingShelveRestore == nil,
               let applyInfo,
               applyInfo.kind == "shelf",
               applyInfo.identifier == name {
                try rootRepo.shelvePopPreservation(name: name)
                _ = try rootRepo.finalizeApplyLocalChangesRestore()
            } else {
                try rootRepo.shelveCompleteRestore(name: name)
            }
            await MainActor.run {
                self.multiRootResolverWorking = false
                self.multiRootResolverError = nil
                if let batchRebaseSessionID {
                    self.closeMultiRootResolver()
                    self.handleMultiRootRebaseRecovery(
                        rootPath: root.rootPath,
                        action: .continueOperation,
                        operationStillActive: false,
                        sessionID: batchRebaseSessionID
                    )
                } else {
                    self.feedbackCenter.success(
                        isPop ? "Shelf pop completed" : "Unshelve completed",
                        detail: "\(root.rootPath) · \(name)"
                    )
                    self.openMultiRootConflictResolver(preferredRootPath: root.rootPath)
                }
            }
        } catch {
            await MainActor.run {
                self.multiRootResolverWorking = false
                self.multiRootResolverError = "\(root.rootPath): \(errorMessage(error))"
                self.refreshMultiRootResolverActiveRoot()
            }
        }
    }
}

private func abortMultiRootResolverShelf(
    _ root: MultiRootConflictResolverRoot,
    name: String
) {
    guard let rootRepo = multiRootResolverActiveRepo else { return }
    let batchRebaseSessionID = multiRootRebaseSession?.roots.contains(where: { $0.rootPath == root.rootPath }) == true
        ? multiRootRebaseSession?.id
        : nil
    multiRootResolverWorking = true
    multiRootResolverError = nil
    Task.detached(priority: .userInitiated) {
        do {
            try rootRepo.shelveAbortRestore(name: name)
            await MainActor.run {
                self.multiRootResolverWorking = false
                self.multiRootResolverError = nil
                if let batchRebaseSessionID {
                    self.closeMultiRootResolver()
                    self.handleMultiRootRebaseRecovery(
                        rootPath: root.rootPath,
                        action: .continueOperation,
                        operationStillActive: false,
                        sessionID: batchRebaseSessionID
                    )
                } else {
                    self.feedbackCenter.success(
                        "Shelf restore rolled back",
                        detail: "\(root.rootPath) · \(name)"
                    )
                    self.openMultiRootConflictResolver(preferredRootPath: root.rootPath)
                }
            }
        } catch {
            await MainActor.run {
                self.multiRootResolverWorking = false
                self.multiRootResolverError = "\(root.rootPath): \(errorMessage(error))"
                self.refreshMultiRootResolverActiveRoot()
            }
        }
    }
}

/// 多 root 恢复动作必须以 root 路径打开对应 Repository；不能复用当前窗口的
/// `repo`，否则会把一个 root 的冲突恢复误应用到另一个 root。
func openMultiRootOperationConflict(rootPath: String, path: String? = nil) {
    openMultiRootConflictResolver(preferredRootPath: rootPath, preferredPath: path)
}

/// 项目级冲突树的批量 Accept。按 root 分组打开 Repository，逐文件继续执行，
/// 因此一个 root 或单个文件失败不会回滚已经成功的其它文件。
func acceptMultiRootConflicts(_ targets: [MultiRootConflictTarget], pick: FilePick) {
    guard !targets.isEmpty, !multiRootConflictBatchWorking else { return }
    var seen = Set<String>()
    let selected = targets
        .filter { seen.insert($0.id).inserted }
        .sorted {
            if $0.rootPath != $1.rootPath { return $0.rootPath < $1.rootPath }
            return $0.path < $1.path
        }
    guard !selected.isEmpty else { return }

    multiRootConflictBatchWorking = true
    multiRootConflictBatchError = nil
    Task.detached(priority: .userInitiated) {
        let grouped = Dictionary(grouping: selected, by: \.rootPath)
        var failures: [String] = []

        for rootPath in grouped.keys.sorted() {
            guard let rootTargets = grouped[rootPath] else { continue }
            do {
                let rootRepo = try openRepository(path: rootPath)
                for target in rootTargets.sorted(by: { $0.path < $1.path }) {
                    do {
                        try rootRepo.acceptConflict(path: target.path, pick: pick)
                    } catch {
                        failures.append("\(target.rootPath)/\(target.path): \(error)")
                    }
                }
            } catch {
                failures.append(contentsOf: rootTargets.map {
                    "\($0.rootPath)/\($0.path): \(error)"
                })
            }
        }

        let failureMessage = failures.isEmpty ? nil : failures.joined(separator: "\n")
        await MainActor.run {
            self.multiRootConflictBatchWorking = false
            self.multiRootConflictBatchError = failureMessage
            self.loadMultiRoots()
            self.refreshAll(showFeedback: false)
        }
    }
}

private func presentMultiRootUpdateRestoreConflicts(_ results: [RootOperationResult]) {
    let roots = results.filter {
        !$0.success && $0.message.localizedCaseInsensitiveContains("local restore conflicted")
    }
    for result in roots {
        let rootPath = result.rootPath
        Task.detached(priority: .userInitiated) {
            do {
                let rootRepo = try openRepository(path: rootPath)
                let paths = try rootRepo.status().filter {
                    $0.staged == .conflicted || $0.unstaged == .conflicted
                }.map(\.path)
                let shelveRestore = (try? rootRepo.shelveRestoreInfo()) ?? nil
                let stash = try rootRepo.stashList().enumerated().first {
                    isArborUpdateStashMessage($0.element.message)
                }
                await MainActor.run {
                    if shelveRestore != nil {
                        self.openMultiRootConflictResolver(preferredRootPath: rootPath)
                        return
                    }
                    guard !paths.isEmpty, let stash else {
                        self.feedbackCenter.error(
                            "Update local changes unavailable",
                            detail: "\(rootPath): the temporary Update Project local-change save could not be located.",
                            nextStep: "Inspect that root's stash or Shelf list before changing its conflicted files."
                        )
                        return
                    }
                    self.presentMultiRootStashConflict(
                        rootPath: rootPath,
                        index: stash.offset,
                        stashID: stash.element.id,
                        isPop: true,
                        paths: paths
                    )
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Local restore conflict unavailable",
                        detail: "\(rootPath): \(errorMessage(error))",
                        nextStep: "Open that Git root and resolve its conflicted files manually."
                    )
                }
            }
        }
    }
}

/// Smart Checkout and Checkout and Update can also leave a named Shelf in a
/// pending restore state. Reuse the project resolver so this remains
/// root-scoped instead of falling back to the currently selected Repository.
private func presentMultiRootShelfRestoreConflicts(_ results: [RootOperationResult]) {
    for result in results where !result.success {
        let rootPath = result.rootPath
        Task.detached(priority: .userInitiated) {
            guard let rootRepo = try? openRepository(path: rootPath) else { return }
            let pending = (try? rootRepo.shelveRestoreInfo()) ?? nil
            let paths = ((try? rootRepo.status()) ?? [])
                .filter { $0.staged == .conflicted || $0.unstaged == .conflicted }
                .map(\.path)
            let stash = try? rootRepo.stashList().enumerated().first(where: {
                $0.element.message.hasPrefix("Arbor: Smart Checkout to")
                    || $0.element.message.hasPrefix("Arbor: Checkout and Update to")
            })
            await MainActor.run {
                if pending != nil {
                    self.openMultiRootConflictResolver(preferredRootPath: rootPath)
                } else if let stash {
                    self.presentMultiRootStashConflict(
                        rootPath: rootPath,
                        index: stash.offset,
                        stashID: stash.element.id,
                        isPop: true,
                        paths: paths
                    )
                }
            }
        }
    }
}

private func recoverMultiRootUpdateStashesAfterFailure(_ results: [RootOperationResult]) {
    let roots = results.filter {
        !$0.success
            && ($0.message.localizedCaseInsensitiveContains("local changes remain in stash")
                || $0.message.localizedCaseInsensitiveContains("local changes remain in shelf"))
    }
    for result in roots {
        let rootPath = result.rootPath
        Task.detached(priority: .userInitiated) {
            do {
                let rootRepo = try openRepository(path: rootPath)
                guard try rootRepo.operationState() == nil else { return }
                let shelf = try rootRepo.shelveList().first(where: { isArborUpdateShelfName($0.name) })
                let stash = try rootRepo.stashList().enumerated().first(where: {
                    isArborUpdateStashMessage($0.element.message)
                })
                guard shelf != nil || stash != nil else {
                    await MainActor.run {
                        self.feedbackCenter.error(
                            "Update local changes unavailable",
                            detail: "\(rootPath): the temporary Update Project local-change save could not be located.",
                            nextStep: "Inspect that root's stash or Shelf list before retrying Update."
                        )
                    }
                    return
                }
                do {
                    if let shelf {
                        try rootRepo.shelvePopPreservation(name: shelf.name)
                    } else if let stash {
                        try rootRepo.stashPopWithIndex(
                            index: try currentStashIndex(
                                repo: rootRepo,
                                stashID: stash.element.id
                            ),
                            restoreIndex: true
                        )
                    }
                    await MainActor.run {
                        self.multiRootUpdateStashedRoots.remove(rootPath)
                        self.loadMultiRoots()
                        self.feedbackCenter.success(
                            "Local changes restored",
                            detail: "\(rootPath): Update failed before completion, so the temporary local changes were restored."
                        )
                    }
                } catch let error as EngineError {
                    if case let .StashApplyConflict(paths, conflictStashID) = error {
                        await MainActor.run {
                            self.presentMultiRootStashConflict(
                                rootPath: rootPath,
                                index: stash?.offset ?? 0,
                                stashID: conflictStashID ?? stash?.element.id,
                                isPop: true,
                                paths: paths
                            )
                        }
                    } else if case .ShelveApplyConflict = error {
                        await MainActor.run {
                            self.openMultiRootConflictResolver(preferredRootPath: rootPath)
                        }
                    } else {
                        await MainActor.run {
                            self.feedbackCenter.error(
                                "Local changes restore failed",
                                detail: "\(rootPath): \(errorMessage(error))",
                                nextStep: "Retry the root-specific local-change restore after checking its Git status."
                            )
                        }
                    }
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Local changes restore failed",
                        detail: "\(rootPath): \(errorMessage(error))",
                        nextStep: "Inspect that Git root and restore its Update Project local changes manually."
                    )
                }
            }
        }
    }
}

/// Restore temporary Update Project local changes discovered after relaunch.
///
/// A Git operation in progress must be completed or aborted first; popping
/// the stash while merge/rebase metadata is active would mix two recovery
/// flows. If the root is clean from Git's operation-state perspective, this
/// follows the same root-scoped conflict workbench used by in-session Update.
func restoreMultiRootUpdateStash(rootPath: String) {
    guard !rootPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
    beginFeedbackOperation("Restore Update Project changes")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            guard try rootRepo.operationState() == nil else {
                throw NSError(
                    domain: "Arbor.MultiRootRecovery",
                    code: 3,
                    userInfo: [NSLocalizedDescriptionKey: "该 Git root 仍有进行中的操作，请先 Continue 或 Abort。"]
                )
            }
            let shelf = try rootRepo.shelveList().first(where: { isArborUpdateShelfName($0.name) })
            let stash = try rootRepo.stashList().enumerated().first(where: {
                isArborUpdateStashMessage($0.element.message)
            })
            guard shelf != nil || stash != nil else {
                throw NSError(
                    domain: "Arbor.MultiRootRecovery",
                    code: 4,
                    userInfo: [NSLocalizedDescriptionKey: "找不到临时 Update Project stash 或 Shelf。"]
                )
            }
            do {
                if let shelf {
                    try rootRepo.shelvePopPreservation(name: shelf.name)
                } else if let stash {
                    try rootRepo.stashPopWithIndex(
                        index: try currentStashIndex(
                            repo: rootRepo,
                            stashID: stash.element.id
                        ),
                        restoreIndex: true
                    )
                }
                await MainActor.run {
                    self.loadMultiRoots()
                    self.feedbackCenter.success(
                        "Local changes restored",
                        detail: "\(rootPath): the Update Project local changes were restored after relaunch."
                    )
                }
            } catch let error as EngineError {
                if case let .StashApplyConflict(paths, conflictStashID) = error {
                    await MainActor.run {
                        self.presentMultiRootStashConflict(
                            rootPath: rootPath,
                            index: stash?.offset ?? 0,
                            stashID: conflictStashID ?? stash?.element.id,
                            isPop: true,
                            paths: paths
                        )
                    }
                } else if case .ShelveApplyConflict = error {
                    await MainActor.run {
                        self.openMultiRootConflictResolver(preferredRootPath: rootPath)
                    }
                } else {
                    throw error
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Local changes restore failed",
                    detail: "\(rootPath): \(errorMessage(error))",
                    nextStep: "Inspect the root's status and Update Project stash before retrying."
                )
            }
        }
    }
}

func executeMultiRootRecovery(
    rootPath: String,
    action: MultiRootRecoveryAction
) {
    runMultiRootResolverRecovery(rootPath: rootPath, action: action)
}

private func multiRootRecoveryTitle(_ action: MultiRootRecoveryAction) -> String {
    switch action {
    case .continueOperation: return "Continue"
    case .skip: return "Skip"
    case .abort: return "Abort"
    }
}

/// stash pop 的冲突不是分支 merge，不创建新的 merge commit；用户解决后，
/// 只需确认所有冲突 stages 已清除，再删除已经成功应用的 stash 记录。
private func finishStashConflict() {
    guard let repo, stashPopConflictInProgress || stashApplyConflictInProgress else { return }
    let stashID = pendingStashPopID
    let shouldDropStash = stashPopConflictInProgress
    let repositoryPath = repo.workdir()
    let pullRebaseSeed = rebaseUndoSeed
    let conflictNotificationID = pendingStashConflictNotificationID
    beginFeedbackOperation(
        "Complete stash restore",
        notificationID: conflictNotificationID
    )
    Task.detached(priority: .userInitiated) {
        do {
            let st = try repo.status()
            let conflicts = st.filter {
                $0.staged == .conflicted || $0.unstaged == .conflicted
            }
            guard conflicts.isEmpty else {
                throw NSError(
                    domain: "Arbor.StashRestore",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "仍有冲突文件未解决：\(conflicts.map(\.path).joined(separator: ", "))"]
                )
            }
            if shouldDropStash {
                let finalizedPreserved = try repo.finalizeApplyLocalChangesRestore()
                if !finalizedPreserved {
                    guard let stashID else {
                        throw NSError(
                            domain: "Arbor.StashRestore",
                            code: 2,
                            userInfo: [NSLocalizedDescriptionKey: "The stash identity is unavailable; the stash was kept."]
                        )
                    }
                    try repo.stashDrop(index: try currentStashIndex(repo: repo, stashID: stashID))
                }
            }
            let pullRebaseRestoreCompleted = pullRebaseSeed != nil
                && (try? repo.operationState()) == nil
            let completedPullRebaseUndoTarget = pullRebaseRestoreCompleted
                ? pullRebaseSeed.flatMap { seed in
                    rebaseUndoTargetAfterCompletion(
                        seed: seed,
                        currentBranch: (try? repo.branchList())?.first(where: { $0.isCurrent })?.name,
                        finalHead: try? repo.revisionCommitId(revision: seed.branch)
                    )
                }
                : nil
            await MainActor.run {
                self.stashPopConflictInProgress = false
                self.stashApplyConflictInProgress = false
                self.pendingStashConflictNotificationID = nil
                self.pendingStashPopIndex = nil
                self.pendingStashPopID = nil
                self.pendingPullStashPop = false
                self.pendingPullStashID = nil
                self.pendingPullStashMessage = nil
                if let repositoryPath {
                    clearPendingPullPreservation(repositoryPath: repositoryPath)
                }
                if pullRebaseRestoreCompleted {
                    self.finishPendingPullRebaseRestore(
                        seed: pullRebaseSeed,
                        target: completedPullRebaseUndoTarget
                    )
                }
                self.mergeInProgress = false
                self.showMergeRevisionsDialog = false
                if shouldDropStash, let repositoryPath, let stashID {
                    self.clearStashDiffIfMatching(rootPath: repositoryPath, stashID: stashID)
                }
                self.mergeFeedback = shouldDropStash ? "已完成本地变更恢复" : "已完成 stash 应用"
                if let completedPullRebaseUndoTarget {
                    self.feedbackCenter.success(
                        "Local changes restored",
                        additionalActions: [self.rebaseUndoFeedbackAction(for: completedPullRebaseUndoTarget)],
                        notificationID: rebaseUndoNotificationID(
                            repositoryPath: completedPullRebaseUndoTarget.repositoryPath
                        ),
                        notificationGroup: .standard
                    )
                } else {
                    self.feedbackCenter.success(
                        shouldDropStash ? "Local changes restored" : "Stash applied",
                        notificationID: conflictNotificationID
                    )
                }
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                let detail = errorMessage(error)
                self.mergeFeedback = detail
                self.feedbackCenter.error(
                    "Complete stash restore failed",
                    detail: detail,
                    nextStep: "Resolve every conflicted file, then complete the restore.",
                    notificationID: conflictNotificationID
                )
            }
        }
    }
}

func loadRepoData(includeComparisons: Bool = true) {
    guard let repo else { return }
    Task.detached(priority: .userInitiated) {
        do {
            let bs = try repo.branchList()
            let ignoredRules = (try? repo.ignoredRules()) ?? []
            let comparisons = includeComparisons ? branchComparisonMap(repo: repo) : nil
            let ss = try repo.stashList()
            let sh = try repo.shelveList()
            let dsh = (try? repo.shelveDeletedList()) ?? []
            let rs = try repo.remoteList()
            let isShallow = repo.isShallow()
            let remoteBranches = (try? repo.remoteBranchList()) ?? []
            let recentBranches = (try? repo.recentBranches(limit: 10)) ?? []
            let syncStatuses = (try? repo.syncStatus()) ?? []
            let ts = try repo.tagList()
            let submodules = (try? repo.submoduleList()) ?? []
            let identity = (try? repo.gitIdentity()) ?? GitIdentity(name: nil, email: nil, signingKey: nil, signingFormat: nil, signCommits: false)
            await MainActor.run {
                guard self.projectRepo === repo else { return }
                self.branches = bs; self.ignoredRules = ignoredRules
                self.refreshLogMyBranches()
                if let comparisons { self.branchComparisons = comparisons }
                self.stashes = ss; self.remotes = rs
                self.isShallowRepository = isShallow
                self.restoreRemoteProtectedBranchPatterns(for: rs, projectPath: self.projectPath)
                self.remoteBranches = remoteBranches
                self.recentBranches = recentBranches; self.syncStatuses = syncStatuses
                self.shelves = sh; self.deletedShelves = dsh; self.tags = ts
                self.submodules = submodules
                self.identityName = identity.name ?? ""
                self.identityEmail = identity.email ?? ""
                self.identitySetNameEmailGlobally = GitIdentityScopeSettings.setNameEmailGlobally(
                    for: self.projectPath
                )
                self.identitySigningKey = identity.signingKey ?? ""
                self.identitySigningFormat = identity.signingFormat ?? "gpg"
                self.identitySignCommits = identity.signCommits
                self.refreshCherryPickedHighlights()
            }
        } catch { await MainActor.run { self.loadError = errorMessage(error) } }
    }
}

func setGitIdentity() {
    guard let repo else { return }
    let name = identityName.trimmingCharacters(in: .whitespacesAndNewlines)
    let email = identityEmail.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !name.isEmpty, !email.isEmpty else {
        loadError = "Git identity requires both name and email."
        return
    }
    let signingKey = identitySigningKey.trimmingCharacters(in: .whitespacesAndNewlines)
    let signingFormat = identitySigningFormat == "ssh" ? "ssh" : "gpg"
    let signCommits = identitySignCommits
    let setNameEmailGlobally = identitySetNameEmailGlobally
    let authorName = identityAuthorName.trimmingCharacters(in: .whitespacesAndNewlines)
    let authorEmail = identityAuthorEmail.trimmingCharacters(in: .whitespacesAndNewlines)
    let committerName = identityCommitterName.trimmingCharacters(in: .whitespacesAndNewlines)
    let committerEmail = identityCommitterEmail.trimmingCharacters(in: .whitespacesAndNewlines)
    let signOff = identitySignOff
    let coAuthors = identityCoAuthors
    beginFeedbackOperation("Save Git identity")
    Task.detached(priority: .userInitiated) {
        do {
            if setNameEmailGlobally {
                try repo.setGitIdentityWithGlobalNameEmail(
                    name: name,
                    email: email,
                    signingKey: signingKey.isEmpty ? nil : signingKey,
                    signingFormat: signingKey.isEmpty ? nil : signingFormat,
                    signCommits: signCommits
                )
            } else {
                try repo.setGitIdentity(
                    name: name,
                    email: email,
                    signingKey: signingKey.isEmpty ? nil : signingKey,
                    signingFormat: signingKey.isEmpty ? nil : signingFormat,
                    signCommits: signCommits
                )
            }
            await MainActor.run {
                GitIdentityScopeSettings.saveSetNameEmailGlobally(
                    setNameEmailGlobally,
                    for: self.projectPath
                )
                self.identityAuthorName = authorName
                self.identityAuthorEmail = authorEmail
                self.identityCommitterName = committerName
                self.identityCommitterEmail = committerEmail
                self.identitySignOff = signOff
                self.identityCoAuthors = coAuthors
                GitSignOffCommitSettings.saveGlobal(signOff)
                UserDefaults.standard.set(authorName, forKey: "arbor.identity.authorName")
                UserDefaults.standard.set(authorEmail, forKey: "arbor.identity.authorEmail")
                UserDefaults.standard.set(committerName, forKey: "arbor.identity.committerName")
                UserDefaults.standard.set(committerEmail, forKey: "arbor.identity.committerEmail")
                UserDefaults.standard.set(signOff, forKey: "arbor.identity.signOff")
                UserDefaults.standard.set(coAuthors, forKey: "arbor.identity.coAuthors")
                self.feedbackCenter.success("Git identity saved")
                if self.pendingIdentityCommitRetry {
                    self.pendingIdentityCommitRetry = false
                    DispatchQueue.main.async {
                        self.doCommit()
                    }
                }
            }
        } catch {
            await MainActor.run { self.feedbackCenter.error("Git identity failed", detail: errorMessage(error)) }
        }
    }
}

private func rememberCommitAuthor(name: String, email: String, projectPath: String?) {
    guard let value = GitCommitAuthorHistorySettings.formattedAuthor(name: name, email: email) else {
        return
    }
    GitCommitAuthorHistorySettings.save(value, for: projectPath)
    identityRecentAuthors = GitCommitAuthorHistorySettings.authors(for: projectPath)
}

private func parseCoAuthors(_ text: String) -> [String] {
    text.split(whereSeparator: \.isNewline)
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }
}

/// IntelliJ asks for a second confirmation only when resetting an existing
/// branch would actually drop commits that are not reachable from the chosen
/// start point. The checkbox itself is still the explicit opt-in for reset;
/// this guard protects the more destructive local-commit case.
private func confirmBranchResetIfNeeded(
    repo: Repository,
    name: String,
    startPoint: String?
) -> Bool {
    guard let branches = try? repo.branchList(),
          branches.contains(where: { $0.name == name }) else {
        return true
    }
    let base: String
    if let trimmed = startPoint?.trimmingCharacters(in: .whitespacesAndNewlines),
       !trimmed.isEmpty {
        base = trimmed
    } else {
        base = "HEAD"
    }
    guard let comparison = try? repo.branchCompare(a: name, b: base),
          comparison.ahead > 0 else {
        return true
    }

    let alert = NSAlert()
    alert.messageText = "Reset existing branch?"
    alert.informativeText = "(name) has (comparison.ahead) local commit(s) not contained in (base). Resetting it will discard those commits from the branch ref."
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Drop Local Commits")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    return alert.runModal() == .alertFirstButtonReturn
}

func branchCreate(
    at baseRevision: String? = nil,
    checkout: Bool = false,
    reset: Bool = false,
    repository repositoryOverride: Repository? = nil
) {
    guard let targetRepo = repositoryOverride ?? newBranchRepositoryOverride ?? repo else { return }
    let name = GitBranchNameCleanup.cleanUp(newBranchName)
        .trimmingCharacters(in: .whitespacesAndNewlines)
    guard !name.isEmpty else { return }
    let base = baseRevision?.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !reset || confirmBranchResetIfNeeded(
        repo: targetRepo,
        name: name,
        startPoint: base
    ) else { return }
    beginFeedbackOperation("Create branch")
    let targetRootPath = targetRepo.workdir() ?? "selected repository"
    Task.detached(priority: .userInitiated) {
        do {
            let startPoint = base?.isEmpty == true ? nil : base
            try targetRepo.branchCreateOrReset(
                name: name,
                at: startPoint,
                checkout: checkout,
                reset: reset
            )
            let bs = try targetRepo.branchList()
            await MainActor.run {
                if self.repo?.workdir() == targetRootPath {
                    self.branches = bs
                    self.loadRepoData()
                } else {
                    self.loadMultiRoots()
                }
                self.newBranchName = ""
                self.newBranchBase = ""
                self.feedbackCenter.success(
                    "Branch created",
                    detail: checkout
                        ? "\(name) (checked out) · \(targetRootPath)"
                        : "\(name) · \(targetRootPath)"
                )
                if self.toolWindowMode == .log { self.loadLog() }
            }
        } catch { await MainActor.run { self.loadError = errorMessage(error) } }
    }
}

/// Finish the remote Checkout with Rebase workflow after the user confirms
/// the local branch name in the shared New Branch dialog. Reuse the existing
/// checkout-with-rebase recovery path so conflicts remain resumable instead
/// of becoming an untracked background failure.
func branchCreateAndRebase(
    at baseRevision: String? = nil,
    reset: Bool = false,
    repository repositoryOverride: Repository? = nil
) {
    guard let targetRepo = repositoryOverride ?? newBranchRepositoryOverride ?? repo else { return }
    let name = GitBranchNameCleanup.cleanUp(newBranchName)
        .trimmingCharacters(in: .whitespacesAndNewlines)
    guard !name.isEmpty else { return }
    let base = baseRevision?.trimmingCharacters(in: .whitespacesAndNewlines)
    guard let existingBranches = try? targetRepo.branchList() else {
        feedbackCenter.error(
            "Checkout with Rebase failed",
            detail: "Unable to inspect the selected repository's local branches."
        )
        return
    }
    guard existingBranches.first(where: { $0.isCurrent })?.name != name else {
        feedbackCenter.error(
            "Checkout with Rebase failed",
            detail: "The branch '\(name)' is already checked out."
        )
        return
    }
    let branchAlreadyExists = existingBranches.contains { $0.name == name }
    guard !reset || confirmBranchResetIfNeeded(
        repo: targetRepo,
        name: name,
        startPoint: base
    ) else { return }
    beginFeedbackOperation("Create branch for Checkout with Rebase")
    Task.detached(priority: .userInitiated) {
        do {
            let startPoint = base?.isEmpty == true ? nil : base
            // Keep the original branch checked out while the rebase starts.
            // `rebaseBranchOnCurrentWithPolicy` deliberately rejects a target
            // that is already HEAD; the native operation then switches the
            // newly rebased branch into HEAD as IntelliJ does.
            // An existing local branch is intentionally reused when Reset is
            // off. IntelliJ's remote Checkout with Rebase workflow only
            // creates the branch for roots that do not already have it.
            if branchCreateAndRebaseShouldCreateBranch(
                branchAlreadyExists: branchAlreadyExists,
                resetExisting: reset
            ) {
                try targetRepo.branchCreateOrReset(
                    name: name,
                    at: startPoint,
                    checkout: false,
                    reset: reset
                )
            }
            let bs = try targetRepo.branchList()
            await MainActor.run {
                if self.repo?.workdir() == targetRepo.workdir() {
                    self.branches = bs
                    self.loadRepoData()
                } else {
                    self.loadMultiRoots()
                }
                self.newBranchName = ""
                self.newBranchBase = ""
                if self.toolWindowMode == .log { self.loadLog() }
                self.checkoutAndRebaseOntoCurrent(repo: targetRepo, name: name)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Checkout with Rebase failed",
                    detail: errorMessage(error),
                    nextStep: "Check the branch name and working tree, then retry."
                )
            }
        }
    }
}

func branchDelete(_ name: String) {
    guard let repo else { return }
    let protectedPatterns = effectiveProtectedBranchPatterns
    beginFeedbackOperation("Delete branch")
    Task.detached(priority: .userInitiated) {
        do {
            let preview = try? repo.branchDeletePreview(name: name)
            let syncStatusesBeforeDelete = (try? repo.syncStatus()) ?? []
            try repo.branchDelete(name: name, force: false)
            let bs = try repo.branchList()
            await MainActor.run {
                self.branches = bs
                if let preview {
                    let context = BranchDeleteRecoveryContext(
                        repo: repo,
                        preview: preview,
                        rootPath: nil,
                        trackedRemoteBranch: deletableTrackedRemoteBranch(
                            branchName: name,
                            upstream: preview.upstream,
                            syncStatuses: syncStatusesBeforeDelete,
                            protectedPatterns: protectedPatterns
                        )
                    )
                    self.branchDeleteRecovery = context
                    self.feedbackCenter.success(
                        "Branch deleted",
                        detail: name,
                        additionalActions: self.branchDeleteRecoveryActions(
                            contexts: [context]
                        ),
                        notificationID: self.branchDeleteNotificationID(),
                        notificationGroup: .standard
                    )
                } else {
                    self.feedbackCenter.success("Branch deleted", detail: name)
                }
                self.loadRepoData()
                if self.toolWindowMode == .log { self.loadLog() }
            }
        } catch {
            await MainActor.run {
                if isUnmergedBranchDeletionError(error) {
                    self.prepareForceDeleteBranch(repo: repo, name: name, rootPath: nil)
                } else {
                    self.loadError = errorMessage(error)
                }
            }
        }
    }
}

nonisolated private func isUnmergedBranchDeletionError(_ error: Error) -> Bool {
    errorMessage(error).localizedCaseInsensitiveContains("not fully merged")
}

private func prepareForceDeleteBranch(repo: Repository, name: String, rootPath: String?) {
    let protectedPatterns = effectiveProtectedBranchPatterns
    Task.detached(priority: .userInitiated) {
        do {
            let preview = try repo.branchDeletePreview(name: name)
            let syncStatusesBeforeDelete = (try? repo.syncStatus()) ?? []
            await MainActor.run {
                guard self.confirmForceDeleteBranch(preview: preview, rootPath: rootPath) else {
                    self.feedbackCenter.warning("Branch deletion cancelled", detail: name)
                    return
                }
                self.forceDeleteBranch(
                    repo: repo,
                    preview: preview,
                    rootPath: rootPath,
                    trackedRemoteBranch: deletableTrackedRemoteBranch(
                        branchName: name,
                        upstream: preview.upstream,
                        syncStatuses: syncStatusesBeforeDelete,
                        protectedPatterns: protectedPatterns
                    )
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Delete branch failed", detail: errorMessage(error))
            }
        }
    }
}

private func confirmForceDeleteBranch(preview: BranchDeletePreview, rootPath: String?) -> Bool {
    let alert = NSAlert()
    alert.messageText = "\(String(localized: "Branch is not fully merged")): \(preview.branchName)"
    let location = rootPath.map { "\n\(String(localized: "Repository")): \($0)" } ?? ""
    var details = String(localized: "Delete anyway? This permanently removes the local branch reference and can discard commits.")
    if !preview.baseBranches.isEmpty {
        details += "\n\n\(String(localized: "Already merged into")): \(preview.baseBranches.joined(separator: ", "))"
    }
    if !preview.unmergedCommits.isEmpty {
        let commits = preview.unmergedCommits
            .prefix(12)
            .map { "\($0.shortId) \($0.summary)" }
            .joined(separator: "\n")
        details += "\n\n\(String(localized: "Unmerged commits")):\n\(commits)"
        if preview.unmergedCommits.count > 12 {
            details += "\n…"
        }
    }
    alert.informativeText = "\(details)\(location)"
    alert.addButton(withTitle: String(localized: "Delete Anyway"))
    alert.addButton(withTitle: String(localized: "Cancel"))
    alert.buttons.first?.hasDestructiveAction = true
    return alert.runModal() == .alertFirstButtonReturn
}

private func forceDeleteBranch(
    repo: Repository,
    preview: BranchDeletePreview,
    rootPath: String?,
    trackedRemoteBranch: String?
) {
    beginFeedbackOperation("Force delete branch")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.branchDelete(name: preview.branchName, force: true)
            let bs = try repo.branchList()
            await MainActor.run {
                let context = BranchDeleteRecoveryContext(
                    repo: repo,
                    preview: preview,
                    rootPath: rootPath,
                    trackedRemoteBranch: trackedRemoteBranch
                )
                if let rootPath {
                    self.loadMultiRoots()
                    self.feedbackCenter.success(
                        "Branch deleted",
                        detail: "\(preview.branchName) · \(rootPath)",
                        additionalActions: self.branchDeleteRecoveryActions(
                            contexts: [context]
                        ),
                        notificationID: self.branchDeleteNotificationID(),
                        notificationGroup: .standard
                    )
                } else {
                    self.branches = bs
                    self.feedbackCenter.success(
                        "Branch deleted",
                        detail: "\(preview.branchName) (force)",
                        additionalActions: self.branchDeleteRecoveryActions(
                            contexts: [context]
                        ),
                        notificationID: self.branchDeleteNotificationID(),
                        notificationGroup: .standard
                    )
                    self.loadRepoData()
                    if self.toolWindowMode == .log { self.loadLog() }
                }
                self.branchDeleteRecovery = context
            }
        } catch {
            await MainActor.run {
                let detail = rootPath.map { "\(preview.branchName) · \($0): \(errorMessage(error))" } ?? errorMessage(error)
                self.feedbackCenter.error("Force delete branch failed", detail: detail)
            }
        }
    }
}

func restoreDeletedBranch(_ context: BranchDeleteRecoveryContext) {
    if let notificationID = branchDeleteNotificationID() {
        feedbackCenter.expire(notificationID: notificationID)
    }
    beginFeedbackOperation("Restore branch")
    Task.detached(priority: .userInitiated) {
        do {
            try context.repo.branchCreate(
                name: context.preview.branchName,
                at: context.preview.tipId
            )
            var upstreamError: String?
            if let upstream = context.preview.upstream {
                do {
                    try context.repo.branchSetUpstream(
                        branch: context.preview.branchName,
                        upstream: upstream
                    )
                } catch {
                    upstreamError = errorMessage(error)
                }
            }
            let restoreUpstreamError = upstreamError
            await MainActor.run {
                self.branchDeleteRecovery = nil
                if let rootPath = context.rootPath {
                    self.loadMultiRoots()
                    if let restoreUpstreamError {
                        self.feedbackCenter.warning(
                            "Branch restored",
                            detail: "\(context.preview.branchName) · \(rootPath). Upstream was not restored: \(restoreUpstreamError)"
                        )
                    } else {
                        self.feedbackCenter.success("Branch restored", detail: "\(context.preview.branchName) · \(rootPath)")
                    }
                } else {
                    self.branches = (try? context.repo.branchList()) ?? self.branches
                    self.loadRepoData()
                    if let restoreUpstreamError {
                        self.feedbackCenter.warning(
                            "Branch restored",
                            detail: "\(context.preview.branchName). Upstream was not restored: \(restoreUpstreamError)"
                        )
                    } else {
                        self.feedbackCenter.success("Branch restored", detail: context.preview.branchName)
                    }
                    if self.toolWindowMode == .log { self.loadLog() }
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Restore branch failed",
                    detail: "\(context.preview.branchName): \(errorMessage(error))",
                    additionalActions: self.branchDeleteRestoreAction(
                        contexts: [context],
                        title: "Retry Restore"
                    ).map { [$0] } ?? [],
                    notificationID: self.branchDeleteNotificationID(),
                    notificationGroup: .standard
                )
            }
        }
    }
}

/// IntelliJ Cleanup Branches 的项目级入口：加载所有 Git root 的本地分支，
/// 由 BranchCleanupDialogView 决定目标分支、前缀、合并状态和批量删除集合。
func deleteMergedBranches() {
    beginBranchCleanup()
}

private func nextBranchCleanupGeneration() -> Int {
    branchCleanupGeneration += 1
    return branchCleanupGeneration
}

private nonisolated func loadBranchCleanupRoots(scanRoot: String) throws -> [BranchCleanupRoot] {
    let roots = try discoverGitRoots(scanRoot: scanRoot, maxDepth: nil)
    return try roots.map { root in
        let rootRepo = try openRepository(path: root.path)
        let branches = try rootRepo.branchList()
        let syncStatuses = (try? rootRepo.syncStatus()) ?? []
        let trackingByBranch = Dictionary(
            uniqueKeysWithValues: syncStatuses
                .filter { $0.trackingExists }
                .map { ($0.branch, $0.upstream) }
        )
        return BranchCleanupRoot(
            rootPath: root.path,
            displayName: root.displayName,
            relativePath: root.relativePath,
            branches: branches,
            trackingByBranch: trackingByBranch,
            mergedBranches: [],
            calculatedTarget: nil,
            calculatedPrefix: nil,
            calculationError: nil
        )
    }
}

private struct BranchMergeScanResult {
    let index: Int
    let root: BranchCleanupRoot
    let repositoryScanned: Bool
    let candidateBranchesChecked: Int
    let mergedBranchesFound: Int
    let error: String?
}

private nonisolated func scanBranchMergeRoot(
    _ root: BranchCleanupRoot,
    index: Int,
    target: String,
    prefix: String
) -> BranchMergeScanResult {
    let candidates = root.branches.filter {
        $0.name != target && (prefix.isEmpty || $0.name.hasPrefix(prefix))
    }
    guard root.branches.contains(where: { $0.name == target }) else {
        let error = "target branch '\(target)' was not found"
        return BranchMergeScanResult(
            index: index,
            root: BranchCleanupRoot(
                rootPath: root.rootPath,
                displayName: root.displayName,
                relativePath: root.relativePath,
                branches: root.branches,
                trackingByBranch: root.trackingByBranch,
                mergedBranches: [],
                calculatedTarget: nil,
                calculatedPrefix: nil,
                calculationError: error
            ),
            repositoryScanned: false,
            candidateBranchesChecked: 0,
            mergedBranchesFound: 0,
            error: error
        )
    }

    do {
        let rootRepo = try openRepository(path: root.rootPath)
        let merged = try rootRepo.branchListMergedInto(target: target, prefix: prefix)
        // The engine and the UI both exclude the comparison branch. Keeping
        // this boundary here also protects older engine builds that returned
        // the target itself for an empty prefix.
        let mergedNames = Set(merged.map(\.name).filter { $0 != target })
        return BranchMergeScanResult(
            index: index,
            root: BranchCleanupRoot(
                rootPath: root.rootPath,
                displayName: root.displayName,
                relativePath: root.relativePath,
                branches: root.branches,
                trackingByBranch: root.trackingByBranch,
                mergedBranches: mergedNames,
                calculatedTarget: target,
                calculatedPrefix: prefix,
                calculationError: nil
            ),
            repositoryScanned: true,
            candidateBranchesChecked: candidates.count,
            mergedBranchesFound: mergedNames.count,
            error: nil
        )
    } catch {
        let error = errorMessage(error)
        return BranchMergeScanResult(
            index: index,
            root: BranchCleanupRoot(
                rootPath: root.rootPath,
                displayName: root.displayName,
                relativePath: root.relativePath,
                branches: root.branches,
                trackingByBranch: root.trackingByBranch,
                mergedBranches: [],
                calculatedTarget: nil,
                calculatedPrefix: nil,
                calculationError: error
            ),
            repositoryScanned: true,
            candidateBranchesChecked: candidates.count,
            mergedBranchesFound: 0,
            error: error
        )
    }
}

/// Find Merged follows IntelliJ's `reposWithTarget` boundary: a repository
/// without the requested local target is not a failed comparison and must not
/// make an otherwise successful multi-root scan look incomplete.
static func findMergedRootsContainingTarget(
    _ target: String,
    in roots: [BranchCleanupRoot]
) -> [BranchCleanupRoot] {
    roots.filter { root in
        root.branches.contains { $0.name == target }
    }
}

/// Scan roots concurrently in small batches. IntelliJ bounds its comparison
/// pool to five workers; batching gives the same upper bound while retaining
/// deterministic ordering and a cancellation boundary between batches.
private nonisolated func scanBranchMergeRoots(
    _ roots: [BranchCleanupRoot],
    target: String,
    prefix: String
) async -> [BranchMergeScanResult] {
    let batchSize = max(1, min(ProcessInfo.processInfo.activeProcessorCount, 5))
    var results: [BranchMergeScanResult] = []

    for start in stride(from: 0, to: roots.count, by: batchSize) {
        if Task.isCancelled { break }
        let end = min(start + batchSize, roots.count)
        let batch = Array(roots[start..<end])
        let batchResults = await withTaskGroup(of: BranchMergeScanResult?.self) { group in
            for (offset, root) in batch.enumerated() {
                let index = start + offset
                group.addTask {
                    guard !Task.isCancelled else { return nil }
                    return scanBranchMergeRoot(root, index: index, target: target, prefix: prefix)
                }
            }

            var collected: [BranchMergeScanResult] = []
            for await result in group {
                if let result { collected.append(result) }
            }
            return collected
        }
        results.append(contentsOf: batchResults)
    }

    return results.sorted { $0.index < $1.index }
}

func beginBranchCleanup() {
    guard let projectPath else { return }
    let generation = nextBranchCleanupGeneration()
    beginFeedbackOperation("Load branch cleanup")
    let scanRoot = projectPath
    Task.detached(priority: .userInitiated) {
        do {
            let roots = try loadBranchCleanupRoots(scanRoot: scanRoot)
            await MainActor.run {
                guard self.branchCleanupGeneration == generation else { return }
                self.branchCleanupWindow.present(roots: roots)
                self.feedbackCenter.success("Branch cleanup loaded", detail: "\(roots.count) repositories")
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Load branch cleanup failed",
                    detail: errorMessage(error),
                    nextStep: "Check the selected Git roots and retry."
                )
            }
        }
    }
}

func refreshBranchCleanup() {
    guard let projectPath else { return }
    let generation = nextBranchCleanupGeneration()
    beginFeedbackOperation("Refresh branch cleanup")
    let scanRoot = projectPath
    Task.detached(priority: .userInitiated) {
        do {
            let roots = try loadBranchCleanupRoots(scanRoot: scanRoot)
            await MainActor.run {
                guard self.branchCleanupGeneration == generation else { return }
                self.branchCleanupWindow.updateRoots(roots)
                self.feedbackCenter.success("Branch cleanup refreshed", detail: "\(roots.count) repositories")
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Refresh branch cleanup failed", detail: errorMessage(error))
            }
        }
    }
}

private func reloadBranchCleanupContext(for generation: Int) {
    guard let projectPath else { return }
    let scanRoot = projectPath
    Task.detached(priority: .userInitiated) {
        do {
            let roots = try loadBranchCleanupRoots(scanRoot: scanRoot)
            await MainActor.run {
                guard self.branchCleanupGeneration == generation else { return }
                self.branchCleanupWindow.updateRoots(roots)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Refresh branch cleanup failed", detail: errorMessage(error))
            }
        }
    }
}

func calculateBranchCleanup(target: String, prefix: String) {
    let roots = branchCleanupWindow.roots
    let generation = nextBranchCleanupGeneration()
    let target = target.trimmingCharacters(in: .whitespacesAndNewlines)
    let prefix = prefix.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !target.isEmpty else { return }
    beginFeedbackOperation("Calculate branch merge status")
    Task.detached(priority: .userInitiated) {
        let scanResults = await scanBranchMergeRoots(roots, target: target, prefix: prefix)
        let rootsToApply = scanResults.map(\.root)
        let failuresToReport = scanResults.compactMap { result in
            result.error.map { "\(result.root.displayName): \($0)" }
        }
        await MainActor.run {
            guard self.branchCleanupGeneration == generation else { return }
            self.branchCleanupWindow.updateRoots(rootsToApply)
            if failuresToReport.isEmpty {
                self.feedbackCenter.success("Branch merge status calculated", detail: target)
            } else {
                self.feedbackCenter.warning(
                    "Branch merge status incomplete",
                    detail: failuresToReport.joined(separator: "\n"),
                    nextStep: "Choose a target branch that exists in each affected root."
                )
            }
        }
    }
}

func deleteBranchCleanup(_ selections: [BranchCleanupSelection]) {
    guard !selections.isEmpty else { return }
    let generation = nextBranchCleanupGeneration()
    beginFeedbackOperation("Delete selected branches")
    Task.detached(priority: .userInitiated) {
        var deleted: [String] = []
        var failures: [String] = []
        for selection in selections {
            do {
                let rootRepo = try openRepository(path: selection.rootPath)
                try rootRepo.branchDelete(name: selection.branchName, force: false)
                deleted.append("\(selection.branchName) · \(selection.rootPath)")
            } catch {
                failures.append("\(selection.branchName) · \(selection.rootPath): \(errorMessage(error))")
            }
        }
        let deletedToReport = deleted
        let failuresToReport = failures
        await MainActor.run {
            guard self.branchCleanupGeneration == generation else { return }
            self.loadRepoData()
            if failuresToReport.isEmpty {
                self.feedbackCenter.success("Selected branches deleted", detail: deletedToReport.joined(separator: ", "))
            } else {
                self.feedbackCenter.warning(
                    "Some branches could not be deleted",
                    detail: failuresToReport.joined(separator: "\n"),
                    nextStep: "Review the affected roots and delete the remaining branches individually."
                )
            }
            self.reloadBranchCleanupContext(for: generation)
        }
    }
}

/// IntelliJ FindMergedLocalBranchesAction 的项目级入口：只读加载所有 Git
/// root，再由独立 sheet 按目标分支和名称前缀计算结果。
func beginFindMergedBranches() {
    guard let projectPath else { return }
    findMergedTask?.cancel()
    findMergedTask = nil
    let generation = nextFindMergedGeneration()
    let activeBranch = branches.first(where: { $0.isCurrent })?.name ?? ""
    findMergedTargetBranch = activeBranch
    findMergedPrefix = ""
    findMergedBranchesRoots = []
    findMergedHasCalculated = false
    findMergedSummary = nil
    findMergedReportID = nil
    findMergedReportText = ""
    findMergedRunning = true
    showFindMergedBranchesDialog = true
    beginFeedbackOperation("Load merged branch roots")
    let scanRoot = projectPath
    let task = Task.detached(priority: .userInitiated) {
        do {
            let roots = try loadBranchCleanupRoots(scanRoot: scanRoot)
            guard !Task.isCancelled else { return }
            let allBranches = roots.flatMap { $0.branches }
            let fallbackTarget: String
            if !activeBranch.isEmpty {
                fallbackTarget = activeBranch
            } else if let main = allBranches.first(where: { $0.name == "main" })?.name {
                fallbackTarget = main
            } else if let master = allBranches.first(where: { $0.name == "master" })?.name {
                fallbackTarget = master
            } else {
                fallbackTarget = allBranches.first(where: { $0.isCurrent })?.name ?? ""
            }
            await MainActor.run {
                guard self.findMergedGeneration == generation else { return }
                self.findMergedTask = nil
                self.findMergedBranchesRoots = roots
                self.findMergedTargetBranch = fallbackTarget
                self.findMergedRunning = false
                self.feedbackCenter.success("Merged branch roots loaded", detail: "\(roots.count) repositories")
            }
        } catch {
            await MainActor.run {
                guard self.findMergedGeneration == generation else { return }
                self.findMergedTask = nil
                self.findMergedRunning = false
                self.feedbackCenter.error(
                    "Load merged branch roots failed",
                    detail: errorMessage(error),
                    nextStep: "Check the selected Git roots and retry."
                )
            }
        }
    }
    findMergedTask = task
}

private func nextFindMergedGeneration() -> Int {
    findMergedGeneration += 1
    return findMergedGeneration
}

func dismissFindMergedBranches() {
    findMergedTask?.cancel()
    findMergedTask = nil
    _ = nextFindMergedGeneration()
    showFindMergedBranchesDialog = false
    findMergedRunning = false
    findMergedHasCalculated = false
    findMergedSummary = nil
    findMergedBranchesRoots = []
}

func cancelFindMergedBranches() {
    guard findMergedRunning else { return }
    // Root discovery is cancellable and dismisses the sheet; an active scan
    // keeps its partial roots and reports cancellation at the next boundary.
    if findMergedBranchesRoots.isEmpty && findMergedSummary == nil {
        dismissFindMergedBranches()
    } else {
        findMergedTask?.cancel()
    }
}

func calculateFindMergedBranches() {
    let target = findMergedTargetBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    let prefix = findMergedPrefix.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !target.isEmpty else {
        feedbackCenter.warning("Target branch is required")
        return
    }
    let discoveredRoots = findMergedBranchesRoots
    let roots = Self.findMergedRootsContainingTarget(target, in: discoveredRoots)
    let generation = nextFindMergedGeneration()
    let startedAt = DispatchTime.now().uptimeNanoseconds
    findMergedRunning = true
    findMergedHasCalculated = false
    findMergedSummary = nil
    findMergedTask?.cancel()
    beginFeedbackOperation("Find merged branches")
    let task = Task.detached(priority: .userInitiated) {
        let scanResults = await scanBranchMergeRoots(roots, target: target, prefix: prefix)
        let calculatedRoots = scanResults.map(\.root)
        let failures = scanResults.compactMap { result in
            result.error.map { "\(result.root.displayName): \($0)" }
        }
        let repositoriesScanned = scanResults.filter(\.repositoryScanned).count
        let candidateBranchesChecked = scanResults.reduce(0) {
            $0 + $1.candidateBranchesChecked
        }
        let mergedBranchesFound = scanResults.reduce(0) {
            $0 + $1.mergedBranchesFound
        }
        let wasCancelled = Task.isCancelled
        let rootsToApply = calculatedRoots
        let completedRepositoryCount = calculatedRoots.count
        let failuresToReport = failures
        let elapsedMilliseconds = Int64(
            (DispatchTime.now().uptimeNanoseconds - startedAt) / 1_000_000
        )
        let summary = FindMergedScanSummary(
            targetBranch: target,
            prefix: prefix,
            repositoriesDiscovered: discoveredRoots.count,
            repositoriesScanned: repositoriesScanned,
            candidateBranchesChecked: candidateBranchesChecked,
            mergedBranchesFound: mergedBranchesFound,
            errors: failuresToReport,
            elapsedMilliseconds: elapsedMilliseconds,
            isCancelled: wasCancelled
        )
        await MainActor.run {
            guard self.findMergedGeneration == generation else { return }
            self.findMergedTask = nil
            self.findMergedBranchesRoots = rootsToApply
            self.findMergedRunning = false
            self.findMergedHasCalculated = true
            self.findMergedSummary = summary
            let reportID = UUID().uuidString
            let report = findMergedBranchesReportText(
                summary: summary,
                roots: rootsToApply,
                projectName: self.projectPath.map {
                    URL(fileURLWithPath: $0).lastPathComponent
                } ?? ""
            )
            FindMergedReportStore.save(
                PersistedFindMergedReport(
                    id: reportID,
                    projectPath: self.projectPath ?? "",
                    targetBranch: summary.targetBranch,
                    prefix: summary.prefix,
                    report: report,
                    createdAt: Date()
                )
            )
            self.findMergedReportID = reportID
            let reportAction = self.findMergedReportAction(reportID: reportID)
            let notificationID = self.findMergedNotificationID(
                targetBranch: summary.targetBranch,
                prefix: summary.prefix
            )
            if summary.isCancelled {
                self.feedbackCenter.warning(
                    "Find merged branches cancelled",
                    detail: "\(completedRepositoryCount) of \(roots.count) repositories completed",
                    additionalActions: [reportAction],
                    notificationID: notificationID,
                    notificationGroup: .standard
                )
            } else if failuresToReport.isEmpty {
                self.feedbackCenter.success(
                    "Merged branches found",
                    detail: target,
                    additionalActions: [reportAction],
                    notificationID: notificationID,
                    notificationGroup: .standard
                )
            } else {
                self.feedbackCenter.warning(
                    "Find merged branches incomplete",
                    detail: failuresToReport.joined(separator: "\n"),
                    nextStep: "Choose a target branch that exists in the affected roots.",
                    additionalActions: [reportAction],
                    notificationID: notificationID,
                    notificationGroup: .standard
                )
            }
        }
    }
    findMergedTask = task
}

private func findMergedReportAction(reportID: String) -> FeedbackAction {
    let request = ArborVCSActionRequest(
        kind: .showFindMergedReport,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        findMergedReportID: reportID
    )
    return FeedbackAction(
        id: "open-find-merged-report",
        title: "Open Report",
        semanticAction: request
    ) {
        NotificationCenter.default.post(name: .arborVCSAction, object: request)
    }
}

private func findMergedNotificationID(targetBranch: String, prefix: String) -> String {
    let source = [projectPath ?? "", targetBranch, prefix].joined(separator: "\u{1f}")
    let encoded = Data(source.utf8)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
    return "git.find-merged.\(encoded)"
}

private func presentFindMergedReport() {
    if showFindMergedBranchesDialog {
        // The report editor is attached to the project view rather than the
        // scan sheet. Dismiss the scan sheet first so SwiftUI does not reject
        // a second presentation while the first sheet is still mounted.
        showFindMergedBranchesDialog = false
        Task { @MainActor in
            await Task.yield()
            self.showFindMergedReport = true
        }
    } else {
        showFindMergedReport = true
    }
}

func openFindMergedReport() {
    let target = findMergedTargetBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    let prefix = findMergedPrefix.trimmingCharacters(in: .whitespacesAndNewlines)
    guard let summary = findMergedSummary,
          summary.targetBranch == target,
          summary.prefix == prefix else {
        feedbackCenter.warning("Run Find to calculate merged branches")
        return
    }
    let report = findMergedBranchesReportText(
        summary: summary,
        roots: findMergedBranchesRoots,
        projectName: projectPath.map { URL(fileURLWithPath: $0).lastPathComponent } ?? ""
    )
    let reportID = findMergedReportID ?? UUID().uuidString
    if let projectPath {
        FindMergedReportStore.save(
            PersistedFindMergedReport(
                id: reportID,
                projectPath: projectPath,
                targetBranch: summary.targetBranch,
                prefix: summary.prefix,
                report: report,
                createdAt: Date()
            )
        )
    }
    findMergedReportID = reportID
    findMergedReportText = report
    presentFindMergedReport()
}

func openFindMergedReport(reportID: String) {
    guard let saved = FindMergedReportStore.load(id: reportID) else {
        feedbackCenter.warning(
            "Merged branches report unavailable",
            detail: "The saved report is no longer available.",
            nextStep: "Run Find Merged Local Branches again."
        )
        return
    }
    if let projectPath,
       URL(fileURLWithPath: projectPath).standardizedFileURL.path
            != URL(fileURLWithPath: saved.projectPath).standardizedFileURL.path
    {
        return
    }
    findMergedReportID = saved.id
    findMergedTargetBranch = saved.targetBranch
    findMergedPrefix = saved.prefix
    findMergedReportText = saved.report
    presentFindMergedReport()
}

func copyFindMergedBranches() {
    let target = findMergedTargetBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    let prefix = findMergedPrefix.trimmingCharacters(in: .whitespacesAndNewlines)
    guard let summary = findMergedSummary,
          summary.targetBranch == target,
          summary.prefix == prefix else {
        feedbackCenter.warning("Run Find to calculate merged branches")
        return
    }
    let report = findMergedBranchesReportText(
        summary: summary,
        roots: findMergedBranchesRoots,
        projectName: projectPath.map { URL(fileURLWithPath: $0).lastPathComponent } ?? ""
    )
    NSPasteboard.general.clearContents()
    NSPasteboard.general.setString(report, forType: .string)
    feedbackCenter.success("Merged branches copied", detail: "\(summary.mergedBranchesFound) branches")
}

/// 在所选 hosted remote 打开 PR / merge request 创建页。
func openPR(_ branch: String, remote: RemoteInfo) {
    guard let repo else {
        feedbackCenter.error(
            "Open pull request unavailable",
            detail: "The Git root is no longer available.",
            nextStep: "Refresh the project and retry."
        )
        return
    }
    let url = remote.url
    let branchName = branch
    Task.detached(priority: .userInitiated) {
        let link = repo.prUrl(remoteUrl: url, branch: branchName)
        await MainActor.run {
            guard let link else {
                self.feedbackCenter.error(
                    "Open pull request unavailable",
                    detail: "The selected remote does not expose a pull request URL.",
                    nextStep: "Choose another hosted remote or configure a supported remote."
                )
                return
            }
            guard let nsUrl = URL(string: link), NSWorkspace.shared.open(nsUrl) else {
                self.feedbackCenter.error(
                    "Open pull request failed",
                    detail: link,
                    nextStep: "Copy the branch name and open the pull request page manually."
                )
                return
            }
        }
    }
}

func branchRename() {
    guard let repo, !renameOld.isEmpty, !renameNew.isEmpty else { return }
    let old = renameOld, new = renameNew
    beginFeedbackOperation("Rename branch")
    Task.detached(priority: .userInitiated) {
        do {
            let localBranchNames = try repo.branchList().map(\.name)
            let remoteBranchNames = try repo.remoteBranchList().map(\.name)
            if let conflict = branchRenameConflictMessage(
                oldName: old,
                newName: new,
                localBranchNames: localBranchNames,
                remoteBranchNames: remoteBranchNames
            ) {
                throw NSError(
                    domain: "Arbor.BranchRename",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: conflict]
                )
            }
            try repo.validateBranchName(name: new)
            try repo.branchRename(old: old, new: new)
            let bs = try repo.branchList()
            await MainActor.run {
                self.branches = bs; self.renameOld = ""; self.renameNew = ""
                self.feedbackCenter.success("Branch renamed", detail: "\(old) → \(new)")
                self.loadRepoData()
                if self.toolWindowMode == .log { self.loadLog() }
            }
        } catch { await MainActor.run { self.loadError = errorMessage(error) } }
    }
}

/// 建立或修改本地分支的 configured upstream。
func setBranchUpstream(_ branch: String, upstream: String) {
    guard let repo else { return }
    let branch = branch.trimmingCharacters(in: .whitespacesAndNewlines)
    let upstream = upstream.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !branch.isEmpty, !upstream.isEmpty else { return }
    beginFeedbackOperation("Set branch upstream")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.branchSetUpstream(branch: branch, upstream: upstream)
            await MainActor.run {
                self.feedbackCenter.success("Upstream configured", detail: "\(branch) → \(upstream)")
                self.loadRepoData()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Set upstream failed", detail: errorMessage(error), nextStep: "选择一个有效的 remote-tracking branch 后重试。")
            }
        }
    }
}

/// 清除本地分支的 configured upstream，不删除本地或远程分支。
func unsetBranchUpstream(_ branch: String) {
    guard let repo else { return }
    beginFeedbackOperation("Unset branch upstream")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.branchUnsetUpstream(branch: branch)
            await MainActor.run {
                self.feedbackCenter.success("Upstream removed", detail: branch)
                self.loadRepoData()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Unset upstream failed", detail: errorMessage(error))
            }
        }
    }
}

func switchBranch(_ name: String) {
    guard let repo else { return }
    beginFeedbackOperation("Checkout branch")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.switchBranch(name: name)
            await MainActor.run {
                self.loadError = nil
                self.feedbackCenter.success("Branch checked out", detail: name)
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            let detail = errorMessage(error)
            await MainActor.run {
                self.presentCheckoutRecovery(
                    repo: repo,
                    name: name,
                    detail: detail,
                    onSmart: { self.smartCheckoutBranch(repo: repo, name: name) },
                    onForce: { self.forceCheckoutBranch(repo: repo, name: name) }
                )
            }
        }
    }
}

private func promptForCheckoutReference() -> String? {
    let alert = NSAlert()
    alert.messageText = "Checkout Tag or Revision"
    alert.informativeText = "Enter reference (branch, tag) name or commit hash:"
    let field = NSTextField(string: "")
    field.placeholderString = "branch, tag, or commit"
    field.frame = NSRect(x: 0, y: 0, width: 360, height: 24)
    alert.accessoryView = field
    alert.addButton(withTitle: "Checkout")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return nil }
    let reference = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !reference.isEmpty else {
        feedbackCenter.warning(
            "Checkout cancelled",
            detail: "A branch, tag, or revision is required.",
            nextStep: "Run Checkout Tag or Revision again and enter a reference."
        )
        return nil
    }
    return reference
}

func checkoutReferenceFromInput() {
    guard let repo, let reference = promptForCheckoutReference() else { return }
    beginFeedbackOperation("Checkout reference")
    Task.detached(priority: .userInitiated) {
        let target = resolveCheckoutReferenceTarget(repo: repo, reference: reference)
        do {
            try performCheckoutReference(repo: repo, target: target)
            await MainActor.run {
                self.feedbackCenter.success("Reference checked out", detail: reference)
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            let detail = errorMessage(error)
            await MainActor.run {
                self.presentCheckoutRecovery(
                    repo: repo,
                    name: reference,
                    detail: detail,
                    onSmart: {
                        self.smartCheckoutReference(repo: repo, target: target)
                    },
                    onForce: {
                        self.forceCheckoutReference(repo: repo, target: target)
                    }
                )
            }
        }
    }
}

/// Multi-root input checkout follows IntelliJ's repository selection: a
/// selected repository is targeted alone; otherwise the reference is tried in
/// every discovered Git root and each root reports its own recovery state.
func checkoutReferenceFromInput(rootPath: String?) {
    guard let reference = promptForCheckoutReference() else { return }
    if let rootPath {
        checkoutReferenceInRoot(rootPath: rootPath, reference: reference)
    } else {
        // The engine resolves local/remote/detached references independently
        // in every root and provides the aggregate Smart/Force/Cancel flow.
        executeMultiRootCheckout(reference: reference, detach: false)
    }
}

private func smartCheckoutReference(
    repo: Repository,
    target: CheckoutReferenceTarget,
    onSuccess: @escaping () -> Void = {}
) {
    switch target {
    case let .localBranch(name):
        smartCheckoutBranch(repo: repo, name: name, onSuccess: onSuccess)
    case let .remoteBranch(name):
        smartCheckoutRemoteBranch(repo: repo, remoteBranch: name, onSuccess: onSuccess)
    case let .detached(reference):
        smartCheckoutDetached(repo: repo, revision: reference, onSuccess: onSuccess)
    }
}

private func forceCheckoutReference(
    repo: Repository,
    target: CheckoutReferenceTarget,
    onSuccess: @escaping () -> Void = {}
) {
    switch target {
    case let .localBranch(name):
        forceCheckoutBranch(repo: repo, name: name, onSuccess: onSuccess)
    case let .remoteBranch(name):
        forceCheckoutRemoteBranch(repo: repo, remoteBranch: name, onSuccess: onSuccess)
    case let .detached(reference):
        forceCheckoutDetached(repo: repo, revision: reference, onSuccess: onSuccess)
    }
}

func checkoutReferenceInRoot(rootPath: String, reference: String) {
    beginFeedbackOperation("Checkout reference")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let target = resolveCheckoutReferenceTarget(repo: rootRepo, reference: reference)
            do {
                try performCheckoutReference(repo: rootRepo, target: target)
                await MainActor.run {
                    self.feedbackCenter.success(
                        "Reference checked out",
                        detail: "\(reference) · \(rootPath)"
                    )
                    self.loadMultiRoots()
                }
            } catch {
                let detail = errorMessage(error)
                await MainActor.run {
                    self.presentCheckoutRecovery(
                        repo: rootRepo,
                        name: reference,
                        detail: detail,
                        onSmart: {
                            self.smartCheckoutReference(
                                repo: rootRepo,
                                target: target,
                                onSuccess: { self.loadMultiRoots() }
                            )
                        },
                        onForce: {
                            self.forceCheckoutReference(
                                repo: rootRepo,
                                target: target,
                                onSuccess: { self.loadMultiRoots() }
                            )
                        }
                    )
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Checkout reference failed",
                    detail: "\(reference) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Check the repository and reference, then retry."
                )
            }
        }
    }
}

/// Branches Popup 多 root 行为：在选中 root 内检出，不把同名分支误操作到
/// 当前窗口绑定的另一个 repository。
func checkoutBranchInRoot(rootPath: String, reference: String, isRemote: Bool) {
    beginFeedbackOperation(isRemote ? "Checkout remote branch" : "Checkout branch")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            if isRemote {
                try rootRepo.checkoutRemoteBranch(remoteBranch: reference, localName: nil)
            } else {
                try rootRepo.switchBranch(name: reference)
            }
            await MainActor.run {
                self.feedbackCenter.success(
                    isRemote ? "Remote branch checked out" : "Branch checked out",
                    detail: reference
                )
                self.loadMultiRoots()
                self.refreshAll(showFeedback: false)
            }
        } catch {
            let detail = errorMessage(error)
            do {
                let rootRepo = try openRepository(path: rootPath)
                await MainActor.run {
                    self.presentCheckoutRecovery(
                        repo: rootRepo,
                        name: reference,
                        detail: detail,
                        onSmart: {
                            if isRemote {
                                self.smartCheckoutRemoteBranch(repo: rootRepo, remoteBranch: reference) {
                                    self.loadMultiRoots()
                                }
                            } else {
                                self.smartCheckoutBranch(repo: rootRepo, name: reference) {
                                    self.loadMultiRoots()
                                }
                            }
                        },
                        onForce: {
                            if isRemote {
                                self.forceCheckoutRemoteBranch(repo: rootRepo, remoteBranch: reference) {
                                    self.loadMultiRoots()
                                }
                            } else {
                                self.forceCheckoutBranch(repo: rootRepo, name: reference) {
                                    self.loadMultiRoots()
                                }
                            }
                        }
                    )
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error("Root checkout failed", detail: detail)
                }
            }
        }
    }
}

/// Recent branch checkout is the same local-branch operation, but the root is
/// explicit so a matching branch name in another repository cannot win.
func checkoutRecentBranchInRoot(rootPath: String, name: String) {
    checkoutBranchInRoot(rootPath: rootPath, reference: name, isRemote: false)
}

/// Tag checkout is detached and uses the selected root's own Smart/Force
/// recovery path.
func checkoutTagInRoot(rootPath: String, name: String) {
    beginFeedbackOperation("Checkout tag")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            try rootRepo.checkoutDetached(commitId: name)
            await MainActor.run {
                self.feedbackCenter.success("Checked out tag", detail: "\(name) · \(rootPath)")
                self.loadMultiRoots()
            }
        } catch {
            let detail = errorMessage(error)
            do {
                let rootRepo = try openRepository(path: rootPath)
                await MainActor.run {
                    self.presentCheckoutRecovery(
                        repo: rootRepo,
                        name: name,
                        detail: detail,
                        onSmart: { self.smartCheckoutRevisionInRoot(rootPath: rootPath, revision: name) },
                        onForce: { self.forceCheckoutRevisionInRoot(rootPath: rootPath, revision: name) }
                    )
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error("Tag checkout failed", detail: "\(name) · \(rootPath): \(detail)")
                }
            }
        }
    }
}

private func smartCheckoutRevisionInRoot(rootPath: String, revision: String) {
    let cancel = GitCancelHandle()
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Smart Checkout", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            try rootRepo.smartCheckoutDetachedWithPolicyAndCancel(
                commitId: revision,
                savePolicy: projectSavePolicy,
                cancel: cancel
            )
            await MainActor.run {
                self.feedbackCenter.success("Smart Checkout completed", detail: "\(revision) · \(rootPath)")
                self.loadMultiRoots()
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                if case .Cancelled = error as? EngineError {
                    self.feedbackCenter.warning(
                        "Smart Checkout cancelled",
                        detail: "\(revision) · \(rootPath)",
                        nextStep: "The preservation Shelf was kept when restore had started; retry after reviewing the root."
                    )
                } else if case let .StashApplyConflict(paths, stashID) = error as? EngineError {
                    let viewAction = stashID.flatMap {
                        self.savedChangesFeedbackAction(
                            kind: .stash,
                            identifier: $0,
                            rootPath: rootPath
                        )
                    }
                    var stashIndex = 0
                    if let stashID,
                       let rootRepo = try? openRepository(path: rootPath),
                       let index = try? rootRepo.stashList().firstIndex(where: { $0.id == stashID }) {
                        stashIndex = index
                    }
                    self.presentMultiRootStashConflict(
                        rootPath: rootPath,
                        index: stashIndex,
                        stashID: stashID,
                        isPop: true,
                        paths: paths,
                        additionalActions: viewAction.map { [$0] } ?? []
                    )
                } else if case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                    let viewAction = self.savedChangesFeedbackAction(
                        kind: .shelf,
                        identifier: name,
                        rootPath: rootPath
                    )
                    self.presentMultiRootShelveConflict(
                        rootPath: rootPath,
                        name: name,
                        paths: paths,
                        additionalActions: viewAction.map { [$0] } ?? []
                    )
                } else {
                    self.feedbackCenter.error(
                        "Smart Checkout failed",
                        detail: "\(revision) · \(rootPath): \(errorMessage(error))",
                        nextStep: "Resolve the root-specific restore conflict, then retry."
                    )
                }
            }
        }
    }
}

private func forceCheckoutRevisionInRoot(rootPath: String, revision: String) {
    beginFeedbackOperation("Force Checkout")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            try rootRepo.forceCheckoutDetached(commitId: revision)
            await MainActor.run {
                self.feedbackCenter.success("Force Checkout completed", detail: "\(revision) · \(rootPath)")
                self.loadMultiRoots()
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error("Force Checkout failed", detail: "\(revision) · \(rootPath): \(errorMessage(error))")
            }
        }
    }
}

/// IntelliJ GitCheckoutOperation 的单仓库交互：先展示会被覆盖的本地
/// 变更，再让用户选择 Smart Checkout、Force Checkout 或取消。
private func presentCheckoutRecovery(
    repo: Repository,
    name: String,
    detail: String,
    onSmart: @escaping () -> Void,
    onForce: @escaping () -> Void
) {
    if (try? repo.operationState()) != nil {
        loadError = detail
        feedbackCenter.error(
            "Checkout unavailable",
            detail: detail,
            nextStep: "Continue or abort the operation in progress, then retry checkout."
        )
        return
    }
    let paths = (try? repo.status())?.filter {
        $0.staged != .unchanged
            || ($0.unstaged != .unchanged && $0.unstaged != .ignored)
    }.map(\.path) ?? []
    guard !paths.isEmpty else {
        loadError = detail
        feedbackCenter.error("Checkout failed", detail: detail, nextStep: "Check the branch name and repository state.")
        return
    }

    feedbackCenter.warning(
        "Checkout needs a decision",
        detail: paths.joined(separator: ", "),
        nextStep: "Choose Smart Checkout to preserve local changes, or cancel and keep the current worktree."
    )
    presentSmartOperationDecision(
        operationTitle: "Checkout",
        paths: paths,
        detail: detail,
        smartButtonTitle: "Smart Checkout",
        forceButtonTitle: "Force Checkout",
        onSmart: onSmart,
        onForce: onForce
    )
}

private func showStashRestoreConflict(
    _ paths: [String],
    operationName: String = "Smart Checkout",
    additionalActions: [FeedbackAction] = [],
    notificationID: String? = nil,
    stashID: String? = nil
) {
    pendingStashConflictNotificationID = notificationID
    stashPopConflictInProgress = true
    stashApplyConflictInProgress = false
    pendingStashPopIndex = 0
    pendingStashPopID = stashID
    pendingPullStashPop = false
    pendingPullStashID = nil
    pendingPullStashMessage = nil
    mergeInProgress = true
    mergeInitialPath = paths.first
    if toolWindowMode != .log {
        selection = paths.first
    }
    fileSelection = nil
    selectionModePath = nil
    commitPreviewPath = nil
    commitPreviewVisible = false
    showMergeRevisionsDialog = true
    mergeFeedback = "\(operationName) 冲突：\(paths.joined(separator: ", "))"
    feedbackCenter.error(
        "\(operationName) paused",
        detail: paths.joined(separator: ", "),
        nextStep: "Resolve every file, then complete the local-change restore.",
        additionalActions: additionalActions,
        notificationID: notificationID
    )
    refreshAll(showFeedback: false)
}

private func smartCheckoutBranch(
    repo: Repository,
    name: String,
    onSuccess: @escaping () -> Void = {}
) {
    let cancel = GitCancelHandle()
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Smart Checkout", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            try repo.smartSwitchBranchWithPolicyAndCancel(
                name: name,
                savePolicy: projectSavePolicy,
                cancel: cancel
            )
            await MainActor.run {
                self.loadError = nil
                self.feedbackCenter.success("Smart Checkout completed", detail: name)
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
                onSuccess()
            }
        } catch {
            if case .Cancelled = error as? EngineError {
                await MainActor.run {
                    self.feedbackCenter.warning(
                        "Smart Checkout cancelled",
                        detail: name,
                        nextStep: "The preservation Shelf was kept when restore had started; retry after reviewing the root."
                    )
                }
            } else if case let .StashApplyConflict(paths, stashID) = error as? EngineError {
                await MainActor.run {
                    let viewAction = stashID.flatMap {
                        self.savedChangesFeedbackAction(
                            kind: .stash,
                            identifier: $0,
                            rootPath: repo.workdir()
                        )
                    }
                    self.showStashRestoreConflict(
                        paths,
                        additionalActions: viewAction.map { [$0] } ?? [],
                        stashID: stashID
                    )
                }
            } else if case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                await MainActor.run {
                    let viewAction = self.savedChangesFeedbackAction(
                        kind: .shelf,
                        identifier: name,
                        rootPath: repo.workdir()
                    )
                    self.presentShelveConflict(
                        name: name,
                        paths: paths,
                        isPop: true,
                        additionalActions: viewAction.map { [$0] } ?? []
                    )
                }
            } else {
                await MainActor.run {
                    self.loadError = errorMessage(error)
                    self.feedbackCenter.error(
                        "Smart Checkout failed",
                        detail: errorMessage(error),
                        nextStep: "The original local changes were restored when possible."
                    )
                }
            }
        }
    }
}

