func updateSelectedBranch(_ name: String) {
    guard let repo, let rootPath = repo.workdir() else { return }
    let cancel = GitCancelHandle()
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    let rebase = GitUpdateMethodSettings.method(for: projectPath) == .rebase
    let savePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Update branch", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let result = try executeBranchUpdateInRoot(
                repo: repo,
                rootPath: rootPath,
                branch: name,
                displayName: name,
                rebase: rebase,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel,
                savePolicy: savePolicy
            )
            await MainActor.run {
                self.loadError = nil
                if result.success && !result.skipped {
                    self.feedbackCenter.success("Branch updated", detail: name)
                    self.refreshAll(showFeedback: false)
                    self.loadRepoData()
                } else if result.skipped {
                    self.feedbackCenter.warning(
                        "Branch update cancelled",
                        detail: result.message,
                        nextStep: "Retry the branch update when the worktree is ready."
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Branch update paused",
                        detail: result.message,
                        nextStep: "Resolve the update state, then retry the branch."
                    )
                }
            }
        } catch {
            await MainActor.run {
                let detail = friendlyRemoteError(error)
                self.loadError = detail
                if case .Cancelled = error as? EngineError {
                    self.feedbackCenter.warning(
                        "Branch update cancelled",
                        detail: detail,
                        nextStep: "Retry the branch update when the worktree is ready."
                    )
                } else {
                    self.feedbackCenter.error(
                        "Update branch failed",
                        detail: detail,
                        nextStep: "Check the upstream, credentials, and Git operation state, then retry."
                    )
                }
            }
        }
    }
}

nonisolated private func dirtyPathsForSmartDecision(_ repo: Repository) throws -> [String] {
    try repo.status()
        .filter {
            $0.staged != .unchanged
                || ($0.unstaged != .unchanged && $0.unstaged != .ignored)
        }
        .map(\.path)
}

/// Rebuild the current branch when its upstream was force-pushed. IntelliJ
/// first offers the affected local changes, then routes Smart/Force/Cancel
/// through the same preserving decision used by checkout and merge.
func updateForcePushedBranch() {
    guard let repo else { return }
    do {
        let paths = try dirtyPathsForSmartDecision(repo)
        if paths.isEmpty {
            runForcePushedBranchUpdate(repo: repo, rootPath: nil, force: false)
        } else {
            feedbackCenter.warning(
                "Force-pushed branch update needs a decision",
                detail: paths.joined(separator: ", "),
                nextStep: "Choose Smart Update to preserve local changes, Force Update to discard them, or cancel."
            )
            presentSmartOperationDecision(
                operationTitle: "Force-pushed branch update",
                paths: paths,
                smartButtonTitle: "Smart Update",
                forceButtonTitle: "Force Update",
                onSmart: {
                    self.runForcePushedBranchUpdate(repo: repo, rootPath: nil, force: false)
                },
                onForce: {
                    self.runForcePushedBranchUpdate(repo: repo, rootPath: nil, force: true)
                }
            )
        }
    } catch {
        feedbackCenter.error(
            "Force-pushed branch update unavailable",
            detail: errorMessage(error),
            nextStep: "Refresh the repository, then retry the update."
        )
    }
}

/// The multi-root Branches Popup can target a current branch in a root that is
/// not the window's primary Repository. Preflight that root on a worker before
/// presenting the same affected-changes dialog.
func updateForcePushedBranchInRoot(rootPath: String, branch: String) {
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let paths = try dirtyPathsForSmartDecision(rootRepo)
            await MainActor.run {
                if paths.isEmpty {
                    self.runForcePushedBranchUpdate(
                        repo: rootRepo,
                        rootPath: rootPath,
                        force: false
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Force-pushed branch update needs a decision",
                        detail: "\(rootPath): \(paths.joined(separator: ", "))",
                        nextStep: "Choose Smart Update to preserve local changes, Force Update to discard them, or cancel."
                    )
                    self.presentSmartOperationDecision(
                        operationTitle: "Force-pushed branch update",
                        paths: paths.map { "\(rootPath): \($0)" },
                        smartButtonTitle: "Smart Update",
                        forceButtonTitle: "Force Update",
                        onSmart: {
                            self.runForcePushedBranchUpdate(
                                repo: rootRepo,
                                rootPath: rootPath,
                                force: false
                            )
                        },
                        onForce: {
                            self.runForcePushedBranchUpdate(
                                repo: rootRepo,
                                rootPath: rootPath,
                                force: true
                            )
                        }
                    )
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Force-pushed branch update unavailable",
                    detail: "\(rootPath): \(errorMessage(error))",
                    nextStep: "Refresh Git Roots, then retry the update."
                )
            }
        }
    }
}

/// Present one Smart/Force decision for all eligible current roots that share
/// a branch name, then execute the engine's per-root aggregate operation.
func updateForcePushedBranchAcrossRoots(_ branch: String) {
    guard self.projectPath != nil else { return }
    let roots = multiRootBranchSnapshots.filter { snapshot in
        snapshot.branches.contains { $0.name == branch && $0.isCurrent }
            && snapshot.syncStatuses.contains {
                $0.branch == branch
                    && $0.trackingExists
                    && $0.ahead > 0
                    && $0.behind > 0
            }
    }
    guard !roots.isEmpty else {
        feedbackCenter.warning(
            "Force-pushed branch update unavailable",
            detail: branch,
            nextStep: "Refresh Git Roots and retry after the branch shows both local and remote divergence."
        )
        return
    }

    Task.detached(priority: .userInitiated) {
        var dirtyByRoot: [(rootPath: String, displayName: String, paths: [String])] = []
        var preflightErrors: [String] = []
        for root in roots {
            do {
                let rootRepo = try openRepository(path: root.rootPath)
                let paths = try dirtyPathsForSmartDecision(rootRepo)
                if !paths.isEmpty {
                    dirtyByRoot.append((root.rootPath, root.displayName, paths))
                }
            } catch {
                preflightErrors.append("\(root.displayName): \(errorMessage(error))")
            }
        }

        let dirtyRoots = dirtyByRoot
        let errors = preflightErrors
        await MainActor.run {
            if !errors.isEmpty {
                self.feedbackCenter.error(
                    "Multi-root force-pushed update unavailable",
                    detail: errors.joined(separator: "\n"),
                    nextStep: "Refresh Git Roots, then retry the update."
                )
                return
            }
            let selectedRootPaths = roots.map(\.rootPath)
            if dirtyRoots.isEmpty {
                self.runMultiRootForcePushedBranchUpdate(
                    branch: branch,
                    selectedRootPaths: selectedRootPaths,
                    force: false
                )
            } else {
                let detail = dirtyRoots.map {
                    "\($0.displayName): \($0.paths.joined(separator: ", "))"
                }.joined(separator: "\n")
                self.feedbackCenter.warning(
                    "Multi-root force-pushed update needs a decision",
                    detail: detail,
                    nextStep: "Choose Smart Update to preserve local changes in each root, Force Update to discard them, or cancel."
                )
                self.presentSmartOperationDecision(
                    operationTitle: "Multi-root force-pushed branch update",
                    paths: dirtyRoots.flatMap { root in
                        root.paths.map { "\(root.displayName): \($0)" }
                    },
                    smartButtonTitle: "Smart Update",
                    forceButtonTitle: "Force Update",
                    onSmart: {
                        self.runMultiRootForcePushedBranchUpdate(
                            branch: branch,
                            selectedRootPaths: selectedRootPaths,
                            force: false
                        )
                    },
                    onForce: {
                        self.runMultiRootForcePushedBranchUpdate(
                            branch: branch,
                            selectedRootPaths: selectedRootPaths,
                            force: true
                        )
                    }
                )
            }
        }
    }
}

private func runForcePushedBranchUpdate(
    repo: Repository,
    rootPath: String?,
    force: Bool
) {
    let cancel = GitCancelHandle()
    let broker = credentialAuth.broker
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Update force-pushed branch", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let outcome: ForcePushedBranchUpdateOutcome
            if force {
                outcome = try repo.forcePushedBranchUpdateWithAuthAndCancelForce(
                    broker: broker,
                    cancel: cancel
                )
            } else {
                outcome = try repo.forcePushedBranchUpdateWithAuthAndCancel(
                    savePolicy: projectSavePolicy,
                    broker: broker,
                    cancel: cancel
                )
            }
            await MainActor.run {
                self.loadError = nil
                let updateDetail = outcome.usedMergeUpdate
                    ? "\(outcome.branch) ← \(outcome.upstream) · merge update"
                    : "\(outcome.branch) ← \(outcome.upstream) · replayed \(outcome.replayedCommits) local commit(s)"
                let counts = outcome.receivedCommitsCount > 0 || outcome.updatedFilesCount > 0
                    ? " · \(outcome.updatedFilesCount) updated file(s) in \(outcome.receivedCommitsCount) received commit(s)"
                    : ""
                let detail = rootPath.map { "\($0): \(updateDetail)\(counts)" } ?? "\(updateDetail)\(counts)"
                let viewCommitRanges = self.forcePushedRevisionRanges(
                    oldTip: outcome.updateRangeStart,
                    newTip: outcome.newUpstreamTip,
                    rootPath: rootPath
                )
                let viewAction = self.forcePushedViewCommitsAction(
                    ranges: viewCommitRanges,
                    rootPath: rootPath
                )
                self.feedbackCenter.success(
                    "Force-pushed branch updated",
                    detail: detail,
                    additionalActions: viewAction.map { [$0] } ?? [],
                    notificationID: rootPath.map { "git.force-pushed-update.\($0)" }
                        ?? "git.force-pushed-update"
                )
                self.autoOpenUpdateInfoIfEnabled(viewCommitRanges)
                if rootPath == nil {
                    self.refreshAll(showFeedback: false)
                    self.loadRepoData()
                } else {
                    self.loadMultiRoots()
                }
            }
        } catch {
            let operationState = (try? repo.operationState()) ?? nil
            let backupBranchNames = (try? repo.branchList())?
                .filter { isArborForcePushedBackupBranch($0.name) }
                .map(\.name)
                .sorted() ?? []
            await MainActor.run {
                self.loadError = errorMessage(error)
                let isPrimaryRoot = rootPath == nil || rootPath == repo.workdir()
                let backupActions = self.forcePushedBackupActions(
                    rootPath: rootPath,
                    branchNames: backupBranchNames
                )
                if !backupBranchNames.isEmpty {
                    self.feedbackCenter.warning(
                        "Force-pushed backup branch kept",
                        detail: backupBranchNames.joined(separator: ", "),
                        nextStep: "Saved backup branches remain available for inspection or deletion.",
                        additionalActions: backupActions
                    )
                }
                if isPrimaryRoot, case let .StashApplyConflict(paths, stashID) = error as? EngineError {
                    self.showStashRestoreConflict(
                        paths,
                        operationName: "Force-pushed branch update",
                        stashID: stashID
                    )
                } else if isPrimaryRoot,
                          case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                    self.presentShelveConflict(name: name, paths: paths, isPop: true)
                } else if let rootPath {
                    self.feedbackCenter.warning(
                        "Force-pushed branch update paused",
                        detail: "\(rootPath): \(errorMessage(error))",
                        nextStep: "Open the Git Roots conflict workbench to resolve the saved local changes.",
                        actionTitle: "Resolve Conflicts",
                        action: { self.openMultiRootConflictResolver(preferredRootPath: rootPath) },
                        additionalActions: backupActions
                    )
                    self.loadMultiRoots()
                } else if operationState != nil {
                    self.feedbackCenter.warning(
                        "Force-pushed branch update paused",
                        detail: errorMessage(error),
                        nextStep: "Resolve the pending operation, then Continue or Abort.",
                        actionTitle: "Resolve Conflicts",
                        action: self.openActiveOperationConflictResolver,
                        additionalActions: backupActions
                    )
                } else {
                    self.feedbackCenter.error(
                        "Force-pushed branch update failed",
                        detail: errorMessage(error),
                        nextStep: "Inspect the backup branch and current Git state before retrying.",
                        additionalActions: backupActions
                    )
                }
            }
        }
    }
}

private func runMultiRootForcePushedBranchUpdate(
    branch: String,
    selectedRootPaths: [String],
    force: Bool
) {
    guard let projectPath else { return }
    let cancel = GitCancelHandle()
    let broker = credentialAuth.broker
    multiRootRunning = true
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Multi-root force-pushed branch update", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let results = try runMultiRootForcePushedBranchUpdateWithAuthAndCancel(
                scanRoot: projectPath,
                selectedRootPaths: selectedRootPaths,
                broker: broker,
                cancel: cancel,
                savePolicy: projectSavePolicy,
                force: force
            )
            let operationResults = results.map { result in
                RootOperationResult(
                    rootPath: result.rootPath,
                    displayName: result.displayName,
                    success: result.success,
                    skipped: result.skipped,
                    message: result.message
                )
            }
            let failures = results.filter { !$0.success }
            let skippedResults = results.filter { $0.skipped }
            let successCount = results.filter { $0.success && !$0.skipped }.count
            var backupBranchesByRoot: [String: [String]] = [:]
            for result in failures {
                guard let rootRepo = try? openRepository(path: result.rootPath) else { continue }
                let branchNames = (try? rootRepo.branchList())?
                    .filter { isArborForcePushedBackupBranch($0.name) }
                    .map(\.name)
                    .sorted() ?? []
                if !branchNames.isEmpty {
                    backupBranchesByRoot[result.rootPath] = branchNames
                }
            }
            let finalizedBackupBranchesByRoot = backupBranchesByRoot
            await MainActor.run {
                self.multiRootRunning = false
                self.multiRootResults = operationResults
                self.loadMultiRoots()
                let successfulResults = results.filter { $0.success && !$0.skipped }
                let receivedCommits = successfulResults.reduce(0) { $0 + Int($1.receivedCommitsCount) }
                let updatedFiles = successfulResults.reduce(0) { $0 + Int($1.updatedFilesCount) }
                let countDetail = receivedCommits > 0 || updatedFiles > 0
                    ? " · \(updatedFiles) updated file(s) in \(receivedCommits) received commit(s)"
                    : ""
                let skippedDetail = self.forcePushedSkippedDetail(skippedResults)
                let viewCommitRanges = successfulResults.compactMap { result in
                    self.forcePushedRevisionRanges(
                        oldTip: result.updateRangeStart,
                        newTip: result.newUpstreamTip,
                        rootPath: result.rootPath
                    ).first
                }
                let viewAction = self.forcePushedViewCommitsAction(
                    ranges: viewCommitRanges
                )
                if failures.isEmpty {
                    self.feedbackCenter.success(
                        "Multi-root force-pushed branch updated",
                        detail: "\(successCount) repositories · \(branch)\(countDetail)\(skippedDetail)",
                        additionalActions: viewAction.map { [$0] } ?? [],
                        notificationID: "git.force-pushed-update.multi-root"
                    )
                } else {
                    let detail = failures.map {
                        "\($0.displayName): \($0.message.isEmpty ? "failed" : $0.message)"
                    }.joined(separator: "\n")
                    let pendingRoot = failures.first(where: { !$0.localChangesOverwritePaths.isEmpty })?.rootPath
                    let backupActions = self.forcePushedBackupActionsByRoot(finalizedBackupBranchesByRoot)
                    let backupDetail = finalizedBackupBranchesByRoot
                        .sorted { $0.key < $1.key }
                        .flatMap { rootPath, names in
                            names.map { "\(rootPath): \($0)" }
                        }
                        .joined(separator: "\n")
                    let detailWithBackups = backupDetail.isEmpty
                        ? detail
                        : "\(detail)\n\n\(String(localized: "Backup branches kept")):\n\(backupDetail)"
                    var additionalActions = backupActions
                    if let viewAction {
                        additionalActions.insert(viewAction, at: 0)
                    }
                    self.feedbackCenter.warning(
                        "Multi-root force-pushed update partially completed",
                        detail: "\(detailWithBackups)\(countDetail)\(skippedDetail)",
                        nextStep: "Review each Git root; saved local changes remain available for recovery.",
                        actionTitle: "Resolve Conflicts",
                        action: {
                            self.openMultiRootConflictResolver(preferredRootPath: pendingRoot)
                        },
                        additionalActions: additionalActions,
                        notificationID: "git.force-pushed-update.multi-root"
                    )
                }
                self.autoOpenUpdateInfoIfEnabled(viewCommitRanges)
            }
        } catch {
            await MainActor.run {
                self.multiRootRunning = false
                self.feedbackCenter.error(
                    "Multi-root force-pushed update failed",
                    detail: errorMessage(error),
                    nextStep: "Check the selected Git roots and retry the update."
                )
            }
        }
    }
}

private func forcePushedSkippedDetail(
    _ results: [MultiRootForcePushedBranchUpdateResult]
) -> String {
    guard !results.isEmpty else { return "" }
    let grouped = Dictionary(grouping: results, by: \.message)
        .sorted { $0.key < $1.key }
        .map { reason, roots in
            "\(roots.map(\.displayName).sorted().joined(separator: ", ")) (\(reason))"
        }
        .joined(separator: "; ")
    return " · skipped roots: \(grouped)"
}

private func forcePushedRevisionRanges(
    oldTip: String?,
    newTip: String,
    rootPath: String?
) -> [PersistedLogRevisionRange] {
    guard let oldTip,
          !oldTip.isEmpty,
          !newTip.isEmpty,
          oldTip != newTip,
          let resolvedRootPath = rootPath ?? repo?.workdir() else { return [] }
    return [PersistedLogRevisionRange(
        rootPath: resolvedRootPath,
        oldRevision: oldTip,
        newRevision: newTip
    )]
}

private func forcePushedViewCommitsAction(
    oldTip: String?,
    newTip: String,
    rootPath: String?
) -> FeedbackAction? {
    let ranges = forcePushedRevisionRanges(
        oldTip: oldTip,
        newTip: newTip,
        rootPath: rootPath
    )
    return forcePushedViewCommitsAction(ranges: ranges, rootPath: rootPath)
}

private func forcePushedViewCommitsAction(
    ranges: [PersistedLogRevisionRange],
    rootPath: String? = nil
) -> FeedbackAction? {
    guard !ranges.isEmpty else { return nil }
    let request = ArborVCSActionRequest(
        kind: .showLogRanges,
        projectPath: projectPath,
        rootPath: ranges.count == 1 ? rootPath : nil,
        shelfName: "",
        logRevisionRanges: ranges
    )
    return FeedbackAction(title: "View Commits", semanticAction: request) {
        self.showLogRevisionRanges(ranges)
    }
}

private func forcePushedBackupActions(
    rootPath: String?,
    branchNames: [String]
) -> [FeedbackAction] {
    guard !branchNames.isEmpty else { return [] }
    var actions = [
        FeedbackAction(title: "Open Branches") {
            if rootPath == nil {
                self.loadRepoData()
            } else {
                self.loadMultiRoots()
            }
            self.showBranchesPopover = true
        }
    ]
    actions.append(contentsOf: branchNames.map { branchName in
        FeedbackAction(title: "Delete backup branch") {
            self.deleteForcePushedBackupBranch(rootPath: rootPath, name: branchName)
        }
    })
    return actions
}

private func forcePushedBackupActionsByRoot(
    _ branchesByRoot: [String: [String]]
) -> [FeedbackAction] {
    guard !branchesByRoot.isEmpty else { return [] }
    var actions = [
        FeedbackAction(title: "Open Branches") {
            self.loadMultiRoots()
            self.showBranchesPopover = true
        }
    ]
    for (rootPath, branchNames) in branchesByRoot.sorted(by: { $0.key < $1.key }) {
        actions.append(contentsOf: branchNames.map { branchName in
            FeedbackAction(title: "Delete backup branch") {
                self.deleteForcePushedBackupBranch(rootPath: rootPath, name: branchName)
            }
        })
    }
    return actions
}

private func deleteForcePushedBackupBranch(rootPath: String?, name: String) {
    guard isArborForcePushedBackupBranch(name) else { return }
    if let rootPath {
        Task.detached(priority: .userInitiated) {
            do {
                let rootRepo = try openRepository(path: rootPath)
                await MainActor.run {
                    self.prepareForceDeleteBranch(repo: rootRepo, name: name, rootPath: rootPath)
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Delete backup branch failed",
                        detail: "\(rootPath): \(errorMessage(error))"
                    )
                }
            }
        }
    } else if let repo {
        prepareForceDeleteBranch(repo: repo, name: name, rootPath: nil)
    }
}

func pullSelectedBranch(_ name: String, rebase: Bool) {
    guard let repo else { return }
    if branches.first(where: { $0.name == name })?.isCurrent == true {
        doPull(nil, rebase: rebase)
        return
    }
    beginFeedbackOperation(rebase ? "Pull branch with rebase" : "Pull branch")
    Task.detached(priority: .userInitiated) {
        do {
            let outcome = try repo.pullBranch(branch: name, rebase: rebase)
            let detail = outcome.updatedCommits > 0
                ? "\(name) ← \(outcome.upstream) (+\(outcome.updatedCommits) commits)"
                : "\(name) 已是最新"
            await MainActor.run {
                self.loadError = nil
                self.feedbackCenter.success("Branch pull completed", detail: detail)
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            await MainActor.run {
                let detail = errorMessage(error)
                self.loadError = detail
                self.feedbackCenter.error(
                    "Branch pull failed",
                    detail: detail,
                    nextStep: "The current branch was not changed. Checkout the selected branch to resolve conflicts if needed."
                )
            }
        }
    }
}

/// 多 root Branches Popup 的 Update：操作必须固定到行所属的 root。
func updateBranchInRoot(rootPath: String, branch: String) {
    let cancel = GitCancelHandle()
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    let rebase = GitUpdateMethodSettings.method(for: projectPath) == .rebase
    let savePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Update branch", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let result = try executeBranchUpdateInRoot(
                repo: rootRepo,
                rootPath: rootPath,
                branch: branch,
                displayName: rootPath,
                rebase: rebase,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel,
                savePolicy: savePolicy
            )
            await MainActor.run {
                if result.success && !result.skipped {
                    self.feedbackCenter.success("Branch updated", detail: "\(branch) · \(rootPath)")
                } else if result.skipped {
                    self.feedbackCenter.warning(
                        "Branch update cancelled",
                        detail: "\(branch) · \(rootPath): \(result.message)",
                        nextStep: "Retry the branch update when the worktree is ready."
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Branch update paused",
                        detail: "\(branch) · \(rootPath): \(result.message)",
                        nextStep: "Resolve the update state, then retry the branch."
                    )
                }
                self.loadMultiRoots()
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                if case .Cancelled = error as? EngineError {
                    self.feedbackCenter.warning(
                        "Branch update cancelled",
                        detail: "\(branch) · \(rootPath): \(errorMessage(error))",
                        nextStep: "Retry the branch update when the worktree is ready."
                    )
                } else {
                    self.feedbackCenter.error(
                        "Update branch failed",
                        detail: "\(branch) · \(rootPath): \(errorMessage(error))",
                        nextStep: "Check the upstream, credentials, and Git operation state, then retry."
                    )
                }
            }
        }
    }
}

/// IntelliJ's MultipleLocalBranchActions.UpdateSelectedBranchAction for the
/// Log dashboard. Each selected reference keeps its root and branch name; a
/// failure in one target does not silently skip the remaining independent
/// targets, and the aggregated result is exposed in the Operations workbench.
func updateSelectedBranchesInRoots(_ targets: [BranchDashboardReference]) {
    let selected = targets
        .filter { $0.kind == .local && $0.hasTracking }
        .sorted {
            if $0.rootPath == $1.rootPath {
                if $0.isCurrent != $1.isCurrent { return !$0.isCurrent }
                return $0.name < $1.name
            }
            return $0.rootPath < $1.rootPath
        }
    guard !selected.isEmpty, !multiRootRunning else { return }

    let displayNames = Dictionary(
        uniqueKeysWithValues: multiRootBranchSnapshots.map { ($0.rootPath, $0.displayName) }
    )
    multiRootRunning = true
    let cancel = GitCancelHandle()
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    let rebase = GitUpdateMethodSettings.method(for: projectPath) == .rebase
    let savePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Update selected branches", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        var results: [RootOperationResult] = []
        for target in selected {
            if cancel.isCancelled() {
                results.append(
                    RootOperationResult(
                        rootPath: target.rootPath,
                        displayName: displayNames[target.rootPath] ?? target.rootPath,
                        success: false,
                        skipped: true,
                        message: "Cancelled before updating \(target.name)"
                    )
                )
                continue
            }
            do {
                let rootRepo = try openRepository(path: target.rootPath)
                results.append(
                    try executeBranchUpdateInRoot(
                        repo: rootRepo,
                        rootPath: target.rootPath,
                        branch: target.name,
                        displayName: displayNames[target.rootPath] ?? target.rootPath,
                        rebase: rebase,
                        tagMode: tagMode,
                        broker: broker,
                        cancel: cancel,
                        savePolicy: savePolicy
                    )
                )
            } catch {
                let wasCancelled: Bool
                if case .Cancelled = error as? EngineError {
                    wasCancelled = true
                } else {
                    wasCancelled = false
                }
                results.append(
                    RootOperationResult(
                        rootPath: target.rootPath,
                        displayName: displayNames[target.rootPath] ?? target.rootPath,
                        success: false,
                        skipped: wasCancelled,
                        message: wasCancelled
                            ? "Cancelled while updating \(target.name)"
                            : "\(target.name): \(errorMessage(error))"
                    )
                )
            }
        }
        let completedResults = results
        let completedFailures = completedResults.filter { !$0.success && !$0.skipped }
        let completedSkipped = completedResults.filter(\.skipped)
        await MainActor.run {
            self.multiRootRunning = false
            self.multiRootResults = completedResults
            self.loadMultiRoots()
            if completedFailures.isEmpty && completedSkipped.isEmpty {
                self.feedbackCenter.success(
                    "Selected branches updated",
                    detail: "\(selected.count) branches"
                )
            } else {
                let failureDetail = completedFailures.map {
                    "\($0.displayName): \($0.message)"
                }
                let skippedDetail = completedSkipped.map {
                    "\($0.displayName): \($0.message)"
                }
                self.feedbackCenter.warning(
                    "Selected branch update partially completed",
                    detail: (failureDetail + skippedDetail).joined(separator: "\n"),
                    nextStep: completedFailures.isEmpty
                        ? "Retry the skipped branch updates when ready."
                        : "Resolve the failed branch upstreams, then retry those branches."
                )
            }
        }
    }
}

/// 多 root Branches Popup 的非当前分支 Pull：只在目标 root 的临时 worktree
/// 更新该分支，不改变当前窗口绑定的另一个 root。
func pullBranchInRoot(rootPath: String, branch: String, rebase: Bool) {
    beginFeedbackOperation(rebase ? "Pull branch with rebase" : "Pull branch")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let outcome = try rootRepo.pullBranch(branch: branch, rebase: rebase)
            let detail = outcome.updatedCommits > 0
                ? "\(branch) (+\(outcome.updatedCommits) commits) · \(rootPath)"
                : "\(branch) already up to date · \(rootPath)"
            await MainActor.run {
                self.feedbackCenter.success("Branch pull completed", detail: detail)
                self.loadMultiRoots()
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error(
                    "Branch pull failed",
                    detail: "\(branch) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Checkout the selected branch in that root to resolve conflicts if needed."
                )
            }
        }
    }
}

/// Multi-root Branches Popup 的 remote ref Pull：严格把 remote-tracking
/// branch 作为 merge/rebase 来源，目标固定为该 root 的当前分支；不能退化为
/// 按本地 branch 名称读取 configured upstream。
func pullRemoteBranchInRoot(rootPath: String, remoteBranch: String, rebase: Bool) {
    pullRemoteBranchInRoot(
        rootPath: rootPath,
        remoteBranch: remoteBranch,
        rebase: rebase,
        options: nil
    )
}

func pullRemoteBranchInRoot(
    rootPath: String,
    remoteBranch: String,
    rebase: Bool,
    options: PullOptions?
) {
    let normalizedRemoteBranch = remoteBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedRemoteBranch.isEmpty else { return }
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    let tagMode = fetchTagsMode
    let savePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation(
        rebase ? "Pull remote branch with rebase" : "Pull remote branch",
        cancelHandle: cancel
    )
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let effectiveOptions = options ?? PullOptions(
                rebase: rebase,
                mode: .fastForward,
                noCommit: false,
                noVerify: false
            )
            let outcome = try rootRepo.pullRemoteBranchWithSettingsAndPolicy(
                remoteBranch: normalizedRemoteBranch,
                options: effectiveOptions,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel,
                savePolicy: savePolicy
            )
            let detail = outcome.updatedCommits > 0
                ? "\(normalizedRemoteBranch) (+\(outcome.updatedCommits) commits) · \(rootPath)"
                : "\(normalizedRemoteBranch) already up to date · \(rootPath)"
            await MainActor.run {
                if outcome.requiresFinish || !outcome.conflicts.isEmpty {
                    self.feedbackCenter.warning(
                        "Remote branch pull paused",
                        detail: "\(detail) · \(outcome.conflicts.joined(separator: ", "))",
                        nextStep: "Resolve the conflicts in the selected Git root, then Continue or Abort.",
                        additionalActions: [
                            FeedbackAction(title: "Open conflict workbench") {
                                self.openMultiRootConflictResolver(
                                    preferredRootPath: rootPath,
                                    preferredPath: outcome.conflicts.first
                                )
                            }
                        ]
                    )
                } else {
                    self.feedbackCenter.success("Remote branch pull completed", detail: detail)
                }
                self.loadMultiRoots()
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                if case let .StashApplyConflict(paths, stashID) = error as? EngineError {
                    self.presentMultiRootMergeRestoreConflict(
                        rootPath: rootPath,
                        paths: paths,
                        stashID: stashID
                    )
                    return
                }
                if case let .ShelveApplyConflict(_, paths) = error as? EngineError {
                    self.presentMultiRootMergeRestoreConflict(rootPath: rootPath, paths: paths)
                    return
                }
                self.feedbackCenter.error(
                    "Remote branch pull failed",
                    detail: "\(normalizedRemoteBranch) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Check the current branch, remote branch, and working tree, then retry."
                )
            }
        }
    }
}

/// 多 root Branches Popup 的远程分支 Fetch：只更新该 root 对应 remote 的
/// remote-tracking refs，不把当前窗口绑定的 repository 当成目标。
func fetchRemoteBranchInRoot(rootPath: String, branch: String) {
    guard let remote = branch.split(separator: "/", maxSplits: 1).first,
          !remote.isEmpty else {
        feedbackCenter.error("Fetch remote branch failed", detail: "Invalid remote branch: \(branch)")
        return
    }
    let cancel = GitCancelHandle()
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    beginFeedbackOperation("Fetch remote branch", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let outcome = try rootRepo.fetchRemoteBranchWithOptionsAndAuthAndCancel(
                remote: String(remote),
                branch: branch,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel
            )
            let detail = outcome.updated.isEmpty ? "No updates" : outcome.updated.joined(separator: ", ")
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.success(
                    "Remote branch fetched",
                    detail: "\(branch) · \(detail) · \(rootPath)"
                )
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error(
                    "Fetch remote branch failed",
                    detail: "\(branch) · \(rootPath): \(friendlyRemoteError(error))",
                    nextStep: "Check the remote and credentials, then retry."
                )
                if self.isAuthenticationFailure(error) {
                    self.showHostingAuthPrompt = true
                }
            }
        }
    }
}

/// 多 root Branches Popup 的远程分支删除；保留二次确认，避免把远程
/// tracking ref 的删除误认为仅本地清理。
func deleteRemoteBranchInRoot(rootPath: String, branch: String) {
    let branchName = branch.split(separator: "/", maxSplits: 1)
        .dropFirst()
        .joined(separator: "/")
    let protectedName = branchName.isEmpty ? branch : branchName
    guard !GitProtectedBranchRules.matches(
        protectedName,
        patterns: effectiveProtectedBranchPatterns
    ) else {
        feedbackCenter.warning(
            "Delete remote branch unavailable",
            detail: "Protected branch: \(branch)",
            nextStep: "Remove the protection rule only if deleting this remote branch is intentional."
        )
        return
    }
    let alert = NSAlert()
    alert.messageText = "Delete remote branch?"
    alert.informativeText = "This will delete \(branch) from its remote repository."
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Delete remote branch", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            try rootRepo.deleteRemoteBranchWithAuthAndCancel(
                remoteBranch: branch,
                broker: broker,
                cancel: cancel
            )
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.success("Remote branch deleted", detail: "\(branch) · \(rootPath)")
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                if cancel.isCancelled() {
                    self.feedbackCenter.warning(
                        "Remote branch deletion cancelled",
                        detail: "\(branch) · \(rootPath)",
                        nextStep: "The remote branch was not confirmed as deleted; refresh before retrying."
                    )
                } else {
                    self.feedbackCenter.error(
                        "Delete remote branch failed",
                        detail: "\(branch) · \(rootPath): \(friendlyRemoteError(error))",
                        nextStep: "Check permissions and the remote name, then retry."
                    )
                }
            }
        }
    }
}

private func multiRootCommonTrackingBranches(
    remoteBranch: String,
    snapshots: [GitRootBranchSnapshot],
    selectedRootPaths: Set<String>
) -> [String] {
    let selected = snapshots.filter { snapshot in
        selectedRootPaths.contains(snapshot.rootPath)
            && snapshot.remoteBranches.contains { $0.name == remoteBranch }
    }
    guard let first = selected.first else { return [] }
    let initial = Set(
        first.syncStatuses
            .filter { $0.upstream == remoteBranch && $0.trackingExists }
            .map(\.branch)
    )
    let common = selected.dropFirst().reduce(initial) { current, snapshot in
        current.intersection(
            snapshot.syncStatuses
                .filter { $0.upstream == remoteBranch && $0.trackingExists }
                .map(\.branch)
        )
    }
    let currentBranches = Set(selected.compactMap(\.headBranch))
    return common.subtracting(currentBranches).sorted()
}

func presentMultiRootRemoteDeleteDialog(branch: String) {
    let eligible = multiRootBranchSnapshots.filter { snapshot in
        snapshot.remoteBranches.contains { $0.name == branch }
    }
    guard !eligible.isEmpty else {
        feedbackCenter.warning(
            "Delete remote branch unavailable",
            detail: "No Git root contains " + branch + "."
        )
        return
    }
    multiRootRemoteDeleteBranchName = branch
    multiRootRemoteDeleteSelectedRootPaths = Set(eligible.map(\.rootPath))
    multiRootRemoteDeleteTracking = false
    showMultiRootRemoteDeleteDialog = true
}

func dismissMultiRootRemoteDeleteDialog() {
    showMultiRootRemoteDeleteDialog = false
    multiRootRemoteDeleteBranchName = ""
    multiRootRemoteDeleteSelectedRootPaths = []
    multiRootRemoteDeleteTracking = false
}

/// Delete one remote branch across selected roots. IntelliJ first asks once
/// for the remote deletion and whether common local tracking branches should
/// follow; remote failures are reported per root, but tracking cleanup starts
/// only after every selected remote deletion succeeds. Local force deletions
/// retain exact previews for Restore All.
func deleteMultiRootRemoteBranch(
    remoteBranch: String,
    deleteTracking: Bool,
    selectedRootPaths: Set<String>
) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    let branchName = remoteBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !branchName.isEmpty else { return }
    let roots = multiRootBranchSnapshots.filter { snapshot in
        selectedRootPaths.contains(snapshot.rootPath)
            && snapshot.remoteBranches.contains { $0.name == branchName }
    }
    guard !roots.isEmpty else { return }
    let commonTrackingBranches = multiRootCommonTrackingBranches(
        remoteBranch: branchName,
        snapshots: multiRootBranchSnapshots,
        selectedRootPaths: selectedRootPaths
    )
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    multiRootRunning = true
    beginFeedbackOperation("Multi-root remote branch deletion", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        var results: [RootOperationResult] = []
        var recoveryContexts: [BranchDeleteRecoveryContext] = []
        var remoteFailures: [String] = []
        var trackingWarnings: [String] = []
        var cancelled = false
        var repositoriesByRoot: [String: Repository] = [:]
        for snapshot in roots {
            guard !cancel.isCancelled() else {
                cancelled = true
                results.append(
                    RootOperationResult(
                        rootPath: snapshot.rootPath,
                        displayName: snapshot.displayName,
                        success: false,
                        skipped: true,
                        message: "Cancelled"
                    )
                )
                continue
            }
            do {
                let rootRepo = try openRepository(path: snapshot.rootPath)
                try rootRepo.deleteRemoteBranchWithAuthAndCancel(
                    remoteBranch: branchName,
                    broker: broker,
                    cancel: cancel
                )
                repositoriesByRoot[snapshot.rootPath] = rootRepo
                results.append(
                    RootOperationResult(
                        rootPath: snapshot.rootPath,
                        displayName: snapshot.displayName,
                        success: true,
                        skipped: false,
                        message: "Deleted \(branchName)"
                    )
                )
            } catch {
                if cancel.isCancelled() {
                    cancelled = true
                    results.append(
                        RootOperationResult(
                            rootPath: snapshot.rootPath,
                            displayName: snapshot.displayName,
                            success: false,
                            skipped: true,
                            message: "Cancelled"
                        )
                    )
                    continue
                }
                let detail = "\(snapshot.displayName): \(errorMessage(error))"
                remoteFailures.append(detail)
                results.append(
                    RootOperationResult(
                        rootPath: snapshot.rootPath,
                        displayName: snapshot.displayName,
                        success: false,
                        skipped: false,
                        message: errorMessage(error)
                    )
                )
            }
        }

        // IntelliJ only removes the common local tracking branches after the
        // remote deletion succeeds for every selected repository. A failed
        // remote operation therefore never causes an extra local deletion.
        var trackingDeletedByRoot: [String: Int] = [:]
        if remoteFailures.isEmpty && !cancelled && deleteTracking {
            for localBranch in commonTrackingBranches {
                for snapshot in roots {
                    guard snapshot.branches.contains(where: { $0.name == localBranch && !$0.isCurrent }),
                          let rootRepo = repositoriesByRoot[snapshot.rootPath] else {
                        continue
                    }
                    do {
                        let preview = try rootRepo.branchDeletePreview(name: localBranch)
                        do {
                            try rootRepo.branchDelete(name: localBranch, force: false)
                        } catch {
                            guard isUnmergedBranchDeletionError(error) else { throw error }
                            try rootRepo.branchDelete(name: localBranch, force: true)
                        }
                        recoveryContexts.append(
                            BranchDeleteRecoveryContext(
                                repo: rootRepo,
                                preview: preview,
                                rootPath: snapshot.rootPath
                            )
                        )
                        trackingDeletedByRoot[snapshot.rootPath, default: 0] += 1
                    } catch {
                        let warning = "\(snapshot.displayName): \(localBranch): \(errorMessage(error))"
                        trackingWarnings.append(warning)
                    }
                }
            }
        }
        if remoteFailures.isEmpty, !cancelled, deleteTracking, !commonTrackingBranches.isEmpty {
            for index in results.indices where results[index].success {
                let deletedCount = trackingDeletedByRoot[results[index].rootPath, default: 0]
                results[index].message = deletedCount == commonTrackingBranches.count
                    ? "Deleted \(branchName) and common local tracking branches"
                    : "Deleted \(branchName); local branches kept"
            }
        }
        let resultsToApply = results
        let recoveryContextsToOffer = recoveryContexts
        let remoteFailuresToReport = remoteFailures
        let trackingWarningsToReport = trackingWarnings
        let cancelledToReport = cancelled
        let restoredBranchNames = Array(
            Set(recoveryContextsToOffer.map(\.preview.branchName))
        ).sorted()
        await MainActor.run {
            self.multiRootRunning = false
            self.showMultiRootRemoteDeleteDialog = false
            self.multiRootResults = resultsToApply
            self.loadMultiRoots()
            if !recoveryContextsToOffer.isEmpty {
                self.multiRootBranchDeleteRecovery = MultiRootBranchDeleteRecoveryContext(
                    branchName: restoredBranchNames.joined(separator: ", "),
                    contexts: recoveryContextsToOffer
                )
            }
            var details = remoteFailuresToReport + trackingWarningsToReport
            if cancelledToReport {
                details.insert("Operation cancelled.", at: 0)
            }
            if details.isEmpty {
                self.feedbackCenter.success(
                    "Multi-root remote branch deletion completed",
                    detail: "\(resultsToApply.filter(\.success).count) repositories · \(branchName)",
                    additionalActions: self.branchDeleteRecoveryActions(
                        contexts: recoveryContextsToOffer
                    ),
                    notificationID: recoveryContextsToOffer.isEmpty
                        ? nil
                        : self.branchDeleteNotificationID(),
                    notificationGroup: recoveryContextsToOffer.isEmpty ? .toolWindow : .standard
                )
            } else {
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                self.feedbackCenter.warning(
                    cancelledToReport
                        ? "Multi-root remote branch deletion cancelled"
                        : remoteFailuresToReport.isEmpty
                        ? "Remote branch deleted; some local branches kept"
                        : "Multi-root remote branch deletion partially completed",
                    detail: details.joined(separator: "\n"),
                    nextStep: recoveryContextsToOffer.isEmpty
                        ? "Review the affected roots and retry the failed operation."
                        : "Use Restore All if you need to recover the deleted local tracking branches.",
                    additionalActions: self.branchDeleteRecoveryActions(
                        contexts: recoveryContextsToOffer
                    ),
                    notificationID: recoveryContextsToOffer.isEmpty
                        ? nil
                        : self.branchDeleteNotificationID(),
                    notificationGroup: recoveryContextsToOffer.isEmpty ? .toolWindow : .standard
                )
            }
        }
    }
}

func loadMoreBranchComparison(_ side: BranchComparisonSide) {
    guard logViewMode == .compareBranches,
          !branchComparisonIsLoading(side),
          branchComparisonSideHasMore(side) else { return }
    startBranchComparisonLoad(side, reset: false)
}

func refreshBranchComparison(_ side: BranchComparisonSide) {
    guard logViewMode == .compareBranches else { return }
    let selectedWasInSide = branchComparisonEntries(side).contains {
        $0.id == branchCompareSelectionID
    }
    cancelBranchComparisonTask(side)
    setBranchComparisonEntries([], side: side)
    setBranchComparisonHasMore(false, side: side)
    setBranchComparisonError(nil, side: side)
    if selectedWasInSide {
        branchCompareSelectionID = nil
    }
    repairBranchComparisonSelection()
    startBranchComparisonLoad(side, reset: true)
}

func loadBranchComparison(reset: Bool = true) {
    guard reset, logViewMode == .compareBranches else { return }
    branchCompareError = nil
    refreshBranchComparison(.first)
    refreshBranchComparison(.second)
}

func cancelBranchComparisonTasks() {
    cancelBranchComparisonTask(.first)
    cancelBranchComparisonTask(.second)
    branchCompareError = nil
}

private func cancelBranchComparisonTask(_ side: BranchComparisonSide) {
    switch side {
    case .first:
        branchCompareFirstLoadTask?.cancel()
        branchCompareFirstLoadTask = nil
        branchCompareFirstRequestGeneration += 1
        branchCompareFirstLoading = false
    case .second:
        branchCompareSecondLoadTask?.cancel()
        branchCompareSecondLoadTask = nil
        branchCompareSecondRequestGeneration += 1
        branchCompareSecondLoading = false
    }
    updateBranchComparisonLoadingState()
}

private func startBranchComparisonLoad(_ side: BranchComparisonSide, reset: Bool) {
    guard logViewMode == .compareBranches else { return }
    let first = compareRev1.trimmingCharacters(in: .whitespacesAndNewlines)
    let second = compareRev2.trimmingCharacters(in: .whitespacesAndNewlines)
    let filter = branchComparisonFilter(side)
    let requestGeneration: Int
    switch side {
    case .first:
        branchCompareFirstRequestGeneration += 1
        requestGeneration = branchCompareFirstRequestGeneration
        branchCompareFirstLoading = true
    case .second:
        branchCompareSecondRequestGeneration += 1
        requestGeneration = branchCompareSecondRequestGeneration
        branchCompareSecondLoading = true
    }
    updateBranchComparisonLoadingState()

    guard !first.isEmpty, !second.isEmpty else {
        finishBranchComparisonLoad(
            side,
            requestGeneration: requestGeneration,
            error: "请输入两个 branch",
            reset: reset
        )
        return
    }
    let comparisonRepo = activeCompareRepo
        ?? compareRepositoryPath.flatMap { path in
            repo?.workdir() == path ? repo : nil
        }
        ?? compareRepositoryPath.flatMap({ try? openRepository(path: $0) })
        ?? repo
    guard let comparisonRepo else {
        finishBranchComparisonLoad(
            side,
            requestGeneration: requestGeneration,
            error: "无法打开比较所需的 Git root",
            reset: reset
        )
        return
    }
    if let filterError = branchComparisonFilterDateError(filter, side: side) {
        finishBranchComparisonLoad(
            side,
            requestGeneration: requestGeneration,
            error: filterError,
            reset: reset
        )
        return
    }

    let sinceText = filter.since.trimmingCharacters(in: .whitespacesAndNewlines)
    let untilText = filter.until.trimmingCharacters(in: .whitespacesAndNewlines)
    let author = filter.author.trimmingCharacters(in: .whitespacesAndNewlines)
    let message = filter.message.trimmingCharacters(in: .whitespacesAndNewlines)
    let hashQuery = isCommitHashQuery(message) ? message.lowercased() : nil
    let since = parseLogSince(sinceText)
    let until = parseLogUntil(untilText)
    let limit = reset
        ? Int(initialLogPageLimit)
        : Int(continuationLogPageLimit)
    let range = side == .first ? "\(second)..\(first)" : "\(first)..\(second)"
    let afterID = reset ? nil : branchComparisonEntries(side).last?.id
    let contextGeneration = branchCompareGeneration
    let filterSnapshot = filter

    let task = Task.detached(priority: .userInitiated) {
        do {
            let loaded = try comparisonRepo.logFilteredWithMessageAndDateOptionsForRevisionsWithAfterId(
                path: nil,
                limit: UInt32(limit),
                follow: false,
                startRevs: [range],
                author: author.isEmpty ? nil : author,
                since: since,
                until: until,
                message: hashQuery == nil && !message.isEmpty ? message : nil,
                messageRegex: filter.messageRegex,
                messageMatchCase: filter.messageMatchCase,
                noMerges: filter.noMerges,
                sortMode: LogGraphSortChoice.byCommitDate.engineValue,
                afterId: afterID
            )
            guard !Task.isCancelled else { return }
            let filtered = hashQuery.map { query in
                loaded.filter { $0.id.lowercased().hasPrefix(query) }
            } ?? loaded
            let hasMore = branchComparisonHasMore(
                returnedCount: loaded.count,
                requestedLimit: limit,
                isHashQuery: hashQuery != nil
            )
            await MainActor.run {
                guard !Task.isCancelled,
                      self.branchCompareGeneration == contextGeneration,
                      self.branchComparisonRequestGeneration(side) == requestGeneration,
                      self.logViewMode == .compareBranches,
                      self.compareRev1.trimmingCharacters(in: .whitespacesAndNewlines) == first,
                      self.compareRev2.trimmingCharacters(in: .whitespacesAndNewlines) == second,
                      self.branchComparisonFilter(side) == filterSnapshot,
                      self.activeCompareRepo === comparisonRepo
                        || (self.activeCompareRepo == nil && self.projectRepo === comparisonRepo) else { return }
                if reset {
                    self.setBranchComparisonEntries(filtered, side: side)
                } else {
                    let newEntries = branchComparisonNewEntries(
                        returned: filtered,
                        existingIDs: Set(self.branchComparisonEntries(side).map(\.id))
                    )
                    self.setBranchComparisonEntries(
                        self.branchComparisonEntries(side) + newEntries,
                        side: side
                    )
                }
                self.setBranchComparisonHasMore(hasMore, side: side)
                self.setBranchComparisonError(nil, side: side)
                self.finishBranchComparisonLoad(side, requestGeneration: requestGeneration)
                self.repairBranchComparisonSelection()
            }
        } catch {
            await MainActor.run {
                guard !Task.isCancelled,
                      self.branchCompareGeneration == contextGeneration,
                      self.branchComparisonRequestGeneration(side) == requestGeneration,
                      self.logViewMode == .compareBranches,
                      self.compareRev1.trimmingCharacters(in: .whitespacesAndNewlines) == first,
                      self.compareRev2.trimmingCharacters(in: .whitespacesAndNewlines) == second,
                      self.branchComparisonFilter(side) == filterSnapshot,
                      self.activeCompareRepo === comparisonRepo
                        || (self.activeCompareRepo == nil && self.projectRepo === comparisonRepo) else { return }
                self.finishBranchComparisonLoad(
                    side,
                    requestGeneration: requestGeneration,
                    error: errorMessage(error),
                    reset: reset
                )
            }
        }
    }
    switch side {
    case .first:
        branchCompareFirstLoadTask = task
    case .second:
        branchCompareSecondLoadTask = task
    }
}

private func finishBranchComparisonLoad(
    _ side: BranchComparisonSide,
    requestGeneration: Int,
    error: String? = nil,
    reset: Bool = false
) {
    guard branchComparisonRequestGeneration(side) == requestGeneration else { return }
    if let error {
        setBranchComparisonError(error, side: side)
        if reset {
            setBranchComparisonEntries([], side: side)
            setBranchComparisonHasMore(false, side: side)
        }
    }
    switch side {
    case .first:
        branchCompareFirstLoading = false
        branchCompareFirstLoadTask = nil
    case .second:
        branchCompareSecondLoading = false
        branchCompareSecondLoadTask = nil
    }
    branchCompareError = branchCompareFirstError ?? branchCompareSecondError
    updateBranchComparisonLoadingState()
}

private func updateBranchComparisonLoadingState() {
    isLoadingBranchComparison = branchCompareFirstLoading || branchCompareSecondLoading
}

private func branchComparisonIsLoading(_ side: BranchComparisonSide) -> Bool {
    side == .first ? branchCompareFirstLoading : branchCompareSecondLoading
}

private func branchComparisonSideHasMore(_ side: BranchComparisonSide) -> Bool {
    side == .first ? branchCompareFirstHasMore : branchCompareSecondHasMore
}

private func branchComparisonFilter(_ side: BranchComparisonSide) -> BranchComparisonFilter {
    side == .first ? branchCompareFirstFilter : branchCompareSecondFilter
}

private func branchComparisonEntries(_ side: BranchComparisonSide) -> [CommitInfo] {
    side == .first ? branchCompareFirstEntries : branchCompareSecondEntries
}

private func branchComparisonRequestGeneration(_ side: BranchComparisonSide) -> Int {
    side == .first ? branchCompareFirstRequestGeneration : branchCompareSecondRequestGeneration
}

private func setBranchComparisonEntries(_ entries: [CommitInfo], side: BranchComparisonSide) {
    switch side {
    case .first:
        branchCompareFirstEntries = entries
    case .second:
        branchCompareSecondEntries = entries
    }
}

private func setBranchComparisonHasMore(_ hasMore: Bool, side: BranchComparisonSide) {
    switch side {
    case .first:
        branchCompareFirstHasMore = hasMore
    case .second:
        branchCompareSecondHasMore = hasMore
    }
}

private func setBranchComparisonError(_ error: String?, side: BranchComparisonSide) {
    switch side {
    case .first:
        branchCompareFirstError = error
    case .second:
        branchCompareSecondError = error
    }
    branchCompareError = branchCompareFirstError ?? branchCompareSecondError
}

private func repairBranchComparisonSelection() {
    let selection = branchComparisonSelectionAfterRefresh(
        selectedID: branchCompareSelectionID,
        firstIDs: branchCompareFirstEntries.map(\.id),
        secondIDs: branchCompareSecondEntries.map(\.id)
    )
    branchCompareSelectionSide = selection.side
    branchCompareSelectionID = selection.id
}

private func activateComparisonRepository(_ rootRepo: Repository, rootPath: String) {
    activeCompareRepo = rootRepo
    compareRepositoryPath = rootPath
    logActiveRootPath = rootPath
    logActiveRepo = rootRepo
    logActiveBranches = (try? rootRepo.branchList()) ?? []
    logActiveRemoteBranches = (try? rootRepo.remoteBranchList()) ?? []
    logActiveRemotes = (try? rootRepo.remoteList()) ?? []
}

/// 多 root Branches Popup 的 Show Files Diff：打开正确 Git root 的
/// 独立 Changes Browser tab，而不是把 revision 交给当前窗口的 repository。
func compareBranchesInRoot(rootPath: String, first: String, second: String) {
    beginFeedbackOperation("Compare selected branches")
    Task.detached(priority: .userInitiated) {
        do {
            _ = try openRepository(path: rootPath)
            await MainActor.run {
                self.openTreeComparisonTab(
                    rootPath: rootPath,
                    first: first,
                    second: second,
                    comparesWithWorkingTree: false
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Compare unavailable",
                    detail: "\(first) ↔ \(second) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Check the selected branches and retry the comparison."
                )
            }
        }
    }
}

/// IntelliJ's Compare Branches action shows the commits unique to each branch
/// in two log panes. It must not silently degrade to the file-level diff used
/// by Show Files Diff.
func compareBranchesCommitWiseInRoot(rootPath: String, first: String, second: String) {
    beginFeedbackOperation("Compare branches")
    Task.detached(priority: .userInitiated) {
        do {
            _ = try openRepository(path: rootPath)
            await MainActor.run {
                self.openBranchComparisonTab(
                    rootPath: rootPath,
                    first: first,
                    second: second
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Compare unavailable",
                    detail: "\(first) ↔ \(second) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Check the selected branches and retry the comparison."
                )
            }
        }
    }
}

func compareBranchInRoot(rootPath: String, branch: String) {
    beginFeedbackOperation("Compare branch")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let current = try rootRepo.branchList().first(where: { $0.isCurrent })?.name ?? "HEAD"
            await MainActor.run {
                self.openBranchComparisonTab(
                    rootPath: rootPath,
                    first: current,
                    second: branch
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Compare unavailable",
                    detail: "\(branch) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Check the selected Git root and revision, then retry."
                )
            }
        }
    }
}

/// 多 root Branches Popup 的 Push 对话框必须先读取目标 root 的数据，不能
/// 复用当前窗口绑定的 remote、branch 或 log 列表。
func beginMultiRootPushDialog(rootPath: String, branch: String) {
    beginFeedbackOperation("Load Push dialog")
    let defaultPushTagMode = GitPushTagSettings.projectTagMode(for: projectPath)
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let remotes = try rootRepo.remoteList()
            guard !remotes.isEmpty else {
                throw NSError(
                    domain: "Arbor.MultiRootPush",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "该 Git root 没有配置 remote。"]
                )
            }
            let branches = try rootRepo.branchList()
            let commits = try rootRepo.log(path: nil, limit: 200, follow: false, afterId: nil)
            let syncStatuses = try rootRepo.syncStatus()
            let selectedBranch = branches.contains(where: { $0.name == branch })
                ? branch
                : branches.first(where: { $0.isCurrent })?.name
            await MainActor.run {
                self.multiRootPushContext = MultiRootPushContext(
                    rootPath: rootPath,
                    remotes: remotes,
                    branches: branches,
                    commits: commits,
                    defaultRemote: remotes.count == 1 ? remotes[0].name : nil,
                    defaultBranch: selectedBranch,
                    currentHasUpstream: syncStatuses.first(where: { $0.branch == selectedBranch })?.trackingExists ?? false,
                    protectedBranchPatterns: self.effectiveProtectedBranchPatterns(
                        forRootPath: rootPath
                    ),
                    defaultPushTagMode: defaultPushTagMode
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Push unavailable",
                    detail: "\(branch) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Configure a remote in that Git root, then retry."
                )
            }
        }
    }
}

/// Open the same root-scoped Push dialog for an initialized submodule. A
/// submodule is a real Git repository with its own remotes and upstream; it
/// must not inherit the superproject's push target or branch state.
func beginSubmodulePushDialog(_ path: String) {
    guard let submodulePath = submoduleRootPath(path) else { return }
    beginMultiRootPushDialog(rootPath: submodulePath, branch: "")
}

/// Open RemoteConfigDialog for the nested repository itself. The parent
/// repository's remote list and refspecs are unrelated to a submodule.
func beginSubmoduleRemoteConfig(_ path: String) {
    guard let submodulePath = submoduleRootPath(path) else { return }
    beginMultiRootRemoteConfig(rootPath: submodulePath)
}

private func submoduleRootPath(_ path: String) -> String? {
    guard let projectPath, !path.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        return nil
    }
    return URL(fileURLWithPath: projectPath)
        .appendingPathComponent(path)
        .standardizedFileURL
        .path
}

private func pushNotificationID(rootPath: String) -> String {
    let normalizedPath = URL(fileURLWithPath: rootPath).standardizedFileURL.path
    let encoded = Data(normalizedPath.utf8)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
    return "arbor.push.v1.\(encoded)"
}

private func showOperationDetailsAction(notificationID: String) -> FeedbackAction {
    let request = ArborVCSActionRequest(
        kind: .showOperationDetails,
        projectPath: projectPath,
        rootPath: nil,
        shelfName: "",
        operationNotificationID: notificationID
    )
    return FeedbackAction(title: "Show Details", semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

private func singleRootPushRecoveryRequest(
    rootPath: String,
    recovery: PersistedPushRecovery,
    viewCommitRanges: [PersistedLogRevisionRange] = []
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .retryPushRecovery,
        projectPath: projectPath,
        rootPath: rootPath,
        shelfName: "",
        pushRecovery: recovery,
        logRevisionRanges: viewCommitRanges.isEmpty ? nil : viewCommitRanges
    )
}

private func singleRootPushRequest(
    rootPath: String,
    remote: String,
    branch: String,
    force: Bool,
    forceWithLease: Bool,
    setUpstream: Bool,
    refspec: String?,
    tagMode: PushDialogTagMode?,
    skipHooks: Bool,
    viewCommitRanges: [PersistedLogRevisionRange] = []
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .retryPush,
        projectPath: projectPath,
        rootPath: rootPath,
        shelfName: "",
        pushRecovery: PersistedPushRecovery(
            remote: remote,
            branch: branch,
            force: force,
            forceWithLease: forceWithLease,
            setUpstream: setUpstream,
            refspec: refspec,
            tagModeRaw: tagMode?.rawValue,
            skipHooks: skipHooks,
            rebase: false
        ),
        logRevisionRanges: viewCommitRanges.isEmpty ? nil : viewCommitRanges
    )
}

private func directPushRetryActions(
    rootPath: String,
    remote: String,
    branch: String,
    force: Bool,
    forceWithLease: Bool,
    setUpstream: Bool,
    refspec: String?,
    tagMode: PushDialogTagMode?,
    skipHooks: Bool,
    viewCommitRanges: [PersistedLogRevisionRange] = [],
    includeForce: Bool
) -> [FeedbackAction] {
    let retryRequest = singleRootPushRequest(
        rootPath: rootPath,
        remote: remote,
        branch: branch,
        force: force,
        forceWithLease: forceWithLease,
        setUpstream: setUpstream,
        refspec: refspec,
        tagMode: tagMode,
        skipHooks: skipHooks,
        viewCommitRanges: viewCommitRanges
    )
    var actions = [FeedbackAction]()
    if includeForce {
        let forceRequest = singleRootPushRequest(
            rootPath: rootPath,
            remote: remote,
            branch: branch,
            force: true,
            forceWithLease: false,
            setUpstream: setUpstream,
            refspec: refspec,
            tagMode: tagMode,
            skipHooks: skipHooks,
            viewCommitRanges: viewCommitRanges
        )
        actions.append(
            FeedbackAction(title: "Force Push Anyway", semanticAction: forceRequest) {
                self.handleVCSActionRequest(forceRequest)
            }
        )
    }
    actions.append(
        FeedbackAction(title: "Retry Push", semanticAction: retryRequest) {
            self.handleVCSActionRequest(retryRequest)
        }
    )
    return actions
}

/// Retry the original Push itself after a rejected or transport failure. The
/// root, remote, branch, refspec and force policy are persisted; only the
/// current Git state is revalidated before starting the command.
private func retrySingleRootPush(
    rootPath: String,
    push: PersistedPushRecovery,
    viewCommitRanges: [PersistedLogRevisionRange] = []
) {
    let hasCustomRefspec = !(push.refspec?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true)
    guard !push.remote.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
          hasCustomRefspec || !push.branch.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        feedbackCenter.error(
            "Push retry unavailable",
            detail: "The saved Push request is incomplete; no Git operation was started.",
            nextStep: "Open Push again and retry after selecting a remote and branch.",
            notificationID: pushNotificationID(rootPath: rootPath)
        )
        return
    }
    guard let rootRepo = try? openRepository(path: rootPath) else {
        feedbackCenter.warning(
            "Push retry unavailable",
            detail: "Open the Git root that originally rejected the Push before retrying.",
            nextStep: rootPath,
            notificationID: pushNotificationID(rootPath: rootPath),
            notificationGroup: .important
        )
        return
    }

    Task.detached(priority: .userInitiated) {
        let currentBranch = (try? rootRepo.branchList())?.first(where: { $0.isCurrent })?.name
        let branchIsValid = hasCustomRefspec || currentBranch == push.branch
        await MainActor.run {
            guard branchIsValid else {
                self.feedbackCenter.warning(
                    "Push retry is stale",
                    detail: "The checked-out branch changed. No Push was started.",
                    nextStep: "Switch back to \(push.branch), then retry the Push action.",
                    notificationID: self.pushNotificationID(rootPath: rootPath),
                    notificationGroup: .important
                )
                return
            }
            self.pushInRoot(
                rootPath: rootPath,
                remote: push.remote,
                branch: push.branch,
                force: push.force,
                forceWithLease: push.forceWithLease,
                setUpstream: push.setUpstream,
                refspec: push.refspec,
                tagMode: push.tagModeRaw.flatMap(PushDialogTagMode.init(rawValue:)),
                skipHooks: push.skipHooks,
                viewCommitRanges: viewCommitRanges
            )
        }
    }
}

/// Resume the rejected-push follow-up only when the original Git root and
/// checked-out branch are still active. IntelliJ's notification action is
/// bound to the Push operation; silently applying it to a different branch
/// after relaunch would be materially unsafe.
private func retrySingleRootPushRecovery(
    rootPath: String,
    recovery: PersistedPushRecovery,
    viewCommitRanges: [PersistedLogRevisionRange] = []
) {
    guard !recovery.remote.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
          !recovery.branch.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        feedbackCenter.error(
            "Push recovery unavailable",
            detail: "The saved Push recovery request is incomplete; no Git operation was started.",
            nextStep: "Open Push again and retry after selecting a remote and branch.",
            notificationID: pushNotificationID(rootPath: rootPath)
        )
        return
    }
    guard let activeRepo = repo,
          let activePath = activeRepo.workdir(),
          URL(fileURLWithPath: activePath).standardizedFileURL.path
              == URL(fileURLWithPath: rootPath).standardizedFileURL.path else {
        feedbackCenter.warning(
            "Push recovery unavailable",
            detail: "Open the Git root that originally rejected the Push before retrying.",
            nextStep: rootPath,
            notificationID: pushNotificationID(rootPath: rootPath),
            notificationGroup: .important
        )
        return
    }

    let expectedBranch = recovery.branch
    Task.detached(priority: .userInitiated) {
        let currentBranch = (try? activeRepo.branchList())?.first(where: { $0.isCurrent })?.name
        let trackingExists = (try? activeRepo.syncStatus())?
            .first(where: { $0.branch == expectedBranch })?
            .trackingExists == true
        await MainActor.run {
            guard currentBranch == expectedBranch, trackingExists else {
                self.feedbackCenter.warning(
                    "Push recovery is stale",
                    detail: "The repository branch or its configured upstream changed. No update or push was started.",
                    nextStep: "Switch back to \(expectedBranch) and restore its upstream, then retry the Push recovery action.",
                    notificationID: self.pushNotificationID(rootPath: rootPath),
                    notificationGroup: .important
                )
                return
            }
            // Keep the recovery as one root-scoped compound operation. The
            // generic doPull/doPush path owns separate global operation
            // lifecycles and would lose the original Push notification and
            // root context when update pauses for conflicts.
            self.updateRootForPushRecovery(
                rootPath: rootPath,
                remote: recovery.remote,
                branch: recovery.branch,
                force: recovery.force,
                forceWithLease: recovery.forceWithLease,
                setUpstream: recovery.setUpstream,
                refspec: nil,
                tagMode: recovery.tagModeRaw.flatMap(PushDialogTagMode.init(rawValue:)),
                skipHooks: recovery.skipHooks,
                rebase: recovery.rebase,
                viewCommitRanges: viewCommitRanges
            )
        }
    }
}

/// 从 root-scoped Push 对话框执行完整 push 选择：remote、branch、force、
/// force-with-lease、publish/upstream 和 custom refspec 都固定在该 root。
func pushInRoot(
    rootPath: String,
    remote requestedRemote: String?,
    branch requestedBranch: String?,
    force: Bool,
    forceWithLease: Bool,
    setUpstream: Bool,
    refspec: String?,
    tagMode: PushDialogTagMode?,
    skipHooks: Bool,
    viewCommitRanges: [PersistedLogRevisionRange] = []
) {
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    let protectedPatterns = effectiveProtectedBranchPatterns(forRootPath: rootPath)
    let notificationID = pushNotificationID(rootPath: rootPath)
    beginFeedbackOperation("Push", cancelHandle: cancel, notificationID: notificationID)
    Task.detached(priority: .userInitiated) {
        var resolvedRemote = requestedRemote
        var resolvedBranch = requestedBranch
        do {
            let rootRepo = try openRepository(path: rootPath)
            let rootRemotes = try rootRepo.remoteList()
            guard let remote = resolveSelectedRemoteName(
                selectedRemote: requestedRemote,
                availableRemoteNames: rootRemotes.map(\.name)
            ) else {
                throw NSError(
                    domain: "Arbor.MultiRootPush",
                    code: 2,
                    userInfo: [
                        NSLocalizedDescriptionKey: rootRemotes.count > 1
                            ? "该 Git root 配置了多个 remote，请先选择目标 remote。"
                            : "该 Git root 没有可用的 remote。"
                    ]
                )
            }
            resolvedRemote = remote
            let rootBranches = try rootRepo.branchList()
            let branch = requestedBranch
                ?? rootBranches.first(where: { $0.isCurrent })?.name
                ?? ""
            let hasCustomRefspec = !(refspec?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true)
            guard hasCustomRefspec || !branch.isEmpty else {
                throw NSError(
                    domain: "Arbor.MultiRootPush",
                    code: 3,
                    userInfo: [NSLocalizedDescriptionKey: "Push 需要一个本地分支。"]
                )
            }
            resolvedBranch = branch
            let protectedTarget = refspec?
                .split(separator: ":", maxSplits: 1, omittingEmptySubsequences: true)
                .last
                .map { $0.replacingOccurrences(of: "refs/heads/", with: "") }
                ?? branch
            guard !force || !GitProtectedBranchRules.matches(
                protectedTarget,
                patterns: protectedPatterns
            ) else {
                throw NSError(
                    domain: "Arbor.MultiRootPush",
                    code: 4,
                    userInfo: [NSLocalizedDescriptionKey: "\(protectedTarget) is protected by Git settings."]
                )
            }
            let engineTagMode = tagMode.map { mode in
                switch mode {
                case .all: PushTagMode.all
                case .currentBranch: PushTagMode.follow
                }
            }
            if let refspec, !refspec.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                if engineTagMode != nil || skipHooks {
                    try rootRepo.pushRefspecWithOptionsAndAuthAndCancel(
                        remote: remote,
                        refspec: refspec,
                        force: force,
                        forceWithLease: force && forceWithLease,
                        tagMode: engineTagMode,
                        skipHooks: skipHooks,
                        broker: broker,
                        cancel: cancel
                    )
                } else {
                    try rootRepo.pushRefspecWithAuthAndCancel(
                        remote: remote,
                        refspec: refspec,
                        force: force,
                        forceWithLease: force && forceWithLease,
                        broker: broker,
                        cancel: cancel
                    )
                }
            } else {
                let trackingExists = (try rootRepo.syncStatus())
                    .first(where: { $0.branch == branch })?.trackingExists ?? false
                try rootRepo.pushWithOptionsAndAuthAndCancel(
                    remote: remote,
                    branch: branch,
                    force: force,
                    forceWithLease: force && forceWithLease,
                    setUpstream: setUpstream || !trackingExists,
                    tagMode: engineTagMode,
                    skipHooks: skipHooks,
                    broker: broker,
                    cancel: cancel
                )
            }
            await MainActor.run {
                self.loadMultiRoots()
                let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
                    ranges: viewCommitRanges
                )
                self.feedbackCenter.success(
                    "Push completed",
                    detail: "\(remote)/\(branch) · \(rootPath)",
                    additionalActions: viewCommitsAction.map { [$0] } ?? [],
                    notificationID: notificationID
                )
                self.autoOpenUpdateInfoIfEnabled(viewCommitRanges)
            }
        } catch {
            let retryRemote = resolvedRemote
            let retryBranch = resolvedBranch
            let recoveryRepo = try? openRepository(path: rootPath)
            let recoveryBranches = recoveryRepo.flatMap { try? $0.branchList() } ?? []
            let recoveryStatuses = recoveryRepo.flatMap { try? $0.syncStatus() } ?? []
            let currentBranchForPush = recoveryBranches.first(where: { $0.isCurrent })?.name
            let hasTrackingForPush = recoveryStatuses
                .first(where: { $0.branch == retryBranch })?.trackingExists ?? false
            await MainActor.run {
                self.loadMultiRoots()
                if let stale = stalePushRejectionDetails(error) {
                    let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
                        ranges: viewCommitRanges
                    )
                    let actions = self.directPushRetryActions(
                        rootPath: rootPath,
                        remote: stale.remote,
                        branch: stale.branch,
                        force: force,
                        forceWithLease: forceWithLease,
                        setUpstream: setUpstream,
                        refspec: refspec,
                        tagMode: tagMode,
                        skipHooks: skipHooks,
                        viewCommitRanges: viewCommitRanges,
                        includeForce: true
                    ) + (viewCommitsAction.map { [$0] } ?? []) + [
                        self.showOperationDetailsAction(notificationID: notificationID)
                    ]
                    self.feedbackCenter.warning(
                        "Push rejected by force-with-lease",
                        detail: "\(rootPath): \(stale.remote)/\(stale.branch): \(stale.message)",
                        nextStep: "The remote branch changed after the lease was recorded. Verify the remote history before overwriting it.",
                        additionalActions: actions,
                        notificationID: notificationID,
                        notificationGroup: .important,
                        localized: false
                    )
                } else if case let .PushRejected(kind, rejectedRemote, rejectedBranch, message) = error as? EngineError,
                          kind == .nonFastForward,
                          !force,
                          refspec == nil {
                    let autoUpdate = gitPushAutoUpdateIsEligible(
                        enabled: GitPushAutoUpdateSettings.value(for: self.projectPath),
                        force: force,
                        refspec: refspec,
                        currentBranch: currentBranchForPush,
                        rejectedBranch: rejectedBranch,
                        hasTracking: hasTrackingForPush
                    )
                    if autoUpdate {
                        self.updateRootForPushRecovery(
                            rootPath: rootPath,
                            remote: rejectedRemote,
                            branch: rejectedBranch,
                            force: force,
                            forceWithLease: forceWithLease,
                            setUpstream: setUpstream,
                            refspec: nil,
                            tagMode: tagMode,
                            skipHooks: skipHooks,
                            rebase: GitUpdateMethodSettings.method(for: self.projectPath) == .rebase,
                            viewCommitRanges: viewCommitRanges
                        )
                    } else {
                        let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
                            ranges: viewCommitRanges
                        )
                        let recovery = PersistedPushRecovery(
                            remote: rejectedRemote,
                            branch: rejectedBranch,
                            force: force,
                            forceWithLease: forceWithLease,
                            setUpstream: setUpstream,
                            refspec: refspec,
                            tagModeRaw: tagMode?.rawValue,
                            skipHooks: skipHooks,
                            rebase: false
                        )
                        let mergeRequest = self.singleRootPushRecoveryRequest(
                            rootPath: rootPath,
                            recovery: recovery,
                            viewCommitRanges: viewCommitRanges
                        )
                        let rebaseRequest = self.singleRootPushRecoveryRequest(
                            rootPath: rootPath,
                            recovery: PersistedPushRecovery(
                                remote: recovery.remote,
                                branch: recovery.branch,
                                force: recovery.force,
                                forceWithLease: recovery.forceWithLease,
                                setUpstream: recovery.setUpstream,
                                refspec: recovery.refspec,
                                tagModeRaw: recovery.tagModeRaw,
                                skipHooks: recovery.skipHooks,
                                rebase: true
                            ),
                            viewCommitRanges: viewCommitRanges
                        )
                        let recoveryActions = [
                            FeedbackAction(title: "Update with Merge", semanticAction: mergeRequest) {
                                self.handleVCSActionRequest(mergeRequest)
                            },
                            FeedbackAction(title: "Update with Rebase", semanticAction: rebaseRequest) {
                                self.handleVCSActionRequest(rebaseRequest)
                            }
                        ] + self.directPushRetryActions(
                            rootPath: rootPath,
                            remote: rejectedRemote,
                            branch: rejectedBranch,
                            force: force,
                            forceWithLease: forceWithLease,
                            setUpstream: setUpstream,
                            refspec: refspec,
                            tagMode: tagMode,
                            skipHooks: skipHooks,
                            viewCommitRanges: viewCommitRanges,
                            includeForce: false
                        ) + (viewCommitsAction.map { [$0] } ?? []) + [
                            self.showOperationDetailsAction(notificationID: notificationID)
                        ]
                        self.feedbackCenter.warning(
                            "Push rejected",
                            detail: "\(rootPath): \(rejectedRemote)/\(rejectedBranch): \(message)",
                            nextStep: "Update this Git root, resolve any conflicts, then retry Push.",
                            additionalActions: recoveryActions,
                            notificationID: notificationID,
                            notificationGroup: .important,
                            localized: false
                        )
                    }
                } else {
                    let viewCommitsAction = self.multiRootUpdateViewCommitsAction(
                        ranges: viewCommitRanges
                    )
                    let retryActions: [FeedbackAction]
                    let hasCustomRefspec = !(refspec?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true)
                    if let remote = retryRemote,
                       let branch = retryBranch,
                       !remote.isEmpty,
                       hasCustomRefspec || !branch.isEmpty {
                        retryActions = self.directPushRetryActions(
                            rootPath: rootPath,
                            remote: remote,
                            branch: branch,
                            force: force,
                            forceWithLease: forceWithLease,
                            setUpstream: setUpstream,
                            refspec: refspec,
                            tagMode: tagMode,
                            skipHooks: skipHooks,
                            viewCommitRanges: viewCommitRanges,
                            includeForce: false
                        )
                    } else {
                        retryActions = []
                    }
                    self.feedbackCenter.error(
                        "Push failed",
                        detail: "\(rootPath): \(friendlyRemoteError(error))",
                        nextStep: "Check the selected remote, refspec, credentials, and protected-branch settings.",
                        additionalActions: retryActions
                            + (viewCommitsAction.map { [$0] } ?? [])
                            + [self.showOperationDetailsAction(notificationID: notificationID)],
                        notificationID: notificationID,
                        notificationGroup: .important
                    )
                }
                if self.isAuthenticationFailure(error) {
                    self.showHostingAuthPrompt = true
                }
            }
        }
    }
}

/// Root-scoped recovery for a rejected push. The selected nested repository is
/// updated directly; it never falls back to the superproject's current repo.
/// A clean update proceeds straight to the original push, while an update
/// conflict stays in the existing project-level resolver with a Resolve action.
private func updateRootForPushRecovery(
    rootPath: String,
    remote: String,
    branch: String,
    force: Bool,
    forceWithLease: Bool,
    setUpstream: Bool,
    refspec: String?,
    tagMode: PushDialogTagMode?,
    skipHooks: Bool,
    rebase: Bool,
    viewCommitRanges: [PersistedLogRevisionRange] = []
) {
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    let notificationID = pushNotificationID(rootPath: rootPath)
    beginFeedbackOperation(
        rebase ? "Update root with rebase" : "Update root with merge",
        cancelHandle: cancel,
        notificationID: notificationID
    )
    let fetchTagMode = fetchTagsMode
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    Task.detached(priority: .userInitiated) {
        let previousHeads = Self.headCommitIDs(for: [rootPath])
        do {
            let result = try runRootUpdateForPushRecoveryWithOptions(
                rootPath: rootPath,
                remote: remote,
                branch: branch,
                rebase: rebase,
                tagMode: fetchTagMode,
                broker: broker,
                cancel: cancel,
                savePolicy: projectSavePolicy
            )
            let currentHeads = Self.headCommitIDs(for: [rootPath])
            let latestViewCommitRanges = result.success && !result.skipped
                ? Self.updateSessionRevisionRanges(
                    previousHeads: previousHeads,
                    currentHeads: currentHeads,
                    results: [result]
                )
                : []
            let combinedViewCommitRanges = Self.joinedRevisionRanges(
                existing: viewCommitRanges,
                latest: latestViewCommitRanges
            )
            await MainActor.run {
                self.loadMultiRoots()
                let existingViewCommitsAction = self.multiRootUpdateViewCommitsAction(
                    ranges: viewCommitRanges
                )
                if result.success && !result.skipped {
                    self.feedbackCenter.success(
                        "Root updated; retrying Push",
                        detail: "\(rootPath): \(remote)/\(branch)",
                        notificationID: notificationID
                    )
                    self.pushInRoot(
                        rootPath: rootPath,
                        remote: remote,
                        branch: branch,
                        force: force,
                        forceWithLease: forceWithLease,
                        setUpstream: setUpstream,
                        refspec: refspec,
                        tagMode: tagMode,
                        skipHooks: skipHooks,
                        viewCommitRanges: combinedViewCommitRanges
                    )
                } else if result.skipped {
                    self.feedbackCenter.warning(
                        "Push update cancelled",
                        detail: "\(rootPath): \(result.message)",
                        nextStep: "Retry the root-scoped update when the worktree is ready.",
                        actionTitle: "Retry Update",
                        action: {
                            self.updateRootForPushRecovery(
                                rootPath: rootPath,
                                remote: remote,
                                branch: branch,
                                force: force,
                                forceWithLease: forceWithLease,
                                setUpstream: setUpstream,
                                refspec: refspec,
                                tagMode: tagMode,
                                skipHooks: skipHooks,
                                rebase: rebase,
                                viewCommitRanges: viewCommitRanges
                            )
                        },
                        additionalActions: existingViewCommitsAction.map { [$0] } ?? [],
                        notificationID: notificationID,
                        localized: false
                    )
                } else if result.message.localizedCaseInsensitiveContains("conflict")
                            || result.message.localizedCaseInsensitiveContains("operation is already in progress") {
                    self.feedbackCenter.warning(
                        "Push update paused for conflicts",
                        detail: "\(rootPath): \(result.message)",
                        nextStep: "Resolve the files in this Git root, then continue the operation.",
                        actionTitle: "Resolve Conflicts",
                        action: {
                            self.openMultiRootConflictResolver(preferredRootPath: rootPath)
                        },
                        additionalActions: existingViewCommitsAction.map { [$0] } ?? [],
                        notificationID: notificationID,
                        localized: false
                    )
                } else {
                    self.feedbackCenter.error(
                        "Push update failed",
                        detail: "\(rootPath): \(result.message)",
                        nextStep: "Resolve the update error, then retry the root-scoped update.",
                        actionTitle: "Retry Update",
                        action: {
                            self.updateRootForPushRecovery(
                                rootPath: rootPath,
                                remote: remote,
                                branch: branch,
                                force: force,
                                forceWithLease: forceWithLease,
                                setUpstream: setUpstream,
                                refspec: refspec,
                                tagMode: tagMode,
                                skipHooks: skipHooks,
                                rebase: rebase,
                                viewCommitRanges: viewCommitRanges
                            )
                        },
                        additionalActions: existingViewCommitsAction.map { [$0] } ?? [],
                        notificationID: notificationID,
                        localized: false
                    )
                }
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                let existingViewCommitsAction = self.multiRootUpdateViewCommitsAction(
                    ranges: viewCommitRanges
                )
                self.feedbackCenter.error(
                    "Push update failed",
                    detail: "\(rootPath): \(friendlyRemoteError(error))",
                    nextStep: "Resolve the update error, then retry the root-scoped update.",
                    actionTitle: "Retry Update",
                    action: {
                        self.updateRootForPushRecovery(
                            rootPath: rootPath,
                            remote: remote,
                            branch: branch,
                            force: force,
                            forceWithLease: forceWithLease,
                            setUpstream: setUpstream,
                            refspec: refspec,
                            tagMode: tagMode,
                            skipHooks: skipHooks,
                            rebase: rebase,
                            viewCommitRanges: viewCommitRanges
                        )
                    },
                    additionalActions: existingViewCommitsAction.map { [$0] } ?? [],
                    notificationID: notificationID
                )
            }
        }
    }
}

/// 多 root Branches Popup 的 Merge into Current：在目标 root 的当前分支上执行，
/// 冲突状态留在目标 root，由 Git Roots 面板提供 root 定向恢复入口。
func mergeBranchInRoot(rootPath: String, branch: String) {
    beginFeedbackOperation("Merge branch")
    let protectedPatterns = effectiveProtectedBranchPatterns
    let configuredDeleteOnMerge = mergeDeleteOnMergeOption
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let initialHead = rootRepo.headCommitId()
            let localSourceBranch = try? rootRepo.branchList().first {
                $0.name == branch && !$0.isCurrent
            }
            let canDeleteMergedBranch = localSourceBranch != nil
                && !GitProtectedBranchRules.matches(branch, patterns: protectedPatterns)
            let deleteOnMerge = GitDeleteOnMergeOption.effectiveOption(
                configuredDeleteOnMerge,
                canDeleteBranch: canDeleteMergedBranch
            )
            let outcome = try rootRepo.mergeWithSettings(
                branch: branch,
                options: MergeOptions(
                    mode: .fastForward,
                    commitMessage: nil,
                    noCommit: false,
                    noVerify: false,
                    allowUnrelatedHistories: false
                )
            )
            let finalHead = rootRepo.headCommitId()
            await MainActor.run {
                self.loadMultiRoots()
                if outcome.completed {
                    let viewCommitsActions = self.completedMergeViewCommitsAction(
                        rootPath: rootPath,
                        initialHead: initialHead,
                        finalHead: finalHead,
                        completed: outcome.completed
                    ).map { [$0] } ?? []
                    if deleteOnMerge == .delete {
                        self.feedbackCenter.success(
                            "Merge completed",
                            detail: "\(branch) · \(rootPath)",
                            additionalActions: viewCommitsActions,
                            notificationGroup: .standard
                        )
                        self.deleteBranchInRoot(rootPath: rootPath, name: branch, confirm: false)
                    } else if deleteOnMerge == .propose {
                        self.feedbackCenter.success(
                            "Merge completed",
                            detail: "\(branch) · \(rootPath)",
                            actionTitle: "Delete branch",
                            action: postMergeDeleteAction(
                                repo: rootRepo,
                                branch: branch,
                                rootPath: rootPath
                            ),
                            additionalActions: viewCommitsActions,
                            notificationGroup: .standard
                        )
                    } else {
                        self.feedbackCenter.success(
                            "Merge completed",
                            detail: "\(branch) · \(rootPath)",
                            additionalActions: viewCommitsActions,
                            notificationGroup: .standard
                        )
                    }
                } else {
                    self.feedbackCenter.warning(
                        "Merge paused",
                        detail: outcome.conflicts.isEmpty
                            ? "\(branch) · \(rootPath): merge result awaits completion"
                            : "\(branch) · \(rootPath): \(outcome.conflicts.count) conflict(s)",
                        nextStep: outcome.conflicts.isEmpty
                            ? "Use Continue in Git Roots to create the merge commit."
                            : "Resolve conflicts in that root, then use Continue or Abort in Git Roots."
                    )
                }
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error(
                    "Merge failed",
                    detail: "\(branch) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Check the target root status, then retry Merge."
                )
            }
        }
    }
}

/// 多 root Branches Popup 的 Rebase Current onto：先生成该 root 当前分支的
/// explicit todo，再交给引擎执行，保持与单 root Rebase 对话框相同的历史语义。
func rebaseCurrentInRoot(rootPath: String, onto: String) {
    let cancel = GitCancelHandle()
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation("Rebase branch", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let seed = try rootRepo.branchList()
                .first(where: { $0.isCurrent })
                .flatMap { makeRebaseUndoSeed(repo: rootRepo, branch: $0.name, onto: onto) }
            if let seed {
                saveRebaseUndoSeed(seed)
            }
            let todo = try rootRepo.rebaseTodo(onto: onto, autoSquash: false)
            let outcome = try rootRepo.rebaseWithTodoAndPolicyAndCancel(
                onto: onto,
                todo: todo,
                preserveMerges: false,
                savePolicy: projectSavePolicy,
                cancel: cancel
            )
            let finalHead = seed.flatMap { try? rootRepo.revisionCommitId(revision: $0.branch) }
            let currentBranch = (try? rootRepo.branchList())?.first(where: { $0.isCurrent })?.name
            let undoTarget = rebaseUndoTargetAfterCompletion(
                seed: seed,
                currentBranch: currentBranch,
                finalHead: finalHead
            )
            await MainActor.run {
                self.loadMultiRoots()
                if outcome.paused {
                    if let seed {
                        self.rebaseUndoSeed = seed
                        saveRebaseUndoSeed(seed)
                    }
                    self.feedbackCenter.warning(
                        "Rebase paused",
                        detail: "\(onto) · \(rootPath): \(outcome.conflicts.count) conflict(s)",
                        nextStep: "Resolve conflicts in that root, then use Continue, Skip, or Abort in Git Roots.",
                        additionalActions: seed.map {
                            [persistedRebaseRecoveryAction(rootPath: $0.repositoryPath, branch: $0.branch)]
                        } ?? [],
                        notificationID: seed.map { rebaseRecoveryNotificationID(repositoryPath: $0.repositoryPath) }
                    )
                } else {
                    if let seed {
                        self.rebaseUndoSeed = nil
                        clearRebaseUndoSeed(repositoryPath: seed.repositoryPath)
                    }
                    if let undoTarget {
                        self.feedbackCenter.success(
                            "Rebase completed",
                            detail: "\(onto) · \(rootPath)",
                            additionalActions: [self.rebaseUndoFeedbackAction(for: undoTarget)],
                            notificationID: rebaseUndoNotificationID(
                                repositoryPath: undoTarget.repositoryPath
                            ),
                            notificationGroup: .standard
                        )
                    } else {
                        self.feedbackCenter.success("Rebase completed", detail: "\(onto) · \(rootPath)")
                    }
                }
            }
        } catch {
            if case .Cancelled = error as? EngineError {
                await MainActor.run {
                    self.feedbackCenter.warning(
                        "Rebase cancelled",
                        detail: "The saved local scene for \(rootPath) was not discarded.",
                        nextStep: "Check Saved Changes or Stash, restore any pending local scene, then retry."
                    )
                }
                return
            }
            let rootRepo = try? openRepository(path: rootPath)
            let state = rootRepo.flatMap { try? $0.operationState() }
            let seed = rootRepo?.workdir().flatMap {
                loadRebaseUndoSeed(repositoryPath: $0)
            }
            await MainActor.run {
                self.loadMultiRoots()
                if state?.kind == .rebase {
                    if let seed {
                        saveRebaseUndoSeed(seed)
                    }
                    self.feedbackCenter.warning(
                        "Rebase paused",
                        detail: "\(onto) · \(rootPath): \(errorMessage(error))",
                        nextStep: "Resolve conflicts in that root, then use Continue, Skip, or Abort in Git Roots.",
                        additionalActions: seed.map {
                            [persistedRebaseRecoveryAction(rootPath: $0.repositoryPath, branch: $0.branch)]
                        } ?? [],
                        notificationID: seed.map { rebaseRecoveryNotificationID(repositoryPath: $0.repositoryPath) }
                    )
                } else {
                    if let seed {
                        self.rebaseUndoSeed = nil
                        clearRebaseUndoSeed(repositoryPath: seed.repositoryPath)
                    }
                    self.feedbackCenter.error(
                        "Rebase failed",
                        detail: "\(onto) · \(rootPath): \(errorMessage(error))",
                        nextStep: "Check the target root status, then retry Rebase."
                    )
                }
            }
        }
    }
}

/// 多 root tracking 配置使用显式输入，避免把当前 root 的 remote branch 列表
/// 错误地复用到另一个 root。
func setBranchUpstreamInRoot(rootPath: String, branch: String) {
    let alert = NSAlert()
    alert.messageText = "Set Upstream"
    alert.informativeText = "输入 remote-tracking branch，例如 origin/\(branch)。"
    let field = NSTextField(string: "origin/\(branch)")
    field.frame = NSRect(x: 0, y: 0, width: 300, height: 24)
    alert.accessoryView = field
    alert.addButton(withTitle: "Set Upstream")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    let upstream = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !upstream.isEmpty else { return }
    setBranchUpstreamInRoot(
        rootPath: rootPath,
        branch: branch,
        upstream: upstream,
        requireCurrentBranch: false
    )
}

/// 保存已从目标 root 的 remote-tracking branch 选择器中选出的 upstream。
/// The write remains explicitly root-scoped; it never falls back to `repo`.
func setBranchUpstreamInRoot(
    rootPath: String,
    branch: String,
    upstream: String,
    requireCurrentBranch: Bool
) {
    beginFeedbackOperation("Set branch upstream")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            if requireCurrentBranch {
                let currentBranch = try rootRepo.branchList().first(where: { $0.isCurrent })?.name
                guard currentBranch == branch else {
                    throw NSError(
                        domain: "Arbor.UpstreamRecovery",
                        code: 1,
                        userInfo: [
                            NSLocalizedDescriptionKey:
                                "The target root is no longer on branch '\(branch)'."
                        ]
                    )
                }
            }
            try rootRepo.branchSetUpstream(branch: branch, upstream: upstream)
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.success("Upstream configured", detail: "\(branch) → \(upstream) · \(rootPath)")
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error("Set upstream failed", detail: "\(branch) · \(rootPath): \(errorMessage(error))")
            }
        }
    }
}

/// Load the upstream choices from the skipped root itself before showing the
/// shared picker. This matches IntelliJ's repository-qualified recovery action
/// and avoids asking users to hand-type a refspec in a multi-root project.
func presentUpstreamDialogInRoot(rootPath: String, displayName: String, branch: String) {
    let normalizedRoot = URL(fileURLWithPath: rootPath).standardizedFileURL.path
    let normalizedBranch = branch.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedRoot.isEmpty, !normalizedBranch.isEmpty else { return }
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: normalizedRoot)
            let currentBranch = try rootRepo.branchList().first(where: { $0.isCurrent })?.name
            guard currentBranch == normalizedBranch else {
                await MainActor.run {
                    self.feedbackCenter.warning(
                        "Upstream recovery is stale",
                        detail: "\(displayName) is no longer on branch \(normalizedBranch)."
                    )
                }
                return
            }
            let remoteBranches = try rootRepo.remoteBranchList()
            let currentUpstream = (try? rootRepo.syncStatus())?.first {
                $0.branch == normalizedBranch && $0.trackingExists
            }?.upstream
            await MainActor.run {
                self.multiRootUpstreamContext = MultiRootUpstreamContext(
                    rootPath: normalizedRoot,
                    displayName: displayName,
                    localBranch: normalizedBranch,
                    remoteBranches: remoteBranches,
                    currentUpstream: currentUpstream
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Load upstream branches failed",
                    detail: "\(displayName) · \(errorMessage(error))"
                )
            }
        }
    }
}

func unsetBranchUpstreamInRoot(rootPath: String, branch: String) {
    beginFeedbackOperation("Unset branch upstream")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            try rootRepo.branchUnsetUpstream(branch: branch)
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.success("Upstream removed", detail: "\(branch) · \(rootPath)")
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error("Unset upstream failed", detail: "\(branch) · \(rootPath): \(errorMessage(error))")
            }
        }
    }
}

func presentSingleRootRenameBranchDialog(rootPath: String, oldName: String) {
    guard let rootRepo = try? openRepository(path: rootPath),
          (try? rootRepo.branchList().contains(where: { $0.name == oldName })) == true else {
        feedbackCenter.warning(
            "Rename branch unavailable",
            detail: "The selected branch no longer exists in this Git root.",
            nextStep: "Refresh Git Roots and try again."
        )
        return
    }
    singleRootRenameRootPath = rootPath
    singleRootRenameOldName = oldName
    singleRootRenameNewName = oldName
    singleRootRenameUnsetUpstream = false
    singleRootRenameHasUpstream = ((try? rootRepo.syncStatus()) ?? []).contains {
        $0.branch == oldName && $0.trackingExists
    }
    showSingleRootRenameBranchDialog = true
}

func dismissSingleRootRenameBranchDialog() {
    showSingleRootRenameBranchDialog = false
    singleRootRenameRootPath = ""
    singleRootRenameOldName = ""
    singleRootRenameNewName = ""
    singleRootRenameUnsetUpstream = false
    singleRootRenameHasUpstream = false
}

func validateSingleRootRenameName(rootPath: String, oldName: String, value: String) -> String? {
    let candidate = value.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !candidate.isEmpty else { return nil }
    guard let snapshot = multiRootBranchSnapshots.first(where: { $0.rootPath == rootPath }) else {
        return "The selected Git root is no longer available."
    }
    if let conflict = branchRenameConflictMessage(
        oldName: oldName,
        newName: candidate,
        localBranchNames: snapshot.branches.map(\.name),
        remoteBranchNames: snapshot.remoteBranches.map(\.name)
    ) {
        return conflict
    }
    guard let rootRepo = try? openRepository(path: rootPath) else {
        return "The selected Git root could not be opened."
    }
    do {
        try rootRepo.validateBranchName(name: candidate)
        return nil
    } catch {
        return errorMessage(error)
    }
}

func renameBranchInRoot(rootPath: String, oldName: String) {
    presentSingleRootRenameBranchDialog(rootPath: rootPath, oldName: oldName)
}

func renameBranchInRoot(
    rootPath: String,
    oldName: String,
    newName: String,
    unsetUpstream: Bool
) {
    let oldName = oldName.trimmingCharacters(in: .whitespacesAndNewlines)
    let newName = newName.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !oldName.isEmpty, !newName.isEmpty, oldName != newName else { return }
    dismissSingleRootRenameBranchDialog()
    beginFeedbackOperation("Rename branch")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let localBranchNames = try rootRepo.branchList().map(\.name)
            let remoteBranchNames = try rootRepo.remoteBranchList().map(\.name)
            if let conflict = branchRenameConflictMessage(
                oldName: oldName,
                newName: newName,
                localBranchNames: localBranchNames,
                remoteBranchNames: remoteBranchNames
            ) {
                throw NSError(
                    domain: "Arbor.BranchRename",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: conflict]
                )
            }
            try rootRepo.validateBranchName(name: newName)
            try rootRepo.branchRename(old: oldName, new: newName)
            if unsetUpstream {
                do {
                    try rootRepo.branchUnsetUpstream(branch: newName)
                } catch {
                    do {
                        try rootRepo.branchRename(old: newName, new: oldName)
                    } catch let rollbackError {
                        throw NSError(
                            domain: "Arbor.BranchRename",
                            code: 3,
                            userInfo: [
                                NSLocalizedDescriptionKey:
                                    "Upstream removal failed: \(errorMessage(error)); automatic rename rollback failed: \(errorMessage(rollbackError))"
                            ]
                        )
                    }
                    throw NSError(
                        domain: "Arbor.BranchRename",
                        code: 2,
                        userInfo: [
                            NSLocalizedDescriptionKey:
                                "Upstream removal failed; the branch rename was rolled back: \(errorMessage(error))"
                        ]
                    )
                }
            }
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.success("Branch renamed", detail: "\(oldName) → \(newName) · \(rootPath)")
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error("Rename branch failed", detail: "\(oldName) · \(rootPath): \(errorMessage(error))")
            }
        }
    }
}

func deleteBranchInRoot(rootPath: String, name: String, confirm: Bool = true) {
    if confirm {
        let alert = NSAlert()
        alert.messageText = "Delete branch \(name)?"
        alert.informativeText = "This removes the local branch reference in the selected root."
        alert.addButton(withTitle: "Delete")
        alert.addButton(withTitle: "Cancel")
        alert.buttons.first?.hasDestructiveAction = true
        guard alert.runModal() == .alertFirstButtonReturn else { return }
    }
    let protectedPatterns = effectiveProtectedBranchPatterns
    beginFeedbackOperation("Delete branch")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let preview = try? rootRepo.branchDeletePreview(name: name)
            let syncStatusesBeforeDelete = (try? rootRepo.syncStatus()) ?? []
            try rootRepo.branchDelete(name: name, force: false)
            await MainActor.run {
                self.loadMultiRoots()
                if let preview {
                    let context = BranchDeleteRecoveryContext(
                        repo: rootRepo,
                        preview: preview,
                        rootPath: rootPath,
                        trackedRemoteBranch: deletableTrackedRemoteBranch(
                            branchName: name,
                            upstream: preview.upstream,
                            syncStatuses: syncStatusesBeforeDelete,
                            protectedPatterns: protectedPatterns
                        )
                    )
                    self.branchDeleteRecovery = context
                    self.feedbackCenter.success(
                        "Branch deleted",
                        detail: "\(name) · \(rootPath)",
                        additionalActions: self.branchDeleteRecoveryActions(
                            contexts: [context]
                        ),
                        notificationID: self.branchDeleteNotificationID(),
                        notificationGroup: .standard
                    )
                } else {
                    self.feedbackCenter.success("Branch deleted", detail: "\(name) · \(rootPath)")
                }
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                if isUnmergedBranchDeletionError(error),
                   let forceRepo = try? openRepository(path: rootPath) {
                    self.prepareForceDeleteBranch(repo: forceRepo, name: name, rootPath: rootPath)
                } else {
                    self.feedbackCenter.error("Delete branch failed", detail: "\(name) · \(rootPath): \(errorMessage(error))")
                }
            }
        }
    }
}

/// Batch counterpart of IntelliJ's DeleteBranchAction for selected local
/// references. Targets may belong to different roots and may have different
/// names; each deletion is still executed against its own repository. Safe
/// deletion is attempted first, then an unmerged target is force-deleted only
/// because the user explicitly confirmed the batch action. Every successful
/// deletion retains its exact preview for Restore/Rollback.
func deleteSelectedBranchesInRoots(_ targets: [BranchDashboardReference]) {
    if targets.allSatisfy({ $0.kind == .tag }) {
        deleteSelectedTagsInRoots(targets)
        return
    }
    if targets.allSatisfy({ $0.kind == .remote }) {
        deleteSelectedRemoteBranchesInRoots(targets)
        return
    }

    let selected = targets
        .filter { !$0.isCurrent }
        .sorted {
            if $0.rootPath == $1.rootPath { return $0.name < $1.name }
            return $0.rootPath < $1.rootPath
        }
    guard !selected.isEmpty, !multiRootRunning else { return }

    let alert = NSAlert()
    alert.messageText = "Delete selected branches?"
    alert.informativeText = selected
        .map { "\($0.name) · \($0.rootPath)" }
        .joined(separator: "\n")
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    let displayNames = Dictionary(
        uniqueKeysWithValues: multiRootBranchSnapshots.map { ($0.rootPath, $0.displayName) }
    )
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    multiRootRunning = true
    beginFeedbackOperation("Delete selected branches", cancelHandle: cancel)
    let protectedPatterns = effectiveProtectedBranchPatterns
    Task.detached(priority: .userInitiated) {
        var results: [RootOperationResult] = []
        var recoveryContexts: [BranchDeleteRecoveryContext] = []
        var syncStatusesByBranch: [String: [[SyncStatus]]] = [:]
        var failures: [String] = []
        var forceDeleted: [String] = []
        var cancelled = false

        for target in selected {
            guard !cancel.isCancelled() else {
                cancelled = true
                break
            }
            do {
                let rootRepo = try openRepository(path: target.rootPath)
                if target.kind == .remote {
                    try rootRepo.deleteRemoteBranchWithAuthAndCancel(
                        remoteBranch: target.name,
                        broker: broker,
                        cancel: cancel
                    )
                    results.append(
                        RootOperationResult(
                            rootPath: target.rootPath,
                            displayName: displayNames[target.rootPath] ?? target.rootPath,
                            success: true,
                            skipped: false,
                            message: "Deleted \(target.name)"
                        )
                    )
                    continue
                }

                let preview = try rootRepo.branchDeletePreview(name: target.name)
                let syncStatusesBeforeDelete = (try? rootRepo.syncStatus()) ?? []
                syncStatusesByBranch[target.name, default: []].append(syncStatusesBeforeDelete)
                var wasForceDeleted = false
                do {
                    try rootRepo.branchDelete(name: target.name, force: false)
                } catch {
                    guard isUnmergedBranchDeletionError(error) else { throw error }
                    try rootRepo.branchDelete(name: target.name, force: true)
                    wasForceDeleted = true
                }
                recoveryContexts.append(
                    BranchDeleteRecoveryContext(
                        repo: rootRepo,
                        preview: preview,
                        rootPath: target.rootPath
                    )
                )
                if wasForceDeleted {
                    forceDeleted.append("\(target.name) · \(target.rootPath)")
                }
                results.append(
                    RootOperationResult(
                        rootPath: target.rootPath,
                        displayName: displayNames[target.rootPath] ?? target.rootPath,
                        success: true,
                        skipped: false,
                        message: wasForceDeleted
                            ? "Deleted \(target.name) (force)"
                            : "Deleted \(target.name)"
                    )
                )
            } catch {
                if cancel.isCancelled() {
                    cancelled = true
                    break
                }
                let detailMessage = target.kind == .remote
                    ? friendlyRemoteError(error)
                    : errorMessage(error)
                let detail = "\(target.name) · \(target.rootPath): \(detailMessage)"
                failures.append(detail)
                results.append(
                    RootOperationResult(
                        rootPath: target.rootPath,
                        displayName: displayNames[target.rootPath] ?? target.rootPath,
                        success: false,
                        skipped: false,
                        message: "\(target.name): \(detailMessage)"
                    )
                )
            }
        }

        let completedResults = results
        let completedRecoveryContexts = recoveryContexts.map { context in
            let deletableRemoteBranches = deletableTrackedRemoteBranches(
                branchName: context.preview.branchName,
                syncStatusesByRoot: syncStatusesByBranch[context.preview.branchName] ?? [],
                protectedPatterns: protectedPatterns
            )
            guard let upstream = context.preview.upstream,
                  deletableRemoteBranches.contains(upstream) else { return context }
            return BranchDeleteRecoveryContext(
                repo: context.repo,
                preview: context.preview,
                rootPath: context.rootPath,
                trackedRemoteBranch: upstream
            )
        }
        let completedFailures = failures + (cancelled ? ["Operation cancelled."] : [])
        let completedForceDeleted = forceDeleted
        await MainActor.run {
            self.multiRootRunning = false
            self.multiRootResults = completedResults
            self.loadMultiRoots()
            guard !completedRecoveryContexts.isEmpty else {
                if completedFailures.isEmpty {
                    self.feedbackCenter.success(
                        "Selected branch deletion completed",
                        detail: "\(completedResults.filter(\.success).count) branches"
                    )
                } else {
                    self.toolWindowMode = .operations
                    self.toolWindowExpanded = true
                    self.feedbackCenter.warning(
                        "Selected branch deletion partially completed",
                        detail: completedFailures.joined(separator: "\n"),
                        nextStep: "Review the failed branch or remote deletions and retry them individually."
                    )
                }
                return
            }

            let label = "selected branches"
            self.multiRootBranchDeleteRecovery = MultiRootBranchDeleteRecoveryContext(
                branchName: label,
                contexts: completedRecoveryContexts
            )
            if completedFailures.isEmpty {
                let forceDetail = completedForceDeleted.isEmpty
                    ? "\(completedResults.filter(\.success).count) branches"
                    : "\(completedResults.filter(\.success).count) branches · force deleted: \(completedForceDeleted.joined(separator: ", "))"
                self.feedbackCenter.success(
                    "Selected branch deletion completed",
                    detail: forceDetail,
                    additionalActions: self.branchDeleteRecoveryActions(
                        contexts: completedRecoveryContexts
                    ),
                    notificationID: self.branchDeleteNotificationID(),
                    notificationGroup: .standard
                )
            } else {
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                self.feedbackCenter.warning(
                    "Selected branch deletion partially completed",
                    detail: completedFailures.joined(separator: "\n"),
                    nextStep: "Rollback the successful deletions or keep the partial result.",
                    additionalActions: self.branchDeleteRecoveryActions(
                        contexts: completedRecoveryContexts
                    ),
                    notificationID: self.branchDeleteNotificationID(),
                    notificationGroup: .standard
                )
                self.presentMultiRootBranchDeleteRollback(
                    branchName: label,
                    contexts: completedRecoveryContexts,
                    failures: completedFailures
                )
            }
        }
    }
}

/// IntelliJ's multi-ref delete action includes tags alongside branches. Keep
/// the tag batch root-qualified and reuse the existing restore/remote-delete
/// recovery surface instead of treating tag deletion as an irreversible
/// branch-only operation.
private func deleteSelectedTagsInRoots(_ targets: [BranchDashboardReference]) {
    let selected = targets
        .filter { $0.kind == .tag && !$0.isCurrent }
        .sorted {
            if $0.rootPath == $1.rootPath { return $0.name < $1.name }
            return $0.rootPath < $1.rootPath
        }
    guard !selected.isEmpty, !multiRootRunning else { return }

    let alert = NSAlert()
    alert.messageText = "Delete selected tags?"
    alert.informativeText = selected
        .map { "\($0.name) · \($0.rootPath)" }
        .joined(separator: "\n")
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    let displayNames = Dictionary(
        uniqueKeysWithValues: multiRootBranchSnapshots.map { ($0.rootPath, $0.displayName) }
    )
    multiRootRunning = true
    beginFeedbackOperation("Delete selected tags")
    Task.detached(priority: .userInitiated) {
        var results: [RootOperationResult] = []
        var contexts: [TagDeleteRecoveryContext] = []
        var failures: [String] = []

        for target in selected {
            do {
                let rootRepo = try openRepository(path: target.rootPath)
                guard let tag = try rootRepo.tagList().first(where: { $0.name == target.name }) else {
                    throw NSError(
                        domain: "Arbor.TagDelete",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "Tag not found: \(target.name)"]
                    )
                }
                try rootRepo.tagDelete(name: target.name)
                contexts.append(
                    TagDeleteRecoveryContext(
                        repo: rootRepo,
                        tag: tag,
                        rootPath: target.rootPath
                    )
                )
                results.append(
                    RootOperationResult(
                        rootPath: target.rootPath,
                        displayName: displayNames[target.rootPath] ?? target.rootPath,
                        success: true,
                        skipped: false,
                        message: "Deleted tag \(target.name)"
                    )
                )
            } catch {
                let detail = "\(target.name) · \(target.rootPath): \(errorMessage(error))"
                failures.append(detail)
                results.append(
                    RootOperationResult(
                        rootPath: target.rootPath,
                        displayName: displayNames[target.rootPath] ?? target.rootPath,
                        success: false,
                        skipped: false,
                        message: detail
                    )
                )
            }
        }

        let completedResults = results
        let completedContexts = contexts
        let completedFailures = failures
        await MainActor.run {
            self.multiRootRunning = false
            self.multiRootResults = completedResults
            self.loadMultiRoots()
            if !completedContexts.isEmpty {
                self.multiRootTagDeleteRecovery = MultiRootTagDeleteRecoveryContext(
                    tagName: "selected tags",
                    contexts: completedContexts
                )
            }
            if completedFailures.isEmpty {
                self.feedbackCenter.success(
                    "Selected tag deletion completed",
                    detail: "\(completedContexts.count) tags"
                )
            } else {
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                self.feedbackCenter.warning(
                    "Selected tag deletion partially completed",
                    detail: completedFailures.joined(separator: "\n"),
                    nextStep: completedContexts.isEmpty
                        ? "Review the failed tags and retry them individually."
                        : "Use Restore All if you need to recover the deleted tags."
                )
            }
        }
    }
}

struct MultiRootRemoteBranchDeleteGroup: Equatable, Sendable {
    let remoteBranch: String
    let rootPaths: [String]
}

nonisolated static func multiRootRemoteBranchDeleteGroups(
    _ targets: [BranchDashboardReference]
) -> [MultiRootRemoteBranchDeleteGroup] {
    let groupedTargets = Dictionary(grouping: targets, by: \.name)
    return groupedTargets
        .keys
        .sorted()
        .compactMap { remoteBranch in
            guard let branchTargets = groupedTargets[remoteBranch] else {
                return nil
            }
            return MultiRootRemoteBranchDeleteGroup(
                remoteBranch: remoteBranch,
                rootPaths: Array(Set(branchTargets.map(\.rootPath))).sorted()
            )
        }
}

/// IntelliJ's multi-ref DeleteBranchAction also accepts remote branch refs.
/// Keep each remote ref tied to its owning root, ask once whether common local
/// tracking branches should follow, and only perform that local cleanup after
/// every selected root for the same remote branch succeeded.
func deleteSelectedRemoteBranchesInRoots(_ targets: [BranchDashboardReference]) {
    let selected = targets
        .filter { $0.kind == .remote }
        .sorted {
            if $0.rootPath == $1.rootPath { return $0.name < $1.name }
            return $0.rootPath < $1.rootPath
        }
    guard !selected.isEmpty, !multiRootRunning else { return }
    guard selected.allSatisfy({ !$0.isProtected }) else {
        feedbackCenter.warning(
            "Delete remote branches unavailable",
            detail: "One or more selected remote branches are protected.",
            nextStep: "Remove the protection rule only if deleting these branches is intentional."
        )
        return
    }

    let groups = Self.multiRootRemoteBranchDeleteGroups(selected)
    let commonTrackingBranchesByRemoteBranch = Dictionary(
        uniqueKeysWithValues: groups.map { group in
            (
                group.remoteBranch,
                multiRootCommonTrackingBranches(
                    remoteBranch: group.remoteBranch,
                    snapshots: multiRootBranchSnapshots,
                    selectedRootPaths: Set(group.rootPaths)
                )
            )
        }
    )
    let trackingSummary = groups.flatMap { group in
        (commonTrackingBranchesByRemoteBranch[group.remoteBranch] ?? []).map {
            "\(group.remoteBranch) → \($0)"
        }
    }

    let alert = NSAlert()
    alert.messageText = "Delete selected remote branches?"
    alert.informativeText = selected
        .map { "\($0.name) · \($0.rootPath)" }
        .joined(separator: "\n")
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    var deleteTrackingCheckbox: NSButton?
    if !trackingSummary.isEmpty {
        let checkbox = NSButton(
            checkboxWithTitle: "Also delete common local tracking branches: \(trackingSummary.joined(separator: ", "))",
            target: nil,
            action: nil
        )
        checkbox.state = .off
        alert.accessoryView = checkbox
        deleteTrackingCheckbox = checkbox
    }
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    let deleteTracking = deleteTrackingCheckbox?.state == .on

    let displayNames = Dictionary(
        uniqueKeysWithValues: multiRootBranchSnapshots.map { ($0.rootPath, $0.displayName) }
    )
    let localBranchesByRoot = Dictionary(
        uniqueKeysWithValues: multiRootBranchSnapshots.map { snapshot in
            (
                snapshot.rootPath,
                Set(snapshot.branches.filter { !$0.isCurrent }.map(\.name))
            )
        }
    )
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    multiRootRunning = true
    beginFeedbackOperation("Delete selected remote branches", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        var results: [RootOperationResult] = []
        var failures: [String] = []
        var trackingWarnings: [String] = []
        var recoveryContexts: [BranchDeleteRecoveryContext] = []
        var repositoriesByRoot: [String: Repository] = [:]
        var cancelled = false

        for group in groups {
            let groupTargets = selected.filter {
                $0.name == group.remoteBranch && group.rootPaths.contains($0.rootPath)
            }
            var groupSucceeded = true

            for target in groupTargets {
                guard !cancel.isCancelled() else {
                    cancelled = true
                    groupSucceeded = false
                    results.append(
                        RootOperationResult(
                            rootPath: target.rootPath,
                            displayName: displayNames[target.rootPath] ?? target.rootPath,
                            success: false,
                            skipped: true,
                            message: "Cancelled"
                        )
                    )
                    continue
                }
                do {
                    let rootRepo = try openRepository(path: target.rootPath)
                    try rootRepo.deleteRemoteBranchWithAuthAndCancel(
                        remoteBranch: target.name,
                        broker: broker,
                        cancel: cancel
                    )
                    repositoriesByRoot[target.rootPath] = rootRepo
                    results.append(
                        RootOperationResult(
                            rootPath: target.rootPath,
                            displayName: displayNames[target.rootPath] ?? target.rootPath,
                            success: true,
                            skipped: false,
                            message: "Deleted \(target.name)"
                        )
                    )
                } catch {
                    groupSucceeded = false
                    if cancel.isCancelled() {
                        cancelled = true
                        results.append(
                            RootOperationResult(
                                rootPath: target.rootPath,
                                displayName: displayNames[target.rootPath] ?? target.rootPath,
                                success: false,
                                skipped: true,
                                message: "Cancelled"
                            )
                        )
                    } else {
                        let detail = "\(target.name) · \(target.rootPath): \(friendlyRemoteError(error))"
                        failures.append(detail)
                        results.append(
                            RootOperationResult(
                                rootPath: target.rootPath,
                                displayName: displayNames[target.rootPath] ?? target.rootPath,
                                success: false,
                                skipped: false,
                                message: "\(target.name): \(friendlyRemoteError(error))"
                            )
                        )
                    }
                }
            }

            let commonTrackingBranches = commonTrackingBranchesByRemoteBranch[group.remoteBranch] ?? []
            guard deleteTracking,
                  groupSucceeded,
                  !cancelled,
                  !cancel.isCancelled(),
                  !commonTrackingBranches.isEmpty else {
                continue
            }

            var trackingDeletedByRoot: [String: Int] = [:]
            for localBranch in commonTrackingBranches {
                for rootPath in group.rootPaths {
                    guard !cancel.isCancelled() else {
                        cancelled = true
                        break
                    }
                    guard localBranchesByRoot[rootPath]?.contains(localBranch) == true,
                          let rootRepo = repositoriesByRoot[rootPath] else {
                        continue
                    }
                    do {
                        let preview = try rootRepo.branchDeletePreview(name: localBranch)
                        do {
                            try rootRepo.branchDelete(name: localBranch, force: false)
                        } catch {
                            guard isUnmergedBranchDeletionError(error) else { throw error }
                            try rootRepo.branchDelete(name: localBranch, force: true)
                        }
                        recoveryContexts.append(
                            BranchDeleteRecoveryContext(
                                repo: rootRepo,
                                preview: preview,
                                rootPath: rootPath
                            )
                        )
                        trackingDeletedByRoot[rootPath, default: 0] += 1
                    } catch {
                        let warning = "\(displayNames[rootPath] ?? rootPath): \(localBranch): \(errorMessage(error))"
                        trackingWarnings.append(warning)
                    }
                }
            }

            for index in results.indices where group.rootPaths.contains(results[index].rootPath)
                && results[index].success
                && !results[index].skipped
                && results[index].message == "Deleted \(group.remoteBranch)" {
                let deletedCount = trackingDeletedByRoot[results[index].rootPath, default: 0]
                results[index].message = deletedCount == commonTrackingBranches.count
                    ? "Deleted \(group.remoteBranch) and common local tracking branches"
                    : "Deleted \(group.remoteBranch); local branches kept"
            }
        }

        let completedResults = results
        let completedFailures = failures + trackingWarnings + (cancelled ? ["Operation cancelled."] : [])
        let completedRecoveryContexts = recoveryContexts
        let cancelledToReport = cancelled
        await MainActor.run {
            self.multiRootRunning = false
            self.multiRootResults = completedResults
            self.loadMultiRoots()
            if !completedRecoveryContexts.isEmpty {
                self.multiRootBranchDeleteRecovery = MultiRootBranchDeleteRecoveryContext(
                    branchName: groups.map(\.remoteBranch).joined(separator: ", "),
                    contexts: completedRecoveryContexts
                )
            }
            if completedFailures.isEmpty && !cancelledToReport {
                self.feedbackCenter.success(
                    "Selected remote branch deletion completed",
                    detail: "\(completedResults.filter(\.success).count) branches",
                    additionalActions: self.branchDeleteRecoveryActions(
                        contexts: completedRecoveryContexts
                    ),
                    notificationID: completedRecoveryContexts.isEmpty
                        ? nil
                        : self.branchDeleteNotificationID(),
                    notificationGroup: completedRecoveryContexts.isEmpty ? .toolWindow : .standard
                )
            } else {
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                self.feedbackCenter.warning(
                    cancelledToReport
                        ? "Selected remote branch deletion cancelled"
                        : "Selected remote branch deletion partially completed",
                    detail: completedFailures.joined(separator: "\n"),
                    nextStep: completedRecoveryContexts.isEmpty
                        ? "Review the failed remote deletions and retry them individually."
                        : "Use Restore All if you need to recover the deleted local tracking branches.",
                    additionalActions: self.branchDeleteRecoveryActions(
                        contexts: completedRecoveryContexts
                    ),
                    notificationID: completedRecoveryContexts.isEmpty
                        ? nil
                        : self.branchDeleteNotificationID(),
                    notificationGroup: completedRecoveryContexts.isEmpty ? .toolWindow : .standard
                )
            }
        }
    }
}

func deleteTagInRoot(rootPath: String, name: String) {
    let alert = NSAlert()
    alert.messageText = "Delete tag \(name)?"
    alert.informativeText = "This removes the local tag in the selected root."
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    beginFeedbackOperation("Delete tag")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            guard let tag = try rootRepo.tagList().first(where: { $0.name == name }) else {
                throw NSError(
                    domain: "Arbor.TagDelete",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "Tag not found: \(name)"]
                )
            }
            try rootRepo.tagDelete(name: name)
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.success("Tag deleted", detail: "\(name) · \(rootPath)")
                self.tagDeleteRecovery = TagDeleteRecoveryContext(
                    repo: rootRepo,
                    tag: tag,
                    rootPath: rootPath
                )
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error("Delete tag failed", detail: "\(name) · \(rootPath): \(errorMessage(error))")
            }
        }
    }
}

func presentMultiRootDeleteTagDialog(name: String) {
    let eligible = multiRootBranchSnapshots.filter { snapshot in
        snapshot.tags.contains { $0.name == name }
    }
    guard !eligible.isEmpty else {
        feedbackCenter.warning(
            "Delete tag unavailable",
            detail: "No Git root contains \(name)."
        )
        return
    }
    multiRootDeleteTagName = name
    multiRootDeleteTagSelectedRootPaths = Set(eligible.map(\.rootPath))
    showMultiRootDeleteTagDialog = true
}

func dismissMultiRootDeleteTagDialog() {
    showMultiRootDeleteTagDialog = false
    multiRootDeleteTagName = ""
    multiRootDeleteTagSelectedRootPaths = []
}

/// Delete one local tag from selected Git roots while retaining the exact
/// peeled target for Restore All and the follow-up remote-delete action.
func deleteMultiRootTag(name: String, selectedRootPaths: Set<String>) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    let tagName = name.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !tagName.isEmpty else { return }
    let roots = multiRootBranchSnapshots.filter { snapshot in
        selectedRootPaths.contains(snapshot.rootPath)
            && snapshot.tags.contains { $0.name == tagName }
    }
    guard !roots.isEmpty else { return }
    multiRootRunning = true
    beginFeedbackOperation("Multi-root tag deletion")
    Task.detached(priority: .userInitiated) {
        var results: [RootOperationResult] = []
        var contexts: [TagDeleteRecoveryContext] = []
        var failures: [String] = []
        for snapshot in roots {
            do {
                let rootRepo = try openRepository(path: snapshot.rootPath)
                guard let tag = try rootRepo.tagList().first(where: { $0.name == tagName }) else {
                    throw NSError(
                        domain: "Arbor.TagDelete",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "Tag not found: \(tagName)"]
                    )
                }
                try rootRepo.tagDelete(name: tagName)
                contexts.append(
                    TagDeleteRecoveryContext(
                        repo: rootRepo,
                        tag: tag,
                        rootPath: snapshot.rootPath
                    )
                )
                results.append(
                    RootOperationResult(
                        rootPath: snapshot.rootPath,
                        displayName: snapshot.displayName,
                        success: true,
                        skipped: false,
                        message: "Deleted \(tagName)"
                    )
                )
            } catch {
                let detail = "\(snapshot.displayName): \(errorMessage(error))"
                failures.append(detail)
                results.append(
                    RootOperationResult(
                        rootPath: snapshot.rootPath,
                        displayName: snapshot.displayName,
                        success: false,
                        skipped: false,
                        message: errorMessage(error)
                    )
                )
            }
        }
        let resultsToApply = results
        let contextsToOffer = contexts
        let failuresToReport = failures
        await MainActor.run {
            self.multiRootRunning = false
            self.showMultiRootDeleteTagDialog = false
            self.multiRootResults = resultsToApply
            self.loadMultiRoots()
            if !contextsToOffer.isEmpty {
                self.multiRootTagDeleteRecovery = MultiRootTagDeleteRecoveryContext(
                    tagName: tagName,
                    contexts: contextsToOffer
                )
            }
            if failuresToReport.isEmpty {
                self.feedbackCenter.success(
                    "Multi-root tag deletion completed",
                    detail: "\(contextsToOffer.count) repositories · \(tagName)"
                )
            } else {
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                self.feedbackCenter.warning(
                    "Multi-root tag deletion partially completed",
                    detail: failuresToReport.joined(separator: "\n"),
                    nextStep: contextsToOffer.isEmpty
                        ? "Review the affected roots and retry the operation."
                        : "Use Restore All if you need to recover the deleted local tags."
                )
            }
        }
    }
}

func restoreDeletedTags(_ contexts: [TagDeleteRecoveryContext]) {
    guard !contexts.isEmpty else { return }
    multiRootTagDeleteRecovery = nil
    beginFeedbackOperation("Restore multi-root tags")
    Task.detached(priority: .userInitiated) {
        var failures: [String] = []
        var remaining: [TagDeleteRecoveryContext] = []
        for context in contexts {
            do {
                try context.repo.tagCreate(name: context.tag.name, at: context.tag.id)
            } catch {
                failures.append(
                    "\(context.rootPath ?? String(localized: "Repository")): \(errorMessage(error))"
                )
                remaining.append(context)
            }
        }
        let failuresToReport = failures
        let remainingContexts = remaining
        await MainActor.run {
            self.loadMultiRoots()
            if failuresToReport.isEmpty {
                self.feedbackCenter.success(
                    "Multi-root tag restore completed",
                    detail: contexts.first?.tag.name ?? ""
                )
            } else {
                self.multiRootTagDeleteRecovery = remainingContexts.isEmpty
                    ? nil
                    : MultiRootTagDeleteRecoveryContext(
                        tagName: contexts.first?.tag.name ?? "",
                        contexts: remainingContexts
                    )
                self.feedbackCenter.warning(
                    "Multi-root tag restore partially failed",
                    detail: failuresToReport.joined(separator: "\n"),
                    nextStep: "Review the affected roots and retry the remaining restore action."
                )
            }
        }
    }
}

func deleteRemoteTagsFromRecovery(_ contexts: [TagDeleteRecoveryContext]) {
    guard !contexts.isEmpty else { return }
    let remotes: [(TagDeleteRecoveryContext, RemoteInfo)] = contexts.flatMap { context in
        let repositoryRemotes = (try? context.repo.remoteList()) ?? []
        return repositoryRemotes.map { remote in (context, remote) }
    }
    guard !remotes.isEmpty else {
        feedbackCenter.warning("No remotes configured", detail: contexts.first?.tag.name ?? "")
        return
    }
    multiRootTagDeleteRecovery = nil
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Delete multi-root remote tags", cancelHandle: cancel)
    let broker = credentialAuth.broker
    Task.detached(priority: .userInitiated) {
        var deleted: [String] = []
        var missing: [String] = []
        var failures: [String] = []
        var cancelled = false
        for (context, remote) in remotes {
            if cancel.isCancelled() {
                cancelled = true
                break
            }
            do {
                let didDelete = try context.repo.deleteRemoteTagWithAuthLeaseAndCancel(
                    remote: remote.name,
                    tag: context.tag.name,
                    expectedObjectId: context.tag.objectId,
                    broker: broker,
                    cancel: cancel
                )
                let location = "\(context.rootPath ?? String(localized: "Repository")) · \(remote.name)"
                if didDelete {
                    deleted.append(location)
                } else {
                    missing.append(location)
                }
            } catch {
                if cancel.isCancelled() {
                    cancelled = true
                    break
                }
                failures.append(
                    "\(context.rootPath ?? String(localized: "Repository")) · \(remote.name): \(friendlyRemoteError(error))"
                )
            }
        }
        let deletedRemotes = deleted
        let missingRemotes = missing
        let failuresToReport = failures
        let wasCancelled = cancelled
        await MainActor.run {
            if failuresToReport.isEmpty && !wasCancelled {
                self.loadMultiRoots()
                let detail = deletedRemotes.isEmpty
                    ? "Tag was not present on configured remotes"
                    : deletedRemotes.joined(separator: "\n")
                if !missingRemotes.isEmpty && !deletedRemotes.isEmpty {
                    self.feedbackCenter.success(
                        "Multi-root remote tag deletion completed",
                        detail: "\(detail)\nAlready absent: \(missingRemotes.joined(separator: ", "))"
                    )
                } else {
                    self.feedbackCenter.success("Multi-root remote tag deletion completed", detail: detail)
                }
            } else if wasCancelled {
                self.multiRootTagDeleteRecovery = MultiRootTagDeleteRecoveryContext(
                    tagName: contexts.first?.tag.name ?? "",
                    contexts: contexts
                )
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                self.feedbackCenter.warning(
                    "Multi-root remote tag deletion canceled",
                    detail: "Deleted \(deletedRemotes.count); already absent \(missingRemotes.count).",
                    nextStep: "Retry the recovery action to process the remaining remotes."
                )
            } else {
                self.multiRootTagDeleteRecovery = MultiRootTagDeleteRecoveryContext(
                    tagName: contexts.first?.tag.name ?? "",
                    contexts: contexts
                )
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                self.feedbackCenter.warning(
                    "Multi-root remote tag deletion partially completed",
                    detail: failuresToReport.joined(separator: "\n"),
                    nextStep: "Review the failed remotes and retry the action."
                )
            }
        }
    }
}

func renameTagInRoot(rootPath: String, name: String) {
    let alert = NSAlert()
    alert.messageText = "Rename Tag"
    let field = NSTextField(string: name)
    field.frame = NSRect(x: 0, y: 0, width: 300, height: 24)
    alert.accessoryView = field
    alert.addButton(withTitle: "Rename")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    let newName = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !newName.isEmpty, newName != name else { return }
    beginFeedbackOperation("Rename tag")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            try rootRepo.tagRename(old: name, new: newName)
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.success("Tag renamed", detail: "\(name) → \(newName) · \(rootPath)")
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error("Rename tag failed", detail: "\(name) · \(rootPath): \(errorMessage(error))")
            }
        }
    }
}

func pushTagInRoot(rootPath: String, name: String, remote selectedRemote: String? = nil) {
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Push tag", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let remoteNames = try rootRepo.remoteList().map(\.name)
            guard let remote = resolveSelectedRemoteName(
                selectedRemote: selectedRemote,
                availableRemoteNames: remoteNames
            ) else {
                throw NSError(
                    domain: "Arbor.PushTags",
                    code: 2,
                    userInfo: [
                        NSLocalizedDescriptionKey: selectedRemote == nil
                            ? "Multiple remotes are configured; choose a remote before pushing the tag."
                            : "The selected remote is no longer configured."
                    ]
                )
            }
            try rootRepo.tagPushWithAuthAndCancel(
                remote: remote,
                tag: name,
                broker: broker,
                cancel: cancel
            )
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.success("Tag pushed", detail: "\(name) · \(rootPath)")
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error("Push tag failed", detail: "\(name) · \(rootPath): \(friendlyRemoteError(error))")
                if self.isAuthenticationFailure(error) { self.showHostingAuthPrompt = true }
            }
        }
    }
}

/// Push every local tag to the selected root's explicitly selected or only
/// configured remote. This mirrors IntelliJ's Git.Push.Tags action while
/// keeping the operation non-forceful:
/// divergent remote tags are rejected by Git instead of being overwritten.
func pushAllTagsInRoot(rootPath: String, remote selectedRemote: String? = nil) {
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Push all tags", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let remoteNames = try rootRepo.remoteList().map(\.name)
            guard let remote = resolveSelectedRemoteName(
                selectedRemote: selectedRemote,
                availableRemoteNames: remoteNames
            ) else {
                throw NSError(
                    domain: "Arbor.PushTags",
                    code: 1,
                    userInfo: [
                        NSLocalizedDescriptionKey: selectedRemote == nil
                            ? "Multiple remotes are configured; choose a remote before pushing all tags."
                            : "The selected remote is no longer configured."
                    ]
                )
            }
            try rootRepo.pushRefspecWithAuthAndCancel(
                remote: remote,
                refspec: "refs/tags/*:refs/tags/*",
                force: false,
                forceWithLease: false,
                broker: broker,
                cancel: cancel
            )
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.success("All tags pushed", detail: "\(remote) · \(rootPath)")
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error(
                    "Push all tags failed",
                    detail: "\(rootPath): \(friendlyRemoteError(error))",
                    nextStep: "Check the remote and tag names, then retry."
                )
            }
        }
    }
}

private func presentMultiRootStashConflict(
    rootPath: String,
    index: Int? = nil,
    stashID: String? = nil,
    isPop: Bool,
    paths: [String],
    additionalActions: [FeedbackAction] = []
) {
    guard (try? openRepository(path: rootPath)) != nil else {
        feedbackCenter.error(
            "Stash conflict unavailable",
            detail: "Could not reopen \(rootPath) to load the conflict workbench."
        )
        return
    }
    let resolvedIndex: Int = {
        guard let stashID,
              let rootRepo = try? openRepository(path: rootPath),
              let stashes = try? rootRepo.stashList(),
              let index = stashes.firstIndex(where: { $0.id == stashID }) else {
            return index ?? 0
        }
        return index
    }()
    multiRootStashConflicts[rootPath] = paths
    multiRootStashConflictIndexes[rootPath] = resolvedIndex
    multiRootStashConflictIDs[rootPath] = stashID
    multiRootStashConflictPopModes[rootPath] = isPop
    feedbackCenter.error(
        isPop ? "Stash pop paused" : "Stash apply paused",
        detail: "\(rootPath): \(paths.joined(separator: ", "))",
        nextStep: "Resolve every file in the project conflict workbench, then complete the restore.",
        additionalActions: additionalActions
    )
    openMultiRootConflictResolver(preferredRootPath: rootPath)
}

private func clearStashDiffIfMatching(rootPath: String, stashID: String) {
    guard stashDiffRootPath == rootPath, stashDiffStashID == stashID else { return }
    showStashDiff = false
    stashDiffText = nil
    stashDiffStashID = nil
    stashDiffRootPath = nil
}

private func presentMultiRootShelveConflict(
    rootPath: String,
    name: String,
    paths: [String],
    additionalActions: [FeedbackAction] = []
) {
    feedbackCenter.warning(
        "Shelve pop paused",
        detail: "\(rootPath) · \(name): \(paths.joined(separator: ", "))",
        nextStep: "Resolve every file in the project conflict workbench, then complete the Shelf restore.",
        additionalActions: additionalActions
    )
    openMultiRootConflictResolver(preferredRootPath: rootPath)
}

func openMultiRootStashConflict(rootPath: String) {
    guard multiRootStashConflicts[rootPath] != nil else { return }
    // The unified resolver re-reads status before presenting the root.
    openMultiRootConflictResolver(preferredRootPath: rootPath)
}

func applyStashInRoot(rootPath: String, stashID: String, restoreIndex: Bool) {
    beginFeedbackOperation("Apply stash")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let currentIndex = try currentStashIndex(repo: rootRepo, stashID: stashID)
            try rootRepo.stashApplyWithIndex(index: currentIndex, restoreIndex: restoreIndex)
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.success("Stash applied; stash kept", detail: "\(rootPath) · \(String(stashID.prefix(7)))")
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                if case let .StashApplyConflict(paths, conflictStashID) = error as? EngineError {
                    self.presentMultiRootStashConflict(
                        rootPath: rootPath,
                        stashID: conflictStashID ?? stashID,
                        isPop: false,
                        paths: paths
                    )
                } else {
                    self.feedbackCenter.error(
                        "Apply stash failed",
                        detail: "\(rootPath) · \(String(stashID.prefix(7))): \(errorMessage(error))",
                        nextStep: "Resolve the root-specific conflict before retrying."
                    )
                }
            }
        }
    }
}

func popStashInRoot(rootPath: String, stashID: String, restoreIndex: Bool) {
    beginFeedbackOperation("Pop stash")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let currentIndex = try currentStashIndex(repo: rootRepo, stashID: stashID)
            try rootRepo.stashPopWithIndex(index: currentIndex, restoreIndex: restoreIndex)
            await MainActor.run {
                self.loadMultiRoots()
                self.clearStashDiffIfMatching(rootPath: rootPath, stashID: stashID)
                self.feedbackCenter.success("Stash popped", detail: "\(rootPath) · \(String(stashID.prefix(7)))")
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                if case let .StashApplyConflict(paths, conflictStashID) = error as? EngineError {
                    self.presentMultiRootStashConflict(
                        rootPath: rootPath,
                        stashID: conflictStashID ?? stashID,
                        isPop: true,
                        paths: paths
                    )
                } else {
                    self.feedbackCenter.error(
                        "Pop stash failed",
                        detail: "\(rootPath) · \(String(stashID.prefix(7))): \(errorMessage(error))",
                        nextStep: "Resolve the root-specific conflict; the stash is retained when Git cannot pop it."
                    )
                }
            }
        }
    }
}

func dropStashInRoot(rootPath: String, stashID: String) {
    let alert = NSAlert()
    alert.messageText = "Drop selected stash?"
    alert.informativeText = "This permanently removes the selected stash from the root."
    alert.addButton(withTitle: "Drop")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    dropStashInRootConfirmed(rootPath: rootPath, stashID: stashID)
}

/// Execute a root-scoped stash drop after the caller has already confirmed
/// the destructive action in its own UI surface.
func dropStashInRootConfirmed(rootPath: String, stashID: String) {
    beginFeedbackOperation("Drop stash")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let currentIndex = try currentStashIndex(repo: rootRepo, stashID: stashID)
            try rootRepo.stashDrop(index: currentIndex)
            await MainActor.run {
                self.loadMultiRoots()
                self.refreshUnstashRootIfVisible(rootPath)
                self.clearStashDiffIfMatching(rootPath: rootPath, stashID: stashID)
                self.feedbackCenter.success("Stash dropped", detail: "\(rootPath) · \(String(stashID.prefix(7)))")
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error("Drop stash failed", detail: "\(rootPath) · \(String(stashID.prefix(7))): \(errorMessage(error))")
            }
        }
    }
}

func stashBranchInRoot(rootPath: String, stashID: String) {
    let alert = NSAlert()
    alert.messageText = "Create branch from stash"
    alert.informativeText = "The new branch will be checked out in the selected root and the stash will be applied."
    let field = NSTextField(string: "stash-branch")
    field.frame = NSRect(x: 0, y: 0, width: 300, height: 24)
    alert.accessoryView = field
    alert.addButton(withTitle: "Create")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    let branch = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !branch.isEmpty else { return }
    stashBranchInRoot(rootPath: rootPath, stashID: stashID, branch: branch)
}

private func stashBranchNotificationComponent(_ value: String) -> String {
    value
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
        .replacingOccurrences(of: "|", with: "_")
        .replacingOccurrences(of: " ", with: "_")
}

private func stashBranchNotificationID(rootPath: String, branch: String) -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    return [
        "git.stash.branch",
        stashBranchNotificationComponent(URL(fileURLWithPath: projectPath).standardizedFileURL.path),
        stashBranchNotificationComponent(URL(fileURLWithPath: rootPath).standardizedFileURL.path),
        stashBranchNotificationComponent(branch)
    ].joined(separator: ".")
}

private func stashBranchRetryRequest(
    _ retry: PersistedStashBranchRetry,
    rootPath: String
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .retryStashBranch,
        projectPath: projectPath,
        rootPath: rootPath,
        shelfName: "",
        stashBranchRetry: retry
    )
}

nonisolated private func stashBranchRetryIsCurrentlySafe(
    _ retry: PersistedStashBranchRetry,
    rootPath: String
) -> Bool {
    guard let rootRepo = try? openRepository(path: rootPath),
          let branches = try? rootRepo.branchList(),
          let stashes = try? rootRepo.stashList() else {
        return false
    }
    return stashBranchRetryStateIsSafe(
        retry,
        currentBranch: branches.first(where: { $0.isCurrent })?.name,
        currentHead: rootRepo.headCommitId(),
        stashIDs: stashes.map(\.id),
        localBranches: branches.map(\.name)
    )
}

private func stashBranchRetryFeedbackAction(
    _ retry: PersistedStashBranchRetry,
    rootPath: String
) -> FeedbackAction {
    let request = stashBranchRetryRequest(retry, rootPath: rootPath)
    return FeedbackAction(
        id: "retry-stash-branch:\(rootPath):\(retry.stashID):\(retry.branch)",
        title: "Retry Create Branch from Stash",
        semanticAction: request
    ) {
        self.handleVCSActionRequest(request)
    }
}

private func retryStashBranch(
    rootPath: String,
    retry: PersistedStashBranchRetry
) {
    let notificationID = stashBranchNotificationID(rootPath: rootPath, branch: retry.branch)
    beginFeedbackOperation("Create branch from stash", notificationID: notificationID)
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let stashes = try rootRepo.stashList()
            let branchNames = try rootRepo.branchList().map(\.name)
            guard stashBranchRetryStateIsSafe(
                retry,
                currentBranch: try rootRepo.branchList().first(where: { $0.isCurrent })?.name,
                currentHead: rootRepo.headCommitId(),
                stashIDs: stashes.map(\.id),
                localBranches: branchNames
            ) else {
                throw NSError(
                    domain: "Arbor.StashBranch",
                    code: 2,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "The repository changed after the failed stash branch operation; retry was refused."
                    ]
                )
            }
            try rootRepo.stashBranch(
                index: try currentStashIndex(repo: rootRepo, stashID: retry.stashID),
                branch: retry.branch
            )
            await MainActor.run {
                self.loadMultiRoots()
                self.refreshUnstashRootIfVisible(rootPath)
                self.clearStashDiffIfMatching(rootPath: rootPath, stashID: retry.stashID)
                self.feedbackCenter.success(
                    "Branch created from stash",
                    detail: "\(retry.branch) · \(rootPath)",
                    notificationID: notificationID
                )
            }
        } catch {
            let canRetry = stashBranchRetryIsCurrentlySafe(retry, rootPath: rootPath)
            await MainActor.run {
                self.feedbackCenter.error(
                    "Create branch from stash retry failed",
                    detail: "\(rootPath): \(errorMessage(error))",
                    nextStep: "The retry was refused if the original repository state no longer matches; inspect the root before retrying again.",
                    additionalActions: canRetry
                        ? [self.stashBranchRetryFeedbackAction(retry, rootPath: rootPath)]
                        : [],
                    notificationID: notificationID
                )
            }
        }
    }
}

/// Execute Create Branch from Stash after the root-scoped Unstash dialog has
/// already validated and captured the branch name.
func stashBranchInRoot(rootPath: String, stashID: String, branch: String) {
    let notificationID = stashBranchNotificationID(rootPath: rootPath, branch: branch)
    beginFeedbackOperation("Create branch from stash", notificationID: notificationID)
    Task.detached(priority: .userInitiated) {
        var retry: PersistedStashBranchRetry?
        do {
            let rootRepo = try openRepository(path: rootPath)
            let stashes = try rootRepo.stashList()
            guard stashes.contains(where: { $0.id == stashID }) else {
                throw NSError(
                    domain: "Arbor.StashBranch",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "The selected stash no longer exists."]
                )
            }
            retry = PersistedStashBranchRetry(
                stashID: stashID,
                branch: branch,
                expectedCurrentBranch: try rootRepo.branchList().first(where: { $0.isCurrent })?.name,
                expectedCurrentHead: rootRepo.headCommitId()
            )
            let currentIndex = try currentStashIndex(repo: rootRepo, stashID: stashID)
            try rootRepo.stashBranch(index: currentIndex, branch: branch)
            await MainActor.run {
                self.loadMultiRoots()
                self.clearStashDiffIfMatching(rootPath: rootPath, stashID: stashID)
                self.feedbackCenter.success(
                    "Branch created from stash",
                    detail: "\(branch) · \(rootPath)",
                    notificationID: notificationID
                )
            }
        } catch {
            let retryContext = retry
            let canRetry = retryContext.map {
                stashBranchRetryIsCurrentlySafe($0, rootPath: rootPath)
            } ?? false
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error(
                    "Create branch from stash failed",
                    detail: "\(rootPath): \(errorMessage(error))",
                    nextStep: "The stash is kept when Git cannot complete the branch operation. Retry only if the original repository state is unchanged.",
                    additionalActions: canRetry
                        ? (retryContext.map {
                            [self.stashBranchRetryFeedbackAction($0, rootPath: rootPath)]
                        } ?? [])
                        : [],
                    notificationID: notificationID
                )
            }
        }
    }
}

func showStashDiffInRoot(rootPath: String, stashID: String) {
    stashDiffStashID = stashID
    stashDiffRootPath = rootPath
    stashDiffText = nil
    showStashDiff = false
    beginFeedbackOperation("Load stash diff")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let currentIndex = try currentStashIndex(repo: rootRepo, stashID: stashID)
            let diff = try rootRepo.stashDiff(index: currentIndex)
            await MainActor.run {
                guard self.stashDiffStashID == stashID,
                      self.stashDiffRootPath == rootPath else { return }
                self.stashDiffText = diff
                self.showStashDiff = true
                self.feedbackCenter.success("Stash diff loaded", detail: "\(rootPath) · \(String(stashID.prefix(7)))")
            }
        } catch {
            await MainActor.run {
                guard self.stashDiffStashID == stashID,
                      self.stashDiffRootPath == rootPath else { return }
                self.feedbackCenter.error("Load stash diff failed", detail: "\(rootPath): \(errorMessage(error))")
            }
        }
    }
}

func clearStashesInRoot(rootPath: String) {
    let repositoryName = URL(fileURLWithPath: rootPath).lastPathComponent
    let confirmation = stashClearConfirmation(repositoryName: repositoryName)
    let alert = NSAlert()
    alert.messageText = confirmation.title
    alert.informativeText = confirmation.message
    alert.addButton(withTitle: confirmation.confirmTitle)
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    clearStashesInRootConfirmed(rootPath: rootPath)
}

/// Execute a root-scoped stash clear after the caller has already confirmed
/// the destructive action in its own UI surface.
func clearStashesInRootConfirmed(rootPath: String) {
    beginFeedbackOperation("Clear stashes")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            try rootRepo.stashClear()
            await MainActor.run {
                self.loadMultiRoots()
                self.refreshUnstashRootIfVisible(rootPath)
                if self.stashDiffRootPath == rootPath {
                    self.showStashDiff = false
                    self.stashDiffText = nil
                    self.stashDiffStashID = nil
                    self.stashDiffRootPath = nil
                }
                self.feedbackCenter.success("Stashes cleared", detail: rootPath)
            }
        } catch {
            await MainActor.run {
                self.loadMultiRoots()
                self.feedbackCenter.error("Clear stashes failed", detail: "\(rootPath): \(errorMessage(error))")
            }
        }
    }
}

/// Remote branch without a local tracking branch: fetch it only; never merge it into HEAD.
func fetchRemoteBranch(_ branch: RemoteBranchInfo) {
    guard let repo else { return }
    let cancel = GitCancelHandle()
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    beginFeedbackOperation("Fetch remote branch", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let outcome = try repo.fetchRemoteBranchWithOptionsAndAuthAndCancel(
                remote: branch.remote,
                branch: branch.name,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel
            )
            let detail = outcome.updated.isEmpty ? "No updates" : outcome.updated.joined(separator: ", ")
            await MainActor.run {
                self.feedbackCenter.success("Remote branch fetched", detail: "\(branch.name) · \(detail)")
                self.loadRepoData()
                self.synchronizeRemoteProtectedBranchPatterns()
            }
        } catch {
            await MainActor.run {
                let detail = friendlyRemoteError(error)
                self.feedbackCenter.error(
                    "Fetch remote branch failed",
                    detail: "\(branch.name): \(detail)",
                    nextStep: "Check the remote and credentials, then retry."
                )
                if self.isAuthenticationFailure(error) { self.showHostingAuthPrompt = true }
            }
        }
    }
}

func checkoutRemoteBranch(_ branch: RemoteBranchInfo) {
    guard let repo else { return }
    beginFeedbackOperation("Checkout remote branch")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.checkoutRemoteBranch(remoteBranch: branch.name, localName: nil)
            await MainActor.run {
                self.feedbackCenter.success("Remote branch checked out", detail: branch.name)
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            let detail = errorMessage(error)
            await MainActor.run {
                self.presentCheckoutRecovery(
                    repo: repo,
                    name: branch.name,
                    detail: detail,
                    onSmart: { self.smartCheckoutRemoteBranch(repo: repo, remoteBranch: branch.name) },
                    onForce: { self.forceCheckoutRemoteBranch(repo: repo, remoteBranch: branch.name) }
                )
            }
        }
    }
}

func deleteRemoteBranch(_ branch: RemoteBranchInfo) {
    guard let repo else { return }
    let alert = NSAlert()
    alert.messageText = "Delete remote branch?"
    alert.informativeText = "This will delete \(branch.name) from the remote repository."
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")
    let currentLocalBranches = Set(branches.filter(\.isCurrent).map(\.name))
    let trackingLocalBranches = syncStatuses
        .filter {
            $0.upstream == branch.name
                && $0.trackingExists
                && !currentLocalBranches.contains($0.branch)
        }
        .map(\.branch)
        .sorted()
    var deleteTrackingCheckbox: NSButton?
    if !trackingLocalBranches.isEmpty {
        let localBranchesTitle = trackingLocalBranches.count == 1
            ? "Also delete local branch \(trackingLocalBranches[0])"
            : "Also delete local branches: \(trackingLocalBranches.joined(separator: ", "))"
        let checkbox = NSButton(
            checkboxWithTitle: localBranchesTitle,
            target: nil,
            action: nil
        )
        checkbox.state = .off
        alert.accessoryView = checkbox
        deleteTrackingCheckbox = checkbox
    }
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    let deleteTracking = deleteTrackingCheckbox?.state == .on
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Delete remote branch", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            try repo.deleteRemoteBranchWithAuthAndCancel(
                remoteBranch: branch.name,
                broker: broker,
                cancel: cancel
            )
            if cancel.isCancelled() {
                await MainActor.run {
                    self.refreshAll(showFeedback: false)
                    self.loadRepoData()
                    self.feedbackCenter.warning(
                        "Remote branch deletion cancelled",
                        detail: branch.name
                    )
                }
                return
            }
            let localDeletionMessages: [String]
            if deleteTracking {
                localDeletionMessages = trackingLocalBranches.compactMap { localBranchName in
                    do {
                        try repo.branchDelete(name: localBranchName, force: false)
                        return nil
                    } catch {
                        return "\(localBranchName): \(errorMessage(error))"
                    }
                }
            } else {
                localDeletionMessages = []
            }
            await MainActor.run {
                if !localDeletionMessages.isEmpty {
                    self.feedbackCenter.warning(
                        "Remote branch deleted; local branches kept",
                        detail: localDeletionMessages.joined(separator: "\n"),
                        nextStep: "Resolve local changes or delete the local branch separately."
                    )
                } else {
                    self.feedbackCenter.success("Remote branch deleted", detail: branch.name)
                }
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            await MainActor.run {
                self.loadError = errorMessage(error)
                if cancel.isCancelled() {
                    self.feedbackCenter.warning(
                        "Remote branch deletion cancelled",
                        detail: branch.name
                    )
                } else {
                    self.feedbackCenter.error("Delete remote branch failed", detail: friendlyRemoteError(error), nextStep: "Check permissions and the remote name, then retry.")
                }
            }
        }
    }
}

/// 清空整个 stash 栈（等价 git stash clear）。
func stashClearAll() {
    guard let repo else { return }
    let repositoryName = repo.workdir().map {
        URL(fileURLWithPath: $0).lastPathComponent
    } ?? "the current Git root"
    let confirmation = stashClearConfirmation(repositoryName: repositoryName)
    let alert = NSAlert()
    alert.messageText = confirmation.title
    alert.informativeText = confirmation.message
    alert.addButton(withTitle: confirmation.confirmTitle)
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    beginFeedbackOperation("Clear stashes")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.stashClear()
            let ss = try repo.stashList()
            await MainActor.run {
                self.stashes = ss
                self.showStashDiff = false
                self.stashDiffText = nil
                self.stashDiffStashID = nil
                self.stashDiffRootPath = nil
                self.stashPreviewStashID = nil
                self.stashPreviewText = nil
                self.showStashPreview = false
                self.feedbackCenter.success("Stashes cleared")
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Clear stashes failed", detail: errorMessage(error), nextStep: "stash 栈未变，可重试。")
            }
        }
    }
}

func presentStashDialog() {
    guard let rootPath = repo?.workdir() ?? multiRoots.first?.path else { return }
    stashRootPath = rootPath
    stashCurrentBranch = currentBranchName
    stashRootLoading = false
    stashMessage = ""
    stashKeepIndex = false
    showStashDialog = true
    selectStashRoot(rootPath)
    loadMultiRoots()
}

/// Load the branch label for the root selected in the IntelliJ-style Stash
/// dialog. The stash operation itself opens the same selected root again so a
/// secondary root can never fall back to the primary repository.
func selectStashRoot(_ rootPath: String) {
    stashRootPath = rootPath
    stashCurrentBranch = multiRootBranchSnapshots.first(where: { $0.rootPath == rootPath })?.headBranch ?? ""
    stashRootLoading = true
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let branch = (try? rootRepo.branchList())?.first(where: { $0.isCurrent })?.name ?? ""
            await MainActor.run {
                guard self.showStashDialog, self.stashRootPath == rootPath else { return }
                self.stashCurrentBranch = branch
                self.stashRootLoading = false
            }
        } catch {
            await MainActor.run {
                guard self.showStashDialog, self.stashRootPath == rootPath else { return }
                self.stashCurrentBranch = ""
                self.stashRootLoading = false
                self.feedbackCenter.error(
                    "Load Git root failed",
                    detail: errorMessage(error),
                    nextStep: "Check the selected Git root and retry."
                )
            }
        }
    }
}

func stashSave(rootPath requestedRootPath: String? = nil) {
    let targetRootPath = requestedRootPath ?? repo?.workdir()
    guard let targetRootPath, !targetRootPath.isEmpty else { return }
    beginFeedbackOperation("Stash changes")
    let msg = stashMessage.trimmingCharacters(in: .whitespaces)
    let keepIndex = stashKeepIndex
    let currentRootPath = repo?.workdir().map(canonicalExternalLogPath)
    let targetRootKey = canonicalExternalLogPath(targetRootPath)
    Task.detached(priority: .userInitiated) {
        do {
            let targetRepo = try openRepository(path: targetRootPath)
            if keepIndex {
                _ = try targetRepo.stashSaveWithKeepIndex(message: msg.isEmpty ? nil : msg)
            } else {
                _ = try targetRepo.stashSave(message: msg.isEmpty ? nil : msg)
            }
            let ss = try targetRepo.stashList()
            let st = try targetRepo.status()
            let staging = try? targetRepo.stagingModel()
            await MainActor.run {
                if currentRootPath == targetRootKey {
                    self.stashes = ss
                    self.entries = st
                    self.stashPreviewStashID = nil
                    self.stashPreviewText = nil
                    self.showStashPreview = false
                    self.stagingModel = staging
                    self.lastIndexRevision = staging?.indexRevision
                }
                self.stashMessage = ""
                self.stashKeepIndex = false
                self.feedbackCenter.success("Changes stashed")
                if currentRootPath == targetRootKey {
                    self.loadRepoData(includeComparisons: false)
                }
                self.loadMultiRoots()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Stash changes failed",
                    detail: errorMessage(error),
                    nextStep: "No stash was created if Git rejected the operation; check the selected root and retry."
                )
            }
        }
    }
}

/// 打开 IntelliJ Git 风格的 Stash Files 对话框。右键触发的路径默认选中，
/// 用户可以在提交前继续扩大或缩小选区。
func showStashFiles(paths: [String]) {
    stashFilesInitialPaths = Set(paths)
    stashFilesMessage = ""
    showStashFilesDialog = true
}

/// Open the single-stash variant of IntelliJ's Git.Stash.UnstashAs action.
/// The stash ID is retained instead of its stack index because another refresh
/// can reorder the stash list while the dialog is open.
func presentUnstashAsDialog(stashID: String) {
    guard stashes.contains(where: { $0.id == stashID }) else { return }
    unstashAsStashID = stashID
    showUnstashAsDialog = true
}

/// Open the repository-level Unstash dialog with the currently active root.
/// Multi-root projects receive their root chooser as soon as discovery has
/// refreshed `multiRoots`; the initial list still comes from the visible root
/// so the dialog is immediately useful while discovery is in flight.
func presentUnstashDialog() {
    guard let rootPath = repo?.workdir() else { return }
    unstashRootPath = rootPath
    unstashStashes = stashes
    unstashCurrentBranch = currentBranchName
    unstashRootLoading = false
    showUnstashDialog = true
    loadMultiRoots()
}

/// Load stash data for the root selected in the IntelliJ-style Unstash root
/// chooser. The generation guard is the selected path itself: a slower root
/// cannot overwrite a newer selection after the user switches repositories.
func selectUnstashRoot(_ rootPath: String) {
    unstashRootPath = rootPath
    unstashStashes = []
    unstashCurrentBranch = multiRootBranchSnapshots.first(where: { $0.rootPath == rootPath })?.headBranch ?? ""
    unstashRootLoading = true
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let loadedStashes = try rootRepo.stashList()
            let loadedBranch = (try? rootRepo.branchList())?.first(where: { $0.isCurrent })?.name ?? ""
            await MainActor.run {
                guard self.showUnstashDialog, self.unstashRootPath == rootPath else { return }
                self.unstashStashes = loadedStashes
                self.unstashCurrentBranch = loadedBranch
                self.unstashRootLoading = false
            }
        } catch {
            await MainActor.run {
                guard self.showUnstashDialog, self.unstashRootPath == rootPath else { return }
                self.unstashStashes = []
                self.unstashRootLoading = false
                self.feedbackCenter.error(
                    "Load stashes failed",
                    detail: "(rootPath): (errorMessage(error))",
                    nextStep: "Check the selected Git root and retry."
                )
            }
        }
    }
}

private func refreshUnstashRootIfVisible(_ rootPath: String) {
    guard showUnstashDialog, unstashRootPath == rootPath else { return }
    selectUnstashRoot(rootPath)
}

