        do {
            let diff = try repo.stashDiff(
                index: try currentStashIndex(repo: repo, stashID: stashID)
            )
            await MainActor.run {
                guard self.showStashPreview, self.stashPreviewStashID == stashID else { return }
                self.stashPreviewText = diff
            }
        } catch {
