/// Import one or more portable unified/binary patches into the active Shelf.
/// The panel is intentionally kept as a small AppKit boundary; the engine
/// owns patch validation and isolated-index construction.
func applyPatchFromFile() {
    guard repo != nil else { return }
    let panel = NSOpenPanel()
    panel.canChooseFiles = true
    panel.canChooseDirectories = false
    panel.allowsMultipleSelection = false
    panel.canCreateDirectories = false
    panel.prompt = "Apply Patch"
    guard panel.runModal() == .OK, let url = panel.url else { return }

    do {
        let patch = try String(contentsOf: url, encoding: .utf8)
        presentApplyPatchRequest(fileName: url.lastPathComponent, patch: patch)
    } catch {
        feedbackCenter.error(
            "Patch apply failed",
            detail: errorMessage(error),
            nextStep: "Choose a UTF-8 unified or Git patch and try again."
        )
    }
}

/// Mirrors IntelliJ's ApplyPatchFromClipboardAction. Clipboard content enters
/// the same differentiated preview and conflict-recovery flow as a patch file;
/// it is never applied directly without path/hunk review.
func applyPatchFromClipboard() {
    guard repo != nil else { return }
    guard let patch = NSPasteboard.general.string(forType: .string),
          !patch.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        feedbackCenter.error(
            "Patch apply failed",
            detail: "The clipboard does not contain text.",
            nextStep: "Copy a unified or Git patch and try again."
        )
        return
    }
    presentApplyPatchRequest(fileName: "Clipboard Patch", patch: patch)
}

private func presentApplyPatchRequest(fileName: String, patch: String) {
    let files = RebasedUnshelveDialog.parsePatchFiles(patch, allowedPaths: [])
    let paths = files.map(\.path)
    guard !paths.isEmpty else {
        feedbackCenter.error(
            "Patch apply failed",
            detail: "The source does not contain a supported unified or Git patch.",
            nextStep: "Choose a valid patch source and try again."
        )
        return
    }
    pendingApplyPatch = RebasedApplyPatchRequest(
        fileName: fileName,
        patch: patch,
        paths: paths
    )
}

/// Apply a reviewed patch directly. This is the platform ApplyPatchAction
/// path: the patch is never inserted into the user's Shelf list, while its
/// conflict snapshot still uses the same restart-safe resolver lifecycle.
func applyImportedPatch(
    fileName: String,
    patch: String,
    paths: [String],
    selections: [ShelvePatchSelection],
    targetName: String?,
    basePath: String?,
    pathStrip: UInt32
) {
    guard let repo, !paths.isEmpty else { return }
    let operationName = "Apply Patch: \(fileName)"
    let mappedBasePath = basePath?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    let trimmedTargetName = targetName?.trimmingCharacters(in: .whitespacesAndNewlines)
    let mappedTargetName = trimmedTargetName?.isEmpty == true ? nil : trimmedTargetName
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Apply patch", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            if let targetName = mappedTargetName,
               !(try repo.changelistList().contains(where: { $0.name == targetName })) {
                throw EngineError.GitOperation(message: "Target Changelist not found: \(targetName)")
            }
            let applyResult = try repo.applyImportedPatchDifferentiatedWithCancel(
                name: operationName,
                patch: patch,
                paths: paths,
                selections: selections,
                basePath: mappedBasePath,
                pathStrip: pathStrip,
                cancel: cancel
            )
            let appliedPaths = applyResult.appliedPaths
            let failedPaths = applyResult.failedPaths

            let status = try repo.status()
            let currentPaths = Set(status.map(\.path))
            let assignablePaths = appliedPaths.filter(currentPaths.contains)
            if let targetName = mappedTargetName {
                if !assignablePaths.isEmpty {
                    try repo.changelistMovePaths(paths: assignablePaths, targetName: targetName)
                }
            }
            await MainActor.run {
                self.entries = status
                self.changeLists = (try? repo.changelistList()) ?? self.changeLists
                self.refreshAfterShelfMutation(
                    repo: repo,
                    paths: appliedPaths
                )
                if applyResult.overallStatus == .abort {
                    self.feedbackCenter.warning(
                        "Patch apply aborted",
                        detail: "(fileName): no patch members were kept",
                        nextStep: "Retry Apply Patch when ready. The original worktree and index were restored."
                    )
                } else if !patchApplyNeedsAttention(applyResult) {
                    self.feedbackCenter.success(
                        "Patch applied",
                        detail: mappedTargetName.map { "\(fileName) → \($0)" } ?? fileName
                    )
                } else {
                    let targetDetail = mappedTargetName.map { " → \($0)" } ?? ""
                    self.feedbackCenter.warning(
                        "Patch partially applied",
                        detail: "\(fileName)\(targetDetail): \(patchApplySummary(applyResult, successDetail: "Applied", failureDetail: "Not applied"))\(failedPaths.isEmpty ? "" : " (\(failedPaths.joined(separator: ", ")))")",
                        nextStep: "Review the failed files and apply those patch members separately."
                    )
                }
            }
        } catch {
            if case let .ShelveApplyConflict(conflictName, conflictPaths) = error as? EngineError {
                let restoreInfo = (try? repo.shelveRestoreInfo()) ?? nil
                let patchText = restoreInfo?.patch ?? patch
                if let targetName = mappedTargetName {
                    _ = try? repo.shelveSetRestoreTarget(
                        name: conflictName,
                        targetChangeList: targetName
                    )
                }
                await MainActor.run {
                    self.presentShelveConflict(
                        name: conflictName,
                        paths: conflictPaths,
                        isPop: false,
                        changeListName: mappedTargetName,
                        isDirectPatch: true,
                        patchText: patchText
                    )
                }
            } else if let engineError = error as? EngineError, case .Cancelled = engineError {
                await MainActor.run {
                    self.feedbackCenter.warning(
                        "Patch apply canceled",
                        detail: fileName,
                        nextStep: "The original worktree and index were kept. Retry Apply Patch when ready."
                    )
                }
            } else {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Patch apply failed",
                        detail: errorMessage(error),
                        nextStep: "The worktree was not left with a partial patch. Resolve the issue and retry."
                    )
                }
            }
        }
    }
}

/// Import one or more portable unified/binary patches into the active Shelf.
/// The panel is intentionally kept as a small AppKit boundary; the engine
/// owns patch validation and isolated-index construction.
func importShelvePatches(rootPath: String? = nil) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let panel = NSOpenPanel()
    panel.canChooseFiles = true
    panel.canChooseDirectories = false
    panel.allowsMultipleSelection = true
    panel.canCreateDirectories = false
    panel.prompt = "Import Patches"
    guard panel.runModal() == .OK, !panel.urls.isEmpty else { return }
    let urls = panel.urls
    beginFeedbackOperation("Import patches into shelf")
    Task.detached(priority: .userInitiated) {
        var imported = 0
        var failures: [String] = []
        for url in urls {
            do {
                let patch = try String(contentsOf: url, encoding: .utf8)
                let baseName = url.deletingPathExtension().lastPathComponent
                    .replacingOccurrences(of: "_", with: " ")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                let name = baseName.isEmpty ? "Imported Patch" : baseName
                try shelfRepository.shelveImport(name: name, patch: patch)
                imported += 1
            } catch {
                failures.append("\(url.lastPathComponent): \(errorMessage(error))")
            }
        }
        let nextShelves = (try? shelfRepository.shelveList()) ?? []
        let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
        let importedCount = imported
        let failureDetails = failures
        await MainActor.run {
            guard shelfActionRootMatchesCurrentRoot(
                requestedRootPath: resolvedRootPath,
                currentRootPath: self.activeShelfRootPath
            ) else { return }
            self.publishShelfSnapshot(
                rootPath: resolvedRootPath,
                shelves: nextShelves,
                deletedShelves: nextDeletedShelves
            )
            if importedCount > 0 && failureDetails.isEmpty {
                self.feedbackCenter.success(
                    "Patches imported",
                    detail: "\(importedCount) shelf(s)",
                    notificationID: self.shelfMetadataNotificationID(
                        operation: "import",
                        rootPath: resolvedRootPath
                    )
                )
            } else if importedCount > 0 {
                self.feedbackCenter.warning(
                    "Some patches imported",
                    detail: failureDetails.joined(separator: "\n"),
                    nextStep: "Fix the failed patch names or base revisions, then import again.",
                    notificationID: self.shelfMetadataNotificationID(
                        operation: "import",
                        rootPath: resolvedRootPath
                    )
                )
            } else {
                self.feedbackCenter.error(
                    "Patch import failed",
                    detail: failureDetails.isEmpty ? "No patches were imported." : failureDetails.joined(separator: "\n"),
                    nextStep: "Choose a valid unified or binary patch based on the current HEAD.",
                    notificationID: self.shelfMetadataNotificationID(
                        operation: "import",
                        rootPath: resolvedRootPath
                    )
                )
            }
        }
    }
}

/// Export a shelf as a portable Git patch. The engine emits binary metadata and
/// disables external diff/textconv, matching the existing preview safety rule.
func exportShelve(_ name: String, rootPath: String? = nil) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    guard (try? shelfRepository.shelveList().contains(where: { $0.name == name })) == true else {
        return
    }
    let panel = NSSavePanel()
    panel.nameFieldStringValue = "\(name.replacingOccurrences(of: " ", with: "_")).patch"
    panel.allowedContentTypes = [.plainText]
    panel.canCreateDirectories = true
    panel.prompt = "Export Patch"
    guard panel.runModal() == .OK, let destination = panel.url else { return }
    beginFeedbackOperation("Export shelf patch")
    Task.detached(priority: .userInitiated) {
        do {
            let patch = try shelfRepository.shelveDiff(name: name)
            try patch.write(to: destination, atomically: true, encoding: .utf8)
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                self.feedbackCenter.success(
                    "Patch exported",
                    detail: destination.lastPathComponent,
                    notificationID: self.shelfMetadataNotificationID(
                        operation: "export",
                        rootPath: resolvedRootPath
                    )
                )
            }
        } catch {
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                self.feedbackCenter.error(
                    "Patch export failed",
                    detail: errorMessage(error),
                    nextStep: "Choose a writable destination and retry.",
                    notificationID: self.shelfMetadataNotificationID(
                        operation: "export",
                        rootPath: resolvedRootPath
                    )
                )
            }
        }
    }
}

func loadShelves() {
    guard let repo else { return }
    Task.detached(priority: .userInitiated) {
        do {
            let ss = try repo.shelveList()
            let dsh = (try? repo.shelveDeletedList()) ?? []
            await MainActor.run {
                self.shelves = ss
                self.deletedShelves = dsh
                if let name = self.shelfPreviewName,
                   !ss.contains(where: { $0.name == name }),
                   !dsh.contains(where: { $0.name == name }) {
                    self.shelfPreviewName = nil
                    self.shelfPreviewIsDeleted = false
                    self.shelfPreviewText = nil
                    self.showShelfPreview = false
                }
            }
        } catch { await MainActor.run { self.loadError = errorMessage(error) } }
    }
}

/// shelve 当前激活仓库的全部变更。
func doShelve(paths selectedPaths: [String]? = nil) {
    guard let repo, !shelveName.isEmpty else { return }
    let name = shelveName
    let paths = selectedPaths ?? entries.map(\.path)
    guard !paths.isEmpty else { return }
    beginFeedbackOperation("Shelve changes")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.shelve(name: name, paths: paths)
            let st = try repo.status()
            let cls = (try? repo.changelistList()) ?? []
            let ss = try repo.shelveList()
            let dsh = (try? repo.shelveDeletedList()) ?? []
            await MainActor.run {
                self.entries = st; self.changeLists = cls; self.shelves = ss; self.deletedShelves = dsh; self.shelveName = ""
                self.refreshAfterShelfMutation(repo: repo, paths: paths)
                self.feedbackCenter.success("Changes shelved")
            }
        } catch { await MainActor.run { self.loadError = errorMessage(error) } }
    }
}

func renameShelve(
