nonisolated private func automaticUnshelveTarget(
    for shelf: ShelveInfo,
    repo: Repository
) throws -> String? {
    guard GitChangelistSettings.createAutomatically(from: .standard) else { return nil }
    let name = shelf.description.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !name.isEmpty else { return nil }
    try repo.changelistEnsure(name: name)
    return name
}

nonisolated private func assignUnshelvedPaths(
    _ paths: [String],
    to target: String?,
    status: [FileEntry],
    repo: Repository
) throws {
    guard let target, !paths.isEmpty else { return }
    let currentPaths = Set(status.map(\.path))
    let assignablePaths = paths.filter(currentPaths.contains)
    guard !assignablePaths.isEmpty else { return }
    try repo.changelistMovePaths(paths: assignablePaths, targetName: target)
}

/// Reconcile a Shelf/Apply Patch mutation through the same root-scoped dirty
/// lifecycle as an external VFS event. Updating `entries` directly is not
/// enough: file previews, the staging model, and the index revision cache
/// must all observe the post-apply worktree/index boundary.
private func refreshAfterShelfMutation(
    repo: Repository,
    paths: [String],
    metadataChanged: Bool = true
) {
    guard let workdir = repo.workdir() else {
        refreshAll(showFeedback: false)
        return
    }

    let dirtyPaths = repositoryShelfMutationDirtyPaths(
        workdir: workdir,
        paths: paths
    )
    let scope = dirtyPaths.isEmpty
        ? RepositoryDirtyScope(
            files: [],
            directories: [],
            nonRecursiveDirectories: [],
            everything: !metadataChanged
        )
        : repositoryDirtyScope(
            workdir: workdir,
            gitDir: repo.gitDir(),
            dirtyPaths: dirtyPaths
        )
    let changeScope: RepositoryChangeScope = metadataChanged
        ? [.worktree, .gitMetadata]
        : [.worktree]

    // Keep the exact path ledger in lockstep with the compacted scope. Shelf
    // operations are internal writes, so they do not enter the external VCS
    // action queue, but their file events still need the same acknowledge
    // boundary as watcher-delivered changes.
    repositoryDirtyFileManager.mark(
        repositoryPath: workdir,
        dirtyPaths: dirtyPaths
    )
    _ = repositoryDirtyScopeManager.mark(
        repositoryPath: workdir,
        scope: scope,
        changeScope: changeScope,
        dirtyPaths: dirtyPaths
    )
    startPendingRepositoryDirtyScopes()
}

func doShelveUnshelve(
    _ name: String,
    removeApplied: Bool = false,
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let scopedDeletedShelves = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    ) ? deletedShelves : activeDeletedShelfList
    let deletedShelfNamesBefore = Set(scopedDeletedShelves.map { $0.name })
    let notificationID = shelfBatchNotificationID(
        operation: .apply,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        shelfFeedbackTitle(.apply, removeApplied: removeApplied),
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    Task.detached(priority: .userInitiated) {
        do {
            guard let shelf = try shelfRepository.shelveList().first(where: { $0.name == name }) else {
                throw EngineError.GitOperation(message: "shelve: shelf not found '\(name)'")
            }
            let targetChangeList = try automaticUnshelveTarget(for: shelf, repo: shelfRepository)
            let applyResult = try shelfRepository.shelveUnshelveWithOptionsDifferentiated(
                name: name,
                removeApplied: removeApplied
            )
            let appliedPaths = applyResult.appliedPaths
            let failedPaths = applyResult.failedPaths
            let operationPaths = Array(
                Set(shelf.paths + appliedPaths + failedPaths)
            ).sorted()
            let operationItem = FeedbackOperationItem(
                scope: resolvedRootPath,
                name: name,
                state: patchApplyFeedbackState(applyResult),
                detail: patchApplySummary(
                    applyResult,
                    successDetail: "Shelf changes unshelved",
                    failureDetail: "\(appliedPaths.count) applied, \(failedPaths.count) not applied"
                ),
                children: shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + name,
                    paths: operationPaths,
                    result: applyResult,
                    successDetail: "Applied",
                    failureDetail: "Not applied"
                )
            )
            let st = try shelfRepository.status()
            try assignUnshelvedPaths(
                appliedPaths,
                to: targetChangeList,
                status: st,
                repo: shelfRepository
            )
            let cls = (try? shelfRepository.changelistList()) ?? []
            let ss = try shelfRepository.shelveList()
            let dsh = (try? shelfRepository.shelveDeletedList()) ?? []
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                if shelfRootSelectionIsPrimary(
                    selectedRootPath: resolvedRootPath,
                    primaryRootPath: self.primaryShelfRootPath
                ) {
                    self.entries = st
                    self.changeLists = cls
                }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: ss,
                    deletedShelves: dsh,
                    changeLists: cls
                )
                self.refreshAfterShelfMutation(
                    repo: shelfRepository,
                    paths: appliedPaths,
                    metadataChanged: removeApplied
                )
                let restoredName = removeApplied
                    ? dsh.first(where: { !deletedShelfNamesBefore.contains($0.name) })?.name
                    : nil
                let detail = targetChangeList.map { "\(name) → \($0)" } ?? name
                if let restoredName {
                    let actions = [self.shelfRestoreFeedbackAction(
                        name: restoredName,
                        rootPath: resolvedRootPath
                    )]
                    if !patchApplyNeedsAttention(applyResult) {
                        self.feedbackCenter.success(
                            "Shelf unshelved and removed",
                            detail: detail,
                            additionalActions: actions,
                            notificationID: self.shelfBatchNotificationID(
                                operation: .apply,
                                rootPath: resolvedRootPath
                            )
                        )
                    } else {
                        self.feedbackCenter.warning(
                            "Shelf partially unshelved and removed",
                            detail: "\(detail): \(appliedPaths.count) applied, \(failedPaths.count) not applied",
                            nextStep: "Review the failed Shelf members and retry them separately.",
                            additionalActions: actions,
                            notificationID: self.shelfBatchNotificationID(
                                operation: .apply,
                                rootPath: resolvedRootPath
                            )
                        )
                    }
                } else if !patchApplyNeedsAttention(applyResult) {
                    self.feedbackCenter.success(
                        "Shelf unshelved",
                        detail: detail,
                        notificationID: self.shelfBatchNotificationID(
                            operation: .apply,
                            rootPath: resolvedRootPath
                        )
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Shelf partially unshelved",
                        detail: "\(detail): \(appliedPaths.count) applied, \(failedPaths.count) not applied",
                        nextStep: "Review the failed Shelf members and retry them separately.",
                        notificationID: self.shelfBatchNotificationID(
                            operation: .apply,
                            rootPath: resolvedRootPath
                        )
                    )
                }
                self.feedbackCenter.attachOperationItems(
                    [operationItem],
                    notificationID: notificationID,
                    mergeWithExisting: preservePreviousItems
                )
            }
        } catch {
            if case let .ShelveApplyConflict(conflictName, paths) = error as? EngineError {
                if GitChangelistSettings.createAutomatically(from: .standard),
                   let shelf = try? shelfRepository.shelveList().first(where: { $0.name == conflictName }),
                   let target = try? automaticUnshelveTarget(for: shelf, repo: shelfRepository) {
                    _ = try? shelfRepository.shelveSetRestoreTarget(
                        name: conflictName,
                        targetChangeList: target
                    )
                }
                await MainActor.run {
                    self.presentShelveConflict(
                        name: conflictName,
                        paths: paths,
                        isPop: false,
                        changeListName: (try? shelfRepository.shelveRestoreInfo())?.targetChangeList,
                        repository: shelfRepository
                    )
                }
            } else {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Unshelve failed",
                        detail: errorMessage(error),
                        nextStep: "The shelf was kept. Resolve the local conflict, then retry.",
                        notificationID: self.shelfBatchNotificationID(
                            operation: .apply,
                            rootPath: resolvedRootPath
                        )
                    )
                }
            }
        }
    }
}

func doShelvePop(
    _ name: String,
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let notificationID = shelfBatchNotificationID(
        operation: .pop,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        shelfFeedbackTitle(.pop),
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    Task.detached(priority: .userInitiated) {
        do {
            guard let shelf = try shelfRepository.shelveList().first(where: { $0.name == name }) else {
                throw EngineError.GitOperation(message: "shelve: shelf not found '\(name)'")
            }
            let targetChangeList = try automaticUnshelveTarget(for: shelf, repo: shelfRepository)
            let applyResult = try shelfRepository.shelvePopDifferentiated(name: name)
            let appliedPaths = applyResult.appliedPaths
            let failedPaths = applyResult.failedPaths
            let st = try shelfRepository.status()
            try assignUnshelvedPaths(
                appliedPaths,
                to: targetChangeList,
                status: st,
                repo: shelfRepository
            )
            let cls = (try? shelfRepository.changelistList()) ?? []
            let ss = try shelfRepository.shelveList()
            let dsh = (try? shelfRepository.shelveDeletedList()) ?? []
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                if shelfRootSelectionIsPrimary(
                    selectedRootPath: resolvedRootPath,
                    primaryRootPath: self.primaryShelfRootPath
                ) {
                    self.entries = st
                    self.changeLists = cls
                }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: ss,
                    deletedShelves: dsh
                )
                self.refreshAfterShelfMutation(repo: shelfRepository, paths: appliedPaths)
                if self.shelfPreviewName == name,
                   !ss.contains(where: { $0.name == name }),
                   shelfActionRootMatchesCurrentRoot(
                       requestedRootPath: resolvedRootPath,
                       currentRootPath: self.shelfPreviewRootPath ?? self.primaryShelfRootPath
                   ) {
                    self.shelfPreviewName = nil
                    self.shelfPreviewText = nil
                    self.showShelfPreview = false
                }
                let operationItem = FeedbackOperationItem(
                    scope: resolvedRootPath,
                    name: name,
                    state: patchApplyFeedbackState(applyResult),
                    detail: patchApplySummary(
                        applyResult,
                        successDetail: targetChangeList.map { "Applied → \($0)" } ?? "Applied",
                        failureDetail: "\(appliedPaths.count) applied, \(failedPaths.count) not applied"
                    ),
                    children: shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + name,
                        paths: shelf.paths,
                        result: applyResult,
                        successDetail: "Applied",
                        failureDetail: "Not applied"
                    )
                )
                if !patchApplyNeedsAttention(applyResult) {
                    self.feedbackCenter.success(
                        "Shelve pop completed",
                        detail: targetChangeList.map { "\(name) → \($0)" },
                        notificationID: notificationID
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Shelve pop partially completed",
                        detail: "\(name): \(appliedPaths.count) applied, \(failedPaths.count) not applied",
                        nextStep: "Review the remaining Shelf members and retry them separately.",
                        notificationID: notificationID
                    )
                }
                self.feedbackCenter.attachOperationItems(
                    [operationItem],
                    notificationID: notificationID,
                    mergeWithExisting: preservePreviousItems
                )
            }
        } catch {
            if case let .ShelveApplyConflict(conflictName, paths) = error as? EngineError {
                if GitChangelistSettings.createAutomatically(from: .standard),
                   let shelf = try? shelfRepository.shelveList().first(where: { $0.name == conflictName }),
                   let target = try? automaticUnshelveTarget(for: shelf, repo: shelfRepository) {
                    _ = try? shelfRepository.shelveSetRestoreTarget(
                        name: conflictName,
                        targetChangeList: target
                    )
                }
                await MainActor.run {
                    self.presentShelveConflict(
                        name: conflictName,
                        paths: paths,
                        isPop: true,
                        changeListName: (try? shelfRepository.shelveRestoreInfo())?.targetChangeList,
                        repository: shelfRepository
                    )
                }
            } else {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Shelve pop failed",
                        detail: errorMessage(error),
                        nextStep: "The shelf was kept. Resolve the local conflict, then retry.",
                        notificationID: self.shelfBatchNotificationID(
                            operation: .pop,
                            rootPath: resolvedRootPath
                        )
                    )
                }
            }
        }
    }
}

/// Pop multiple active Shelves with the same non-dialog action semantics as
/// IntelliJ's PopShelfAction. Each list is applied and removed independently;
/// a conflict stops the queue so the persisted restore snapshot can be
/// resolved before another Shelf touches the same worktree.
func doShelvePopShelves(
    _ names: [String],
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    var seen = Set<String>()
    let uniqueNames = names
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty && seen.insert($0).inserted }
    guard !uniqueNames.isEmpty else { return }
    if uniqueNames.count == 1, let name = uniqueNames.first {
        doShelvePop(
            name,
            rootPath: resolvedRootPath,
            preservePreviousItems: preservePreviousItems
        )
        return
    }

    let notificationID = shelfBatchNotificationID(
        operation: .pop,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        "Pop shelves",
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    feedbackCenter.updateBatchProgress(
        completed: 0,
        total: uniqueNames.count,
        phase: "Pop Shelf"
    )
    Task.detached(priority: .userInitiated) {
        var appliedDetails: [String] = []
        var appliedNames: [String] = []
        var consumedNames: [String] = []
        var mutatedPaths: [String] = []
        var failures: [String] = []
        var itemStates: [String: FeedbackResultState] = [:]
        var itemDetails: [String: String] = [:]
        var itemChildren: [String: [FeedbackOperationSubitem]] = [:]
        var conflict: (name: String, paths: [String], targetName: String?)?

        for (index, name) in uniqueNames.enumerated() {
            var shelfPaths: [String] = []
            do {
                guard let shelf = try shelfRepository.shelveList().first(where: { $0.name == name }) else {
                    throw EngineError.GitOperation(message: "shelve: shelf not found '\(name)'")
                }
                shelfPaths = shelf.paths
                let targetName = try automaticUnshelveTarget(for: shelf, repo: shelfRepository)
                let applyResult = try shelfRepository.shelvePopDifferentiated(name: name)
                let appliedPaths = applyResult.appliedPaths
                let failedPaths = applyResult.failedPaths
                if !(try shelfRepository.shelveList()).contains(where: { $0.name == name }) {
                    consumedNames.append(name)
                }
                mutatedPaths.append(contentsOf: appliedPaths)
                let status = try shelfRepository.status()
                try assignUnshelvedPaths(
                    appliedPaths,
                    to: targetName,
                    status: status,
                    repo: shelfRepository
                )
                if !patchApplyNeedsAttention(applyResult) {
                    appliedNames.append(name)
                    appliedDetails.append(
                        targetName.map { "\(name) → \($0)" } ?? name
                    )
                } else {
                    failures.append(
                        "\(name): \(appliedPaths.count) applied, \(failedPaths.count) not applied"
                    )
                }
                itemStates[name] = patchApplyFeedbackState(applyResult)
                itemDetails[name] = patchApplySummary(
                    applyResult,
                    successDetail: targetName.map { "Applied → \($0)" } ?? "Applied",
                    failureDetail: "\(appliedPaths.count) applied, \(failedPaths.count) not applied"
                )
                itemChildren[name] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + name,
                    paths: shelfPaths,
                    result: applyResult,
                    successDetail: "Applied",
                    failureDetail: "Not applied"
                )
            } catch {
                if case let .ShelveApplyConflict(conflictName, paths) = error as? EngineError {
                    let targetName: String? = {
                        guard GitChangelistSettings.createAutomatically(from: .standard),
                              let shelf = try? shelfRepository.shelveList().first(where: { $0.name == conflictName })
                        else { return nil }
                        return try? automaticUnshelveTarget(for: shelf, repo: shelfRepository)
                    }()
                    if let targetName {
                        _ = try? shelfRepository.shelveSetRestoreTarget(
                            name: conflictName,
                            targetChangeList: targetName
                        )
                    }
                    let restoreInfo = (try? shelfRepository.shelveRestoreInfo()) ?? nil
                    let appliedPaths = restoreInfo?.appliedPaths ?? []
                    let conflictPaths = restoreInfo?.conflictPaths ?? paths
                    mutatedPaths.append(contentsOf: appliedPaths)
                    conflict = (conflictName, paths, targetName)
                    itemStates[conflictName] = .failed
                    itemDetails[conflictName] = "Conflict paused: \(paths.joined(separator: ", "))"
                    itemChildren[conflictName] = shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + conflictName,
                        paths: shelfPaths,
                        appliedPaths: Set(appliedPaths),
                        failedPaths: Set(conflictPaths),
                        successDetail: "Applied",
                        failureDetail: "Conflict paused"
                    )
                    await MainActor.run {
                        self.feedbackCenter.updateBatchProgress(
                            completed: index + 1,
                            total: uniqueNames.count,
                            phase: "Pop Shelf",
                            detail: conflictName
                        )
                    }
                    break
                }
                itemStates[name] = .failed
                itemDetails[name] = errorMessage(error)
                itemChildren[name] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + name,
                    paths: shelfPaths,
                    state: .failed,
                    detail: errorMessage(error)
                )
                failures.append("\(name): \(errorMessage(error))")
            }
            await MainActor.run {
                self.feedbackCenter.updateBatchProgress(
                    completed: index + 1,
                    total: uniqueNames.count,
                    phase: "Pop Shelf",
                    detail: name
                )
            }
        }

        let finalStatus = (try? shelfRepository.status()) ?? []
        let nextChangeLists = (try? shelfRepository.changelistList()) ?? []
        let nextShelves = (try? shelfRepository.shelveList()) ?? []
        let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
        let appliedNamesSnapshot = appliedNames
        let consumedNamesSnapshot = consumedNames
        let mutatedPathsSnapshot = mutatedPaths
        let appliedDetailsSnapshot = appliedDetails
        let failuresSnapshot = failures
        let itemStatesSnapshot = itemStates
        let itemDetailsSnapshot = itemDetails
        let itemChildrenSnapshot = itemChildren
        let conflictSnapshot = conflict
        await MainActor.run {
            guard shelfActionRootMatchesCurrentRoot(
                requestedRootPath: resolvedRootPath,
                currentRootPath: self.activeShelfRootPath
            ) else { return }
            let isPrimaryRoot = shelfRootSelectionIsPrimary(
                selectedRootPath: resolvedRootPath,
                primaryRootPath: self.primaryShelfRootPath
            )
            if isPrimaryRoot {
                self.entries = finalStatus
                self.changeLists = nextChangeLists
            }
            self.publishShelfSnapshot(
                rootPath: resolvedRootPath,
                shelves: nextShelves,
                deletedShelves: nextDeletedShelves,
                changeLists: nextChangeLists
            )
            self.refreshAfterShelfMutation(
                repo: shelfRepository,
                paths: mutatedPathsSnapshot
            )
            if !isPrimaryRoot {
                self.refreshAll(showFeedback: false)
            }
            if let previewName = self.shelfPreviewName,
               uniqueNames.contains(previewName),
               !nextShelves.contains(where: { $0.name == previewName }) {
                self.shelfPreviewName = nil
                self.shelfPreviewText = nil
                self.showShelfPreview = false
            }

            let retryNames = uniqueNames.filter {
                !appliedNamesSnapshot.contains($0)
                    && !consumedNamesSnapshot.contains($0)
                    && $0 != conflictSnapshot?.name
            }
            let retryAction = self.shelfBatchRetryFeedbackAction(
                names: retryNames,
                operation: .pop,
                targetName: nil,
                removeApplied: true,
                rootPath: resolvedRootPath
            )
            let operationItems = shelfOperationItems(
                rootPath: resolvedRootPath,
                names: uniqueNames,
                states: itemStatesSnapshot,
                details: itemDetailsSnapshot,
                children: itemChildrenSnapshot
            )
            let detail = appliedDetailsSnapshot.isEmpty
                ? "0/\(uniqueNames.count)"
                : appliedDetailsSnapshot.joined(separator: ", ")
            if let conflictSnapshot {
                let remaining = failuresSnapshot.isEmpty
                    ? nil
                    : failuresSnapshot.joined(separator: "\n")
                self.feedbackCenter.warning(
                    "Shelve pop paused",
                    detail: [detail, remaining].compactMap { $0 }.joined(separator: "\n"),
                    nextStep: "Resolve the restored local changes, then complete the Shelf pop.",
                    additionalActions: retryAction.map { [$0] } ?? [],
                    notificationID: notificationID
                )
                self.presentShelveConflict(
                    name: conflictSnapshot.name,
                    paths: conflictSnapshot.paths,
                    isPop: true,
                    changeListName: conflictSnapshot.targetName,
                    repository: shelfRepository
                )
            } else if failuresSnapshot.isEmpty {
                self.feedbackCenter.success(
                    "Shelve pop completed",
                    detail: detail,
                    notificationID: notificationID
                )
            } else if !appliedDetailsSnapshot.isEmpty {
                self.feedbackCenter.warning(
                    "Shelves applied with warnings",
                    detail: [detail, failuresSnapshot.joined(separator: "\n")]
                        .joined(separator: "\n"),
                    nextStep: "Review the remaining Shelves and retry them individually.",
                    additionalActions: retryAction.map { [$0] } ?? [],
                    notificationID: notificationID
                )
            } else {
                self.feedbackCenter.error(
                    "Shelf pop failed",
                    detail: failuresSnapshot.joined(separator: "\n"),
                    nextStep: "The remaining Shelves were kept. Resolve the local issue, then retry.",
                    additionalActions: retryAction.map { [$0] } ?? [],
                    notificationID: notificationID,
                    localized: true
                )
            }
            self.feedbackCenter.attachOperationItems(
                operationItems,
                notificationID: notificationID,
                mergeWithExisting: preservePreviousItems
            )
        }
    }
}

/// Drop multiple active Shelves as one serial operation. IntelliJ treats a
/// multi-selection delete as one notification with per-list recovery actions;
/// serial execution keeps the repository lock and Recently Deleted ordering
/// deterministic while still allowing the remaining lists to be retried.
func doShelveDropShelves(
    _ names: [String],
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    var seenNames = Set<String>()
    let uniqueNames = names
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty && seenNames.insert($0).inserted }
    guard !uniqueNames.isEmpty else { return }
    if uniqueNames.count == 1, let name = uniqueNames.first {
        doShelveDrop(
            name,
            rootPath: resolvedRootPath,
            preservePreviousItems: preservePreviousItems
        )
        return
    }

    let notificationID = shelfBatchNotificationID(
        operation: .drop,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        "Drop shelves",
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    feedbackCenter.updateBatchProgress(
        completed: 0,
        total: uniqueNames.count,
        phase: "Drop Shelf"
    )
    Task.detached(priority: .userInitiated) {
        var droppedNames: [String] = []
        var originalTimestamps: [String: Int64] = [:]
        var failures: [String] = []
        var itemStates: [String: FeedbackResultState] = [:]
        var itemDetails: [String: String] = [:]
        var itemChildren: [String: [FeedbackOperationSubitem]] = [:]

        for (index, name) in uniqueNames.enumerated() {
            do {
                guard let shelf = try shelfRepository.shelveList().first(where: { $0.name == name }) else {
                    throw EngineError.GitOperation(message: "shelve: shelf not found '\(name)'")
                }
                originalTimestamps[name] = shelf.timestamp
                try shelfRepository.shelveDrop(name: name)
                droppedNames.append(name)
                itemStates[name] = .success
                itemDetails[name] = "Moved to Recently Deleted"
                itemChildren[name] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + name,
                    paths: shelf.paths,
                    state: .success,
                    detail: "Moved to Recently Deleted"
                )
            } catch {
                itemStates[name] = .failed
                itemDetails[name] = errorMessage(error)
                itemChildren[name] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + name,
                    paths: (try? shelfRepository.shelveList().first(where: { $0.name == name })?.paths) ?? [],
                    state: .failed,
                    detail: errorMessage(error)
                )
                failures.append("\(name): \(errorMessage(error))")
            }
            await MainActor.run {
                self.feedbackCenter.updateBatchProgress(
                    completed: index + 1,
                    total: uniqueNames.count,
                    phase: "Drop Shelf",
                    detail: name
                )
            }
        }

        let nextShelves = (try? shelfRepository.shelveList()) ?? []
        let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
        let droppedNamesSnapshot = droppedNames
        let originalTimestampsSnapshot = originalTimestamps
        let failuresSnapshot = failures
        let itemStatesSnapshot = itemStates
        let itemDetailsSnapshot = itemDetails
        let itemChildrenSnapshot = itemChildren
        await MainActor.run {
            guard shelfActionRootMatchesCurrentRoot(
                requestedRootPath: resolvedRootPath,
                currentRootPath: self.activeShelfRootPath
            ) else { return }
            self.publishShelfSnapshot(
                rootPath: resolvedRootPath,
                shelves: nextShelves,
                deletedShelves: nextDeletedShelves
            )
            if let previewName = self.shelfPreviewName,
               droppedNamesSnapshot.contains(previewName) {
                self.shelfPreviewName = nil
                self.shelfPreviewText = nil
                self.showShelfPreview = false
            }

            let batchUndoAction = self.shelfUndoDeletionsFeedbackAction(
                names: droppedNamesSnapshot,
                originalTimestamps: originalTimestampsSnapshot,
                rootPath: resolvedRootPath
            )
            let retryNames = uniqueNames.filter { !droppedNamesSnapshot.contains($0) }
            let retryAction = self.shelfBatchRetryFeedbackAction(
                names: retryNames,
                operation: .drop,
                targetName: nil,
                removeApplied: false,
                rootPath: resolvedRootPath
            )
            let additionalActions = (batchUndoAction.map { [$0] } ?? []) + (retryAction.map { [$0] } ?? [])
            let operationItems = shelfOperationItems(
                rootPath: resolvedRootPath,
                names: uniqueNames,
                states: itemStatesSnapshot,
                details: itemDetailsSnapshot,
                children: itemChildrenSnapshot
            )
            let droppedDetail = droppedNamesSnapshot.isEmpty
                ? "0/\(uniqueNames.count)"
                : "\(droppedNamesSnapshot.count)/\(uniqueNames.count): "
                    + droppedNamesSnapshot.joined(separator: ", ")

            if failuresSnapshot.isEmpty {
                self.feedbackCenter.success(
                    "Shelves dropped",
                    detail: droppedDetail,
                    additionalActions: batchUndoAction.map { [$0] } ?? [],
                    notificationID: notificationID
                )
            } else if droppedNamesSnapshot.isEmpty {
                self.feedbackCenter.error(
                    "Shelf drop failed",
                    detail: failuresSnapshot.joined(separator: "\n"),
                    nextStep: "The selected Shelves were kept. Resolve the reported issue and retry.",
                    additionalActions: retryAction.map { [$0] } ?? [],
                    notificationID: notificationID,
                    localized: true
                )
            } else {
                self.feedbackCenter.warning(
                    "Some Shelves dropped",
                    detail: [droppedDetail, failuresSnapshot.joined(separator: "\n")]
                        .joined(separator: "\n"),
                    nextStep: "The failed Shelves were kept. Retry them after resolving the reported issue.",
                    additionalActions: additionalActions,
                    notificationID: notificationID,
                    localized: true
                )
            }
            self.feedbackCenter.attachOperationItems(
                operationItems,
                notificationID: notificationID,
                mergeWithExisting: preservePreviousItems
            )
        }
    }
}

/// Execute the DeleteProvider's mixed active/Recently Deleted Shelf scope as
/// one root-scoped lifecycle. IntelliJ's ShelvedChangesViewManager performs
/// this as one deletion notification; keeping the four storage mutations in
/// one serial runner prevents concurrent repository access and gives Undo and
/// Retry one coherent result.
func deleteShelfPlan(
    _ plan: ShelfDeletePlan,
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let operations = shelfDeleteOperations(plan)
    guard !operations.isEmpty else { return }

    let notificationID = shelfRootNotificationID(
        prefix: "shelf-delete-plan",
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        "Delete Shelf changes",
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    feedbackCenter.updateBatchProgress(
        completed: 0,
        total: operations.count,
        phase: "Delete Shelf Changes"
    )

    Task.detached(priority: .userInitiated) {
        var completedKeys = Set<String>()
        var successfulLabels: [String] = []
        var undoNames: [String] = []
        var undoTimestamps: [String: Int64] = [:]
        var knownDeletedNames = Set((try? shelfRepository.shelveDeletedList().map(\.name)) ?? [])
        var failures: [String] = []
        var failedActiveShelfNames: [String] = []
        var failedActivePathGroups: [ShelfPathDeleteGroup] = []
        var failedDeletedShelfNames: [String] = []
        var failedDeletedPathGroups: [ShelfPathDeleteGroup] = []
        var itemStates: [String: FeedbackResultState] = [:]
        var itemDetails: [String: String] = [:]
        var itemChildren: [String: [FeedbackOperationSubitem]] = [:]

        for (index, operation) in operations.enumerated() {
            do {
                switch operation.kind {
                case .activeShelf:
                    guard let shelf = try shelfRepository.shelveList().first(where: {
                        $0.name == operation.shelfName
                    }) else {
                        throw EngineError.GitOperation(
                            message: "shelve: shelf not found '\(operation.shelfName)'"
                        )
                    }
                    try shelfRepository.shelveDrop(name: operation.shelfName)
                    undoNames.append(operation.shelfName)
                    undoTimestamps[operation.shelfName] = shelf.timestamp
                    itemChildren[operation.key] = shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + operation.key,
                        paths: shelf.paths,
                        state: .success,
                        detail: "Moved to Recently Deleted"
                    )
                    itemDetails[operation.key] = "Moved to Recently Deleted"

                case .activePaths:
                    guard let shelf = try shelfRepository.shelveList().first(where: {
                        $0.name == operation.shelfName
                    }) else {
                        throw EngineError.GitOperation(
                            message: "shelve: shelf not found '\(operation.shelfName)'"
                        )
                    }
                    try shelfRepository.shelveDropPaths(
                        name: operation.shelfName,
                        paths: operation.paths
                    )
                    let currentDeleted = try shelfRepository.shelveDeletedList()
                    for deleted in currentDeleted where !knownDeletedNames.contains(deleted.name) {
                        knownDeletedNames.insert(deleted.name)
                        undoNames.append(deleted.name)
                        undoTimestamps[deleted.name] = shelf.timestamp
                    }
                    itemChildren[operation.key] = shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + operation.key,
                        paths: operation.paths,
                        state: .success,
                        detail: "Moved to Recently Deleted"
                    )
                    itemDetails[operation.key] = "Moved to Recently Deleted"

                case .deletedShelf:
                    guard let shelf = try shelfRepository.shelveDeletedList().first(where: {
                        $0.name == operation.shelfName
                    }) else {
                        throw EngineError.GitOperation(
                            message: "shelve: deleted Shelf not found '\(operation.shelfName)'"
                        )
                    }
                    try shelfRepository.shelveDeleteDeleted(name: operation.shelfName)
                    itemChildren[operation.key] = shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + operation.key,
                        paths: shelf.paths,
                        state: .success,
                        detail: "Deleted permanently"
                    )
                    itemDetails[operation.key] = "Deleted permanently"

                case .deletedPaths:
                    guard let shelf = try shelfRepository.shelveDeletedList().first(where: {
                        $0.name == operation.shelfName
                    }) else {
                        throw EngineError.GitOperation(
                            message: "shelve: deleted Shelf not found '\(operation.shelfName)'"
                        )
                    }
                    try shelfRepository.shelveDeleteDeletedPaths(
                        name: operation.shelfName,
                        paths: operation.paths
                    )
                    itemChildren[operation.key] = shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + operation.key,
                        paths: operation.paths,
                        state: .success,
                        detail: "Deleted permanently"
                    )
                    itemDetails[operation.key] = "Deleted permanently"
                    _ = shelf
                }
                completedKeys.insert(operation.key)
                successfulLabels.append(operation.displayName)
                itemStates[operation.key] = .success
            } catch {
                let message = errorMessage(error)
                failures.append("\(operation.displayName): \(message)")
                itemStates[operation.key] = .failed
                itemDetails[operation.key] = message
                let currentPaths: [String] = {
                    switch operation.kind {
                    case .activeShelf, .activePaths:
                        return (try? shelfRepository.shelveList().first(where: {
                            $0.name == operation.shelfName
                        })?.paths) ?? []
                    case .deletedShelf, .deletedPaths:
                        return (try? shelfRepository.shelveDeletedList().first(where: {
                            $0.name == operation.shelfName
                        })?.paths) ?? []
                    }
                }()
                itemChildren[operation.key] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + operation.key,
                    paths: operation.paths.isEmpty ? currentPaths : operation.paths,
                    state: .failed,
                    detail: message
                )
                switch operation.kind {
                case .activeShelf:
                    failedActiveShelfNames.append(operation.shelfName)
                case .activePaths:
                    failedActivePathGroups.append(
                        ShelfPathDeleteGroup(
                            shelfName: operation.shelfName,
                            paths: operation.paths
                        )
                    )
                case .deletedShelf:
                    failedDeletedShelfNames.append(operation.shelfName)
                case .deletedPaths:
                    failedDeletedPathGroups.append(
                        ShelfPathDeleteGroup(
                            shelfName: operation.shelfName,
                            paths: operation.paths
                        )
                    )
                }
            }
            await MainActor.run {
                self.feedbackCenter.updateBatchProgress(
                    completed: index + 1,
                    total: operations.count,
                    phase: "Delete Shelf Changes",
                    detail: operation.displayName
                )
            }
        }

        let nextShelves = (try? shelfRepository.shelveList()) ?? []
        let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
        let completedKeysSnapshot = completedKeys
        let successfulLabelsSnapshot = successfulLabels
        let undoNamesSnapshot = undoNames
        let undoTimestampsSnapshot = undoTimestamps
        let failuresSnapshot = failures
        let retryPlan = ShelfDeletePlan(
            activeShelfNames: failedActiveShelfNames,
            activePathGroups: failedActivePathGroups,
            deletedShelfNames: failedDeletedShelfNames,
            deletedPathGroups: failedDeletedPathGroups
        )
        let itemStatesSnapshot = itemStates
        let itemDetailsSnapshot = itemDetails
        let itemChildrenSnapshot = itemChildren
        await MainActor.run {
            guard shelfActionRootMatchesCurrentRoot(
                requestedRootPath: resolvedRootPath,
                currentRootPath: self.activeShelfRootPath
            ) else { return }
            self.publishShelfSnapshot(
                rootPath: resolvedRootPath,
                shelves: nextShelves,
                deletedShelves: nextDeletedShelves
            )
            if let previewName = self.shelfPreviewName,
               let previewOperation = operations.first(where: {
                   $0.shelfName == previewName
                       && (($0.kind == .deletedShelf || $0.kind == .deletedPaths)
                           == self.shelfPreviewIsDeleted)
                       && completedKeysSnapshot.contains($0.key)
               }) {
                _ = previewOperation
                self.shelfPreviewName = nil
                self.shelfPreviewText = nil
                self.showShelfPreview = false
            }

            let undoAction = self.shelfUndoDeletionsFeedbackAction(
                names: undoNamesSnapshot,
                originalTimestamps: undoTimestampsSnapshot,
                rootPath: resolvedRootPath
            )
            let retryAction = self.shelfDeletePlanRetryFeedbackAction(
                plan: retryPlan,
                rootPath: resolvedRootPath
            )
            let additionalActions = [undoAction, retryAction].compactMap { $0 }
            let operationItems = operations.map { operation in
                FeedbackOperationItem(
                    scope: resolvedRootPath,
                    name: operation.displayName,
                    state: itemStatesSnapshot[operation.key] ?? .skipped,
                    detail: itemDetailsSnapshot[operation.key] ?? "Not attempted",
                    children: itemChildrenSnapshot[operation.key] ?? []
                )
            }
            let detail = successfulLabelsSnapshot.isEmpty
                ? "0/\(operations.count)"
                : "\(completedKeysSnapshot.count)/\(operations.count): "
                    + successfulLabelsSnapshot.joined(separator: ", ")
            if failuresSnapshot.isEmpty {
                self.feedbackCenter.success(
                    "Shelf changes deleted",
                    detail: detail,
                    additionalActions: undoAction.map { [$0] } ?? [],
                    notificationID: notificationID
                )
            } else if completedKeysSnapshot.isEmpty {
                self.feedbackCenter.error(
                    "Shelf deletion failed",
                    detail: failuresSnapshot.joined(separator: "\n"),
                    nextStep: "The selected Shelves were kept. Resolve the reported issue and retry.",
                    additionalActions: retryAction.map { [$0] } ?? [],
                    notificationID: notificationID,
                    localized: true
                )
            } else {
                self.feedbackCenter.warning(
                    "Some Shelf changes were not deleted",
                    detail: [detail, failuresSnapshot.joined(separator: "\n")].joined(separator: "\n"),
                    nextStep: "Retry the remaining Shelf changes or use Undo to restore active deletions.",
                    additionalActions: additionalActions,
                    notificationID: notificationID,
                    localized: true
                )
            }
            self.feedbackCenter.attachOperationItems(
                operationItems,
                notificationID: notificationID,
                mergeWithExisting: preservePreviousItems
            )
        }
    }
}

private func normalizedShelfPathGroups(
    _ groups: [ShelfPathDeleteGroup]
) -> [ShelfPathDeleteGroup] {
    var result: [ShelfPathDeleteGroup] = []
    var indexes: [String: Int] = [:]
    for group in groups {
        let name = group.shelfName.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !name.isEmpty else { continue }
        var paths: [String] = []
        var seenPaths = Set<String>()
        for path in group.paths {
            let normalized = path.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !normalized.isEmpty, seenPaths.insert(normalized).inserted else { continue }
            paths.append(normalized)
        }
        guard !paths.isEmpty else { continue }
        if let index = indexes[name] {
            var merged = result[index].paths
            for path in paths where !merged.contains(path) {
                merged.append(path)
            }
            result[index] = ShelfPathDeleteGroup(shelfName: name, paths: merged)
        } else {
            indexes[name] = result.count
            result.append(ShelfPathDeleteGroup(shelfName: name, paths: paths))
        }
    }
    return result
}

nonisolated private func shelfPathGroupKey(_ group: ShelfPathDeleteGroup) -> String {
    "\(group.shelfName)\u{1E}\(group.paths.joined(separator: "\u{1F}"))"
}

/// Apply selected members from several Shelves as one serialized operation.
/// IntelliJ passes a grouped-changes map to ShelfService; never starting one
/// detached repository mutation per group preserves that same lock and
/// notification boundary in SwiftUI.
func doShelveUnshelvePathGroups(
    _ groups: [ShelfPathDeleteGroup],
    removeApplied: Bool,
    sourceIsDeleted: Bool,
    targetName: String? = nil,
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let groups = normalizedShelfPathGroups(groups)
    guard !groups.isEmpty else { return }
    let explicitTargetName = targetName?.trimmingCharacters(in: .whitespacesAndNewlines)
    if targetName != nil, explicitTargetName?.isEmpty != false { return }
    let operation: ArborVCSActionRequest.ShelfMemberBatchOperation = sourceIsDeleted
        ? (removeApplied ? .unshelveDeletedAndRemove : .unshelveDeleted)
        : (removeApplied ? .unshelveAndRemove : .unshelve)
    let scopedDeletedShelves = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    ) ? deletedShelves : activeDeletedShelfList
    let deletedShelfNamesBefore = Set(scopedDeletedShelves.map { $0.name })
    let notificationID = shelfMemberBatchNotificationID(
        operation: operation,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        sourceIsDeleted ? "Unshelve deleted Shelf changes" : "Unshelve Shelf changes",
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    feedbackCenter.updateBatchProgress(
        completed: 0,
        total: groups.count,
        phase: "Unshelve Shelf Changes"
    )
    Task.detached(priority: .userInitiated) {
        var completedKeys = Set<String>()
        var appliedDetails: [String] = []
        var mutatedPaths: [String] = []
        var failures: [String] = []
        var postApplyWarnings: [String] = []
        var conflict: (name: String, paths: [String], targetName: String?)?
        var itemStates: [String: FeedbackResultState] = [:]
        var itemDetails: [String: String] = [:]
        var itemChildren: [String: [FeedbackOperationSubitem]] = [:]

        for (index, group) in groups.enumerated() {
            let key = shelfPathGroupKey(group)
            var didApply = false
            var targetName: String?
            do {
                if let explicitTargetName,
                   !(try shelfRepository.changelistList()).contains(where: { $0.name == explicitTargetName }) {
                    throw EngineError.GitOperation(message: "Target Changelist not found: \(explicitTargetName)")
                }
                let sourceShelves = sourceIsDeleted
                    ? try shelfRepository.shelveDeletedList()
                    : try shelfRepository.shelveList()
                guard let shelf = sourceShelves.first(where: { $0.name == group.shelfName }) else {
                    throw EngineError.GitOperation(
                        message: "shelve: shelf not found '\(group.shelfName)'"
                    )
                }
                if let explicitTargetName {
                    targetName = explicitTargetName
                } else {
                    targetName = try automaticUnshelveTarget(for: shelf, repo: shelfRepository)
                }
                let applyResult = sourceIsDeleted
                    ? try shelfRepository.shelveUnshelveDeletedPathsWithOptionsDifferentiated(
                        name: group.shelfName,
                        paths: group.paths,
                        removeApplied: removeApplied
                    )
                    : try shelfRepository.shelveUnshelvePathsWithOptionsDifferentiated(
                        name: group.shelfName,
                        paths: group.paths,
                        removeApplied: removeApplied
                    )
                let appliedPaths = applyResult.appliedPaths
                let failedPaths = applyResult.failedPaths
                didApply = !appliedPaths.isEmpty
                itemStates[group.shelfName] = patchApplyFeedbackState(applyResult)
                itemDetails[group.shelfName] = patchApplySummary(
                    applyResult,
                    successDetail: targetName.map { "Applied → \($0)" } ?? "Shelf changes unshelved",
                    failureDetail: "\(appliedPaths.count) applied, \(failedPaths.count) not applied"
                )
                itemChildren[group.shelfName] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + group.shelfName,
                    paths: group.paths,
                    result: applyResult,
                    successDetail: "Applied",
                    failureDetail: "Not applied"
                )
                if !patchApplyNeedsAttention(applyResult) {
                    completedKeys.insert(key)
                } else {
                    failures.append(
                        "\(group.shelfName): \(appliedPaths.count) applied, \(failedPaths.count) not applied"
                    )
                }
                mutatedPaths.append(contentsOf: appliedPaths)
                let status = try shelfRepository.status()
                do {
                    try assignUnshelvedPaths(
                        appliedPaths,
                        to: targetName,
                        status: status,
                        repo: shelfRepository
                    )
                } catch {
                    postApplyWarnings.append(
                        "\(group.shelfName): applied, but final Changelist assignment failed: \(errorMessage(error))"
                    )
                }
                appliedDetails.append(
                    targetName.map { "\(group.shelfName) → \($0): \(group.paths.joined(separator: ", "))" }
                        ?? "\(group.shelfName): \(group.paths.joined(separator: ", "))"
                )
            } catch {
                if case let .ShelveApplyConflict(conflictName, paths) = error as? EngineError {
                    if let targetName {
                        _ = try? shelfRepository.shelveSetRestoreTarget(
                            name: conflictName,
                            targetChangeList: targetName
                        )
                    }
                    conflict = (conflictName, paths, targetName)
                    itemStates[group.shelfName] = .failed
                    itemDetails[group.shelfName] = "Conflict paused: \(paths.joined(separator: ", "))"
                    itemChildren[group.shelfName] = shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + group.shelfName,
                        paths: group.paths,
                        appliedPaths: [],
                        failedPaths: Set(paths),
                        successDetail: "Applied",
                        failureDetail: "Conflict paused"
                    )
                    await MainActor.run {
                        self.feedbackCenter.updateBatchProgress(
                            completed: index + 1,
                            total: groups.count,
                            phase: "Unshelve Shelf Changes",
                            detail: conflictName
                        )
                    }
                    break
                }
                if !didApply {
                    failures.append("\(group.shelfName): \(errorMessage(error))")
                    itemStates[group.shelfName] = .failed
                    itemDetails[group.shelfName] = errorMessage(error)
                    itemChildren[group.shelfName] = shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + group.shelfName,
                        paths: group.paths,
                        state: .failed,
                        detail: errorMessage(error)
                    )
                }
            }
            await MainActor.run {
                self.feedbackCenter.updateBatchProgress(
                    completed: index + 1,
                    total: groups.count,
                    phase: "Unshelve Shelf Changes",
                    detail: group.shelfName
                )
            }
        }

        let finalStatus = (try? shelfRepository.status()) ?? []
        let nextChangeLists = (try? shelfRepository.changelistList()) ?? []
        let nextShelves = (try? shelfRepository.shelveList()) ?? []
        let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
        let completedKeysSnapshot = completedKeys
        let appliedDetailsSnapshot = appliedDetails
        let mutatedPathsSnapshot = mutatedPaths
        let failuresSnapshot = failures
        let postApplyWarningsSnapshot = postApplyWarnings
        let conflictSnapshot = conflict
        let itemStatesSnapshot = itemStates
        let itemDetailsSnapshot = itemDetails
        let itemChildrenSnapshot = itemChildren
        let retryGroups = groups.filter {
            !completedKeysSnapshot.contains(shelfPathGroupKey($0))
                && $0.shelfName != conflictSnapshot?.name
        }
        await MainActor.run {
            guard shelfActionRootMatchesCurrentRoot(
                requestedRootPath: resolvedRootPath,
                currentRootPath: self.activeShelfRootPath
            ) else { return }
            let isPrimaryRoot = shelfRootSelectionIsPrimary(
                selectedRootPath: resolvedRootPath,
                primaryRootPath: self.primaryShelfRootPath
            )
            if isPrimaryRoot {
                self.entries = finalStatus
                self.changeLists = nextChangeLists
            }
            self.publishShelfSnapshot(
                rootPath: resolvedRootPath,
                shelves: nextShelves,
                deletedShelves: nextDeletedShelves
            )
            self.refreshAfterShelfMutation(
                repo: shelfRepository,
                paths: mutatedPathsSnapshot,
                metadataChanged: removeApplied || sourceIsDeleted
            )
            if !isPrimaryRoot {
                self.refreshAll(showFeedback: false)
            }

            let retryAction = self.shelfMemberBatchRetryFeedbackAction(
                groups: retryGroups,
                operation: operation,
                targetName: explicitTargetName,
                rootPath: resolvedRootPath
            )
            let restoreActions = removeApplied
                ? nextDeletedShelves
                    .filter { !deletedShelfNamesBefore.contains($0.name) }
                    .map {
                        self.shelfRestoreFeedbackAction(
                            name: $0.name,
                            rootPath: resolvedRootPath
                        )
                    }
                : []
            let additionalActions = [retryAction].compactMap { $0 } + restoreActions
            let detail = appliedDetailsSnapshot.isEmpty
                ? "0/\(groups.count)"
                : "\(completedKeysSnapshot.count)/\(groups.count): \(appliedDetailsSnapshot.joined(separator: "; "))"
            let warningDetail = [detail, failuresSnapshot.joined(separator: "\n"), postApplyWarningsSnapshot.joined(separator: "\n")]
                .filter { !$0.isEmpty }
                .joined(separator: "\n")
            let operationItems = shelfOperationItems(
                rootPath: resolvedRootPath,
                names: groups.map(\.shelfName),
                states: itemStatesSnapshot,
                details: itemDetailsSnapshot,
                children: itemChildrenSnapshot
            )

            if let conflictSnapshot {
                self.feedbackCenter.warning(
                    sourceIsDeleted ? "Unshelve deleted Shelf changes paused" : "Unshelve Shelf changes paused",
                    detail: warningDetail,
                    nextStep: "Resolve the conflict, then retry the remaining Shelf changes.",
                    additionalActions: additionalActions,
                    notificationID: notificationID
                )
                self.presentShelveConflict(
                    name: conflictSnapshot.name,
                    paths: conflictSnapshot.paths,
                    isPop: false,
                    changeListName: conflictSnapshot.targetName,
                    repository: shelfRepository
                )
            } else if failuresSnapshot.isEmpty && postApplyWarningsSnapshot.isEmpty {
                self.feedbackCenter.success(
                    sourceIsDeleted ? "Deleted Shelf changes unshelved" : "Shelf changes unshelved",
                    detail: detail,
                    additionalActions: restoreActions,
                    notificationID: notificationID
                )
            } else if completedKeysSnapshot.isEmpty {
                self.feedbackCenter.error(
                    sourceIsDeleted ? "Deleted Shelf changes unshelve failed" : "Shelf changes unshelve failed",
                    detail: warningDetail,
                    nextStep: "The selected Shelf changes were kept. Resolve the reported issue and retry.",
                    additionalActions: additionalActions,
                    notificationID: notificationID,
                    localized: true
                )
            } else {
                self.feedbackCenter.warning(
                    "Some Shelf changes were not unshelved",
                    detail: warningDetail,
                    nextStep: "The failed Shelf changes were kept. Retry the remaining groups.",
                    additionalActions: additionalActions,
                    notificationID: notificationID,
                    localized: true
                )
            }
            self.feedbackCenter.attachOperationItems(
                operationItems,
                notificationID: notificationID,
                mergeWithExisting: preservePreviousItems
            )
        }
    }
}

func doShelveUnshelvePathGroupsIntoChangeList(
    _ groups: [ShelfPathDeleteGroup],
    targetName: String,
    removeApplied: Bool = false,
    rootPath: String? = nil
) {
    let trimmedTargetName = targetName.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmedTargetName.isEmpty else { return }
    let uniqueGroups = normalizedShelfPathGroups(groups)
    guard uniqueGroups.count > 1 else { return }
    doShelveUnshelvePathGroups(
        uniqueGroups,
        removeApplied: removeApplied,
        sourceIsDeleted: false,
        targetName: trimmedTargetName,
        rootPath: rootPath
    )
}

/// Drop selected members from several active Shelves as one serialized
/// lifecycle operation. Every successful group remains undoable through one
/// timestamp-preserving batch action.
func doShelveDropPathGroups(
    _ groups: [ShelfPathDeleteGroup],
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let groups = normalizedShelfPathGroups(groups)
    guard !groups.isEmpty else { return }
    let notificationID = shelfMemberBatchNotificationID(
        operation: .drop,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        "Drop Shelf changes",
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    feedbackCenter.updateBatchProgress(
        completed: 0,
        total: groups.count,
        phase: "Drop Shelf Changes"
    )
    Task.detached(priority: .userInitiated) {
        var completedKeys = Set<String>()
        var droppedNames: [String] = []
        var failures: [String] = []
        var restoreNames: [String] = []
        var restoreTimestamps: [String: Int64] = [:]
        var knownDeletedNames = Set((try? shelfRepository.shelveDeletedList().map(\.name)) ?? [])
        var itemStates: [String: FeedbackResultState] = [:]
        var itemDetails: [String: String] = [:]
        var itemChildren: [String: [FeedbackOperationSubitem]] = [:]

        for (index, group) in groups.enumerated() {
            do {
                guard let shelf = try shelfRepository.shelveList().first(where: { $0.name == group.shelfName }) else {
                    throw EngineError.GitOperation(message: "shelve: shelf not found '\(group.shelfName)'")
                }
                try shelfRepository.shelveDropPaths(name: group.shelfName, paths: group.paths)
                completedKeys.insert(shelfPathGroupKey(group))
                droppedNames.append(group.shelfName)
                itemStates[group.shelfName] = .success
                itemDetails[group.shelfName] = "Moved to Recently Deleted"
                itemChildren[group.shelfName] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + group.shelfName,
                    paths: group.paths,
                    state: .success,
                    detail: "Moved to Recently Deleted"
                )
                let currentDeleted = try shelfRepository.shelveDeletedList()
                for deleted in currentDeleted where !knownDeletedNames.contains(deleted.name) {
                    knownDeletedNames.insert(deleted.name)
                    restoreNames.append(deleted.name)
                    restoreTimestamps[deleted.name] = shelf.timestamp
                }
            } catch {
                failures.append("\(group.shelfName): \(errorMessage(error))")
                itemStates[group.shelfName] = .failed
                itemDetails[group.shelfName] = errorMessage(error)
                itemChildren[group.shelfName] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + group.shelfName,
                    paths: group.paths,
                    state: .failed,
                    detail: errorMessage(error)
                )
            }
            await MainActor.run {
                self.feedbackCenter.updateBatchProgress(
                    completed: index + 1,
                    total: groups.count,
                    phase: "Drop Shelf Changes",
                    detail: group.shelfName
                )
            }
        }

        let nextShelves = (try? shelfRepository.shelveList()) ?? []
        let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
        let completedKeysSnapshot = completedKeys
        let droppedNamesSnapshot = droppedNames
        let failuresSnapshot = failures
        let restoreNamesSnapshot = restoreNames
        let restoreTimestampsSnapshot = restoreTimestamps
        let itemStatesSnapshot = itemStates
        let itemDetailsSnapshot = itemDetails
        let itemChildrenSnapshot = itemChildren
        let retryGroups = groups.filter { !completedKeysSnapshot.contains(shelfPathGroupKey($0)) }
        await MainActor.run {
            guard shelfActionRootMatchesCurrentRoot(
                requestedRootPath: resolvedRootPath,
                currentRootPath: self.activeShelfRootPath
            ) else { return }
            self.publishShelfSnapshot(
                rootPath: resolvedRootPath,
                shelves: nextShelves,
                deletedShelves: nextDeletedShelves
            )
            if let previewName = self.shelfPreviewName,
               droppedNamesSnapshot.contains(previewName) {
                self.shelfPreviewName = nil
                self.shelfPreviewText = nil
                self.showShelfPreview = false
            }
            let retryAction = self.shelfMemberBatchRetryFeedbackAction(
                groups: retryGroups,
                operation: .drop,
                rootPath: resolvedRootPath
            )
            let undoAction = self.shelfUndoDeletionsFeedbackAction(
                names: restoreNamesSnapshot,
                originalTimestamps: restoreTimestampsSnapshot,
                rootPath: resolvedRootPath
            )
            let additionalActions = [undoAction, retryAction].compactMap { $0 }
            let detail = droppedNamesSnapshot.isEmpty
                ? "0/\(groups.count)"
                : "\(droppedNamesSnapshot.count)/\(groups.count): \(droppedNamesSnapshot.joined(separator: ", "))"
            let operationItems = shelfOperationItems(
                rootPath: resolvedRootPath,
                names: groups.map(\.shelfName),
                states: itemStatesSnapshot,
                details: itemDetailsSnapshot,
                children: itemChildrenSnapshot
            )
            if failuresSnapshot.isEmpty {
                self.feedbackCenter.success(
                    "Shelf changes dropped",
                    detail: detail,
                    additionalActions: [undoAction].compactMap { $0 },
                    notificationID: notificationID
                )
            } else if droppedNamesSnapshot.isEmpty {
                self.feedbackCenter.error(
                    "Shelf changes drop failed",
                    detail: failuresSnapshot.joined(separator: "\n"),
                    nextStep: "The selected Shelf changes were kept. Resolve the reported issue and retry.",
                    additionalActions: additionalActions,
                    notificationID: notificationID,
                    localized: true
                )
            } else {
                self.feedbackCenter.warning(
                    "Some Shelf changes were dropped",
                    detail: [detail, failuresSnapshot.joined(separator: "\n")].joined(separator: "\n"),
                    nextStep: "Retry the remaining Shelf changes or use Undo to restore the dropped groups.",
                    additionalActions: additionalActions,
                    notificationID: notificationID,
                    localized: true
                )
            }
            self.feedbackCenter.attachOperationItems(
                operationItems,
                notificationID: notificationID,
                mergeWithExisting: preservePreviousItems
            )
        }
    }
}

/// Permanently remove selected members from several Recently Deleted Shelves
/// as one serialized operation with one retryable notification.
func doShelveDeleteDeletedPathGroups(
    _ groups: [ShelfPathDeleteGroup],
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let groups = normalizedShelfPathGroups(groups)
    guard !groups.isEmpty else { return }
    let notificationID = shelfMemberBatchNotificationID(
        operation: .deleteDeleted,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        "Delete deleted Shelf changes permanently",
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    feedbackCenter.updateBatchProgress(
        completed: 0,
        total: groups.count,
        phase: "Delete Shelf Changes"
    )
    Task.detached(priority: .userInitiated) {
        var completedKeys = Set<String>()
        var deletedDetails: [String] = []
        var failures: [String] = []
        var itemStates: [String: FeedbackResultState] = [:]
        var itemDetails: [String: String] = [:]
        var itemChildren: [String: [FeedbackOperationSubitem]] = [:]
        for (index, group) in groups.enumerated() {
            do {
                try shelfRepository.shelveDeleteDeletedPaths(name: group.shelfName, paths: group.paths)
                completedKeys.insert(shelfPathGroupKey(group))
                deletedDetails.append("\(group.shelfName): \(group.paths.joined(separator: ", "))")
                itemStates[group.shelfName] = .success
                itemDetails[group.shelfName] = "Deleted permanently"
                itemChildren[group.shelfName] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + group.shelfName,
                    paths: group.paths,
                    state: .success,
                    detail: "Deleted permanently"
                )
            } catch {
                failures.append("\(group.shelfName): \(errorMessage(error))")
                itemStates[group.shelfName] = .failed
                itemDetails[group.shelfName] = errorMessage(error)
                itemChildren[group.shelfName] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + group.shelfName,
                    paths: group.paths,
                    state: .failed,
                    detail: errorMessage(error)
                )
            }
            await MainActor.run {
                self.feedbackCenter.updateBatchProgress(
                    completed: index + 1,
                    total: groups.count,
                    phase: "Delete Shelf Changes",
                    detail: group.shelfName
                )
            }
        }
        let nextShelves = (try? shelfRepository.shelveList()) ?? []
        let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
        let completedKeysSnapshot = completedKeys
        let deletedDetailsSnapshot = deletedDetails
        let failuresSnapshot = failures
        let itemStatesSnapshot = itemStates
        let itemDetailsSnapshot = itemDetails
        let itemChildrenSnapshot = itemChildren
        let retryGroups = groups.filter { !completedKeysSnapshot.contains(shelfPathGroupKey($0)) }
        await MainActor.run {
            guard shelfActionRootMatchesCurrentRoot(
                requestedRootPath: resolvedRootPath,
                currentRootPath: self.activeShelfRootPath
            ) else { return }
            self.publishShelfSnapshot(
                rootPath: resolvedRootPath,
                shelves: nextShelves,
                deletedShelves: nextDeletedShelves
            )
            let retryAction = self.shelfMemberBatchRetryFeedbackAction(
                groups: retryGroups,
                operation: .deleteDeleted,
                rootPath: resolvedRootPath
            )
            let additionalActions = [retryAction].compactMap { $0 }
            let detail = deletedDetailsSnapshot.isEmpty
                ? "0/\(groups.count)"
                : "\(completedKeysSnapshot.count)/\(groups.count): \(deletedDetailsSnapshot.joined(separator: "; "))"
            let operationItems = shelfOperationItems(
                rootPath: resolvedRootPath,
                names: groups.map(\.shelfName),
                states: itemStatesSnapshot,
                details: itemDetailsSnapshot,
                children: itemChildrenSnapshot
            )
            if failuresSnapshot.isEmpty {
                self.feedbackCenter.success(
                    "Deleted Shelf changes deleted permanently",
                    detail: detail,
                    notificationID: notificationID
                )
            } else if completedKeysSnapshot.isEmpty {
                self.feedbackCenter.error(
                    "Deleted Shelf changes deletion failed",
                    detail: failuresSnapshot.joined(separator: "\n"),
                    nextStep: "The deleted Shelf changes were kept. Resolve the reported issue and retry.",
                    additionalActions: additionalActions,
                    notificationID: notificationID,
                    localized: true
                )
            } else {
                self.feedbackCenter.warning(
                    "Some deleted Shelf changes were deleted",
                    detail: [detail, failuresSnapshot.joined(separator: "\n")].joined(separator: "\n"),
                    nextStep: "Retry the remaining deleted Shelf changes.",
                    additionalActions: additionalActions,
                    notificationID: notificationID,
                    localized: true
                )
            }
            self.feedbackCenter.attachOperationItems(
                operationItems,
                notificationID: notificationID,
                mergeWithExisting: preservePreviousItems
            )
        }
    }
}

/// 仅应用 Shelf 中选中的成员，保留其余成员和整个 Shelf。
func doShelveUnshelvePaths(
    _ name: String,
    _ paths: [String],
    removeApplied: Bool = false,
    selections: [ShelvePatchSelection]? = nil,
    sourceIsDeleted: Bool = false,
    basePath: String? = nil,
    pathStrip: UInt32 = 1,
    rootPath: String? = nil
) {
    guard !paths.isEmpty,
          let context = shelfMutationContext(
              rootPath: rootPath,
              activeRootPath: activeShelfRootPath,
              primaryRootPath: primaryShelfRootPath,
              primaryRepository: repo,
              secondaryRepository: shelfRootRepository
          ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let scopedDeletedShelves = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    ) ? deletedShelves : activeDeletedShelfList
    let deletedShelfNamesBefore = Set(scopedDeletedShelves.map { $0.name })
    beginFeedbackOperation("Unshelve changes")
    Task.detached(priority: .userInitiated) {
        var operationItem: FeedbackOperationItem?
        do {
            let sourceShelves = sourceIsDeleted
                ? (try shelfRepository.shelveDeletedList())
                : (try shelfRepository.shelveList())
            guard let shelf = sourceShelves.first(where: { $0.name == name }) else {
                throw EngineError.GitOperation(message: "shelve: shelf not found '\(name)'")
            }
            let targetChangeList = try automaticUnshelveTarget(for: shelf, repo: shelfRepository)
            let appliedPaths: [String]
            var engineFailedPaths = Set<String>()
            var applyResult: PatchApplyResult?
            let mappedBasePath = basePath?.trimmingCharacters(in: .whitespacesAndNewlines)
            let hasPathMapping = (mappedBasePath?.isEmpty == false) || pathStrip != 1
            if let selections, !selections.isEmpty {
                guard !sourceIsDeleted else {
                    throw EngineError.GitOperation(
                        message: "shelve: hunk selection is not available for Recently Deleted members"
                    )
                }
                if hasPathMapping {
                    appliedPaths = try shelfRepository.shelveUnshelveSelectionsWithOptionsAndBase(
                        name: name,
                        selections: selections,
                        removeApplied: removeApplied,
                        basePath: mappedBasePath ?? "",
                        pathStrip: pathStrip
                    )
                } else {
                    let result = try shelfRepository.shelveUnshelveSelectionsWithOptionsDifferentiated(
                        name: name,
                        selections: selections,
                        removeApplied: removeApplied
                    )
                    applyResult = result
                    appliedPaths = result.appliedPaths
                    engineFailedPaths = Set(result.failedPaths)
                }
            } else {
                if sourceIsDeleted {
                    if hasPathMapping {
                        appliedPaths = try shelfRepository.shelveUnshelveDeletedPathsWithOptionsAndBase(
                            name: name,
                            paths: paths,
                            removeApplied: removeApplied,
                            basePath: mappedBasePath ?? "",
                            pathStrip: pathStrip
                        )
                    } else {
                        let result = try shelfRepository.shelveUnshelveDeletedPathsWithOptionsDifferentiated(
                            name: name,
                            paths: paths,
                            removeApplied: removeApplied
                        )
                        applyResult = result
                        appliedPaths = result.appliedPaths
                        engineFailedPaths = Set(result.failedPaths)
                    }
                } else {
                    if hasPathMapping {
                        appliedPaths = try shelfRepository.shelveUnshelvePathsWithOptionsAndBase(
                            name: name,
                            paths: paths,
                            removeApplied: removeApplied,
                            basePath: mappedBasePath ?? "",
                            pathStrip: pathStrip
                        )
                    } else {
                        let result = try shelfRepository.shelveUnshelvePathsWithOptionsDifferentiated(
                            name: name,
                            paths: paths,
                            removeApplied: removeApplied
                        )
                        applyResult = result
                        appliedPaths = result.appliedPaths
                        engineFailedPaths = Set(result.failedPaths)
                    }
                }
            }
            let requestedPaths = selections?.map(\.path) ?? paths
            let requestedPathSet = Set(requestedPaths)
            let appliedPathSet = Set(appliedPaths).intersection(requestedPathSet)
            let failedPathSet = requestedPathSet
                .subtracting(appliedPathSet)
                .union(engineFailedPaths)
            if let applyResult {
                operationItem = FeedbackOperationItem(
                    scope: resolvedRootPath,
                    name: name,
                    state: patchApplyFeedbackState(applyResult),
                    detail: patchApplySummary(
                        applyResult,
                        successDetail: "Shelf changes unshelved",
                        failureDetail: "\(appliedPathSet.count) applied, \(failedPathSet.count) not applied"
                    ),
                    children: shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + name,
                        paths: requestedPaths,
                        result: applyResult,
                        successDetail: "Applied",
                        failureDetail: "Not applied"
                    )
                )
            } else {
                operationItem = FeedbackOperationItem(
                    scope: resolvedRootPath,
                    name: name,
                    state: failedPathSet.isEmpty ? .success : .failed,
                    detail: failedPathSet.isEmpty
                        ? "Shelf changes unshelved"
                        : "\(appliedPathSet.count) applied, \(failedPathSet.count) not applied",
                    children: shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + name,
                        paths: requestedPaths,
                        appliedPaths: appliedPathSet,
                        failedPaths: failedPathSet,
                        successDetail: "Applied",
                        failureDetail: "Not applied"
                    )
                )
            }
            let needsAttention = applyResult.map(patchApplyNeedsAttention) ?? !failedPathSet.isEmpty
            let st = try shelfRepository.status()
            try assignUnshelvedPaths(appliedPaths, to: targetChangeList, status: st, repo: shelfRepository)
            let cls = (try? shelfRepository.changelistList()) ?? []
            let ss = try shelfRepository.shelveList()
            let dsh = (try? shelfRepository.shelveDeletedList()) ?? []
            let operationItemSnapshot = operationItem
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                let isPrimaryRoot = shelfRootSelectionIsPrimary(
                    selectedRootPath: resolvedRootPath,
                    primaryRootPath: self.primaryShelfRootPath
                )
                if isPrimaryRoot {
                    self.entries = st
                    self.changeLists = cls
                }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: ss,
                    deletedShelves: dsh,
                    changeLists: cls
                )
                self.refreshAfterShelfMutation(
                    repo: shelfRepository,
                    paths: appliedPaths,
                    metadataChanged: removeApplied || sourceIsDeleted
                )
                if !isPrimaryRoot {
                    self.refreshAll(showFeedback: false)
                }
                let restoredName = removeApplied
                    ? dsh.first(where: { !deletedShelfNamesBefore.contains($0.name) })?.name
                    : nil
                let detail = targetChangeList.map { "\(name) → \($0)" } ?? paths.joined(separator: ", ")
                let notificationID = self.shelfBatchNotificationID(
                    operation: .apply,
                    rootPath: resolvedRootPath
                )
                if let restoredName {
                    let restoreAction = self.shelfRestoreFeedbackAction(
                        name: restoredName,
                        rootPath: resolvedRootPath
                    )
                    if !needsAttention {
                        self.feedbackCenter.success(
                            "Shelf changes unshelved and removed",
                            detail: detail,
                            additionalActions: [restoreAction],
                            notificationID: notificationID
                        )
                    } else {
                        self.feedbackCenter.warning(
                            "Shelf changes partially unshelved",
                            detail: "\(detail): \(appliedPathSet.count) applied, \(failedPathSet.count) not applied",
                            nextStep: "Review the failed Shelf members and retry them separately.",
                            additionalActions: [restoreAction],
                            notificationID: notificationID
                        )
                    }
                } else if !needsAttention {
                    self.feedbackCenter.success(
                        "Shelf changes unshelved",
                        detail: detail,
                        notificationID: notificationID
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Shelf changes partially unshelved",
                        detail: "\(detail): \(appliedPathSet.count) applied, \(failedPathSet.count) not applied",
                        nextStep: "Review the failed Shelf members and retry them separately.",
                        notificationID: notificationID
                    )
                }
                self.feedbackCenter.attachOperationItems(
                    [operationItemSnapshot].compactMap { $0 },
                    notificationID: notificationID
                )
            }
        } catch {
            let requestedPaths = selections?.map(\.path) ?? paths
            let operationItemSnapshot = operationItem
            if case let .ShelveApplyConflict(conflictName, conflictPaths) = error as? EngineError {
                if GitChangelistSettings.createAutomatically(from: .standard),
                   let shelf = try? (sourceIsDeleted
                       ? shelfRepository.shelveDeletedList()
                       : shelfRepository.shelveList()).first(where: { $0.name == conflictName }),
                       let target = try? automaticUnshelveTarget(for: shelf, repo: shelfRepository) {
                    _ = try? shelfRepository.shelveSetRestoreTarget(name: conflictName, targetChangeList: target)
                }
                await MainActor.run {
                    let notificationID = self.shelfBatchNotificationID(
                        operation: .apply,
                        rootPath: resolvedRootPath
                    )
                    self.presentShelveConflict(
                        name: conflictName,
                        paths: conflictPaths,
                        isPop: false,
                        repository: shelfRepository,
                        notificationID: notificationID
                    )
                    self.feedbackCenter.attachOperationItems(
                        [FeedbackOperationItem(
                            scope: resolvedRootPath,
                            name: name,
                            state: .failed,
                            detail: "Conflict paused: \(conflictPaths.joined(separator: ", "))",
                            children: shelfOperationSubitems(
                                scope: resolvedRootPath + "\u{1f}" + name,
                                paths: requestedPaths,
                                appliedPaths: [],
                                failedPaths: Set(conflictPaths),
                                successDetail: "Applied",
                                failureDetail: "Conflict paused"
                            )
                        )],
                        notificationID: notificationID
                    )
                }
            } else {
                await MainActor.run {
                    let notificationID = self.shelfBatchNotificationID(
                        operation: .apply,
                        rootPath: resolvedRootPath
                    )
                    self.feedbackCenter.error(
                        "Unshelve selected changes failed",
                        detail: errorMessage(error),
                        nextStep: "The shelf was kept. Resolve any local conflict, then try the member again.",
                        notificationID: notificationID
                    )
                    let item = operationItemSnapshot.map {
                        FeedbackOperationItem(
                            scope: $0.scope,
                            name: $0.name,
                            state: .failed,
                            detail: "Shelf apply completed, but post-apply bookkeeping failed: \(errorMessage(error))",
                            children: $0.children
                        )
                    } ?? FeedbackOperationItem(
                        scope: resolvedRootPath,
                        name: name,
                        state: .failed,
                        detail: errorMessage(error),
                        children: shelfOperationSubitems(
                            scope: resolvedRootPath + "\u{1f}" + name,
                            paths: requestedPaths,
                            state: .failed,
                            detail: errorMessage(error)
                        )
                    )
                    self.feedbackCenter.attachOperationItems(
                        [item],
                        notificationID: notificationID
                    )
                }
            }
        }
    }
}

/// Apply selected text hunks from a Shelf while preserving the same
/// automatic Changelist and conflict-recovery behavior as file selection.
func doShelveUnshelveSelections(
    _ name: String,
    selections: [ShelvePatchSelection],
    removeApplied: Bool = false,
    basePath: String? = nil,
    pathStrip: UInt32 = 1,
    rootPath: String? = nil
) {
    guard !selections.isEmpty else { return }
    var paths: [String] = []
    var seen = Set<String>()
    for selection in selections where seen.insert(selection.path).inserted {
        paths.append(selection.path)
    }
    doShelveUnshelvePaths(
        name,
        paths,
        removeApplied: removeApplied,
        selections: selections,
        basePath: basePath,
        pathStrip: pathStrip,
        rootPath: rootPath
    )
}

/// Apply multiple ShelvedChangeLists serially. An explicit target mirrors
/// UnshelveWithDialogAction; a nil target mirrors ChangesView.UnshelveSilently
/// and lets the automatic Changelist setting choose a destination per Shelf.
/// Serial execution is intentional because all lists modify one worktree and
/// the Rust engine persists one conflict restore snapshot per repository.
nonisolated private func shelfOperationItems(
    rootPath: String,
    names: [String],
    states: [String: FeedbackResultState],
    details: [String: String],
    children: [String: [FeedbackOperationSubitem]] = [:]
) -> [FeedbackOperationItem] {
    names.map { name in
        FeedbackOperationItem(
            scope: rootPath,
            name: name,
            state: states[name] ?? .skipped,
            detail: details[name] ?? "Not attempted",
            children: children[name] ?? []
        )
    }
}

nonisolated private func shelfOperationSubitems(
    scope: String,
    paths: [String],
    result: PatchApplyResult,
    successDetail: String,
    failureDetail: String,
    skippedDetail: String = "Not attempted"
) -> [FeedbackOperationSubitem] {
    var statuses: [String: PatchApplyStatus] = [:]
    for member in result.memberStatuses {
        statuses[member.path] = member.status
    }
    var seen = Set<String>()
    return paths.filter { seen.insert($0).inserted }.map { path in
        let status = statuses[path] ?? .skip
        let state: FeedbackResultState
        let detail: String
        switch status {
        case .success:
            state = .success
            detail = successDetail
        case .alreadyApplied:
            state = .success
            detail = "Already applied"
        case .partial:
            state = .partial
            detail = "Partially applied"
        case .failure:
            state = .failed
            detail = failureDetail
        case .skip:
            state = .skipped
            detail = skippedDetail
        case .abort:
            state = .aborted
            detail = "Aborted"
        }
        return FeedbackOperationSubitem(
            scope: scope,
            path: path,
            state: state,
            detail: detail
        )
    }
}

nonisolated private func patchApplyFeedbackState(
    _ result: PatchApplyResult
) -> FeedbackResultState {
    switch result.overallStatus {
    case .skip:
        .skipped
    case .failure:
        .failed
    case .abort:
        .aborted
    case .success, .alreadyApplied:
        .success
    case .partial:
        .partial
    }
}

nonisolated private func patchApplyNeedsAttention(
    _ result: PatchApplyResult
) -> Bool {
    !result.failedPaths.isEmpty
        || result.overallStatus == .partial
        || result.overallStatus == .failure
        || result.overallStatus == .abort
}

nonisolated private func patchApplySummary(
    _ result: PatchApplyResult,
    successDetail: String,
    failureDetail: String
) -> String {
    switch result.overallStatus {
    case .success:
        successDetail
    case .alreadyApplied:
        "Already applied"
    case .partial:
        "Partially applied: \(result.appliedPaths.count) applied, \(result.failedPaths.count) not applied"
    case .failure:
        failureDetail
    case .skip:
        "Not attempted"
    case .abort:
        "Aborted"
    }
}

nonisolated private func shelfOperationSubitems(
    scope: String,
    paths: [String],
    state: FeedbackResultState,
    detail: String
) -> [FeedbackOperationSubitem] {
    var seen = Set<String>()
    return paths.filter { seen.insert($0).inserted }.map {
        FeedbackOperationSubitem(
            scope: scope,
            path: $0,
            state: state,
            detail: detail
        )
    }
}

nonisolated private func shelfOperationSubitems(
    scope: String,
    paths: [String],
    appliedPaths: Set<String>,
    failedPaths: Set<String>,
    successDetail: String,
    failureDetail: String,
    skippedDetail: String = "Not attempted"
) -> [FeedbackOperationSubitem] {
    var seen = Set<String>()
    return paths.filter { seen.insert($0).inserted }.map { path in
        let state: FeedbackResultState
        let detail: String
        if failedPaths.contains(path) {
            state = .failed
            detail = failureDetail
        } else if appliedPaths.contains(path) {
            state = .success
            detail = successDetail
        } else {
            state = .skipped
            detail = skippedDetail
        }
        return FeedbackOperationSubitem(
            scope: scope,
            path: path,
            state: state,
            detail: detail
        )
    }
}

private func doShelveUnshelveShelves(
    _ names: [String],
    targetName: String?,
    removeApplied: Bool = false,
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let explicitTargetName = targetName?.trimmingCharacters(in: .whitespacesAndNewlines)
    if targetName != nil, explicitTargetName?.isEmpty != false { return }

    var seenNames = Set<String>()
    let uniqueNames = names
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty && seenNames.insert($0).inserted }
    guard !uniqueNames.isEmpty else { return }

    let isSilent = explicitTargetName == nil
    let scopedDeletedShelves = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    ) ? deletedShelves : activeDeletedShelfList
    let deletedShelfNamesBefore = Set(scopedDeletedShelves.map { $0.name })
    let notificationID = shelfBatchNotificationID(
        operation: .apply,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        isSilent ? "Unshelve shelves silently" : "Unshelve selected shelves",
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    feedbackCenter.updateBatchProgress(
        completed: 0,
        total: uniqueNames.count,
        phase: "Unshelve Shelf"
    )
    Task.detached(priority: .userInitiated) {
        do {
            let lists = try shelfRepository.changelistList()
            if let explicitTargetName,
               !lists.contains(where: { $0.name == explicitTargetName }) {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Move changes failed",
                        detail: explicitTargetName,
                        notificationID: self.shelfBatchNotificationID(
                            operation: .apply,
                            rootPath: resolvedRootPath
                        )
                    )
                }
                return
            }

            var appliedNames: [String] = []
            var appliedDetails: [String] = []
            var mutatedPaths: [String] = []
            var failureMessages: [String] = []
            var postApplyWarnings: [String] = []
            var itemStates: [String: FeedbackResultState] = [:]
            var itemDetails: [String: String] = [:]
            var itemChildren: [String: [FeedbackOperationSubitem]] = [:]
            var conflict: (name: String, paths: [String], targetName: String?)?

            for (index, name) in uniqueNames.enumerated() {
                var currentTargetName: String?
                var didApply = false
                var shelfPaths: [String] = []
                do {
                    let activeShelf = try shelfRepository.shelveList().first(where: { $0.name == name })
                    let deletedShelf = activeShelf == nil
                        ? try shelfRepository.shelveDeletedList().first(where: { $0.name == name })
                        : nil
                    guard let shelf = activeShelf ?? deletedShelf else {
                        throw EngineError.GitOperation(message: "shelve: shelf not found '\(name)'")
                    }
                    shelfPaths = shelf.paths
                    if let explicitTargetName {
                        currentTargetName = explicitTargetName
                    } else {
                        currentTargetName = try automaticUnshelveTarget(for: shelf, repo: shelfRepository)
                    }
                    let applyResult: PatchApplyResult
                    if activeShelf != nil {
                        applyResult = try shelfRepository.shelveUnshelveWithOptionsDifferentiated(
                            name: name,
                            removeApplied: removeApplied
                        )
                    } else {
                        applyResult = try shelfRepository.shelveUnshelveDeletedWithOptionsDifferentiated(
                            name: name,
                            removeApplied: removeApplied
                        )
                    }
                    let appliedPaths = applyResult.appliedPaths
                    let failedPaths = applyResult.failedPaths
                    mutatedPaths.append(contentsOf: appliedPaths)
                    if !appliedPaths.isEmpty {
                        appliedNames.append(name)
                        appliedDetails.append(
                            currentTargetName.map { "\(name) → \($0)" } ?? name
                        )
                    }
                    itemStates[name] = patchApplyFeedbackState(applyResult)
                    itemDetails[name] = patchApplySummary(
                        applyResult,
                        successDetail: currentTargetName.map { "Applied → \($0)" } ?? "Applied",
                        failureDetail: "\(appliedPaths.count) applied, \(failedPaths.count) not applied"
                    )
                    itemChildren[name] = shelfOperationSubitems(
                        scope: resolvedRootPath + "\u{1f}" + name,
                        paths: shelfPaths,
                        result: applyResult,
                        successDetail: currentTargetName.map { "Applied → \($0)" } ?? "Applied",
                        failureDetail: "Not applied"
                    )
                    didApply = !appliedPaths.isEmpty
                    if patchApplyNeedsAttention(applyResult) {
                        failureMessages.append(
                            "\(name): \(appliedPaths.count) applied, \(failedPaths.count) not applied"
                        )
                    }
                    let status = try shelfRepository.status()
                    try assignUnshelvedPaths(
                        appliedPaths,
                        to: currentTargetName,
                        status: status,
                        repo: shelfRepository
                    )
                } catch {
                    if case let .ShelveApplyConflict(conflictName, paths) = error as? EngineError {
                        if let currentTargetName {
                            _ = try? shelfRepository.shelveSetRestoreTarget(
                                name: conflictName,
                                targetChangeList: currentTargetName
                            )
                        }
                        conflict = (conflictName, paths, currentTargetName)
                        itemStates[conflictName] = .failed
                        itemDetails[conflictName] = "Conflict paused: \(paths.joined(separator: ", "))"
                        itemChildren[conflictName] = shelfOperationSubitems(
                            scope: resolvedRootPath + "\u{1f}" + conflictName,
                            paths: shelfPaths,
                            appliedPaths: [],
                            failedPaths: Set(paths),
                            successDetail: "Applied",
                            failureDetail: "Conflict paused"
                        )
                        await MainActor.run {
                            self.feedbackCenter.updateBatchProgress(
                                completed: index + 1,
                                total: uniqueNames.count,
                                phase: "Unshelve Shelf",
                                detail: conflictName
                            )
                        }
                        break
                    }
                    if didApply {
                        itemStates[name] = .success
                        itemDetails[name] = "Applied, but Changelist assignment failed: \(errorMessage(error))"
                        itemChildren[name] = shelfOperationSubitems(
                            scope: resolvedRootPath + "\u{1f}" + name,
                            paths: shelfPaths,
                            state: .success,
                            detail: "Applied, but Changelist assignment failed"
                        )
                        postApplyWarnings.append(
                            "\(name): applied, but final Changelist assignment failed: \(errorMessage(error))"
                        )
                    } else {
                        itemStates[name] = .failed
                        itemDetails[name] = errorMessage(error)
                        itemChildren[name] = shelfOperationSubitems(
                            scope: resolvedRootPath + "\u{1f}" + name,
                            paths: shelfPaths,
                            state: .failed,
                            detail: errorMessage(error)
                        )
                        failureMessages.append("\(name): \(errorMessage(error))")
                    }
                }
                await MainActor.run {
                    self.feedbackCenter.updateBatchProgress(
                        completed: index + 1,
                        total: uniqueNames.count,
                        phase: "Unshelve Shelf",
                        detail: name
                    )
                }
            }

            let finalStatus = (try? shelfRepository.status()) ?? []
            let nextChangeLists = (try? shelfRepository.changelistList()) ?? []
            let nextShelves = (try? shelfRepository.shelveList()) ?? []
            let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
            let appliedNamesSnapshot = appliedNames
            let appliedDetailsSnapshot = appliedDetails
            let mutatedPathsSnapshot = mutatedPaths
            let failureMessagesSnapshot = failureMessages
            let postApplyWarningsSnapshot = postApplyWarnings
            let itemStatesSnapshot = itemStates
            let itemDetailsSnapshot = itemDetails
            let itemChildrenSnapshot = itemChildren
            let conflictSnapshot = conflict
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                let isPrimaryRoot = shelfRootSelectionIsPrimary(
                    selectedRootPath: resolvedRootPath,
                    primaryRootPath: self.primaryShelfRootPath
                )
                if isPrimaryRoot {
                    self.entries = finalStatus
                    self.changeLists = nextChangeLists
                }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: nextShelves,
                    deletedShelves: nextDeletedShelves,
                    changeLists: nextChangeLists
                )
                self.refreshAfterShelfMutation(
                    repo: shelfRepository,
                    paths: mutatedPathsSnapshot,
                    metadataChanged: removeApplied
                )
                if !isPrimaryRoot {
                    self.refreshAll(showFeedback: false)
                }

                let retryNames = uniqueNames.filter {
                    itemStatesSnapshot[$0] != .success && $0 != conflictSnapshot?.name
                }
                let retryAction = self.shelfBatchRetryFeedbackAction(
                    names: retryNames,
                    operation: .apply,
                    targetName: explicitTargetName,
                    removeApplied: removeApplied,
                    rootPath: resolvedRootPath
                )
                let operationItems = shelfOperationItems(
                    rootPath: resolvedRootPath,
                    names: uniqueNames,
                    states: itemStatesSnapshot,
                    details: itemDetailsSnapshot,
                    children: itemChildrenSnapshot
                )
                let destination = isSilent
                    ? (appliedDetailsSnapshot.isEmpty
                        ? "0/\(uniqueNames.count)"
                        : appliedDetailsSnapshot.joined(separator: ", "))
                    : "\(appliedNamesSnapshot.count)/\(uniqueNames.count) → \(explicitTargetName ?? "")"
                let restoreActions = removeApplied
                        ? nextDeletedShelves
                            .filter { !deletedShelfNamesBefore.contains($0.name) }
                            .map {
                                self.shelfRestoreFeedbackAction(
                                    name: $0.name,
                                    rootPath: resolvedRootPath
                                )
                            }
                    : []
                if let conflictSnapshot {
                    let failures = failureMessagesSnapshot.isEmpty
                        ? postApplyWarningsSnapshot.isEmpty
                            ? nil
                            : postApplyWarningsSnapshot.joined(separator: "\n")
                        : (failureMessagesSnapshot + postApplyWarningsSnapshot)
                            .joined(separator: "\n")
                    self.feedbackCenter.warning(
                        isSilent ? "Unshelve shelves silently paused" : "Unshelve selected shelves paused",
                        detail: [destination, failures].compactMap { $0 }.joined(separator: "\n"),
                        additionalActions: [retryAction].compactMap { $0 } + restoreActions,
                        notificationID: notificationID
                    )
                    self.presentShelveConflict(
                        name: conflictSnapshot.name,
                        paths: conflictSnapshot.paths,
                        isPop: false,
                        changeListName: conflictSnapshot.targetName,
                        repository: shelfRepository
                    )
                } else if failureMessagesSnapshot.isEmpty && postApplyWarningsSnapshot.isEmpty {
                    self.feedbackCenter.success(
                        isSilent ? "Shelves unshelved silently" : "Shelves unshelved",
                        detail: destination,
                        additionalActions: restoreActions,
                        notificationID: notificationID
                    )
                } else if appliedNamesSnapshot.isEmpty {
                    self.feedbackCenter.error(
                        isSilent ? "Unshelve shelves silently failed" : "Unshelve selected shelves failed",
                        detail: (failureMessagesSnapshot + postApplyWarningsSnapshot)
                            .joined(separator: "\n"),
                        nextStep: "The remaining shelves were kept. Resolve the local issue, then retry.",
                        additionalActions: [retryAction].compactMap { $0 },
                        notificationID: notificationID,
                        localized: true
                    )
                } else if failureMessagesSnapshot.isEmpty {
                    self.feedbackCenter.warning(
                        "Shelves applied with warnings",
                        detail: [
                            destination,
                            postApplyWarningsSnapshot.joined(separator: "\n")
                        ].joined(separator: "\n"),
                        additionalActions: [retryAction].compactMap { $0 } + restoreActions,
                        notificationID: notificationID
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Some shelves were not unshelved",
                        detail: [
                            destination,
                            (failureMessagesSnapshot + postApplyWarningsSnapshot)
                                .joined(separator: "\n")
                        ]
                            .joined(separator: "\n"),
                        additionalActions: [retryAction].compactMap { $0 } + restoreActions,
                        notificationID: notificationID
                    )
                }
                self.feedbackCenter.attachOperationItems(
                    operationItems,
                    notificationID: notificationID,
                    mergeWithExisting: preservePreviousItems
                )
            }
        } catch {
            await MainActor.run {
                let retryAction = self.shelfBatchRetryFeedbackAction(
                    names: uniqueNames,
                    operation: .apply,
                    targetName: explicitTargetName,
                    removeApplied: removeApplied,
                    rootPath: resolvedRootPath
                )
                let notificationID = self.shelfBatchNotificationID(
                    operation: .apply,
                    rootPath: resolvedRootPath
                )
                self.feedbackCenter.error(
                    isSilent ? "Unshelve shelves silently failed" : "Unshelve selected shelves failed",
                    detail: errorMessage(error),
                    nextStep: "The shelves were kept. Resolve the local issue, then retry.",
                    additionalActions: [retryAction].compactMap { $0 },
                    notificationID: notificationID,
                    localized: true
                )
                self.feedbackCenter.attachOperationItems(
                    uniqueNames.map {
                        FeedbackOperationItem(
                            scope: resolvedRootPath,
                            name: $0,
                            state: .failed,
                            detail: errorMessage(error)
                        )
                    },
                    notificationID: notificationID,
                    mergeWithExisting: preservePreviousItems
                )
            }
        }
    }
}

func doShelveUnshelveShelvesIntoChangeList(
    _ names: [String],
    targetName: String,
    removeApplied: Bool = false,
    rootPath: String? = nil
) {
    let trimmedTargetName = targetName.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmedTargetName.isEmpty else { return }
    var seenNames = Set<String>()
    let uniqueNames = names.filter { seenNames.insert($0).inserted }
    guard uniqueNames.count > 1 else { return }
    doShelveUnshelveShelves(
        uniqueNames,
        targetName: trimmedTargetName,
        removeApplied: removeApplied,
        rootPath: rootPath
    )
}

func doShelveUnshelveSilently(
    _ names: [String],
    removeApplied: Bool = false,
    rootPath: String? = nil
) {
    doShelveUnshelveShelves(
        names,
        targetName: nil,
        removeApplied: removeApplied,
        rootPath: rootPath
    )
}

/// Permanently remove recycled Shelf lists through the explicit IntelliJ
/// "clean already unshelved" action. This does not touch active or Recently
/// Deleted shelves; the engine owns the lifecycle cutoff and ref cleanup.
func cleanRecycledShelves(rootPath: String? = nil) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let cutoff = Int64(Date().timeIntervalSince1970)
    let notificationID = shelfMetadataNotificationID(
        operation: "clean",
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        "Clear Already Unshelved",
        notificationID: notificationID
    )
    Task.detached(priority: .userInitiated) {
        do {
            let cleaned = try shelfRepository.shelveCleanRecycled(beforeTimestamp: cutoff)
            let nextShelves = try shelfRepository.shelveList()
            let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: nextShelves,
                    deletedShelves: nextDeletedShelves
                )
                if cleaned.isEmpty {
                    self.feedbackCenter.warning(
                        "No already unshelved shelves to clear",
                        notificationID: notificationID
                    )
                } else {
                    self.feedbackCenter.success(
                        "Already unshelved shelves cleared",
                        detail: cleaned.joined(separator: ", "),
                        notificationID: notificationID
                    )
                }
            }
        } catch {
            let nextShelves = (try? shelfRepository.shelveList()) ?? []
            let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: nextShelves,
                    deletedShelves: nextDeletedShelves
                )
                self.feedbackCenter.error(
                    "Clear already unshelved shelves failed",
                    detail: errorMessage(error),
                    nextStep: "The remaining shelves were kept. Retry the cleanup when the repository is ready.",
                    notificationID: notificationID
                )
            }
        }
    }
}

/// Apply a whole Shelf or selected Shelf members directly into a local
/// Changelist. This is the Changes Browser target-list drop path; unlike a
/// generic group drop it keeps the Shelf apply and Changelist assignment as
/// one user-visible operation.
func doShelveUnshelveIntoChangeList(
    _ name: String,
    paths: [String]?,
    selections: [ShelvePatchSelection]? = nil,
    targetName: String,
    removeApplied: Bool? = nil,
    basePath: String? = nil,
    pathStrip: UInt32 = 1,
    rootPath: String? = nil
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let targetName = targetName.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !targetName.isEmpty else { return }
    let selectedPaths = paths?.filter { !$0.isEmpty }
    let selectedSelections = selections?.filter { !$0.path.isEmpty }
    let shouldRemoveApplied = removeApplied
        ?? ShelfViewSettings.removeAppliedFilesFromShelf(for: projectPath)
    let scopedDeletedShelves = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    ) ? deletedShelves : activeDeletedShelfList
    let deletedShelfNamesBefore = Set(scopedDeletedShelves.map { $0.name })
    beginFeedbackOperation("Unshelve changes")
    Task.detached(priority: .userInitiated) {
        do {
            let lists = try shelfRepository.changelistList()
            guard lists.contains(where: { $0.name == targetName }) else {
                await MainActor.run {
                    self.feedbackCenter.error("Move changes failed", detail: targetName)
                }
                return
            }

            guard let shelf = try shelfRepository.shelveList().first(where: { $0.name == name }) else {
                await MainActor.run {
                    self.feedbackCenter.error("Unshelve failed", detail: name)
                }
                return
            }
            let requestedPaths = selectedSelections?.map(\.path) ?? selectedPaths ?? shelf.paths
            guard !requestedPaths.isEmpty else {
                await MainActor.run {
                    self.feedbackCenter.error("Unshelve failed", detail: name)
                }
                return
            }

            let appliedPaths: [String]
            var engineFailedPaths = Set<String>()
            var applyResult: PatchApplyResult?
            do {
                let mappedBasePath = basePath?.trimmingCharacters(in: .whitespacesAndNewlines)
                let hasPathMapping = (mappedBasePath?.isEmpty == false) || pathStrip != 1
                if hasPathMapping {
                    if let selectedSelections, !selectedSelections.isEmpty {
                        appliedPaths = try shelfRepository.shelveUnshelveSelectionsWithOptionsAndBase(
                            name: name,
                            selections: selectedSelections,
                            removeApplied: shouldRemoveApplied,
                            basePath: mappedBasePath ?? "",
                            pathStrip: pathStrip
                        )
                    } else {
                        appliedPaths = try shelfRepository.shelveUnshelvePathsWithOptionsAndBase(
                            name: name,
                            paths: selectedPaths ?? shelf.paths,
                            removeApplied: shouldRemoveApplied,
                            basePath: mappedBasePath ?? "",
                            pathStrip: pathStrip
                        )
                    }
                } else if let selectedSelections, !selectedSelections.isEmpty {
                    let result = try shelfRepository.shelveUnshelveSelectionsWithOptionsDifferentiated(
                        name: name,
                        selections: selectedSelections,
                        removeApplied: shouldRemoveApplied
                    )
                    applyResult = result
                    appliedPaths = result.appliedPaths
                    engineFailedPaths = Set(result.failedPaths)
                } else if let selectedPaths {
                    let result = try shelfRepository.shelveUnshelvePathsWithOptionsDifferentiated(
                        name: name,
                        paths: selectedPaths,
                        removeApplied: shouldRemoveApplied
                    )
                    applyResult = result
                    appliedPaths = result.appliedPaths
                    engineFailedPaths = Set(result.failedPaths)
                } else {
                    let result = try shelfRepository.shelveUnshelveWithOptionsDifferentiated(
                        name: name,
                        removeApplied: shouldRemoveApplied
                    )
                    applyResult = result
                    appliedPaths = result.appliedPaths
                    engineFailedPaths = Set(result.failedPaths)
                }
            } catch {
                if case let .ShelveApplyConflict(conflictName, conflictPaths) = error as? EngineError {
                    // The target is also persisted in the Rust snapshot so a
                    // resolver restored after relaunch can finish the same
                    // drag operation.
                    _ = try? shelfRepository.shelveSetRestoreTarget(
                        name: conflictName,
                        targetChangeList: targetName
                    )
                    await MainActor.run {
                        self.presentShelveConflict(
                            name: conflictName,
                            paths: conflictPaths,
                            isPop: false,
                            changeListName: targetName,
                            repository: shelfRepository
                        )
                    }
                } else {
                    await MainActor.run {
                        self.feedbackCenter.error(
                            "Unshelve failed",
                            detail: errorMessage(error),
                            nextStep: "The shelf was kept. Resolve the local conflict, then retry."
                        )
                    }
                }
                return
            }

            let status = try shelfRepository.status()
            let currentPaths = Set(status.map(\.path))
            let assignablePaths = appliedPaths.filter(currentPaths.contains)
            do {
                if !assignablePaths.isEmpty {
                    try shelfRepository.changelistMovePaths(paths: assignablePaths, targetName: targetName)
                }
            } catch {
                await MainActor.run {
                    self.feedbackCenter.error("Move changes failed", detail: targetName)
                }
                return
            }

            let nextChangeLists = try shelfRepository.changelistList()
            let nextShelves = try shelfRepository.shelveList()
            let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
            let failedPaths = Set(requestedPaths)
                .subtracting(Set(appliedPaths))
                .union(engineFailedPaths)
            let feedbackApplyResult = applyResult
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                let isPrimaryRoot = shelfRootSelectionIsPrimary(
                    selectedRootPath: resolvedRootPath,
                    primaryRootPath: self.primaryShelfRootPath
                )
                if isPrimaryRoot {
                    self.entries = status
                    self.changeLists = nextChangeLists
                }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: nextShelves,
                    deletedShelves: nextDeletedShelves,
                    changeLists: nextChangeLists
                )
                self.refreshAfterShelfMutation(
                    repo: shelfRepository,
                    paths: appliedPaths,
                    metadataChanged: shouldRemoveApplied
                )
                if !isPrimaryRoot {
                    self.refreshAll(showFeedback: false)
                }
                let restoredName = shouldRemoveApplied
                    ? nextDeletedShelves.first(where: { !deletedShelfNamesBefore.contains($0.name) })?.name
                    : nil
                let detail = "\(name) → \(targetName)"
                let operationItem: FeedbackOperationItem
                if let applyResult = feedbackApplyResult {
                    operationItem = FeedbackOperationItem(
                        scope: resolvedRootPath,
                        name: name,
                        state: patchApplyFeedbackState(applyResult),
                        detail: patchApplySummary(
                            applyResult,
                            successDetail: "Applied → \(targetName)",
                            failureDetail: "\(appliedPaths.count) applied, \(failedPaths.count) not applied"
                        ),
                        children: shelfOperationSubitems(
                            scope: resolvedRootPath + "\u{1f}" + name,
                            paths: requestedPaths,
                            result: applyResult,
                            successDetail: "Applied",
                            failureDetail: "Not applied"
                        )
                    )
                } else {
                    operationItem = FeedbackOperationItem(
                        scope: resolvedRootPath,
                        name: name,
                        state: failedPaths.isEmpty ? .success : .failed,
                        detail: failedPaths.isEmpty
                            ? "Applied → \(targetName)"
                            : "\(appliedPaths.count) applied, \(failedPaths.count) not applied",
                        children: shelfOperationSubitems(
                            scope: resolvedRootPath + "\u{1f}" + name,
                            paths: requestedPaths,
                            appliedPaths: Set(appliedPaths),
                            failedPaths: failedPaths,
                            successDetail: "Applied",
                            failureDetail: "Not applied"
                        )
                    )
                }
                let needsAttention = feedbackApplyResult.map(patchApplyNeedsAttention) ?? !failedPaths.isEmpty
                if let restoredName {
                    let actions = [self.shelfRestoreFeedbackAction(
                        name: restoredName,
                        rootPath: resolvedRootPath
                    )]
                    if !needsAttention {
                        self.feedbackCenter.success(
                            "Unshelve completed",
                            detail: detail,
                            additionalActions: actions,
                            notificationID: self.shelfBatchNotificationID(
                                operation: .apply,
                                rootPath: resolvedRootPath
                            )
                        )
                    } else {
                        self.feedbackCenter.warning(
                            "Unshelve partially completed",
                            detail: "\(detail): \(appliedPaths.count) applied, \(failedPaths.count) not applied",
                            nextStep: "Review the failed Shelf members and retry them separately.",
                            additionalActions: actions,
                            notificationID: self.shelfBatchNotificationID(
                                operation: .apply,
                                rootPath: resolvedRootPath
                            )
                        )
                    }
                } else if !needsAttention {
                    self.feedbackCenter.success(
                        "Unshelve completed",
                        detail: detail,
                        notificationID: self.shelfBatchNotificationID(
                            operation: .apply,
                            rootPath: resolvedRootPath
                        )
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Unshelve partially completed",
                        detail: "\(detail): \(appliedPaths.count) applied, \(failedPaths.count) not applied",
                        nextStep: "Review the failed Shelf members and retry them separately.",
                        notificationID: self.shelfBatchNotificationID(
                            operation: .apply,
                            rootPath: resolvedRootPath
                        )
                    )
                }
                self.feedbackCenter.attachOperationItems(
                    [operationItem],
                    notificationID: self.shelfBatchNotificationID(
                        operation: .apply,
                        rootPath: resolvedRootPath
                    )
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Unshelve failed",
                    detail: errorMessage(error),
                    nextStep: "The shelf was kept. Resolve the local conflict, then retry.",
                    notificationID: self.shelfBatchNotificationID(
                        operation: .apply,
                        rootPath: resolvedRootPath
                    )
                )
            }
        }
    }
}

/// Move selected Shelf members to another ShelvedChangeList without applying
/// them to the worktree. The engine preserves patch metadata and moves the
/// source to Recently Deleted when its final member is transferred.
func moveShelfPaths(
    _ sourceName: String,
    _ targetName: String,
    _ paths: [String],
    rootPath: String? = nil
) {
    guard !paths.isEmpty,
          let context = shelfMutationContext(
              rootPath: rootPath,
              activeRootPath: activeShelfRootPath,
              primaryRootPath: primaryShelfRootPath,
              primaryRepository: repo,
              secondaryRepository: shelfRootRepository
          ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    beginFeedbackOperation("Move shelf changes")
    Task.detached(priority: .userInitiated) {
        do {
            try shelfRepository.shelveMovePaths(
                sourceName: sourceName,
                targetName: targetName,
                paths: paths
            )
            let ss = try shelfRepository.shelveList()
            let dsh = (try? shelfRepository.shelveDeletedList()) ?? []
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: ss,
                    deletedShelves: dsh
                )
                self.feedbackCenter.success(
                    "Shelf changes moved",
                    detail: targetName,
                    notificationID: self.shelfMetadataNotificationID(
                        operation: "move",
                        rootPath: resolvedRootPath
                    )
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Move shelf changes failed",
                    detail: errorMessage(error),
                    nextStep: "Choose a destination shelf without overlapping paths, then retry.",
                    notificationID: self.shelfMetadataNotificationID(
                        operation: "move",
                        rootPath: resolvedRootPath
                    )
                )
            }
        }
    }
}

/// Shelf 应用冲突进入与 merge/stash 相同的冲突工作台；区别是 shelf 没有
/// Git operation state，因此引擎会持久化应用前的 worktree/index 快照，
/// 让完成、回滚和重启后恢复都拥有明确的生命周期。
private func presentShelveConflict(
    name: String,
    paths: [String],
    isPop: Bool,
    changeListName: String? = nil,
    isDirectPatch: Bool = false,
    patchText: String? = nil,
    repository: Repository? = nil,
    additionalActions: [FeedbackAction] = [],
    notificationID: String? = nil
) {
    pendingShelveConflictName = name
    pendingShelveConflictRepository = repository ?? repo
    pendingShelveConflictChangeList = changeListName
    let conflictNotificationID = notificationID
        ?? (isDirectPatch
            ? pendingShelveConflictRepository?.workdir().map(directPatchNotificationID(rootPath:))
            : nil)
    pendingShelveConflictNotificationID = conflictNotificationID
    shelveConflictIsPop = isPop
    shelveConflictIsDirectPatch = isDirectPatch
    pendingShelveConflictPatch = patchText
    shelveConflictInProgress = true
    mergeInitialPath = paths.first
    if toolWindowMode != .log {
        selection = paths.first
    }
    fileSelection = nil
    selectionModePath = nil
    commitPreviewPath = nil
    commitPreviewVisible = false
    showMergeRevisionsDialog = true
    if let conflictRepository = pendingShelveConflictRepository {
        if conflictRepository === self.repo {
            refreshAll(showFeedback: false)
        } else {
            refreshShelveConflictStatus(repository: conflictRepository)
        }
    } else {
        refreshAll(showFeedback: false)
    }
    let conflictRootDetail = pendingShelveConflictRepository?.workdir()
        .map { " · Git root: \($0)" } ?? ""
    let conflictDetail = paths.joined(separator: ", ") + conflictRootDetail
    mergeFeedback = if isDirectPatch {
        "Apply Patch 冲突：\(conflictDetail)"
    } else if isPop {
        "Shelve pop 冲突：\(conflictDetail)"
    } else {
        "Unshelve 冲突：\(conflictDetail)"
    }
    feedbackCenter.warning(
        isDirectPatch ? "Patch apply paused" : (isPop ? "Shelve pop paused" : "Unshelve paused"),
        detail: conflictDetail,
        nextStep: isDirectPatch
            ? "Resolve every conflicted file, then complete Apply Patch."
            : "Resolve every conflicted file, then complete the shelf operation.",
        actionTitle: "Resolve Conflicts",
        action: { self.showMergeRevisionsDialog = true },
        additionalActions: additionalActions,
        notificationID: conflictNotificationID
    )
}

func refreshShelveConflictStatus(repository: Repository? = nil) {
    guard let conflictRepository = repository ?? pendingShelveConflictRepository else { return }
    Task.detached(priority: .userInitiated) {
        let conflictEntries = (try? conflictRepository.status()) ?? []
        let conflictChangeLists = (try? conflictRepository.changelistList()) ?? []
        await MainActor.run {
            guard self.pendingShelveConflictRepository === conflictRepository else { return }
            self.entries = conflictEntries
            self.changeLists = conflictChangeLists
            self.fileContentRefreshToken &+= 1
        }
    }
}

private func clearShelveConflictState() {
    shelveConflictInProgress = false
    shelveConflictIsPop = false
    shelveConflictIsDirectPatch = false
    pendingShelveConflictName = nil
    pendingShelveConflictRepository = nil
    pendingShelveConflictChangeList = nil
    pendingShelveConflictPatch = nil
    pendingShelveConflictNotificationID = nil
    mergeInProgress = false
    showMergeRevisionsDialog = false
    mergeInitialPath = nil
}

/// Conflict resolution is finalized by the engine. For Pop, the shelf is
/// removed only after the engine confirms that no conflict stages remain;
/// Unshelve keeps the shelf available for reuse.
func finishShelveConflict() {
    guard let repo = pendingShelveConflictRepository ?? self.repo,
          shelveConflictInProgress,
          let name = pendingShelveConflictName else { return }
    let isPop = shelveConflictIsPop
    let isDirectPatch = shelveConflictIsDirectPatch
    guard let repositoryPath = repo.workdir() else { return }
    let resolvedRootPath = canonicalExternalLogPath(repositoryPath)
    let isPrimaryRoot = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    )
    let pullRebaseSeed = rebaseUndoSeed
    let restoreInfo = (try? repo.shelveRestoreInfo()) ?? nil
    let targetChangeList = pendingShelveConflictChangeList ?? restoreInfo?.targetChangeList
    let restorePaths: [String] = if let restoreInfo,
                                    !restoreInfo.appliedPaths.isEmpty
                                        || !restoreInfo.conflictPaths.isEmpty {
        Array(Set(restoreInfo.appliedPaths + restoreInfo.conflictPaths)).sorted()
    } else {
        restoreInfo?.paths ?? []
    }
    let removeApplied = restoreInfo?.removeApplied ?? false
    let deletedShelfNamesBefore = Set(
        (isPrimaryRoot ? deletedShelves : activeDeletedShelfList).map(\.name)
    )
    let conflictNotificationID = pendingShelveConflictNotificationID
        ?? (isDirectPatch
            ? directPatchNotificationID(rootPath: resolvedRootPath)
            : shelfBatchNotificationID(
                operation: isPop ? .pop : .apply,
                rootPath: resolvedRootPath
            ))
    beginFeedbackOperation(
        isDirectPatch ? "Complete Apply Patch" : "Complete shelve restore",
        notificationID: conflictNotificationID
    )
    Task.detached(priority: .userInitiated) {
        do {
            if let targetChangeList {
                let lists = try repo.changelistList()
                guard lists.contains(where: { $0.name == targetChangeList }) else {
                    await MainActor.run {
                        self.feedbackCenter.error(
                            "Move changes failed",
                            detail: targetChangeList,
                            notificationID: conflictNotificationID
                        )
                    }
                    return
                }
            }
            if isDirectPatch {
                try repo.applyImportedPatchCompleteRestore(name: name)
            } else {
                try repo.shelveCompleteRestore(name: name)
            }
            let nextStatus = try repo.status()
            let nextShelves = try repo.shelveList()
            let nextDeletedShelves = (try? repo.shelveDeletedList()) ?? []
            let nextChangeLists: [ChangeListInfo]
            do {
                let currentPaths = Set(nextStatus.map(\.path))
                let assignablePaths = restorePaths.filter(currentPaths.contains)
                if let targetChangeList, !assignablePaths.isEmpty {
                    try repo.changelistMovePaths(
                        paths: assignablePaths,
                        targetName: targetChangeList
                    )
                }
                nextChangeLists = try repo.changelistList()
            } catch {
                let lists = (try? repo.changelistList()) ?? []
                await MainActor.run {
                    let isActiveRoot = shelfActionRootMatchesCurrentRoot(
                        requestedRootPath: resolvedRootPath,
                        currentRootPath: self.activeShelfRootPath
                    )
                    if isActiveRoot {
                        if isPrimaryRoot {
                            self.entries = nextStatus
                            self.changeLists = lists
                        }
                        self.publishShelfSnapshot(
                            rootPath: resolvedRootPath,
                            shelves: nextShelves,
                            deletedShelves: nextDeletedShelves
                        )
                    }
                    self.clearShelveConflictState()
                    self.feedbackCenter.error(
                        "Move changes failed",
                        detail: targetChangeList ?? errorMessage(error),
                        notificationID: conflictNotificationID
                    )
                    self.refreshAfterShelfMutation(
                        repo: repo,
                        paths: restorePaths
                    )
                }
                return
            }
            let pullRebaseRestoreCompleted = isPrimaryRoot
                && isPop
                && pullRebaseSeed != nil
                && (try? repo.operationState()) == nil
            let completedPullRebaseUndoTarget = pullRebaseRestoreCompleted
                ? pullRebaseSeed.flatMap { seed in
                    rebaseUndoTargetAfterCompletion(
                        seed: seed,
                        currentBranch: (try? repo.branchList())?.first(where: { $0.isCurrent })?.name,
                        finalHead: try? repo.revisionCommitId(revision: seed.branch)
                    )
                }
                : nil
            await MainActor.run {
                let isActiveRoot = shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                )
                if isActiveRoot {
                    if isPrimaryRoot {
                        self.entries = nextStatus
                        self.changeLists = nextChangeLists
                    }
                    self.publishShelfSnapshot(
                        rootPath: resolvedRootPath,
                        shelves: nextShelves,
                        deletedShelves: nextDeletedShelves
                    )
                }
                self.clearShelveConflictState()
                self.refreshAfterShelfMutation(
                    repo: repo,
                    paths: restorePaths
                )
                if isActiveRoot && !isPrimaryRoot {
                    self.refreshAll(showFeedback: false)
                }
                if isPrimaryRoot && isPop {
                    clearPendingPullPreservation(repositoryPath: repositoryPath)
                }
                if pullRebaseRestoreCompleted {
                    self.finishPendingPullRebaseRestore(
                        seed: pullRebaseSeed,
                        target: completedPullRebaseUndoTarget
                    )
                }
                let restoredName = (!isPop && removeApplied)
                    ? nextDeletedShelves.first(where: { !deletedShelfNamesBefore.contains($0.name) })?.name
                    : nil
                if let restoredName {
                    self.feedbackCenter.success(
                        "Unshelve completed",
                        detail: targetChangeList.map { "\(name) → \($0)" } ?? name,
                        additionalActions: [self.shelfRestoreFeedbackAction(
                            name: restoredName,
                            rootPath: resolvedRootPath
                        )],
                        notificationID: conflictNotificationID
                    )
                } else if let completedPullRebaseUndoTarget {
                    self.feedbackCenter.success(
                        "Local changes restored",
                        additionalActions: [self.rebaseUndoFeedbackAction(for: completedPullRebaseUndoTarget)],
                        notificationID: rebaseUndoNotificationID(
                            repositoryPath: completedPullRebaseUndoTarget.repositoryPath
                        ),
                        notificationGroup: .standard
                    )
                } else {
                    self.feedbackCenter.success(
                        isDirectPatch
                            ? "Patch applied"
                            : (isPop ? "Shelve pop completed" : "Unshelve completed"),
                        detail: isPop
                            ? nil
                            : (targetChangeList.map { "\(name) → \($0)" } ?? "Shelf kept: \(name)"),
                        notificationID: conflictNotificationID
                    )
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    isDirectPatch ? "Complete Apply Patch failed" : "Complete shelve restore failed",
                    detail: errorMessage(error),
                    nextStep: isDirectPatch
                        ? "Resolve every conflicted file, then complete Apply Patch."
                        : "Resolve every conflicted file, then complete the shelf operation.",
                    notificationID: conflictNotificationID
                )
            }
        }
    }
}

/// Roll back the exact worktree/index snapshot captured before the shelf was
/// applied. The shelf is intentionally kept for a later retry.
func abortShelveConflict() {
    guard let repo = pendingShelveConflictRepository ?? self.repo,
          shelveConflictInProgress,
          let name = pendingShelveConflictName else { return }
    let isDirectPatch = shelveConflictIsDirectPatch
    let isPop = shelveConflictIsPop
    guard let repositoryPath = repo.workdir() else { return }
    let resolvedRootPath = canonicalExternalLogPath(repositoryPath)
    let isPrimaryRoot = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    )
    let restorePaths = (try? repo.shelveRestoreInfo())?.paths ?? []
    let conflictNotificationID = pendingShelveConflictNotificationID
        ?? (isDirectPatch
            ? directPatchNotificationID(rootPath: resolvedRootPath)
            : shelfBatchNotificationID(
                operation: isPop ? .pop : .apply,
                rootPath: resolvedRootPath
            ))
    beginFeedbackOperation(
        isDirectPatch ? "Rollback Apply Patch" : "Rollback shelve restore",
        notificationID: conflictNotificationID
    )
    Task.detached(priority: .userInitiated) {
        do {
            try repo.shelveAbortRestore(name: name)
            let nextStatus = try repo.status()
            let nextChangeLists = (try? repo.changelistList()) ?? []
            let nextShelves = try repo.shelveList()
            let nextDeletedShelves = (try? repo.shelveDeletedList()) ?? []
            await MainActor.run {
                let isActiveRoot = shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                )
                if isActiveRoot {
                    if isPrimaryRoot {
                        self.entries = nextStatus
                        self.changeLists = nextChangeLists
                    }
                    self.publishShelfSnapshot(
                        rootPath: resolvedRootPath,
                        shelves: nextShelves,
                        deletedShelves: nextDeletedShelves
                    )
                }
                self.clearShelveConflictState()
                self.refreshAfterShelfMutation(
                    repo: repo,
                    paths: restorePaths
                )
                if isActiveRoot && !isPrimaryRoot {
                    self.refreshAll(showFeedback: false)
                }
                self.feedbackCenter.success(
                    isDirectPatch ? "Apply Patch rolled back" : "Shelve restore rolled back",
                    detail: isDirectPatch ? name : "Shelf kept: \(name)",
                    notificationID: conflictNotificationID
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    isDirectPatch ? "Rollback Apply Patch failed" : "Rollback shelve restore failed",
                    detail: errorMessage(error),
                    nextStep: isDirectPatch
                        ? "Resolve the conflict or retry Apply Patch rollback."
                        : "The shelf was kept. Resolve the conflict or retry rollback.",
                    notificationID: conflictNotificationID
                )
            }
        }
    }
}

/// 仅删除 Shelf 中选中的成员；未选中的成员仍留在原 Shelf 中。
func doShelveDropPaths(
    _ name: String,
    _ paths: [String],
    rootPath: String? = nil
) {
    guard !paths.isEmpty,
          let context = shelfMutationContext(
              rootPath: rootPath,
              activeRootPath: activeShelfRootPath,
              primaryRootPath: primaryShelfRootPath,
              primaryRepository: repo,
              secondaryRepository: shelfRootRepository
          ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let scopedShelves = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    ) ? shelves : activeShelfList
    let scopedDeletedShelves = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    ) ? deletedShelves : activeDeletedShelfList
    let deletedShelfNamesBefore = Set(scopedDeletedShelves.map { $0.name })
    let originalShelfTimestamp = scopedShelves.first(where: { $0.name == name })?.timestamp
    beginFeedbackOperation("Drop shelve changes")
    Task.detached(priority: .userInitiated) {
        do {
            try shelfRepository.shelveDropPaths(name: name, paths: paths)
            let ss = try shelfRepository.shelveList()
            let dsh = (try? shelfRepository.shelveDeletedList()) ?? []
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: ss,
                    deletedShelves: dsh
                )
                if self.shelfPreviewName == name,
                   shelfActionRootMatchesCurrentRoot(
                       requestedRootPath: resolvedRootPath,
                       currentRootPath: self.shelfPreviewRootPath ?? self.primaryShelfRootPath
                   ) {
                    self.shelfPreviewText = nil
                    self.showShelfPreview = false
                }
                let restoredName = dsh.first(where: { !deletedShelfNamesBefore.contains($0.name) })?.name
                if let restoredName {
                    let restoreAction = originalShelfTimestamp.map {
                        self.shelfUndoDeletedMembersFeedbackAction(
                            name: restoredName,
                            paths: paths,
                            originalTimestamp: $0,
                            rootPath: resolvedRootPath
                        )
                    } ?? self.shelfRestoreFeedbackAction(
                        name: restoredName,
                        rootPath: resolvedRootPath
                    )
                    self.feedbackCenter.success(
                        "Shelve dropped",
                        detail: paths.joined(separator: ", "),
                        additionalActions: [restoreAction],
                        notificationID: self.shelfBatchNotificationID(
                            operation: .drop,
                            rootPath: resolvedRootPath
                        )
                    )
                } else {
                    self.feedbackCenter.success(
                        "Shelve dropped",
                        detail: paths.joined(separator: ", "),
                        notificationID: self.shelfBatchNotificationID(
                            operation: .drop,
                            rootPath: resolvedRootPath
                        )
                    )
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Shelve drop failed",
                    detail: errorMessage(error),
                    nextStep: "The shelf was kept. Select a valid member and try again.",
                    notificationID: self.shelfBatchNotificationID(
                        operation: .drop,
                        rootPath: resolvedRootPath
                    )
                )
            }
        }
    }
}

func doShelveDrop(
    _ name: String,
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    let scopedShelves = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    ) ? shelves : activeShelfList
    let scopedDeletedShelves = shelfRootSelectionIsPrimary(
        selectedRootPath: resolvedRootPath,
        primaryRootPath: primaryShelfRootPath
    ) ? deletedShelves : activeDeletedShelfList
    let deletedShelfNamesBefore = Set(scopedDeletedShelves.map(\.name))
    let originalShelfTimestamp = scopedShelves.first(where: { $0.name == name })?.timestamp
    let originalShelfPaths = scopedShelves.first(where: { $0.name == name })?.paths ?? []
    let notificationID = shelfBatchNotificationID(
        operation: .drop,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        shelfFeedbackTitle(.drop),
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    Task.detached(priority: .userInitiated) {
        do {
            try shelfRepository.shelveDrop(name: name)
            let ss = try shelfRepository.shelveList()
            let dsh = (try? shelfRepository.shelveDeletedList()) ?? []
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: ss,
                    deletedShelves: dsh
                )
                if self.shelfPreviewName == name,
                   shelfActionRootMatchesCurrentRoot(
                       requestedRootPath: resolvedRootPath,
                       currentRootPath: self.shelfPreviewRootPath ?? self.primaryShelfRootPath
                   ) {
                    self.shelfPreviewName = nil
                    self.shelfPreviewText = nil
                    self.showShelfPreview = false
                }
                let restoredName = dsh.first(where: { !deletedShelfNamesBefore.contains($0.name) })?.name
                if let restoredName {
                    let restoreAction = originalShelfTimestamp.map {
                        self.shelfUndoDeletionFeedbackAction(
                            name: restoredName,
                            originalTimestamp: $0,
                            rootPath: resolvedRootPath
                        )
                    } ?? self.shelfRestoreFeedbackAction(
                        name: restoredName,
                        rootPath: resolvedRootPath
                    )
                    self.feedbackCenter.success(
                        "Shelve dropped",
                        additionalActions: [restoreAction],
                        notificationID: self.shelfBatchNotificationID(
                            operation: .drop,
                            rootPath: resolvedRootPath
                        )
                    )
                } else {
                    self.feedbackCenter.success(
                        "Shelve dropped",
                        notificationID: self.shelfBatchNotificationID(
                            operation: .drop,
                            rootPath: resolvedRootPath
                        )
                    )
                }
                self.feedbackCenter.attachOperationItems(
                    [FeedbackOperationItem(
                        scope: resolvedRootPath,
                        name: name,
                        state: .success,
                        detail: "Moved to Recently Deleted",
                        children: originalShelfPaths.map {
                            FeedbackOperationSubitem(
                                scope: resolvedRootPath + "\u{1f}" + name,
                                path: $0,
                                state: .success,
                                detail: "Moved to Recently Deleted"
                            )
                        }
                    )],
                    notificationID: notificationID,
                    mergeWithExisting: preservePreviousItems
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Shelve drop failed",
                    detail: errorMessage(error),
                    nextStep: "The shelf was kept. Retry the deletion when the repository is ready.",
                    notificationID: self.shelfBatchNotificationID(
                        operation: .drop,
                        rootPath: resolvedRootPath
                    )
                )
                self.feedbackCenter.attachOperationItems(
                    [FeedbackOperationItem(
                        scope: resolvedRootPath,
                        name: name,
                        state: .failed,
                        detail: errorMessage(error),
                        children: originalShelfPaths.map {
                            FeedbackOperationSubitem(
                                scope: resolvedRootPath + "\u{1f}" + name,
                                path: $0,
                                state: .failed,
                                detail: errorMessage(error)
                            )
                        }
                    )],
                    notificationID: notificationID,
                    mergeWithExisting: preservePreviousItems
                )
            }
        }
    }
}

func handleVCSActionRequest(_ request: ArborVCSActionRequest) {
    let shelfName = request.shelfName

    func pathsMatch(_ lhs: String, _ rhs: String) -> Bool {
        URL(fileURLWithPath: lhs).standardizedFileURL.path
            == URL(fileURLWithPath: rhs).standardizedFileURL.path
    }

    if let requestedProjectPath = request.projectPath {
        guard let projectPath, pathsMatch(requestedProjectPath, projectPath) else { return }
    }
    let requestTargetsSecondaryShelfRoot = request.rootPath.map {
        !shelfRootSelectionIsPrimary(
            selectedRootPath: $0,
            primaryRootPath: primaryShelfRootPath
        )
    } ?? false
    if requestTargetsSecondaryShelfRoot,
       !isSecondaryShelfRootScopedAction(request.kind) {
        feedbackCenter.error(
            "Shelf action unavailable",
            detail: request.rootPath ?? "",
            nextStep: "This Shelf action is not yet available for a secondary Git root.",
            localized: false
        )
        return
    }
    if isShelfSemanticAction(request.kind),
       !shelfActionRootMatchesCurrentRoot(
           requestedRootPath: request.rootPath,
           currentRootPath: activeShelfRootPath
       ) {
        feedbackCenter.error(
            "Shelf action unavailable",
            detail: request.rootPath ?? "",
            nextStep: "Activate the Git root that owns this Shelf, then retry the action.",
            localized: false
        )
        return
    }
    if let requestedRootPath = request.rootPath {
        let isCurrentRoot = repo?.workdir().map { pathsMatch(requestedRootPath, $0) } == true
        let isActiveShelfRoot = isShelfSemanticAction(request.kind)
            && shelfActionRootMatchesCurrentRoot(
                requestedRootPath: requestedRootPath,
                currentRootPath: activeShelfRootPath
            )
            && shelfRootRepository != nil
        if isShelfSemanticAction(request.kind) {
            guard isCurrentRoot || isActiveShelfRoot else { return }
        } else {
            guard isCurrentRoot || (try? openRepository(path: requestedRootPath)) != nil else {
                return
            }
        }
    }

    switch request.kind {
    case .restoreShelf:
        guard !shelfName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        restoreDeletedShelve(shelfName, rootPath: request.rootPath)
    case .restoreShelfPaths:
        guard !shelfName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
              !(request.shelfPaths ?? []).isEmpty else { return }
        if let timestamp = request.shelfRestoreTimestamp {
            undoShelfDeletion(
                shelfName,
                originalTimestamp: timestamp,
                rootPath: request.rootPath
            )
        } else {
            restoreDeletedShelve(shelfName, rootPath: request.rootPath)
        }
    case .deleteDeletedShelfPaths:
        guard !shelfName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
              let paths = request.shelfPaths,
              !paths.isEmpty else { return }
        doShelveDeleteDeletedPaths(shelfName, paths, rootPath: request.rootPath)
    case .undoShelfDeletion:
        guard !shelfName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
              let timestamp = request.shelfRestoreTimestamp else { return }
        undoShelfDeletion(
            shelfName,
            originalTimestamp: timestamp,
            rootPath: request.rootPath
        )
    case .undoShelfDeletions:
        guard let names = request.shelfNames,
              let timestamps = request.shelfRestoreTimestamps else { return }
        undoShelfDeletions(
            names,
            originalTimestamps: timestamps,
            rootPath: request.rootPath
        )
    case .dropShelf:
        guard !shelfName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        doShelveDrop(shelfName, rootPath: request.rootPath)
    case .showSavedChanges:
        showSavedChanges(request)
    case .showLogApplyAffectedFiles:
        guard let rootPath = request.rootPath,
              let recovery = request.logApplyRecovery,
              pathsMatch(rootPath, recovery.rootPath) else { return }
        showLogApplyAffectedFiles(recovery)
    case .showOperationDetails:
        guard let notificationID = request.operationNotificationID else { return }
        operationLogFocusNotificationID = notificationID
        operationsViewMode = .history
        toolWindowMode = .operations
        toolWindowExpanded = true
    case .showLogRanges:
        guard let ranges = request.logRevisionRanges else { return }
        showLogRevisionRanges(ranges)
    case .showFindMergedReport:
        guard let reportID = request.findMergedReportID else { return }
        openFindMergedReport(reportID: reportID)
    case .rewordCommit:
        guard let rootPath = request.rootPath,
              let commitID = request.rewordCommitID else { return }
        openRewordCommit(rootPath: rootPath, commitID: commitID)
    case .undoRewordCommit:
        guard let rootPath = request.rootPath,
              let context = request.rewordUndo else { return }
        undoRewordCommit(rootPath: rootPath, context: context)
    case .undoUncommit:
        guard let rootPath = request.rootPath,
              let originalCommitID = request.uncommitCommitID,
              let expectedHead = request.uncommitExpectedHead,
              let expectedBranch = request.uncommitExpectedBranch else { return }
        undoUncommit(
            rootPath: rootPath,
            originalCommitID: originalCommitID,
            expectedHead: expectedHead,
            expectedBranch: expectedBranch
        )
    case .undoRebase:
        guard let rootPath = request.rootPath,
              let initialHead = request.rebaseUndoInitialHead,
              let expectedHead = request.rebaseUndoExpectedHead,
              let branch = request.rebaseUndoBranch,
              !initialHead.isEmpty,
              !expectedHead.isEmpty,
              !branch.isEmpty else { return }
        undoLastRebase(
            RebaseUndoTarget(
                repositoryPath: rootPath,
                branch: branch,
                initialHead: initialHead,
                expectedHead: expectedHead,
                protectionCommitID: request.rebaseUndoProtectionCommit
            )
        )
    case .undoLogSelectedChanges:
        guard let rootPath = request.rootPath,
              let initialHead = request.logSelectedChangesUndoInitialHead,
              let expectedHead = request.logSelectedChangesUndoExpectedHead,
              let branch = request.logSelectedChangesUndoBranch,
              !initialHead.isEmpty,
              !expectedHead.isEmpty else { return }
        undoLogSelectedChanges(
            LogSelectedChangesUndoTarget(
                repositoryPath: rootPath,
                branch: branch,
                initialHead: initialHead,
                expectedHead: expectedHead
            )
        )
    case .restoreApplyLocalChanges:
        openApplyLocalChangesRestore(request)
    case .resumeRebase:
        guard let rootPath = request.rootPath else { return }
        openPersistedRebaseRecovery(rootPath: rootPath, branch: request.rebaseBranch)
    case .retryShelfBatch:
        guard let names = request.shelfNames,
              let operation = request.shelfBatchOperation else { return }
        switch operation {
        case .apply:
            doShelveUnshelveShelves(
                names,
                targetName: request.shelfBatchTargetName,
                removeApplied: request.shelfBatchRemoveApplied ?? false,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        case .pop:
            doShelvePopShelves(
                names,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        case .drop:
            doShelveDropShelves(
                names,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        }
    case .retryShelfMemberBatch:
        guard let persistedGroups = request.shelfMemberGroups,
              let operation = request.shelfMemberBatchOperation,
              !persistedGroups.isEmpty else { return }
        let groups = persistedGroups.map {
            ShelfPathDeleteGroup(shelfName: $0.shelfName, paths: $0.paths)
        }
        switch operation {
        case .unshelve:
            doShelveUnshelvePathGroups(
                groups,
                removeApplied: false,
                sourceIsDeleted: false,
                targetName: request.shelfMemberBatchTargetName,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        case .unshelveAndRemove:
            doShelveUnshelvePathGroups(
                groups,
                removeApplied: true,
                sourceIsDeleted: false,
                targetName: request.shelfMemberBatchTargetName,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        case .unshelveDeleted:
            doShelveUnshelvePathGroups(
                groups,
                removeApplied: false,
                sourceIsDeleted: true,
                targetName: request.shelfMemberBatchTargetName,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        case .unshelveDeletedAndRemove:
            doShelveUnshelvePathGroups(
                groups,
                removeApplied: true,
                sourceIsDeleted: true,
                targetName: request.shelfMemberBatchTargetName,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        case .drop:
            doShelveDropPathGroups(
                groups,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        case .deleteDeleted:
            doShelveDeleteDeletedPathGroups(
                groups,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        }
    case .retryShelfLifecycleBatch:
        guard let names = request.shelfNames,
              let operation = request.shelfLifecycleOperation else { return }
        switch operation {
        case .restoreDeleted:
            restoreDeletedShelves(
                names,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        case .deleteDeleted:
            deleteDeletedShelves(
                names,
                confirm: false,
                rootPath: request.rootPath,
                preservePreviousItems: true
            )
        }
    case .retryShelfDeletePlan:
        guard let persistedPlan = request.shelfDeletePlan else { return }
        deleteShelfPlan(
            persistedPlan.shelfDeletePlan,
            rootPath: request.rootPath,
            preservePreviousItems: true
        )
    case .retryLogApply:
        guard let recovery = request.logApplyRecovery else { return }
        retryLogApplyRecovery(recovery)
    case .retryStashBranch:
        guard let rootPath = request.rootPath,
              let retry = request.stashBranchRetry else { return }
        retryStashBranch(rootPath: rootPath, retry: retry)
    case .retryExternalVCSAction:
        guard let rootPath = request.rootPath,
              let action = request.externalVCSAction else { return }
        retryExternalVCSAction(rootPath: rootPath, action: action)
    case .openGpgAgentSettings:
        showGpgAgentSettings = true
    case .openIdentitySettings:
        showIdentitySettings = true
    case .rollbackMultiRootCheckout:
        guard let reference = request.checkoutReference,
              let persistedTargets = request.checkoutTargets,
              !persistedTargets.isEmpty else { return }
        rollbackMultiRootCheckout(
            persistedTargets.map { $0.makeLiveTarget() },
            reference: reference
        )
    case .rollbackMultiRootBranchCreate:
        guard let branchName = request.multiRootBranchName,
              let persistedTargets = request.multiRootBranchCreateRollbackTargets,
              !persistedTargets.isEmpty else { return }
        rollbackMultiRootBranchCreate(
            persistedTargets.map { $0.makeLiveTarget() },
            branchName: branchName
        )
    case .keepMultiRootBranchCreatePartial:
        guard let branchName = request.multiRootBranchName else { return }
        feedbackCenter.success(
            "Partial branch creation kept",
            detail: branchName,
            notificationID: multiRootBranchCreateRollbackNotificationID(),
            notificationGroup: .standard
        )
    case .rollbackMultiRootBranchRename:
        guard let targets = request.multiRootBranchRenameRollbackTargets,
              !targets.isEmpty else { return }
        rollbackMultiRootBranchRename(targets)
    case .keepMultiRootBranchRenamePartial:
        guard let newName = request.multiRootBranchRenameNewName else { return }
        feedbackCenter.success(
            "Partial branch renames kept",
            detail: newName,
            notificationID: multiRootBranchRenameRollbackNotificationID(),
            notificationGroup: .standard
        )
    case .rollbackMultiRootMerge:
        guard let persistedTargets = request.multiRootMergeRollbackTargets,
              !persistedTargets.isEmpty else { return }
        rollbackMultiRootMerge(
            persistedTargets.map { $0.makeLiveTarget() },
            branchName: request.multiRootMergeBranchName,
            priorResultRows: request.multiRootMergeRollbackResultRows ?? []
        )
    case .deleteMultiRootMergeBranch:
        guard let branchName = request.multiRootMergeDeleteBranchName,
              let rootPaths = request.multiRootMergeDeleteRootPaths,
              !rootPaths.isEmpty else { return }
        confirmAndDeleteMultiRootMergedBranch(
            name: branchName,
            selectedRootPaths: Set(rootPaths)
        )
    case .restoreDeletedBranches:
        guard let targets = request.branchDeleteRecoveryTargets,
              !targets.isEmpty else { return }
        restoreDeletedBranchesFromSemanticTargets(targets)
    case .viewDeletedBranchCommits:
        guard let targets = request.branchDeleteRecoveryTargets,
              !targets.isEmpty else { return }
        viewDeletedBranchCommitsFromSemanticTargets(targets)
    case .rollbackMultiRootUpdate:
        guard let targets = request.multiRootUpdateRollbackTargets,
              !targets.isEmpty else { return }
        if let notificationID = multiRootUpdateNotificationID(partial: true) {
            feedbackCenter.expire(notificationID: notificationID)
        }
        rollbackMultiRootUpdate(targets)
    case .rollbackSubmoduleUpdate:
        guard let targets = request.multiRootUpdateRollbackTargets,
              !targets.isEmpty else { return }
        rollbackMultiRootUpdate(
            targets,
            completionTitle: "Submodule update undone",
            operationTitle: "Undo Submodule Update",
            notificationID: submoduleUpdateRollbackNotificationID(),
            rollbackKind: .rollbackSubmoduleUpdate
        )
    case .retrySubmoduleOperation:
        guard let retry = request.submoduleRetry else { return }
        runSubmoduleOperation(retry)
    case .undoSubmoduleOperation:
        guard let rootPath = request.rootPath,
              let undo = request.submoduleUndo else { return }
        undoSubmoduleOperation(undo, rootPath: rootPath)
    case .rollbackMultiRootReset:
        guard let targets = request.multiRootResetRollbackTargets,
              !targets.isEmpty else { return }
        rollbackMultiRootReset(targets)
    case .rollbackResetRecovery:
        guard let targets = request.resetRecoveryTargets,
              !targets.isEmpty else { return }
        rollbackResetRecovery(targets)
    case .keepResetRecovery:
        guard let targets = request.resetRecoveryTargets,
              !targets.isEmpty else { return }
        keepResetRecovery(targets)
    case .multiRootRebaseRecovery:
        guard let action = request.multiRootRebaseRecoveryAction else { return }
        if let projectPath {
            restorePersistedMultiRootRebaseSession(for: projectPath)
        }
        if let requestedSessionID = request.multiRootRebaseSessionID {
            guard multiRootRebaseSession?.id.uuidString == requestedSessionID else { return }
        }
        switch action {
        case .resume:
            resumeMultiRootRebase()
        case .retry:
            retryMultiRootRebase()
        case .stageAndRetry:
            guard let rootPath = request.rootPath,
                  let sessionID = request.multiRootRebaseSessionID.flatMap(UUID.init(uuidString:)) else {
                return
            }
            stageAndRetryMultiRootRebaseContinue(
                rootPath: rootPath,
                sessionID: sessionID
            )
        case .openRecovery:
            guard let rootPath = request.rootPath else { return }
            openMultiRootConflictResolver(preferredRootPath: rootPath)
        case .rollback:
            rollbackPersistedMultiRootRebase()
        case .keepPartial:
            keepPersistedMultiRootRebasePartial()
        case .undo:
            guard let persistedTargets = request.multiRootRebaseRollbackTargets,
                  !persistedTargets.isEmpty else { return }
            rollbackMultiRootRebase(
                persistedTargets.map { $0.makeLiveTarget() },
                completionTitle: "Multi-root rebase undone"
            )
        }
    case .operationRecovery:
        guard let action = request.operationRecoveryAction,
              let rootPath = request.rootPath else { return }
        let isCurrentRoot = repo?.workdir().map { pathsMatch(rootPath, $0) } == true
        guard isCurrentRoot else {
            openOperationRecovery(rootPath: rootPath)
            return
        }
        guard let currentRepo = repo else { return }
        let currentState: OperationState?
        do {
            currentState = try currentRepo.operationState()
        } catch {
            return
        }
        guard let currentState else { return }
        operationState = currentState
        switch action {
        case .continueOperation:
            doOperationContinue()
        case .skip:
            doOperationSkip()
        case .abort:
            doOperationAbort()
        case .openRecovery:
            openOperationRecovery(rootPath: rootPath)
        }
    case .autoFetchRecovery:
        guard let action = request.autoFetchRecoveryAction else { return }
        switch action {
        case .fetchAll:
            doFetchAll(rootPaths: request.autoFetchRootPaths)
        case .retryCheck:
            autoFetchRunGeneration &+= 1
        case .enable:
            if let projectPath {
                GitIncomingCheckStrategySettings.saveProjectStrategy(.fetch, for: projectPath)
                projectIncomingCheckStrategyRaw = GitIncomingCheckStrategy.fetch.rawValue
            } else {
                incomingCheckStrategyRaw = GitIncomingCheckStrategy.fetch.rawValue
                gitAutoFetch = true
            }
        case .doNotAskAgain:
            GitIncomingCheckStrategySettings.setSuggestionDisabled(true, for: projectPath)
            GitIncomingCheckStrategySettings.setSuggestionCount(3, for: projectPath)
        }
    case .retryMultiRootOperation:
        guard let operation = request.multiRootRetryOperation,
              let rootPaths = request.multiRootRetryRootPaths,
              !rootPaths.isEmpty else { return }
        switch operation {
        case .update:
            guard let rebase = request.multiRootRetryRebase else { return }
            retryMultiRootUpdateFailedRoots(
                rootPaths: rootPaths,
                rebase: rebase,
                rebaseRootPaths: request.multiRootRetryRebaseRootPaths
            )
        case .fetch:
            executeMultiRootOperation(.fetch, rootPaths: rootPaths)
        case .pullMerge:
            executeMultiRootOperation(
                .pullMerge,
                rootPaths: rootPaths,
                priorRevisionRanges: request.multiRootRetryLogRevisionRanges ?? []
            )
        case .pullRebase:
            executeMultiRootOperation(
                .pullRebase,
                rootPaths: rootPaths,
                priorRevisionRanges: request.multiRootRetryLogRevisionRanges ?? []
            )
        case .push:
            retryMultiRootPushFailedRoots(
                rootPaths: rootPaths,
                tagMode: request.multiRootPushTagMode.flatMap { PushDialogTagMode(rawValue: $0.rawValue) },
                skipHooks: request.multiRootPushSkipHooks,
                force: request.multiRootPushForce,
                forceWithLease: request.multiRootPushForceWithLease,
                priorViewCommitRanges: request.multiRootRetryLogRevisionRanges,
                priorResultRows: request.multiRootRetryResultRows
            )
        case .pushRecovery:
            guard let rebase = request.multiRootRetryRebase else { return }
            retryMultiRootPushFailedRoots(
                rootPaths: rootPaths,
                recoveryRebase: rebase,
                recoveryUpdateRootPaths: request.multiRootRetryUpdateRootPaths,
                tagMode: request.multiRootPushTagMode.flatMap { PushDialogTagMode(rawValue: $0.rawValue) },
                skipHooks: request.multiRootPushSkipHooks,
                force: false,
                forceWithLease: false,
                priorViewCommitRanges: request.multiRootRetryLogRevisionRanges,
                priorResultRows: request.multiRootRetryResultRows
            )
        case .checkoutUpdate:
            guard let reference = request.checkoutReference,
                  let detach = request.multiRootRetryDetach,
                  let rebase = request.multiRootRetryRebase,
                  let checkoutMode = request.multiRootRetryCheckoutMode else { return }
            retryMultiRootCheckoutAndUpdateFailedRoots(
                reference: reference,
                selectedRootPaths: rootPaths,
                detach: detach,
                rebase: rebase,
                checkoutMode: checkoutMode
            )
        case .commit:
            guard let retry = request.multiRootCommitRetry else { return }
            let selectedChanges = retry.selectedPaths?.map { $0.makeLiveSelection() }
            performMultiRootCommit(
                rootPaths: rootPaths,
                message: retry.message,
                options: retry.makeLiveOptions(),
                allowForceRetry: true,
                pushAfterCommit: retry.pushAfterCommit ?? false,
                priorPushRootPaths: retry.pushRootPaths ?? [],
                selectedChanges: selectedChanges
            )
        case .pushAfterCommit:
            executeMultiRootPush(selectedRootPaths: rootPaths, fromCommit: true)
        case .stage:
            if let changePaths = request.multiRootRetryChangePaths,
               !changePaths.isEmpty {
                runMultiRootChangeMutation(operation: .stage, paths: changePaths)
                return
            }
            guard rootPaths.count == 1,
                  let rootPath = rootPaths.first,
                  let path = request.multiRootRetryPath else { return }
            stageMultiRootPath(rootPath: rootPath, path: path)
        case .unstage:
            if let changePaths = request.multiRootRetryChangePaths,
               !changePaths.isEmpty {
                runMultiRootChangeMutation(operation: .unstage, paths: changePaths)
                return
            }
            guard rootPaths.count == 1,
                  let rootPath = rootPaths.first,
                  let path = request.multiRootRetryPath else { return }
            unstageMultiRootPath(rootPath: rootPath, path: path)
        case .stageAll:
            guard rootPaths.count == 1, let rootPath = rootPaths.first else { return }
            stageAllMultiRootPath(rootPath: rootPath)
        case .unstageAll:
            guard rootPaths.count == 1, let rootPath = rootPaths.first else { return }
            unstageAllMultiRootPath(rootPath: rootPath)
        }
    case .retryPush:
        guard let rootPath = request.rootPath,
              let push = request.pushRecovery else { return }
        retrySingleRootPush(
            rootPath: rootPath,
            push: push,
            viewCommitRanges: request.logRevisionRanges ?? []
        )
    case .retryPushRecovery:
        guard let rootPath = request.rootPath,
              let recovery = request.pushRecovery else { return }
        retrySingleRootPushRecovery(
            rootPath: rootPath,
            recovery: recovery,
            viewCommitRanges: request.logRevisionRanges ?? []
        )
    }
}

private func openApplyLocalChangesRestore(_ request: ArborVCSActionRequest) {
    guard let rootPath = request.rootPath else { return }
    toolWindowMode = .commit
    toolWindowExpanded = true
    openMultiRootConflictResolver(preferredRootPath: rootPath)
}

private func showLogApplyAffectedFiles(
    _ recovery: PersistedLogApplyRecovery
) {
    guard let persisted = loadLogApplyRecovery(repositoryPath: recovery.rootPath),
          persisted == recovery,
          !recovery.affectedPaths.isEmpty else {
        feedbackCenter.warning(
            "Show Files unavailable",
            detail: "The Log operation is no longer pending.",
            nextStep: "Refresh the Log and select the commits again."
        )
        return
    }

    let rootPath = URL(fileURLWithPath: recovery.rootPath).standardizedFileURL.path
    let preferredPath = recovery.affectedPaths.first
    toolWindowMode = .commit
    toolWindowExpanded = true
    let currentRootMatches = repo?.workdir().map {
        URL(fileURLWithPath: $0).standardizedFileURL.path == rootPath
    } == true
    guard currentRootMatches, let activeRepo = repo else {
        openMultiRootConflictResolver(
            preferredRootPath: rootPath,
            preferredPath: preferredPath
        )
        return
    }

    selection = preferredPath
    fileSelection = nil
    selectionModePath = nil
    commitPreviewPath = nil
    commitPreviewVisible = false
    Task.detached(priority: .userInitiated) {
        let status = (try? activeRepo.status()) ?? []
        await MainActor.run {
            guard self.repo === activeRepo else { return }
            self.entries = status
            self.selection = status.first(where: {
                recovery.affectedPaths.contains($0.path)
            })?.path ?? preferredPath
        }
    }
}

private func showSavedChanges(_ request: ArborVCSActionRequest) {
    guard let savedChangesKind = request.savedChangesKind,
          let savedChangesID = request.savedChangesID,
          !savedChangesID.isEmpty else { return }

    let rootPath = request.rootPath ?? repo?.workdir()
    guard let rootPath else { return }
    let savedChangesRepo: Repository
    do {
        savedChangesRepo = try openRepository(path: rootPath)
    } catch {
        feedbackCenter.error("Load saved changes failed", detail: errorMessage(error))
        return
    }

    toolWindowMode = .commit
    toolWindowExpanded = true
    Task.detached(priority: .userInitiated) {
        do {
            switch savedChangesKind {
            case .shelf:
                let shelves = try savedChangesRepo.shelveList()
                guard shelves.contains(where: { $0.name == savedChangesID }) else {
                    throw NSError(
                        domain: "Arbor.SavedChanges",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "找不到已保存的 Shelf：\(savedChangesID)"]
                    )
                }
                let diff = try savedChangesRepo.shelveDiff(name: savedChangesID)
                await MainActor.run {
                    self.shelves = shelves
                    self.stashPreviewStashID = nil
                    self.stashPreviewText = nil
                    self.showStashPreview = false
                    self.shelfPreviewName = savedChangesID
                    self.shelfPreviewIsDeleted = false
                    self.shelfPreviewText = diff
                    self.showShelfPreview = true
                }
            case .stash:
                let stashes = try savedChangesRepo.stashList()
                guard let index = stashes.firstIndex(where: { $0.id == savedChangesID }) else {
                    throw NSError(
                        domain: "Arbor.SavedChanges",
                        code: 2,
                        userInfo: [NSLocalizedDescriptionKey: "找不到已保存的 stash：\(savedChangesID)"]
                    )
                }
                let diff = try savedChangesRepo.stashDiff(
                    index: try currentStashIndex(repo: savedChangesRepo, stashID: savedChangesID)
                )
                await MainActor.run {
                    self.stashes = stashes
                    self.shelfPreviewName = nil
                    self.shelfPreviewText = nil
                    self.showShelfPreview = false
                    self.stashPreviewStashID = stashes[index].id
                    self.stashPreviewText = diff
                    self.showStashPreview = true
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Load saved changes failed", detail: errorMessage(error))
            }
        }
    }
}

private func shelfActionRequest(
    kind: ArborVCSActionRequest.Kind,
    name: String,
    paths: [String]? = nil,
    restoreTimestamp: Int64? = nil,
    rootPath: String? = nil
) -> ArborVCSActionRequest? {
    guard let resolvedRootPath = rootPath ?? repo?.workdir() else { return nil }
    return ArborVCSActionRequest(
        kind: kind,
        projectPath: projectPath,
        rootPath: resolvedRootPath,
        shelfName: name,
        shelfPaths: paths,
        shelfRestoreTimestamp: restoreTimestamp
    )
}

private func isShelfSemanticAction(_ kind: ArborVCSActionRequest.Kind) -> Bool {
    switch kind {
    case .restoreShelf,
         .restoreShelfPaths,
         .deleteDeletedShelfPaths,
         .undoShelfDeletion,
         .undoShelfDeletions,
         .dropShelf,
         .retryShelfBatch,
         .retryShelfMemberBatch,
         .retryShelfLifecycleBatch,
         .retryShelfDeletePlan:
        return true
    default:
        return false
    }
}

private func shelfRootNotificationID(
    prefix: String,
    rootPath: String? = nil
) -> String? {
    guard let resolvedRootPath = rootPath ?? repo?.workdir() else { return nil }
    return shelfNotificationID(prefix: prefix, rootPath: resolvedRootPath)
}

private func shelfMetadataNotificationID(
    operation: String,
    rootPath: String? = nil
) -> String? {
    shelfRootNotificationID(prefix: "shelf-metadata.\(operation)", rootPath: rootPath)
}

private func shelfBatchNotificationID(
    operation: ArborVCSActionRequest.ShelfBatchOperation,
    rootPath: String? = nil
) -> String? {
    shelfRootNotificationID(
        prefix: "shelf-batch.\(operation.rawValue)",
        rootPath: rootPath
    )
}

private func shelfMemberBatchNotificationID(
    operation: ArborVCSActionRequest.ShelfMemberBatchOperation,
    rootPath: String? = nil
) -> String? {
    shelfRootNotificationID(
        prefix: "shelf-member-batch.\(operation.rawValue)",
        rootPath: rootPath
    )
}

private func shelfLifecycleNotificationID(
    operation: ArborVCSActionRequest.ShelfLifecycleOperation,
    rootPath: String? = nil
) -> String? {
    shelfRootNotificationID(
        prefix: "shelf-lifecycle.\(operation.rawValue)",
        rootPath: rootPath
    )
}

private func shelfUndoDeletionNotificationID(rootPath: String? = nil) -> String? {
    shelfRootNotificationID(prefix: "shelf-undo-deletion", rootPath: rootPath)
}

private func shelfDeletedMemberDeletionNotificationID(rootPath: String? = nil) -> String? {
    shelfRootNotificationID(prefix: "shelf-deleted-member-deletion", rootPath: rootPath)
}

private func shelfBatchRetryFeedbackAction(
    names: [String],
    operation: ArborVCSActionRequest.ShelfBatchOperation,
    targetName: String?,
    removeApplied: Bool,
    rootPath: String? = nil
) -> FeedbackAction? {
    let normalizedNames = names
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }
    guard !normalizedNames.isEmpty,
          let resolvedRootPath = rootPath ?? repo?.workdir() else { return nil }
    let request = ArborVCSActionRequest(
        kind: .retryShelfBatch,
        projectPath: projectPath,
        rootPath: resolvedRootPath,
        shelfName: "",
        shelfNames: normalizedNames,
        shelfBatchOperation: operation,
        shelfBatchTargetName: targetName,
        shelfBatchRemoveApplied: removeApplied
    )
    return FeedbackAction(title: "Retry Remaining Shelves", semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

private func shelfMemberBatchRetryFeedbackAction(
    groups: [ShelfPathDeleteGroup],
    operation: ArborVCSActionRequest.ShelfMemberBatchOperation,
    targetName: String? = nil,
    rootPath: String? = nil
) -> FeedbackAction? {
    let normalizedGroups = normalizedShelfPathGroups(groups)
    guard !normalizedGroups.isEmpty,
          let resolvedRootPath = rootPath ?? repo?.workdir() else { return nil }
    let request = ArborVCSActionRequest(
        kind: .retryShelfMemberBatch,
        projectPath: projectPath,
        rootPath: resolvedRootPath,
        shelfName: "",
        shelfMemberGroups: normalizedGroups.map {
            PersistedShelfPathGroup(shelfName: $0.shelfName, paths: $0.paths)
        },
        shelfMemberBatchOperation: operation,
        shelfMemberBatchTargetName: targetName
    )
    return FeedbackAction(title: "Retry Remaining Shelf Changes", semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

