func restoreDeletedShelve(_ name: String, rootPath: String? = nil) {
    restoreDeletedShelves([name], rootPath: rootPath)
}

/// Undo a recent Shelf deletion while preserving the original list timestamp.
/// This is distinct from the Recently Deleted Restore action: IntelliJ's
/// deletion notification restores the list to its pre-delete position rather
/// than making it a newly modified Shelf.
private func undoShelfDeletion(
    _ name: String,
    originalTimestamp: Int64,
    rootPath: String? = nil
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    beginFeedbackOperation("Undo shelf deletion")
    Task.detached(priority: .userInitiated) {
        do {
            try shelfRepository.shelveRestoreDeletedWithTimestamp(
                name: name,
                timestamp: originalTimestamp
            )
            let ss = try shelfRepository.shelveList()
            let dsh = (try? shelfRepository.shelveDeletedList()) ?? []
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: ss,
                    deletedShelves: dsh
                )
                self.feedbackCenter.success(
                    "Shelf deletion undone",
                    detail: name,
                    additionalActions: [self.shelfDropFeedbackAction(
                        name: name,
                        rootPath: resolvedRootPath
                    )],
                    notificationID: self.shelfUndoDeletionNotificationID(
                        rootPath: resolvedRootPath
                    )
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Undo shelf deletion failed",
                    detail: errorMessage(error),
                    nextStep: "The deleted Shelf was kept. Resolve any active name conflict, then retry Undo.",
                    notificationID: self.shelfUndoDeletionNotificationID(
                        rootPath: resolvedRootPath
                    )
                )
            }
        }
    }
}

/// Undo one notification's multi-Shelf deletion as one semantic action. The
/// timestamp map preserves IntelliJ's restore-to-original-position behavior
/// while allowing a partial result when one deleted list is no longer present.
private func undoShelfDeletions(
    _ names: [String],
    originalTimestamps: [String: Int64],
    rootPath: String? = nil
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    var seen = Set<String>()
    let uniqueNames = names
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty && seen.insert($0).inserted }
    guard !uniqueNames.isEmpty else { return }

    beginFeedbackOperation("Undo shelf deletions")
    feedbackCenter.updateBatchProgress(
        completed: 0,
        total: uniqueNames.count,
        phase: "Undo Shelf Deletion"
    )
    Task.detached(priority: .userInitiated) {
        var restored: [String] = []
        var failures: [String] = []
        var failedNames: [String] = []
        for (index, name) in uniqueNames.enumerated() {
            do {
                guard let timestamp = originalTimestamps[name] else {
                    throw EngineError.GitOperation(message: "shelve: missing original timestamp for '\(name)'")
                }
                try shelfRepository.shelveRestoreDeletedWithTimestamp(name: name, timestamp: timestamp)
                restored.append(name)
            } catch {
                failedNames.append(name)
                failures.append("\(name): \(errorMessage(error))")
            }
            await MainActor.run {
                self.feedbackCenter.updateBatchProgress(
                    completed: index + 1,
                    total: uniqueNames.count,
                    phase: "Undo Shelf Deletion",
                    detail: name
                )
            }
        }

        let nextShelves = (try? shelfRepository.shelveList()) ?? []
        let nextDeletedShelves = (try? shelfRepository.shelveDeletedList()) ?? []
        let restoredSnapshot = restored
        let failuresSnapshot = failures
        let failedNamesSnapshot = failedNames
        let retryTimestamps = originalTimestamps
        await MainActor.run {
            guard shelfActionRootMatchesCurrentRoot(
                requestedRootPath: resolvedRootPath,
                currentRootPath: self.activeShelfRootPath
            ) else { return }
            self.publishShelfSnapshot(
                rootPath: resolvedRootPath,
                shelves: nextShelves,
                deletedShelves: nextDeletedShelves
            )
            let dropActions = restoredSnapshot.map {
                self.shelfDropFeedbackAction(name: $0, rootPath: resolvedRootPath)
            }
            let retryAction = self.shelfUndoDeletionsFeedbackAction(
                names: failedNamesSnapshot,
                originalTimestamps: retryTimestamps,
                title: "Retry Undo",
                rootPath: resolvedRootPath
            )
            let notificationID = self.shelfUndoDeletionNotificationID(rootPath: resolvedRootPath)
            if failuresSnapshot.isEmpty {
                self.feedbackCenter.success(
                    restoredSnapshot.count == 1 ? "Shelf deletion undone" : "Shelf deletions undone",
                    detail: restoredSnapshot.joined(separator: ", "),
                    additionalActions: dropActions,
                    notificationID: notificationID
                )
            } else if restoredSnapshot.isEmpty {
                self.feedbackCenter.error(
                    "Undo shelf deletion failed",
                    detail: failuresSnapshot.joined(separator: "\n"),
                    nextStep: "The deleted Shelves were kept. Resolve any active name conflict, then retry Undo.",
                    additionalActions: retryAction.map { [$0] } ?? [],
                    notificationID: notificationID
                )
            } else {
                var actions = dropActions
                if let retryAction { actions.append(retryAction) }
                self.feedbackCenter.warning(
                    "Some shelf deletions undone",
                    detail: "Restored: \(restoredSnapshot.joined(separator: ", "))\nFailed: \(failuresSnapshot.joined(separator: ", "))",
                    nextStep: "Retry Undo for the deleted Shelves that remain in Recently Deleted.",
                    additionalActions: actions,
                    notificationID: notificationID
                )
            }
        }
    }
}

/// Restore one or more deleted shelves as a single Recently Deleted action.
/// IntelliJ's RestoreShelvedChange action operates on the selected deleted
/// changelists and reports a partial result when one list cannot be restored.
func restoreDeletedShelves(
    _ names: [String],
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    var uniqueNames: [String] = []
    var seen = Set<String>()
    for name in names {
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, seen.insert(trimmed).inserted else { continue }
        uniqueNames.append(trimmed)
    }
    guard !uniqueNames.isEmpty else { return }
    let notificationID = shelfLifecycleNotificationID(
        operation: .restoreDeleted,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        uniqueNames.count == 1 ? "Restore deleted shelf" : "Restore deleted shelves",
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    feedbackCenter.updateBatchProgress(
        completed: 0,
        total: uniqueNames.count,
        phase: "Restore Shelf"
    )
    Task.detached(priority: .userInitiated) { [uniqueNames] in
        let shelfPathsByName = Dictionary(
            uniqueKeysWithValues: ((try? shelfRepository.shelveDeletedList()) ?? []).map {
                ($0.name, $0.paths)
            }
        )
        var restored: [String] = []
        var failures: [String] = []
        var failedNames: [String] = []
        var itemStates: [String: FeedbackResultState] = [:]
        var itemDetails: [String: String] = [:]
        var itemChildren: [String: [FeedbackOperationSubitem]] = [:]
        for (index, name) in uniqueNames.enumerated() {
            do {
                try shelfRepository.shelveRestoreDeleted(name: name)
                restored.append(name)
                itemStates[name] = .success
                itemDetails[name] = "Restored from Recently Deleted"
                itemChildren[name] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + name,
                    paths: shelfPathsByName[name] ?? [],
                    state: .success,
                    detail: "Restored from Recently Deleted"
                )
            } catch {
                failedNames.append(name)
                itemStates[name] = .failed
                itemDetails[name] = errorMessage(error)
                itemChildren[name] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + name,
                    paths: shelfPathsByName[name] ?? [],
                    state: .failed,
                    detail: errorMessage(error)
                )
                failures.append("\(name): \(errorMessage(error))")
            }
            await MainActor.run {
                self.feedbackCenter.updateBatchProgress(
                    completed: index + 1,
                    total: uniqueNames.count,
                    phase: "Restore Shelf",
                    detail: name
                )
            }
        }
        let restoredNames = restored
        let failureMessages = failures
        let failedNamesSnapshot = failedNames
        let itemStatesSnapshot = itemStates
        let itemDetailsSnapshot = itemDetails
        let itemChildrenSnapshot = itemChildren
        do {
            let ss = try shelfRepository.shelveList()
            let dsh = (try? shelfRepository.shelveDeletedList()) ?? []
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: ss,
                    deletedShelves: dsh
                )
                let actions = restoredNames.map {
                    self.shelfDropFeedbackAction(
                        name: $0,
                        rootPath: resolvedRootPath
                    )
                }
                let retryAction = self.shelfLifecycleRetryFeedbackAction(
                    names: failedNamesSnapshot,
                    operation: .restoreDeleted,
                    rootPath: resolvedRootPath
                )
                let operationItems = shelfOperationItems(
                    rootPath: resolvedRootPath,
                    names: uniqueNames,
                    states: itemStatesSnapshot,
                    details: itemDetailsSnapshot,
                    children: itemChildrenSnapshot
                )
                if failureMessages.isEmpty {
                    self.feedbackCenter.success(
                        restoredNames.count == 1 ? "Shelf restored" : "Shelves restored",
                        detail: restoredNames.joined(separator: ", "),
                        additionalActions: actions,
                        notificationID: notificationID
                    )
                } else if restoredNames.isEmpty {
                    self.feedbackCenter.error(
                        "Shelf restore failed",
                        detail: failureMessages.joined(separator: "\n"),
                        nextStep: "The deleted shelves were kept. Resolve any active shelf name conflict and retry.",
                        additionalActions: retryAction.map { [$0] } ?? [],
                        notificationID: notificationID
                    )
                } else {
                    var additionalActions = actions
                    if let retryAction { additionalActions.append(retryAction) }
                    self.feedbackCenter.warning(
                        "Some shelves restored",
                        detail: "Restored: \(restoredNames.joined(separator: ", "))\nFailed: \(failureMessages.joined(separator: ", "))",
                        nextStep: "The failed deleted shelves were kept. Resolve the reported conflict and retry.",
                        additionalActions: additionalActions,
                        notificationID: notificationID
                    )
                }
                self.feedbackCenter.attachOperationItems(
                    operationItems,
                    notificationID: notificationID,
                    mergeWithExisting: preservePreviousItems
                )
            }
        } catch {
            await MainActor.run {
                let notificationID = self.shelfLifecycleNotificationID(
                    operation: .restoreDeleted,
                    rootPath: resolvedRootPath
                )
                self.feedbackCenter.error(
                    "Shelf restore failed",
                    detail: failureMessages.isEmpty ? errorMessage(error) : failureMessages.joined(separator: "\n"),
                    nextStep: "The deleted shelf was kept. Resolve any active shelf name conflict and retry.",
                    additionalActions: self.shelfLifecycleRetryFeedbackAction(
                        names: failedNamesSnapshot,
                        operation: .restoreDeleted,
                        rootPath: resolvedRootPath
                    ).map { [$0] } ?? [],
                    notificationID: notificationID
                )
                self.feedbackCenter.attachOperationItems(
                    uniqueNames.map {
                        FeedbackOperationItem(
                            scope: resolvedRootPath,
                            name: $0,
                            state: itemStatesSnapshot[$0] ?? .failed,
                            detail: itemDetailsSnapshot[$0] ?? errorMessage(error)
                        )
                    },
                    notificationID: notificationID,
                    mergeWithExisting: preservePreviousItems
                )
            }
        }
    }
}

/// Permanently remove selected members from a Recently Deleted Shelf. The
/// remaining members stay recoverable; deleting the last member removes the
/// deleted Shelf itself.
func doShelveDeleteDeletedPaths(
    _ name: String,
    _ paths: [String],
    rootPath: String? = nil
) {
    guard !paths.isEmpty,
          let context = shelfMutationContext(
              rootPath: rootPath,
              activeRootPath: activeShelfRootPath,
              primaryRootPath: primaryShelfRootPath,
              primaryRepository: repo,
              secondaryRepository: shelfRootRepository
          ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    beginFeedbackOperation("Delete deleted Shelf members permanently")
    Task.detached(priority: .userInitiated) {
        do {
            try shelfRepository.shelveDeleteDeletedPaths(name: name, paths: paths)
            let ss = (try? shelfRepository.shelveList()) ?? []
            let dsh = (try? shelfRepository.shelveDeletedList()) ?? []
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: ss,
                    deletedShelves: dsh
                )
                self.feedbackCenter.success(
                    paths.count == 1
                        ? "Deleted Shelf member deleted permanently"
                        : "Deleted Shelf members deleted permanently",
                    detail: "\(name): \(paths.joined(separator: ", "))",
                    notificationID: self.shelfDeletedMemberDeletionNotificationID(
                        rootPath: resolvedRootPath
                    )
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Delete deleted Shelf members failed",
                    detail: errorMessage(error),
                    nextStep: "The selected deleted Shelf members were kept. Retry the permanent deletion.",
                    additionalActions: [
                        self.shelfDeleteDeletedMembersFeedbackAction(
                            name: name,
                            paths: paths,
                            rootPath: resolvedRootPath
                        )
                    ],
                    notificationID: self.shelfDeletedMemberDeletionNotificationID(
                        rootPath: resolvedRootPath
                    )
                )
            }
        }
    }
}

/// Permanently delete a shelf from Recently Deleted after an explicit prompt.
func deleteDeletedShelve(_ name: String, rootPath: String? = nil) {
    deleteDeletedShelves([name], rootPath: rootPath)
}

/// Permanently delete one or more selected Recently Deleted shelves.
func deleteDeletedShelves(
    _ names: [String],
    confirm: Bool = true,
    rootPath: String? = nil,
    preservePreviousItems: Bool = false
) {
    guard let context = shelfMutationContext(
        rootPath: rootPath,
        activeRootPath: activeShelfRootPath,
        primaryRootPath: primaryShelfRootPath,
        primaryRepository: repo,
        secondaryRepository: shelfRootRepository
    ) else { return }
    let shelfRepository = context.repository
    let resolvedRootPath = context.rootPath
    var uniqueNames: [String] = []
    var seen = Set<String>()
    for name in names {
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, seen.insert(trimmed).inserted else { continue }
        uniqueNames.append(trimmed)
    }
    guard !uniqueNames.isEmpty else { return }
    if confirm {
        let alert = NSAlert()
        alert.messageText = uniqueNames.count == 1
            ? "Delete Shelf Permanently?"
            : "Delete Shelves Permanently?"
        alert.informativeText = uniqueNames.joined(separator: "\n")
        alert.alertStyle = .warning
        alert.addButton(withTitle: "Delete Permanently")
        alert.addButton(withTitle: "Cancel")
        guard alert.runModal() == .alertFirstButtonReturn else { return }
    }

    let notificationID = shelfLifecycleNotificationID(
        operation: .deleteDeleted,
        rootPath: resolvedRootPath
    )
    beginFeedbackOperation(
        uniqueNames.count == 1 ? "Delete shelf permanently" : "Delete shelves permanently",
        notificationID: notificationID,
        preserveResultItems: preservePreviousItems
    )
    feedbackCenter.updateBatchProgress(
        completed: 0,
        total: uniqueNames.count,
        phase: "Delete Shelf"
    )
    Task.detached(priority: .userInitiated) { [uniqueNames] in
        let shelfPathsByName = Dictionary(
            uniqueKeysWithValues: ((try? shelfRepository.shelveDeletedList()) ?? []).map {
                ($0.name, $0.paths)
            }
        )
        var deleted: [String] = []
        var failures: [String] = []
        var failedNames: [String] = []
        var itemStates: [String: FeedbackResultState] = [:]
        var itemDetails: [String: String] = [:]
        var itemChildren: [String: [FeedbackOperationSubitem]] = [:]
        for (index, name) in uniqueNames.enumerated() {
            do {
                try shelfRepository.shelveDeleteDeleted(name: name)
                deleted.append(name)
                itemStates[name] = .success
                itemDetails[name] = "Deleted permanently"
                itemChildren[name] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + name,
                    paths: shelfPathsByName[name] ?? [],
                    state: .success,
                    detail: "Deleted permanently"
                )
            } catch {
                failedNames.append(name)
                itemStates[name] = .failed
                itemDetails[name] = errorMessage(error)
                itemChildren[name] = shelfOperationSubitems(
                    scope: resolvedRootPath + "\u{1f}" + name,
                    paths: shelfPathsByName[name] ?? [],
                    state: .failed,
                    detail: errorMessage(error)
                )
                failures.append("\(name): \(errorMessage(error))")
            }
            await MainActor.run {
                self.feedbackCenter.updateBatchProgress(
                    completed: index + 1,
                    total: uniqueNames.count,
                    phase: "Delete Shelf",
                    detail: name
                )
            }
        }
        let deletedNames = deleted
        let failureMessages = failures
        let failedNamesSnapshot = failedNames
        let itemStatesSnapshot = itemStates
        let itemDetailsSnapshot = itemDetails
        let itemChildrenSnapshot = itemChildren
        do {
            let dsh = try shelfRepository.shelveDeletedList()
            await MainActor.run {
                guard shelfActionRootMatchesCurrentRoot(
                    requestedRootPath: resolvedRootPath,
                    currentRootPath: self.activeShelfRootPath
                ) else { return }
                let currentShelves = shelfRootSelectionIsPrimary(
                    selectedRootPath: resolvedRootPath,
                    primaryRootPath: self.primaryShelfRootPath
                ) ? self.shelves : self.activeShelfList
                self.publishShelfSnapshot(
                    rootPath: resolvedRootPath,
                    shelves: currentShelves,
                    deletedShelves: dsh
                )
                let retryAction = self.shelfLifecycleRetryFeedbackAction(
                    names: failedNamesSnapshot,
                    operation: .deleteDeleted,
                    rootPath: resolvedRootPath
                )
                let operationItems = shelfOperationItems(
                    rootPath: resolvedRootPath,
                    names: uniqueNames,
                    states: itemStatesSnapshot,
                    details: itemDetailsSnapshot,
                    children: itemChildrenSnapshot
                )
                if failureMessages.isEmpty {
                    self.feedbackCenter.success(
                        deletedNames.count == 1 ? "Shelf deleted permanently" : "Shelves deleted permanently",
                        detail: deletedNames.joined(separator: ", "),
                        notificationID: notificationID
                    )
                } else if deletedNames.isEmpty {
                    self.feedbackCenter.error(
                        "Permanent shelf deletion failed",
                        detail: failureMessages.joined(separator: "\n"),
                        nextStep: "The deleted shelves were kept. Retry after checking repository permissions.",
                        additionalActions: retryAction.map { [$0] } ?? [],
                        notificationID: notificationID
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Some shelves deleted permanently",
                        detail: "Deleted: \(deletedNames.joined(separator: ", "))\nFailed: \(failureMessages.joined(separator: ", "))",
                        nextStep: "The failed deleted shelves were kept. Retry after checking repository permissions.",
                        additionalActions: retryAction.map { [$0] } ?? [],
                        notificationID: notificationID
                    )
                }
                self.feedbackCenter.attachOperationItems(
                    operationItems,
                    notificationID: notificationID,
                    mergeWithExisting: preservePreviousItems
                )
            }
        } catch {
            await MainActor.run {
                let notificationID = self.shelfLifecycleNotificationID(
                    operation: .deleteDeleted,
                    rootPath: resolvedRootPath
                )
                self.feedbackCenter.error(
                    "Permanent shelf deletion failed",
                    detail: failureMessages.isEmpty ? errorMessage(error) : failureMessages.joined(separator: "\n"),
                    nextStep: "The deleted shelf was kept. Retry after checking repository permissions.",
                    additionalActions: self.shelfLifecycleRetryFeedbackAction(
                        names: failedNamesSnapshot,
                        operation: .deleteDeleted,
                        rootPath: resolvedRootPath
                    ).map { [$0] } ?? [],
                    notificationID: notificationID
                )
                self.feedbackCenter.attachOperationItems(
                    uniqueNames.map {
                        FeedbackOperationItem(
                            scope: resolvedRootPath,
                            name: $0,
                            state: itemStatesSnapshot[$0] ?? .failed,
                            detail: itemDetailsSnapshot[$0] ?? errorMessage(error)
                        )
                    },
                    notificationID: notificationID,
                    mergeWithExisting: preservePreviousItems
                )
            }
        }
    }
}

// MARK: 远程 + 变基

private struct SubmoduleGitmodulesSnapshot: Equatable, Sendable {
    let present: Bool
    let contents: String?
}

struct SubmoduleRemoveUndoSeed: Sendable {
    let path: String
    let parentHeadID: String
    let gitlinkID: String
    let gitmodulesPresent: Bool
    let gitmodulesContents: String?
}

struct SubmoduleAddUndoSeed: Sendable {
    let path: String
    let parentHeadID: String
    let gitmodulesPresent: Bool
    let gitmodulesContents: String?
}

nonisolated private static func submoduleGitmodulesSnapshot(rootPath: String) throws -> SubmoduleGitmodulesSnapshot {
    let url = URL(fileURLWithPath: rootPath).appendingPathComponent(".gitmodules")
    guard FileManager.default.fileExists(atPath: url.path) else {
        return SubmoduleGitmodulesSnapshot(present: false, contents: nil)
    }
    return SubmoduleGitmodulesSnapshot(
        present: true,
        contents: try String(contentsOf: url, encoding: .utf8)
    )
}

nonisolated private static func ensureSubmoduleUndoWorktreeIsEmpty(
    rootPath: String,
    path: String
) throws {
    let url = URL(fileURLWithPath: rootPath).appendingPathComponent(path, isDirectory: true)
    var isDirectory = ObjCBool(false)
    guard FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory) else {
        return
    }
    guard isDirectory.boolValue else {
        throw NSError(
            domain: "Arbor.SubmoduleUndo",
            code: 1,
            userInfo: [NSLocalizedDescriptionKey: "The submodule path is occupied by a file."]
        )
    }
    guard try FileManager.default.contentsOfDirectory(atPath: url.path).isEmpty else {
        throw NSError(
            domain: "Arbor.SubmoduleUndo",
            code: 2,
            userInfo: [NSLocalizedDescriptionKey: "The submodule worktree contains files created after deinit."]
        )
    }
}

private func submoduleOperationTitle(_ retry: PersistedSubmoduleRetry) -> String {
    switch retry.operation {
    case .add: "Add submodule"
    case .update: retry.path?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
            ? "Update submodule"
            : "Update submodules"
    case .sync: "Sync submodules"
    case .deinitialize: "Deinit submodule"
    case .remove: "Remove submodule"
    case .setBranch: "Set submodule branch"
    }
}

private func submoduleOperationSuccessTitle(_ retry: PersistedSubmoduleRetry) -> String {
    switch retry.operation {
    case .add: "Submodule added"
    case .update: retry.path?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
            ? "Submodule updated"
            : "Submodules updated"
    case .sync: "Submodules synchronized"
    case .deinitialize: "Submodule deinitialized"
    case .remove: "Submodule removed"
    case .setBranch: "Submodule branch set"
    }
}

private func submoduleOperationDetail(_ retry: PersistedSubmoduleRetry) -> String? {
    switch retry.operation {
    case .add:
        return retry.path
    case .update:
        return [
            retry.path.map { "path=\($0)" },
            retry.initFlag.map { "init=\($0)" },
            retry.recursive.map { "recursive=\($0)" },
            retry.remote.map { "remote=\($0)" }
        ].compactMap { $0 }.joined(separator: ", ")
    case .sync:
        return nil
    case .deinitialize, .remove:
        return retry.path
    case .setBranch:
        guard let path = retry.path, let branch = retry.branch else { return nil }
        return "\(path) → \(branch)"
    }
}

private func submoduleNotificationComponent(_ value: String) -> String {
    value
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: ":", with: "_")
        .replacingOccurrences(of: "|", with: "_")
        .replacingOccurrences(of: " ", with: "_")
}

private func submoduleNotificationID(
    _ retry: PersistedSubmoduleRetry,
    rootPath: String
) -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    let options = [
        retry.initFlag.map { "init=\($0)" },
        retry.recursive.map { "recursive=\($0)" },
        retry.remote.map { "remote=\($0)" },
        retry.force.map { "force=\($0)" }
    ].compactMap { $0 }.joined(separator: ",")
    return [
        "git.submodule",
        retry.operation.rawValue,
        submoduleNotificationComponent(URL(fileURLWithPath: projectPath).standardizedFileURL.path),
        submoduleNotificationComponent(URL(fileURLWithPath: rootPath).standardizedFileURL.path),
        submoduleNotificationComponent(retry.path ?? "all"),
        submoduleNotificationComponent(retry.branch ?? ""),
        submoduleNotificationComponent(options)
    ].joined(separator: ".")
}

private func submoduleRetryRequest(
    _ retry: PersistedSubmoduleRetry,
    rootPath: String
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .retrySubmoduleOperation,
        projectPath: projectPath,
        rootPath: rootPath,
        shelfName: "",
        submoduleRetry: retry
    )
}

private func submoduleRetryFeedbackAction(
    _ retry: PersistedSubmoduleRetry,
    rootPath: String
) -> FeedbackAction {
    let request = submoduleRetryRequest(retry, rootPath: rootPath)
    let title: String = switch retry.operation {
    case .add: "Retry Add Submodule"
    case .update: "Retry Submodule Update"
    case .sync: "Retry Submodule Sync"
    case .deinitialize: "Retry Submodule Deinit"
    case .remove: "Retry Remove Submodule"
    case .setBranch: "Retry Set Submodule Branch"
    }
    let initOption = retry.initFlag.map { String($0) } ?? ""
    let recursiveOption = retry.recursive.map { String($0) } ?? ""
    let remoteOption = retry.remote.map { String($0) } ?? ""
    let forceOption = retry.force.map { String($0) } ?? ""
    let identity: String = [
        retry.operation.rawValue,
        retry.path ?? "all",
        retry.branch ?? "",
        retry.url ?? "",
        initOption,
        recursiveOption,
        remoteOption,
        forceOption
    ].joined(separator: "|")
    return FeedbackAction(
        id: "retry-submodule:\(identity)",
        title: title,
        semanticAction: request
    ) {
        handleVCSActionRequest(request)
    }
}

private func submoduleUndoNotificationID(
    _ context: PersistedSubmoduleUndo,
    rootPath: String
) -> String? {
    guard let projectPath, !projectPath.isEmpty else { return nil }
    return [
        "git.submodule.undo",
        context.operation.rawValue,
        submoduleNotificationComponent(URL(fileURLWithPath: projectPath).standardizedFileURL.path),
        submoduleNotificationComponent(URL(fileURLWithPath: rootPath).standardizedFileURL.path),
        submoduleNotificationComponent(context.path),
        submoduleNotificationComponent(context.expectedHeadID)
    ].joined(separator: ".")
}

private func submoduleUndoRequest(
    _ context: PersistedSubmoduleUndo,
    rootPath: String
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .undoSubmoduleOperation,
        projectPath: projectPath,
        rootPath: rootPath,
        shelfName: "",
        submoduleUndo: context
    )
}

private func submoduleUndoFeedbackAction(
    _ context: PersistedSubmoduleUndo,
    rootPath: String
) -> FeedbackAction {
    let request = submoduleUndoRequest(context, rootPath: rootPath)
    let isAdd = context.operation == .add
    let isRemove = context.operation == .remove
    return FeedbackAction(
        id: "undo-submodule-\(context.operation.rawValue):\(context.path):\(context.expectedHeadID)",
        title: isAdd
            ? "Undo Submodule Add"
            : (isRemove ? "Undo Submodule Remove" : "Undo Submodule Deinit"),
        semanticAction: request
    ) {
        handleVCSActionRequest(request)
    }
}

/// Undo an add, deinit, or clean remove only after checking every piece of state
/// that the operation could overwrite. The nested update is issued by the
/// parent repository so the gitlink remains authoritative, matching
/// IntelliJ's submodule model.
private func undoSubmoduleOperation(
    _ context: PersistedSubmoduleUndo,
    rootPath: String
) {
    guard context.operation == .add
        || context.operation == .deinitialize
        || context.operation == .remove else { return }
    let isAdd = context.operation == .add
    let isRemove = context.operation == .remove
    let notificationID = submoduleUndoNotificationID(context, rootPath: rootPath)
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    beginFeedbackOperation(
        isAdd
            ? "Undo Submodule Add"
            : (isRemove ? "Undo Submodule Remove" : "Undo Submodule Deinit"),
        cancelHandle: cancel,
        notificationID: notificationID
    )

    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let currentModules = try rootRepo.submoduleList()
            let currentGitmodules = try ContentView.submoduleGitmodulesSnapshot(rootPath: rootPath)
            if isRemove {
                guard let expectedParentHeadID = context.expectedParentHeadID,
                      let restoreGitmodulesPresent = context.restoreGitmodulesPresent else {
                    throw NSError(
                        domain: "Arbor.SubmoduleUndo",
                        code: 5,
                        userInfo: [NSLocalizedDescriptionKey: "The remove undo context is incomplete."]
                    )
                }
                try rootRepo.submoduleRemoveUndoWithAuthAndCancel(
                    target: SubmoduleRemoveUndoTarget(
                        path: context.path,
                        expectedParentHeadId: expectedParentHeadID,
                        restoreGitlinkId: context.expectedHeadID,
                        expectedGitmodulesPresent: context.expectedGitmodulesPresent,
                        expectedGitmodulesContents: context.expectedGitmodulesContents,
                        restoreGitmodulesPresent: restoreGitmodulesPresent,
                        restoreGitmodulesContents: context.restoreGitmodulesContents
                    ),
                    broker: broker,
                    cancel: cancel
                )
            } else if isAdd {
                guard let currentModule = currentModules.first(where: { $0.path == context.path }),
                      currentModule.state == .clean,
                      !currentModule.dirty,
                      currentModule.headId == context.expectedHeadID,
                      let expectedParentHeadID = context.expectedParentHeadID,
                      currentGitmodules.present == context.expectedGitmodulesPresent,
                      currentGitmodules.contents == context.expectedGitmodulesContents else {
                    throw NSError(
                        domain: "Arbor.SubmoduleUndo",
                        code: 6,
                        userInfo: [NSLocalizedDescriptionKey: "The submodule state changed after add; Undo was refused."]
                    )
                }
                guard (try rootRepo.submoduleWorktreeHasUntrackedOrIgnoredFiles(path: context.path)) == false else {
                    throw NSError(
                        domain: "Arbor.SubmoduleUndo",
                        code: 7,
                        userInfo: [NSLocalizedDescriptionKey: "The nested worktree has changes; Undo was refused."]
                    )
                }
                try rootRepo.submoduleAddUndoWithAuthAndCancel(
                    target: SubmoduleAddUndoTarget(
                        path: context.path,
                        expectedParentHeadId: expectedParentHeadID,
                        expectedSubmoduleHeadId: context.expectedHeadID,
                        expectedGitmodulesPresent: context.expectedGitmodulesPresent,
                        expectedGitmodulesContents: context.expectedGitmodulesContents,
                        restoreGitmodulesPresent: context.restoreGitmodulesPresent ?? false,
                        restoreGitmodulesContents: context.restoreGitmodulesContents
                    ),
                    broker: broker,
                    cancel: cancel
                )
            } else {
                guard let currentModule = currentModules.first(where: { $0.path == context.path }),
                      currentModule.state == .uninitialized,
                      !currentModule.dirty,
                      currentModule.headId == context.expectedHeadID,
                      currentGitmodules.present == context.expectedGitmodulesPresent,
                      currentGitmodules.contents == context.expectedGitmodulesContents else {
                    throw NSError(
                        domain: "Arbor.SubmoduleUndo",
                        code: 3,
                        userInfo: [NSLocalizedDescriptionKey: "The submodule state changed after deinit; Undo was refused."]
                    )
                }
                try ContentView.ensureSubmoduleUndoWorktreeIsEmpty(
                    rootPath: rootPath,
                    path: context.path
                )
                try rootRepo.submoduleUpdatePathWithAuthAndCancel(
                    path: context.path,
                    recursive: false,
                    broker: broker,
                    cancel: cancel
                )
            }
            let restoredModules = try rootRepo.submoduleList()
            let restoredGitmodules = try ContentView.submoduleGitmodulesSnapshot(rootPath: rootPath)
            let restoredModule = restoredModules.first(where: { $0.path == context.path })
            if isAdd {
                guard restoredModule == nil,
                      restoredGitmodules.present == (context.restoreGitmodulesPresent ?? false),
                      restoredGitmodules.contents == context.restoreGitmodulesContents else {
                    throw NSError(
                        domain: "Arbor.SubmoduleUndo",
                        code: 8,
                        userInfo: [NSLocalizedDescriptionKey: "The submodule add was not undone to the expected state."]
                    )
                }
            } else {
                guard let restoredModule,
                      restoredModule.state == .clean,
                      !restoredModule.dirty,
                      restoredModule.headId == context.expectedHeadID,
                      restoredGitmodules.present == (isRemove ? context.restoreGitmodulesPresent : context.expectedGitmodulesPresent),
                      restoredGitmodules.contents == (isRemove ? context.restoreGitmodulesContents : context.expectedGitmodulesContents) else {
                    throw NSError(
                        domain: "Arbor.SubmoduleUndo",
                        code: 4,
                        userInfo: [NSLocalizedDescriptionKey: "The submodule was not restored to the expected clean commit."]
                    )
                }
            }
            await MainActor.run {
                self.submodules = restoredModules
                self.submoduleFeedback = isAdd
                    ? "Submodule add undone"
                    : (isRemove ? "Submodule removal undone" : "Submodule deinitialized state restored")
                self.feedbackCenter.success(
                    isAdd
                        ? "Submodule add undone"
                        : (isRemove ? "Submodule remove undone" : "Submodule deinit undone"),
                    detail: context.path,
                    notificationID: notificationID,
                    notificationGroup: .standard
                )
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                self.submoduleFeedback = errorMessage(error)
                let retryAction = self.submoduleUndoFeedbackAction(context, rootPath: rootPath)
                if let engineError = error as? EngineError, case .Cancelled = engineError {
                    self.feedbackCenter.warning(
                        isAdd
                            ? "Undo Submodule Add canceled"
                            : (isRemove ? "Undo Submodule Remove canceled" : "Undo Submodule Deinit canceled"),
                        detail: context.path,
                        additionalActions: [retryAction],
                        notificationID: notificationID,
                        notificationGroup: .important
                    )
                } else {
                    self.feedbackCenter.error(
                        isAdd
                            ? "Undo Submodule Add failed"
                            : (isRemove ? "Undo Submodule Remove failed" : "Undo Submodule Deinit failed"),
                        detail: errorMessage(error),
                        nextStep: "检查子模块状态后重试；Arbor 不会覆盖现有文件。",
                        additionalActions: [retryAction],
                        notificationID: notificationID,
                        notificationGroup: .important
                    )
                }
            }
        }
    }
}

/// Run a standalone SubmodulePanel operation from durable input, keeping the
/// same command, credential broker, cancellation, and notification lifecycle
/// for both the initial click and a retry restored from Operation Log.
private func submoduleUpdateRestoreAction(
    repo: Repository,
    rootPath: String
) -> FeedbackAction? {
    guard let info = ((try? repo.applyLocalChangesRestoreInfo()) ?? nil),
          info.operation == "submodule-update",
          let savedChangesKind = ArborVCSActionRequest.SavedChangesKind(rawValue: info.kind) else {
        return nil
    }
    let request = ArborVCSActionRequest(
        kind: .restoreApplyLocalChanges,
        projectPath: projectPath,
        rootPath: rootPath,
        shelfName: "",
        savedChangesKind: savedChangesKind,
        savedChangesID: info.identifier
    )
    return FeedbackAction(title: "Resolve local changes", semanticAction: request) {
        self.openApplyLocalChangesRestore(request)
    }
}

private func runSubmoduleOperation(_ retry: PersistedSubmoduleRetry) {
    guard let repo else { return }
    let rootPath = repo.workdir() ?? ""
    let title = submoduleOperationTitle(retry)
    let notificationID = submoduleNotificationID(retry, rootPath: rootPath)
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    let savePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    beginFeedbackOperation(
        title,
        cancelHandle: retry.operation == .setBranch ? nil : cancel,
        notificationID: notificationID
    )
    let beforeRoots = retry.operation == .update
        ? ((try? discoverGitRoots(scanRoot: rootPath, maxDepth: nil)) ?? [])
        : []
    let beforeDeinitUndo: PersistedSubmoduleUndo? = {
        guard retry.operation == .deinitialize,
              let path = retry.path,
              let modules = try? repo.submoduleList(),
              let snapshot = try? ContentView.submoduleGitmodulesSnapshot(rootPath: rootPath) else {
            return nil
        }
        return ContentView.submoduleDeinitUndoContext(
            path: path,
            before: modules,
            gitmodulesPresent: snapshot.present,
            gitmodulesContents: snapshot.contents
        )
    }()
    let beforeAddUndo: SubmoduleAddUndoSeed? = {
        guard retry.operation == .add,
              let path = retry.path,
              let modules = try? repo.submoduleList(),
              let snapshot = try? ContentView.submoduleGitmodulesSnapshot(rootPath: rootPath) else {
            return nil
        }
        let pathURL = URL(fileURLWithPath: rootPath).appendingPathComponent(path, isDirectory: true)
        return ContentView.submoduleAddUndoSeed(
            path: path,
            before: modules,
            parentHeadID: repo.headCommitId(),
            gitmodulesPresent: snapshot.present,
            gitmodulesContents: snapshot.contents,
            pathExists: FileManager.default.fileExists(atPath: pathURL.path)
        )
    }()
    let beforeRemoveUndo: SubmoduleRemoveUndoSeed? = {
        guard retry.operation == .remove,
              let path = retry.path,
              let modules = try? repo.submoduleList(),
              let snapshot = try? ContentView.submoduleGitmodulesSnapshot(rootPath: rootPath) else {
            return nil
        }
        return ContentView.submoduleRemoveUndoSeed(
            repo: repo,
            path: path,
            before: modules,
            parentHeadID: repo.headCommitId(),
            gitmodulesPresent: snapshot.present,
            gitmodulesContents: snapshot.contents
        )
    }()

    Task.detached(priority: .userInitiated) {
        do {
            switch retry.operation {
            case .add:
                guard let url = retry.url, let path = retry.path else {
                    throw EngineError.GitOperation(message: "submodule add retry is missing URL or path")
                }
                try repo.submoduleAddWithAuthAndCancel(url: url, path: path, broker: broker, cancel: cancel)
            case .update:
                if let path = retry.path?.trimmingCharacters(in: .whitespacesAndNewlines),
                   !path.isEmpty {
                    _ = try runSubmoduleUpdateWithPolicy(
                        parentPath: rootPath,
                        path: path,
                        recursive: retry.recursive ?? true,
                        broker: broker,
                        cancel: cancel,
                        savePolicy: savePolicy
                    )
                } else {
                    try repo.submoduleUpdateWithOptionsWithAuthAndCancel(
                        init: retry.initFlag ?? true,
                        recursive: retry.recursive ?? false,
                        remote: retry.remote ?? false,
                        broker: broker,
                        cancel: cancel
                    )
                }
            case .sync:
                try repo.submoduleSyncWithAuthAndCancel(broker: broker, cancel: cancel)
            case .deinitialize:
                guard let path = retry.path else {
                    throw EngineError.GitOperation(message: "submodule deinit retry is missing path")
                }
                try repo.submoduleDeinitWithAuthAndCancel(
                    path: path,
                    force: retry.force ?? true,
                    broker: broker,
                    cancel: cancel
                )
            case .remove:
                guard let path = retry.path else {
                    throw EngineError.GitOperation(message: "submodule remove retry is missing path")
                }
                try repo.submoduleRemoveWithAuthAndCancel(path: path, broker: broker, cancel: cancel)
            case .setBranch:
                guard let path = retry.path, let branch = retry.branch else {
                    throw EngineError.GitOperation(message: "submodule branch retry is missing path or branch")
                }
                try repo.submoduleSetBranch(path: path, branch: branch)
            }

            let afterRoots = retry.operation == .update
                ? ((try? discoverGitRoots(scanRoot: rootPath, maxDepth: nil)) ?? [])
                : []
            let modules = (retry.operation == .add || retry.operation == .sync || retry.operation == .remove || retry.operation == .deinitialize)
                ? (try? repo.submoduleList())
                : nil
            let afterAddSnapshot = retry.operation == .add
                ? (try? ContentView.submoduleGitmodulesSnapshot(rootPath: rootPath))
                : nil
            let afterDeinitSnapshot = retry.operation == .deinitialize
                ? (try? ContentView.submoduleGitmodulesSnapshot(rootPath: rootPath))
                : nil
            let afterRemoveSnapshot = retry.operation == .remove
                ? (try? ContentView.submoduleGitmodulesSnapshot(rootPath: rootPath))
                : nil
            await MainActor.run {
                self.submoduleFeedback = submoduleOperationSuccessTitle(retry)
                if let modules { self.submodules = modules }
                if retry.operation == .add {
                    self.submoduleUrl = ""
                    self.submodulePath = ""
                }
                var actions: [FeedbackAction] = []
                if retry.operation == .update {
                    let targets = ContentView.submoduleUpdateRollbackTargets(before: beforeRoots, after: afterRoots)
                    if let undoAction = self.submoduleUpdateRollbackAction(targets: targets) {
                        actions.append(undoAction)
                    }
                }
                if let beforeAddUndo,
                   let modules,
                   let afterAddSnapshot,
                   let addedModule = modules.first(where: { $0.path == beforeAddUndo.path }),
                   let undoContext = ContentView.submoduleAddUndoContext(
                       beforeAddUndo,
                       module: addedModule,
                       gitmodulesPresent: afterAddSnapshot.present,
                       gitmodulesContents: afterAddSnapshot.contents
                   ) {
                    actions.append(
                        self.submoduleUndoFeedbackAction(
                            undoContext,
                            rootPath: rootPath
                        )
                    )
                }
                if let beforeDeinitUndo,
                   let modules,
                   let afterDeinitSnapshot,
                   let undoContext = ContentView.submoduleDeinitUndoTargetAfterDeinit(
                       beforeDeinitUndo,
                       modules: modules,
                       gitmodulesPresent: afterDeinitSnapshot.present,
                       gitmodulesContents: afterDeinitSnapshot.contents
                   ) {
                    actions.append(
                        self.submoduleUndoFeedbackAction(
                            undoContext,
                            rootPath: rootPath
                        )
                    )
                }
                if let beforeRemoveUndo,
                   let afterRemoveSnapshot,
                   let undoContext = ContentView.submoduleRemoveUndoContextAfterRemove(
                       beforeRemoveUndo,
                       gitmodulesPresent: afterRemoveSnapshot.present,
                       gitmodulesContents: afterRemoveSnapshot.contents
                   ) {
                    actions.append(
                        self.submoduleUndoFeedbackAction(
                            undoContext,
                            rootPath: rootPath
                        )
                    )
                }
                self.feedbackCenter.success(
                    submoduleOperationSuccessTitle(retry),
                    detail: submoduleOperationDetail(retry),
                    additionalActions: actions,
                    notificationID: notificationID,
                    notificationGroup: .standard
                )
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                self.submoduleFeedback = errorMessage(error)
                let retryAction = self.submoduleRetryFeedbackAction(retry, rootPath: rootPath)
                let restoreAction = retry.operation == .update
                    ? self.submoduleUpdateRestoreAction(repo: repo, rootPath: rootPath)
                    : nil
                let actions = [retryAction] + [restoreAction].compactMap { $0 }
                if let engineError = error as? EngineError, case .Cancelled = engineError {
                    self.feedbackCenter.warning(
                        "\(title) canceled",
                        detail: submoduleOperationDetail(retry),
                        additionalActions: actions,
                        notificationID: notificationID,
                        notificationGroup: .important
                    )
                } else {
                    self.feedbackCenter.error(
                        "\(title) failed",
                        detail: errorMessage(error),
                        nextStep: restoreAction == nil
                            ? "检查子模块状态后重试。"
                            : "先 Resolve local changes，再重试子模块 Update。",
                        additionalActions: actions,
                        notificationID: notificationID,
                        notificationGroup: .important
                    )
                }
            }
        }
    }
}

func submoduleAdd() {
    guard !submoduleUrl.trimmingCharacters(in: .whitespaces).isEmpty,
          !submodulePath.trimmingCharacters(in: .whitespaces).isEmpty else { return }
    runSubmoduleOperation(
        PersistedSubmoduleRetry(
            operation: .add,
            url: submoduleUrl.trimmingCharacters(in: .whitespacesAndNewlines),
            path: submodulePath.trimmingCharacters(in: .whitespacesAndNewlines)
        )
    )
}

func submoduleUpdate() {
    runSubmoduleOperation(
        PersistedSubmoduleRetry(operation: .update, initFlag: true, recursive: true, remote: false)
    )
}

/// Update one initialized submodule from its parent, matching IntelliJ's
/// path-scoped `GitSubmoduleUpdater` command. Dirty submodule worktrees are
/// preserved with the configured stash/Shelf policy by the Rust engine.
func submoduleUpdatePath(_ path: String) {
    let normalized = path.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalized.isEmpty else { return }
    runSubmoduleOperation(
        PersistedSubmoduleRetry(
            operation: .update,
            path: normalized,
            initFlag: false,
            recursive: true,
            remote: false
        )
    )
}

func submoduleSync() {
    runSubmoduleOperation(PersistedSubmoduleRetry(operation: .sync))
}

func loadSubmodules() {
    guard let repo else { return }
    Task.detached(priority: .userInitiated) {
        let modules = (try? repo.submoduleList()) ?? []
        await MainActor.run { self.submodules = modules }
    }
}

/// 在嵌套子模块仓库中打开提交日志；父仓库的 gitlink 只代表固定提交，不是日志数据源。
func openSubmoduleLog(_ path: String) {
    guard let repo else { return }
    let path = path.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !path.isEmpty else { return }

    submoduleLogPath = path
    submoduleLogEntries = []
    submoduleLogError = nil
    showSubmoduleLog = true
    Task.detached(priority: .userInitiated) {
        do {
            let commits = try repo.submoduleLog(path: path, limit: 200)
            await MainActor.run {
                guard self.showSubmoduleLog, self.submoduleLogPath == path else { return }
                self.submoduleLogEntries = commits
            }
        } catch {
            await MainActor.run {
                guard self.showSubmoduleLog, self.submoduleLogPath == path else { return }
                self.submoduleLogError = errorMessage(error)
            }
        }
    }
}

