/// Phase 5：重命名 tag。
func tagRename(_ old: String, _ new: String) {
    guard let repo, !new.isEmpty else { return }
    beginFeedbackOperation("Rename tag")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.tagRename(old: old, new: new)
            await MainActor.run {
                self.feedbackCenter.success("Tag renamed", detail: "\(old) → \(new)")
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Rename tag failed", detail: errorMessage(error), nextStep: "检查 tag 名后重试。")
            }
        }
    }
}

/// Phase 5：删除 tag。
func tagDelete(_ name: String) {
    guard let repo else { return }
    beginFeedbackOperation("Delete tag")
    Task.detached(priority: .userInitiated) {
        do {
            guard let tag = try repo.tagList().first(where: { $0.name == name }) else {
                throw NSError(
                    domain: "Arbor.TagDelete",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "Tag not found: \(name)"]
                )
            }
            try repo.tagDelete(name: name)
            await MainActor.run {
                self.feedbackCenter.success("Tag deleted", detail: name)
                self.tagDeleteRecovery = TagDeleteRecoveryContext(repo: repo, tag: tag, rootPath: nil)
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Delete tag failed", detail: errorMessage(error), nextStep: "tag 可能已被删除。")
            }
        }
    }
}

func restoreDeletedTag(_ context: TagDeleteRecoveryContext) {
    beginFeedbackOperation("Restore tag")
    Task.detached(priority: .userInitiated) {
        do {
            // IntelliJ restores the saved tag tip as a new lightweight tag;
            // using the full peeled id avoids dependence on reflog retention.
            try context.repo.tagCreate(name: context.tag.name, at: context.tag.id)
            await MainActor.run {
                self.tagDeleteRecovery = nil
                if let rootPath = context.rootPath {
                    self.loadMultiRoots()
                    self.feedbackCenter.success("Tag restored", detail: "\(context.tag.name) · \(rootPath)")
                } else {
                    self.refreshAll(showFeedback: false)
                    self.feedbackCenter.success("Tag restored", detail: context.tag.name)
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Restore tag failed",
                    detail: "\(context.tag.name): \(errorMessage(error))"
                )
            }
        }
    }
}

/// IntelliJ's local tag deletion notification exposes a follow-up action that
/// removes the same tag from every configured remote. Each remote is checked
/// independently; an already absent tag is successful, while a real push
/// failure keeps the recovery surface open for another attempt.
func deleteRemoteTagFromRecovery(_ context: TagDeleteRecoveryContext) {
    let remotes = context.remotes
    guard !remotes.isEmpty else {
        feedbackCenter.warning("No remotes configured", detail: context.tag.name)
        return
    }
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Delete remote tag", cancelHandle: cancel)
    let broker = credentialAuth.broker
    Task.detached(priority: .userInitiated) {
        var deleted: [String] = []
        var missing: [String] = []
        var failures: [String] = []
        var cancelled = false
        for remote in remotes {
            if cancel.isCancelled() {
                cancelled = true
                break
            }
            do {
                let didDelete = try context.repo.deleteRemoteTagWithAuthLeaseAndCancel(
                    remote: remote.name,
                    tag: context.tag.name,
                    expectedObjectId: context.tag.objectId,
                    broker: broker,
                    cancel: cancel
                )
                if didDelete {
                    deleted.append(remote.name)
                } else {
                    missing.append(remote.name)
                }
            } catch {
                if cancel.isCancelled() {
                    cancelled = true
                    break
                }
                failures.append("\(remote.name): \(friendlyRemoteError(error))")
            }
        }
        let deletedRemotes = deleted
        let missingRemotes = missing
        let failuresToReport = failures
        let wasCancelled = cancelled
        await MainActor.run {
            if failuresToReport.isEmpty && !wasCancelled {
                self.tagDeleteRecovery = nil
                self.refreshAll(showFeedback: false)
                let detail = deletedRemotes.isEmpty
                    ? "\(context.tag.name) was not present on configured remotes"
                    : "\(context.tag.name) · \(deletedRemotes.joined(separator: ", "))"
                self.feedbackCenter.success("Remote tag deletion completed", detail: detail)
            } else if wasCancelled {
                self.feedbackCenter.warning(
                    "Remote tag deletion canceled",
                    detail: "Deleted \(deletedRemotes.count); already absent \(missingRemotes.count).",
                    nextStep: "Retry the recovery action to process the remaining remotes."
                )
            } else {
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                let missingDetail = missingRemotes.isEmpty
                    ? ""
                    : "\nAlready absent: \(missingRemotes.joined(separator: ", "))"
                self.feedbackCenter.warning(
                    "Remote tag deletion partially completed",
                    detail: failuresToReport.joined(separator: "\n") + missingDetail,
                    nextStep: "Review the failed remotes and retry the action."
                )
            }
        }
    }
}

/// Phase 5：推送 tag 到远程。
func tagPushToRemote(_ name: String, remote selectedRemote: String? = nil) {
    guard let repo,
          let remote = resolveSelectedRemoteName(
              selectedRemote: selectedRemote,
              availableRemoteNames: remotes.map(\.name)
          ) else {
        feedbackCenter.warning(
            "Choose a remote before pushing the tag",
            detail: "Multiple remotes are configured for this Git root."
        )
        return
    }
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Push tag", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            try repo.tagPushWithAuthAndCancel(
                remote: remote,
                tag: name,
                broker: broker,
                cancel: cancel
            )
            await MainActor.run { self.feedbackCenter.success("Tag pushed", detail: "\(remote)/\(name)") }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Push tag failed", detail: friendlyRemoteError(error), nextStep: "检查远程与 tag 后重试。")
                if self.isAuthenticationFailure(error) { self.showHostingAuthPrompt = true }
            }
        }
    }
}

/// Push all local tags to the current root's explicitly selected or only configured remote.
func pushAllTagsToRemote(remote selectedRemote: String? = nil) {
    guard let repo,
          let remote = resolveSelectedRemoteName(
              selectedRemote: selectedRemote,
              availableRemoteNames: remotes.map(\.name)
          ) else {
        feedbackCenter.warning(
            "Choose a remote before pushing all tags",
            detail: "Multiple remotes are configured for this Git root."
        )
        return
    }
    let broker = credentialAuth.broker
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Push all tags", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            try repo.pushRefspecWithAuthAndCancel(
                remote: remote,
                refspec: "refs/tags/*:refs/tags/*",
                force: false,
                forceWithLease: false,
                broker: broker,
                cancel: cancel
            )
            await MainActor.run {
                self.feedbackCenter.success("All tags pushed", detail: remote)
                self.refreshAll(showFeedback: false)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Push all tags failed",
                    detail: friendlyRemoteError(error),
                    nextStep: "Check the remote and tag names, then retry."
                )
            }
        }
    }
}

func submoduleRemove(_ path: String) {
    let alert = NSAlert()
    alert.messageText = "Remove submodule?"
    alert.informativeText = "This removes \(path) from .gitmodules, the index and the worktree."
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Remove")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    runSubmoduleOperation(
        PersistedSubmoduleRetry(
            operation: .remove,
            path: path.trimmingCharacters(in: .whitespacesAndNewlines)
        )
    )
}

// MARK: Worktrees

func loadWorktrees() {
    guard let repo else { return }
    Task.detached(priority: .userInitiated) {
        let items = (try? repo.worktreeList()) ?? []
        await MainActor.run { self.worktrees = items }
    }
}

func createWorktree(
    path: String,
    branch: String,
    revision: String,
    rootPath: String? = nil
) {
    let targetRepo: Repository
    let targetRootPath: String
    if let rootPath {
        guard let openedRepo = try? openRepository(path: rootPath) else {
            feedbackCenter.error("Create worktree failed", detail: "The selected Git root could not be opened.")
            return
        }
        targetRepo = openedRepo
        targetRootPath = rootPath
    } else {
        guard let repo, let workdir = repo.workdir(), !workdir.isEmpty else { return }
        targetRepo = repo
        targetRootPath = workdir
    }
    let path = path.trimmingCharacters(in: .whitespacesAndNewlines)
    let branch = branch.trimmingCharacters(in: .whitespacesAndNewlines)
    let revision = revision.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !path.isEmpty else { return }
    beginFeedbackOperation("Create worktree")
    Task.detached(priority: .userInitiated) {
        do {
            try targetRepo.worktreeAdd(
                path: path,
                newBranch: branch.isEmpty ? nil : branch,
                revision: revision.isEmpty ? nil : revision
            )
            let items = try targetRepo.worktreeList()
            await MainActor.run {
                if self.repo?.workdir() == targetRootPath {
                    self.worktrees = items
                }
                self.loadMultiRoots()
                self.worktreeFeedback = "已创建 worktree：\(path)"
                self.feedbackCenter.success("Worktree created", detail: path)
            }
        } catch {
            await MainActor.run {
                self.worktreeFeedback = errorMessage(error)
                self.feedbackCenter.error("Create worktree failed", detail: errorMessage(error))
            }
        }
    }
}

func removeWorktree(path: String, force: Bool) {
    guard let repo else { return }
    let alert = NSAlert()
    alert.messageText = force ? "Force remove worktree?" : "Remove worktree?"
    alert.informativeText = "\(path) 中未提交的修改可能会丢失。"
    alert.alertStyle = .warning
    alert.addButton(withTitle: force ? "Force Remove" : "Remove")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    beginFeedbackOperation("Remove worktree")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.worktreeRemove(path: path, force: force)
            let items = try repo.worktreeList()
            await MainActor.run {
                self.worktrees = items
                self.worktreeFeedback = "已移除 worktree：\(path)"
                self.feedbackCenter.success("Worktree removed", detail: path)
            }
        } catch {
            await MainActor.run {
                self.worktreeFeedback = errorMessage(error)
                self.feedbackCenter.error("Remove worktree failed", detail: errorMessage(error))
            }
        }
    }
}

func lockWorktree(_ path: String) {
    updateWorktreeLock(path: path, lock: true)
}

func unlockWorktree(_ path: String) {
    updateWorktreeLock(path: path, lock: false)
}

private func updateWorktreeLock(path: String, lock: Bool) {
    guard let repo else { return }
    beginFeedbackOperation(lock ? "Lock worktree" : "Unlock worktree")
    Task.detached(priority: .userInitiated) {
        do {
            if lock { try repo.worktreeLock(path: path) }
            else { try repo.worktreeUnlock(path: path) }
            let items = try repo.worktreeList()
            await MainActor.run {
                self.worktrees = items
                self.feedbackCenter.success(lock ? "Worktree locked" : "Worktree unlocked", detail: path)
            }
        } catch {
            await MainActor.run {
                self.worktreeFeedback = errorMessage(error)
                self.feedbackCenter.error(lock ? "Lock worktree failed" : "Unlock worktree failed", detail: errorMessage(error))
            }
        }
    }
}

func pruneWorktrees() {
    guard let repo else { return }
    beginFeedbackOperation("Prune worktrees")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.worktreePrune()
            let items = try repo.worktreeList()
            await MainActor.run {
                self.worktrees = items
                self.feedbackCenter.success("Worktrees pruned")
            }
        } catch {
            await MainActor.run { self.feedbackCenter.error("Prune worktrees failed", detail: errorMessage(error)) }
        }
    }
}

/// 重新加载远程列表到状态（Configure Remotes Dialog 与推送选择共用）。
func loadRemotes() {
    guard let repo else { return }
    Task.detached(priority: .userInitiated) {
        do {
            let rs = try repo.remoteList()
            await MainActor.run {
                self.remotes = rs
                self.restoreRemoteProtectedBranchPatterns(for: rs, projectPath: self.projectPath)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Load remotes failed", detail: errorMessage(error), nextStep: "检查仓库配置后重试。")
            }
        }
    }
}

/// 打开指定 Git root 的 Configure Remotes，而不是复用当前窗口 repository
/// 的 remote 状态。Push 对话框和 Branches Popup 都通过这个入口进入。
func beginConfigureRemotes() {
    guard let projectPath else { return }
    beginFeedbackOperation("Load remotes")
    Task.detached(priority: .userInitiated) {
        do {
            let roots = try loadRemoteConfigRoots(scanRoot: projectPath)
            await MainActor.run {
                self.multiRootRemoteConfigAggregateContext = MultiRootRemoteConfigAggregateContext(roots: roots)
                self.feedbackCenter.success("Remotes loaded", detail: "\(roots.count) repositories")
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Load remotes failed",
                    detail: errorMessage(error),
                    nextStep: "Check the selected Git roots and retry."
                )
            }
        }
    }
}

func loadMultiRootRemoteConfigAggregate() {
    guard let projectPath else { return }
    Task.detached(priority: .userInitiated) {
        do {
            let roots = try loadRemoteConfigRoots(scanRoot: projectPath)
            await MainActor.run {
                guard self.multiRootRemoteConfigAggregateContext != nil else { return }
                self.multiRootRemoteConfigAggregateContext = MultiRootRemoteConfigAggregateContext(roots: roots)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Refresh remotes failed",
                    detail: errorMessage(error),
                    nextStep: "Check the selected Git roots and retry."
                )
            }
        }
    }
}

func beginMultiRootRemoteConfig(rootPath: String, selectedRemote: String? = nil) {
    beginFeedbackOperation("Load root remotes")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let rootRemotes = try rootRepo.remoteList()
            let selected = selectedRemote.flatMap { name in
                rootRemotes.first(where: { $0.name == name })
            }
            await MainActor.run {
                self.multiRootRemoteName = selected?.name ?? ""
                self.multiRootRemoteURL = selected?.url ?? ""
                self.multiRootRemotePushURL = selected?.pushUrl ?? ""
                self.multiRootRemoteFetchRefspec = selected?.fetchRefspec ?? ""
                self.multiRootRemotePushRefspec = selected?.pushRefspec ?? ""
                self.multiRootRemoteConfigContext = MultiRootRemoteConfigContext(
                    rootPath: rootPath,
                    remotes: rootRemotes
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Load root remotes failed",
                    detail: "\(rootPath): \(errorMessage(error))",
                    nextStep: "Check the selected Git root and retry."
                )
            }
        }
    }
}

func loadMultiRootRemoteConfig(rootPath: String) {
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let rootRemotes = try rootRepo.remoteList()
            await MainActor.run {
                guard self.multiRootRemoteConfigContext?.rootPath == rootPath else { return }
                self.multiRootRemoteConfigContext = MultiRootRemoteConfigContext(
                    rootPath: rootPath,
                    remotes: rootRemotes
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Refresh root remotes failed",
                    detail: "\(rootPath): \(errorMessage(error))"
                )
            }
        }
    }
}

func saveRemoteConfigInRoot(rootPath: String) {
    let name = multiRootRemoteName.trimmingCharacters(in: .whitespacesAndNewlines)
    let url = multiRootRemoteURL.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !name.isEmpty, !url.isEmpty else { return }
    let pushURL = multiRootRemotePushURL.trimmingCharacters(in: .whitespacesAndNewlines)
    let fetchRefspec = multiRootRemoteFetchRefspec.trimmingCharacters(in: .whitespacesAndNewlines)
    let pushRefspec = multiRootRemotePushRefspec.trimmingCharacters(in: .whitespacesAndNewlines)
    let broker = credentialAuth.broker
    beginFeedbackOperation("Save root remote")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            if let checkFailure = try remoteURLCheckFailure(repo: rootRepo, url: url, broker: broker) {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Remote URL check failed",
                        detail: "\(url): \(checkFailure)",
                        nextStep: "Check the URL and authentication, then retry."
                    )
                }
                return
            }
            try rootRepo.remoteSetUrl(name: name, url: url)
            try rootRepo.remoteSetPushUrl(name: name, pushUrl: pushURL)
            try rootRepo.remoteSetRefspecs(
                name: name,
                fetchRefspec: fetchRefspec.isEmpty ? nil : fetchRefspec,
                pushRefspec: pushRefspec.isEmpty ? nil : pushRefspec
            )
            await MainActor.run {
                self.feedbackCenter.success("Root remote updated", detail: "\(name) · \(rootPath)")
                self.loadMultiRootRemoteConfig(rootPath: rootPath)
                self.loadMultiRootRemoteConfigAggregate()
                self.loadMultiRoots()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Save root remote failed",
                    detail: "\(name) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Check the URL and refspec, then retry."
                )
            }
        }
    }
}

func addRemoteInRoot(rootPath: String, fetchAfterAdd: Bool = true) {
    let name = multiRootRemoteName.trimmingCharacters(in: .whitespacesAndNewlines)
    let url = multiRootRemoteURL.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !name.isEmpty, !url.isEmpty else { return }
    addRemoteInRoot(rootPath: rootPath, name: name, url: url, fetchAfterAdd: fetchAfterAdd)
}

func addRemoteInRoot(
    rootPath: String,
    name: String,
    url: String,
    fetchAfterAdd: Bool = true,
    completion: @escaping (Bool) -> Void = { _ in }
) {
    let name = name.trimmingCharacters(in: .whitespacesAndNewlines)
    let url = url.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !name.isEmpty, !url.isEmpty else {
        completion(false)
        return
    }
    let broker = credentialAuth.broker
    beginFeedbackOperation("Add root remote")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            if let checkFailure = try remoteURLCheckFailure(repo: rootRepo, url: url, broker: broker) {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Remote URL check failed",
                        detail: "\(url): \(checkFailure)",
                        nextStep: "Check the URL and authentication, then retry."
                    )
                    completion(false)
                }
                return
            }
            try rootRepo.remoteAdd(name: name, url: url)
            await MainActor.run {
                if self.multiRootRemoteConfigContext?.rootPath == rootPath {
                    self.multiRootRemoteName = ""
                    self.multiRootRemoteURL = ""
                    self.multiRootRemotePushURL = ""
                    self.multiRootRemoteFetchRefspec = ""
                    self.multiRootRemotePushRefspec = ""
                }
                self.feedbackCenter.success("Root remote added", detail: "\(name) · \(rootPath)")
                completion(true)
                self.loadMultiRootRemoteConfig(rootPath: rootPath)
                self.loadMultiRootRemoteConfigAggregate()
                self.loadMultiRoots()
                if fetchAfterAdd {
                    self.fetchRemoteInRoot(rootPath: rootPath, remote: name)
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Add root remote failed",
                    detail: "\(name) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Check the remote name and URL, then retry."
                )
                completion(false)
            }
        }
    }
}

func updateRemoteInRoot(
    rootPath: String,
    oldName: String,
    name: String,
    url: String,
    pushURL: String,
    fetchRefspec: String,
    pushRefspec: String,
    fetchAfterUpdate: Bool,
    completion: @escaping (Bool) -> Void = { _ in }
) {
    let oldName = oldName.trimmingCharacters(in: .whitespacesAndNewlines)
    let name = name.trimmingCharacters(in: .whitespacesAndNewlines)
    let url = url.trimmingCharacters(in: .whitespacesAndNewlines)
    let pushURL = pushURL.trimmingCharacters(in: .whitespacesAndNewlines)
    let fetchRefspec = fetchRefspec.trimmingCharacters(in: .whitespacesAndNewlines)
    let pushRefspec = pushRefspec.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !oldName.isEmpty, !name.isEmpty, !url.isEmpty else {
        completion(false)
        return
    }
    let broker = credentialAuth.broker
    beginFeedbackOperation("Update root remote")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            if let checkFailure = try remoteURLCheckFailure(repo: rootRepo, url: url, broker: broker) {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Remote URL check failed",
                        detail: "\(url): \(checkFailure)",
                        nextStep: "Check the URL and authentication, then retry."
                    )
                    completion(false)
                }
                return
            }
            if oldName != name {
                try rootRepo.remoteRename(old: oldName, new: name)
            }
            try rootRepo.remoteSetUrl(name: name, url: url)
            try rootRepo.remoteSetPushUrl(name: name, pushUrl: pushURL)
            try rootRepo.remoteSetRefspecs(
                name: name,
                fetchRefspec: fetchRefspec.isEmpty ? nil : fetchRefspec,
                pushRefspec: pushRefspec.isEmpty ? nil : pushRefspec
            )
            await MainActor.run {
                self.feedbackCenter.success("Root remote updated", detail: "\(name) · \(rootPath)")
                completion(true)
                self.loadMultiRootRemoteConfig(rootPath: rootPath)
                self.loadMultiRootRemoteConfigAggregate()
                self.loadMultiRoots()
                if fetchAfterUpdate {
                    self.fetchRemoteInRoot(rootPath: rootPath, remote: name)
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Update root remote failed",
                    detail: "\(name) · \(rootPath): \(errorMessage(error))",
                    nextStep: "Check the remote name, URL, and refspec, then retry."
                )
                completion(false)
            }
        }
    }
}

func fetchRemoteInRoot(rootPath: String, remote: String) {
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Fetch", cancelHandle: cancel)
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            let outcome = try rootRepo.fetchWithOptionsAndAuthAndCancel(
                remote: remote,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel
            )
            let detail = outcome.updated.isEmpty ? "无更新" : outcome.updated.joined(separator: ", ")
            await MainActor.run {
                self.feedbackCenter.success("Fetch completed", detail: "\(remote) · \(detail)")
                self.loadMultiRootRemoteConfig(rootPath: rootPath)
                self.loadMultiRootRemoteConfigAggregate()
                self.loadMultiRoots()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Fetch failed",
                    detail: "\(remote) · \(rootPath): \(friendlyRemoteError(error))",
                    nextStep: "Check the remote and Git identity, then retry."
                )
            }
        }
    }
}

func removeRemoteInRoot(rootPath: String, name: String) {
    guard confirmRemoteRemoval(name) else { return }
    beginFeedbackOperation("Remove root remote")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            try rootRepo.remoteRemove(name: name)
            await MainActor.run {
                self.feedbackCenter.success("Root remote removed", detail: "\(name) · \(rootPath)")
                self.loadMultiRootRemoteConfig(rootPath: rootPath)
                self.loadMultiRootRemoteConfigAggregate()
                self.loadMultiRoots()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Remove root remote failed",
                    detail: "\(name) · \(rootPath): \(errorMessage(error))"
                )
            }
        }
    }
}

/// IntelliJ's MultipleGroupActions removes each selected remote group while
/// retaining the owning Git root. A failure in one root must not prevent the
/// other selected remotes from being attempted.
func removeSelectedRemotesInRoots(_ groups: [BranchDashboardRemoteGroup]) {
    let selected = Array(Set(groups)).sorted {
        if $0.rootPath == $1.rootPath { return $0.name < $1.name }
        return $0.rootPath < $1.rootPath
    }
    guard !selected.isEmpty, !multiRootRunning else { return }

    let alert = NSAlert()
    alert.messageText = "Remove selected remotes?"
    alert.informativeText = selected
        .map { "\($0.name) · \($0.rootPath)" }
        .joined(separator: "\n")
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Remove")
    alert.addButton(withTitle: "Cancel")
    alert.buttons.first?.hasDestructiveAction = true
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    let displayNames = Dictionary(
        uniqueKeysWithValues: multiRootBranchSnapshots.map { ($0.rootPath, $0.displayName) }
    )
    multiRootRunning = true
    beginFeedbackOperation("Remove selected remotes")
    Task.detached(priority: .userInitiated) {
        var results: [RootOperationResult] = []
        for group in selected {
            do {
                let rootRepo = try openRepository(path: group.rootPath)
                try rootRepo.remoteRemove(name: group.name)
                results.append(
                    RootOperationResult(
                        rootPath: group.rootPath,
                        displayName: displayNames[group.rootPath] ?? group.rootPath,
                        success: true,
                        skipped: false,
                        message: "Removed \(group.name)"
                    )
                )
            } catch {
                results.append(
                    RootOperationResult(
                        rootPath: group.rootPath,
                        displayName: displayNames[group.rootPath] ?? group.rootPath,
                        success: false,
                        skipped: false,
                        message: "\(group.name): \(errorMessage(error))"
                    )
                )
            }
        }

        let completedResults = results
        let completedFailures = completedResults.filter { !$0.success }
        await MainActor.run {
            self.multiRootRunning = false
            self.multiRootResults = completedResults
            self.loadMultiRootRemoteConfigAggregate()
            self.loadMultiRoots()
            if completedFailures.isEmpty {
                self.feedbackCenter.success(
                    "Selected remotes removed",
                    detail: "\(selected.count) remotes"
                )
            } else {
                self.toolWindowMode = .operations
                self.toolWindowExpanded = true
                self.feedbackCenter.warning(
                    "Selected remote removal partially completed",
                    detail: completedFailures.map { "\($0.displayName): \($0.message)" }.joined(separator: "\n"),
                    nextStep: "Review the failed remote removals and retry them individually."
                )
            }
        }
    }
}

func renameRemoteInRoot(rootPath: String, old: String, new: String) {
    let newName = new.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !newName.isEmpty, newName != old else { return }
    beginFeedbackOperation("Rename root remote")
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: rootPath)
            try rootRepo.remoteRename(old: old, new: newName)
            await MainActor.run {
                self.multiRootRemoteName = newName
                self.feedbackCenter.success("Root remote renamed", detail: "\(old) → \(newName) · \(rootPath)")
                self.loadMultiRootRemoteConfig(rootPath: rootPath)
                self.loadMultiRootRemoteConfigAggregate()
                self.loadMultiRoots()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Rename root remote failed",
                    detail: "\(old) → \(newName) · \(rootPath): \(errorMessage(error))"
                )
            }
        }
    }
}

/// REMOTE-001：保存当前编辑的远程配置（URL/push URL/refspec）。
func saveRemoteConfig() {
    guard let repo, !remoteName.isEmpty, !remoteUrl.isEmpty else { return }
    let name = remoteName.trimmingCharacters(in: .whitespaces)
    let url = remoteUrl.trimmingCharacters(in: .whitespaces)
    let pushUrl = remotePushUrl.trimmingCharacters(in: .whitespaces)
    let fetchRefspec = remoteFetchRefspec.trimmingCharacters(in: .whitespaces)
    let pushRefspec = remotePushRefspec.trimmingCharacters(in: .whitespaces)
    let broker = credentialAuth.broker
    beginFeedbackOperation("Save remote")
    Task.detached(priority: .userInitiated) {
        do {
            if let checkFailure = try remoteURLCheckFailure(repo: repo, url: url, broker: broker) {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Remote URL check failed",
                        detail: "\(url): \(checkFailure)",
                        nextStep: "Check the URL and authentication, then retry."
                    )
                }
                return
            }
            try repo.remoteSetUrl(name: name, url: url)
            try repo.remoteSetPushUrl(name: name, pushUrl: pushUrl)
            try repo.remoteSetRefspecs(
                name: name,
                fetchRefspec: fetchRefspec.isEmpty ? nil : fetchRefspec,
                pushRefspec: pushRefspec.isEmpty ? nil : pushRefspec
            )
            await MainActor.run {
                self.feedbackCenter.success("Remote updated", detail: name)
            }
            await MainActor.run { self.loadRemotes() }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Save remote failed", detail: errorMessage(error), nextStep: "检查名称与 URL 后重试。")
            }
        }
    }
}

/// REMOTE-001：重命名远程（config + refs/remotes 一并处理）。
func remoteRename(_ old: String, _ new: String) {
    guard let repo, !new.isEmpty else { return }
    let newName = new.trimmingCharacters(in: .whitespaces)
    beginFeedbackOperation("Rename remote")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.remoteRename(old: old, new: newName)
            await MainActor.run { self.feedbackCenter.success("Remote renamed", detail: "\(old) → \(newName)") }
            await MainActor.run { self.loadRemotes() }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error("Rename remote failed", detail: errorMessage(error), nextStep: "检查名称后重试。")
            }
        }
    }
}

func remoteAdd(_ fetchAfterAdd: Bool = true) {
    guard let repo, !remoteName.isEmpty, !remoteUrl.isEmpty else { return }
    let name = remoteName, url = remoteUrl
    let broker = credentialAuth.broker
    beginFeedbackOperation("Add remote")
    Task.detached(priority: .userInitiated) {
        do {
            if let checkFailure = try remoteURLCheckFailure(repo: repo, url: url, broker: broker) {
                await MainActor.run {
                    self.feedbackCenter.error(
                        "Remote URL check failed",
                        detail: "\(url): \(checkFailure)",
                        nextStep: "Check the URL and authentication, then retry."
                    )
                }
                return
            }
            try repo.remoteAdd(name: name, url: url)
            let rs = try repo.remoteList()
            await MainActor.run {
                self.remotes = rs; self.remoteName = ""; self.remoteUrl = ""
                self.feedbackCenter.success("Remote added", detail: name)
                if fetchAfterAdd {
                    self.doFetch(name)
                }
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Add remote failed",
                    detail: errorMessage(error),
                    nextStep: "Check the remote name and URL, then retry."
                )
            }
        }
    }
}

func remoteRemove(_ name: String) {
    guard let repo else { return }
    guard confirmRemoteRemoval(name) else { return }
    beginFeedbackOperation("Remove remote")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.remoteRemove(name: name)
            let rs = try repo.remoteList()
            await MainActor.run {
                self.remotes = rs
                self.feedbackCenter.success("Remote removed", detail: name)
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Remove remote failed",
                    detail: errorMessage(error),
                    nextStep: "Check the remote configuration, then retry."
                )
            }
        }
    }
}

private func confirmRemoteRemoval(_ name: String) -> Bool {
    let alert = NSAlert()
    alert.messageText = "Remove remote?"
    alert.informativeText = "This removes the remote configuration and its remote-tracking branches."
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Remove")
    alert.addButton(withTitle: "Cancel")
    return alert.runModal() == .alertFirstButtonReturn
}

/// IntelliJ's `Git.Fetch` action fetches every configured remote in every Git
/// root.  A named remote is still supported for remote configuration flows
/// that intentionally fetch only the remote just edited.
func doFetch(_ name: String? = nil) {
    guard let name else {
        doFetchAll()
        return
    }
    doFetchRemote(name)
}

private func doFetchRemote(_ remote: String) {
    guard !isArborFetchInProgress(
        isRunning: feedbackCenter.isRunning,
        operationName: feedbackCenter.operationName
    ) else { return }
    guard let repository = repo else { return }
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Fetch", cancelHandle: cancel)
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    Task.detached(priority: .userInitiated) {
        do {
            let fo = try repository.fetchWithOptionsAndAuthAndCancel(
                remote: remote,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel
            )
            let detail = fo.updated.isEmpty ? "无更新" : fo.updated.joined(separator: ", ")
            await MainActor.run {
                self.mergeFeedback = "fetch 完成：\(detail)"
                self.publishFetchCompletion(detail: detail)
                self.loadRepoData()
                self.synchronizeRemoteProtectedBranchPatterns()
            }
        } catch {
            await MainActor.run {
                let detail = friendlyRemoteError(error)
                self.mergeFeedback = detail
                self.feedbackCenter.error("Fetch failed", detail: detail, nextStep: "Check the remote and Git identity, then retry.")
                if self.isAuthenticationFailure(error) { self.showHostingAuthPrompt = true }
            }
        }
    }
}

func autoFetchRecoveryRequest(
    _ action: ArborVCSActionRequest.AutoFetchRecoveryAction,
    rootPaths: [String]? = nil
) -> ArborVCSActionRequest {
    ArborVCSActionRequest(
        kind: .autoFetchRecovery,
        projectPath: projectPath,
        rootPath: repo?.workdir(),
        shelfName: "",
        autoFetchRecoveryAction: action,
        autoFetchRootPaths: rootPaths ?? autoFetchRootPaths
    )
}

func autoFetchRecoveryFeedbackAction(
    _ action: ArborVCSActionRequest.AutoFetchRecoveryAction,
    rootPaths: [String]? = nil
) -> FeedbackAction {
    let request = autoFetchRecoveryRequest(action, rootPaths: rootPaths)
    let title: String = switch action {
    case .fetchAll: "Fetch All"
    case .retryCheck: incomingCheckStrategy == .fetch ? "Retry Fetch All" : "Retry Check"
    case .enable: "Enable Auto-fetch"
    case .doNotAskAgain: "Do Not Ask Again"
    }
    return FeedbackAction(title: title, semanticAction: request) {
        self.handleVCSActionRequest(request)
    }
}

/// IntelliJ 的 Fetch All：每个 remote 独立执行，保留部分成功结果。
func doFetchAll(rootPaths: [String]? = nil) {
    guard !isArborFetchInProgress(
        isRunning: feedbackCenter.isRunning,
        operationName: feedbackCenter.operationName
    ) else { return }
    let paths = Array(Set(rootPaths ?? autoFetchRootPaths)).sorted()
    guard !paths.isEmpty else { return }
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Fetch all remotes", cancelHandle: cancel)
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    Task.detached(priority: .userInitiated) {
        var updated: [String] = []
        var failures: [String] = []
        var successfulRemoteCount = 0
        for rootPath in paths {
            guard !cancel.isCancelled() else { break }
            do {
                let rootRepo = try openRepository(path: rootPath)
                let rootRemotes = try rootRepo.remoteList()
                for remote in rootRemotes {
                    guard !cancel.isCancelled() else { break }
                    do {
                        let outcome = try rootRepo.fetchWithOptionsAndAuthAndCancel(
                            remote: remote.name,
                            tagMode: tagMode,
                            broker: broker,
                            cancel: cancel
                        )
                        successfulRemoteCount += 1
                        updated.append(contentsOf: outcome.updated.map {
                            "\(rootPath) · \(remote.name)/\($0)"
                        })
                    } catch {
                        failures.append("\(rootPath) · \(remote.name): \(friendlyRemoteError(error))")
                    }
                }
            } catch {
                failures.append("\(rootPath): \(friendlyRemoteError(error))")
            }
        }
        let result = (
            updated: updated,
            failures: failures,
            successfulRemoteCount: successfulRemoteCount
        )
        await MainActor.run {
            self.loadRepoData()
            self.loadMultiRoots()
            self.autoFetchIncomingFingerprint = nil
            self.autoFetchFailureFingerprint = nil
            if result.successfulRemoteCount > 0 {
                self.synchronizeRemoteProtectedBranchPatternsForAllRoots()
            }
            if result.failures.isEmpty {
                self.publishFetchCompletion(
                    detail: result.updated.isEmpty ? "无更新" : result.updated.joined(separator: ", "),
                    title: "Fetch all completed"
                )
            } else {
                self.feedbackCenter.warning(
                    "Fetch all partially completed",
                    detail: result.failures.joined(separator: "\n"),
                    nextStep: "修正失败的 remote 或认证配置后重试。",
                    additionalActions: [
                        self.autoFetchRecoveryFeedbackAction(.fetchAll, rootPaths: paths)
                    ],
                    notificationID: "\(self.autoFetchNotificationIDPrefix).error"
                )
            }
        }
    }
}

func publishFetchCompletion(detail: String, title: String = "Fetch completed") {
    let suggestionCount = GitIncomingCheckStrategySettings.suggestionCount(for: projectPath)
    let suggestionDisabled = GitIncomingCheckStrategySettings.suggestionDisabled(for: projectPath)
    guard shouldSuggestAutoFetch(
        autoFetchEnabled: incomingCheckStrategy == .fetch,
        suggestionDisabled: suggestionDisabled,
        shownCount: suggestionCount
    ) else {
        feedbackCenter.success(
            title,
            detail: detail,
            notificationID: "\(autoFetchNotificationIDPrefix).result"
        )
        return
    }

    GitIncomingCheckStrategySettings.setSuggestionCount(
        suggestionCount + 1,
        for: projectPath
    )
    feedbackCenter.success(
        title,
        detail: detail,
        additionalActions: [
            autoFetchRecoveryFeedbackAction(.enable),
            autoFetchRecoveryFeedbackAction(.doNotAskAgain)
        ],
        notificationID: "\(autoFetchNotificationIDPrefix).result"
    )
}

/// 对所有已配置 remote 执行 prune，避免删除远程分支后 Branches Popup 保留旧引用。
func doFetchPrune() {
    guard !isArborFetchInProgress(
        isRunning: feedbackCenter.isRunning,
        operationName: feedbackCenter.operationName
    ) else { return }
    guard let repo, !remotes.isEmpty else { return }
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Prune remote branches", cancelHandle: cancel)
    let remoteNames = remotes.map(\.name)
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    Task.detached(priority: .userInitiated) {
        var failures: [String] = []
        for remote in remoteNames {
            guard !cancel.isCancelled() else { break }
            do {
                try repo.fetchPruneWithOptionsAndAuthAndCancel(
                    remote: remote,
                    tagMode: tagMode,
                    broker: broker,
                    cancel: cancel
                )
            } catch {
                failures.append("\(remote): \(friendlyRemoteError(error))")
            }
        }
        let result = failures
        await MainActor.run {
            self.loadRepoData()
            if result.isEmpty {
                self.feedbackCenter.success("Remote branches pruned")
            } else {
                self.feedbackCenter.warning(
                    "Prune partially completed",
                    detail: result.joined(separator: "\n"),
                    nextStep: "检查失败的 remote 后重试。"
                )
            }
        }
    }
}

/// 将浅克隆补全为完整历史；执行前要求用户确认，因为该操作不可逆地扩大本地仓库。
func doFetchUnshallow() {
    guard !isArborFetchInProgress(
        isRunning: feedbackCenter.isRunning,
        operationName: feedbackCenter.operationName
    ) else { return }
    guard let repo, isShallowRepository else { return }
    let preferredRemote: String? = currentSyncStatus.flatMap { status -> String? in
        let candidate = status.upstream.split(separator: "/", maxSplits: 1).first.map(String.init)
        guard let candidate, remotes.contains(where: { $0.name == candidate }) else { return nil }
        return candidate
    }
    let remote = defaultFetchRemoteName(
        preferredRemote: preferredRemote,
        availableRemoteNames: remotes.map(\.name)
    )
    guard let remote else {
        feedbackCenter.warning(
            "Fetch full history unavailable",
            detail: remotes.count > 1
                ? "No tracked remote or origin is available; choose a remote configuration before retrying."
                : "No usable remote is configured for this Git root."
        )
        return
    }
    let alert = NSAlert()
    alert.messageText = "Fetch complete history?"
    alert.informativeText = "这会把当前浅克隆补全为完整历史，并增加本地磁盘占用。"
    alert.alertStyle = .warning
    alert.addButton(withTitle: "Fetch Full History")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Fetch full history", cancelHandle: cancel)
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    Task.detached(priority: .userInitiated) {
        do {
            try repo.fetchUnshallowWithOptionsAndAuthAndCancel(
                remote: remote,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel
            )
            await MainActor.run {
                self.loadRepoData()
                self.feedbackCenter.success("Full history fetched", detail: remote)
            }
        } catch {
            await MainActor.run {
                let detail = friendlyRemoteError(error)
                self.feedbackCenter.error("Fetch full history failed", detail: detail, nextStep: "确认该 remote 支持 unshallow 后重试。")
            }
        }
    }
}

func presentPullDialog(rebase: Bool?) {
    guard let projectPath,
          isArborVCSActionEnabled(
        rebase == true ? .pullRebase : .pullMerge,
        in: vcsActionContext
    ) else {
        return
    }
    let defaultRebase = pullDialogDefaultRebase(
        explicit: rebase,
        savedOptions: GitPullDialogSettingsStore.load(for: projectPath).options
    )
    pullDialogGeneration &+= 1
    let generation = pullDialogGeneration
    pullDialogRebase = defaultRebase
    pullDialogSnapshots = []
    showPullDialog = false
    Task.detached(priority: .userInitiated) {
        do {
            let snapshots = try listMultiRootBranches(scanRoot: projectPath)
            await MainActor.run {
                guard self.pullDialogGeneration == generation else { return }
                guard !snapshots.isEmpty else {
                    self.feedbackCenter.warning(
                        "Pull unavailable",
                        detail: "No Git root was discovered for this project.",
                        nextStep: "Refresh the project and retry Pull."
                    )
                    return
                }
                self.pullDialogSnapshots = snapshots
                self.showPullDialog = true
            }
        } catch {
            await MainActor.run {
                guard self.pullDialogGeneration == generation else { return }
                self.feedbackCenter.error(
                    "Pull dialog unavailable",
                    detail: errorMessage(error),
                    nextStep: "Refresh the project and retry Pull."
                )
            }
        }
    }
}

func savePullDialogSettings(_ options: PullDialogOptions) {
    var selected = GitPullDialogSettingsStore.load(for: projectPath).options
    selected.removeAll()
    if options.rebase { selected.insert(.rebase) }
    switch options.mode {
    case .fastForwardOnly: selected.insert(.ffOnly)
    case .noFastForward: selected.insert(.noFF)
    case .squash: selected.insert(.squash)
    case .fastForward: break
    }
    if options.noCommit { selected.insert(.noCommit) }
    if options.noVerify { selected.insert(.noVerify) }
    GitPullDialogSettingsStore.save(
        GitPullDialogSettings(options: selected),
        for: projectPath
    )
}

func refreshPullDialogSnapshots() {
    guard let projectPath else { return }
    let generation = pullDialogGeneration
    Task.detached(priority: .utility) {
        guard let snapshots = try? listMultiRootBranches(scanRoot: projectPath) else { return }
        await MainActor.run {
            guard self.pullDialogGeneration == generation, self.showPullDialog else { return }
            self.pullDialogSnapshots = snapshots
        }
    }
}

func fetchPullDialogRemote(rootPath: String, remote: String) {
    let normalizedRootPath = rootPath.trimmingCharacters(in: .whitespacesAndNewlines)
    let normalizedRemote = remote.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedRootPath.isEmpty, !normalizedRemote.isEmpty else { return }
    guard !isArborFetchInProgress(
        isRunning: feedbackCenter.isRunning,
        operationName: feedbackCenter.operationName
    ) else { return }
    let cancel = GitCancelHandle()
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    beginFeedbackOperation("Fetch for Pull", cancelHandle: cancel)
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: normalizedRootPath)
            let outcome = try rootRepo.fetchWithOptionsAndAuthAndCancel(
                remote: normalizedRemote,
                tagMode: tagMode,
                broker: broker,
                cancel: cancel
            )
            await MainActor.run {
                self.refreshPullDialogSnapshots()
                self.loadRepoData()
                self.feedbackCenter.success(
                    "Fetch for Pull completed",
                    detail: outcome.updated.isEmpty ? "No updates from \(normalizedRemote)." : outcome.updated.joined(separator: ", ")
                )
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Fetch for Pull failed",
                    detail: friendlyRemoteError(error),
                    nextStep: "Check the selected remote and credentials, then retry."
                )
            }
        }
    }
}

func executePullDialogSelection(_ selection: PullDialogSelection) {
    let options = PullOptions(
        rebase: selection.options.rebase,
        mode: selection.options.mode,
        noCommit: selection.options.noCommit,
        noVerify: selection.options.noVerify
    )
    let selectedRootPath = canonicalExternalLogPath(selection.rootPath)
    let currentRootPath = repo?.workdir().map(canonicalExternalLogPath)
    guard !selection.remoteBranch.isEmpty,
          !multiRootRunning,
          operationState == nil,
          !feedbackCenter.isRunning,
          !multiRoots.contains(where: { root in
              canonicalExternalLogPath(root.path) == selectedRootPath && root.operation != nil
          }),
          isArborVCSActionEnabled(
              selection.options.rebase ? .pullRebase : .pullMerge,
              in: vcsActionContext
          ) else {
        return
    }

    if selectedRootPath != currentRootPath {
        // The root-qualified path is intentionally explicit. The existing
        // multi-root operation reports conflicts against that root instead of
        // silently redirecting the Pull to the window's primary repository.
        pullRemoteBranchInRoot(
            rootPath: selection.rootPath,
            remoteBranch: selection.remoteBranch,
            rebase: selection.options.rebase,
            options: options
        )
        return
    }

    guard let currentRepo = repo else { return }
    let dirty = (try? currentRepo.status())?.contains { entry in
        entry.staged != .unchanged
            || (entry.unstaged != .unchanged && entry.unstaged != .ignored)
    } == true
    if dirty {
        stashAndPull(
            remote: selection.remote,
            remoteBranch: selection.remoteBranch,
            rebase: selection.options.rebase,
            pullOptions: options,
            onComplete: nil
        )
    } else {
        runPull(
            remote: selection.remote,
            remoteBranch: selection.remoteBranch,
            rebase: selection.options.rebase,
            pullOptions: options,
            restoreStash: false,
            onComplete: nil
        )
    }
}

func doPull(
    _ name: String? = nil,
    rebase: Bool = false,
    autoOpenUpdateInfo: Bool = false,
    onComplete: (() -> Void)? = nil
) {
    guard repo != nil, !remotes.isEmpty else { return }
    if hasTrackedChanges || hasUntrackedOrIgnoredFiles {
        // Match Rebased: preserve the complete local workspace automatically.
        // This includes untracked/ignored files so users never need to Add or
        // Commit local-only files just to update from the remote.
        stashAndPull(
            remote: name,
            remoteBranch: nil,
            rebase: rebase,
            autoOpenUpdateInfo: autoOpenUpdateInfo,
            onComplete: onComplete
        )
        return
    }
    runPull(
        remote: name,
        remoteBranch: nil,
        rebase: rebase,
        restoreStash: false,
        autoOpenUpdateInfo: autoOpenUpdateInfo,
        onComplete: onComplete
    )
}

func pullRemoteBranch(_ branch: RemoteBranchInfo, rebase: Bool) {
    guard repo != nil, !remotes.isEmpty else { return }
    if hasTrackedChanges || hasUntrackedOrIgnoredFiles {
        stashAndPull(
            remote: nil,
            remoteBranch: branch.name,
            rebase: rebase,
            onComplete: nil
        )
        return
    }
    runPull(
        remote: nil,
        remoteBranch: branch.name,
        rebase: rebase,
        restoreStash: false,
        onComplete: nil
    )
}

/// Resolve the exact stash created by the current preserving process. The
/// stash stack is user-visible and may change while Pull is running, so
/// `stash@{0}` is not a stable identity for an automatic restore.
nonisolated private static func pullStashReference(
    repo: Repository,
    stashID: String? = nil,
    message: String?
) throws -> (index: UInt32, stash: StashInfo) {
    let stashes = try repo.stashList()
    if let stashID {
        guard let index = stashes.firstIndex(where: { $0.id == stashID }) else {
            throw NSError(
                domain: "Arbor.Git",
                code: 4,
                userInfo: [NSLocalizedDescriptionKey: "找不到本次 Pull 保存的临时 stash；现有 stash 已保留。"]
            )
        }
        return (UInt32(index), stashes[index])
    }
    guard let message else {
        throw NSError(
            domain: "Arbor.Git",
            code: 3,
            userInfo: [NSLocalizedDescriptionKey: "无法确认 Pull 保存的临时 stash；现有 stash 已保留。"]
        )
    }
    guard let index = pullStashIndex(message: message, in: stashes) else {
        throw NSError(
            domain: "Arbor.Git",
            code: 2,
            userInfo: [NSLocalizedDescriptionKey: "找不到本次 Pull 保存的临时 stash：\(message)"]
        )
    }
    return (UInt32(index), stashes[index])
}

/// Save all dirty paths using IntelliJ's configured local-changes policy.
/// Returning the exact Shelf name or stash ID prevents a later user-created
/// artifact from being mistaken for the operation's temporary preservation.
nonisolated private static func saveLocalChangesBeforePull(
    repo: Repository,
    policy: LocalChangesSavePolicy,
    purpose: String = "pull"
) throws -> PullLocalChangesPreservation {
    let paths = try repo.status()
        .filter { $0.staged != .unchanged || $0.unstaged != .unchanged }
        .map(\.path)
    guard !paths.isEmpty else {
        return PullLocalChangesPreservation(shelfName: nil, stashMessage: nil)
    }

    switch policy {
    case .stash:
        let message = "Arbor: \(purpose) \(UUID().uuidString)"
        let stashID = try repo.stashSaveIncludingUntracked(message: message)
        return PullLocalChangesPreservation(
            shelfName: nil,
            stashMessage: message,
            stashID: stashID
        )
    case .shelve:
        let name = "Arbor: \(purpose) \(UUID().uuidString)"
        try repo.shelveForPreservation(name: name, paths: paths)
        return PullLocalChangesPreservation(shelfName: name, stashMessage: nil)
    }
}

nonisolated private static func restoreLocalChangesAfterPull(
    repo: Repository,
    preservation: PullLocalChangesPreservation
) throws {
    if let shelfName = preservation.shelfName {
        try repo.shelvePopPreservation(name: shelfName)
    } else if preservation.stashID != nil || preservation.stashMessage != nil {
        let reference = try pullStashReference(
            repo: repo,
            stashID: preservation.stashID,
            message: preservation.stashMessage
        )
        try repo.stashPopWithIndex(
            index: try currentStashIndex(repo: repo, stashID: reference.stash.id),
            restoreIndex: true
        )
    }
}

/// dirty-tree pull 的 UI 编排：按保存策略保存本地现场，pull 成功后恢复；
/// pull 进入冲突暂停时保留 stash 或 Shelf，避免把用户变更混进冲突索引。
func stashAndPull(
    remote: String?,
    remoteBranch: String?,
    rebase: Bool,
    pullOptions: PullOptions? = nil,
    autoOpenUpdateInfo: Bool = false,
    onComplete: (() -> Void)? = nil
) {
    guard let repo else { return }
    beginFeedbackOperation(rebase ? "Preserve and pull with rebase" : "Preserve and pull")
    let savePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    Task.detached(priority: .userInitiated) {
        do {
            let preservation = try Self.saveLocalChangesBeforePull(
                repo: repo,
                policy: savePolicy
            )
            let savedStash = preservation.stashID != nil || preservation.stashMessage != nil
            if let repositoryPath = repo.workdir() {
                savePendingPullPreservation(
                    repositoryPath: repositoryPath,
                    preservation: preservation
                )
            }
            await MainActor.run {
                self.pendingPullShelfName = preservation.shelfName
                self.pendingPullStashPop = savedStash
                self.pendingPullStashID = preservation.stashID
                self.pendingPullStashMessage = preservation.stashMessage
                self.runPull(
                    remote: remote,
                    remoteBranch: remoteBranch,
                        rebase: rebase,
                        pullOptions: pullOptions,
                        restoreStash: savedStash,
                        restoreStashID: preservation.stashID,
                        restoreStashMessage: preservation.stashMessage,
                        restoreShelf: preservation.shelfName,
                        autoOpenUpdateInfo: autoOpenUpdateInfo,
                        onComplete: onComplete
                )
            }
        } catch {
            await MainActor.run {
                let detail = errorMessage(error)
                if case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                    self.pendingPullShelfName = nil
                    self.presentShelveConflict(name: name, paths: paths, isPop: true)
                }
                self.mergeFeedback = detail
                self.feedbackCenter.error("Pull failed before preserving local changes", detail: detail, nextStep: "Check the local worktree and retry.")
            }
        }
    }
}

func runPull(
    remote: String?,
    remoteBranch: String?,
    rebase: Bool,
    pullOptions: PullOptions? = nil,
    restoreStash: Bool,
    restoreStashID: String? = nil,
    restoreStashMessage: String? = nil,
    restoreShelf: String? = nil,
    autoOpenUpdateInfo: Bool = false,
    onComplete: (() -> Void)? = nil
) {
    guard let repo else { return }
    let effectivePullOptions = pullOptions ?? PullOptions(
        rebase: rebase,
        mode: .fastForward,
        noCommit: false,
        noVerify: false
    )
    let pullRebaseSeed: RebaseUndoSeed? = {
        guard rebase else { return nil }
        if (try? repo.operationState()) != nil {
            return rebaseUndoSeed
        }
        guard let branch = (try? repo.branchList())?.first(where: { $0.isCurrent })?.name else {
            return nil
        }
        let configuredUpstream: String? = remote == nil
            ? (try? repo.syncStatus())?.first {
                $0.branch == branch
                    && !$0.upstream.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            }?.upstream
            : nil
        return makeRebaseUndoSeed(
            repo: repo,
            branch: branch,
            onto: remoteBranch ?? configuredUpstream
        )
    }()
    if rebase {
        rebaseUndoTarget = nil
        rebaseUndoSeed = pullRebaseSeed
        if let pullRebaseSeed {
            saveRebaseUndoSeed(pullRebaseSeed)
        }
    }
    let cancel = GitCancelHandle()
    beginFeedbackOperation(rebase ? "Pull with rebase" : "Pull", cancelHandle: cancel)
    let repositoryPath = repo.workdir()
    let initialHead = repo.headCommitId()
    let persistedPreservation = repositoryPath.flatMap {
        loadPendingPullPreservation(repositoryPath: $0)
    }
    let stashIDToRestore = restoreStashID ?? persistedPreservation?.stashID
    let stashMessageToRestore = restoreStashMessage ?? persistedPreservation?.stashMessage
    let stashWillBePopped = restoreStash || stashIDToRestore != nil || stashMessageToRestore != nil
    let shelfToRestore = restoreShelf ?? persistedPreservation?.shelfName
    let broker = credentialAuth.broker
    let tagMode = fetchTagsMode
    Task.detached(priority: .userInitiated) {
        do {
            let mo: MergeOutcome
            if let remoteBranch {
                mo = try repo.pullRemoteBranchWithSettingsAndAuthAndCancel(
                    remoteBranch: remoteBranch,
                    options: effectivePullOptions,
                    tagMode: tagMode,
                    broker: broker,
                    cancel: cancel
                )
            } else {
                mo = try repo.pullWithSettingsAndAuthAndCancel(
                    remote: remote,
                    options: effectivePullOptions,
                    tagMode: tagMode,
                    broker: broker,
                    cancel: cancel
                )
            }
            let completedUpdateRange: PersistedLogRevisionRange? = {
                guard mo.conflicts.isEmpty,
                      let initialHead,
                      let finalHead = repo.headCommitId(),
                      let repositoryPath,
                      !initialHead.isEmpty,
                      !finalHead.isEmpty,
                      initialHead != finalHead else {
                    return nil
                }
                return PersistedLogRevisionRange(
                    rootPath: repositoryPath,
                    oldRevision: initialHead,
                    newRevision: finalHead
                )
            }()
            let completedRebaseUndoTarget: RebaseUndoTarget? = {
                guard rebase, mo.conflicts.isEmpty, let pullRebaseSeed else { return nil }
                return rebaseUndoTargetAfterCompletion(
                    seed: pullRebaseSeed,
                    currentBranch: (try? repo.branchList())?.first(where: { $0.isCurrent })?.name,
                    finalHead: try? repo.revisionCommitId(revision: pullRebaseSeed.branch)
                )
            }()
            var stashPopError: String?
            var stashPopConflicts: [String]?
            var stashPopID: String? = stashIDToRestore
            var stashPopIndex: Int?
            var stashPopConflictID: String?
            var stashPopCancelled = false
            var shelfPopError: String?
            var shelfPopConflictName: String?
            var shelfPopConflicts: [String]?
            var shelfPopCancelled = false
            if mo.conflicts.isEmpty, let shelfToRestore {
                do {
                    try repo.shelvePopWithCancel(name: shelfToRestore, cancel: cancel)
                    await MainActor.run { self.pendingPullShelfName = nil }
                } catch {
                    if case .Cancelled = error as? EngineError {
                        shelfPopCancelled = true
                    } else if case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                        shelfPopConflictName = name
                        shelfPopConflicts = paths
                    } else {
                        shelfPopError = String(describing: error)
                    }
                }
            } else if mo.conflicts.isEmpty, stashWillBePopped {
                do {
                    let reference = try Self.pullStashReference(
                        repo: repo,
                        stashID: stashIDToRestore,
                        message: stashMessageToRestore
                    )
                    stashPopID = reference.stash.id
                    stashPopIndex = Int(reference.index)
                    try repo.stashPopWithIndexAndCancel(
                        index: try currentStashIndex(repo: repo, stashID: reference.stash.id),
                        restoreIndex: true,
                        cancel: cancel
                    )
                    await MainActor.run {
                        self.pendingPullStashPop = false
                        self.pendingPullStashID = nil
                        self.pendingPullStashMessage = nil
                    }
                } catch {
                    if case .Cancelled = error as? EngineError {
                        stashPopCancelled = true
                    } else if case let .StashApplyConflict(paths, conflictID) = error as? EngineError {
                        stashPopConflicts = paths
                        stashPopConflictID = conflictID ?? stashPopID
                    } else {
                        stashPopError = String(describing: error)
                    }
                }
            }
            let st = try repo.status()
            let stashPopErrorMessage = stashPopError
            let stashPopConflictPaths = stashPopConflicts
            let stashPopIDValue = stashPopID
            let stashPopIndexValue = stashPopIndex
            let stashPopConflictIDValue = stashPopConflictID
            let shelfPopConflictNameValue = shelfPopConflictName
            let shelfPopConflictsValue = shelfPopConflicts
            let shelfPopErrorMessage = shelfPopError
            let shelfPopCancelledValue = shelfPopCancelled
            let stashPopCancelledValue = stashPopCancelled
            await MainActor.run {
                let savedChangesAction: FeedbackAction? = {
                    if shelfToRestore != nil,
                       shelfPopCancelledValue
                        || shelfPopConflictNameValue != nil
                        || shelfPopConflictsValue != nil
                        || shelfPopErrorMessage != nil
                    {
                        return self.savedChangesFeedbackAction(
                            kind: .shelf,
                            identifier: shelfPopConflictNameValue ?? shelfToRestore!
                        )
                    }
                    if let stashPopIDValue,
                       stashPopCancelledValue
                        || stashPopConflictPaths != nil
                        || stashPopErrorMessage != nil
                    {
                        return self.savedChangesFeedbackAction(
                            kind: .stash,
                            identifier: stashPopIDValue
                        )
                    }
                    return nil
                }()
                let savedChangesActions = savedChangesAction.map { [$0] } ?? []
                let viewCommitsActions = completedUpdateRange
                    .flatMap { range in
                        self.forcePushedViewCommitsAction(
                            ranges: [range],
                            rootPath: range.rootPath
                        )
                    }
                    .map { [$0] } ?? []
                self.entries = st
                self.toolWindowMode = .commit
                self.toolWindowExpanded = true
                self.rebasePaused = !mo.conflicts.isEmpty && rebase
                self.rebasePauseReason = rebase && !mo.conflicts.isEmpty ? .conflict : nil
                self.rebaseConflicts = rebase ? mo.conflicts : []
                let localRestoreCompleted = stashPopConflictPaths == nil
                    && shelfPopConflictsValue == nil
                    && stashPopErrorMessage == nil
                    && !stashPopCancelledValue
                    && shelfPopErrorMessage == nil
                    && !shelfPopCancelledValue
                if rebase, !mo.conflicts.isEmpty {
                    self.rebaseUndoSeed = pullRebaseSeed
                    if let pullRebaseSeed {
                        saveRebaseUndoSeed(pullRebaseSeed)
                    }
                } else if rebase, localRestoreCompleted {
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = completedRebaseUndoTarget
                    if let pullRebaseSeed {
                        clearRebaseUndoSeed(repositoryPath: pullRebaseSeed.repositoryPath)
                    }
                } else if rebase {
                    self.rebaseUndoSeed = pullRebaseSeed
                    self.rebaseUndoTarget = nil
                    if let pullRebaseSeed {
                        saveRebaseUndoSeed(pullRebaseSeed)
                    }
                }
                if mo.conflicts.isEmpty,
                   localRestoreCompleted,
                   (shelfToRestore != nil || stashWillBePopped),
                   let repositoryPath
                {
                    clearPendingPullPreservation(repositoryPath: repositoryPath)
                }
                if localRestoreCompleted, let repositoryPath, let stashPopIDValue {
                    self.clearStashDiffIfMatching(rootPath: repositoryPath, stashID: stashPopIDValue)
                }
                self.stashPopConflictInProgress = stashPopConflictPaths != nil
                self.stashApplyConflictInProgress = false
                self.pendingStashPopIndex = stashPopConflictPaths != nil ? 0 : nil
                self.pendingStashPopID = stashPopConflictIDValue
                if stashPopConflictPaths != nil {
                    self.pendingStashPopIndex = stashPopIndexValue
                    self.pendingPullStashPop = false
                    self.pendingPullStashID = nil
                    self.pendingPullStashMessage = nil
                }
                if shelfPopConflictNameValue != nil { self.pendingPullShelfName = nil }
                if let shelfPopConflictNameValue, let shelfPopConflictsValue {
                    self.presentShelveConflict(
                        name: shelfPopConflictNameValue,
                        paths: shelfPopConflictsValue,
                        isPop: true
                    )
                }
                self.mergeInProgress = (!rebase && mo.requiresFinish)
                    || stashPopConflictPaths != nil
                    || shelfPopConflictsValue != nil
                self.selection = shelfPopConflictsValue?.first
                    ?? stashPopConflictPaths?.first
                    ?? mo.conflicts.first
                self.showMergeRevisionsDialog = !mo.conflicts.isEmpty
                    || stashPopConflictPaths != nil
                    || shelfPopConflictsValue != nil
                if let stashPopConflictPaths {
                    self.mergeFeedback = "pull 完成，但恢复本地变更时发生冲突：\(stashPopConflictPaths.joined(separator: ", "))"
                } else if let shelfPopConflictsValue {
                    self.mergeFeedback = "pull 完成，但恢复 Shelf 本地变更时发生冲突：\(shelfPopConflictsValue.joined(separator: ", "))"
                } else if !mo.conflicts.isEmpty {
                    self.mergeFeedback = "pull\(rebase ? " --rebase" : "") 冲突 \(mo.conflicts.count) 个文件"
                } else if let stashPopErrorMessage {
                    self.mergeFeedback = "pull 完成，但自动 stash pop 产生冲突：\(stashPopErrorMessage)"
                } else if let shelfPopErrorMessage {
                    self.mergeFeedback = "pull 完成，但自动 Shelf 恢复失败：\(shelfPopErrorMessage)"
                } else if stashPopCancelledValue {
                    self.mergeFeedback = "pull 完成，但恢复 Stash 本地变更已取消，Stash 已保留"
                } else if shelfPopCancelledValue {
                    self.mergeFeedback = "pull 完成，但恢复 Shelf 本地变更已取消，Shelf 已保留"
                } else if mo.updatedCommits > 0, !mo.upstream.isEmpty, !mo.branch.isEmpty {
                    self.mergeFeedback = "已更新 \(mo.upstream) → \(mo.branch)（+\(mo.updatedCommits) commits）"
                } else if stashWillBePopped || shelfToRestore != nil {
                    self.mergeFeedback = "pull 完成，已恢复本地变更"
                } else {
                    self.mergeFeedback = "pull 完成（已是最新）"
                }
                let detail = self.mergeFeedback ?? "pull 完成"
                let rebaseRecoveryAction = rebase && !mo.conflicts.isEmpty
                    ? pullRebaseSeed.map {
                        self.persistedRebaseRecoveryAction(
                            rootPath: $0.repositoryPath,
                            branch: $0.branch
                        )
                    }
                    : nil
                let recoveryActions = savedChangesActions + (rebaseRecoveryAction.map { [$0] } ?? [])
                if !mo.conflicts.isEmpty || stashPopConflictPaths != nil || shelfPopConflictsValue != nil {
                    self.feedbackCenter.warning(
                        "Pull paused for conflicts",
                        detail: detail,
                        nextStep: (stashPopConflictPaths != nil || shelfPopConflictsValue != nil)
                            ? "Open Merge Revisions, resolve the restored local changes, then complete the restore."
                            : "Open Merge Revisions, resolve the files, then finish the merge.",
                        additionalActions: recoveryActions,
                        notificationID: rebaseRecoveryAction.map { _ in
                            rebaseRecoveryNotificationID(repositoryPath: pullRebaseSeed?.repositoryPath ?? "")
                        }
                    )
                } else {
                    if let notificationID = self.multiRootUpdateErrorNotificationID() {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    if savedChangesActions.isEmpty {
                        if let notificationID = self.multiRootUpdateNotificationID(partial: true) {
                            self.feedbackCenter.expire(notificationID: notificationID)
                        }
                    } else if let notificationID = self.multiRootUpdateNotificationID(partial: false) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    if let completedRebaseUndoTarget {
                        self.feedbackCenter.success(
                            "Pull completed",
                            detail: detail,
                            additionalActions: [self.rebaseUndoFeedbackAction(for: completedRebaseUndoTarget)]
                                + savedChangesActions + viewCommitsActions,
                            notificationID: self.multiRootUpdateNotificationID(partial: false),
                            notificationGroup: .standard
                        )
                } else if stashPopCancelledValue || shelfPopCancelledValue {
                    self.feedbackCenter.warning(
                        "Local changes restore cancelled",
                        detail: detail,
                        nextStep: stashPopCancelledValue
                            ? "The preservation Stash was kept. Retry restoring it when ready."
                            : "The preservation Shelf was kept. Retry restoring it when ready.",
                        additionalActions: savedChangesActions + viewCommitsActions,
                        notificationID: self.multiRootUpdateNotificationID(partial: true),
                        notificationGroup: .standard
                    )
                } else if savedChangesActions.isEmpty {
                    self.feedbackCenter.success(
                        "Pull completed",
                        detail: detail,
                        additionalActions: viewCommitsActions,
                        notificationID: self.multiRootUpdateNotificationID(partial: false),
                        notificationGroup: .standard
                    )
                } else {
                    self.feedbackCenter.warning(
                        "Local changes were not restored",
                        detail: detail,
                        nextStep: "View the saved changes and restore them after fixing the conflict.",
                        additionalActions: savedChangesActions + viewCommitsActions,
                        notificationID: self.multiRootUpdateNotificationID(partial: true),
                        notificationGroup: .standard
                    )
                }
                }
                if autoOpenUpdateInfo,
                   mo.conflicts.isEmpty,
                   localRestoreCompleted,
                   let completedUpdateRange
                {
                    self.autoOpenUpdateInfoIfEnabled([completedUpdateRange])
                }
                if mo.conflicts.isEmpty,
                   stashPopConflictPaths == nil,
                   shelfPopConflictsValue == nil,
                   stashPopErrorMessage == nil,
                   shelfPopErrorMessage == nil,
                   !stashPopCancelledValue,
                   !shelfPopCancelledValue {
                    onComplete?()
                }
                self.refreshAll(showFeedback: false)
            }
        } catch {
            let failedOperationState = try? repo.operationState()
            let rebaseStillActive = rebase && failedOperationState?.kind == .rebase
            var restoreError: String?
            var stashRestoreID: String? = stashIDToRestore
            var stashRestoreIndex: Int?
            var stashRestoreConflictID: String?
            var stashRestoreConflictPaths: [String]?
            var shelfRestoreConflictName: String?
            var shelfRestoreConflictPaths: [String]?
            if !rebaseStillActive, let shelfToRestore {
                do {
                    try repo.shelvePopPreservation(name: shelfToRestore)
                    await MainActor.run { self.pendingPullShelfName = nil }
                } catch {
                    if case let .ShelveApplyConflict(name, paths) = error as? EngineError {
                        shelfRestoreConflictName = name
                        shelfRestoreConflictPaths = paths
                    } else {
                        restoreError = String(describing: error)
                    }
                }
            } else if !rebaseStillActive, stashWillBePopped {
                do {
                    let reference = try Self.pullStashReference(
                        repo: repo,
                        stashID: stashIDToRestore,
                        message: stashMessageToRestore
                    )
                    stashRestoreID = reference.stash.id
                    stashRestoreIndex = Int(reference.index)
                    try repo.stashPopWithIndex(
                        index: try currentStashIndex(repo: repo, stashID: reference.stash.id),
                        restoreIndex: true
                    )
                    await MainActor.run {
                        self.pendingPullStashPop = false
                        self.pendingPullStashID = nil
                        self.pendingPullStashMessage = nil
                    }
                } catch let error as EngineError {
                if case let .StashApplyConflict(paths, conflictStashID) = error {
                        stashRestoreConflictID = conflictStashID ?? stashRestoreID
                        stashRestoreConflictPaths = paths
                    } else {
                        restoreError = String(describing: error)
                    }
                } catch {
                    restoreError = String(describing: error)
                }
            }
            let restoreErrorMessage = restoreError
            let stashRestoreIDValue = stashRestoreID
            let stashRestoreIndexValue = stashRestoreIndex
            let stashRestoreConflictIDValue = stashRestoreConflictID
            let stashRestoreConflictPathsValue = stashRestoreConflictPaths
            let shelfRestoreConflictNameValue = shelfRestoreConflictName
            let shelfRestoreConflictPathsValue = shelfRestoreConflictPaths
            await MainActor.run {
                let savedChangesAction: FeedbackAction? = {
                    if let shelfRestoreConflictNameValue,
                       shelfRestoreConflictPathsValue != nil || restoreErrorMessage != nil
                    {
                        return self.savedChangesFeedbackAction(
                            kind: .shelf,
                            identifier: shelfRestoreConflictNameValue
                        )
                    }
                    if let stashRestoreIDValue,
                       stashRestoreConflictPathsValue != nil || restoreErrorMessage != nil
                    {
                        return self.savedChangesFeedbackAction(
                            kind: .stash,
                            identifier: stashRestoreIDValue
                        )
                    }
                    return nil
                }()
                let savedChangesActions = savedChangesAction.map { [$0] } ?? []
                let pullError = friendlyRemoteError(error)
                let localRestoreCompleted = restoreErrorMessage == nil
                    && shelfRestoreConflictPathsValue == nil
                    && stashRestoreConflictPathsValue == nil
                if !rebaseStillActive,
                   localRestoreCompleted,
                   (shelfToRestore != nil || stashWillBePopped),
                   let repositoryPath
                {
                    clearPendingPullPreservation(repositoryPath: repositoryPath)
                }
                if rebaseStillActive {
                    if let pullRebaseSeed {
                        self.rebaseUndoSeed = pullRebaseSeed
                        saveRebaseUndoSeed(pullRebaseSeed)
                    }
                    self.rebasePaused = true
                    self.rebasePauseReason = .conflict
                    self.rebaseConflicts = failedOperationState?.conflictedFiles ?? []
                    self.operationState = failedOperationState
                    self.showMergeRevisionsDialog = true
                } else if rebase {
                    self.rebasePaused = false
                    self.rebasePauseReason = nil
                    self.rebaseConflicts = []
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = nil
                    if let pullRebaseSeed {
                        clearRebaseUndoSeed(repositoryPath: pullRebaseSeed.repositoryPath)
                    }
                }
                let rebaseRecoveryAction = rebaseStillActive
                    ? pullRebaseSeed.map {
                        self.persistedRebaseRecoveryAction(rootPath: $0.repositoryPath, branch: $0.branch)
                    }
                    : nil
                if let shelfRestoreConflictNameValue, let shelfRestoreConflictPathsValue {
                    self.pendingPullShelfName = nil
                    self.presentShelveConflict(
                        name: shelfRestoreConflictNameValue,
                        paths: shelfRestoreConflictPathsValue,
                        isPop: true
                    )
                }
                if let stashRestoreConflictPathsValue {
                    self.showStashRestoreConflict(
                        stashRestoreConflictPathsValue,
                        operationName: "Pull",
                        stashID: stashRestoreConflictIDValue ?? stashRestoreIDValue
                    )
                    self.pendingStashPopIndex = stashRestoreIndexValue
                    self.pendingPullStashPop = false
                    self.pendingPullStashID = nil
                    self.pendingPullStashMessage = nil
                }
                let untrackedPaths: [String]? = {
                    guard case let .UntrackedWouldBeOverwritten(paths) = error as? EngineError else {
                        return nil
                    }
                    return paths
                }()
                if let shelfRestoreConflictPathsValue {
                    self.mergeFeedback = "pull 失败：\(pullError)；恢复 Shelf 本地变更时发生冲突：\(shelfRestoreConflictPathsValue.joined(separator: ", "))"
                } else if let stashRestoreConflictPathsValue {
                    self.mergeFeedback = "pull 失败：\(pullError)；恢复 stash 本地变更时发生冲突：\(stashRestoreConflictPathsValue.joined(separator: ", "))"
                } else if let restoreErrorMessage {
                    self.mergeFeedback = "pull 失败：\(pullError)；自动恢复本地变更失败：\(restoreErrorMessage)"
                } else if stashWillBePopped || shelfToRestore != nil {
                    self.mergeFeedback = "pull 失败，已恢复本地变更：\(pullError)"
                } else if let untrackedPaths {
                    self.mergeFeedback = "远程更新涉及本地未跟踪文件，正在临时保存后重试：\(untrackedPaths.joined(separator: ", "))"
                } else {
                    self.mergeFeedback = pullError
                }
                let detail = self.mergeFeedback ?? pullError
                let upstreamAction = self.chooseUpstreamFeedbackAction(for: error)
                let recoveryActions = savedChangesActions
                    + (rebaseRecoveryAction.map { [$0] } ?? [])
                    + (upstreamAction.map { [$0] } ?? [])
                if rebaseStillActive {
                    self.feedbackCenter.warning(
                        "Pull with Rebase paused",
                        detail: detail,
                        nextStep: "Resolve the files, then Continue or Abort the rebase. Pull's saved local changes will be restored after completion.",
                        additionalActions: recoveryActions,
                        notificationID: rebaseRecoveryAction.map { _ in
                            rebaseRecoveryNotificationID(repositoryPath: pullRebaseSeed?.repositoryPath ?? "")
                        }
                    )
                } else if let untrackedPaths, !stashWillBePopped, shelfToRestore == nil {
                    self.feedbackCenter.warning(
                        "Preserving local files",
                        detail: detail,
                        nextStep: "These local files will not be added or committed; Arbor is retrying pull after a temporary save."
                    )
                    self.temporarilySaveWorkspaceAndRetryPull(
                        paths: untrackedPaths,
                        remote: remote,
                        remoteBranch: remoteBranch,
                        rebase: rebase,
                        pullOptions: pullOptions,
                        autoOpenUpdateInfo: autoOpenUpdateInfo,
                        onComplete: onComplete
                    )
                } else {
                    let nextStep: String
                    if restoreErrorMessage != nil
                        || shelfRestoreConflictPathsValue != nil
                        || stashRestoreConflictPathsValue != nil
                    {
                        nextStep = "Resolve the local restore conflict in Merge Revisions, then complete the restore."
                    } else if stashWillBePopped || shelfToRestore != nil {
                        nextStep = "Your local changes were restored; fix the remote or upstream issue, then retry pull."
                    } else {
                        nextStep = "Check the branch upstream and remote, then retry pull."
                    }
                    if let notificationID = self.multiRootUpdateNotificationID(partial: false) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    if let notificationID = self.multiRootUpdateNotificationID(partial: true) {
                        self.feedbackCenter.expire(notificationID: notificationID)
                    }
                    self.feedbackCenter.error(
                        "Pull failed",
                        detail: detail,
                        nextStep: nextStep,
                        additionalActions: recoveryActions,
                        notificationID: self.multiRootUpdateErrorNotificationID()
                    )
                    if self.isAuthenticationFailure(error) { self.showHostingAuthPrompt = true }
                }
                if rebaseStillActive || stashWillBePopped || shelfToRestore != nil {
                    self.refreshAll(showFeedback: false)
                }
            }
        }
    }
}

/// 未跟踪文件和远程更新发生路径冲突时，不要求用户 Add 或 Commit。
/// 先把完整本地现场（tracked + untracked + ignored）按保存策略临时保存，
/// 再重试 pull；真正的同路径内容冲突才进入 Merge Revisions。
private func temporarilySaveWorkspaceAndRetryPull(
    paths: [String],
    remote: String?,
    remoteBranch: String?,
    rebase: Bool,
    pullOptions: PullOptions? = nil,
    autoOpenUpdateInfo: Bool = false,
    onComplete: (() -> Void)? = nil
) {
    guard let repo else { return }
    beginFeedbackOperation("Preserve local files and retry pull")
    let savePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    Task.detached(priority: .userInitiated) {
        do {
            let preservation = try Self.saveLocalChangesBeforePull(
                repo: repo,
                policy: savePolicy
            )
            let savedStash = preservation.stashID != nil || preservation.stashMessage != nil
            if let repositoryPath = repo.workdir() {
                savePendingPullPreservation(
                    repositoryPath: repositoryPath,
                    preservation: preservation
                )
            }
            await MainActor.run {
                self.pendingPullShelfName = preservation.shelfName
                self.pendingPullStashPop = savedStash
                self.pendingPullStashID = preservation.stashID
                self.pendingPullStashMessage = preservation.stashMessage
                self.mergeFeedback = "已临时保存本地文件，正在重试 pull：\(paths.joined(separator: ", "))"
                self.runPull(
                        remote: remote,
                        remoteBranch: remoteBranch,
                        rebase: rebase,
                        pullOptions: pullOptions,
                        restoreStash: savedStash,
                        restoreStashID: preservation.stashID,
                        restoreStashMessage: preservation.stashMessage,
                        restoreShelf: preservation.shelfName,
                        autoOpenUpdateInfo: autoOpenUpdateInfo,
                        onComplete: onComplete
                )
            }
        } catch {
            await MainActor.run {
                let detail = errorMessage(error)
                self.mergeFeedback = detail
                self.feedbackCenter.error("Preserve local files failed", detail: detail, nextStep: "Keep the files local and retry after checking the worktree.")
            }
        }
    }
}

func popPendingPullStash() {
    guard let repo, pendingPullStashPop || pendingPullShelfName != nil else { return }
    let repositoryPath = repo.workdir()
    let shelfName = pendingPullShelfName
    let stashID = pendingPullStashID
    let stashMessage = pendingPullStashMessage
    let pullRebaseSeed = rebaseUndoSeed
    let restoreCancel = GitCancelHandle()
    beginFeedbackOperation(
        shelfName == nil ? "Restore pull stash" : "Restore pull Shelf",
        cancelHandle: restoreCancel
    )
    Task.detached(priority: .userInitiated) {
        var stashRestoreID: String? = stashID
        do {
            if let shelfName {
                try repo.shelvePopWithCancel(name: shelfName, cancel: restoreCancel)
            } else if stashID != nil || stashMessage != nil {
                let reference = try Self.pullStashReference(
                    repo: repo,
                    stashID: stashID,
                    message: stashMessage
                )
                stashRestoreID = reference.stash.id
                try repo.stashPopWithIndexAndCancel(
                    index: try currentStashIndex(repo: repo, stashID: reference.stash.id),
                    restoreIndex: true,
                    cancel: restoreCancel
                )
            } else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 3,
                    userInfo: [NSLocalizedDescriptionKey: "无法确认 Pull 保存的临时 stash；现有 stash 已保留。"]
                )
            }
            let pullRebaseRestoreCompleted = pullRebaseSeed != nil
                && (try? repo.operationState()) == nil
            let completedPullRebaseUndoTarget = pullRebaseRestoreCompleted
                ? pullRebaseSeed.flatMap { seed in
                    rebaseUndoTargetAfterCompletion(
                        seed: seed,
                        currentBranch: (try? repo.branchList())?.first(where: { $0.isCurrent })?.name,
                        finalHead: try? repo.revisionCommitId(revision: seed.branch)
                    )
                }
                : nil
            await MainActor.run {
                self.pendingPullStashPop = false
                self.pendingPullStashID = nil
                self.pendingPullStashMessage = nil
                self.pendingPullShelfName = nil
                if let repositoryPath {
                    clearPendingPullPreservation(repositoryPath: repositoryPath)
                }
                if pullRebaseRestoreCompleted {
                    self.finishPendingPullRebaseRestore(
                        seed: pullRebaseSeed,
                        target: completedPullRebaseUndoTarget
                    )
                }
                self.mergeFeedback = "已恢复 pull 前的本地变更"
                if let completedPullRebaseUndoTarget {
                    self.feedbackCenter.success(
                        "Pull changes restored",
                        additionalActions: [self.rebaseUndoFeedbackAction(for: completedPullRebaseUndoTarget)],
                        notificationID: rebaseUndoNotificationID(
                            repositoryPath: completedPullRebaseUndoTarget.repositoryPath
                        ),
                        notificationGroup: .standard
                    )
                } else {
                    self.feedbackCenter.success("Pull changes restored")
                }
                self.refreshAll(showFeedback: false)
            }
        } catch let error as EngineError {
            let stashRestoreIDValue = stashRestoreID
            await MainActor.run {
                switch error {
                case .Cancelled:
                    let action: FeedbackAction? = {
                        if let shelfName {
                            return self.savedChangesFeedbackAction(kind: .shelf, identifier: shelfName)
                        }
                        if let stashRestoreIDValue {
                            return self.savedChangesFeedbackAction(kind: .stash, identifier: stashRestoreIDValue)
                        }
                        return nil
                    }()
                    let savedKind = shelfName == nil ? "Stash" : "Shelf"
                    self.mergeFeedback = "已取消恢复 pull 前的本地变更，保存的\(savedKind) 已保留"
                    self.feedbackCenter.warning(
                        "Restore pull changes cancelled",
                        detail: self.mergeFeedback ?? "保存的\(savedKind) 已保留",
                        nextStep: "Retry restoring the saved \(savedKind) when ready.",
                        additionalActions: action.map { [$0] } ?? []
                    )
                case let .StashApplyConflict(paths, conflictStashID):
                    self.showStashRestoreConflict(
                        paths,
                        operationName: "Pull",
                        stashID: conflictStashID ?? stashRestoreIDValue
                    )
                case let .ShelveApplyConflict(name, paths):
                    self.pendingPullShelfName = nil
                    self.presentShelveConflict(name: name, paths: paths, isPop: true)
                default:
                    let detail = errorMessage(error)
                    self.mergeFeedback = detail
                    self.feedbackCenter.error(
                        "Restore pull changes failed",
                        detail: detail,
                        nextStep: "Resolve the local conflict before retrying."
                    )
                }
            }
        } catch {
            await MainActor.run {
                let detail = errorMessage(error)
                self.mergeFeedback = detail
                self.feedbackCenter.error("Restore pull changes failed", detail: detail, nextStep: "Resolve the local conflict before retrying.")
            }
        }
    }
}

func doPush(
    _ name: String? = nil,
    branch requestedBranch: String? = nil,
    force requestedForce: Bool? = nil,
    forceWithLease requestedForceWithLease: Bool? = nil,
    setUpstream: Bool = false,
    refspec: String? = nil,
    tagMode: PushDialogTagMode? = nil,
    skipHooks: Bool = false,
    viewCommitRanges: [PersistedLogRevisionRange] = [],
    afterCommit: Bool = false
) {
    guard let repo else { return }
    guard let remote = resolveSelectedRemoteName(
        selectedRemote: name,
        availableRemoteNames: remotes.map(\.name)
    ) else {
        feedbackCenter.warning(
            "Choose a remote before pushing",
            detail: remotes.count > 1
                ? "Multiple remotes are configured for this Git root."
                : "No usable remote is configured for this Git root."
        )
        return
    }
    let branch = requestedBranch ?? branches.first { $0.isCurrent }?.name ?? "main"
    let force = requestedForce ?? pushForce
    let useForceWithLease = GitPushSettings.useForceWithLease(force: force, requested: requestedForceWithLease)
    let protectedTarget = refspec?
        .split(separator: ":", maxSplits: 1, omittingEmptySubsequences: true)
        .last
        .map { $0.replacingOccurrences(of: "refs/heads/", with: "") }
        ?? branch
    if force,
       GitProtectedBranchRules.matches(
           protectedTarget,
           patterns: effectiveProtectedBranchPatterns
       ) {
        feedbackCenter.error(
            "Force push blocked",
            detail: "\(protectedTarget) is protected by Git settings.",
            nextStep: "Edit Protected Branches in Settings or use a non-force push."
        )
        return
    }
    let cancel = GitCancelHandle()
    let notificationID = pushNotificationID(rootPath: repo.workdir() ?? "current")
    let rootPath = repo.workdir()
    beginFeedbackOperation("Push", cancelHandle: cancel, notificationID: notificationID)
    let currentBranchForPush = currentBranchName
    let publish = setUpstream
        || (branch == currentBranchForPush && currentSyncStatus?.trackingExists == false)
    let broker = credentialAuth.broker
    let engineTagMode = tagMode.map { mode in
        switch mode {
        case .all: PushTagMode.all
        case .currentBranch: PushTagMode.follow
        }
    }
    Task.detached(priority: .userInitiated) {
        let initialViewCommitRanges: [PersistedLogRevisionRange] = {
            guard viewCommitRanges.isEmpty,
                  refspec == nil,
                  branch == currentBranchForPush,
                  let rootPath = repo.workdir() else {
                return viewCommitRanges
            }
            return Self.multiRootPushRevisionRanges(for: [rootPath], remote: remote)
        }()
        do {
            if let refspec, !refspec.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                if engineTagMode != nil || skipHooks {
                    try repo.pushRefspecWithOptionsAndAuthAndCancel(
                        remote: remote,
                        refspec: refspec,
                        force: force,
                        forceWithLease: useForceWithLease,
                        tagMode: engineTagMode,
                        skipHooks: skipHooks,
                        broker: broker,
                        cancel: cancel
                    )
                } else {
                    try repo.pushRefspecWithAuthAndCancel(
                        remote: remote,
                        refspec: refspec,
                        force: force,
                        forceWithLease: useForceWithLease,
                        broker: broker,
                        cancel: cancel
                    )
                }
            } else {
                try repo.pushWithOptionsAndAuthAndCancel(
                    remote: remote,
                    branch: branch,
                    force: force,
                    forceWithLease: useForceWithLease,
                    setUpstream: publish,
                    tagMode: engineTagMode,
                    skipHooks: skipHooks,
                    broker: broker,
                    cancel: cancel
                )
            }
            await MainActor.run {
                self.mergeFeedback = "push 完成"
                self.feedbackCenter.success(
                    "Push completed",
                    detail: "\(remote)/\(branch)",
                    additionalActions: self.multiRootUpdateViewCommitsAction(
                        ranges: initialViewCommitRanges
                    ).map { [$0] } ?? [],
                    notificationID: notificationID
                )
                self.autoOpenUpdateInfoIfEnabled(initialViewCommitRanges)
                self.loadRepoData()
            }
        } catch {
            await MainActor.run {
                let detail = friendlyRemoteError(error)
                self.mergeFeedback = detail
                if let stale = stalePushRejectionDetails(error) {
                    if let rootPath {
                        let actions = self.directPushRetryActions(
                            rootPath: rootPath,
                            remote: stale.remote,
                            branch: stale.branch,
                            force: force,
                            forceWithLease: useForceWithLease,
                            setUpstream: publish,
                            refspec: refspec,
                            tagMode: tagMode,
                            skipHooks: skipHooks,
                            viewCommitRanges: initialViewCommitRanges,
                            includeForce: true
                        ) + (self.multiRootUpdateViewCommitsAction(
                            ranges: initialViewCommitRanges
                        ).map { [$0] } ?? []) + [
                            self.showOperationDetailsAction(notificationID: notificationID)
                        ]
                        self.feedbackCenter.warning(
                            afterCommit
                                ? "Commit completed; Push rejected by force-with-lease"
                                : "Push rejected by force-with-lease",
                            detail: "\(stale.remote)/\(stale.branch): \(stale.message)",
                            nextStep: "The remote branch changed after the lease was recorded. Verify the remote history before overwriting it.",
                            additionalActions: actions,
                            notificationID: notificationID,
                            notificationGroup: .important,
                            localized: false
                        )
                    } else {
                        self.feedbackCenter.warning(
                            afterCommit
                                ? "Commit completed; Push rejected by force-with-lease"
                                : "Push rejected by force-with-lease",
                            detail: "\(stale.remote)/\(stale.branch): \(stale.message)",
                            nextStep: "The remote branch changed after the lease was recorded. Verify the remote history before overwriting it.",
                            actionTitle: "Force Push Anyway",
                            action: {
                                self.doPush(
                                    stale.remote,
                                    branch: stale.branch,
                                    force: true,
                                    forceWithLease: false,
                                    setUpstream: publish,
                                    refspec: refspec,
                                    tagMode: tagMode,
                                    skipHooks: skipHooks,
                                    viewCommitRanges: initialViewCommitRanges
                                )
                            },
                            notificationID: notificationID,
                            localized: false
                        )
                    }
                } else {
                    let autoUpdate = gitPushAutoUpdateIsEligible(
                        enabled: GitPushAutoUpdateSettings.value(for: self.projectPath),
                        force: force,
                        refspec: refspec,
                        currentBranch: currentBranchForPush,
                        rejectedBranch: branch,
                        hasTracking: self.currentSyncStatus?.trackingExists == true
                    )
                    if autoUpdate, let rootPath {
                        self.updateRootForPushRecovery(
                            rootPath: rootPath,
                            remote: remote,
                            branch: branch,
                            force: force,
                            forceWithLease: useForceWithLease,
                            setUpstream: publish,
                            refspec: nil,
                            tagMode: tagMode,
                            skipHooks: skipHooks,
                            rebase: GitUpdateMethodSettings.method(for: self.projectPath) == .rebase,
                            viewCommitRanges: initialViewCommitRanges
                        )
                    } else {
                        let retryActions: [FeedbackAction] = rootPath.map { path in
                            self.directPushRetryActions(
                                rootPath: path,
                                remote: remote,
                                branch: branch,
                                force: force,
                                forceWithLease: useForceWithLease,
                                setUpstream: publish,
                                refspec: refspec,
                                tagMode: tagMode,
                                skipHooks: skipHooks,
                                viewCommitRanges: initialViewCommitRanges,
                                includeForce: false
                            )
                        } ?? []
                        let detailAction = self.showOperationDetailsAction(notificationID: notificationID)
                        self.feedbackCenter.error(
                            "Push failed",
                            detail: detail,
                            nextStep: "Check the remote, upstream, and credentials, then retry.",
                            additionalActions: retryActions + [detailAction],
                            notificationID: notificationID,
                            notificationGroup: .important
                        )
                        self.offerPushRecovery(
                            error,
                            remote: remote,
                            branch: branch,
                            force: force,
                            forceWithLease: useForceWithLease,
                            setUpstream: publish,
                            refspec: refspec,
                            tagMode: tagMode,
                            afterCommit: afterCommit,
                            viewCommitRanges: initialViewCommitRanges
                        )
                    }
                }
                if self.isAuthenticationFailure(error) { self.showHostingAuthPrompt = true }
            }
        }
    }
}

/// Rebased 的 rejected push 引导：只对 non-fast-forward 提供 Merge/Rebase，
/// 不把 force push 当成修复建议；Publish Branch 则由 Push 对话框的 upstream 开关完成。
func offerPushRecovery(
    _ error: Error,
    remote: String?,
    branch: String?,
    force: Bool,
    forceWithLease: Bool = false,
    setUpstream: Bool,
    refspec: String? = nil,
    tagMode: PushDialogTagMode? = nil,
    skipHooks: Bool = false,
    afterCommit: Bool = false,
    viewCommitRanges: [PersistedLogRevisionRange] = []
) {
    // A detached/custom source cannot be repaired by pulling the checked-out
    // branch and retrying it. The caller must rebuild that source against the
    // newly fetched remote tip instead of silently pushing the wrong ref.
    guard refspec == nil else { return }
    guard case let .PushRejected(kind, remote, branch, _) = error as? EngineError,
          kind == .nonFastForward else { return }
    // Match GitPushOperation.pushingToNotTrackedBranch and
    // pushingNotCurrentBranch: updating the checked-out branch is only a
    // valid repair when the rejected push came from that branch's tracked
    // upstream. A custom/non-current push must remain a plain rejection.
    guard currentBranchName == branch,
          currentSyncStatus?.trackingExists == true else { return }
    guard let rootPath = repo?.workdir() else { return }
    let recovery = PersistedPushRecovery(
        remote: remote,
        branch: branch,
        force: force,
        forceWithLease: forceWithLease,
        setUpstream: setUpstream,
        tagModeRaw: tagMode?.rawValue,
        skipHooks: skipHooks,
        rebase: false
    )
    let mergeRequest = singleRootPushRecoveryRequest(
        rootPath: rootPath,
        recovery: recovery,
        viewCommitRanges: viewCommitRanges
    )
    let rebaseRequest = singleRootPushRecoveryRequest(
        rootPath: rootPath,
        recovery: PersistedPushRecovery(
            remote: recovery.remote,
            branch: recovery.branch,
            force: recovery.force,
            forceWithLease: recovery.forceWithLease,
            setUpstream: recovery.setUpstream,
            tagModeRaw: recovery.tagModeRaw,
            skipHooks: recovery.skipHooks,
            rebase: true
        ),
        viewCommitRanges: viewCommitRanges
    )
    let notificationID = pushNotificationID(rootPath: rootPath)
    let recoveryActions = [
        FeedbackAction(title: "Update with Merge", semanticAction: mergeRequest) {
            self.handleVCSActionRequest(mergeRequest)
        },
        FeedbackAction(title: "Update with Rebase", semanticAction: rebaseRequest) {
            self.handleVCSActionRequest(rebaseRequest)
        }
    ] + self.directPushRetryActions(
        rootPath: rootPath,
        remote: remote,
        branch: branch,
        force: force,
        forceWithLease: forceWithLease,
        setUpstream: setUpstream,
        refspec: refspec,
        tagMode: tagMode,
        skipHooks: skipHooks,
        viewCommitRanges: viewCommitRanges,
        includeForce: false
    ) + (self.multiRootUpdateViewCommitsAction(ranges: viewCommitRanges).map { [$0] } ?? [])
        + [self.showOperationDetailsAction(notificationID: notificationID)]
    feedbackCenter.warning(
        afterCommit ? "Commit completed; Push rejected" : "Push rejected",
        detail: "Remote branch \(remote)/\(branch) has commits that are not local.",
        nextStep: "Update the checked-out branch, then retry Push.",
        additionalActions: recoveryActions,
        notificationID: notificationID,
        notificationGroup: .important
    )
}

func rebaseActionBinding(_ index: Int) -> Binding<RebaseAction> {
    Binding(
        get: { self.rebaseActions[index] },
        set: { self.rebaseActions[index] = $0 }
    )
}

func loadRebaseRange() {
    rebaseRangeGeneration += 1
    let generation = rebaseRangeGeneration
    guard let repo else {
        rebaseRange = []
        rebaseActions = []
        return
    }
    let onto = rebaseOnto.trimmingCharacters(in: .whitespacesAndNewlines)
    let branch = rebaseBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    let repositoryPath = rebaseRootPath.trimmingCharacters(in: .whitespacesAndNewlines)
    let root = rebaseRoot
    guard rebaseInputsCanLoadRange(onto: onto, branch: branch, root: root) else {
        rebaseRange = []
        rebaseActions = []
        return
    }
    let preserveMerges = rebasePreserveMerges
    let currentRepositoryPath = repo.workdir() ?? ""
    Task.detached(priority: .userInitiated) {
        do {
            let selectedRepo: Repository
            if repositoryPath.isEmpty || repositoryPath == currentRepositoryPath {
                selectedRepo = repo
            } else {
                selectedRepo = try openRepository(path: repositoryPath)
            }
            let range = try selectedRepo.rebaseRangeForBranch(
                onto: onto,
                preserveMerges: preserveMerges,
                root: root,
                branch: branch
            )
            await MainActor.run {
                guard rebaseRangeRequestIsCurrent(
                    generation: generation,
                    currentGeneration: self.rebaseRangeGeneration,
                    requestedOnto: onto,
                    currentOnto: self.rebaseOnto,
                    requestedPreserveMerges: preserveMerges,
                    currentPreserveMerges: self.rebasePreserveMerges,
                    requestedRoot: root,
                    currentRoot: self.rebaseRoot,
                    requestedBranch: branch,
                    currentBranch: self.rebaseBranch,
                    requestedRepositoryPath: repositoryPath,
                    currentRepositoryPath: self.rebaseRootPath
                ) else { return }
                self.rebaseRange = range
                self.rebaseActions = Array(repeating: .pick, count: range.count)
                self.rebaseFeedback = "范围 \(range.count) 个提交"
            }
        } catch {
            await MainActor.run {
                guard rebaseRangeRequestIsCurrent(
                    generation: generation,
                    currentGeneration: self.rebaseRangeGeneration,
                    requestedOnto: onto,
                    currentOnto: self.rebaseOnto,
                    requestedPreserveMerges: preserveMerges,
                    currentPreserveMerges: self.rebasePreserveMerges,
                    requestedRoot: root,
                    currentRoot: self.rebaseRoot,
                    requestedBranch: branch,
                    currentBranch: self.rebaseBranch,
                    requestedRepositoryPath: repositoryPath,
                    currentRepositoryPath: self.rebaseRootPath
                ) else { return }
                self.rebaseRange = []
                self.rebaseActions = []
                self.rebaseFeedback = "\(error)"
            }
        }
    }
}

func invalidateLoadedRebaseRange() {
    rebaseRangeGeneration += 1
    rebaseRange = []
    rebaseActions = []
    rebaseFeedback = nil
}

func doRebase() {
    guard operationState?.kind == nil,
          isArborVCSActionEnabled(.rebase, in: vcsActionContext),
          let repo else { return }
    let interactive = rebaseInteractive
    guard !interactive || !rebaseActions.isEmpty else { return }
    let onto = rebaseOnto.trimmingCharacters(in: .whitespacesAndNewlines)
    let branch = rebaseBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    let repositoryPath = rebaseRootPath.trimmingCharacters(in: .whitespacesAndNewlines)
    let root = rebaseRoot
    guard rebaseInputsCanLoadRange(onto: onto, branch: branch, root: root) else { return }
    let currentRepositoryPath = repo.workdir() ?? ""
    let persistedRepositoryPath = repositoryPath.isEmpty ? currentRepositoryPath : repositoryPath
    rebaseRangeGeneration += 1
    rebaseUndoSeed = nil
    rebaseUndoTarget = nil
    clearRebaseUndoSeed(repositoryPath: persistedRepositoryPath)
    let cancel = GitCancelHandle()
    beginFeedbackOperation("Rebase", cancelHandle: cancel)
    let actions = rebaseActions
    let preserveMerges = rebasePreserveMerges
    let autoSquash = rebaseAutoSquash
    let keepEmpty = rebaseKeepEmpty
    let updateRefs = rebaseUpdateRefs
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    rebaseRetryContext = RebaseRetryContext(
        repositoryPath: repositoryPath,
        branch: branch,
        onto: onto,
        actions: actions,
        interactive: interactive,
        preserveMerges: preserveMerges,
        autoSquash: autoSquash,
        keepEmpty: keepEmpty,
        updateRefs: updateRefs,
        root: root
    )
    Task.detached(priority: .userInitiated) {
        do {
            let selectedRepo: Repository
            if repositoryPath.isEmpty || repositoryPath == currentRepositoryPath {
                selectedRepo = repo
            } else {
                selectedRepo = try openRepository(path: repositoryPath)
            }
            let initialHead = try? selectedRepo.revisionCommitId(revision: branch)
            let undoSeed = initialHead.map {
                RebaseUndoSeed(
                    repositoryPath: persistedRepositoryPath,
                    branch: branch,
                    initialHead: $0,
                    updateRefs: updateRefs,
                    protectionCommitID: rebaseUndoProtectionCommitBeforeOperation(
                        repo: selectedRepo,
                        initialHead: $0,
                        onto: onto
                    )
                )
            }
            if let undoSeed {
                await MainActor.run {
                    self.rebaseUndoSeed = undoSeed
                    saveRebaseUndoSeed(undoSeed)
                }
            }
            let outcome: RebaseOutcome
            if interactive {
                outcome = try selectedRepo.rebaseBranchWithAdvancedOptionsAndPolicyAndCancel(
                    onto: onto,
                    branch: branch,
                    actions: actions,
                    preserveMerges: preserveMerges,
                    autoSquash: autoSquash,
                    keepEmpty: keepEmpty,
                    updateRefs: updateRefs,
                    root: root,
                    savePolicy: projectSavePolicy,
                    cancel: cancel
                )
            } else {
                outcome = try selectedRepo.rebaseBranchWithOptionsAndPolicyAndCancel(
                    onto: onto,
                    branch: branch,
                    preserveMerges: preserveMerges,
                    autoSquash: autoSquash,
                    keepEmpty: keepEmpty,
                    updateRefs: updateRefs,
                    root: root,
                    savePolicy: projectSavePolicy,
                    cancel: cancel
                )
            }
            let st = try selectedRepo.status()
            let finalHead = try? selectedRepo.revisionCommitId(revision: branch)
            let currentBranch = (try? selectedRepo.branchList())?.first(where: { $0.isCurrent })?.name
            let undoTarget = rebaseUndoTargetAfterCompletion(
                seed: undoSeed,
                currentBranch: currentBranch,
                finalHead: finalHead
            )
            await MainActor.run {
                if repositoryPath.isEmpty || repositoryPath == currentRepositoryPath {
                    self.entries = st
                }
                if outcome.paused {
                    self.rebaseRetryContext = nil
                    let pausedSeed = undoSeed
                    self.rebaseUndoSeed = pausedSeed
                    if let pausedSeed {
                        saveRebaseUndoSeed(pausedSeed)
                    } else {
                        clearRebaseUndoSeed(repositoryPath: persistedRepositoryPath)
                    }
                    self.rebaseUndoTarget = nil
                    self.rebasePaused = true
                    self.rebasePauseReason = outcome.pauseReason
                    self.rebaseConflicts = outcome.conflicts
                    if outcome.pauseReason == .conflict {
                        let names = outcome.conflicts.prefix(3).joined(separator: "、")
                        let suffix = names.isEmpty ? "" : "：\(names)"
                        self.rebaseFeedback = "冲突 \(outcome.conflicts.count) 个文件\(suffix)，请在状态页解决后「继续」"
                        self.showMergeRevisionsDialog = true
                    } else {
                        self.rebaseFeedback = "已暂停在 edit 提交，可修改文件后「继续」"
                    }
                    self.rebaseRange = []
                    self.rebaseActions = []
                } else {
                    self.rebaseRetryContext = nil
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = undoTarget
                    clearRebaseUndoSeed(repositoryPath: persistedRepositoryPath)
                    self.rebasePaused = false
                    self.rebasePauseReason = nil
                    self.rebaseConflicts = []
                    self.rebaseFeedback = "变基完成"
                    self.rebaseRange = []
                    self.rebaseActions = []
                    if let undoTarget {
                        self.feedbackCenter.success(
                            "Rebase completed",
                            detail: String(outcome.headId.prefix(7)),
                            additionalActions: [self.rebaseUndoFeedbackAction(for: undoTarget)],
                            notificationID: rebaseUndoNotificationID(repositoryPath: repositoryPath),
                            notificationGroup: .standard
                        )
                    } else {
                        self.feedbackCenter.success(
                            "Rebase completed",
                            detail: String(outcome.headId.prefix(7))
                        )
                    }
                }
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            let detail = errorMessage(error)
            if case .Cancelled = error as? EngineError {
                await MainActor.run {
                    self.rebaseFeedback = "变基已取消；保存的本地现场未被丢弃"
                    self.feedbackCenter.warning(
                        "Rebase cancelled",
                        detail: self.rebaseFeedback ?? detail,
                        nextStep: "Check Saved Changes or Stash, restore any pending local scene, then retry if needed."
                    )
                }
                return
            }
            // Re-running the original command is unsafe while Git has an
            // unfinished operation in the worktree. The recovery bar owns
            // Continue/Abort in that case; Retry is only offered for a clean
            // failed start.
            let operationStillActive: Bool
            do {
                let operationRepo: Repository
                if repositoryPath.isEmpty || repositoryPath == currentRepositoryPath {
                    operationRepo = repo
                } else {
                    operationRepo = try openRepository(path: repositoryPath)
                }
                operationStillActive = try operationRepo.operationState() != nil
            } catch {
                // Do not offer a destructive retry when the recovery state
                // itself cannot be inspected.
                operationStillActive = true
            }
            await MainActor.run {
                self.rebaseFeedback = detail
                if operationStillActive {
                    self.feedbackCenter.error(
                        "Rebase failed",
                        detail: detail,
                        nextStep: "Resolve conflicts, then Continue or Abort the rebase."
                    )
                } else {
                    self.rebaseUndoSeed = nil
                    clearRebaseUndoSeed(repositoryPath: persistedRepositoryPath)
                    self.feedbackCenter.error(
                        "Rebase failed",
                        detail: detail,
                        nextStep: "Resolve the cause and retry, or Abort if Git left an operation in progress.",
                        actionTitle: "Retry",
                        action: { self.retryLastRebase() }
                    )
                }
            }
        }
    }
}

func retryLastRebase() {
    guard let context = rebaseRetryContext else { return }
    rebaseRootPath = context.repositoryPath
    rebaseBranch = context.branch
    rebaseOnto = context.onto
    rebaseActions = context.actions
    rebaseInteractive = context.interactive
    rebasePreserveMerges = context.preserveMerges
    rebaseAutoSquash = context.autoSquash
    rebaseKeepEmpty = context.keepEmpty
    rebaseUpdateRefs = context.updateRefs
    rebaseRoot = context.root
    doRebase()
}

/// Undo only a completed single-root rebase whose target branch still points
/// at the exact HEAD produced by that operation.  This is the same safety
/// boundary as IntelliJ's notification actions: a later fetch, commit, push,
/// branch switch, active Git operation, or protected-remote publication
/// invalidates the action.
func undoLastRebase(_ requestedTarget: RebaseUndoTarget? = nil) {
    guard let target = requestedTarget ?? rebaseUndoTarget else { return }
    let protectedPatterns = effectiveProtectedBranchPatterns
    let notificationID = rebaseUndoNotificationID(repositoryPath: target.repositoryPath)
    beginFeedbackOperation("Undo Rebase", notificationID: notificationID)
    Task.detached(priority: .userInitiated) {
        do {
            let selectedRepo = try openRepository(path: target.repositoryPath)
            guard try selectedRepo.operationState() == nil else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 2,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "The rebase Undo action is unavailable while another Git operation is active."
                    ]
                )
            }
            let currentBranch = (try selectedRepo.branchList()).first(where: { $0.isCurrent })?.name
            guard currentBranch == target.branch,
                  try selectedRepo.revisionCommitId(revision: target.branch) == target.expectedHead else {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 1,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "The branch changed after the rebase; the Undo action is no longer safe."
                    ]
                )
            }
            let remoteBranches = try selectedRepo.remoteBranchList()
            let protectedCommitID = rebaseUndoProtectionCommit(
                repo: selectedRepo,
                initialHead: target.initialHead,
                expectedHead: target.expectedHead,
                recordedCommitID: target.protectionCommitID
            )
            if let protectedBranch = protectedRemoteBranchContainingCommit(
                repo: selectedRepo,
                commitID: protectedCommitID,
                remoteBranches: remoteBranches,
                protectedPatterns: protectedPatterns
            ) {
                throw NSError(
                    domain: "Arbor.Git",
                    code: 3,
                    userInfo: [
                        NSLocalizedDescriptionKey:
                            "The rebase Undo action is blocked: \(protectedBranch) contains published pre-rebase history."
                    ]
                )
            }
            try selectedRepo.reset(commitId: target.initialHead, mode: .keep)
            await MainActor.run {
                self.feedbackCenter.expire(notificationID: notificationID)
                if self.rebaseUndoTarget?.expectedHead == target.expectedHead {
                    self.rebaseUndoTarget = nil
                }
                clearRebaseUndoSeed(repositoryPath: target.repositoryPath)
                self.feedbackCenter.success(
                    "Rebase undone",
                    detail: target.branch + " restored to " + String(target.initialHead.prefix(7))
                )
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Undo Rebase failed",
                    detail: errorMessage(error),
                    nextStep: "The branch or published history may have changed; inspect the Log before trying another reset.",
                    notificationID: notificationID
                )
            }
        }
    }
}

/// Prepare one independent todo list per root before starting a batch rebase.
/// The preparation step is intentionally separate from execution so a user
/// can inspect every root's range and fix an invalid branch/ref before any
/// repository is rewritten.
func prepareMultiRootRebaseEditor() {
    guard !multiRoots.isEmpty else { return }
    let onto = rebaseOnto.trimmingCharacters(in: .whitespacesAndNewlines)
    let branch = rebaseBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    let rootMode = rebaseRoot
    guard rebaseInputsCanLoadRange(onto: onto, branch: branch, root: rootMode) else { return }

    let roots = multiRoots
    let preserveMerges = rebasePreserveMerges
    beginFeedbackOperation("Prepare multi-root rebase")
    Task.detached(priority: .userInitiated) {
        var drafts: [MultiRootRebaseTodoDraft] = []
        for root in roots {
            do {
                let rootRepo = try openRepository(path: root.path)
                let todo = try rootRepo.rebaseTodoForBranchWithOptions(
                    onto: onto,
                    // Keep the initial visible rows in native commit order;
                    // later edits carry their commit identities in the
                    // structured multi-root spec.
                    autoSquash: false,
                    preserveMerges: preserveMerges,
                    root: rootMode,
                    branch: branch
                )
                drafts.append(
                    MultiRootRebaseTodoDraft(
                        rootPath: root.path,
                        displayName: root.displayName,
                        items: todo.items,
                        rawTodo: nil,
                        loadError: nil
                    )
                )
            } catch {
                drafts.append(
                    MultiRootRebaseTodoDraft(
                        rootPath: root.path,
                        displayName: root.displayName,
                        items: [],
                        rawTodo: nil,
                        loadError: errorMessage(error)
                    )
                )
            }
        }
        let preparedDrafts = drafts
        await MainActor.run {
            self.multiRootRebaseDrafts = preparedDrafts
            self.showMultiRootRebaseEditor = true
            let failures = preparedDrafts.filter { $0.loadError != nil }
            if failures.isEmpty {
                let count = preparedDrafts.reduce(0) { $0 + $1.items.count }
                self.feedbackCenter.success(
                    "Multi-root rebase prepared",
                    detail: String(count) + " commits across " + String(preparedDrafts.count) + " repositories"
                )
            } else {
                self.feedbackCenter.error(
                    "Multi-root rebase range incomplete",
                    detail: failures.map { "\($0.displayName): \($0.loadError ?? "Unknown error")" }.joined(separator: "\n"),
                    nextStep: "Fix the branch or onto revision, then reload the ranges."
                )
            }
        }
    }
}

/// Capture the native todo for one repository in the multi-root editor. The
/// branch is explicit because the batch may target a branch that is not the
/// currently checked-out branch in that root.
func prepareMultiRootRawTodoEditor(_ draft: MultiRootRebaseTodoDraft) {
    guard draft.loadError == nil else { return }
    let onto = rebaseOnto.trimmingCharacters(in: .whitespacesAndNewlines)
    let branch = rebaseBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    let preserveMerges = rebasePreserveMerges
    let autoSquash = rebaseAutoSquash
    let keepEmpty = rebaseKeepEmpty
    let updateRefs = rebaseUpdateRefs
    let rootMode = rebaseRoot
    let projectSavePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)
    if let rawTodo = draft.rawTodo {
        multiRootRawTodoText = rawTodo
        multiRootRawTodoContext = MultiRootRawTodoContext(
            rootPath: draft.rootPath,
            displayName: draft.displayName,
            onto: onto,
            preserveMerges: preserveMerges,
            root: rootMode
        )
        return
    }

    let cancel = GitCancelHandle()
    beginFeedbackOperation(
        "Prepare Native Todo · \(draft.displayName)",
        cancelHandle: cancel
    )
    Task.detached(priority: .userInitiated) {
        do {
            let rootRepo = try openRepository(path: draft.rootPath)
            let rawTodo = try rootRepo.rebaseRawTodoForBranchWithOptionsAndPolicyAndCancel(
                onto: onto,
                branch: branch,
                preserveMerges: preserveMerges,
                autoSquash: autoSquash,
                keepEmpty: keepEmpty,
                updateRefs: updateRefs,
                root: rootMode,
                savePolicy: projectSavePolicy,
                cancel: cancel
            )
            await MainActor.run {
                self.multiRootRawTodoText = rawTodo
                self.multiRootRawTodoContext = MultiRootRawTodoContext(
                    rootPath: draft.rootPath,
                    displayName: draft.displayName,
                    onto: onto,
                    preserveMerges: preserveMerges,
                    root: rootMode
                )
                self.feedbackCenter.success(
                    "Native todo ready",
                    detail: draft.displayName + " · control rows remain editable"
                )
            }
        } catch {
            await MainActor.run {
                if case .Cancelled = error as? EngineError {
                    self.feedbackCenter.warning(
                        "Native todo preparation cancelled",
                        detail: draft.displayName,
                        nextStep: "The local scene was restored; reopen the native todo editor to retry."
                    )
                } else {
                    self.feedbackCenter.error(
                        "Prepare native todo failed",
                        detail: draft.displayName + ": " + errorMessage(error),
                        nextStep: "The root must be free of another Git operation; retry after refreshing."
                    )
                }
            }
        }
    }
}

/// Store the text edited for one root without starting the batch yet. Other
/// roots remain structured or raw independently in the same editor.
func finishMultiRootRawTodoEditor(_ context: MultiRootRawTodoContext) {
    let rawTodo = multiRootRawTodoText
    guard !rawTodo.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
          let index = multiRootRebaseDrafts.firstIndex(where: { $0.rootPath == context.rootPath }) else {
        return
    }
    multiRootRebaseDrafts[index].rawTodo = rawTodo
    multiRootRawTodoContext = nil
    multiRootRawTodoText = ""
}

/// Execute the edited per-root todo lists as one dependency-ordered batch.
/// The Rust engine stops at the first paused/failed root and returns the
/// already completed and skipped roots for the same partial-result model as
/// IntelliJ's GitRebaseSpec/GitRebaseProcess.
func doMultiRootRebase(drafts: [MultiRootRebaseTodoDraft]?) {
    multiRootUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryAvailable = false
    multiRootCheckoutUpdateRetryContext = nil
    guard let projectPath, !multiRoots.isEmpty else { return }
    let onto = rebaseOnto.trimmingCharacters(in: .whitespacesAndNewlines)
    let branch = rebaseBranch.trimmingCharacters(in: .whitespacesAndNewlines)
    let rootMode = rebaseRoot
    guard rebaseInputsCanLoadRange(onto: onto, branch: branch, root: rootMode) else { return }

    let draftsByPath = Dictionary(uniqueKeysWithValues: (drafts ?? []).map { ($0.rootPath, $0) })
    if rebaseInteractive {
        guard multiRoots.allSatisfy({
            guard let draft = draftsByPath[$0.path] else { return false }
            return draft.loadError == nil && !draft.items.isEmpty
        }) else {
            feedbackCenter.error(
                "Multi-root rebase is not ready",
                detail: "Every repository must have a loaded, non-empty todo list.",
                nextStep: "Reload the ranges and review each repository before starting."
            )
            return
        }
    }

    let savePolicyRaw = GitLocalChangesSavePolicySettings.choice(for: projectPath).rawValue
    let savePolicy = GitLocalChangesSavePolicySettings.engineValue(for: projectPath)

    let specs = multiRoots.compactMap { root -> MultiRootRebaseSpec? in
        let actions: [RebaseAction]
        if rebaseInteractive {
            guard let draft = draftsByPath[root.path] else { return nil }
            actions = draft.items.map { item -> RebaseAction in
                switch item.action {
                case .pick:
                    return .pick
                case .drop:
                    return .drop
                case .reword:
                    return .reword(message: item.message ?? item.summary)
                case .squash:
                    if let message = item.message?.trimmingCharacters(in: .whitespacesAndNewlines),
                       !message.isEmpty {
                        return .squashWithMessage(message: message)
                    }
                    return .squash
                case .fixup:
                    return .fixup
                case .edit:
                    return .edit
                }
            }
        } else {
            actions = []
        }
        return MultiRootRebaseSpec(
            rootPath: root.path,
            branch: branch,
            onto: onto,
            actions: actions,
            orderedCommitIds: rebaseInteractive
                && rebasePreserveMerges
                && draftsByPath[root.path]?.rawTodo == nil
                ? (draftsByPath[root.path]?.items.map(\.commitId) ?? [])
                : [],
            rawTodo: draftsByPath[root.path]?.rawTodo,
            preserveMerges: rebasePreserveMerges,
            autoSquash: rebaseAutoSquash,
            keepEmpty: rebaseKeepEmpty,
            updateRefs: rebaseUpdateRefs,
            root: rootMode,
            interactive: rebaseInteractive,
            savePolicy: savePolicy
        )
    }
    guard specs.count == multiRoots.count else { return }

    let session = MultiRootRebaseSession(
        projectPath: projectPath,
        roots: specs.map { spec in
            let displayName = multiRoots.first(where: { $0.path == spec.rootPath })?.displayName
                ?? URL(fileURLWithPath: spec.rootPath).lastPathComponent
            return MultiRootRebaseSessionRoot(
                rootPath: spec.rootPath,
                displayName: displayName,
                branch: spec.branch,
                onto: spec.onto,
                actions: spec.actions.map(PersistedRebaseAction.init),
                orderedCommitIds: spec.orderedCommitIds.isEmpty ? nil : spec.orderedCommitIds,
                rawTodo: spec.rawTodo,
                preserveMerges: spec.preserveMerges,
                autoSquash: spec.autoSquash,
                keepEmpty: spec.keepEmpty,
                updateRefs: spec.updateRefs,
                root: spec.root,
                savePolicyRaw: savePolicyRaw,
                state: .pending,
                initialHead: nil,
                expectedHead: nil,
                initialBranch: nil,
                message: ""
            )
        }
    )
    multiRootRebaseSession = session
    saveMultiRootRebaseSession(session)
    rebaseRangeGeneration += 1
    runPendingMultiRootRebase(session)
}

private func multiRootRebaseSessionKey(projectPath: String) -> String {
    let normalizedPath = URL(fileURLWithPath: projectPath).standardizedFileURL.path
    let encoded = Data(normalizedPath.utf8)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
    return "arbor.multiRootRebase.session.v1.\(encoded)"
}

private func saveMultiRootRebaseSession(_ session: MultiRootRebaseSession) {
    guard let data = try? JSONEncoder().encode(session) else { return }
    UserDefaults.standard.set(data, forKey: multiRootRebaseSessionKey(projectPath: session.projectPath))
}

private func loadMultiRootRebaseSession(projectPath: String) -> MultiRootRebaseSession? {
    let key = multiRootRebaseSessionKey(projectPath: projectPath)
    guard let data = UserDefaults.standard.data(forKey: key) else { return nil }
    return try? JSONDecoder().decode(MultiRootRebaseSession.self, from: data)
}

private func clearMultiRootRebaseSession(_ session: MultiRootRebaseSession) {
    UserDefaults.standard.removeObject(forKey: multiRootRebaseSessionKey(projectPath: session.projectPath))
}

private func multiRootRebaseRows(for session: MultiRootRebaseSession) -> [RootOperationResult] {
    session.roots.map { root in
        switch root.state {
        case .pending:
            return RootOperationResult(
                rootPath: root.rootPath,
                displayName: root.displayName,
                success: true,
                skipped: true,
                message: root.message.isEmpty ? "not attempted yet" : root.message
            )
        case .completed:
            return RootOperationResult(
                rootPath: root.rootPath,
                displayName: root.displayName,
                success: true,
                skipped: false,
                message: root.message.isEmpty ? "rebase completed" : root.message
            )
        case .paused:
            return RootOperationResult(
                rootPath: root.rootPath,
                displayName: root.displayName,
                success: true,
                skipped: false,
                message: root.message.isEmpty ? "rebase paused" : root.message
            )
        case .failed:
            return RootOperationResult(
                rootPath: root.rootPath,
                displayName: root.displayName,
                success: false,
                skipped: false,
                message: root.message.isEmpty ? "rebase failed" : root.message
            )
        case .aborted:
            return RootOperationResult(
                rootPath: root.rootPath,
                displayName: root.displayName,
                success: false,
                skipped: false,
                message: root.message.isEmpty ? "rebase aborted" : root.message
            )
        }
    }
}

private func multiRootRebaseFeedbackResultRows(
    for session: MultiRootRebaseSession
) -> [FeedbackResultRow] {
    let pausedRootPaths = Set(
        session.roots
            .filter { $0.state == .paused }
            .map(\.rootPath)
    )
    return feedbackResultRows(
        from: multiRootRebaseRows(for: session),
        partialRootPaths: pausedRootPaths
    )
}

private func updateMultiRootRebaseSession(
    _ session: MultiRootRebaseSession,
    with results: [MultiRootRebaseResult]
) -> MultiRootRebaseSession {
    var updated = session
    for result in results {
        guard let index = updated.roots.firstIndex(where: { $0.rootPath == result.rootPath }) else { continue }
        var root = updated.roots[index]
        root.initialHead = result.initialHead ?? root.initialHead
        root.expectedHead = result.finalHead ?? root.expectedHead
        root.initialBranch = result.initialBranch ?? root.initialBranch
        root.message = result.message
        if result.skipped {
            updated.roots[index] = root
            continue
        }
        if result.requiresFinish {
            root.state = .paused
        } else if result.success && result.completed {
            root.state = .completed
        } else {
            root.state = .failed
        }
        updated.roots[index] = root
    }
    return updated
}

private func multiRootRebaseRollbackTargets(
    for session: MultiRootRebaseSession,
    completedOnly: Bool = true
) -> [MultiRootRebaseRollbackTarget] {
    session.roots.compactMap { root -> MultiRootRebaseRollbackTarget? in
        guard (!completedOnly || root.state == .completed),
              let initialHead = root.initialHead,
              let expectedHead = root.expectedHead,
              initialHead != expectedHead else { return nil }
        return MultiRootRebaseRollbackTarget(
            rootPath: root.rootPath,
            displayName: root.displayName,
            initialHead: initialHead,
            expectedHead: expectedHead,
            branch: root.branch,
            protectionCommitID: root.protectionCommitID
        )
    }
}

private func runPendingMultiRootRebase(_ session: MultiRootRebaseSession) {
    guard !multiRootRunning else { return }
    let pendingRoots = session.roots.filter { $0.state == .pending }
    guard !pendingRoots.isEmpty else { return }
    let specs = pendingRoots.map { $0.makeSpec() }
    let sessionID = session.id
    let cancel = GitCancelHandle()
    multiRootRunning = true
    beginFeedbackOperation(
        "Multi-root Rebase",
        cancelHandle: cancel,
        notificationID: multiRootRebaseNotificationID()
    )
    if session.roots.contains(where: { $0.state != .pending }) {
        feedbackCenter.attachResultRows(
            multiRootRebaseFeedbackResultRows(for: session),
            notificationID: multiRootRebaseNotificationID()
        )
    }
    Task.detached(priority: .userInitiated) {
        var activeRootPath: String?
        for root in pendingRoots {
            if let rootRepo = try? openRepository(path: root.rootPath),
               (try? rootRepo.operationState()) != nil {
                activeRootPath = root.rootPath
                break
            }
        }
        if let activeRootPath {
            if let activeRepo = try? openRepository(path: activeRootPath) {
                Task.detached(priority: .userInitiated) {
                    while !Task.isCancelled {
                        if let pending = try? activeRepo.rebasePendingMessage() {
                            await MainActor.run {
                                guard self.multiRootRebaseSession?.id == sessionID,
                                      !self.showRawRebaseMessageEditor else { return }
                                self.rawRebaseMessageRepository = activeRepo
                                self.rawRebaseMessageText = pending
                                self.showRawRebaseMessageEditor = true
                            }
                        }
                        if (try? activeRepo.operationState()) == nil {
                            break
                        }
                        try? await Task.sleep(nanoseconds: 100_000_000)
                    }
                }
            }
            await MainActor.run {
                guard self.multiRootRebaseSession?.id == sessionID else { return }
                self.multiRootRunning = false
                self.feedbackCenter.warning(
                    "Multi-root rebase paused",
                    detail: "A Git rebase is already in progress in \(activeRootPath).",
                    additionalActions: [
                        self.multiRootRebaseRecoveryFeedbackAction(
                            .openRecovery,
                            rootPath: activeRootPath,
                            sessionID: sessionID
                        )
                    ],
                    notificationID: self.multiRootRebaseNotificationID()
                )
                self.feedbackCenter.attachResultRows(
                    multiRootRebaseFeedbackResultRows(for: session),
                    notificationID: self.multiRootRebaseNotificationID()
                )
                self.openMultiRootConflictResolver(preferredRootPath: activeRootPath)
            }
            return
        }
        var protectionCommitIDs: [String: String] = [:]
        for root in pendingRoots {
            guard let rootRepo = try? openRepository(path: root.rootPath),
                  let initialHead = try? rootRepo.revisionCommitId(revision: root.branch),
                  let protectionCommitID = rebaseUndoProtectionCommitBeforeOperation(
                      repo: rootRepo,
                      initialHead: initialHead,
                      onto: root.onto
                  ) else { continue }
            protectionCommitIDs[root.rootPath] = protectionCommitID
        }
        if !protectionCommitIDs.isEmpty {
            let recordedProtectionCommitIDs = protectionCommitIDs
            await MainActor.run {
                guard var current = self.multiRootRebaseSession,
                      current.id == sessionID else { return }
                for index in current.roots.indices {
                    if let protectionCommitID = recordedProtectionCommitIDs[current.roots[index].rootPath] {
                        current.roots[index].protectionCommitID = protectionCommitID
                    }
                }
                self.multiRootRebaseSession = current
                saveMultiRootRebaseSession(current)
            }
        }
        let messageMonitorRepositories = pendingRoots.compactMap {
            try? openRepository(path: $0.rootPath)
        }
        let messageMonitorPaths = Set(pendingRoots.map(\.rootPath))
        let messageMonitor = Task.detached(priority: .userInitiated) {
            while !Task.isCancelled {
                for rootRepo in messageMonitorRepositories {
                    if let pending = try? rootRepo.rebasePendingMessage() {
                        await MainActor.run {
                            guard !self.showRawRebaseMessageEditor else { return }
                            self.rawRebaseMessageRepository = rootRepo
                            self.rawRebaseMessageText = pending
                            self.showRawRebaseMessageEditor = true
                        }
                    }
                }
                try? await Task.sleep(nanoseconds: 100_000_000)
            }
        }
        do {
            let results = try runMultiRootRebaseWithCancel(specs: specs, cancel: cancel)
            messageMonitor.cancel()
            await MainActor.run {
                guard let current = self.multiRootRebaseSession,
                      current.id == sessionID else { return }
                if messageMonitorPaths.contains(self.rawRebaseMessageRepository?.workdir() ?? "") {
                    self.showRawRebaseMessageEditor = false
                    self.rawRebaseMessageRepository = nil
                    self.rawRebaseMessageText = ""
                }
                self.applyMultiRootRebaseResults(results, to: current)
            }
        } catch {
            messageMonitor.cancel()
            await MainActor.run {
                guard let current = self.multiRootRebaseSession,
                      current.id == sessionID else { return }
                self.multiRootRunning = false
                if messageMonitorPaths.contains(self.rawRebaseMessageRepository?.workdir() ?? "") {
                    self.showRawRebaseMessageEditor = false
                    self.rawRebaseMessageRepository = nil
                    self.rawRebaseMessageText = ""
                }
                self.feedbackCenter.error(
                    "Multi-root rebase failed",
                    detail: errorMessage(error),
                    nextStep: "Review the roots view before retrying.",
                    additionalActions: [
                        self.multiRootRebaseRecoveryFeedbackAction(.retry, sessionID: sessionID)
                    ],
                    notificationID: self.multiRootRebaseNotificationID()
                )
                self.feedbackCenter.attachResultRows(
                    multiRootRebaseFeedbackResultRows(for: current),
                    notificationID: self.multiRootRebaseNotificationID()
                )
            }
        }
    }
}

private func applyMultiRootRebaseResults(
    _ results: [MultiRootRebaseResult],
    to session: MultiRootRebaseSession
) {
    let updated = updateMultiRootRebaseSession(session, with: results)
    multiRootRebaseSession = updated
    saveMultiRootRebaseSession(updated)
    multiRootRunning = false
    multiRootResults = multiRootRebaseRows(for: updated)
    rebaseFeedback = updated.roots
        .map { "\($0.displayName): \($0.message)" }
        .joined(separator: "\n")
    multiRootRebaseDrafts = []
    loadMultiRoots()

    if let paused = results.first(where: { $0.requiresFinish }) {
        let conflicts = paused.conflicts.isEmpty
            ? ""
            : "\n\(paused.conflicts.joined(separator: "、"))"
        feedbackCenter.warning(
            "Multi-root rebase paused",
            detail: "\(paused.displayName): \(paused.message)\(conflicts)",
            nextStep: "Resolve the root conflict, then use Continue or Abort from the roots view.",
            additionalActions: [
                multiRootRebaseRecoveryFeedbackAction(
                    .openRecovery,
                    rootPath: paused.rootPath,
                    sessionID: updated.id
                )
            ],
            notificationID: multiRootRebaseNotificationID()
        )
        openMultiRootConflictResolver(
            preferredRootPath: paused.rootPath,
            preferredPath: paused.conflicts.first
        )
    } else if let failure = results.first(where: { !$0.success && !$0.skipped }) {
        feedbackCenter.error(
            "Multi-root rebase partially completed",
            detail: "\(failure.displayName): \(failure.message)",
            nextStep: "Fix the failed root, then retry the remaining repositories.",
            additionalActions: [
                multiRootRebaseRecoveryFeedbackAction(.retry, sessionID: updated.id)
            ],
            notificationID: multiRootRebaseNotificationID()
        )
    } else if updated.roots.allSatisfy({ $0.state == .completed }) {
        let undoTargets = updated.roots.allSatisfy { !$0.updateRefs }
            ? multiRootRebaseRollbackTargets(for: updated)
            : []
        clearMultiRootRebaseSession(updated)
        multiRootRebaseSession = nil
        if undoTargets.count == updated.roots.count, !undoTargets.isEmpty {
            let undoAction = multiRootRebaseRecoveryFeedbackAction(
                .undo,
                rollbackTargets: undoTargets
            )
            feedbackCenter.success(
                "Multi-root rebase completed",
                detail: updated.projectPath,
                additionalActions: [undoAction],
                notificationID: multiRootRebaseNotificationID()
            )
        } else {
            feedbackCenter.success(
                "Multi-root rebase completed",
                detail: updated.projectPath,
                notificationID: multiRootRebaseNotificationID()
            )
        }
    }
    feedbackCenter.attachResultRows(
        multiRootRebaseFeedbackResultRows(for: updated),
        notificationID: multiRootRebaseNotificationID()
    )
}

func retryMultiRootRebase() {
    guard var session = multiRootRebaseSession else { return }
    for index in session.roots.indices where session.roots[index].state == .failed {
        session.roots[index].state = .pending
        session.roots[index].message = ""
    }
    multiRootRebaseSession = session
    saveMultiRootRebaseSession(session)
    runPendingMultiRootRebase(session)
}

/// Restore the persisted batch spec after project reopen. An active Git
/// operation is never replayed; it is handed to the project-level resolver.
func restorePersistedMultiRootRebaseSession(for projectPath: String) {
    guard multiRootRebaseSession == nil,
          let session = loadMultiRootRebaseSession(projectPath: projectPath),
          session.projectPath == projectPath else { return }
    guard session.roots.contains(where: { $0.state != .completed && $0.state != .aborted }) else {
        clearMultiRootRebaseSession(session)
        return
    }
    multiRootRebaseSession = session
    let sessionID = session.id
    Task.detached(priority: .utility) {
        let activeRoot = session.roots.compactMap { root -> String? in
            guard let rootRepo = try? openRepository(path: root.rootPath),
                  (try? rootRepo.operationState()) != nil else { return nil }
            return root.rootPath
        }.first
        await MainActor.run {
            guard self.multiRootRebaseSession?.id == sessionID else { return }
            if let activeRoot {
                self.feedbackCenter.warning(
                    "Multi-root rebase paused",
                    detail: "A persisted rebase is waiting in \(activeRoot).",
                    additionalActions: [
                        self.multiRootRebaseRecoveryFeedbackAction(
                            .openRecovery,
                            rootPath: activeRoot,
                            sessionID: sessionID
                        )
                    ],
                    notificationID: self.multiRootRebaseNotificationID()
                )
            } else {
                self.feedbackCenter.warning(
                    "Multi-root rebase recovery available",
                    detail: "The previous multi-root rebase did not finish.",
                    additionalActions: [
                        self.multiRootRebaseRecoveryFeedbackAction(.resume, sessionID: sessionID)
                    ],
                    notificationID: self.multiRootRebaseNotificationID()
                )
            }
        }
    }
}

func resumeMultiRootRebase() {
    guard let session = multiRootRebaseSession else { return }
    let sessionID = session.id
    Task.detached(priority: .utility) { [session] in
        let activeRoot = session.roots.compactMap { root -> String? in
            guard let rootRepo = try? openRepository(path: root.rootPath),
                  (try? rootRepo.operationState()) != nil else { return nil }
            return root.rootPath
        }.first
        await MainActor.run {
            guard self.multiRootRebaseSession?.id == sessionID else { return }
            if let activeRoot {
                self.openMultiRootConflictResolver(preferredRootPath: activeRoot)
                return
            }
            if session.roots.contains(where: { $0.state == .paused }) {
                self.feedbackCenter.error(
                    "Multi-root rebase recovery unavailable",
                    detail: "Git no longer reports the paused rebase state for this session.",
                    nextStep: "Inspect the affected roots and keep or restore the partial state manually."
                )
                return
            }
            var resumedSession = session
            for index in resumedSession.roots.indices where resumedSession.roots[index].state == .failed {
                resumedSession.roots[index].state = .pending
                resumedSession.roots[index].message = ""
            }
            self.multiRootRebaseSession = resumedSession
            saveMultiRootRebaseSession(resumedSession)
            self.runPendingMultiRootRebase(resumedSession)
        }
    }
}

private func handleMultiRootRebaseRecovery(
    rootPath: String,
    action: MultiRootRecoveryAction,
    operationStillActive: Bool,
    sessionID: UUID
) {
    guard var session = multiRootRebaseSession, session.id == sessionID,
          let index = session.roots.firstIndex(where: { $0.rootPath == rootPath }) else { return }
    var root = session.roots[index]
    if operationStillActive {
        root.state = .paused
        root.message = "rebase remains paused"
        session.roots[index] = root
        multiRootRebaseSession = session
        saveMultiRootRebaseSession(session)
        return
    }

    switch action {
    case .continueOperation, .skip:
        root.state = .completed
        root.message = action == .skip ? "rebase step skipped and root completed" : "rebase completed"
        session.roots[index] = root
        multiRootRebaseSession = session
        saveMultiRootRebaseSession(session)
        if session.roots.contains(where: { $0.state == .pending }) {
            feedbackCenter.success("Rebase root completed", detail: "Starting the next repository.")
            runPendingMultiRootRebase(session)
        } else {
            clearMultiRootRebaseSession(session)
            multiRootRebaseSession = nil
            feedbackCenter.success("Multi-root rebase completed", detail: session.projectPath)
        }
    case .abort:
        root.state = .aborted
        root.message = "rebase aborted"
        session.roots[index] = root
        multiRootRebaseSession = session
        saveMultiRootRebaseSession(session)
        let targets = multiRootRebaseRollbackTargets(for: session)
        let failures = session.roots
            .filter { $0.state == .failed || $0.state == .aborted || $0.state == .pending }
            .map { "\($0.displayName): \($0.message)" }
        if targets.isEmpty {
            clearMultiRootRebaseSession(session)
            multiRootRebaseSession = nil
            feedbackCenter.warning("Multi-root rebase aborted", detail: failures.joined(separator: "\n"))
        } else {
            multiRootRebaseRollbackContext = MultiRootRebaseRollbackContext(
                sessionID: session.id,
                branch: root.branch,
                targets: targets,
                failures: failures
            )
            feedbackCenter.warning(
                "Multi-root rebase partially completed",
                detail: failures.joined(separator: "\n"),
                nextStep: "Choose whether to rollback the successful repositories or keep the partial state.",
                additionalActions: [
                    multiRootRebaseRecoveryFeedbackAction(
                        .rollback,
                        sessionID: session.id
                    ),
                    multiRootRebaseRecoveryFeedbackAction(
                        .keepPartial,
                        sessionID: session.id
                    )
                ],
                notificationID: multiRootRebaseNotificationID()
            )
        }
    }
}

private func rollbackPersistedMultiRootRebase() {
    guard let session = multiRootRebaseSession else { return }
    let targets = multiRootRebaseRollbackTargets(for: session)
    guard !targets.isEmpty else {
        clearMultiRootRebaseSession(session)
        multiRootRebaseSession = nil
        feedbackCenter.warning(
            "Multi-root rebase rollback unavailable",
            detail: "No completed root has an expected HEAD to restore.",
            notificationID: multiRootRebaseNotificationID()
        )
        return
    }
    multiRootRebaseRollbackContext = MultiRootRebaseRollbackContext(
        sessionID: session.id,
        branch: session.roots.first?.branch ?? rebaseBranch,
        targets: targets,
        failures: session.roots
            .filter { $0.state == .failed || $0.state == .aborted || $0.state == .pending }
            .map { "\($0.displayName): \($0.message)" }
    )
    rollbackMultiRootRebase(targets)
}

private func keepPersistedMultiRootRebasePartial() {
    guard let session = multiRootRebaseSession else { return }
    let context = MultiRootRebaseRollbackContext(
        sessionID: session.id,
        branch: session.roots.first?.branch ?? rebaseBranch,
        targets: multiRootRebaseRollbackTargets(for: session),
        failures: session.roots
            .filter { $0.state == .failed || $0.state == .aborted || $0.state == .pending }
            .map { "\($0.displayName): \($0.message)" }
    )
    keepMultiRootRebasePartial(context)
}

func keepMultiRootRebasePartial(_ context: MultiRootRebaseRollbackContext) {
    multiRootRebaseRollbackContext = nil
    if let session = multiRootRebaseSession, session.id == context.sessionID {
        clearMultiRootRebaseSession(session)
        multiRootRebaseSession = nil
    }
    feedbackCenter.warning(
        "Partial rebase kept",
        detail: context.branch,
        nextStep: "Review the affected repositories in Git Roots."
    )
}

func rollbackMultiRootRebase(
    _ targets: [MultiRootRebaseRollbackTarget],
    completionTitle: String = "Multi-root rebase rollback completed"
) {
    guard !targets.isEmpty else { return }
    let context = multiRootRebaseRollbackContext
    multiRootRebaseRollbackContext = nil
    let protectedPatterns = effectiveProtectedBranchPatterns
    let notificationID = multiRootRebaseNotificationID()
    beginFeedbackOperation(
        "Rollback multi-root rebase",
        notificationID: notificationID
    )
    Task.detached(priority: .userInitiated) {
        var failures: [String] = []
        var remaining: [MultiRootRebaseRollbackTarget] = []
        for target in targets {
            do {
                let rootRepo = try openRepository(path: target.rootPath)
                guard try rootRepo.operationState() == nil else {
                    throw NSError(
                        domain: "Arbor.MultiRootRebaseRollback",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "A Git operation is still in progress."]
                    )
                }
                let remoteBranches = try rootRepo.remoteBranchList()
                let protectedCommitID = rebaseUndoProtectionCommit(
                    repo: rootRepo,
                    initialHead: target.initialHead,
                    expectedHead: target.expectedHead,
                    recordedCommitID: target.protectionCommitID
                )
                if let protectedBranch = protectedRemoteBranchContainingCommit(
                    repo: rootRepo,
                    commitID: protectedCommitID,
                    remoteBranches: remoteBranches,
                    protectedPatterns: protectedPatterns
                ) {
                    throw NSError(
                        domain: "Arbor.MultiRootRebaseRollback",
                        code: 2,
                        userInfo: [
                            NSLocalizedDescriptionKey:
                                "Rollback is blocked: \(protectedBranch) contains published pre-rebase history."
                        ]
                    )
                }
                try rootRepo.restoreBranchIfExpected(
                    branch: target.branch,
                    initialCommitId: target.initialHead,
                    expectedCommitId: target.expectedHead
                )
            } catch {
                failures.append("\(target.displayName): \(errorMessage(error))")
                remaining.append(target)
            }
        }
        let rollbackFailures = failures
        let rollbackRemaining = remaining
        await MainActor.run {
            self.loadMultiRoots()
            if rollbackFailures.isEmpty {
                if let session = self.multiRootRebaseSession {
                    clearMultiRootRebaseSession(session)
                }
                self.multiRootRebaseSession = nil
                if let notificationID {
                    self.feedbackCenter.expire(notificationID: notificationID)
                }
                self.feedbackCenter.success(completionTitle)
            } else {
                self.feedbackCenter.warning(
                    "Multi-root rebase rollback partially failed",
                    detail: rollbackFailures.joined(separator: "\n"),
                    nextStep: "Review the affected repositories and retry the remaining rollback targets.",
                    additionalActions: rollbackRemaining.isEmpty
                        ? []
                        : [
                            self.multiRootRebaseRecoveryFeedbackAction(
                                .undo,
                                rollbackTargets: rollbackRemaining
                            )
                        ],
                    notificationID: notificationID
                )
                if let context {
                    self.multiRootRebaseRollbackContext = MultiRootRebaseRollbackContext(
                        sessionID: context.sessionID,
                        branch: context.branch,
                        targets: rollbackRemaining,
                        failures: rollbackFailures
                    )
                }
            }
        }
    }
}

func promptReword(index: Int, defaultMessage: String) {
    guard rebaseActions.indices.contains(index) else { return }
    let alert = NSAlert()
    alert.messageText = "修改提交信息"
    alert.informativeText = "请输入新的提交标题。"
    let field = NSTextField(string: defaultMessage)
    field.frame = NSRect(x: 0, y: 0, width: 360, height: 24)
    alert.accessoryView = field
    alert.addButton(withTitle: "确定")
    alert.addButton(withTitle: "取消")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    let message = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !message.isEmpty else { return }
    rebaseActions[index] = .reword(message: message)
}

func doRebaseContinue() {
    guard let repo else { return }
    beginFeedbackOperation("Continue rebase")
    let seed = rebaseUndoSeed
    let selectedRootPath = rebaseRootPath.trimmingCharacters(in: .whitespacesAndNewlines)
    let repositoryPath = seed?.repositoryPath ?? selectedRootPath
    let currentRepositoryPath = repo.workdir() ?? ""
    Task.detached(priority: .userInitiated) {
        do {
            let selectedRepo: Repository
            if repositoryPath.isEmpty || repositoryPath == currentRepositoryPath {
                selectedRepo = repo
            } else {
                selectedRepo = try openRepository(path: repositoryPath)
            }
            let outcome = try selectedRepo.rebaseContinue()
            let st = try selectedRepo.status()
            let currentBranch = (try? selectedRepo.branchList())?.first(where: { $0.isCurrent })?.name
            let finalHead = seed.flatMap { try? selectedRepo.revisionCommitId(revision: $0.branch) }
            let undoTarget = rebaseUndoTargetAfterCompletion(
                seed: seed,
                currentBranch: currentBranch,
                finalHead: finalHead
            )
            await MainActor.run {
                if repositoryPath.isEmpty || repositoryPath == currentRepositoryPath {
                    self.entries = st
                }
                self.rebasePaused = outcome.paused
                self.rebasePauseReason = outcome.pauseReason
                self.rebaseConflicts = outcome.conflicts
                if outcome.paused, outcome.pauseReason == .conflict {
                    let names = outcome.conflicts.prefix(3).joined(separator: "、")
                    let suffix = names.isEmpty ? "" : "：\(names)"
                    self.rebaseFeedback = "再次冲突 \(outcome.conflicts.count) 个文件\(suffix)"
                    self.rebaseUndoSeed = seed
                    self.rebaseUndoTarget = nil
                    if let seed {
                        saveRebaseUndoSeed(seed)
                    }
                    self.showMergeRevisionsDialog = true
                } else {
                    self.rebaseFeedback = outcome.paused ? "再次暂停在 edit 提交" : "变基完成"
                    if !outcome.paused {
                        self.showMergeRevisionsDialog = false
                        self.rebaseUndoSeed = nil
                        self.rebaseUndoTarget = undoTarget
                        if let seed {
                            clearRebaseUndoSeed(repositoryPath: seed.repositoryPath)
                        }
                        if let undoTarget {
                            self.feedbackCenter.success(
                                "Rebase completed",
                                detail: String(outcome.headId.prefix(7)),
                                additionalActions: [self.rebaseUndoFeedbackAction(for: undoTarget)],
                                notificationID: rebaseUndoNotificationID(repositoryPath: undoTarget.repositoryPath),
                                notificationGroup: .standard
                            )
                        } else {
                            self.feedbackCenter.success(
                                "Rebase completed",
                                detail: String(outcome.headId.prefix(7))
                            )
                        }
                    } else {
                        self.rebaseUndoSeed = seed
                        self.rebaseUndoTarget = nil
                        if let seed {
                            saveRebaseUndoSeed(seed)
                        }
                    }
                }
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            let detail = errorMessage(error)
            let recoveryRepository: Repository?
            if repositoryPath.isEmpty || repositoryPath == currentRepositoryPath {
                recoveryRepository = repo
            } else {
                recoveryRepository = try? openRepository(path: repositoryPath)
            }
            let canStageAndRetry: Bool
            if let recoveryRepository {
                canStageAndRetry = (try? recoveryRepository.status().contains {
                    $0.unstaged != .unchanged
                        && $0.unstaged != .untracked
                        && $0.unstaged != .ignored
                        && $0.unstaged != .conflicted
                }) ?? false
            } else {
                canStageAndRetry = false
            }
            await MainActor.run {
                self.rebaseFeedback = detail
                self.feedbackCenter.error(
                    "Rebase continue failed",
                    detail: detail,
                    nextStep: "Resolve remaining conflicts or stage tracked changes before continuing.",
                    actionTitle: canStageAndRetry ? "Stage-and-Retry" : nil,
                    action: canStageAndRetry ? { self.stageAndRetryRebaseContinue() } : nil
                )
            }
        }
    }
}

func stageAndRetryRebaseContinue() {
    guard let repo else { return }
    beginFeedbackOperation("Stage-and-Retry Rebase")
    let seed = rebaseUndoSeed
    let selectedRootPath = rebaseRootPath.trimmingCharacters(in: .whitespacesAndNewlines)
    let repositoryPath = seed?.repositoryPath ?? selectedRootPath
    let currentRepositoryPath = repo.workdir() ?? ""
    Task.detached(priority: .userInitiated) {
        do {
            let selectedRepo: Repository
            if repositoryPath.isEmpty || repositoryPath == currentRepositoryPath {
                selectedRepo = repo
            } else {
                selectedRepo = try openRepository(path: repositoryPath)
            }
            try selectedRepo.stageTracked()
            let outcome = try selectedRepo.rebaseContinue()
            let st = try selectedRepo.status()
            let currentBranch = (try? selectedRepo.branchList())?.first(where: { $0.isCurrent })?.name
            let finalHead = seed.flatMap { try? selectedRepo.revisionCommitId(revision: $0.branch) }
            let undoTarget = rebaseUndoTargetAfterCompletion(
                seed: seed,
                currentBranch: currentBranch,
                finalHead: finalHead
            )
            await MainActor.run {
                if repositoryPath.isEmpty || repositoryPath == currentRepositoryPath {
                    self.entries = st
                }
                self.rebasePaused = outcome.paused
                self.rebasePauseReason = outcome.pauseReason
                self.rebaseConflicts = outcome.conflicts
                self.rebaseFeedback = outcome.paused
                    ? "Rebase 继续后再次暂停"
                    : "Rebase 完成"
                if !outcome.paused {
                    self.showMergeRevisionsDialog = false
                    self.rebaseUndoSeed = nil
                    self.rebaseUndoTarget = undoTarget
                    if let seed {
                        clearRebaseUndoSeed(repositoryPath: seed.repositoryPath)
                    }
                    if let undoTarget {
                        self.feedbackCenter.success(
                            "Rebase continued",
                            detail: String(outcome.headId.prefix(7)),
                            additionalActions: [self.rebaseUndoFeedbackAction(for: undoTarget)],
                            notificationID: rebaseUndoNotificationID(repositoryPath: undoTarget.repositoryPath),
                            notificationGroup: .standard
                        )
                    } else {
                        self.feedbackCenter.success(
                            "Rebase continued",
                            detail: String(outcome.headId.prefix(7))
                        )
                    }
                } else if outcome.pauseReason == .conflict {
                    self.rebaseUndoSeed = seed
                    self.rebaseUndoTarget = nil
                    if let seed {
                        saveRebaseUndoSeed(seed)
                    }
                    self.showMergeRevisionsDialog = true
                } else {
                    self.rebaseUndoSeed = seed
                    self.rebaseUndoTarget = nil
                    if let seed {
                        saveRebaseUndoSeed(seed)
                    }
                }
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch {
            await MainActor.run {
                self.feedbackCenter.error(
                    "Stage-and-Retry failed",
                    detail: errorMessage(error),
                    nextStep: "Review tracked and conflicted files, then continue or abort the rebase."
                )
            }
        }
    }
}

func doRebaseAbort() {
    guard let repo else { return }
    let repositoryPath = rebaseUndoSeed?.repositoryPath ?? repo.workdir() ?? ""
    beginFeedbackOperation("Abort rebase")
    Task.detached(priority: .userInitiated) {
        do {
            try repo.rebaseAbort()
            let st = try repo.status()
            await MainActor.run {
                self.entries = st
                self.rebasePaused = false
                self.rebasePauseReason = nil
                self.rebaseConflicts = []
                self.rebaseUndoSeed = nil
                self.rebaseUndoTarget = nil
                clearRebaseUndoSeed(repositoryPath: repositoryPath)
                self.rebaseFeedback = "已中止变基"
                self.refreshAll(showFeedback: false)
                self.loadRepoData()
            }
        } catch { await MainActor.run { self.rebaseFeedback = "\(error)" } }
    }
}

nonisolated func errorMessage(_ error: Error) -> String {
    if let e = error as? EngineError {
        switch e {
        case .NotARepository(let p): return "不是 git 仓库：\(p)"
        case .GitOperation(let m): return m
        case .NoUpstream(let branch):
            return "分支 \(branch) 没有配置 upstream。请先设置远程跟踪分支，再重试 pull。"
        case .TrackingMissing(let branch, let upstream):
            return "分支 \(branch) 的远程跟踪分支 \(upstream) 不存在。请先 Fetch，或重新配置 upstream。"
        case .UntrackedWouldBeOverwritten(let paths):
            return "远程更新与本地文件路径重叠：\(paths.joined(separator: ", "))。这些文件不会被 Add 或 Commit，Arbor 会先临时保存它们并重试 pull。"
        case .LocalChangesWouldBeOverwritten(let paths):
            return "本地变更会被覆盖：\(paths.joined(separator: ", "))。请先临时保存本地变更，再重试该 Git 操作。"
        case .StashApplyConflict(let paths, _):
            return "恢复本地变更时发生冲突：\(paths.joined(separator: ", "))。请在 Merge Revisions 中解决后完成操作。"
        case .ShelveApplyConflict(let name, let paths):
            return "Shelf \(name) 应用时发生冲突：\(paths.joined(separator: ", "))。请在 Merge Revisions 中解决后完成操作。"
        case .PushRejected(let kind, let remote, let branch, let message):
            switch kind {
            case .nonFastForward:
                return "Push 被拒绝：\(remote)/\(branch) 有远程更新。请先用 Merge 或 Rebase 更新，再重试 Push。\n\(message)"
            case .noUpstream:
                return "Push 目标没有 upstream：\(remote)/\(branch)。请选择 Publish Branch / set upstream 后重试。\n\(message)"
            case .authentication:
                return "Push 认证失败：\(message)"
            case .permission:
                return "Push 权限不足：\(message)"
            case .staleInfo:
                return "Push 被 force-with-lease 拒绝：远程分支已发生变化。请确认远程历史后选择 Force Push Anyway，或先 Fetch 再重试。\n\(message)"
            case .other:
                return message
            }
        case .Cancelled:
            return "操作已取消"
        }
    }
    return "\(error)"
}

nonisolated func friendlyRemoteError(_ error: Error) -> String {
    let full = errorMessage(error)
    let raw = full.count > 4000 ? String(full.prefix(4000)) + "\n…" : full
    let lower = raw.lowercased()
    if lower.contains("ssh host key changed")
        || lower.contains("remote host identification has changed")
    {
        return raw + "\nSSH 安全阻断：远端 host key 已变化。请先确认服务器身份，在 Git SSH Settings 检查 Known Hosts 后再重试。"
    }
    if lower.contains("authentication failed")
        || lower.contains("invalid username or token")
        || lower.contains("invalid credentials")
        || lower.contains("could not read username")
        || lower.contains("permission denied (publickey)")
        || lower.contains("publickey") {
        return raw + "\n认证失败：请检查 SSH key，或配置 git credential.helper。"
    }
    return raw
}

func treeChangeKindText(_ kind: TreeChangeKind) -> String {
    switch kind {
    case .added: return "新增"
    case .modified: return "修改"
    case .deleted: return "删除"
    case .renamed: return "重命名"
    }
}

}
